add{ q = { "where is the bank", "bank location", "where do i find a banker", "bank coords all cities", "where is the bank in stormwind", "wheres the bank", "wher is the banker", "how do i get to the bank", "bank coordinates", "cant find the bank in my city", "what are the bank coords in ironforge and org", "where can i store my stuff in town", "bank loc", "just got to sw where do i put my stuff" }, a = "Forever bank coordinates: Stormwind 62.4, 77.0 (Trade District); Ironforge 33.7, 62.9 (The Commons); Darnassus 39.8, 42.6; Orgrimmar 49.5, 69.8; Thunder Bluff 47.2, 58.5; Undercity 66.0, 46.0 (center ring); Dalaran 23.2, 64.8 and 10.7, 68.1; Valanaar (Zephras Isle) 57.5, 77.0. Neutral banks: Booty Bay 26.6, 76.5, Gadgetzan 52.4, 28.7, Ratchet 62.6, 37.4, Everlook 61.5, 37.1, Powderfuse Port (Riverglades) 76.9, 54.5. Every bank opens the same storage.", topic = "basics" }
add{ q = { "how big is the bank", "bank slots forever", "buy bank bag slot", "bank bag slot cost", "how many bank slots", "how many slots does the bank have", "bank space", "how much does a bank bag slot cost", "can i get more bank slots", "bank full how do i expand it", "price of next bank slot", "my bank is full need more room what does it cost", "bank size forever", "is it worth buying more bank bag slots or nah" }, a = "Your bank starts with 48 slots and 8 bank bag slots you can unlock. The first bag slot costs 10 silver and each one after costs more. Bank contents are shared between every bank in the world, so you can deposit in Orgrimmar and withdraw in Booty Bay.", topic = "basics" }
add{ q = { "how many bag slots", "backpack only 16 slots", "unlock 4 backpack slots", "authenticator bag slots", "reagent bag slot what is it", "backpack slots", "why is my backpack only 16", "how do i get 20 slot backpack", "does authenticator give more bag space", "what goes in the reagent bag slot", "how many bags can i equip", "extra 4 slots backpack authenticator", "how do i get the extra 4 backpack slots" }, a = "Your backpack has 16 slots, plus 4 more that unlock when you attach the Battle.net Authenticator (20 total). You can equip 4 extra bags, plus a separate reagent bag slot on the far left that only takes reagent bags (Linen 6, Woolen 8, Silk 10, Mageweave 12, Runecloth 14, Mooncloth 18, Bottomless 20). Soul bags also fit there. Keys go to the automatic keyring.", topic = "basics" }
add{ q = { "b only opens backpack", "open all bags key", "shift b bags", "how to open all bags at once", "combine bags option", "b key only opens one bag", "how to open all bags", "make b open all bags", "open every bag at once keybind", "my bags dont all open when i press b", "one big bag option", "how do i combine bags into one", "is there a setting so b opens all my bags not just the backpack" }, a = "By default B opens only the backpack and Shift+B opens every bag. To make B open all bags, go to Options > Keybindings > Interface Panel and bind Open All Bags to B. You can also merge all bags into one window with Combine Bags (Options > Controls/Presets).", topic = "basics" }
add{ q = { "where is the auction house stormwind", "stormwind ah", "sw ah location", "stormwind bank and ah", "where is the inn in stormwind", "where is sw ah", "stormwind auction house", "ah in stormwind where", "where is the inn stormwind", "stormwind bank location", "just got to stormwind where is everything ah bank inn", "trade district services", "im new in stormwind where do i find the auction house" }, a = "Stormwind's Trade District holds most services: the Auction House is in the middle of the district, the bank (Counting House) is in its southwest corner at about 62.4, 77.0, and a mailbox sits between the bank and the Gilded Rose inn. The gryphon master is up on the city wall on the east side of the Trade District (Dungar Longdrink, about 66.3, 62.1). A guard will mark any of these on your map.", src = "classic", topic = "basics" }
add{ q = { "ironforge ah", "where is the auction house ironforge", "ironforge inn", "ironforge flight master", "if gryphon master", "where is the ah in if", "ironforge bank", "where is the inn in ironforge", "ironforge flight path", "where is gryphon in ironforge", "first time in ironforge wheres the ah and bank", "if bank and ah", "just ran into ironforge from dun morogh where is the bank" }, a = "Ironforge: the bank (33.7, 62.9) and Auction House are both in The Commons, the ring just inside the main gate. The inn (Stonefire Tavern, Innkeeper Firebrew, about 18.1, 51.4) is also off The Commons. The gryphon master, Gryth Thurden, is by The Great Forge in the middle of the city (about 55.5, 47.7). The Deeprun Tram to Stormwind leaves from Tinker Town.", src = "classic", topic = "basics" }
add{ q = { "darnassus ah", "darnassus auction house", "darnassus bank", "darnassus inn", "darnassus flight master", "where is the ah in darnassus", "darn ah", "darn bank", "darnassus innkeeper", "darnassus hippogryph master", "where do i fly from in darnassus", "cant find the auction house in darnassus", "playing a night elf where is the ah in darn" }, a = "Darnassus: Auction House is in the open pavilion on Tradesmen's Terrace in the south, around 56, 52. The bank is in a tree on the island between the Temple Gardens and the Cenarion Enclave (39.8, 42.6). The inn is on Craftsmen's Terrace (Innkeeper Saelienne, about 67.4, 15.7). There is no flight master in the city: take the pink portal at the entrance down to Rut'theran Village, where the hippogryph master and the boat to Auberdine are.", src = "classic", topic = "basics" }
add{ q = { "orgrimmar ah", "org auction house", "org bank", "orgrimmar inn", "org flight master", "where is the zeppelin org", "where is the ah in org", "orgrimmar bank", "org inn", "where is the zeppelin tower orgrimmar", "orgrimmar flight path wind rider", "where is everything in orgrimmar ah bank inn", "og ah", "first time in org cant find the bank or ah lol" }, a = "Orgrimmar: the bank (49.5, 69.8) and Auction House are in the Valley of Strength just inside the front gate. Innkeeper Gryshka runs the inn there (about 54.1, 68.4). The wind rider master, Doras, stands on top of the tall tower near the Valley of Strength (about 45.1, 63.9). Zeppelins to Undercity and Grom'gol leave from the towers just outside the main gate in Durotar.", src = "classic", topic = "basics" }
add{ q = { "thunder bluff ah", "tb auction house", "tb bank", "thunder bluff inn", "tb flight master", "how do i get up thunder bluff", "where is the ah in thunder bluff", "thunder bluff bank", "tb inn", "thunder bluff wind rider", "how to get up to tb", "thunder bluff elevator", "where is everything in tb", "just finished mulgore how do i get into thunder bluff and find the ah" }, a = "Thunder Bluff: ride the elevators up from Mulgore. The bank (47.2, 58.5), Auction House and inn (Innkeeper Pala, about 45.8, 64.6) are on the Lower Rise, the first big mesa. The wind rider master, Tal, is on the tower in the middle of the central rise (about 47.0, 49.8). Rope bridges link the Lower Rise to Spirit Rise, Elder Rise and Hunter's Rise.", src = "classic", topic = "basics" }
add{ q = { "undercity ah", "uc auction house", "uc bank", "undercity inn", "uc flight master", "how do i get into undercity", "where is the ah in undercity", "undercity bank", "uc inn", "undercity bat handler", "how to get to undercity entrance", "wheres the elevator into uc", "uc services where", "undead noob where is the bank in uc" }, a = "Undercity: enter through the ruined throne room of Lordaeron in Tirisfal and ride an elevator down. The bank (66.0, 46.0) sits in the center ring surrounded by green slime. The Auction House, inn (Innkeeper Norman, about 67.7, 37.9) and bat handler (Michael Garrett, about 63.3, 48.6) are all in the Trade Quarter ring. The zeppelin tower to Orgrimmar and Grom'gol is outside in Tirisfal near Brill.", src = "classic", topic = "basics" }
add{ q = { "dalaran bank", "dalaran services", "does dalaran have a bank", "what is in dalaran city", "dalaran trainers", "what does dalaran have", "is there a bank in dalaran", "dalaran flight master", "dalaran inn", "what services are in dalaran forever", "is dalaran a city in forever", "dal bank", "what can i do in dalaran is there a bank and inn" }, a = "Dalaran (Alterac Mountains) is an Alliance hub in Forever. It has two banks (23.2, 64.8 and 10.7, 68.1), a flight master, a stable master (Talia Softglen, 19.7, 70.1), a barber, new Mage (Jessa Weaver, 17.7, 69.5) and Druid (Alfina Nightgaze, Sky Enclave 11.7, 56.7) trainers, and Expert-rank profession trainers. A portal takes you to Stormwind. Horde players are attacked by the guards and teleported out.", topic = "basics" }
add{ q = { "dalaran profession trainers", "dalaran alchemy trainer", "dalaran blacksmith trainer", "dalaran enchanting trainer", "dalaran tailoring trainer", "where are trainers in dalaran", "dalaran herbalism trainer", "dalaran mining trainer", "dalaran engineering trainer", "dalaran leatherworking trainer", "expert trainer dalaran", "dal proffesion trainers", "i want to train alchemy in dalaran where is the trainer" }, a = "Dalaran trainers: Alchemy (Expert) Linzy Blackbolt or Patricia Egan 18.7, 62.4; Blacksmithing (Expert) Alard Schmied 19.7, 63.2; Enchanting (Expert) Vanessa Sellers 16.8, 62.4; Tailoring (Expert) Charles Worth 17.9, 60.7; Herbalism Edward Egan 18.4, 63.4; Cooking Katherine Lee 12.5, 65.7; First Aid Angelique Butler 17.1, 61.0.", topic = "basics" }
add{ q = { "valanaar bank", "valanaar auction house", "zephras isle ah", "skyborne bank", "where is the bank on zephras isle", "where is the ah on zephras", "valanaar ah", "zephras isle bank", "skyborne auction house", "bank in valanaar", "where do skyborne bank", "is there an ah in valanaar", "skyborne here where do i find a bank on zephras isle" }, a = "In Valanaar, the town at the south end of Zephras Isle, the bank and Auction House share one building at the back of town (bank about 57.5, 77.0). Walk in through the main arch, follow the paved path past the craft shops, and go up the ramp into the building signed Bank and Auction House. The auctioneer is Zelena Favorbreeze.", topic = "basics" }
add{ q = { "valanaar trainers", "zephras isle profession trainers", "skyborne profession trainer", "valanaar herbalism trainer", "valanaar mining trainer", "zephras trainers", "valanaar alchemy trainer", "valanaar blacksmith trainer", "skyborne herbalism trainer", "where do skyborne learn professions", "valanaar tailoring trainer", "zephras isle skinning trainer", "skyborne player where do i train herb and mining" }, a = "Valanaar trainers: Alchemy Valiena Swiftgale 59.3, 76.2 or Iaadaria Bitterwind 66.3, 79.5; Blacksmithing Daeann Steelwind 65.4, 80.0; Enchanting Eaysaa Brightgust 59.2, 76.3; Leatherworking Emerii Tallgust 63.8, 80.7; Tailoring Othesia Evengale 64.4, 81.1; Herbalism Syriel Nightrain 57.9, 75.5; Mining Halavuul Cragwind 65.4, 80.4; Skinning Ishlee Breezewhisper 59.6, 75.9; Cooking Nyalah Brightfire 60.6, 72.7; Fishing Baelann Swiftcurrent 63.2, 75.7; First Aid Melasa Fairmend 63.1, 72.6.", topic = "basics" }
add{ q = { "skyborne riding trainer", "galestrider mount", "where do skyborne learn riding", "genn fairweather", "skyborne mount", "where do skyborne get a mount", "galestrider vendor", "skyborne riding", "how do i get galestrider", "zephras riding trainer", "skyborne level 40 mount", "hit 40 on my skyborne where do i get my mount" }, a = "Skyborne of both factions learn riding and buy their Galestrider mount from Genn Fairweather on Zephras Isle at 53.8, 81.3. Training is at level 40 like everyone else.", topic = "basics" }
add{ q = { "how do i find anything in a city", "where is x in city", "ask guard directions", "city guard map marker", "lost in stormwind", "how to find stuff in city", "ask a guard for directions", "where is anything in town", "guard directions", "im lost in org", "how do i find the trainer in a capital", "city guards show on map", "im lost in the city how do i find stuff" }, a = "Talk to any city guard. They list services such as bank, auction house, inn, flight master, class and profession trainers, battlemasters and mailboxes, and put a flag on your map for the one you pick. You can also track mailboxes, trainers and more with the magnifying glass on the minimap.", topic = "basics" }
add{ q = { "where is the mailbox", "find mailbox", "track mailbox minimap", "mailbox near me", "mailbox location", "where is a mailbox", "how do i find a mailbox", "nearest mailbox", "track mailboxes", "cant find mailbox in town", "show mailbox on minimap", "where is the closest mailbox i need to send stuff to my alt" }, a = "Every capital and most towns have mailboxes, usually right by the inn and the bank. To find one fast, click the magnifying glass at the top right of the minimap and pick Mailbox so they show up as icons.", topic = "basics" }
add{ q = { "stormwind class trainers", "where is warrior trainer stormwind", "stormwind rogue trainer", "stormwind mage trainer", "stormwind warlock trainer", "stormwind paladin trainer", "sw class trainers", "warrior trainer stormwind", "rogue trainer sw", "mage trainer sw", "lock trainer stormwind", "pally trainer stormwind", "where is priest trainer stormwind", "stormwind hunter trainer", "just made a human warrior where is my trainer in sw" }, a = "Stormwind trainers: Warrior and Rogue in Old Town (warriors in the Command Center, e.g. Wu Shen 80.6, 59.5; rogues Osborne the Night Man 77.3, 65.3). Paladin and Priest in the Cathedral of Light (Lord Grayson Shadowbreaker 48.6, 50.0; High Priestess Laurena 49.6, 44.7). Mage in the Mage Quarter (Jennea Cannon 49.5, 86.0). Warlock in the Mage Quarter basement of the Slaughtered Lamb (Ursula Deline 39.9, 84.3). Hunter in the Dwarven District (Ulfir Ironbeard 67.6, 35.9). Druid in The Park (Theridran 36.0, 64.3).", topic = "basics" }
add{ q = { "ironforge class trainers", "ironforge warrior trainer", "ironforge shaman trainer", "dwarf shaman trainer", "ironforge paladin trainer", "ironforge hunter trainer", "if class trainers", "warrior trainer ironforge", "shaman trainer ironforge", "pally trainer ironforge", "hunter trainer if", "ironforge rogue trainer", "where do dwarves train", "dwarf hunter where do i train in ironforge" }, a = "Ironforge trainers: Warrior and Hunter in the Hall of Arms, Military Ward (Kelv Sternhammer 71.2, 91.6; Olmin Burningbeard 70.6, 83.8). Paladin, Priest and Mage in the Mystic Ward (Brandur Ironhammer 24.2, 6.8; High Priest Rohan 25.6, 9.0; Juli Stormkettle 26.2, 7.6). Rogue and Warlock in the Forlorn Cavern (Fenthwick 52.0, 13.6; Alexander Calder 50.8, 6.4). New Alliance Shaman trainer: Eldrun Stormbreaker, Forlorn Cavern 47.3, 13.5. No druid trainer.", topic = "basics" }
add{ q = { "darnassus class trainers", "night elf druid trainer", "darnassus warrior trainer", "darnassus hunter trainer", "darnassus priest trainer", "darn class trainers", "druid trainer darnassus", "warrior trainer darnassus", "hunter trainer darn", "priest trainer darnassus", "night elf rogue trainer", "where do night elves train", "where is my druid trainer in darnassus" }, a = "Darnassus trainers: Druid in the Cenarion Enclave (Mathrengyl Bearwalker 35.2, 8.3). Hunter also in the Cenarion Enclave (Jeen'ra Nightrunner 39.6, 5.8; pet trainer Silvaria 42.2, 8.8). Rogue in the Cenarion Enclave (Syurna 36.8, 21.8). Priest in the Temple of the Moon (Astarii Starseeker 38.9, 81.4). Warrior on the Warrior's Terrace (Arias'ta Bladesinger 58.4, 34.9). No mage or warlock trainer in Darnassus.", topic = "basics" }
add{ q = { "orgrimmar class trainers", "org warrior trainer", "org shaman trainer", "org rogue trainer", "org warlock trainer", "org hunter trainer", "org class trainers", "warrior trainer orgrimmar", "shaman trainer org", "rogue trainer orgrimmar", "lock trainer org", "hunter trainer orgrimmar", "orc mage trainer", "where do orcs train", "orc warrior lvl 10 where is my trainer in org" }, a = "Orgrimmar trainers: Warrior and Hunter in the Valley of Honor (Grezz Ragefist 79.6, 31.6; Ormak Grimshot 66.2, 18.5). Shaman in the Valley of Wisdom (Kardris Dreamseeker 39.0, 36.7). Rogue and Warlock in the Cleft of Shadow (Shenthul 43.0, 53.6; Zevrost 48.3, 46.4). Mage and Priest in the Valley of Spirits (Deino 38.6, 86.0; Ur'kyo 35.7, 87.5). No druid or paladin trainer.", topic = "basics" }
