add{ q = { "orgrimmar profession trainers", "org blacksmith trainer", "org engineering trainer", "org alchemy trainer", "org herbalism trainer", "org profession trainers", "blacksmith trainer orgrimmar", "engineering trainer org", "alchemy trainer org", "herbalism trainer orgrimmar", "mining trainer org", "where to learn engi in org", "where do i learn bs in org" }, a = "Orgrimmar: Blacksmithing Saru Steelfury (Valley of Honor 82.4, 23.5); Engineering Roxxik (76.0, 25.0); Mining Makaru (73.0, 27.0); Fishing Lumak (69.7, 29.3). In The Drag: Alchemy Yelmak (56.4, 33.8); Herbalism Jandi (55.6, 40.0); Enchanting Godan (53.6, 38.3); Leatherworking Karolek (62.6, 44.8); Skinning Thuwd (63.1, 45.3); Tailoring Magar (63.7, 50.0); Cooking Zamja (57.4, 53.8). First Aid Arnok (Valley of Spirits 34.0, 84.3).", topic = "basics" }
add{ q = { "thunder bluff profession trainers", "tb leatherworking trainer", "tb skinning trainer", "tb alchemy trainer", "tb profession trainers", "leatherworking trainer thunder bluff", "skinning trainer tb", "alchemy trainer thunder bluff", "herbalism trainer tb", "enchanting trainer thunder bluff", "where to learn lw in tb", "where do i train skinning in thunder bluff" }, a = "Thunder Bluff (Middle Rise): Alchemy Bena Winterhoof 46.6, 33.2; Herbalism Komin Winterhoof 49.7, 39.6; Enchanting Teg Dawnstrider 45.2, 38.5; Leatherworking Una 41.7, 42.7; Skinning Mooranta 44.7, 43.3; Tailoring Tepa 43.9, 44.8; Blacksmithing Karn Stonehoof 39.7, 55.5; Mining Brek Stonehoof 34.5, 57.5; Cooking Aska Mistrunner 51.0, 52.3; Fishing Kah Mistrunner 56.4, 47.6. First Aid Pand Stonebinder (Spirit Rise 29.2, 21.7). No engineering trainer.", topic = "basics" }
add{ q = { "undercity profession trainers", "uc alchemy trainer", "uc tailoring trainer", "uc engineering trainer", "uc profession trainers", "alchemy trainer undercity", "tailoring trainer uc", "engineering trainer undercity", "herbalism trainer uc", "enchanting trainer undercity", "where to learn alch in uc", "where do i learn tailoring in undercity" }, a = "Undercity: Alchemy Doctor Herbert Halsey (Apothecarium 48.3, 72.3); Herbalism Martha Alliestar (54.8, 50.1); Enchanting Lavinia Crowe (62.5, 61.3); Tailoring Josef Gregorian (Magic Quarter 70.8, 30.6); Fishing Armand Cromwell (81.0, 29.5); Blacksmithing James Van Brunt (War Quarter 61.6, 30.2); Mining Brom Killian (55.9, 36.0); Engineering Franklin Lloyd (Rogues' Quarter 76.5, 75.0); Leatherworking Arthur Moore (70.6, 58.5); Skinning Killian Hagey (71.0, 59.5); First Aid Mary Edras (73.5, 55.5); Cooking Eunice Burch (Trade Quarter 62.6, 44.8).", topic = "basics" }
add{ q = { "where is the weapon master", "weapon trainer location", "where do i learn swords", "where to learn polearms", "weapon skill trainer", "weapon master location", "where do i learn weapons", "weapon trainer", "where to train swords", "where can i learn polearms", "who teaches staves", "weapon master stormwind", "want to learn swords on my warrior where do i go" }, a = "Stormwind - Woo Ping, Trade District 63.8, 69.0 (swords, polearms, staves, daggers, crossbows). Ironforge - Buliwyf Stonehand / Bixi Wobblebonk, Military Ward 62.2, 89.6 (axes, maces, fist, guns / crossbows, daggers, thrown). Darnassus - Ilyenia Moonfire, Warrior's Terrace 57.6, 46.7 (bows, daggers, fist, staves, thrown). Orgrimmar - Sayoc / Hanashi, Valley of Honor 81.5, 19.6 (axes, bows, daggers, fist, staves, thrown). Thunder Bluff - Ansekhwa 40.9, 62.7 (guns, maces, staves). Undercity - Archibald, War Quarter 57.3, 32.8 (swords, polearms, daggers, crossbows).", topic = "basics" }
add{ q = { "weapon skill cost", "how much to learn a weapon", "polearm level requirement", "why cant i learn polearms", "how much does a weapon skill cost", "cost to learn a weapon", "polearm level", "why cant i train polearms", "what level for polearms", "weapon trainer prices", "how much to learn axes", "how much do weapon skills cost at the trainer" }, a = "Most weapon skills cost 10 silver and can be learned at level 1. Polearms need level 20 and cost 1 gold. Trainers only show weapons your class can use.", topic = "basics" }
add{ q = { "where to learn fist weapons alliance", "fist weapon trainer", "stormwind fist weapons", "horde fist weapon trainer", "fist weapon trainer alliance", "where to learn fist weapons", "who teaches fist weapons", "fist weapons horde", "why cant i learn fist weapons in stormwind", "fist weapon skill where", "alliance rogue wants fist weapons who teaches them" }, a = "Woo Ping in Stormwind does not teach fist weapons. Alliance learn them from Ilyenia Moonfire in Darnassus (57.6, 46.7) or Buliwyf Stonehand in Ironforge (62.2, 89.6), 10 silver, no level requirement. Horde learn them from Sayoc in Orgrimmar's Valley of Honor (81.5, 19.6).", topic = "basics" }
add{ q = { "where to learn 2h swords horde", "horde sword trainer", "undercity weapon master", "horde polearm trainer", "horde 2h sword trainer", "where do horde learn swords", "undercity weapon trainer", "where do horde learn polearms", "orgrimmar doesnt teach swords", "uc weapon master", "orc warrior where do i learn 2h swords" }, a = "Horde swords and polearms come from Archibald in the Undercity War Quarter (57.3, 32.8). Orgrimmar and Thunder Bluff don't teach swords, so Orc and Tauren players need the zeppelin to Undercity.", topic = "basics" }
add{ q = { "riding trainer locations", "where do i learn to ride", "mount vendor location", "where buy mount", "riding trainer location", "where to learn riding", "where to buy a mount", "mount vendor", "where is my race mount vendor", "where do i get my first mount", "riding trainer for my race", "just hit 40 where do i go to learn riding" }, a = "Riding trainer / mount vendor by race: Human Randal Hunter & Katie Hunter, Eastvale Logging Camp, Elwynn (84.3, 64.9). Dwarf Ultham Ironhorn & Veron Amberstill, Amberstill Ranch, Dun Morogh (63.7, 50.1). Gnome Binjy & Milli Featherwhistle, Dun Morogh (49.2, 48.1). Night Elf Jartsam & Lelanai, Darnassus (38.1, 16.1). Orc Kildar & Ogunaro Wolfrunner, Orgrimmar (69.4, 13.1). Troll Xar'Ti & Zjolnir, Durotar (55.3, 75.5). Tauren Kar Stormsinger, Mulgore (46.8, 61.9) & Harb Clawhoof (47.5, 58.6). Undead Velma Warnam & Zachariah Post, Brill (60.2, 52.4).", topic = "basics" }
add{ q = { "how much is riding", "mount cost level 40", "epic mount cost", "journeyman riding cost", "riding cost", "how much is a mount", "how much gold for mount at 40", "epic mount price", "how much is journeyman riding", "how much gold do i need for 40 mount", "mount cost", "how much gold do i need for my first mount" }, a = "Apprentice Riding at level 40 costs 100 gold, plus about 20 gold for a 60% mount. Journeyman Riding at 60 costs 1,000 gold, plus about 200 gold for a 100% epic mount. Honored with your home city takes 10% off both. Paladins and Warlocks get their mounts through class quests instead.", topic = "basics" }
add{ q = { "where are the battlemasters", "how to queue warsong gulch", "how do i queue for bg", "battleground queue npc", "where do i queue pvp", "where to queue bg", "battlemaster location", "how do i queue wsg", "how to join battleground", "queue pvp", "where is the battlemaster", "bg queue", "want to do warsong gulch how do i queue" }, a = "Every capital (Stormwind, Ironforge, Darnassus, Orgrimmar, Thunder Bluff, Undercity) has battlemasters; ask a guard for Battlemaster to get a map flag. You can also queue at the Warsong Gulch entrance in Ashenvale (Alliance) or the Barrens (Horde). Once queued, keep questing until it pops. Warsong Gulch opens at level 10 and is 10 vs 10.", topic = "basics" }
add{ q = { "battlemaster locations classic", "stormwind battlemaster", "orgrimmar battlemaster", "where are battlemasters in org", "battlemaster stormwind", "battlemaster org", "where are battlemasters in stormwind", "battlemaster ironforge", "battlemaster undercity", "battlemaster thunder bluff", "where are bm npcs", "where are the battlemasters in orgrimmar" }, a = "Classic battlemaster spots: Stormwind in the War Room of Stormwind Keep; Ironforge in the Hall of Arms (Military Ward); Darnassus on the Warrior's Terrace; Orgrimmar in the Hall of the Brave (Valley of Honor); Thunder Bluff on Hunter's Rise; Undercity in the Royal Quarter. Not yet confirmed for Forever, so ask a guard if they aren't there.", src = "classic", topic = "basics" }
add{ q = { "bg level brackets", "warsong gulch brackets", "when can i do battlegrounds", "pvp level 10", "bg brackets", "wsg brackets", "what level can i do bgs", "battleground level ranges", "when can i pvp", "what level for warsong", "darkspear islands level", "im level 15 can i do battlegrounds yet" }, a = "Warsong Gulch brackets: 10-19, 20-29, 30-39, 40-49, 50-59 and 60. The new Darkspear Islands battleground is 15 vs 15 for level 30-60. Normal and PvP ruleset characters share battleground queues.", topic = "basics" }
add{ q = { "pvp rank forever", "honor changes forever", "how does rank work forever", "marks of honor cap", "pvp ranks", "how does honor work forever", "rank system forever", "how to rank up pvp", "is there a rank grind", "marks of honor limit", "weekly honor cap", "how does the pvp rank system work in forever" }, a = "Forever changed the honor system: each match fills a personal rank bar with a weekly cap, instead of you competing against the whole faction. Warsong Gulch, Arathi Basin and Darkspear Islands give more honor than in Classic, AV a little less. Holiday weeks give bonus honor, and Marks of Honor stack to 30.", topic = "basics" }
add{ q = { "where do i repair", "repair gear", "how to repair armor", "repair vendor", "anvil icon vendor", "where to repair", "repair armor", "repair vendor near me", "how do i fix my gear", "who repairs gear", "repair npc", "how to repair items", "my gear is broken where can i repair it" }, a = "Any vendor whose name shows an anvil icon when you hover over them can repair (armor, weapon, blacksmith and general merchants usually can). Open their window and click the anvil button, then a red item, or Repair All. Engineers can also place a Repair Bot at a camp from skill 140.", topic = "basics" }
add{ q = { "my gear is red", "item turned red", "durability 0", "why does my armor not work", "broken gear", "gear is red", "my armor is red", "item red durability", "broken armor", "durability zero", "why is my gear red", "why did my gear turn red" }, a = "Red gear has 0 durability and gives no stats until repaired; yellow means it's low. Every death costs durability and resurrecting at a spirit healer costs more. Repair at any vendor with the anvil icon. The Legacy talent Reinforce cuts death durability loss by 8% per rank.", topic = "basics" }
add{ q = { "sold item by accident", "buyback vendor", "get back sold item", "how to undo sell", "sold wrong item", "how to buy back item", "undo sell", "accidentally sold my weapon", "buyback tab", "sold item to vendor by mistake", "i sold my weapon by mistake can i get it back" }, a = "Open the same vendor and click the Buyback tab. It holds the items you've sold recently, and you can buy them back for the price you got.", topic = "basics" }
add{ q = { "how to buy from vendor", "how to sell items", "what should i sell", "grey items worth", "what are gray items for", "how do i buy things", "how to sell stuff", "selling items to vendor", "what should i vendor", "are gray items worth anything", "vendor trash", "should i sell my gray items to a vendor" }, a = "Right-click a merchant to open the shop. Right-click an item in the shop to buy it, and right-click an item in your bags to sell. Gray (poor quality) items are only for vendor gold, so sell them all. Keep crafting materials in the bank or sell them on the Auction House.", topic = "basics" }
add{ q = { "what armor can i wear", "armor types by class", "can mage wear leather", "which classes wear plate", "cloth leather mail plate classes", "armor types", "what armor can i use", "what armor does my class wear", "can druids wear leather", "who wears mail", "plate classes", "what can priest wear", "can my mage wear leather armor" }, a = "Armor by class in Forever: Cloth - Mage, Priest, Warlock. Leather - Druid, Rogue. Mail - Hunter, Shaman. Plate - Warrior, Paladin. Every class can still wear lighter types (a warrior can wear leather), but you lose armor and usually get the wrong stats.", topic = "basics" }
add{ q = { "when can hunters wear mail", "hunter mail level 40", "hunter mail armor", "learn mail hunter", "hunter mail", "when do hunters get mail", "hunter mail 40", "can hunters wear mail", "learn mail hunter trainer", "when can my hunter use mail", "just dinged 40 on my hunter can i wear mail now" }, a = "Hunters wear cloth and leather until level 40, then learn Mail from their class trainer. Train it as soon as you ding 40, since most hunter upgrades after that are mail.", class = "HUNTER", topic = "basics" }
add{ q = { "when can shamans wear mail", "shaman mail level 40", "shaman mail armor", "shaman mail", "when do shamans get mail", "shaman mail 40", "can shamans wear mail", "learn mail shaman", "when can my shaman use mail", "just hit 40 on my shaman when can i wear mail" }, a = "Shamans wear cloth, leather and shields until level 40, then learn Mail from their class trainer (Classic baseline; Forever's class guides list shaman as a mail class, but no source has stated a changed level).", class = "SHAMAN", src = "classic", topic = "basics" }
add{ q = { "when can warriors wear plate", "warrior plate level 40", "learn plate warrior", "warrior plate armor", "warrior plate", "when do warriors get plate", "plate at 40 warrior", "can warriors wear plate", "learn plate warrior trainer", "when can my warrior wear plate", "just hit 40 on my warrior can i wear plate now" }, a = "Warriors learn Plate at level 40 from their class trainer. Until then they wear mail, which they can use from level 1.", class = "WARRIOR", topic = "basics" }
add{ q = { "when can paladins wear plate", "paladin plate 40", "learn plate paladin", "paladin mail armor", "pally plate", "when do paladins get plate", "plate at 40 paladin", "can paladins wear plate", "learn plate paladin trainer", "when can my pally wear plate", "just dinged 40 on my pally can i use plate armor" }, a = "Paladins learn Plate at level 40 from their class trainer. Before that they wear mail, which they can use from level 1. Remember to visit the trainer at 40, it isn't automatic.", class = "PALADIN", src = "classic", topic = "basics" }
add{ q = { "can rogues use axes", "rogue axes forever", "druid polearms forever", "new weapon proficiencies forever", "rogue axes", "can rogues use axes in forever", "can druids use polearms", "druid polearm", "new weapon skills in forever", "rogues get axes", "can my rogue use one handed axes in forever" }, a = "Yes. Forever lets Rogues use one-handed axes and Druids learn polearms, neither of which was possible in Classic. Druids also get a Feral Combat weapon skill from level 1 that levels once you have Bear Form at 10. Defense and Unarmed are default skills for everyone.", topic = "basics" }
add{ q = { "what weapons can my class use", "weapon proficiency list", "can warlock use swords", "can priest use maces", "which classes use bows", "weapon types for my class", "what weapons can i use", "can warlocks use swords", "can priests use maces", "who can use bows", "which classes can use guns", "class weapon list", "can a warlock use a sword" }, a = "Forever weapon skills: Bows, Crossbows, Guns, Thrown - Hunter, Rogue, Warrior. Daggers - all but Paladin. Fist - Druid, Hunter, Rogue, Shaman, Warrior. 1H Axe - Hunter, Paladin, Rogue, Shaman, Warrior. 1H Mace - Druid, Paladin, Priest, Rogue, Shaman, Warrior. 1H Sword - Hunter, Mage, Paladin, Rogue, Warlock, Warrior. Polearm - Druid, Hunter, Paladin, Warrior. Staff - all but Paladin and Rogue. 2H Axe - Hunter, Paladin, Shaman, Warrior. 2H Mace - Druid, Paladin, Shaman, Warrior. 2H Sword - Hunter, Paladin, Warrior. Wands - Mage, Priest, Warlock.", topic = "basics" }
add{ q = { "why do i miss so much with new weapon", "weapon skill 1/300", "new weapon keeps missing", "how to level weapon skill fast", "missing a lot with new weapon", "new weapon misses", "weapon skill leveling", "how to level weapon skill", "weapon skill 1", "why do i miss with my new sword", "just learned axes and i keep missing everything" }, a = "A newly learned weapon starts at skill 1, so you miss and glance a lot. Weapon skill rises as you hit things with that weapon type, up to 5 x your level (300 at 60). Level it on easy mobs a few levels below you. In Forever each missing point costs about 0.04% hit and crit, and low skill causes many more glancing blows.", topic = "basics" }
add{ q = { "weapon skill items forever", "edgemaster's handguards forever", "does weapon skill matter forever", "racial weapon skill forever", "human sword specialization forever", "is weapon skill important", "edgemaster's forever", "racial weapon skill", "human sword spec", "do racials give weapon skill", "weapon skill gear forever", "does weapon skill still matter in forever" }, a = "Weapon skill still exists, but Blizzard shrank it: no racial gives weapon skill anymore (Human, Orc and Dwarf weapon racials now give crit chance or crit damage instead), and +weapon skill gear was cut hard. Edgemaster's Handguards give +1 instead of +7. Just keep your skill maxed by using the weapon.", topic = "basics" }
add{ q = { "how to dual wield", "when can i dual wield", "dual wield level", "which classes can dual wield", "learn dual wield", "dual wield", "when do warriors dual wield", "what level dual wield", "who can dual wield", "learn dual wield trainer", "can hunters dual wield", "at what level can my warrior dual wield" }, a = "Warriors learn Dual Wield from their class trainer at level 20. Rogues can dual wield from level 1 and Hunters learn it at 20 (Classic baseline). Shamans cannot dual wield in Forever (Enhancement is built around two-handers), and casters can't either. Off-hand swings miss far more often unless you stack hit.", topic = "basics" }
add{ q = { "can shaman dual wield forever", "enhancement dual wield", "shaman two weapons", "shaman off hand weapon", "can shamans dual wield", "enh shaman dual wield", "shaman dual wield forever", "shaman two weapons forever", "enhancement shaman off hand", "dual wield shaman", "is there any way for shaman to dual wield in forever" }, a = "No. Shamans cannot dual wield in Forever, there is no talent, trainer or Legacy unlock for it, and Blizzard designed Enhancement around two-handed weapons. Two-handed axes and maces are learned from weapon masters instead of a talent. Use a 2H or a 1H plus shield/off-hand.", class = "SHAMAN", topic = "basics" }
add{ q = { "where to buy arrows", "where to buy bullets", "ammo vendor", "out of arrows", "how to get ammo", "where can i buy arrows", "where can i get bullets", "ammo vendor location", "ran out of arrows", "who sells ammo", "where do hunters buy arrows", "im out of ammo on my hunter where do i buy more", "arrow vendor", "wher do i get arrows" }, a = "General Goods vendors in every town and city sell basic arrows and bullets, and weapon/gun vendors in bigger towns carry higher tiers. Buy a stack, then drag it into your ammo slot or quiver. Restock every time you're in town, since running dry mid-dungeon kills your damage. Engineers can craft bullets.", class = "HUNTER", topic = "basics" }
add{ q = { "arrow tiers by level", "best arrows to buy", "which arrows level 40", "jagged arrow", "razor arrow level", "best arrows", "what arrows should i use", "arrow levels", "which ammo for level 40", "best vendor arrows", "what arrows at lvl 25", "arrows tiers", "what bullets should my hunter buy at 30", "just hit 40 on my hunter which arrows should i be using" }, a = "Vendor arrows (per 200): Rough Arrow L1 +1.5 dps, 10c. Sharp Arrow L10 +3.5, 50c. Razor Arrow L25 +7.5, 3s. Jagged Arrow L40 +13, 10s. Ice Threaded Arrow L51 +16.5, 48s, from Alterac Valley quartermasters at Honored. Thorium Headed Arrows (+17.5) come from turning in Thorium Shells.", class = "HUNTER", topic = "basics" }
add{ q = { "quiver vs ammo pouch", "does quiver give attack speed", "which bag for arrows", "quiver haste", "quiver or ammo pouch", "does a quiver increase attack speed", "what bag holds arrows", "do i need a quiver", "quiver speed bonus", "ammo pouch vs quiver hunter", "is the quiver haste worth a bag slot", "is it worth using a quiver or should i just use a bag" }, a = "Arrows go in a quiver and bullets in an ammo pouch; each takes one regular bag slot. Quivers and pouches add ranged attack speed (the Light Quiver gives 10%, endgame ones like Harpy Hide Quiver 15%), and the bonuses don't stack between bags. Leatherworkers craft quivers and pouches.", class = "HUNTER", src = "classic", topic = "basics" }
add{ q = { "auto shot not working", "auto shot wont fire while moving", "wand delay forever", "auto shot not firing", "auto shot wont work", "why does my auto shot not shoot", "wand not firing", "wand wont shoot while moving", "hunter auto shot delay", "my auto shot stops when i move", "why wont my auto shot fire when im running" }, a = "In Forever, Auto Shot and wands need you to stand still for 0.5 seconds before they fire, so stop moving briefly. Also check you're beyond 8 yards: hunters can't shoot inside that dead zone. Make sure you have ammo equipped.", topic = "basics" }
add{ q = { "how to equip items", "how to equip gear", "compare items tooltip", "which item is better", "how do i equip gear", "how to wear items", "how to put on armor", "how to compare gear", "which item is an upgrade", "how do i know if an item is better", "how do i equip a new weapon", "new player how do i put on the gear i just looted" }, a = "Right-click an item in your bags or drag it to the matching slot in the character panel (C). Hovering shows a tooltip with a comparison to what you have equipped, with green and red stat changes. Forever's Equipment Manager in the character panel can save whole gear sets.", topic = "basics" }
add{ q = { "what do item colors mean", "item quality colors", "gray white green blue purple items", "what is a blue item", "item colors", "what does green item mean", "what are purple items", "item rarity colors", "what is an epic item", "what does blue mean on an item", "loot colors meaning", "what do the different colors on items mean" }, a = "Item quality by color: gray (poor, vendor trash), white (common), green (uncommon), blue (rare), purple (epic), orange (legendary). Higher quality usually means better stats for its level.", src = "classic", topic = "basics" }
add{ q = { "bop vs boe", "bind on pickup meaning", "bind on equip meaning", "can i sell bop items", "what is bop", "what is boe", "bind on pickup", "bind on equip", "can i sell boe on ah", "soulbound meaning", "difference between bop and boe", "can i trade soulbound items", "got a boe drop can i sell it on the ah" }, a = "Bind on Pickup (BoP) items become soulbound when you loot them and can't be traded or sold on the AH. Bind on Equip (BoE) items can be traded or sold until someone equips them. Soulbound items can only be vendored or disenchanted.", src = "classic", topic = "basics" }
add{ q = { "hit cap forever", "what is the hit cap", "how much hit do i need", "melee hit cap", "spell hit cap", "hit cap", "whats the hit cap", "melee hit cap forever", "spell hit cap forever", "hit cap for raids", "how much hit for raid bosses", "what hit % do i need for raids in forever" }, a = "Forever hit caps (with maxed weapon skill): Melee and ranged special attacks 5% vs same level, 8% vs raid bosses. Spells 4% vs same level, 17% vs raid bosses. Dual-wield auto attacks need about 24% vs same level and roughly 27-29% vs bosses. In PvP the same-level caps apply. Hit is one stat that covers melee, ranged and spells.", topic = "basics" }
add{ q = { "is hit one stat forever", "spell hit and melee hit combined", "hit rating or percent", "how does hit work forever", "is hit combined in forever", "is spell hit the same as melee hit", "how does hit work", "hit percent or rating", "one hit stat", "does melee hit count for spells", "does melee hit and spell hit count as one stat in forever" }, a = "Forever merged melee, ranged and spell hit into one Hit Chance stat, and gear shows it as a flat percentage, not a rating. Most hit gear starts dropping around level 50. Crit is merged the same way.", topic = "basics" }
add{ q = { "talents that give hit", "hit talents by class", "which talent gives hit chance", "what talents give hit", "hit talents", "talents with hit chance", "which classes get hit from talents", "hit from talents", "does my class have a hit talent", "which talents give hit for my class" }, a = "Hit talents: Druid Nature's Reach 4%; Hunter Surefooted 3%; Mage Precision 6% spells; Paladin Precision 3% and Divine Precision 8% Holy; Priest Holy Precision 18% Holy, Shadow Focus 5% Shadow; Rogue Precision 3%; Shaman Tidal Focus 5%; Warlock Suppression 5%; Warrior Furious Precision up to 10% off-hand only. Dwarves get 1% from Artisan's Precision.", topic = "basics" }
add{ q = { "dual wield hit penalty", "off hand miss chance", "why does my offhand miss", "heroic strike off hand hit", "dual wield miss chance", "why does my offhand miss so much", "offhand miss", "dual wield hit cap", "how much hit for dual wield", "dw hit penalty", "my offhand misses like half the time how much hit do i need" }, a = "Dual-wielding auto attacks have a big extra miss chance, so you need about 24% hit to never miss a same-level target. In Forever Dual Wield Specialization no longer gives hit and queuing Heroic Strike no longer raises off-hand hit; Fury's Furious Precision (up to 10% off-hand hit) replaces them.", class = "WARRIOR", topic = "basics" }
add{ q = { "what is crit", "how does crit work forever", "crit rating", "crit chance from agility", "what does crit do", "how does crit work", "crit chance", "does agility give crit", "what is crit chance", "crit forever", "is crit good", "how does crit chance work in forever" }, a = "Crit is the chance for a hit to deal bonus damage or healing. In Forever melee, ranged and spell crit are one combined stat, coming from Agility, Intellect, gear, talents and racials. Basic-attack crits also generate extra rage for warriors and bears.", topic = "basics" }
add{ q = { "glancing blows", "what is a glancing blow", "glancing forever", "why do my hits do less damage", "what are glancing blows", "glancing blow", "why do my hits do less damage on bosses", "glancing blows forever", "glancing damage reduction", "what is glancing", "why are my white hits doing less damage on higher level mobs" }, a = "Glancing blows happen only on white auto-attacks against higher-level mobs and deal reduced damage; abilities can't glance. Your weapon skill sets how often you glance and how hard the penalty is. Classic baseline: about 40% of auto-attacks glance against a raid boss, each doing roughly 65% damage at 300 skill. Blizzard said the Forever glance chance is right but some numbers on the character sheet are inaccurate.", topic = "basics" }
add{ q = { "crushing blows", "what is a crushing blow", "why do i take huge hits as tank", "what are crushing blows", "crushing blow", "why do i get hit so hard tanking", "crushing blows forever", "how to avoid crushing blows", "tank taking huge hits", "tanking a skull mob and getting crushed what are crushing blows" }, a = "Crushing blows are extra-strong melee hits (150% damage in Classic) that mobs 3+ levels above you can land on you. Tanks avoid them by raising defense, dodge, parry and block so the attack table fills up. Forever hasn't published its own numbers, so treat this as the Classic baseline.", src = "classic", topic = "basics" }
add{ q = { "attack from behind", "why cant i hit from front", "parry from front", "dodge parry block", "should i attack from behind", "why do mobs parry me", "parry from the front", "can mobs block from behind", "why stand behind the boss", "dodge parry block explained", "why should i stand behind the mob when im dps" }, a = "Mobs can only parry and block attacks from the front. Attack from behind when you're not tanking to remove those outcomes, and to avoid the parry-haste that speeds up a boss's next swing. Dodge still happens from any side.", src = "classic", topic = "basics" }
add{ q = { "expertise forever", "what is expertise", "expertise vs weapon skill", "what does expertise do", "expertise", "is expertise in forever", "expertise reduces dodge", "do i need expertise", "what is expertise and how is it different from weapon skill" }, a = "Forever added Expertise, which works much like in The Burning Crusade: it lowers the chance your attacks are dodged or parried. It takes over from weapon skill as the gear stat melee players look for, since +weapon skill items were nerfed.", topic = "basics" }
add{ q = { "five second rule", "5 second rule", "fsr wow", "why no mana regen while casting", "what is the five second rule", "5sr", "why does my mana stop regenerating", "fsr", "mana regen while casting", "why no mana regen after casting", "why does my mana regen stop after i cast a spell" }, a = "The five-second rule: after you finish casting a spell that costs mana, your Spirit-based mana regen stops for 5 seconds, then resumes. Tricks: let the timer run out between pulls, and use talents that keep part of your regen while casting. This is Classic behavior that Forever keeps, with buffed while-casting talents.", src = "classic", topic = "basics" }
add{ q = { "spirit forever", "what does spirit do", "is spirit good", "spirit mana regen talents", "meditation forever", "spirit stat", "spirit mana regen", "meditation talent", "spirit regen while casting", "is spirit worth it", "is spirit worth stacking on my priest" }, a = "Spirit drives out-of-casting mana regen (and health regen). Forever talents that keep 50% of it while casting: Meditation (Priest, buffed), Arcane Meditation (Mage), Reflection (Druid), Mindfulness (Shaman), Bestial Discipline (Hunter); Reverence (Paladin) keeps 30%. Divine Spirit is baseline for priests at 30, and the Human racial is now +10% Spirit.", topic = "basics" }
add{ q = { "what is mp5", "mana per 5", "mp5 vs spirit", "is mp5 better than spirit", "mp5", "what is mana per 5", "mp5 or spirit", "is mp5 better", "what does mp5 do", "mana per five seconds", "should i get mp5 or spirit gear for healing" }, a = "Mp5 (mana per 5 seconds) is regen from gear that keeps ticking even while you cast, unlike Spirit regen which stops for 5 seconds after each spell. Healers who cast nonstop value mp5; casters who drink often value Spirit. Forever stat guides tie regen mainly to Spirit and haven't published mp5 values.", src = "classic", topic = "basics" }
add{ q = { "what does armor do", "how much armor do i need", "armor damage reduction", "how much armor", "armor reduction", "does armor reduce spell damage", "armor stat", "is armor good", "how much damage does armor actually reduce" }, a = "Armor reduces physical damage you take (melee and most physical abilities, not spells). Higher armor means a bigger percentage cut, with diminishing returns. In Forever armor no longer lowers the rage warriors get from being hit.", topic = "basics" }
add{ q = { "what is threat", "how does aggro work", "why does the mob attack me", "pulling aggro healer", "what is aggro", "how does threat work", "why is the mob attacking me", "healer pulling aggro", "threat explained", "how do mobs choose who to attack", "why does the mob keep attacking me instead of the tank" }, a = "Each mob keeps a threat list. Damage gives 1 threat per point, healing gives half its effective amount (split across mobs), and rage/mana gains add some too. To pull a mob off the tank you need 110% of the tank's threat in melee range or 130% at range. Threat never decays until the fight ends. Classic baseline; Forever hasn't published changes.", src = "classic", topic = "basics" }
add{ q = { "how to lose aggro", "drop threat", "fade feign death vanish", "threat reduction abilities", "how do i drop aggro", "lose threat", "threat drop abilities", "how to reduce threat", "fade", "feign death", "vanish threat", "how can i drop aggro when im pulling threat" }, a = "Feign Death (hunter) and Vanish (rogue) wipe your threat. Fade (priest) and Feint (rogue) reduce it. Blessing of Salvation cuts threat by about 30%. Stance and form matter: Defensive Stance and bear form raise threat, cat form and rogues generate less.", src = "classic", topic = "basics" }
add{ q = { "how do i leave combat", "stuck in combat", "cant mount in combat", "how to drop combat", "how to get out of combat", "how do i drop combat", "leave combat", "why am i still in combat", "im stuck in combat and cant mount up how do i drop it", "wont let me mount says im in combat", "how do i get out of combat so i can mount" }, a = "You stay in combat while any mob has you on its threat list or you are attacking. Kill or outrun every mob (they reset when pulled too far from home), or use Feign Death or Vanish. Don't attack anything and wait a few seconds. In Forever the Lingering Rage bug that stopped health regen after combat was fixed.", src = "classic", topic = "basics" }
add{ q = { "i died what do i do", "how to resurrect", "release spirit", "corpse run", "how to get back to my body", "how do i resurrect", "i died", "how to revive", "what to do after dying", "how do i get back to my body", "just died first time what do i do now" }, a = "1. Click Release Spirit; you appear as a ghost at the nearest graveyard.\n2. Run back to your corpse following the arrow on the minimap or the map (M).\n3. When you're close enough, click Resurrect. Your gear loses some durability with each death, so repair soon.\nThe Legacy talent The Quick and the Dead adds 5% move speed while dead.", topic = "basics" }
add{ q = { "spirit healer", "should i use the spirit healer", "res at graveyard", "angel res", "should i use spirit healer", "graveyard res", "res at the angel", "spirit healer penalty", "is spirit healer worth it", "should i res at the spirit healer or run back to my corpse" }, a = "The Spirit Healer at the graveyard revives you without running to your body, but it costs extra durability on your gear and, from level 10, gives Resurrection Sickness. Only use it if your corpse is somewhere you can't safely reach.", topic = "basics" }
add{ q = { "resurrection sickness", "res sickness how long", "what does resurrection sickness do", "res sickness", "how long is res sickness", "what does res sickness do", "res sickness duration", "how to remove res sickness", "how long does resurrection sickness last in forever" }, a = "Resurrection Sickness comes from reviving at a spirit healer at level 10 or higher. It lasts 10 minutes in Forever and cuts your stats and damage by 75%, so wait it out before fighting. Repair your gear afterward.", topic = "basics" }
add{ q = { "drowned can't breathe", "breath bar", "fatigue bar", "swimming too far", "drowning", "fatigue", "i keep drowning", "how to breathe underwater", "fatigue bar swimming", "what is the breath bar and how do i stop drowning" }, a = "The breath bar drains while underwater and you start taking damage when it empties, so surface in time or use water breathing (Elixir of Water Breathing, shaman Water Breathing, warlock Unending Breath). The fatigue bar appears in deep open sea; turn back before it empties or you'll take heavy damage.", src = "classic", topic = "basics" }
add{ q = { "combat rage gain forever", "rage from crits", "rage normalization forever", "rage gain forever", "how does rage work", "rage normalization", "how to get more rage", "rage changes forever", "how does rage generation work in forever warrior" }, a = "Forever rage: damage taken generates rage as if your armor blocked 50%, ignoring your real armor and absorbs. Basic-attack crits give extra rage (100% more for warriors, 75% for bears). Dual Wield Specialization's off-hand rage bonus was removed.", class = "WARRIOR", topic = "basics" }
add{ q = { "how to join a guild", "how do i get into a guild", "find a guild forever", "guild recruitment", "find a guild", "how do i find a guild", "looking for guild", "lf guild", "im new how do i join a guild", "looking for a guild to join any tips", "how do i get a guild invite" }, a = "Ask in your city's chat or the LookingForGroup channel, or check the official forums' community/guild recruitment sections, then have an officer invite you (/ginvite yourname on their side). You can only join a guild on your own ruleset and faction. Press J to open the Guild and Communities window once you're in.", topic = "basics" }
add{ q = { "how to make a guild", "create guild forever", "guild charter", "how many signatures for guild", "where buy guild charter", "create a guild", "how many signatures guild", "where to buy guild charter", "guild charter cost", "how many signatures do i need to make a guild", "want to start my own guild what do i need", "where is the guild master npc to buy a charter" }, a = "1. Buy a Guild Charter from a Guild Master NPC in any capital (ask a guard for Guild Master).\n2. Name your guild when you buy it.\n3. Collect signatures: the Forever beta asked for 9 other players (10 with you), likely one per Battle.net account.\n4. Turn the signed charter back in to the Guild Master.\nThe Forever charter price wasn't published (it was 10 silver in Classic). Guilds are locked to one ruleset and faction.", topic = "basics" }
add{ q = { "guild bank forever", "does forever have guild bank", "guild bank cost", "guild bank", "does forever have a guild bank", "guild bank tab price", "how much is guild bank", "is there a guild bank", "how much does a guild bank cost in forever" }, a = "Yes, guild banks were in the Forever beta, where the first tab cost 100 gold. Blizzard hasn't published launch prices for more tabs. Check with your guild master, who controls bank permissions per rank.", topic = "basics" }
add{ q = { "guild member limit", "how many people in a guild", "guild cap forever", "guild size limit", "max guild members", "guild member cap", "how many players can be in a guild", "guild cap", "biggest guild size", "how many people can join one guild in forever" }, a = "Blizzard hasn't stated a guild size cap for Forever; players report around 1,000 characters. Guild members who aren't grouped are placed in the same layer as their guild where possible.", topic = "basics" }
add{ q = { "how to invite to group", "how to make a party", "invite player", "/invite command", "how to join friends group", "how to invite", "invite to party", "how do i make a group", "/invite", "how to group with friend", "how to join a group", "how do i invite my friend to a group" }, a = "Type /invite Name (or /inv Name), or right-click their portrait or chat name and pick Invite. A party is up to 5; the leader can convert it to a raid (up to 40) from the party menu. Grouping also pulls you onto your friend's layer so you can see each other. Only same ruleset and same faction can group.", topic = "basics" }
add{ q = { "friend invisible", "cant see my friend", "party member not visible", "friend in different layer", "cant see friend", "party member invisible", "why cant i see my friend", "friend on different layer", "my party member is invisible", "we're grouped but i cant see my friend why" }, a = "You're on different layers (separate copies of the world). Group with them, then click the notice at the lower left and choose Refresh Now (out of combat) to move to their layer; otherwise it moves you automatically after 30 minutes. Layers can't be switched any other way.", topic = "basics" }
add{ q = { "loot rules", "group loot vs free for all", "how to change loot settings", "master looter", "round robin", "loot settings", "how to change loot", "group loot", "free for all loot", "round robin loot", "how do i change the loot settings in my group" }, a = "The party leader sets loot by right-clicking their portrait: Free for All (anyone loots), Round Robin (takes turns), Group Loot (items at or above the threshold, green by default, get a Need/Greed roll), Need Before Greed, and Master Looter (one person hands items out, used in raids). This is the Classic menu; Forever hasn't announced different options.", src = "classic", topic = "basics" }
add{ q = { "need or greed", "when should i roll need", "need vs greed", "what does greed mean", "ninja looting", "when to roll need", "what is greed", "should i roll need", "when is it okay to roll need on an item", "whats the rule for rolling need", "is it rude to roll need on something", "can i roll need if i just want to sell it" }, a = "Roll Need only if the item is a real upgrade for your class and spec right now. Roll Greed if you just want to sell or disenchant it, or Pass if you don't want it. Needing on gear for another class is called ninja looting and gets you kicked and ignored. In Forever, looting an item also unlocks its appearance for every eligible group member, so you don't need to win it for transmog.", src = "classic", topic = "basics" }
add{ q = { "is gdkp allowed", "gdkp forever", "selling raid loot for gold", "gold bid raid", "gdkp", "can we sell raid loot", "is gdkp bannable", "gold bid raids allowed", "can my guild run gdkp raids in forever", "are gold bid loot runs allowed", "will blizz ban gdkp in forever" }, a = "No. Blizzard said at the Sept 17, 2026 developer Q&A that GDKP (raid loot auctioned for gold) is not allowed in Forever. Reports say this applies to North America and Europe.", topic = "basics" }
add{ q = { "how to trade", "trade window", "how to trade items with player", "give item to friend", "trade items", "trade with player", "how do i trade gold", "open trade window", "how do i give my friend an item", "how do i send gold to someone in a trade", "trade a player in person" }, a = "Right-click the player's portrait and choose Trade, or drag an item onto their character. Put items and gold in your side, wait for them to fill theirs, then both click Trade. Check the window carefully before accepting. Forever shows a warning when you trade with strangers about accepting gold from unknown sources.", topic = "basics" }
add{ q = { "how to send mail", "mail items to alt", "how long does mail take", "mail to other player", "mail cost", "send items to alt", "mail to friend", "send gold to alt", "how do i mail gold to my alt and how long does it take", "send mail", "can i mail stuff to my other characters", "how many items can i attach to mail" }, a = "Use any mailbox: open the Send Mail tab, type the name, add up to 12 items and/or gold, and send for a small postage fee. Mail between your own characters on the same account arrives instantly; mail to other players takes about 60 minutes. Unclaimed mail goes back after 30 days, and only 50 letters show at a time.", topic = "basics" }
add{ q = { "cod mail", "cash on delivery", "what is cod", "how does cod work", "send cod", "cod payment", "how do i send something cod to a buyer", "how do i sell something to someone with cod", "what does cod mean in mail", "someone sent me cod mail what is that" }, a = "COD (cash on delivery) mail makes the receiver pay the gold you set before taking the attached items. It's how players sell to each other without meeting. Always check the COD amount before you accept.", src = "classic", topic = "basics" }
add{ q = { "bank alt", "do i need a bank alt", "how to make a bank alt", "storage alt", "extra storage", "is a bank alt worth it", "should i make a bank alt for extra storage", "park a level 1 alt at the bank for storage", "running out of bank space should i make an alt", "how do people use bank alts", "lvl 1 alt for storage" }, a = "A level 1 alt parked next to a bank and mailbox works as extra storage: it gets its own 48 bank slots and bags, items mailed between your own characters arrive instantly, and it can post auctions for you. No second account is needed.", topic = "basics" }
add{ q = { "chat channels", "how to talk in trade", "how to join lfg channel", "general chat", "/1 /2 command", "how to talk in trade chat", "join lfg channel", "how to type in trade", "how to join world chat", "how do i talk in trade chat", "how do i join lookingforgroup channel", "what is /2", "how do i get into trade chat outside the city" }, a = "Default channels: /1 General (zone), /2 Trade (capitals only), and LocalDefense; LookingForGroup is joined with /join LookingForGroup. Other commands: /s say, /y yell, /p party, /g guild, /o officer, /ra raid, /w Name to whisper, /r to reply to the last whisper. Whispers open in their own tab by default in Forever.", src = "classic", topic = "basics" }
add{ q = { "what do chat colors mean", "pink chat text", "orange chat", "blue chat text", "green chat text", "chat colors", "what does pink chat mean", "green chat", "red chat", "what does pink text in chat mean", "why is some chat text orange", "what color is guild chat" }, a = "Default chat colors: white = say, red = yell, pink/purple = whispers, light blue = party, orange = raid, green = guild, dark green = officer, yellowish/peach = General, Trade and other numbered channels, yellow = system messages. You can change any of them by right-clicking the chat tab and choosing Settings.", src = "classic", topic = "basics" }
add{ q = { "how to ignore someone", "ignore player", "/ignore", "block spam", "how to ignore", "block player", "how to block someone", "how do i ignore a spammer in chat", "someone keeps whispering me how do i block them", "how to stop seeing someones messages", "ignore list" }, a = "Type /ignore Name, or right-click their name in chat and choose Ignore. You won't see their chat, whispers or invites. Manage the list from the Friends window (O), Ignore tab.", src = "classic", topic = "basics" }
add{ q = { "how to report a player", "report spam", "report harassment", "report bad name", "how to report", "report player", "report a name", "report someone", "how do i report someone for harassment", "someone has an offensive name how do i report it", "where is report player button" }, a = "Target the player and right-click their portrait (or right-click their name in chat), choose Report Player, pick the category that fits, then click Report. Reported players can't see who reported them.", topic = "basics" }
add{ q = { "how to report bots", "report botter", "bot farming report", "gold seller report", "report bots", "how to report a bot", "too many bots", "how do i report a bot farming mobs", "theres a bot running in circles how do i report it", "gold spammer whispering me how do i report", "report cheater" }, a = "Right-click the bot's portrait or chat name, choose Report Player and pick the cheating option. Blizzard says it is actively banning Forever botters and also punishes accounts that buy or knowingly receive illicit gold, from removing the gold up to permanent closure.", topic = "basics" }
add{ q = { "can i buy gold", "is buying gold bannable", "rmt forever", "buying gold bannable", "rmt", "buy gold forever", "will i get banned for buying gold", "is buying gold allowed", "will i get banned if i buy gold in forever" }, a = "Buying gold is real-money trading (RMT) and is against the rules. Blizzard has been banning Forever gold buyers and sellers since the beta and can remove the gold, suspend, or permanently close the account. There is no WoW Token in Forever.", topic = "basics" }
add{ q = { "friends list", "add friend", "battletag friend", "see friends online", "how to add friend", "add someone to friends", "how do i add my friend by battletag", "how to see when my friends are online", "how do i add a friend in forever", "press o friends", "add real id friend" }, a = "Press O for the Friends list. Add a character name for a normal friend or a BattleTag for a Battle.net friend, who you can see across games. Remember you can only group with friends on your ruleset and faction.", src = "classic", topic = "basics" }
add{ q = { "emotes", "how to dance", "/wave", "custom emote", "how to emote", "emote list", "how do i do a custom emote", "what emotes are there", "how do i make my character dance", "list of emotes", "/e command" }, a = "Type emotes like /wave, /cheer, /dance, /thank, /bow or /sit. For your own text, type /emote (or /e) followed by what your character does, e.g. /e sharpens his blade.", topic = "basics" }
add{ q = { "looking for group tool", "how do i find a dungeon group", "lfg forever", "i key group finder", "lfg tool", "looking for group", "group finder", "i key lfg", "how do i find a group for a dungeon in forever", "is there an lfg list in forever", "how to post a group listing" }, a = "Press I for the Looking For Group list. You can post a listing or browse others, but it doesn't auto-match or teleport you, and there are no summoning stones, so you must travel. You pick a playstyle first: Learning, Relaxed, Competitive or Carry Offered. The LookingForGroup chat channel also works.", topic = "basics" }
add{ q = { "default keybinds forever", "what keys open what", "hotkeys list", "key for map", "key for quest log", "keybinds", "default keybinds", "hotkeys", "default hotkeys", "what key opens the legacy and professions window", "what are the default key bindings in forever", "what key opens talents" }, a = "Forever default keys: C character, B backpack (Shift+B all bags), P spellbook, N talents, Y Legacy talents, K professions, L quest log, M map, U reputation, O friends and raid, J guild and communities, I looking for group, H honor/PvP, Shift+P collections, V / Shift+V enemy / friendly nameplates, Esc game menu.", topic = "basics" }
add{ q = { "where are profession spells", "how do i put cooking on my bar", "profession icon action bar", "professions window", "where are my profession spells", "cooking on action bar", "profession icon", "how to put profession on bar", "where did professions go", "how do i get cooking onto my action bar" }, a = "Professions moved out of the spellbook into their own window. Press K, then drag the profession icon to your action bar. The window lets you search recipes, track a recipe and link your profession in chat.", topic = "basics" }
add{ q = { "how to change keybinds", "keybind menu", "quick keybind mode", "bind keys to action bar", "quick keybind", "bind keys", "rebind keys", "how to set keybinds", "how do i change my keybinds in forever", "how do i bind a key to my action bar slot", "how to use quick keybind mode" }, a = "Esc > Options > Keybindings. Fastest way: use Quick Keybind mode, then hover over an action bar slot and press the key you want for it. You can add more action bars in the Action Bars tab.", topic = "basics" }
add{ q = { "spells not on action bar", "new spell not showing", "where did my new ability go", "learned spell not on bar", "new spells not on bar", "learned a spell cant find it", "why arent new spells on my bars", "spell not added to action bar", "trained new rank where is it", "new abilities dont show up", "just trained at my class trainer but the spell isnt on my bars", "how do i put new spells on bar", "new spell didnt go on my bar" }, a = "Forever no longer puts newly learned spells on your bars automatically. Open your spellbook (P) and drag the new spell onto a bar. Higher ranks replace the old rank on your bar automatically.", topic = "basics" }
add{ q = { "auto loot", "how to turn on auto loot", "autoloot setting", "shift click loot", "autoloot", "turn on autoloot", "how to enable auto loot", "auto loot option", "how do i loot everything at once", "auto loot setting where", "is there auto loot in forever", "how do i loot without shift clicking every corpse" }, a = "Turn on Auto Loot in Options (type 'auto loot' in the Options search bar at the top right). With it on, clicking a corpse grabs everything; holding the auto-loot key (Shift by default) reverses it for that click.", topic = "basics" }
add{ q = { "options search bar", "cant find a setting", "where is the setting for", "find setting fast", "how to find a setting", "search options", "options search", "where is that setting", "find setting in options", "cant find the option i want in settings", "settings search box", "is there a way to search the options menu" }, a = "Esc > Options has a search box at the top right. Type any part of the setting name (auto loot, nameplates, UI scale, damage meter) to jump straight to it.", topic = "basics" }
add{ q = { "ui scale", "make ui smaller", "ui too big", "change ui size", "change ui scale", "ui is too big", "how to shrink ui", "ui scale slider", "my ui is huge how do i make it smaller", "resize ui", "everything on my screen is too big how do i scale the ui down" }, a = "Open Esc > Options and type 'UI Scale' in the search box at the top right, then move the slider. For finer layout control use Edit Mode (Esc > Edit Mode) to resize or move each frame.", src = "classic", topic = "basics" }
add{ q = { "edit mode", "move action bars", "move unit frames", "how to move ui elements", "how to move action bars", "move my unit frames", "edit mode forever", "move ui", "how do i move my bars", "how to move the minimap", "how to rearrange my ui", "how do i drag my action bars somewhere else" }, a = "Press Esc and pick Edit Mode. You can drag, resize and snap action bars, player/target frames, raid frames, the cooldown manager and more. Turn on Grid and Snap to Elements to line things up, and save it as a layout.", topic = "basics" }
add{ q = { "nameplates", "show enemy nameplates", "how to turn on nameplates", "v key nameplates", "friendly nameplates", "turn on nameplates", "enemy nameplates", "show nameplates", "nameplates key", "nameplates not showing", "how do i see health bars over mobs", "how do i see enemy health bars above their heads" }, a = "Press V to toggle enemy nameplates and Shift+V for friendly ones. Options > Nameplates holds Always Show Nameplates, My Name, NPC names, aggro coloring and style options. Forever nameplates show elite status, and debuff icons are click-through.", topic = "basics" }
add{ q = { "hide last name", "hide secondary name", "my second name showing", "hide my last name", "hide second name", "how to hide surname", "last name over my head", "remove secondary name", "how do i stop my last name showing over my character", "can i hide my last name from showing above my head" }, a = "Go to Options > Nameplates > My Secondary Name to hide your second name over your head. It still shows in chat.", topic = "basics" }
add{ q = { "camera keeps turning", "camera follow setting", "camera max distance", "zoom out further", "camera keeps moving", "stop camera following", "camera swings behind me", "max camera zoom", "zoom out more", "camera distance", "how do i stop my camera auto turning", "my camera keeps swinging around how do i stop it" }, a = "Options > Controls: set Camera Following Style to Never so the camera stops swinging behind you, and raise Max Camera Distance to zoom out further.", topic = "basics" }
add{ q = { "health numbers on bars", "show health percent", "show mana numbers", "status text", "show health numbers", "health percentage on frame", "mana numbers", "show hp numbers", "how to see exact health", "display health as numbers", "how do i make my health bar show actual numbers" }, a = "Options > Interface: set the health and mana display to Numeric value, Percentage, or Both. It's off (none) by default.", topic = "basics" }
add{ q = { "target of target", "tot frame", "how to see who mob is attacking", "tot", "turn on target of target", "see who the mob is targeting", "target of target frame", "how to see what mob is hitting", "enable tot forever", "as a healer how do i see who the boss is attacking" }, a = "Turn on Target of Target in Options > Combat. It's off by default and is very handy for tanks and healers to see who a mob is hitting.", topic = "basics" }
add{ q = { "mouseover macro setting", "self cast key", "mouseover casting forever", "click casting", "mouseover casting", "self cast keybind", "mouseover heal setting", "click cast", "focus keybind", "mouseover cast option", "how to cast on mouseover without macro", "can i heal party members by mousing over them without a macro" }, a = "Forever has built-in mouseover cast and self-cast keybinds in Options > Combat, plus focus keybinds, so you can heal a unit frame by hovering it without macros. Alt is the usual self-cast modifier. Click Casting is set up from the keybindings menu.", topic = "basics" }
add{ q = { "swing timer", "built in swing timer", "cooldown manager", "personal resource display", "swing timer forever", "how to turn on swing timer", "is there a swing timer", "does forever have a built in swing timer for my warrior", "does forever have a personal resource display", "how do i turn on the cooldown manager", "where is the swing timer option" }, a = "Forever has a built-in Swing Timer and Cooldown Manager (Options > Advanced Options) and a Personal Resource Display (Options > Combat) that shows health and resource bars under your character. These replace common addons.", topic = "basics" }
add{ q = { "damage meter", "dps meter", "how to see my dps", "turn on damage meter", "see my dps", "turn on dps meter", "built in damage meter", "how to check dps", "where is the damage meter setting", "how do i see how much dps im doing" }, a = "Forever has a built-in Damage Meter: Options > Advanced Options > Damage Meter. It shows at the top-left; click the corner icon to switch between Damage Done, DPS, Healing, HPS, Damage Taken, Interrupts, Dispels or Deaths, and use the gear icon > Reset Data to clear it.", topic = "basics" }
add{ q = { "where is xp bar", "how much xp to level", "xp bar not showing", "rested xp bar blue", "xp bar", "xp bar missing", "rested xp", "blue xp bar", "how much exp until level", "how do i see my exp", "how much exp do i need for next level" }, a = "The XP bar sits along the bottom of the screen above your action bars; hover over it to see exact numbers. A blue/purple shaded section is rested XP, which doubles XP from kills until used. If it's gone, check Edit Mode for the status tracking bar.", src = "classic", topic = "basics" }
add{ q = { "experience presets", "classic or enhanced preset", "quest blobs on map", "turn off quest markers", "one bag setting", "experience preset", "classic preset", "enhanced preset", "quest areas on map", "one bag", "how do i change my preset", "picked classic preset by mistake can i switch to enhanced" }, a = "On first login you choose a preset. Classic: SD models, no quest objective areas on the map, separate bags, transmog off, turning keys, classic layout. Enhanced: HD models, quest POIs on, one bag, transmog on, strafe keys, centered layout. You can switch any of these later in Options.", topic = "basics" }
add{ q = { "hd models or sd", "old character models", "change to classic models", "hd models", "sd models", "old models", "classic models", "switch to old models", "change character models", "how to use original models", "can i switch back to the old vanilla character models" }, a = "Each character can use HD or SD (original) models. It's purely visual and can be switched any time in Options or at a barber shop.", topic = "basics" }
add{ q = { "ping system", "how to ping", "ping keybind", "ping", "how do i ping", "ping key", "ping system forever", "how to use ping", "ping a target", "set up ping keybind", "how do i ping a mob for my group" }, a = "Forever has the modern ping system: bind a ping key in Options > Ping, then ping targets, directions or danger spots for your group.", topic = "basics" }
add{ q = { "controller support", "gamepad forever", "play with controller", "controller", "gamepad", "controller support forever", "can i use a controller", "xbox controller", "ps5 controller", "does forever support gamepad", "can i play forever with an xbox controller" }, a = "Gamepad support is in a working beta: movement, spells, interaction and UI menus all work, and you can tune it in Edit Mode and Options.", topic = "basics" }
add{ q = { "how to make a macro", "create macro", "/macro", "macro tutorial", "how do macros work", "make a macro", "macro", "how to create macro", "macro guide", "how do i make macros", "macro help", "how to write a macro", "never made a macro before how do i do it" }, a = "1. Type /macro (or /m) to open the macro window.\n2. Click New, give it a name and pick the question-mark icon so #showtooltip shows the spell's icon.\n3. Type or paste the macro text (max 255 characters) and close the window.\n4. Drag the macro icon onto your action bar.\nSpell names must match your game language.", topic = "basics" }
add{ q = { "mouseover heal macro", "heal without targeting macro", "priest mouseover flash heal", "mouseover heal", "mouseover macro", "heal macro", "mouseover heal macro priest", "flash heal mouseover", "heal without target", "mouseover heals forever", "need a mouseover heal macro for my priest" }, a = "Mouseover heal macro (swap in your spell):\n#showtooltip\n/cast [@mouseover,help,nodead][help,nodead][@player] Flash Heal\nIt heals whoever your mouse is over, otherwise your friendly target, otherwise yourself. Forever also has built-in mouseover keybinds in Options > Combat.", topic = "basics" }
add{ q = { "start attack macro", "melee opener macro", "auto attack macro", "rogue sinister strike macro", "startattack macro", "macro to start attack", "opener macro", "sinister strike macro", "melee macro", "attack macro", "macro so my rogue starts auto attacking with sinister strike" }, a = "Opener that also starts auto-attack:\n#showtooltip\n/startattack\n/cast Sinister Strike\nSwap Sinister Strike for any melee ability (Heroic Strike, Crusader Strike, etc.).", topic = "basics" }
add{ q = { "interrupt macro", "stopcasting macro", "kick mouseover macro", "kick macro", "stopcasting", "counterspell macro", "focus kick macro", "mouseover interrupt", "pummel macro", "need a macro that stops my cast and interrupts" }, a = "Interrupt that cancels your own cast first:\n#showtooltip Counterspell\n/stopcasting\n/cast [@mouseover,harm,nodead][harm,nodead] Counterspell\nReplace Counterspell with Kick, Pummel, Earth Shock etc. It hits your mouseover enemy, otherwise your target.", topic = "basics" }
add{ q = { "trinket macro", "use trinket with spell", "/use 13 14", "use trinkets macro", "/use 13", "trinket with cooldown", "pop trinkets", "macro trinkets", "how do i macro my trinkets to my big cooldown" }, a = "Fire both trinkets with your main cooldown:\n#showtooltip Spell Name\n/use 13\n/use 14\n/cast Spell Name\n13 and 14 are the top and bottom trinket slots.", topic = "basics" }
add{ q = { "focus macro", "sheep focus macro", "polymorph focus", "cc focus macro", "polymorph focus macro", "sheep focus", "cc focus", "focus target macro", "sap focus macro", "mage macro to sheep my focus target" }, a = "Crowd control on your focus:\n#showtooltip Polymorph\n/focus [@focus,noexists][@focus,dead][mod:ctrl] target\n/cast [@focus,harm,nodead][@target,harm,nodead] Polymorph\nThe first press sets your target as focus (Ctrl+press resets it), then it re-sheeps the focus without changing target.", topic = "basics" }
add{ q = { "castsequence macro", "cast sequence example", "one button macro", "castsequence", "cast sequence macro", "castsequence example", "/castsequence", "reset castsequence", "how do i make a castsequence macro" }, a = "Example cast sequence:\n#showtooltip\n/castsequence reset=target/combat Spell One, Spell Two\nEach press casts the next spell; it only advances when a cast succeeds, and resets when you change target or leave combat.", topic = "basics" }
add{ q = { "hunter auto shot macro", "hunter macros forever", "pet attack macro", "hunters mark mouseover", "hunter macros", "auto shot macro", "hunters mark macro", "hunter macro forever", "pet attack mouseover", "good macros for hunter in forever" }, a = "Hunter macros:\nAuto Shot (won't toggle it off):\n#showtooltip\n/targetenemy [noexists][dead][help]\n/cast !Auto Shot\nPet attack on mouseover:\n#showtooltip\n/petattack [@mouseover,harm,nodead][]\nHunter's Mark on mouseover:\n#showtooltip\n/cast [@mouseover,harm][] Hunter's Mark", class = "HUNTER", topic = "basics" }
add{ q = { "druid form macro", "cat form dash macro", "cancelform macro", "stay in cat form", "druid macro", "cat form macro", "cancelform", "powershift macro", "druid form macros", "stay in form macro", "macro so cat form doesnt toggle off when i spam it" }, a = "Druid macros: /cast !Cat Form keeps you in Cat Form instead of toggling out. /cancelform leaves any form. Dash that shifts you first:\n/cast [noform:3] !Cat Form\n/cast [form:3] Dash", class = "DRUID", topic = "basics" }
add{ q = { "eat and drink macro", "food water one button", "potion healthstone macro", "eat drink macro", "food water macro", "potion macro", "healthstone macro", "drink macro", "one button food and water", "macro to eat and drink at the same time" }, a = "Eat and drink with one press:\n/use Your Drink\n/use Your Food\nHealthstone-then-potion button:\n/use Your Healthstone\n/use Your Healing Potion\nUse exact item names.", topic = "basics" }
add{ q = { "where do i put addons", "addon folder forever", "addons folder path", "how to install addons", "addon folder", "where to install addons", "addons path", "install addons", "addon install", "how do i install addons forever", "forever addon directory", "wher do i put addons for forever", "i downloaded an addon where does the folder go" }, a = "Windows: World of Warcraft\\_forever_\\Interface\\AddOns\\ (in Battle.net pick Forever, click the gear by Play > Show in Explorer). Mac: /Applications/World of Warcraft/_forever_/Interface/AddOns/. Create Interface and AddOns if missing. Copy the addon's folder (not the zip) there, or use CurseForge/Wago with Forever selected as the game.", topic = "basics" }
add{ q = { "addon not showing", "addon not loading", "addons not working forever", "my addons dont work", "addons not working", "addons dont show up", "addons not in list", "addon wont load", "installed an addon but it doesnt show up in game", "my addons wont load in forever" }, a = "1. Check the path: the .toc must be at _forever_/Interface/AddOns/AddonName/AddonName.toc, not one folder deeper.\n2. Make sure you downloaded the Forever version (CurseForge Files tab); Classic Era addons won't load because Forever runs the Midnight client (interface 16001).\n3. At character select or Esc > AddOns, make sure it's ticked for this character.\n4. Fully restart the game; /reload doesn't detect new folders.\n5. Type /console scriptErrors 1 to see which addon throws errors.", topic = "basics" }
add{ q = { "load out of date addons", "addon out of date", "enable out of date addons", "incompatible addon", "out of date addons", "load out of date", "enable old addons", "incompatible addons", "how to load out of date addons", "my addon says out of date how do i make it load anyway" }, a = "In the AddOns list (Esc > AddOns or at character select) you can tick 'Load out of date AddOns' to force older addons to load. It only helps if the addon still works on the new client; it can't fix addons whose code is broken or blocked by Forever's combat restrictions. Better to update to the Forever build of the addon.", topic = "basics" }
add{ q = { "lua errors", "addon errors popup", "bugsack", "how to find broken addon", "lua error", "addon error", "broken addon", "error popup", "how to find which addon is broken", "keep getting lua errors how do i find which addon is causing it" }, a = "Install BugSack + BugGrabber to catch Lua errors quietly. To track a culprit: disable all addons, confirm the default UI works, then enable them one at a time. /console scriptErrors 1 shows errors on screen, /console scriptErrors 0 hides them.", topic = "basics" }
add{ q = { "best addons forever", "what addons should i get", "recommended addons", "must have addons", "best addons", "good addons", "addons for forever", "top addons", "which addons should i use", "what addons should i get for forever", "must have addons for a new player in forever" }, a = "Popular working Forever addons: Questie (quests), Baganator/Bagnon/BetterBags (bags), Bartender4 (bars), Leatrix Plus (comfort tweaks), Deadly Boss Mods, Auctionator, VuhDo or Grid2 (raid frames), and BugSack. Use only builds made for Forever.", topic = "basics" }
add{ q = { "does weakauras work", "which addons dont work forever", "why dont combat addons work", "omnicc forever", "weakauras forever", "addons that dont work", "combat addons", "omnicc", "why do combat addons not work", "why doesnt weakauras work in forever", "which addons are broken in forever" }, a = "Forever uses retail Midnight's addon rules, so addons can't read hidden combat values or make decisions in combat. Broken or gutted: official WeakAuras, OmniCC, OmniCD, Hekili, old Skada/Recount, Quartz, MSBT, Postal, AdiBags and others. UI skins, bags, maps and quest helpers still work. Use the built-in Damage Meter and Cooldown Manager instead.", topic = "basics" }
add{ q = { "does questie work forever", "quest helper addon", "quest addon forever", "questie", "does questie work", "questie forever", "quest addon", "quest helper", "best quest addon", "is questie working for forever yet", "is there a quest helper addon for forever" }, a = "Yes, Questie has a Forever version (often paired with QuestieTrace). Make sure you get the Forever file, since the Classic Era version won't load.", topic = "basics" }
add{ q = { "addon settings lost", "reset addon settings", "wtf folder backup", "addon settings reset", "lost addon settings", "wtf folder", "backup addon settings", "savedvariables", "all my addon settings got wiped how do i back them up" }, a = "Addon settings live in the WTF folder (WTF/Account/.../SavedVariables). Back it up before resetting or reinstalling. Check whether each addon profile is account-wide or per character if settings seem to vanish on alts.", topic = "basics" }
add{ q = { "how much is forever", "is forever free", "forever subscription price", "do i need a sub", "monthly cost", "how much does forever cost", "forever price", "do i need a subscription", "subscription price", "monthly cost forever", "is forever included with wow sub", "do i have to pay extra for forever or is it in my sub", "how much is forever per month" }, a = "Forever is included with a regular WoW subscription or Game Time; there's no separate box to buy for the base game. US prices (Sept 2026): $14.99 for 1 month, $13.99/month for 3 months, $12.99/month for 6 or 12 months. No free trial was listed.", topic = "basics" }
add{ q = { "forever editions", "skyborne pack price", "heroic vs epic pack", "what do the packs give", "collectors edition forever", "editions", "skyborne pack", "heroic pack", "epic pack", "pack prices", "what comes in the packs", "collector's edition", "what do i get with the skyborne heroic pack", "which forever pack should i buy", "heroic vs epic edition whats the difference" }, a = "Optional packs: Skyborne Heroic $29.99 (Skyborne race, name reservation, cosmetics). Skyborne Epic $59.99 (adds beta access, 30 days game time, more cosmetics). Warcraft Forever Collection $79.99 (adds Warcraft III: Reforged; sold until Jan 11, 2027). A physical Collector's Edition includes the Collection code. Only the Skyborne race is locked behind a pack.", topic = "basics" }
add{ q = { "can i play forever on mac", "mac support", "does forever run on mac", "apple silicon forever", "mac", "forever on mac", "does it run on mac", "apple silicon", "m1 mac", "macbook", "can i play forever on my macbook", "does forever support mac m1 m2" }, a = "Yes, Forever runs on Windows and Mac. Mac minimum: macOS 12, Apple M2 (or 9th-gen Intel) with 8 GB RAM. Recommended: macOS 15 and Apple M4 with 16 GB. Both platforms need about 128 GB of SSD space.", topic = "basics" }
add{ q = { "system requirements", "can my pc run forever", "minimum specs forever", "recommended specs", "specs", "can i run forever", "min specs", "pc requirements", "will my pc run it", "will my laptop be able to run forever", "what are the min specs for forever" }, a = "PC minimum: Windows 10 64-bit, 4-core 3.0 GHz CPU (i5-8400 / Ryzen 5 2600), DX12 GPU with 4 GB (GTX 1060 / RX 580), 8 GB RAM. Recommended: Windows 11, 8-core modern CPU, 8 GB GPU (RTX 40 / RDNA 3), 16 GB RAM. 128 GB SSD space either way.", topic = "basics" }
add{ q = { "how to install forever", "download forever", "where is forever in battle.net", "install forever", "how do i download", "where is forever in battlenet", "how to get forever", "install game", "how do i download wow forever in the battle net app", "cant find forever in the launcher" }, a = "Open the Battle.net app, select World of Warcraft, pick World of Warcraft: Forever in the game version dropdown, and click Install. You need an active subscription or Game Time to log in.", topic = "basics" }
add{ q = { "character transfer forever", "can i transfer my character", "move character to pvp ruleset", "change ruleset", "character transfer", "transfer character", "can i move my character", "server transfer", "transfer to pvp", "can i transfer my character from normal to pvp ruleset", "is there a character transfer in forever" }, a = "No. Forever has no transfers between rulesets; your ruleset choice is permanent. The only exception: a Hardcore character that dies (Hardcore isn't live yet) can move to another ruleset. Classic Era characters can't be moved into Forever either.", topic = "basics" }
add{ q = { "name change forever", "can i change my name", "rename character", "paid name change", "name change", "change name", "rename", "can i rename my character", "rename character forever", "can i change my character name in forever", "regret my name can i change it" }, a = "Name changes aren't available in Forever right now. Choose carefully: names are first and last name, 2-12 letters each, unique across your whole region and all rulesets. Offensive names can get a forced rename.", topic = "basics" }
add{ q = { "faction change forever", "race change forever", "appearance change", "barber shop forever", "faction change", "race change", "barber shop", "change race forever", "change faction forever", "can i change my race or faction in forever", "is there a barber shop in forever" }, a = "No paid faction or race change service was announced for Forever. You can change your look and switch between HD and SD models at a barber shop (Dalaran has one).", src = "classic", topic = "basics" }
add{ q = { "can i play horde and alliance", "faction lock pvp", "why cant i make horde", "one faction pvp ruleset", "play both factions", "faction lock", "horde and alliance same account", "one faction per account", "faction restriction pvp", "why cant i make a horde char on pvp i already have alliance", "can i have both alliance and horde on the same account" }, a = "On the PvP and RP-PvP rulesets each account can only have characters of one faction per region. On Normal and RP you can have both factions.", topic = "basics" }
add{ q = { "do i need separate sub for eu", "play on eu and us", "regions forever", "eu and us", "separate sub for eu", "regions", "play on eu", "eu servers", "region transfer", "can i play on eu and us with one sub", "do i need another account for eu region" }, a = "Each region needs its own WoW account and subscription, and nothing carries over between them. One Battle.net account can hold several WoW accounts.", topic = "basics" }
add{ q = { "what ruleset should i pick", "normal vs pvp ruleset", "pve or pvp forever", "rp ruleset", "which ruleset", "normal or pvp", "pve or pvp", "what ruleset", "pvp ruleset", "ruleset choice", "should i play normal or pvp ruleset", "whats the difference between normal and pvp ruleset" }, a = "Normal: other players can't attack you unless you flag with /pvp or enter their territory; the flag drops 5 minutes after PvP ends. PvP: you're flagged nearly everywhere outside sanctuaries and your own faction's areas, so expect ganking. RP and RP-PvP use the same rules plus roleplay and strict naming. Hardcore (one life) comes later. You can only group and guild within one ruleset.", topic = "basics" }
add{ q = { "where to buy food and water", "buy water", "where to get drinks", "food vendor", "buy food", "food and water vendor", "where to get water", "where to buy drinks", "where can i buy food", "where do i buy water for my mage", "need food where is a vendor" }, a = "Innkeepers sell food and drink, and so do trade-goods/food vendors in most towns. Buy the highest level food and water you can use and keep a stack in your bags. Mages can conjure water, and cooking makes better food.", topic = "basics" }
add{ q = { "how to eat and drink", "regen health out of combat", "drink faster", "sit to eat", "how to eat", "how to drink", "regen health", "regen mana", "how to eat food", "sit and eat", "how to get health back", "how do i get health back out of combat", "how do i drink to get mana back" }, a = "Out of combat, eat food to regenerate health and drink to regenerate mana. You sit while doing it, and moving or taking damage stops it. Eat and drink at the same time to save downtime (a one-button /use macro helps). Cooked buff food gives Well Fed, and in Forever it also adds +5% XP from kills.", topic = "basics" }
add{ q = { "how to rest", "what is rested xp", "rest in inn", "log out in inn", "rest", "rested xp", "how to get rested", "inn rest", "what is resting", "rested bonus", "what is rested xp and how do i get it", "does logging out in an inn give rested" }, a = "Log out in an inn or a capital city (you'll see Resting by your portrait) to build rested XP, which doubles XP from kills until it's used up. It builds 5% of a level every 8 hours, even while offline, up to 1.5 levels (about 10 days to fill). Quest XP isn't doubled.", topic = "basics" }
add{ q = { "how to set hearthstone", "bind hearthstone", "change home inn", "make this inn your home", "set hearthstone", "bind hearth", "change hearth", "set home", "hearthstone inn", "how to change hearthstone location", "how do i set my hearth to this inn", "how do i change where my hearthstone goes" }, a = "Talk to any innkeeper and choose the option to make this inn your home. Your Hearthstone will then take you back there. Skyborne start bound to Zephras Isle, so rebind once you reach your faction's city.", topic = "basics" }
add{ q = { "hearthstone cooldown", "how long hearthstone cd", "hearth cd", "hearthstone cd", "hearth cooldown", "how long is hearth cd", "hearthstone timer", "when can i use hearthstone again", "hs cooldown", "how long is the hearthstone cooldown", "whats the hearth cd in forever" }, a = "The Hearthstone has a 1-hour cooldown and a 10-second cast that any damage interrupts (Classic baseline; no Forever change has been reported). Many players bind it to the city where they bank and train, then hearth to sell and repair.", src = "classic", topic = "basics" }
add{ q = { "lost my hearthstone", "deleted hearthstone", "get new hearthstone", "lost hearthstone", "deleted my hearth", "new hearthstone", "where to get hearthstone", "replace hearthstone", "no hearthstone", "i deleted my hearthstone how do i get it back", "how do i get another hearthstone" }, a = "Talk to any innkeeper and ask for a new Hearthstone; they give one for free.", src = "classic", topic = "basics" }
add{ q = { "how to get from eastern kingdoms to kalimdor", "alliance boat to kalimdor", "how to get to darkshore from stormwind", "cross continents alliance", "ek to kalimdor alliance", "boat to kalimdor", "stormwind to darkshore", "how to get to kalimdor alliance", "alliance boat", "how to get to auberdine", "alliance how do i get from stormwind to kalimdor", "how do i get to darkshore as alliance" }, a = "Alliance: take the new boat from Stormwind Harbor to Auberdine (Darkshore), or the Menethil Harbor (Wetlands) boat to Theramore (Dustwallow Marsh). Auberdine's boat to Rut'theran Village goes on to Darnassus. Neutral option: Booty Bay to Ratchet goblin boat.", topic = "basics" }
add{ q = { "horde how to get to undercity", "zeppelin to undercity", "horde cross continent", "how to get to stranglethorn horde", "horde zeppelin", "how to get to uc from org", "horde cross continents", "how to get to stv horde", "zep to grom'gol", "horde how do i get to undercity from org", "how do i get from org to stranglethorn" }, a = "Horde: zeppelins leave from the towers just outside Orgrimmar's gate to Undercity and to Grom'gol (Stranglethorn Vale), and there's also an Undercity-Grom'gol zeppelin. No zeppelin goes to Thunder Bluff. The new Steamwheedle Port (Tanaris) to Powderfuse Port (Riverglades) ferry is often quicker for southern zones.", topic = "basics" }
add{ q = { "stormwind to ironforge", "deeprun tram", "how to get to ironforge from stormwind", "sw to if", "tram", "how to get to ironforge", "stormwind to ironforge tram", "ironforge from stormwind", "how do i get to ironforge from stormwind", "where is the tram in stormwind" }, a = "Take the Deeprun Tram from Stormwind's Dwarven District; it drops you in Ironforge's Tinker Town in about a minute. Flying between them also works once you have both flight paths.", topic = "basics" }
add{ q = { "how do flight paths work", "learn flight path", "talk to flight master first", "fly to town", "flight paths", "how to fly", "learn flight paths", "flight master", "taxi", "how do flight paths work in forever", "do i need to talk to every flight master" }, a = "Talk to each flight master you pass to learn that node (a green icon). Then any flight master can fly you to any node you've learned on that continent, as long as there's a route. Always grab the flight point when you reach a new town. Legacy's Frequent Flier halves flight costs and makes flights 20% faster.", topic = "basics" }
add{ q = { "portal to stormwind", "dalaran portal", "how to get to stormwind from dalaran", "dalaran to stormwind", "how to get to stormwind", "stormwind portal", "dal portal", "how do i get from dalaran to stormwind", "is there a portal in dalaran" }, a = "Dalaran has a portal to Stormwind for Alliance (it's how Skyborne reach the city). The Stormwind-to-Dalaran portal was removed during the beta, so going the other way you walk from Southshore or fly to Dalaran's flight master.", topic = "basics" }
add{ q = { "how to get to zephras isle", "skyship to zephras", "valanaar boat", "zephras isle", "how to get to zephras", "skyboat", "how do i get to valanaar", "zephras travel", "how do i get to zephras isle", "where is the skyboat to valanaar" }, a = "Skyboats fly between Valanaar (Zephras Isle) and either Dalaran (Alliance side) or Skywatcher Plateau just outside Thunder Bluff in Mulgore (Horde side), arriving about every 5 minutes. Either faction can ride both.", topic = "basics" }
add{ q = { "new player tips", "what should i do first", "beginner tips forever", "im new to wow", "new player", "beginner tips", "what to do first", "im new", "tips for new players", "newbie tips", "im new to wow what should i do first", "any tips for a brand new player in forever" }, a = "1. Pick the Enhanced preset if you're new.\n2. Visit your class trainer every even level; spells aren't added to bars automatically.\n3. Learn two primary professions (a gathering one is easiest) plus cooking, fishing and first aid.\n4. Grab every flight path and set your hearthstone at your main town.\n5. Keep food, water and (hunters) ammo stocked.\n6. Repair often and don't res at the spirit healer unless you must.\n7. Group with others for hard quests and dungeons; there's no auto group finder.", topic = "basics" }
add{ q = { "how many professions can i have", "professions limit", "which professions should i take", "how many professions", "profession limit", "which professions", "best professions", "two professions", "profession choice", "how many professions can i learn in forever", "which professions should i pick as a new player" }, a = "Two primary professions (Herbalism, Mining, Skinning, Alchemy, Blacksmithing, Enchanting, Engineering, Leatherworking, Tailoring) plus all three secondary ones (Cooking, Fishing, First Aid). Taking two gathering professions is the easiest way to make gold while leveling.", topic = "basics" }
add{ q = { "what is a campsite", "how to camp", "campfire rest", "campsite", "camping", "campfire", "how to make a campsite", "camp rest", "what is a campsite in forever", "how do i make a campfire to rest" }, a = "Forever's Camping lets you build a campfire in the open world as a place to rest, trade and meet people. Professions unlock camp features such as rested-XP tents, buffs, a reagent vendor bot or a repair bot that everyone at the camp can use.", topic = "basics" }
add{ q = { "how many quests can i have", "quest log full", "abandon quest", "track quest", "quest limit", "how many quests", "track quests", "max quests", "my quest log is full what do i do", "how many quests can i have in my log" }, a = "The quest log (L) has a fixed number of slots. When it's full, Abandon low-value or gray quests. You can Track or Untrack quests to choose which ones show on screen, and the minimap points toward objectives. Exclamation marks mean a quest is available, question marks mean it's ready to turn in.", topic = "basics" }
add{ q = { "how do i tame a pet", "how to tame beast hunter", "tame beast not working", "why cant i tame this", "hunter cant tame", "how to tame", "tame beast how", "how do hunters tame pets", "cant tame this beast why", "where do i learn tame beast", "it says i cant tame that", "just hit 10 how do i tame my first pet", "how do i tame a pet on my huntr", "im a new hunter and the game says i cant tame this mob what am i doing wrong", "tame pet huntr" }, a = "Tame Beast comes from the level 10 hunter taming quests (three tames with the Taming Rod, then Training the Beast). It fails if:\n1. The beast is higher level than you (you can only tame your level or lower).\n2. You already have a pet, even a dismissed one. Stable or abandon it first.\n3. A dead pet sits in your stable. Revive it first.\n4. The beast takes damage or loses aggro on you during the channel, or another player hits it.", class = "HUNTER", topic = "class_howto" }
add{ q = { "tame keeps failing", "pet tame interrupted", "taming beast kills me", "how to tame elite pet", "taming keeps failing", "pet keeps killing me while taming", "how to tame without dying", "tame beast getting interrupted", "tips for taming elites", "every time i try to tame it kills me before it finishes", "taming elite cat how", "trying to tame an elite but it keeps hitting me so hard i die mid channel", "taming keeps getting interupted" }, a = "While channeling Tame Beast your armor drops by 100%, so the beast hits hard. Start at range, clear nearby mobs, and use Aspect of the Monkey. Lay a Freezing Trap or Concussive Shot first to buy time (traps now work in combat). Don't let anything else damage the beast, or the tame breaks.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how do i feed my pet", "feed pet hunter", "pet wont eat", "how to make pet happy", "cant feed pet", "how to feed pet", "feed pet how", "my pet wont eat the food", "pet is unhappy how to fix", "how to keep pet happy", "what food do i give my pet", "my pet keeps refusing food what do i do", "how do i feed my pett", "my pets happiness is dropping and it wont take the food i give it", "feed my pett" }, a = "Cast Feed Pet (learned with Training the Beast at 10), then click a food your pet's family eats. Mouse over the happiness icon on the pet frame to see what it accepts. You can't feed in combat, so feed before pulls. A new tame starts unhappy, so feed it right away.", class = "HUNTER", topic = "class_howto" }
add{ q = { "what does my cat eat", "cat pet food", "what do cats eat hunter", "feed cat pet", "cat diet", "what food for cat pet", "what can my cat eat", "cat pet eats what", "best food for cat pet", "tamed a cat what do i feed it", "what does cat eat hunter", "just tamed a cat in elwynn what food should i carry for it", "wat do cats eat" }, a = "Cats eat Meat and Fish. Cheap options: raw or cooked meat from vendors and fish you catch. Keep a stack of level-appropriate food, because higher-level pets refuse very low-level food.", class = "HUNTER", topic = "class_howto" }
add{ q = { "what does wolf eat", "wolf pet diet", "raptor spider scorpid food", "what do raptors eat", "wolf pet food", "what do wolves eat", "what does spider eat", "what does scorpid eat", "what does raptor pet eat", "tamed a wolf what food does it want", "fox pet diet", "i have a wolf pet now does it only eat meat or other stuff too", "wolf pet eats wat" }, a = "Meat-only families: Wolf, Raptor, Spider, Scorpid, Core Hound and Fox. Hyena is Meat too (some guides add Fruit). Buy meat from a butcher or food vendor and keep a stack in your bags.", class = "HUNTER", topic = "class_howto" }
add{ q = { "what does bear eat", "boar pet food", "pet that eats everything", "easiest pet to feed", "bear pet food", "what does boar eat", "what pet eats anything", "easiest pet to keep fed", "bear diet hunter pet", "which pet eats everything so i dont have to carry food", "boar pet diet", "i hate carrying a bunch of food types which pet will eat anything i give it", "bear pet eats wat" }, a = "Bear and Boar eat everything: Meat, Fish, Bread, Cheese, Fruit and Fungus. That makes them the easiest pets to keep fed, since any vendor food works.", class = "HUNTER", topic = "class_howto" }
add{ q = { "what does bat eat", "gorilla pet food", "what do bats eat", "bat pet food", "what does gorilla eat", "bat diet hunter", "gorilla diet", "tamed a bat what do i feed it", "what do gorillas eat pet", "tamed a bat and it wont eat meat what does it actually like", "gorila food" }, a = "Bats eat Fruit and Fungus. Gorillas eat Bread, Fruit and Fungus. Fruit vendors and mushrooms from the Undercity or Darnassus vendors work well.", class = "HUNTER", topic = "class_howto" }
add{ q = { "wind serpent food", "what does wind serpent eat", "turtle crab pet food", "tallstrider diet", "what do wind serpents eat", "turtle pet food", "what does crab eat", "tallstrider food", "what does tallstrider eat", "tamed a wind serpent what food", "what do turtles eat hunter", "just got a wind serpent what food do i need to feed it", "wind serpant food" }, a = "Wind Serpent: Bread, Cheese, Fish. Turtle: Bread, Fish, Fruit, Fungus (raw fish works). Crab: Bread, Fish, Fruit, Fungus. Tallstrider: Bread, Cheese, Fruit, Fungus.", class = "HUNTER", topic = "class_howto" }
add{ q = { "carrion bird food", "crocolisk diet", "bird of prey owl food", "what does owl eat", "what do carrion birds eat", "crocolisk food", "owl pet food", "bird of prey diet", "what does croc pet eat", "tamed an owl what does it eat", "what food do i give my owl or carrion bird pet", "carion bird food" }, a = "Carrion Bird and Crocolisk eat Meat and Fish. Bird of Prey (the old Owl family) eats Meat; one guide also lists Fish.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet happiness", "what does pet happiness do", "pet unhappy damage", "red pet happiness", "what does happiness do for pet", "pet happiness damage", "how does pet happiness work", "pet is red happiness", "unhappy pet less damage?", "my pet face is red what does that mean", "pet happyness", "does it actually matter if my pet is green or yellow happiness for damage", "pet happy damage" }, a = "Happiness changes your pet's damage: Happy (green) 125%, Content (yellow) 100%, Unhappy (red) 75%. It drops slowly over time, by 50 when you Dismiss Pet, and by a lot when the pet dies. Feed it out of combat to raise it.", class = "HUNTER", topic = "class_howto" }
add{ q = { "why did my pet run away", "pet ran away", "pet left me", "pet abandoned me", "lost my pet", "my pet ran away", "pet abandoned me why", "why did my pet leave", "how do pets run away", "pet gone after unhappy", "logged in and my pet left me what happened", "pet ran off", "came back to my hunter and my pet is just gone did it run away on me", "pet runned away" }, a = "In Classic, a pet only leaves if you keep it unhappy for a long time: low happiness drains loyalty, and at the lowest loyalty it runs off. Feeding it regularly and fighting with it prevents this. Guides haven't confirmed whether Forever keeps the run-away rule (in beta, happiness only dropped on death), so just keep it fed. A missing pet may also be in the stable or dismissed. Try Call Pet, or ask a Stable Master.", class = "HUNTER", src = "classic", topic = "class_howto" }
add{ q = { "pet loyalty", "loyalty levels hunter pet", "how to raise pet loyalty", "best friend loyalty", "how does pet loyalty work", "pet loyalty ranks", "raise loyalty pet", "how to get pet to best friend", "pet rebellious loyalty", "how long until my pet hits best friend loyalty", "pet loyality", "my new pet is rebellious how do i get its loyalty up to best friend", "pet loyalty lvl" }, a = "Loyalty ranks are Rebellious, Unruly, Submissive, Dependable, Faithful and Best Friend. New tames start at Rebellious. Feed the pet and kill mobs with it to raise loyalty. Higher loyalty gives more Training Points, up to 300 for a level 60 Best Friend pet.", class = "HUNTER", topic = "class_howto" }
add{ q = { "negative training points", "pet training points negative", "not enough training points pet", "pet has negative training points", "why are my pet tp negative", "pet tp negative", "cant train pet skills not enough points", "tamed high level pet negative points", "my new pet shows minus training points how do i fix", "negitive training points", "tamed a pet higher than me and now its training points are negative is that bad", "negative tp pet" }, a = "If you tame a high-level beast, it starts at low loyalty and can show negative Training Points. Keep feeding it and fighting with it, and the points come back as loyalty rises. Check the total in the Beast Training window.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how to learn pet skills", "how to teach pet bite", "how do i get claw for my pet", "learn pet abilities", "beast training how to", "how do pets learn abilities", "teach pet new skill", "how to get bite for pet", "pet learn claw", "how does beast training work", "how do i teach my pet higher rank bite", "beast trainin", "how do i get my pet a higher rank of bite or claw do i tame something", "teach pet bite" }, a = "Pet skills are learned from wild beasts:\n1. Stable your main pet.\n2. Tame a beast that knows the skill rank you want.\n3. Use that skill in combat until chat says you learned it.\n4. Check that it appears in Beast Training.\n5. Abandon or stable the temp pet and take your main back.\n6. Open Beast Training and teach the skill (costs Training Points).\nA pet can have up to 4 active abilities.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet trainer what do they teach", "growl from pet trainer", "great stamina natural armor pet", "pet resistances", "what does pet trainer teach", "pet trainer skills", "where to get growl for pet", "great stamina pet", "natural armor pet", "pet resistance skills", "what can i buy from the pet trainer", "what skills can i buy for my pet from the pet trainer in town", "pet traner skills" }, a = "Pet Trainers teach Growl (ranks 1-7, a new rank every 10 levels from 10), Great Stamina (1-10), Natural Armor (1-10), and Arcane/Fire/Frost/Nature/Shadow Resistance (1-4 each). Your pet needs the level and enough Training Points. Everything else (Bite, Claw, Dash, family skills) comes from wild beasts.", class = "HUNTER", topic = "class_howto" }
add{ q = { "reset pet skills", "unlearn pet abilities", "pet trainer reset training points", "how to reset pet skills", "unlearn pet skills", "pet training points reset", "refund pet tp", "reset pet abilities trainer", "i messed up my pet skills how do i reset them", "reset pet trainng", "i put training points in the wrong skills on my pet can i reset them", "reset pet tp" }, a = "Talk to a Pet Trainer and pay a small fee to unlearn your pet's abilities and refund its Training Points. Beta warning: Attack Speed counted as an ability and was wiped by a full reset, so guides advise against a full reset.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet trainer location alliance", "where is pet trainer stormwind", "pet trainer ironforge", "pet trainer darnassus", "alliance pet trainer", "where is the pet trainer alliance", "pet trainer sw", "pet trainer if", "where is pet trainer in darnassus", "where do alliance hunters train pets", "pet trainer stormwind location", "im alliance and need to find the pet trainer in stormwind or ironforge", "pet traner alliance" }, a = "Alliance Pet Trainers: Karrina Mekenda, Stormwind Dwarven District (67.4,36.7); Belia Thundergranite, Ironforge Hall of Arms (70.8,85.6); Silvaria, Darnassus Cenarion Enclave (42.2,8.8); Keldas, Dolanaar (56.8,59.7); Peria Lamenur, Kharanos (46.6,54.0); Claude Erksine, Farstrider Lodge, Loch Modan (82.2,62.8); Bolyun and Caelyb in Ashenvale; Nalesette Wildbringer, Felwood; Quel'dora Quickgale, Valanaar, Zephras Isle (59.6,72.6).", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet trainer location horde", "where is pet trainer orgrimmar", "pet trainer thunder bluff", "horde pet trainer", "horde pet trainer location", "where is the pet trainer horde", "pet trainer org", "pet trainer tb", "pet trainer undercity", "where do horde hunters train pets", "pet trainer orgrimmar location", "im horde where is the pet trainer in orgrimmar or thunder bluff", "pet traner horde" }, a = "Horde Pet Trainers: Xao'tsu, Orgrimmar Valley of Honor (66.4,15.3); Hesuwa Thunderhorn, Thunder Bluff Hunter's Rise (54.5,83.4); Harruk, Razor Hill (52.0,43.6); Reban Freerunner, Bloodhoof Village (46.8,59.7); Zudd, Grom'gol (31.2,28.8); Grokar, Stonard (47.2,53.0); Quel'dora Quickgale, Valanaar, Zephras Isle.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how many pets can i have", "stable slots hunter", "how to stable pet", "buy stable slot", "how many pets can hunter have", "stable slots", "how to use stable master", "how to store pet", "buy more stable slots", "can i keep more than one pet", "how do i stable my pet", "want to keep a second pet for pvp how many stable slots can i have", "stable slot how" }, a = "You can own 3 pets: one active and two in the stable. Buy the two extra stable slots from any Stable Master, and swap pets at any friendly one. Keep a slot free before going out to tame something new.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how does pet level up", "pet not getting xp", "pet stuck level", "pet behind my level", "pet not leveling", "pet xp", "how do pets get xp", "my pet is lower level than me", "pet stuck behind my level", "why is my pet not getting any experience", "pet not leveling up why", "my pet is like 3 levels below me and not catching up how does pet xp work", "pet xp not working" }, a = "Pets get 25% of the XP you earn from green-or-higher mobs. They get no quest XP and no rested XP. A pet stops at your level until you ding. To catch up a low pet, grind mobs instead of just questing.", class = "HUNTER", topic = "class_howto" }
add{ q = { "do pets scale with gear", "pet stats forever", "pet attack power hunter", "why my buffs dont affect pet", "do pets get stronger with my gear", "does my ap affect pet", "pet scaling forever", "do my buffs work on pet", "pet stats scale with hunter", "does gear make my pet do more damage", "pet scaleing", "if i get more attack power does my pet hit harder in forever", "pet scale gear" }, a = "In Forever, pets get 10% of your higher melee or ranged Attack Power and 100% of your crit chance, and they benefit from Expertise. Player buffs (Fortitude, Mark of the Wild, etc.) no longer raise pet stats. Pet health was cut from a bugged 150% to 115% of normal on Nov 10.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet focus", "pet abilities delayed", "pet focus regen forever", "pet focus regen", "pet abilities slow", "what is pet focus", "pet focus forever", "why does my pet not use abilities", "pet skills feel delayed", "pet focuss", "my pet takes forever to use its abilities whats up with focus" }, a = "Pet Focus now regenerates smoothly instead of in chunks. Abilities that need more Focus may wait a moment before they fire. That's normal, not a bug.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet keeps pulling mobs", "pet on stay wandering", "pet aggro extra mobs", "pet pulling extra mobs", "pet wanders on stay", "pet aggro adds", "pet on stay moves", "my pet keeps pulling stuff", "why does my pet keep wandering off and pulling more packs", "pet pulling adds", "i set my pet to stay but it keeps drifting and pulling extra packs", "pet pulls adds" }, a = "Pets on Stay can drift and pull extra packs. Watch your pet's position and stance, keep it on Passive or Assist in groups, and use Move To or Follow before moving through packs. Growl on a pet in dungeons steals tank aggro, so turn it off in groups.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best pet for leveling", "best leveling pet hunter", "what pet should i get first", "best tank pet", "best pet to level with", "what pet should i tame first", "best first pet hunter", "best tank pet hunter", "cat or boar for leveling", "what pet is best for leveling", "good leveling pet", "just hit 10 on my hunter which pet should i tame first for leveling", "best pet lvling" }, a = "Leveling: a Cat for damage, or a Boar for toughness (Charge roots and grabs aggro, and it eats anything). Turtle (Shell Shield) and Bear (Swipe hits 3 targets, eats anything) are tanky alternatives. Damage was normalized within a family in PvE, so any cat is fine for leveling.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best pvp pet", "best hunter pet pvp", "pvp pet forever", "best pet for pvp", "pvp pet hunter", "what pet for pvp", "best pet arena", "best pet for bgs", "which pet should i use for pvp forever", "pvp pett", "going into bgs on my hunter what pet should i be using", "pvp pet huntr" }, a = "PvP: Broken Tooth (1.0 speed cat, lots of spell pushback) or a Wind Serpent (Lightning Breath ignores armor, good vs plate). For premades: Crocolisk Dismember (-25% healing for 6s), Bird of Prey Mine! (3s disarm, 90s CD) and Bat Sonic Blast (30% slower casts for 20s). Spider Web roots, Crab and Hyena slow 50%.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best raid pet", "best dungeon pet hunter", "wolf or cat raid", "best pet for raids", "best pet for dungeons", "raid pet hunter", "cat or wolf for raids", "dungeon pet", "which pet should i bring to raids", "best raid pett", "going into dungeons on my hunter should i use a cat or a wolf", "raid pet huntr" }, a = "Raids and dungeons: a Cat for raw damage, or a Wolf when your group lacks Battle Shout (Furious Howl gives melee AP to party within 15 yards, doesn't stack with Battle Shout). Tallstrider (Dust Cloud, armor reduction) and Carrion Bird (Demoralizing Screech) bring debuffs.", class = "HUNTER", topic = "class_howto" }
add{ q = { "broken tooth", "where is broken tooth", "broken tooth location", "broken tooth respawn", "tame broken tooth", "where to tame broken tooth", "broken tooth spawn", "how to find broken tooth", "broken tooth badlands", "where is the 1.0 speed cat", "brokentooth where", "where exactly does broken tooth spawn in badlands and how often", "brokentooth spawn" }, a = "Broken Tooth is a level 37 rare cat in the Badlands with a 1.0 attack speed. It respawns roughly every 7-8 hours and shares three spawn points: east of Uldaman, south of Angor Fortress, and east of the northernmost butte. Stand near 50,24 and use Eagle Eye to check all three. You must be 37+. Expect competition. The Classic spawn details aren't reconfirmed for Forever.", class = "HUNTER", src = "classic", topic = "class_howto" }
add{ q = { "rare tames", "rare hunter pets", "humar", "echeyakee", "where to tame humar", "rare pets to tame", "where is humar", "where is echeyakee", "rare hunter tames", "best rare pets", "humar the pridelord location", "rare tamable pets", "are there any rare cats or pets worth taming while leveling like humar", "rare tames huntr" }, a = "Humar the Pridelord is a level 23 rare elite cat that roams The Barrens. Echeyakee, a white lion, is summoned by the Horde quest Echeyakee: use the Horn of Echeyakee at its lair northeast of the Crossroads, then tame it instead of killing it. A rare isn't automatically stronger than a normal pet of the same family.", class = "HUNTER", topic = "class_howto" }
add{ q = { "bite 4 where", "where to learn bite rank 4", "claw 4 pet", "pet skills level 24", "where to get bite 4", "bite rank 4 where", "claw rank 4 where", "pet skills at 24", "level 24 pet abilities", "what pet to tame for bite 4", "bite 4 tame", "my pet is 24 what beast do i tame to learn bite 4", "bite rank 4" }, a = "Level 24 is the first big pet breakpoint (Bite 4, Claw 4, Charge 3, Furious Howl 2). Bite 4: Black Ravager or Mastiff (Duskwood), Giant Moss Creeper (Hillsbrad), Leech Widow or Giant Wetlands Crocolisk (Wetlands). Claw 4: Elder Ashenvale Bear (Ashenvale), Barbed Crustacean (BFD). Charge 3: Bellygrub (Redridge, 24). Furious Howl 2: Black Ravager Mastiff, Ghostpaw Alpha (Ashenvale).", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet skill ranks by level", "when does pet get new bite", "pet ability breakpoints", "when does pet get new skills", "pet skill ranks levels", "pet ability ranks", "when can pet learn bite 3", "pet skills by level", "what levels does my pet get new ranks", "pet skill levels", "at what levels can my pet learn the next rank of bite and claw", "pet ranks lvl" }, a = "Pet skill breakpoints: 16 Bite/Claw 3. 24 Bite/Claw 4, Charge 3, family skill rank 2. 30 Prowl 1, Dash 1, Dive 1, Thunderstomp 1. 32 Bite/Claw 5. 36 Charge 4. 40 Bite/Claw 6, Dash/Dive 2. 48 Bite/Claw 7, Charge 5. 56 Bite/Claw 8. 60 Growl 7, Great Stamina and Natural Armor 10.", class = "HUNTER", topic = "class_howto" }
add{ q = { "where to get dash for pet", "dive for pet", "dash 1 pet tame", "dash pet where", "dive pet where", "where to learn dash for pet", "what to tame for dash", "pet dash rank 1", "where to tame for dive", "what beast do i need to tame to teach my pet dash or dive", "dash for pett" }, a = "Dash 1: Stranglethorn Tiger (32-33, Stranglethorn). Dive 1: Young Mesa Buzzard (31-32, Arathi) or Kraul Bat (30-31, RFK). Dash 2 and Bite 6: Longtooth Runner, Feralas (40-41). Dive 2: Vale Screecher, Feralas (41-43). Dash 3: Vilebranch Raiding Wolf, Hinterlands (50-51).", class = "HUNTER", topic = "class_howto" }
add{ q = { "bite 7 where", "bite 8 pet", "claw 8 winterspring", "max rank bite pet", "where to get bite 7", "bite 8 where", "claw 8 where", "max bite for pet", "highest rank bite", "where do i get max rank bite and claw for my pet", "bite 8 tame", "im 60 where do i tame something to get my pet max rank bite", "bite 8 wher" }, a = "Bite 7: Rekk'tilac (48, Searing Gorge) or Vilebranch Raiding Wolf (50-51, Hinterlands). Claw 7: Ironfur Patriarch (48-49, Feralas) or Ironbeak Hunter (Felwood). Claw 8: Elder Shardtooth or Winterspring Screecher (57-59, Winterspring). Bite 8 and Furious Howl 4: Bloodaxe Worg (56-57, Blackrock Spire). These are from Petopia lists, not tested in the launch client.", class = "HUNTER", topic = "class_howto" }
add{ q = { "fox pet", "new hunter pet families", "what pet families are new", "tricksters dance", "new pet families forever", "fox pet hunter", "what is tricksters dance", "can you tame foxes", "fox pet ability", "what new pets can hunters tame", "what new hunter pet families did forever add like the fox", "new pet familys" }, a = "Fox is a new family (Meat diet) with Trickster's Dance (more dodge and attack speed for 12s, from pet level 20). Several old families got new unique skills: Bear Swipe, Crab Pinch, Crocolisk Dismember, Hyena Tendon Rip, Raptor Savage Rend, Spider Web, Tallstrider Dust Cloud, Bat Sonic Blast, Bird of Prey Mine! (Owl renamed). There are 19 families.", class = "HUNTER", topic = "class_howto" }
add{ q = { "core hound pet", "lava breath pet", "can you tame core hound", "can hunters tame core hounds", "lava breath core hound", "core hound tame", "where to tame core hound", "core hound pet ability", "can i actually tame a core hound in forever and does it keep lava breath", "core hound tamable" }, a = "Core Hounds are tameable and keep Lava Breath (hits 2 nearby enemies with Fire and slows casting 25% for 10s). The pet learns it at level 48. Guides suggest them against casters. Their diet is Meat.", class = "HUNTER", topic = "class_howto" }
add{ q = { "do hunters need ammo", "ammo forever", "does forever have arrows", "hunter ammo still", "do i need ammo", "do hunters still use arrows", "ammo in forever", "does forever have ammo", "hunter bullets", "do hunters still need to buy ammo in forever", "amo forever", "coming from retail do hunters in forever still have to buy arrows", "do hunters need amo" }, a = "Yes, Forever still uses ammo. Arrows go in bows and crossbows, bullets in guns. Running out stops Auto Shot and your shots, so restock at every vendor and carry pet food too. Engineers can craft bullets and scopes.", class = "HUNTER", topic = "class_howto" }
add{ q = { "quiver", "ammo pouch", "do i need a quiver", "quiver bag slot", "where to put arrows", "quiver forever", "what is ammo pouch", "where to put ammo", "quiver bag", "quiver or ammo pouch", "do hunters need quivers", "where do i put my arrows do i need to buy a quiver", "quiver slot" }, a = "A quiver (arrows) or ammo pouch (bullets) takes one of your bag slots and holds only that ammo. In Classic, quivers and pouches also give ranged attack speed; guides haven't confirmed that bonus for Forever. Ammo, a quiver and pet food together fill bags fast, so plan your bag space.", class = "HUNTER", src = "classic", topic = "class_howto" }
add{ q = { "auto shot not firing", "hunter shot not working moving", "why wont my hunter shoot", "auto shot not working", "why wont my auto shot fire", "auto shot stops when moving", "hunter not shooting", "auto shot delay forever", "my hunter stops shooting when i move", "autoshot not firing", "my auto shot keeps stopping whenever i strafe is that a forever thing", "auto shot not fireing" }, a = "In Forever, Auto Shot (and wands) only fire after you stand still for 0.5 seconds. Stop moving fully before shooting. Also check that you have the right ammo for your weapon (arrows for bows and crossbows, bullets for guns) in the ammo slot, and that you're not inside the 8-yard dead zone.", class = "HUNTER", topic = "class_howto" }
add{ q = { "hunter abilities by level", "when do hunters get feign death", "hunter aspects levels", "when do i get aimed shot", "hunter spells by level", "when do i get feign death", "hunter aspects by level", "when do hunters get aimed shot", "hunter level abilities", "what level does hunter get multishot", "hunter abilitys by level", "at what level does a hunter get feign death and aimed shot", "hunter abilites by level" }, a = "Key hunter levels: 4 Monkey, Serpent Sting. 6 Hunter's Mark, Arcane Shot. 8 Concussive. 10 Hawk and pet taming. 12 Mend Pet. 16 Immolation Trap. 18 Multi-Shot. 20 Cheetah, Freezing Trap, Aimed Shot (baseline). 26 Rapid Fire. 28 Frost Trap. 30 Feign Death, Beast. 34 Explosive Trap. 36 Viper Sting. 40 Pack and Mail. 46 Wild. 60 Tranquilizing Shot.", class = "HUNTER", topic = "class_howto" }
add{ q = { "traps in combat", "can i use traps in combat", "trap cooldown", "traps in combat forever", "can traps be used in combat", "trap cd", "hunter traps forever", "do traps share cooldown", "can i drop freezing trap in combat", "can i drop a freezing trap while im already in combat in forever", "traps in combat?" }, a = "Yes. Forever lets you drop traps in combat, and all traps share a 30-second cooldown. Freezing Trap is your main crowd control, Immolation is single-target damage, and Explosive is AoE.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best hunter weapon leveling", "hunter bow by level", "hunter ranged weapon 30 40 50", "hunter gun upgrade", "best hunter weapon", "hunter bow upgrades", "hunter weapons by level", "best gun for hunter leveling", "hunter ranged upgrade", "what bow should i use at 30", "hunter weapon upgrades", "what bow or gun should my hunter be using around level 30 or 40", "best hunter wepon" }, a = "Ranged upgrades: 13 Barbaric Crossbow (RFC) or Calibrated Blunderbuss (Hall of Thanes, Alliance). 19 Venomstrike (WC). 22-23 Naga Heartpiercer or Fallenroot Longbow (BFD). 29 Quilboar Blaster (RFK quest). 30 Master Hunter's Bow (Big Game Hunter quest). 34 Spellsever Crossbow (SM Library). 35 Frosty Blunderbuss (Drowned City). 42 Galgann's Fireblaster (Uldaman) or Arch of the Covenant (ZF). 48 Megashot Rifle (Maraudon). 54 Blackcrow (LBRS). 56 Carapace Spine Crossbow (Strat). 58 Deep Jungle Rifle (Shaper's Terrace).", class = "HUNTER", topic = "class_howto" }
add{ q = { "hunter running out of mana", "hunter mana regen", "hunter oom", "hunter mana", "hunter keeps running out of mana", "how to regen mana hunter", "hunter mana problems", "my hunter is always oom what do i do", "hunter mana regen tips", "my hunter keeps running out of mana while leveling what should i do", "hunter oom alot" }, a = "Hunters still use mana. Carry water and a few mana potions, and keep enough for Feign Death and crowd control. Spirit helps, as do Bestial Discipline (BM, 50% regen while casting), Rapid Recuperation (MM, after Serpent Sting or Rapid Killing) and Resourcefulness (after crits). The Alchemy camp buff adds regen.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pet macro hunter", "one button mend revive call pet", "hunter macros forever", "hunter pet macro", "macro for revive pet", "mend pet macro", "one button pet macro", "hunter macro forever", "how do i make a macro for call revive and mend pet", "pet macros", "can i make one macro that calls revives and mends my pet", "hunter pet macro forever" }, a = "A common macro uses one button for pet upkeep: Revive Pet if it's dead, Call Pet if it's dismissed, Mend Pet otherwise. Add a mouseover Pet Attack macro so your pet hits whatever you hover. Huntwell Forever also adds an ammo counter and auto-refills your quiver.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how do i get soul shards", "soul shards how", "farm soul shards", "drain soul shard", "how to get soul shards", "soul shard farming", "how does drain soul work", "where do i get shards", "lock shards how", "how do i get more soul shards on my warlock", "soul shareds", "i have no soul shards on my warlock how do i get more", "soul shard how" }, a = "Use Drain Soul (rank 1 is fine) on a mob that's about to die. A kill during the channel always gives a Soul Shard. In Forever each Drain Soul tick also has a growing chance to give a shard, which rises until it's guaranteed. The mob must give XP or honor. Start the channel when the target is nearly dead.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "how many soul shards should i keep", "soul shard bag", "shards taking bag space", "soul pouch", "how many shards to keep", "soul shard bag space", "shards filling my bags", "how many soul shards do i need", "my shards are taking all my bag space help", "soul shard bags", "my bags are full of soul shards how many should i actually keep", "soul shard bagg" }, a = "Keep 2-3 spare shards while leveling, more before dungeons (Healthstones, Soulstone, summons). Your Soul Shard bag can go in the reagent bag slot so shards don't fill normal bags. The Succubus/Incubus quest at 20 rewards a Small Soul Pouch, and the Felhunter quest at 30 a Box of Souls.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "what uses soul shards", "soul shard uses", "what do i need shards for", "what are soul shards for", "what do soul shards do", "shard uses warlock", "what costs a soul shard", "what spells need soul shards", "why do i need shards", "what spells on my warlock actually use up soul shards", "soul shard use" }, a = "Soul Shards pay for summoning the Voidwalker, Succubus/Incubus and Felhunter, Create Healthstone, Create Soulstone, Soul Fire, Shadowburn and Ritual of Summoning. The Imp is free. Shadowburn refunds its shard if the target dies (with Shadow and Flame), and Decimation makes Soul Fire free below 35% target health.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "healthstone", "how to make healthstone", "healthstone cooldown potion", "healthstone warlock", "healthstone cd", "does healthstone share cd with potion", "create healthstone level", "lock healthstone", "how do i make healthstones and does it share cooldown with potions", "healtstone" }, a = "Create Healthstone is trained at level 10 and costs a Soul Shard. It's an instant heal on its own cooldown, separate from potions, so use both in an emergency. Make one for yourself and hand them out before dungeons. Forever removed the Improved Healthstone talent.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "soulstone", "how to soulstone", "soulstone resurrection", "what does soulstone do", "how to use soulstone", "soulstone level", "create soulstone", "soulstone res", "who should i soulstone", "soulstone how", "what does soulstone do and who should i put it on in a group", "soul stone" }, a = "Create Soulstone is trained at level 18 and costs a Soul Shard. Use the stone on a friendly player (usually the healer or yourself) before a risky pull. If they die, they can resurrect themselves on the spot.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "ritual of summoning", "how to summon players warlock", "summoning stone forever", "meeting stone summon", "how to summon people warlock", "ritual of summoning level", "lock summon", "summon players", "meeting stone summon forever", "how do i summon my group as a lock", "ritual of sumoning", "my group wants a summon how do i summon players as a warlock", "ritual of summon" }, a = "Ritual of Summoning is trained at level 20 and needs a Soul Shard plus two other players to click the portal. Meeting Stones no longer summon players in Forever, so a warlock is the way to pull people to a dungeon.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "which demon should i use", "best warlock pet by level", "imp or voidwalker", "when to use succubus", "which demon to use", "best warlock pet", "imp or void", "when to use felhunter", "best lock pet leveling", "what demon should i use for leveling", "best demon by level", "which demon should i be using while leveling my warlock", "best demon lock" }, a = "Imp (1): ranged damage, Blood Pact Stamina, mostly for groups after 10. Voidwalker (10): tank, Sacrifice shield, best solo until 20. Succubus/Incubus (20): highest damage, Seduce holds a humanoid up to 15s; most builds switch here. Felhunter (30): Spell Lock and Devour Magic, best for PvP. Inferno (50) and Ritual of Doom (60) aren't needed to level.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "voidwalker quest", "how to get voidwalker", "summon voidwalker quest", "gakins summons", "how do i get voidwalker", "voidwalker quest where", "voidwalker quest horde", "voidwalker quest alliance", "lock 10 quest", "just hit 10 on my lock where is the voidwalker quest", "voidwaker quest", "just hit 10 on my warlock where do i get the voidwalker quest", "voidwalker how" }, a = "The Voidwalker is a level 10 quest. Human: Gakin's Summons (Goldshire). Gnome: The Slaughtered Lamb (Ironforge). Orc/Troll: Gan'rul's Summons (Razor Hill). Undead: Halgar's Summons (Brill). Horde can use the Orgrimmar or Undercity version, and the Undercity one is easier.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "succubus quest", "incubus quest", "how to get succubus", "devourer of souls quest", "what is love quest", "how do i get succubus", "how to get incubus", "succubus quest where", "incubus quest where", "lock 20 demon quest", "hit 20 on my lock how do i get succubus or incubus", "succubis quest", "just hit 20 on my lock how do i get the succubus or incubus quest", "succubus how" }, a = "At 20 you choose Succubus or Incubus. Succubus: Devourer of Souls (Stormwind, Orgrimmar or Undercity). Incubus: What Is Love? (Stormwind), Love Hurts (Orgrimmar) or Hearts of the Lovers (Undercity). The Horde Succubus chain is 8 quests across the Barrens and Stonetalon. Both rewards include a Small Soul Pouch.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "felhunter quest", "seeking strahad", "how to get felhunter", "how do i get felhunter", "felhunter quest where", "seeking strahad quest", "lock 30 quest", "felhunter level", "hit 30 on my lock how do i get felhunter", "felhuter quest", "just hit 30 on my lock where do i get the felhunter quest", "felhunter how" }, a = "The Felhunter is a level 30 quest, Seeking Strahad, from your warlock trainer (Stormwind, Orgrimmar or Undercity). It leads to Strahad Farsan in The Barrens (Ratchet) and rewards Summon Felhunter plus a Box of Souls.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "how to summon demon", "summon demon reagent", "need soul shard to summon", "summoning demon cost", "do demons cost shards", "summon pet warlock", "why cant i summon voidwalker", "do i need a soul shard to summon my demon", "summon demon shard", "why cant i summon my voidwalker do i need a soul shard every time", "summon demon how" }, a = "Every demon except the Imp costs one Soul Shard per summon, so resummoning after a death costs a shard. Summoning a demon is a long cast, so do it out of combat. Train new demon spells from the demon trainer (grimoires are now folded into training).", class = "WARLOCK", topic = "class_howto" }
add{ q = { "demon trainer location", "where to buy grimoire", "warlock pet trainer", "where to buy grimoires", "demon trainer", "warlock pet trainer location", "where to train my imp", "grimoire vendor", "where do i buy demon spells", "demon trainer where", "where do i buy new spells for my imp and voidwalker", "grimoire where" }, a = "Demon trainers: Alliance: Spackle Thornberry (Stormwind Mage Quarter, 39.8,84.6), Jubahl Corpseseeker (Ironforge Forlorn Cavern, 53.2,7.6), Cylina Darkheart (Goldshire), Dannie Fizzwizzle (Kharanos). Horde: Kurgul (Orgrimmar Cleft of Shadow, 47.8,47.3), Martha Strain (Undercity Magic Quarter, 85.8,15.8), Kitha (Razor Hill), Gina Lang (Brill). Starter-zone ones teach only Imp and Voidwalker skills.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "felsteed", "warlock mount 40", "summon felsteed quest", "how do warlocks get mount", "how do i get felsteed", "warlock mount", "lock mount 40", "felsteed quest", "free warlock mount", "hit 40 on my lock how do i get my mount", "felsteed how", "just hit 40 on my warlock how do i get the free felsteed", "felsteed quest wher" }, a = "Summon Felsteed is a free two-step quest at level 40 from your warlock trainer, ending with Strahad Farsan in The Barrens. You still need Apprentice Riding (trained at 40). The Felsteed makes travel between quest hubs much faster.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "dreadsteed", "warlock epic mount", "dreadsteed quest start", "how do i get dreadsteed", "dreadsteed quest", "lock epic mount", "where does dreadsteed quest start", "warlock 60 mount", "how do i start the dreadsteed quest chain", "dreadsteed how", "im 60 on my lock where does the dreadsteed epic mount quest start", "dreadsteed quest wher" }, a = "The Dreadsteed (60) starts with Mor'zul Bloodbringer at the Altar of Storms, Burning Steppes. It sends you across most level 60 zones for materials, through Scholomance, and ends with a 5-player ritual in Dire Maul West. Forever needs 3 Arcanite Bars instead of 1.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "infernal stone", "ritual of doom reagent", "inferno reagent", "demonic figurine", "infernal stone where", "ritual of doom", "inferno spell reagent", "where to get demonic figurine", "inferno warlock", "what reagent does inferno need", "infernal stones", "where do i get infernal stones and demonic figurines for my lock spells", "infernal stone wher" }, a = "Inferno (from Niby the Almighty, Felwood) and Ritual of Doom (from Daio the Decrepit, Blasted Lands) are 50-60 quests. In Classic, Inferno uses an Infernal Stone and Ritual of Doom a Demonic Figurine, both sold by reagent vendors. The Reagent Economy Legacy node removes vendor reagent costs.", class = "WARLOCK", src = "classic", topic = "class_howto" }
add{ q = { "firestone spellstone", "warlock weapon stone", "firestone forever off hand", "firestone", "spellstone", "warlock firestone forever", "spellstone forever", "lock weapon imbue", "do firestone and spellstone go on weapon now", "firestone how", "how do firestone and spellstone work in forever do they go on my weapon", "fire stone forever" }, a = "Create Firestone (28) and Create Spellstone (36) now make weapon imbues, not off-hand items. They stack with Wizard Oil. Firestone gives Fire damage and crit (Destruction). Spellstone gives Shadow damage and spell haste (Affliction and Demonology).", class = "WARLOCK", topic = "class_howto" }
add{ q = { "life tap", "warlock mana", "how does life tap work", "warlock out of mana", "lock mana", "warlock oom", "life tap forever", "does life tap scale with spirit", "my lock keeps running out of mana", "lifetap", "my warlock keeps going oom how should i use life tap", "life tap how" }, a = "Life Tap (6) turns health into mana and scales with Spirit in Forever. Max rank gives 424 mana plus 1 per Spirit (1.2 with Improved Life Tap) and costs 20 + Spirit in health. Refill health with Drain Life, Siphon Life or bandages. Rule: lots of health means Life Tap, lots of mana means Drain Life. Don't wand at full mana.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "warlock abilities by level", "when do warlocks get fear", "death coil level", "howl of terror level", "warlock spells by level", "when do i get fear", "death coil lvl", "howl of terror lvl", "lock abilities by level", "what level does warlock get fear", "warlock abilitys by level", "at what level does a warlock get fear and death coil", "lock abilites by level" }, a = "Warlock key levels: 1 Imp (quest). 6 Life Tap. 8 Fear. 10 Voidwalker (quest), Healthstone. 12 Health Funnel. 14 Drain Life. 16 Unending Breath. 18 Soulstone. 20 Succubus/Incubus (quest), Ritual of Summoning. 22 Eye of Kilrogg. 26 Detect Invisibility. 28 Firestone. 30 Felhunter (quest). 36 Spellstone. 40 Felsteed, Howl of Terror. 42 Death Coil. 60 Dreadsteed.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "demon move to", "pet stay warlock", "demonic sacrifice forever", "how to make demon stay", "demon move to command", "warlock pet commands forever", "how do i make my demon stay in one spot theres no stay button", "demon stay", "my voidwalker wont stay put where is the stay command", "lock pet commands", "how do i park my demon somewhere" }, a = "Move To replaces Stay for demons. Boss AoE does half damage to demons, but keep them out of mechanics anyway. Demonic Sacrifice now lasts 2 hours: Imp gives Shadow damage, Voidwalker mana, Succubus/Incubus Fire damage, Felhunter health. With Demonic Pact you can summon another demon without losing it.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "best warlock weapon leveling", "warlock wand by level", "warlock staff 20 30 40 50", "best warlock weapon", "warlock wand upgrades", "lock staff by level", "warlock weapons by level", "best wand for lock", "what wand should my lock use at 30", "warlock weapon upgrades", "what wand or staff should my warlock use around level 30", "best lock wepon" }, a = "Warlock upgrades: 5 Lesser Magic Wand, 13 Greater Magic Wand (Enchanting). 18+ Gravestone Scepter (BFD quest, Horde). 20 Staff or Orb of Soran'ruk (class quest, Doan Karhan, Barrens). 22+ Staff of the Shade (RFK rare drop). 26 Dancing Flame (Horde quest). 39 White Obsidian Wand. 43 Peacekeeper Wand. 51 Wand of Biting Cold (quest).", class = "WARLOCK", topic = "class_howto" }
add{ q = { "conjure water", "how do mages make water", "conjure food level", "mage food water", "mage water", "how do mages make food", "conjure food lvl", "mage conjure", "when does mage get conjure water", "conjur water", "what level do mages get conjure water and food", "mage water how" }, a = "Conjure Water is trained at 4 and Conjure Food at 6, and neither needs a reagent. New ranks come about every 10 levels; in Classic water ranks are 4/10/20/30/40/50/60 and food 6/12/22/32/42/52. Make a stack before you leave town, drink between pulls, and trade extras to your group.", class = "MAGE", topic = "class_howto" }
add{ q = { "mana gem", "conjure mana agate", "mana ruby", "mage mana stone", "mana agate", "mage mana gem level", "conjure mana gem", "mana ruby level", "when do mages get mana gems", "mana jem", "at what level can my mage make a mana gem", "mana gem lvl" }, a = "Conjure Mana Agate is trained at 28. Higher gems follow in Classic: Jade 38, Citrine 48, Ruby 58. A gem restores a burst of mana and usually has one charge, so save it for long fights. In Classic you can carry one of each gem.", class = "MAGE", src = "classic", topic = "class_howto" }
add{ q = { "mage portal level", "when do mages get portals", "mage teleport level", "how to learn teleport", "when do mages get teleports", "mage portal lvl", "mage teleport lvl", "when do i get portals", "what level can mages make portals", "mage portals", "at what level can my mage learn teleports and portals", "mage portal level?" }, a = "Teleports start at 20 (two capitals) and the third capital at 30. Group Portals come at 40 and 50. Teleport: Dalaran (50) is for Human, Gnome and High Order Skyborne mages. Learn them from the portal trainers in the capitals. Teleports use a Rune of Teleportation, portals a Rune of Portals.", class = "MAGE", topic = "class_howto" }
add{ q = { "portal trainer", "where to learn portals", "mage teleport trainer location", "portal trainer location", "where to learn mage portals", "teleport trainer", "where to learn teleports", "portal trainer alliance", "portal trainer horde", "where do mages learn portals", "where do i go to learn portals and teleports on my mage", "portal traner" }, a = "Portal trainers: Alliance: Larimaine Purdue (Stormwind Mage Quarter, 50.3,86.0), Milstaff Stormeye (Ironforge Mystic Ward, 26.0,8.6), Elissa Dumas (Darnassus Temple of the Moon, 40.6,82.0). Horde: Thuul (Orgrimmar Valley of Spirits, 38.6,85.8), Birgitte Cranston (Thunder Bluff Spirit Rise, 22.4,16.4), Lexington Mortaim (Undercity Magic Quarter, 84.6,16.8).", class = "MAGE", topic = "class_howto" }
add{ q = { "mage trainer location", "where is mage trainer", "mage trainer alliance horde", "mage trainer dalaran", "mage trainer where", "where is the mage trainer", "mage trainer locations", "mage trainer stormwind", "mage trainer orgrimmar", "where do mages train", "mage traner location", "where is the closest mage trainer in my capital city", "mage traner" }, a = "Alliance mage trainers: Northshire, Goldshire, Stormwind Mage Quarter, Coldridge, Kharanos, Ironforge Mystic Ward, Dalaran (Violet Gate), and Zephras Isle (Thendal, Shen'dar, Valanaar). There are none in Kalimdor. Horde: Valley of Trials, Sen'jin, Orgrimmar Valley of Spirits, Thunder Bluff Spirit Rise, Deathknell, Brill, Undercity Magic Quarter. Jessa Weaver in Dalaran (17.7,69.5) also trains Horde for now.", class = "MAGE", topic = "class_howto" }
add{ q = { "mage reagents", "arcane powder", "rune of teleportation where", "what reagents do mages need", "what is arcane powder", "where to buy runes of teleportation", "mage reagent vendor", "reagents for mage", "what reagents do mages use", "mage reagants", "what reagents do i need to buy as a mage for teleports and portals", "mage reagent how" }, a = "Mage reagents: Rune of Teleportation (teleports), Rune of Portals (portals) and Arcane Powder (Arcane Brilliance). In Classic Slow Fall also uses a Light Feather. Buy them from reagent vendors in any capital. The Legacy node Reagent Economy removes the need for vendor reagents.", class = "MAGE", topic = "class_howto" }
add{ q = { "comprehension mage", "mage turned into sheep", "comprehend scroll", "mage scroll skill", "how to read scrolls mage", "i turned into a sheep", "what is comprehension skill", "my mage got sheeped by a scroll", "comprehenshion", "my mage read a scroll and turned into a sheep what is comprehension", "comprehend scrol" }, a = "Comprehension is a mage-only skill learned at 6. Use Comprehend Scroll (General tab of your spellbook) on scrolls that mobs drop. If your skill is too low you can fail and turn into a sheep, so read easy scrolls first. Rewards include Frog Familiar, Scroll of Confuse Beast and weapon imbues.", class = "MAGE", topic = "class_howto" }
add{ q = { "mage abilities by level", "when do mages get blink", "polymorph level", "frost nova level", "counterspell level", "mage spells by level", "polymorph lvl", "frost nova lvl", "counterspell lvl", "what level does mage get blink", "at what level does a mage get blink and polymorph", "mage abilites by level" }, a = "Mage key levels: 4 Frostbolt, Conjure Water. 6 Fire Blast, Conjure Food, Comprehension. 8 Arcane Missiles, Polymorph. 10 Frost Nova. 14 Arcane Explosion. 16 Flamestrike. 20 Blizzard, Blink, Evocation, Mana Shield, Teleports. 22 Scorch. 24 Counterspell. 28 Mana Agate. 30 Ice Armor. 34 Mage Armor. 40 Portals, Frostfire Bolt.", class = "MAGE", topic = "class_howto" }
add{ q = { "mage best weapon leveling", "mage staff by level", "mage wand 30", "mage weapon 20 30 40", "best mage weapon", "mage staff upgrades", "mage wand upgrades", "mage weapons by level", "best staff for mage", "what staff should my mage use at 30", "mage weapon upgrades", "what staff or wand should my mage use around level 30", "best mage wepon" }, a = "Mage upgrades: 13 Fang of Magmatus (Hall of Thanes), 17 Emberstone Staff (Deadmines), 18 Staff of Westfall (Alliance quest), 24 Rod of the Sleepwalker (BFD), 26 Raptor's Gaze off-hand, 27 Hydrocane (Gnomeregan), 28 Spine of the Devourer (Dalaran), 30 Swinetusk Shank (RFK) and the class wand (Nether Force, Ragefire or Icefury). Sim lists favor Hypnotic Blade with Orb of the Forgotten Seer at 31-50 and Spirit of Aquementas off-hand in the 50s.", class = "MAGE", topic = "class_howto" }
add{ q = { "mage mana problems", "mage oom leveling", "how to save mana mage", "mage oom", "mage mana", "mage running out of mana", "mage mana regen", "my mage is always oom", "mage mana tips", "my mage keeps running out of mana every pull how do i fix it", "mage oom alot" }, a = "Stop casting for 5+ seconds (wand instead) so Spirit regen kicks in, and drink conjured water between pulls. Mage Armor (34) increases regen from Spirit, Arcane Meditation keeps up to 50% of regen while casting, and Evocation refills mana. Don't overcast Arcane Blast. Always keep enough for Frost Nova and Blink.", class = "MAGE", topic = "class_howto" }
add{ q = { "priest racial spell quest", "how do i get my priest racial", "priest racial 10 20", "priest racial quest", "how do i get priest racial", "priest racial spells", "priest racial lvl 10", "priest racial lvl 20", "where is my priest racial quest", "preist racial quest", "i hit 10 on my priest where is the racial spell quest", "priest racial how" }, a = "At 10 and 20 your priest trainer gives a racial spell quest that ends at a trainer in your capital. Human: Divine Grace, then Feedback. Dwarf: Desperate Prayer, then Chastise. Gnome: Confounding Flash, then Contingency Plan. Night Elf: Starshards, then Elune's Grace. Troll: Hex of Weakness, then Shadowguard. Undead: Touch of Weakness, then Dark Sacrifice.", class = "PRIEST", topic = "class_howto" }
add{ q = { "dark sacrifice", "undead priest racial mana", "contingency plan gnome", "chastise dwarf", "undead priest racial", "contingency plan", "chastise", "gnome priest racial", "what does dark sacrifice do", "dwarf priest racial", "what does my undead priest racial dark sacrifice actually do", "dark sacrafice" }, a = "Dark Sacrifice (Undead, 20) turns some of your health into mana over 15s, scaling with Spirit. Contingency Plan (Gnome, 20) is a 30s ward that shields and HoTs the target below 35% health (5 min CD). Chastise (Dwarf, 20) is a 2s immobilize (2 min CD). Elune's Grace (Night Elf) lasts 15s or 3 missed attacks.", class = "PRIEST", topic = "class_howto" }
add{ q = { "priest reagents", "holy candle", "sacred candle", "prayer of fortitude reagent", "light feather levitate", "light feather", "what reagents do priests need", "levitate reagent", "preist reagents", "what reagents do i need to buy on my priest for fortitude and levitate", "priest reagent how" }, a = "Classic priest reagents: Holy Candle (Prayer of Fortitude rank 1), Sacred Candle (higher Prayer ranks, incl. Prayer of Shadow Protection and Prayer of Spirit) and Light Feather (Levitate). Buy them at reagent vendors. The Legacy node Reagent Economy removes vendor reagents.", class = "PRIEST", src = "classic", topic = "class_howto" }
add{ q = { "priest abilities by level", "when do priests get shadowform", "when do priests get fear ward", "mind control level", "priest spells by level", "mind control lvl", "what level does priest get shadowform", "preist abilities by level", "at what level does a priest get shadowform and fear ward", "priest abilites by level" }, a = "Priest key levels: 6 PW:Shield. 8 Renew, Fade. 10 Mind Blast, Resurrection. 14 Psychic Scream. 16 Heal. 20 Fear Ward, Flash Heal, Holy Fire, Mind Flay, Devouring Plague. 24 Mana Burn. 30 Divine Spirit, Prayer of Healing, Silence, Mind Control. 32 SW:Death. 40 Shadowform, Greater Heal. 48 Prayer of Fortitude.", class = "PRIEST", topic = "class_howto" }
add{ q = { "priest wand leveling", "best priest wand", "priest weapon by level", "priest wands", "priest weapon upgrades", "priest wand by level", "best wand priest leveling", "what wand should my priest use at 30", "preist wand", "what wand should my priest be using around level 30", "best priest wepon" }, a = "Priests level with wands: 5 Lesser Magic Wand, 13 Greater Magic Wand (Enchanting), 15 Sizzle Stick (WC quest), 18+ Gravestone Scepter (BFD quest, Horde), 27 Wand of Eventide (BoE). Others: Elven Wand (Darkshore quest) and Torchlight Wand (Westfall quest) for Alliance, Cinder Wand (Silverpine) for Horde, and Necrotic Wand (30, SM Graveyard rare).", class = "PRIEST", topic = "class_howto" }
add{ q = { "priest mana regen", "spirit tap", "priest oom leveling", "priest oom", "priest mana", "priest running out of mana", "my priest is always oom", "preist mana", "my priest keeps running out of mana every pull how do i fix it", "priest oom alot" }, a = "Wand once your DoTs are up and let the 5-second rule pass so Spirit regen resumes. Spirit Tap gives 50% regen while casting plus 100% more Spirit for 15s after a kill, and Meditation (buffed in Forever) keeps 50% regen while casting. PW:Shield stops pushback early on.", class = "PRIEST", topic = "class_howto" }
add{ q = { "druid forms levels", "when do druids get cat form", "druid travel form level", "when do i get bear form", "druid forms", "druid travel form lvl", "when do druids get bear form", "druid form levels", "what level does druid get travel form", "druid froms", "at what level does a druid get bear cat and travel form", "druid form lvl" }, a = "Druid forms: Bear at 10 (quest Heeding the Call). Aquatic at 16 (quest). Cat at 20 (quest The Great Cat Spirit, with Claw, Prowl and Rip). Travel at 30 (trainer). Dire Bear at 40 (trainer). Moonkin is the Balance 31-point talent. Other levels: 10 Teleport: Moonglade (quest), Nature's Grasp; 12 Revive; 14 Cure Poison (quest); 20 Shred, Rebirth; 26 Dash; 36 Frenzied Regen; 40 Innervate; 44 Barkskin.", class = "DRUID", topic = "class_howto" }
add{ q = { "druid bear form quest", "heeding the call", "how to get bear form", "heeding the call quest", "bear form quest", "druid lvl 10 quest", "hit 10 on my druid how do i get bear", "bear from quest", "just hit 10 on my druid where do i get the bear form quest", "bear form how" }, a = "Heeding the Call (10) comes from your druid trainer in Darnassus or Thunder Bluff and goes through Moonglade, teaching Bear Form, Growl, Maul and Teleport: Moonglade. High Order Skyborne druids do The Great Ursera Spirit (Strength and Mercy) on Zephras Isle instead.", class = "DRUID", topic = "class_howto" }
add{ q = { "druid reagents", "rebirth reagent", "gift of the wild reagent", "maple seed", "druid rez reagent", "what reagents do druids need", "druid reagants", "what reagents do i need to buy on my druid for rebirth and gift of the wild", "druid reagent how", "rebirth seed", "which seed does rebirth use", "wild berries reagent druid" }, a = "Rebirth uses a seed that depends on its rank; check the tooltip (Classic: Maple, Stranglethorn, Ashwood, Hornbeam, then Ironwood Seed). Gift of the Wild uses Wild Berries, later Wild Thornroot. Buy them from reagent vendors. Reagent Economy (Legacy) removes vendor reagents.", class = "DRUID", topic = "class_howto" }
add{ q = { "can druids use potions in form", "drink potion cat form", "consumables shapeshifted", "can druids drink potions in form", "potions in cat form", "potions in bear form", "consumables in form", "druid potion form forever", "do i have to shift out to use a potion", "potions cat from", "can i drink a potion in cat form without shifting out in forever", "potions in form?" }, a = "Yes. In Forever most potions and consumables, including rage potions and Thistle Tea, work in any form without shifting out. Weapon enchants, sharpening stones and procs also work in form, and your form damage follows your weapon's DPS.", class = "DRUID", topic = "class_howto" }
add{ q = { "druid best weapon leveling", "feral weapon by level", "druid staff 20 30 40", "best druid weapon", "feral weapon upgrades", "druid weapons by level", "best staff for druid", "druid two hander", "what weapon should my feral druid use at 30", "druid weapon upgrades", "what weapon should my feral druid use around level 30", "best druid wepon" }, a = "Feral wants high-DPS two-handers (form damage follows weapon DPS): Smite's Mighty Hammer (Deadmines, 18), Manual Crowd Pummeler (Gnomeregan, 29), Illusionary Rod around 31-40, then Dark Iron Pulverizer and Hammer of the Titans in the sim lists. Polearms are trainable from 20. Balance: Rhahk'Zor's Hammer early, then Swinetusk Shank with Raptor's Gaze, then Skullbreaker with Orb of the Forgotten Seer.", class = "DRUID", topic = "class_howto" }
add{ q = { "druid mana", "druid oom", "shapeshift mana cost", "idol of shifting tides", "shapeshift costs mana", "druid mana problems", "my druid keeps going oom shifting", "druid mana tips", "my druid keeps going oom from shifting what should i do", "druid oom alot" }, a = "Shifting costs mana, so feral druids still need water and a reserve for forms. The Idol of Shifting Tides (Aquatic Form quest, 16) lowers shapeshift cost. Shifting Power (Feral, 40) turns mana into Energy. Use Innervate often, and Resto benefits most from Spirit.", class = "DRUID", topic = "class_howto" }
add{ q = { "shaman totems list", "what totems do i get", "totems by element", "when do i get windfury totem", "shaman totems", "what totems does shaman get", "totem list", "totems by level", "what level does shaman get windfury totem", "shamen totems", "at what level does my shaman get windfury totem and other totems", "totem list shaman" }, a = "Earth (4): Stoneskin, Earthbind (6), Stoneclaw (8), Strength of Earth (10), Tremor (18). Fire (10): Searing, Magma (26), Flametongue (28), Frost Resistance (24). Water (20): Healing Stream, Poison Cleansing (22), Mana Spring (26), Fire Resistance (28), Disease Cleansing. Air (30): Grounding, Nature Resistance, Windfury (32), Windwall, Grace of Air. One totem per element at a time.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "call of the elements", "totem bar", "drop all totems at once", "how to drop all totems", "shaman totem bar forever", "drop all totems one button", "how do i set up the totem bar", "call of the elemnts", "how do i use the totem bar to drop all my totems at once", "totem bar how" }, a = "Call of the Elements (20) unlocks the totem bar. Preset one totem per element, and a 3-second cast drops all four for their combined mana. Call of the Spirits and Call of the Ancestors add a second and third preset set. You can leave an element empty.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "totemic recall", "totemic projection", "move totems", "totem duration forever", "totem duration", "how long do totems last forever", "can i move my totems", "totem recall", "how long do totems last now and can i move them with totemic projection", "totem durration" }, a = "Buff totems now last 5 minutes and totems have a 1.0s GCD. Totemic Recall (20) destroys your totems and refunds 25% of their mana. Totemic Projection (22) moves all your totems up to 30 yards (1 min CD). Right-click a totem on the tracker to remove it.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "shaman reagents", "ankh", "fish oil", "shiny fish scales", "reincarnation reagent", "what reagents do shamans need", "shamen reagents", "what reagents do i need on my shaman for reincarnation and water walking", "shaman reagent how", "ankh for reincarnation", "where to buy ankh", "water walking reagent", "water breathing reagent shaman" }, a = "Shaman reagents: Ankh for Reincarnation (passive, 30), Fish Oil for Water Walking and Shiny Fish Scales for Water Breathing. Buy them from reagent vendors. The Legacy node Reagent Economy removes vendor reagent needs.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "shaman abilities by level", "when do shamans get ghost wolf", "chain lightning level", "purge level", "shaman spells by level", "chain lightning lvl", "purge lvl", "what level does shaman get ghost wolf", "shamen abilities by level", "at what level does a shaman get ghost wolf and chain lightning", "shaman abilites by level" }, a = "Shaman key levels: 1 Rockbiter. 4 Earth Shock, Stoneskin (quest). 8 Lightning Shield. 10 Flame Shock, Flametongue, Searing Totem (quest). 12 Purge, Fire Nova, Ancestral Spirit. 16 Cure Poison. 20 Ghost Wolf, Frost Shock, Frostbrand, Lesser Healing Wave, Call of the Elements. 22 Cure Disease. 30 Reincarnation, Windfury Weapon, Grounding. 32 Chain Lightning, Windfury Totem. 40 Mail.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "weapon imbue duration", "rockbiter flametongue windfury weapon forever", "shaman imbue stack with stone", "shaman imbues forever", "do imbues stack with sharpening stone", "windfury weapon forever", "rockbiter weapon", "flametongue weapon forever", "shaman imbue stone", "do shaman weapon imbues stack with sharpening stones in forever", "weapon imbue stack" }, a = "Shaman weapon imbues (Rockbiter, Flametongue, Frostbrand, Windfury) now last 60 minutes and stack with sharpening stones, weightstones and oils. Since Nov 10 your own imbue and a weapon totem work together. Rockbiter boosts threat, especially with Spirit Weapons.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "shaman best weapon leveling", "enhancement weapon by level", "shaman two hander 20 30 40 50", "best shaman weapon", "enh weapon upgrades", "shaman weapons by level", "best two hander shaman", "shaman 2h leveling", "what weapon should my shaman use at 30", "shaman weapon upgrades", "what two hander should my enh shaman use around level 30", "best shaman wepon" }, a = "Enhancement wants slow two-handers: Smite's Mighty Hammer (Deadmines, 18), Manual Crowd Pummeler (Gnomeregan, 29), then Rage of the Storm from the level 30 Tempest's Weapons quest (+10% Stormstrike). Sim lists suggest Hypnotic Blade or Dawn's Edge with a shield in the 30s-40s and Arcanite Reaper in the 50s. Train Axes, Fist and 2H Maces from weapon trainers.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "shaman mana", "shaman oom", "enhancement mana problem", "enh mana problems", "shaman mana regen", "shaman running out of mana", "my shaman is always oom", "shamen mana", "my shaman keeps running out of mana every pull how do i fix it", "shaman oom alot" }, a = "Only drop the totems that help the fight, since every totem costs mana and a GCD. Use Totemic Projection instead of recasting. Mana Spring (26) and Mana Tide help. Water Shield gives mana on crits, Mindfulness keeps 50% regen while casting, and Improved Stormstrike gives 50% regen for 15s after Stormstrike. Mental Dexterity makes Int worthwhile for Enhancement.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "when do rogues get poisons", "poison levels", "when do i get deadly poison", "wound poison level", "poisons level", "wound poison lvl", "rogue poisons lvl", "what level does rogue get poisons", "rouge poisons", "at what level can my rogue start using poisons", "rogue poison lvl" }, a = "Poisons unlock with the level 20 class quest (you need 80 Lockpicking; guides suggest being 22 for Vanish and Distract). Instant Poison comes first. Crippling 20, Mind-numbing 24, Deadly 30, Wound 32. Learn new recipes and ranks from any rogue trainer.", class = "ROGUE", topic = "class_howto" }
add{ q = { "how to make poisons", "poison skill", "craft poisons rogue", "where to buy poison reagents", "craft poisons", "rogue poison skill", "poison reagents", "where to buy poison mats", "how do i make poisons on my rogue", "rouge poisons craft", "how do i actually make poisons on my rogue in forever", "poison craft how" }, a = "Poisons work like a profession in the Professions tab. Each poison you make gives 1 skill point. The cap is 5x your level (100 at 20, 300 at 60), and high ranks need more skill. Recipes come from rogue trainers, and materials (Deathweed, Essence of Pain, Dust of Deterioration, Essence of Agony, vials) from Shady Dealers or poison vendors.", class = "ROGUE", topic = "class_howto" }
add{ q = { "which poison to use", "best poison leveling", "what poisons main hand off hand", "pvp poisons", "best poisons leveling", "poisons main hand off hand", "best rogue poisons", "what poisons should i use for leveling", "rouge poisons best", "what poisons should i put on my main hand and off hand while leveling", "best poison rogue" }, a = "Leveling: Instant in both hands until 30, then Instant main hand and Deadly off hand. PvP: Crippling to stop kiting, Wound vs healers, Mind-numbing vs casters. In Forever poisons scale with AP, can crit, have more charges, and stack with sharpening stones and Windfury Totem. You can have one per weapon.", class = "ROGUE", topic = "class_howto" }
add{ q = { "flash powder", "blinding powder", "vanish reagent", "blind reagent", "where to buy flash powder", "where do i get blinding powder", "flash powdr", "where do i buy flash powder for vanish and blinding powder for blind", "flash powder where", "vanish powder", "what does blind need", "rogue reagents" }, a = "Vanish uses Flash Powder, bought from reagent vendors or Shady Dealers. Blind uses Blinding Powder. In Classic you craft it with your poison skill from Fadeleaf, and many rogues also buy it. Reagent Economy (Legacy) removes the vendor reagent cost.", class = "ROGUE", src = "classic", topic = "class_howto" }
add{ q = { "how to level lockpicking", "lockpicking guide", "lockpicking 1-100", "where to practice lockpicking alliance", "lockpicking", "lockpicking guide alliance", "where to train lockpicking", "how do i level lockpicking on alliance", "lockpickin", "im alliance rogue how do i level lockpicking from 1 to 100", "lockpicking how alliance" }, a = "Lockpicking is trained at 16, and the cap is 5x your level. Alliance 1-110:\n1. Take Redridge Rendezvous from Renzik the Shiv (Stormwind), then Alther's Mill from Lucius in Redridge.\n2. Pick the practice lockboxes at Alther's Mill to about 80.\n3. Open Lucius's Lockbox to finish.\n4. Pick Waterlogged Footlockers in Lake Everstill (Redridge) to 110.", class = "ROGUE", topic = "class_howto" }
add{ q = { "lockpicking horde", "horde lockpicking guide", "wrenix lockpicking", "lockpicking ratchet", "horde lockpicking", "lockpicking guide horde", "wrenix of ratchet", "how do i level lockpicking on horde", "lock picking horde", "im horde rogue how do i level lockpicking from 1 to 110", "lockpicking how horde" }, a = "Horde 1-110:\n1. Take Wrenix of Ratchet from Zando'zan (Orgrimmar), then Plundering the Plunders (The Barrens).\n2. Use Wrenix's Gizmotronic Apparatus for Thieves' Tools and the E.C.A.C.\n3. Pick boxes on the pirate boat on the Merchant Coast to about 80.\n4. Open the Jewel of the Southsea to summon Polly, use the E.C.A.C to make it normal-level, kill it and loot.\n5. Waterlogged Footlockers on Zoram Strand, Ashenvale, to 110.", class = "ROGUE", topic = "class_howto" }
add{ q = { "lockpicking 110-200", "where to level lockpicking 150", "lockpicking 175", "lockpicking 110", "lockpicking 150", "where to level lockpicking after 110", "lockpicking 150 where", "lock picking 150", "my lockpicking is 110 where do i go to get it to 150 or 200", "lockpicking 110 to 200" }, a = "110-150: Battered Footlockers in Durnholde Keep, Hillsbrad (both factions), Windshear Mine in Stonetalon (Horde), or the murlocs northeast of Menethil (Alliance, 110 skill). 150-200: Angor Fortress, Badlands (Battered upstairs to 175, Dented downstairs to 200); Waterlogged Footlockers underwater at Sar'theris Strand, Desolace (bring water breathing); or Mossy Footlockers at Sunken Temple, Swamp of Sorrows (175-200).", class = "ROGUE", topic = "class_howto" }
add{ q = { "lockpicking 200-300", "lockpicking 250", "max lockpicking", "lockpicking brd doors", "lockpicking 200", "lockpicking 300", "where to level lockpicking past 200", "lock picking 250", "my lockpicking is 200 where do i go to max it out to 300", "lockpicking 200 to 300" }, a = "200-250: Dented Footlockers in The Slag Pits, Searing Gorge (pickpocket mobs for extra boxes), or Azshara/Tanaris footlockers from 225. 250-280: Scarlet Footlockers at Tyr's Hand, Eastern Plaguelands (dangerous elites). 280-300: Blackrock Depths doors: pick the left entrance gate and two easy doors, leave, reset, repeat.", class = "ROGUE", topic = "class_howto" }
add{ q = { "thieves tools", "do i need thieves tools", "where to get thieves tools", "thieves tools rogue", "lockpicking tool", "lost my thieves tools", "theives tools", "do i need thieves tools to pick locks and where do i get them", "thiefs tools" }, a = "Thieves' Tools are reusable and come from the intro lockpicking quest or a Shady Dealer. They aren't used up when you pick a lock. Pick Pocket on mid- to high-level mobs gives lockboxes to practice on, and you can open other players' boxes through the trade window's Will not be Traded slot.", class = "ROGUE", topic = "class_howto" }
add{ q = { "rogue abilities by level", "when do rogues get vanish", "kidney shot level", "blind level rogue", "rogue spells by level", "kidney shot lvl", "blind lvl", "what level does rogue get vanish", "rouge abilities by level", "at what level does a rogue get vanish and kidney shot", "rogue abilites by level" }, a = "Rogue key levels: 4 Pick Pocket, Backstab. 6 Gouge. 8 Evasion. 10 Dual Wield, Sap, Slice and Dice, Sprint. 12 Kick. 14 Expose Armor, Garrote. 16 Feint, Pick Lock. 18 Ambush. 20 Poisons (quest), Rupture. 22 Distract, Vanish. 24 Shank. 26 Cheap Shot. 30 Kidney Shot, Disarm Trap. 34 Blind. 40 Safe Fall.", class = "ROGUE", topic = "class_howto" }
add{ q = { "rogue best weapon leveling", "rogue weapons by level", "rogue daggers 20 30 40 50", "best rogue weapon", "rogue weapon upgrades", "best daggers rogue leveling", "best swords rogue leveling", "what weapon should my rogue use at 30", "rouge weapon upgrades", "what daggers or swords should my rogue use around level 30", "best rogue wepon" }, a = "Rogue upgrades: 16 Buzzer Blade (Deadmines), 18 Butcher's Slicer (SFK), 19 Cruel Barb (VanCleef), 23 Meteor Shard (Arugal), 24 Outlaw Sabre (Horde BFD quest), 30 Bloody Brass Knuckles (SM Graveyard) and Swinetusk Shank (RFK). Sims suggest Mithril Claws or Wicked Mithril Blade at 31-40, Dawn's Edge with Thrash Blade at 41-50, and Persuader in the 50s. Combat can swap weapon types freely with Hack and Slash.", class = "ROGUE", topic = "class_howto" }
add{ q = { "paladin seals", "what seals do paladins have", "which seal to use", "seal of fury", "what seals do paladins get", "which seal should i use", "seal of righteousness", "what seal for leveling pally", "paladin seels", "which seal should i be using on my paladin while leveling", "pally seals" }, a = "Seals last 30s and only buff you. Righteousness: Holy damage per swing (the leveling default, scales with weapon speed). Crusader: faster swings, and its Judgement makes the target take more Holy damage. Fury (new, 10): Holy damage, a small absorb, and its Judgement taunts (the only paladin taunt). Light: your hits heal you. Wisdom (38): hits restore mana. Command (Ret talent): chance for big Holy hits. Justice: Judgement stops fleeing.", class = "PALADIN", topic = "class_howto" }
add{ q = { "how does judgement work", "judgement consumes seal", "paladin judgement forever", "judgement seal", "does judgement use up seal", "judgement forever", "pally judgement", "what does judgement do on paladin", "judgment", "how does judgement work in forever does it use up my seal", "judgement how" }, a = "Judgement (4) releases your active Seal's effect on the target. In Forever it no longer uses up the Seal, so you keep your Seal up and judge on cooldown. Judging Light or Wisdom leaves a debuff that heals or gives mana to anyone hitting the target. Ret's Sanctified Judgement makes Judgement mana-positive.", class = "PALADIN", topic = "class_howto" }
add{ q = { "paladin blessings", "blessing duration forever", "which blessing to use", "blessing of kings", "how long do blessings last", "blessing of might", "what blessing should i put on people", "paladin blessngs", "which blessing should i put on people and how long do they last", "pally blessings" }, a = "Blessings last 1 hour, and you can put one Blessing per paladin on each person. Might (4) gives AP, Wisdom gives mana regen, Kings (20, baseline now) gives 10% stats. Protection (10) and Sacrifice (46) are emergency spells. Salvation and Blessing of Light were removed before launch.", class = "PALADIN", topic = "class_howto" }
add{ q = { "greater blessing", "symbol of kings", "greater blessing reagent", "when do paladins get greater blessings", "greater blessings level", "what reagent for greater blessing", "greater blesing", "when do paladins get greater blessings and what reagent do they need", "greater blessing how", "greater blessing of kings", "how long do greater blessings last", "pally reagent greater blessing" }, a = "Greater Blessings cover everyone of one class for 1 hour. Greater Might 52, Greater Wisdom 54, Greater Kings 60. Each cast uses a Symbol of Kings from a reagent vendor. Divine Intervention uses a Symbol of Divinity. You won't need either while leveling.", class = "PALADIN", topic = "class_howto" }
add{ q = { "paladin auras", "which aura", "devotion retribution concentration aura", "which aura should i use", "devotion aura", "retribution aura", "concentration aura", "what aura for leveling pally", "paladin auras forever", "which aura should my paladin keep up while leveling", "pally auras" }, a = "Auras are set-and-forget. Devotion (1) gives armor, Retribution (16) damages attackers, and Concentration (22) cuts spell pushback. Fire, Frost and Shadow Resistance auras are raid-wide for specific bosses. Pick one that fits the group and leave it on.", class = "PALADIN", topic = "class_howto" }
add{ q = { "paladin abilities by level", "when do paladins get consecration", "hammer of wrath level", "divine shield level", "paladin spells by level", "hammer of wrath lvl", "divine shield lvl", "what level does paladin get bubble", "paldin abilities by level", "at what level does a paladin get consecration and divine shield", "pally abilites by level" }, a = "Paladin key levels: 4 Might, Judgement. 6 Divine Protection, Holy Strike. 8 Hammer of Justice. 10 Seal of Fury, Lay on Hands, BoP, Righteous Fury. 12 Redemption (quest). 16 Retribution Aura. 20 Kings, Consecration, Exorcism. 22 Concentration Aura. 30 Seal of Light, Divine Intervention. 32 Divine Shield. 38 Seal of Wisdom. 40 Warhorse (quest). 42 Cleanse. 44 Hammer of Wrath. 46 Sacrifice.", class = "PALADIN", topic = "class_howto" }
add{ q = { "paladin best weapon leveling", "ret weapon by level", "paladin two hander 20 30 40", "best paladin weapon", "ret weapon upgrades", "paladin weapons by level", "best two hander paladin", "pally 2h leveling", "what weapon should my ret pally use at 30", "paladin weapon upgrades", "what two hander should my ret paladin use around level 30", "best pally wepon" }, a = "Ret wants slow two-handers: Smite's Mighty Hammer (Deadmines, 18), then the level 20 class weapon (Verigan's Fist for Alliance, Wolfsbane for Undead), Morbid Dawn or Corpsemaker (RFK) in the 20s, Mithril Claymore in the 30s, Bleakwood Hew in the 40s, and Arcanite Reaper in the 50s. Prot wants a fast one-hander for more Seal of Fury hits.", class = "PALADIN", topic = "class_howto" }
add{ q = { "paladin mana", "paladin oom", "ret paladin mana regen", "pally mana", "ret pally mana regen", "paladin running out of mana", "my pally is always oom", "paldin mana", "my paladin keeps running out of mana every pull how do i fix it", "pally oom alot" }, a = "Use Judgement and Holy Strike instead of only auto-attacking. Keep Blessing of Wisdom on yourself, judge Seal of Wisdom on long fights, and carry water and mana potions. Ret's Sanctified Judgement refunds mana, Prot gets mana from Redoubt and Improved Seal of Fury, and Holy's Reverence keeps 30% regen while casting. Lay on Hands drains all your mana.", class = "PALADIN", topic = "class_howto" }
add{ q = { "warrior stances", "when do warriors get stances", "which stance to use", "berserker stance level", "which stance should i use", "berserker stance lvl", "defensive stance lvl", "what stance for leveling warrior", "warior stances", "at what level do warriors get defensive and berserker stance", "warrior stance lvl" }, a = "Battle Stance from level 1 (Charge, Overpower, Thunder Clap). Defensive Stance at 10 via a race quest (Taunt, Revenge, Shield Wall). Berserker Stance at 30 via The Islander and The Affray on Fray Island, Barrens (Intercept, Whirlwind, Pummel, Berserker Rage). Level in Battle, tank in Defensive, and use Berserker for Fury damage.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "stance swap lose rage", "tactical mastery", "switching stances rage", "stance swap rage", "do i lose rage switching stance", "stance dancing rage", "tactical mastery forever", "how much rage do i keep when i switch stances", "tactical mastry", "do i lose all my rage when i switch stances on my warrior", "stance swap rage loss" }, a = "Tactical Mastery is now baseline at 14: you keep 10 rage when you swap stances. Improved Tactical Mastery adds 3 per point, up to 25. Plan swaps ahead, for example spend rage before swapping to Overpower.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "how does rage work", "warrior rage generation", "rage from weapon speed", "no rage warrior", "warrior rage", "rage generation", "warrior no rage", "why doesnt my warrior get any rage", "warrior rage gen", "how does warrior rage work in forever with weapon speed", "rage how warrior" }, a = "Rage from your hits now depends on weapon speed, not damage, and crits give 75% more. Rage from taking damage ignores your armor, and absorbs like PW:Shield don't reduce it. Rage decays out of combat, so open fights with Charge and Bloodrage. Victory Rush (20) is free healing after kills.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "do warriors need water", "warrior food", "warrior downtime", "how do warriors heal", "warrior eat or drink", "what should my warrior eat between pulls", "warior food", "does my warrior need water or just food between pulls", "warrior water?", "warrior drink water?", "do warriors drink", "warrior eating between fights" }, a = "Warriors use no mana, so you only need food, never water. Eat between pulls and keep cooked food handy for the Well Fed buff (it also gives an XP buff). Train First Aid for bandages; in Forever First Aid can also make health potions. Victory Rush (20, heals 10% after a kill) cuts downtime.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "warrior abilities by level", "when do warriors get whirlwind", "execute level", "when does warrior get mortal strike", "warrior spells by level", "execute lvl", "mortal strike lvl", "what level does warrior get whirlwind", "warior abilities by level", "at what level does a warrior get whirlwind and execute", "warrior abilites by level" }, a = "Warrior key levels: 4 Rend, Charge. 6 Thunder Clap. 8 Hamstring. 10 Defensive Stance (quest), Taunt, Sunder, Bloodrage. 12 Overpower, Shield Bash. 14 Revenge, Demo Shout, Tactical Mastery. 20 Victory Rush, Cleave, Slam, Retaliation, Dual Wield. 22 Intimidating Shout. 24 Execute. 28 Shield Wall. 30 Berserker Stance (quest), Intercept, Berserker Rage. 36 Whirlwind. 38 Pummel. 40 Plate. 50 Recklessness.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "whirlwind axe quest", "whirlwind axe", "how to get whirlwind axe", "whirlwind weapon steps", "cyclonian", "how do i get whirlwind axe", "whirlwind axe steps", "cyclonian quest", "whirlwind axe forever level", "whirlwind ax quest", "what are the steps for the whirlwind axe quest in forever", "whirlwind axe how" }, a = "Whirlwind weapon chain (level 30 in Forever):\n1. Get Berserker Stance first: The Islander, then The Affray on Fray Island, Barrens.\n2. Go to Bath'rah the Windwatcher in Alterac Mountains.\n3. Collect 8 Liferoot, 30 Bloodscalp Tusks (Stranglethorn trolls) and the Essence of the Exile (from elemental charms in Arathi).\n4. Do the summoning and kill Cyclonian (level 40 elite). Bring help.\n5. Loot the Whirlwind Heart and return it to Bath'rah.\n6. Choose the Whirlwind Axe, Sword or Warhammer.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "warrior best weapon leveling", "warrior 2h by level", "arms weapon 10 20 30", "best two hander leveling", "best warrior weapon", "warrior 2h upgrades", "warrior weapons by level", "best two hander warrior", "arms weapons leveling", "what weapon should my warrior use at 30", "warior weapon upgrades", "what two hander should my arms warrior use around level 30", "best warrior wepon" }, a = "Arms upgrades: 10-11 Coldridge Hammer (Alliance) or Steady Bastard Sword (Horde quest). 16 Ironforge Greathammer or Axe of Orgrimmar (dungeon quests). 18 Smite's Mighty Hammer (Deadmines). 24 Heavehammer (Wetlands dig site quest). 29 Corpsemaker (RFK) or Manual Crowd Pummeler (Gnomeregan). 30-40 Whirlwind Axe. 40s Dark Iron Pulverizer or Enchanted Battlehammer. 50s Arcanite Reaper (Blacksmithing). Slow weapons boost instant attacks.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "fury weapons leveling", "dual wield warrior weapons", "prot warrior weapon shield leveling", "fury weapons", "dual wield warrior", "prot warrior shield", "fury weapons by level", "best one handers fury", "what weapons should i dual wield on fury", "prot warrior weapon leveling", "what weapons should i dual wield as fury or use with a shield as prot", "fury wepons" }, a = "Fury dual wield (from 20): Pronged Reaver (RFK) with Ironspine's Fist (SM) in the 20s, Wicked Mithril Blade and Mithril Claws in the 30s, Dawn's Edge and Thrash Blade in the 40s, Persuader with Annihilator in the 50s. Prot: Windstorm Hammer or Heavy Mithril Axe with Aegis of the Scarlet Commander (SM Cathedral) at 30-50. These come from sim-based lists.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "reagent economy", "legacy no reagents", "do i need reagents forever", "stop buying reagents", "legacy reagents", "do i need reagents", "reagent economy node", "is there a way to not need reagents", "reagent econemy", "is there a legacy node that lets me stop buying class reagents", "legacy reagent node" }, a = "The Legacy node Reagent Economy (Resourcefulness tree, 1 rank) makes class abilities stop needing vendor-bought reagents: no more candles, powders, runes, Symbols, Ankhs or Fish Oil. It also makes tier 1 camping items free to craft. Earned reagents like Soul Shards aren't vendor items, so you still need them.", topic = "class_howto" }
add{ q = { "reagents for every class", "what reagents do i need", "class reagent list", "reagent vendor", "what reagents for each class", "class reagents", "reagent list", "where to buy reagents", "reagent vendor location", "what reagents does my class need", "reagants list", "what reagents does every class need to buy in forever", "reagent list class" }, a = "Mage: Rune of Teleportation, Rune of Portals, Arcane Powder. Priest: Holy and Sacred Candles, Light Feather. Druid: Rebirth seeds, Wild Berries or Thornroot. Paladin: Symbol of Kings, Symbol of Divinity. Shaman: Ankh, Fish Oil, Shiny Fish Scales. Rogue: Flash Powder, Blinding Powder, poison materials. Warlock: Soul Shards (plus Infernal Stone and Demonic Figurine). Hunter: ammo and pet food. Warrior: none. All sold at reagent vendors except shards.", src = "classic", topic = "class_howto" }
add{ q = { "reagent bag", "reagent bag slot", "where to put soul shards", "reagent bag sizes", "where do soul shards go", "reagent bag size", "separate bag for reagents", "where is the reagent bag slot", "reagant bag", "where is the reagent bag slot and what goes in it", "reagent bag slot where" }, a = "Forever adds a separate reagent bag slot next to the micro menu, on top of your four normal bags. Reagent bags include Linen (6), Runecloth (14), Mooncloth (18) and Bottomless (20 slots). Warlocks can put a soul shard bag there.", topic = "class_howto" }
add{ q = { "why is my mana not regenerating", "mana not regen", "mana regen stopped", "why no mana regen in combat", "five second rule", "mana not regenerating", "why is my mana not coming back", "no mana regen in combat", "5 second rule", "why does my mana stop regenerating", "mana not regening", "my mana wont regenerate while im casting whats the five second rule", "mana regen not workin" }, a = "After you spend mana, regen from Spirit stops for 5 seconds (the 5-second rule) and is reduced in combat. To get it back, stop casting: auto-attack, wand or wait 5s. Out of combat, drink water. Talents let some regen continue while casting (Meditation, Arcane Meditation, Reflection, Mindfulness, Bestial Discipline at 50%; Reverence at 30%). Mp5 on gear works while casting.", topic = "class_howto" }
add{ q = { "does spirit matter", "what does spirit do forever", "spirit mana regen", "spirit stat", "what does spirit do", "spirit forever", "is spirit good", "should i get spirit gear", "spirt mana regen", "is spirit worth it on gear or should i skip it in forever", "spirt stat" }, a = "Spirit raises health and mana regen out of the 5-second window. In Forever it also powers Life Tap (Warlock) and Bloom (Resto Druid), and Human Spirit gives +10% Spirit. Mage Armor and Spirit Tap boost it further. Healers with regen-while-casting talents value Spirit more than leveling DPS casters do.", topic = "class_howto" }
add{ q = { "mana regen racial", "skyborne mana regen", "cannibalize mana", "best racial for mana", "read ley line mana", "racial mana regen", "which racials help with mana regen in forever", "racial mana", "which race has best mana regen", "read ley line racial mana", "undead cannibalize mana forever" }, a = "Racials that help mana: High Order Skyborne Read Ley Line (+50% HP/mana regen for 15s, or 100% for 1 hour at a Ley Line), Undead Cannibalize (now restores mana too), Undead priest Dark Sacrifice, and Human Spirit (+10% Spirit).", topic = "class_howto" }
add{ q = { "warrior rogue mana", "do warriors use mana", "energy regen rogue", "do rogues use mana", "energy regen", "rogue energy", "warrior rage no mana", "do warriors and rogues need water", "do warriors or rogues need to drink water ever", "rogue mana?" }, a = "Warriors use rage and Rogues use energy, so neither needs water or Spirit regen; they only eat food for health. Rogues can drink Thistle Tea for a burst of energy, and Poised (18) makes the next ability cheaper when you're at full energy out of combat.", topic = "class_howto" }
add{ q = { "best warrior pvp spec", "warrior pvp forever", "arms or fury pvp", "warrior pvp", "arms pvp", "fury pvp", "what spec should warrior pvp", "warior pvp spec", "what spec should i run on my warrior for pvp in forever", "warrior pvp spec best" }, a = "Arms is the PvP pick (A tier on SeeMeta's Nov 16 list): Mortal Strike halves healing for 10s, and Improved Hamstring can root a fleeing target for 5s. Fury is B tier (Bloodthirst speed, Improved Berserker Rage clears slows) but has no healing reduction. Prot is only for flag carrying and control. These are editorial tiers, not ladder stats.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "how to beat warrior pvp", "counter warrior", "warrior counters", "how to kite warrior", "how to beat warrior", "warrior counter", "kite warrior", "how to fight warrior pvp", "warriors keep killing me in pvp", "how to beat warior", "warriors keep running me down in bgs how do i beat them", "warrior counters pvp" }, a = "Kite them: slows, roots and fears (Frost Nova, Crippling Poison, Concussive Shot, Earthbind, Curse of Exhaustion) stop Charge and Intercept follow-ups. Hunters and mages win at range. Bird of Prey's Mine! disarms them for 3s. Keep healers out of Mortal Strike range. Warriors die fast when starved of rage, so don't stand and trade blows.", class = "WARRIOR", topic = "class_howto" }
add{ q = { "best mage pvp spec", "mage pvp forever", "frost mage pvp", "mage pvp", "fire mage pvp", "what spec should mage pvp", "mage pvp spec", "what spec should i run on my mage for pvp in forever", "mage pvp spec best" }, a = "Frost is S tier: Ice Block (10s immunity), Ice Barrier, Frost Nova and Shatter combos with Ice Lance. Fire (Impact stun, Blast Wave) and Arcane (Improved Counterspell 4s silence, Presence of Mind) are A tier, but Fire lacks defensive talents. Gnome Escape Artist and Human Will to Survive are strong mage racials.", class = "MAGE", topic = "class_howto" }
add{ q = { "how to beat mage pvp", "counter mage", "mage counters", "how to beat mage", "mage counter", "how to fight mage pvp", "mages keep killing me in pvp", "how to beat frost mage", "mages keep sheeping and kiting me in bgs how do i beat them", "mage counters pvp" }, a = "Close the gap and stay on them: use stun-breaks or trinkets for Polymorph and Frost Nova, and save interrupts (Kick, Pummel, Spell Lock, Earth Shock) for Polymorph or big casts. Felhunter Devour Magic and Purge strip Ice Barrier. Warlocks are a mage's archenemy, and Orc Shatter Curse helps. Don't burn cooldowns into Ice Block.", class = "MAGE", topic = "class_howto" }
add{ q = { "best hunter pvp spec", "hunter pvp forever", "bm or mm pvp", "hunter pvp", "bm hunter pvp", "mm hunter pvp", "what spec should hunter pvp", "huntr pvp spec", "what spec should i run on my hunter for pvp in forever", "hunter pvp spec best" }, a = "Beast Mastery and Marksmanship are both A tier. BM has Intimidation (3s stun) and Bestial Wrath; MM has Scatter Shot (4s disorient) and Improved Concussive Shot stuns. Survival is B tier (Entrapment roots, Deterrence) but needs melee range. Remember Auto Shot needs 0.5s standing still.", class = "HUNTER", topic = "class_howto" }
add{ q = { "how to beat hunter pvp", "counter hunter", "hunter counters", "how to beat hunter", "hunter counter", "how to fight hunter pvp", "hunters keep killing me in pvp", "hunter dead zone", "how to beat huntr", "hunters keep kiting me in bgs how do i beat them", "hunter counters pvp" }, a = "Get inside the 8-yard dead zone and stay there, where hunters can't shoot. Watch for Freezing Trap (traps work in combat now), Scatter Shot and Wing Clip. Kill or CC the pet (pets lose player buffs in Forever). Make them move: Auto Shot only fires after 0.5s standing still, so slows and constant pressure hurt their damage.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best rogue pvp spec", "rogue pvp forever", "sub rogue pvp", "rogue pvp", "combat rogue pvp", "what spec should rogue pvp", "rouge pvp spec", "what spec should i run on my rogue for pvp in forever", "rogue pvp spec best" }, a = "Subtlety is S tier: Preparation resets your cooldowns, and Elusiveness cuts Vanish and Blind cooldowns by 90s. Assassination is A tier (Cold Blood guaranteed crits, Improved Kidney Shot). Combat is B tier with Improved Kick silence and Riposte disarm, but has no cooldown resets. Undead and Human have the best PvP racials.", class = "ROGUE", topic = "class_howto" }
add{ q = { "how to beat rogue pvp", "counter rogue", "rogue counters", "stop getting stunlocked", "how to beat rogue", "rogue counter", "how to fight rogue pvp", "rogues keep stunlocking me in pvp", "how to beat rouge", "rogues keep stunlocking me to death in bgs how do i beat them", "rogue counters pvp" }, a = "Keep a stun-break or trinket for Kidney Shot or Cheap Shot. Use AoE, Flare (hunters) or Perception (Human) to catch stealth. Don't waste CC while they have Vanish up. Rogues lack self-healing and struggle against 2v1, so stay near teammates. Slows, roots and armor make them work harder.", class = "ROGUE", topic = "class_howto" }
add{ q = { "best priest pvp spec", "priest pvp forever", "shadow priest pvp", "priest pvp", "disc priest pvp", "what spec should priest pvp", "preist pvp spec", "what spec should i run on my priest for pvp in forever", "priest pvp spec best" }, a = "Shadow is S tier: Silence (5s), Psychic Scream, Shadowform (+10% Shadow damage, half-cost Shadow spells). For healing, Discipline is A tier (faster Improved Mana Burn, Silent Resolve shortens CC), and Holy is B (Prayer of Mending, Spell Warding, but no control). SW:Death costs you HP if it doesn't kill.", class = "PRIEST", topic = "class_howto" }
add{ q = { "how to beat priest pvp", "counter shadow priest", "priest counters", "how to beat priest", "counter priest", "priest counter", "how to beat shadow priest", "how to fight priest pvp", "shadow priests keep killing me", "how to beat preist", "shadow priests keep melting me in bgs how do i beat them", "priest counters pvp" }, a = "Break line of sight to stop casts and Mind Flay, and use Fear Ward or Tremor Totem (or Will of the Forsaken) to ignore Psychic Scream. Interrupt Mind Blast and heals. Purge or Devour Magic their shields. Shadow priests are cloth and still cast-dependent, so pressure them early before DoTs stack.", class = "PRIEST", topic = "class_howto" }
add{ q = { "best warlock pvp spec", "warlock pvp forever", "demo lock pvp", "warlock pvp", "affliction pvp", "lock pvp forever", "what spec should warlock pvp", "warlok pvp spec", "what spec should i run on my warlock for pvp in forever", "warlock pvp spec best" }, a = "Demonology is S tier: Soul Link sends 30% of damage to your demon and Demonic Embrace adds 15% Stamina. Affliction is A tier (Curse of Exhaustion 30% slow, Siphon Life) but has little burst. Destruction is B (Shadowburn, Molten Skin) and its long casts get interrupted. Felhunter (Spell Lock, Devour Magic) is the PvP demon.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "how to beat warlock pvp", "counter warlock", "warlock counters", "how to beat warlock", "warlock counter", "how to fight warlock pvp", "warlocks keep fearing me", "how to beat lock pvp", "how to beat warlok", "warlocks keep fearing me to death in bgs how do i beat them", "warlock counters pvp" }, a = "Kill or crowd-control the demon, then interrupt Fear and Death Coil setups. Fear Ward, Tremor Totem, Will of the Forsaken and Berserker Rage stop Fear. Dispel or cleanse DoTs and curses (Orc Shatter Curse clears Curses and Banes). Warlocks are cloth and immobile, so melee pressure works well.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "best paladin pvp spec", "paladin pvp forever", "ret paladin pvp", "paladin pvp", "ret pally pvp", "holy pally pvp", "pally pvp forever", "what spec should paladin pvp", "paldin pvp spec", "what spec should i run on my paladin for pvp in forever", "paladin pvp spec best" }, a = "Holy Paladin is A tier for healing in groups (Divine Favor crit, instant Holy Shock, immunity to silence and interrupts), but weak in duels. Prot Paladin is A tier in duels thanks to Templar's Bulwark. Retribution is B tier: Repentance and Seal of Command, but short on reach. Divine Shield and Hammer of Justice make paladins hard to pin down.", class = "PALADIN", topic = "class_howto" }
add{ q = { "how to beat paladin pvp", "counter paladin", "paladin counters", "how to beat paladin", "paladin counter", "how to beat pally", "how to fight paladin pvp", "paladins are so tanky in pvp", "how to beat paldin", "paladins keep bubbling and healing in bgs how do i beat them", "paladin counters pvp" }, a = "Paladins are tanky but slow. Kite them (they lack gap closers), drain their mana with Mana Burn or Viper Sting, and save burst for after Divine Shield ends. Interrupt Holy Light outside of Holy's immunity window, and use Mortal Strike, Wound Poison or Dismember to cut their heals.", class = "PALADIN", topic = "class_howto" }
add{ q = { "best druid pvp spec", "druid pvp forever", "feral druid pvp", "druid pvp", "feral pvp", "resto druid pvp", "what spec should druid pvp", "druid pvp spec", "what spec should i run on my druid for pvp in forever", "druid pvp spec best" }, a = "Feral is A tier: Feral Charge roots and interrupts for 4s, and Feral Swiftness gives +30% cat speed. Resto is A tier for group healing (Nature's Swiftness, Swiftmend). Balance is B (Moonkin armor, Improved Starfire stun) but can't heal in form. Shapeshifting breaks roots, snares and Polymorph, and potions now work in form.", class = "DRUID", topic = "class_howto" }
add{ q = { "how to beat druid pvp", "counter druid", "druid counters", "how to beat druid", "druid counter", "how to fight druid pvp", "druids keep shifting out of my slows", "how to beat feral druid", "druids keep shifting out of my roots in bgs how do i beat them", "druid counters pvp" }, a = "Druids shift out of slows and roots, so use stuns, Fear and silences instead. Interrupt or purge their HoTs and Innervate, and use healing reduction (Mortal Strike, Wound Poison). Catch them in caster form for Polymorph or Fear. Night Elf druids can Shadowmeld and Prowl, so watch for openers.", class = "DRUID", topic = "class_howto" }
add{ q = { "best shaman pvp spec", "shaman pvp forever", "enhance or ele pvp", "shaman pvp", "ele shaman pvp", "enh shaman pvp", "what spec should shaman pvp", "shamen pvp spec", "what spec should i run on my shaman for pvp in forever", "shaman pvp spec best" }, a = "Elemental is A tier (Earthbound totem roots for 5s, Lightning Mastery burst). Enhancement is B tier (Maelstrom Weapon, Rage of the Farseer +30% attack speed) but has no gap closer. Resto Shaman is B for healing, with Nature's Swiftness. Every spec has Purge, Grounding, Tremor and Earthbind.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "how to beat shaman pvp", "counter shaman", "shaman counters", "how to beat shaman", "shaman counter", "how to fight shaman pvp", "kill totems first", "shamans keep killing me in pvp", "how to beat shamen", "shamans keep grounding my spells in bgs how do i beat them", "shaman counters pvp" }, a = "Kill the totems first: Grounding eats your big spell, Tremor stops Fear, and Earthbind slows you. Shamans have no hard crowd control, so pressure works. Interrupt Lightning Bolt and Healing Wave, and kite Enhancement since it can't close gaps.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "best pvp class forever", "pvp tier list forever", "strongest pvp spec", "best pvp class", "pvp tier list", "strongest pvp class", "best class for pvp", "pvp tierlist", "what class is best at pvp", "best pvp spec forever", "which class and spec is strongest for pvp in forever right now" }, a = "SeeMeta's Nov 16 editorial list puts Subtlety Rogue, Shadow Priest, Frost Mage and Demonology Warlock in S tier. A tier: Arms, BM/MM Hunter, Assassination, Elemental, Fire/Arcane Mage, Affliction, Feral, plus Holy Paladin, Disc Priest and Resto Druid for healers. There are no ladder stats yet, so treat it as opinion.", topic = "class_howto" }
add{ q = { "weapon trainer", "where to learn polearms", "weapon skill trainer stormwind", "weapon trainer orgrimmar", "how to learn new weapon skill", "weapon master", "where to learn weapon skills", "weapon trainer location", "how to learn polearms", "how to learn swords", "where do i learn new weapon types", "wepon trainer", "i want to use polearms where is the weapon trainer and how much does it cost", "weapon trainer where" }, a = "Weapon skills cost 10 silver (polearms 1 gold, level 20). Stormwind: Woo Ping, Trade District (63.8,69.0) for swords, polearms, staves, daggers, crossbows. Ironforge: Buliwyf Stonehand (axes, maces, fist, guns) and Bixi Wobblebonk (62.2,89.6). Darnassus: Ilyenia Moonfire (57.6,46.7). Orgrimmar: Sayoc and Hanashi, Valley of Honor (81.5,19.6). Thunder Bluff: Ansekhwa (40.9,62.7). Undercity: Archibald, War Quarter (57.3,32.8) for swords and polearms.", topic = "class_howto" }
add{ q = { "sunken temple class quest", "level 50 class quest", "atal hakkar class items", "st class quest", "atal hakkar class item", "class quest sunken temple", "what is the lvl 50 class quest", "sunkin temple class quest", "what is the level 50 class quest in sunken temple for my class", "sunken temple quest class" }, a = "Every class (except Horde Paladins and Alliance Shamans) has a level 50 Sunken Temple chain worth 12,400 XP and a choice of three rare class items. Four classes need voodoo feathers from the troll minibosses, four need a Morphaz drop, and Druids need Putrid Vine.", topic = "class_howto" }
add{ q = { "rhokdelar", "hunter epic bow quest", "hunter level 60 quest", "hunter epic bow", "hunter lvl 60 quest", "rhokdelar quest", "how to get rhokdelar", "where does the epic bow quest start", "rhok delar", "im a 60 hunter how do i start the rhokdelar epic bow quest", "epic bow hunter" }, a = "The hunter epic bow chain starts at 60 with An Introduction and ends in Rhok'delar, Longbow of the Ancient Keepers. Its parts drop in Molten Core.", class = "HUNTER", topic = "class_howto" }
add{ q = { "coldflame saber", "mage sword research scroll", "where to get coldflame saber", "how to get coldflame saber", "mage sword scroll", "coldflame saber mage", "where to find coldflame saber", "is coldflame saber a quest", "cold flame saber", "how do i get the coldflame saber on my mage is it a quest", "coldflame sabre" }, a = "The Coldflame Saber isn't a quest reward. It comes from Comprehension research scrolls and is also a rare drop in Shadowfang Keep. No leveling spell is locked behind a mage class quest.", class = "MAGE", topic = "class_howto" }
add{ q = { "troll warlock quest", "tainted tablet", "troll warlock imp", "troll warlock imp quest", "troll warlock start", "tainted tablet quest", "where does troll warlock start", "troll warlok quest", "just made a troll warlock what is the tainted tablet starting quest", "troll lock quest" }, a = "Troll Warlocks (new in Forever) get their own starting quest, Tainted Tablet, which leads to Summon Imp. Every other warlock also gets the Imp from a short starting-zone quest; you don't start with a demon.", class = "WARLOCK", topic = "class_howto" }
add{ q = { "totem of charged flames", "call of fire reward", "skyborne shaman totem", "call of fire quest reward", "charged flames totem", "what do i get from call of fire", "totem of charged flame", "what reward do i get from call of fire is it the totem of charged flames", "fire totem quest reward", "skyborne shaman call of fire", "charged flames totem what does it do" }, a = "Call of Fire (10) gives the Fire Totem plus the Totem of Charged Flames. Skyborne shamans can also get it from The Meddlesome Mages. Call of Air (30) opens the Tempest's Weapons quest for Rage of the Storm, Lightning's Grasp or Tidebringer's Claw.", class = "SHAMAN", topic = "class_howto" }
add{ q = { "aspect of the cheetah daze", "cheetah dazed", "aspect of the pack daze", "cheetah daze", "why do i get dazed", "cheetah dazed forever", "how does cheetah daze work", "cheeta daze", "i keep getting dazed with aspect of the cheetah on how does that work", "cheetah aspect daze" }, a = "Aspect of the Cheetah (20) gives 30% run speed, but any hit dazes you. Aspect of the Pack (40) does the same for your group. Turn them off before pulling or in contested areas, or you'll be dazed and caught.", class = "HUNTER", topic = "class_howto" }
add{ q = { "eyes of the beast", "control pet hunter", "scout with pet", "control pet", "how to control my pet", "what does eyes of the beast do", "how do i use eyes of the beast", "eye of the beast", "how do i control my pet directly to scout ahead with eyes of the beast", "eyes of beast" }, a = "Eyes of the Beast lets you control your pet directly. Use it to scout or pull from far away. Combine it with Feign Death and pet stances to set up safe pulls.", class = "HUNTER", topic = "class_howto" }
add{ q = { "best pet each level", "what pet at level 20 30 40", "pet upgrade path", "what pet should i have at 30", "pet by level", "what pet at 40", "when should i retame a new pet", "pet upgrade", "what pet should i have at each level and when should i tame a new one", "pet upgrade path huntr" }, a = "Typical path: tame a Boar or Cat at 10, then retame a fresh one near your level every 10 or so. Grab a Bite or Claw 4 carrier at 24 to teach your main. Take Broken Tooth at 37+ if you can find it. Through the 40s and 50s keep your favourite and teach it new Bite or Claw ranks from wild carriers. Since damage is normalized in a family, retaming isn't needed for damage.", class = "HUNTER", topic = "class_howto" }
add{ q = { "mend pet", "revive pet", "pet died what do i do", "call pet not working", "pet died", "my pet is dead", "how do i bring my pet back", "revive pet how", "my pet died and call pet does nothing how do i get it back", "pet dead help" }, a = "Mend Pet (12) heals your pet over time. Revive Pet brings back a dead pet (Call Pet won't work until you revive it). A pet death costs a lot of happiness, so feed it after reviving.", class = "HUNTER", topic = "class_howto" }
add{ q = { "pickpocket", "rogue pick pocket worth it", "what does pickpocket give", "pick pocket", "is pickpocket worth it", "pickpocket loot", "should i pickpocket mobs", "pick pocketing", "is pickpocketing worth doing on my rogue while leveling", "pickpocket worth" }, a = "Pick Pocket (4) steals coins, junk and lockboxes from humanoids while you're stealthed. Use it on every humanoid before you open, because it's free gold and lockbox practice for Lockpicking.", class = "ROGUE", topic = "class_howto" }
add{ q = { "polymorph tips", "how to sheep", "polymorph breaks", "how to polymorph", "polymorph", "sheep breaks", "how long does polymorph last", "why does my polymorph break", "polymorf tips", "how do i polymorph properly and why does my sheep keep breaking", "polymorph how" }, a = "Polymorph (8) turns a humanoid or beast into a sheep that heals while sheeped and breaks on any damage. Sheep the second mob at the start of a pull and keep AoE and DoTs off it. Don't sheep a mob that has your Frost Nova or DoTs on it.", class = "MAGE", src = "classic", topic = "class_howto" }
add{ q = { "seal twisting forever", "unsealed wrath", "paladin swap seals", "seal twisting", "can you seal twist", "seal twist", "swap seals", "unsealed wrath how", "is seal twisting a thing in forever", "seal twistin", "can i still seal twist on my paladin in forever or is it unsealed wrath now", "seal twist forever" }, a = "Forever's version of seal twisting is Unsealed Wrath (Ret 31-point). Your swings store your current Seal (up to 3 stacks for 15s), and when you swap Seals, each stack can proc the old one. Twist of Light was cut before launch.", class = "PALADIN", topic = "class_howto" }
add{ q = { "druid skyborne forms", "skyborne druid quest", "high order druid bear", "skyborne druid forms", "skyborne druid", "windshaper druid forms", "do skyborne druids look different", "skyborn druid forms", "what forms do skyborne druids get and is there a special quest", "skyborne druid form quest" }, a = "Skyborne druids get their own form looks. High Order Skyborne get Bear Form from The Great Ursera Spirit (Strength and Mercy) on Zephras Isle, and Teleport: Moonglade from a quest in Stormwind or Thunder Bluff. Since Nov 2 they can also do the Cure Poison quests.", class = "DRUID", topic = "class_howto" }
add{ q = { "when do i get talents", "what level do talents start", "talent milestones forever", "how many talent points", "16 point talent", "dual spec level", "what lvl do i get my first talent point", "when do talents unlock", "talent points start at 10?", "how many talent points do i get at 60", "whats the new 16 point talent thing", "when can i dual spec", "dual spec lvl forever", "do we still get talents every level after 10", "just made a new char when do i actually start getting talent points", "wat lvl talents" }, a = "Talents start at level 10. Each tree keeps the 11, 21 and 31-point gold milestone talents and adds a new 16-point gold milestone. You change talents (including Legacy talents) at your class trainer in a major city. You still can't go over 51 total talent points. Dual Talent Specialization unlocks at level 40.", topic = "classes" }
add{ q = { "talented legacy", "get talents earlier", "legacy talented node", "talents before level 10", "can i get talent points before 10", "talented node legacy how does it work", "how do i unlock talents early", "legacy talented rank 5 what lvl", "talents at lvl 9 legacy", "is the talented legacy node worth it", "early talent points forever", "is there any way to get my talent points sooner than level 10 with legacy", "talentd legacy node" }, a = "The Legacy system's Talented node (Adventure tree, 5 ranks) gives talent points earlier: rank 1 starts them at level 9, and max rank starts them at level 5. That lets you reach key talents up to 5 levels sooner. The 51-point cap doesn't change. Legacy points come from account challenges, such as hitting level 25/45/60 on a class.", topic = "classes" }
add{ q = { "how much does training cost", "total cost to train spells", "training cost 1-60", "how much gold for spells", "how much gold to train all my spells", "spell training cost total", "how much money do i need for training", "training costs forever", "cost to train 1 to 60", "is training more expensive on some classes", "how much g should i save for spells", "im broke how much gold will i need total to keep training my spells to 60", "how much does trainin cost" }, a = "Blizzard evened out training costs: training all class abilities from 1 to 60 now costs about 206-207 gold for every class.", topic = "classes" }
add{ q = { "hit crit apply to spells", "weapon skill forever", "expertise forever", "haste stat forever", "stats changes forever", "does hit work for spells now", "is weapon skill gone in forever", "what does expertise do", "does haste exist in forever", "stat changes forever", "does crit apply to everything now", "how do stats work on forever", "coming from classic do i still need weapon skill or did forever change how hit and crit work", "does spell hit exsist" }, a = "Forever unified the combat stats. Crit and Hit apply to all attack types, Expertise replaces the old weapon-skill bonuses, and Haste is a new secondary stat. Hunter guides put the effective hit cap against bosses at 9% for a level 60 with 300 weapon skill.", topic = "classes" }
add{ q = { "wand not shooting", "auto shot delay", "why does my wand wait", "wand standing still", "my wand wont shoot", "wand not firing", "why does my wand take forever to shoot", "auto shot delayed when moving", "wand only shoots when i stand still?", "wand keeps stopping", "wtf is wrong with my wand", "my wand just sits there doing nothing when i stutter step whats going on", "wand wont shot" }, a = "In Forever, Wands and Auto Shot fire only after you've stood still for 0.5 seconds. If you're moving or stutter-stepping, the shot won't start.", topic = "classes" }
add{ q = { "race class combos forever", "what new race class combinations", "new combos forever", "which races can be what class", "what race class combos are new", "new race and class combos", "can orc be mage now", "list of new combos", "which races can play which class forever", "human hunter possible?", "all the new race class options", "what are all the new race and class combinations they added in forever", "new race class combo's" }, a = "There are 16 new combos: Human Hunter; Dwarf Shaman; Gnome Priest; Orc Mage; Troll Warlock; Undead Paladin; and Skyborne Druid, Hunter, Rogue and Warrior. Alliance (High Order) Skyborne can also be Mage, and Horde (Windshaper) Skyborne can be Shaman. That makes 56 combos in total.", topic = "classes" }
add{ q = { "can horde be paladin", "alliance shaman", "undead paladin", "dwarf shaman forever", "can horde play paladin", "can alliance be shaman", "can undead be paladin", "is dwarf shaman a thing", "do both factions get pally and shaman", "horde pally race", "alliance shammy which race", "i play horde but want to be a paladin is that possible now", "can alliance play shamman" }, a = "Yes, both factions get both hybrids. Horde Paladins are Undead only, and their class quests run from Bandarion Keep in Tirisfal Glades. Alliance Shamans are Dwarf only, with new trainers in Coldridge Valley, Kharanos and Ironforge.", topic = "classes" }
add{ q = { "what is skyborne", "skyborne classes", "high order vs windshaper", "skyborne faction", "what is the skyborne race", "skyborne race classes", "what classes can skyborne be", "difference between high order and windshaper", "is skyborne alliance or horde", "where do skyborne start", "skyborne what faction", "i keep seeing skyborne in character creation what is it and what classes can it be", "what is skyborn" }, a = "Skyborne is Forever's new race, and it starts on Zephras Isle. High Order Skyborne are Alliance (Druid, Hunter, Mage, Rogue, Warrior). Windshaper Skyborne are Horde (Druid, Hunter, Rogue, Shaman, Warrior).", topic = "classes" }
add{ q = { "skyborne racials", "walk on air", "read ley line", "skysight", "wind blessed", "what are skyborne racials", "skyborne racial abilities", "what does walk on air do", "read ley line racial", "skysight what is it", "skyborne racials worth it", "wind blessed haste racial", "thinking about rolling skyborne what racials do they get and are they good", "skyborne racals" }, a = "Both Skyborne types get Walk on Air (steerable slow fall, 90s CD), Wind Blessed (+2% haste) and Elemental Insight (+5% damage vs Elementals). High Order adds Read Ley Line: +50% HP/mana regen for 15s, or 100% for 1 hour (Attuned) if used at a Ley Line. Windshaper adds Skysight: +15% speed for 15s, or 30% for 1 hour (Charged) at an elemental convergence. Both buffs drop when you enter a raid.", topic = "classes" }
add{ q = { "human racials forever", "ruthless racial", "human spirit", "what are human racials", "human racial forever", "what does ruthless do", "human spirit racial", "human racials changed?", "did human lose sword spec", "is human still good with the racial changes what do they get now", "humen racials" }, a = "Human: Ruthless gives +1% crit (cut from 2% before launch) and replaces Sword Specialization. Human Spirit is now +10% Spirit. Humans also get a stun-break (Will to Survive) and Perception (stealth detection).", topic = "classes" }
add{ q = { "dwarf racials forever", "stoneform forever", "artisan's precision", "what are dwarf racials", "dwarf racial forever", "what does artisans precision do", "stoneform changes", "dwarf racials changed", "dwarf hit racial", "rolling a dwarf what racials do they have in forever now", "dwarf racails" }, a = "Dwarf: Artisan's Precision gives +1% hit with spells and attacks. It replaced Earth Fury at launch, which had replaced Mace Specialization. Stoneform now also cuts physical damage taken (guides say 10%). Find Treasure can also find extra items in chests.", topic = "classes" }
add{ q = { "orc racials forever", "blood fury cooldown", "command racial", "shatter curse", "what are orc racials", "orc racial forever", "blood fury cd", "does orc have command again", "what is shatter curse", "orc pet damage racial", "did orc racials change at all in forever like blood fury and command", "orc racals" }, a = "Orc: Blood Fury gives +10% AP and spell power for 15s on a 2-minute CD. Command is back (+5% Warlock and Hunter pet damage). Shatter Curse dispels Curses and Banes and cuts magic damage taken by 5%. Hardiness shortens stuns by 20%.", topic = "classes" }
add{ q = { "tauren racials forever", "plainsrunning", "war stomp cooldown", "endurance tauren", "what are tauren racials", "tauren racial forever", "how does plainsrunning work", "war stomp cd", "tauren endurance changes", "does plainsrunning work on mount", "playing tauren what is plainsrunning and how does it work", "tauren racails" }, a = "Tauren: Plainsrunning gives +2% run speed per stack (max 60%) while you keep moving. It doesn't affect mounts, and stutter-stepping breaks it. War Stomp is on a 90s CD, Endurance is +5% health, and Cultivation's CD is 15 minutes.", topic = "classes" }
add{ q = { "troll racials forever", "berserking forever", "troll regeneration", "what are troll racials", "troll racial forever", "berserking duration forever", "troll regen racial", "did berserking change", "troll racials changed", "did troll berserking get changed in forever how long does it last", "troll racals" }, a = "Troll: Berserking gives +10% casting and attack speed for 15s (lengthened from 10s at launch). Regeneration is +20% health regen, and some of it continues in combat. Beast Slaying is +5% damage vs beasts.", topic = "classes" }
add{ q = { "undead racials forever", "touch of the grave", "cannibalize forever", "what are undead racials", "undead racial forever", "what does touch of the grave do", "cannibalize changes", "will of the forsaken forever", "forsaken racials changed", "what do undead get for racials now did touch of the grave change", "undead racails" }, a = "Undead: Touch of the Grave procs a health drain (ICD 15s at launch). Will of the Forsaken removes Charm, Fear and Sleep but can't be used during Scatter Shot. Cannibalize restores 7% HP and mana every 2s for 10s, and it now restores mana too.", topic = "classes" }
add{ q = { "gnome racials forever", "eureka racial", "expansive mind", "what are gnome racials", "gnome racial forever", "what does eureka do", "expansive mind gnome", "gnome racials changed", "eureka racial cooldown", "playing a gnome what does eureka actually do in forever", "gnome racals" }, a = "Gnome: Eureka! is an 8s buff (2 min CD) with no charges that makes eligible abilities cost 10% less and deal 10% more, or heal 10% more. It also boosts Power Word: Shield. Expansive Mind gives +5% max mana, rage or energy. Escape Artist is unchanged.", topic = "classes" }
add{ q = { "night elf racials forever", "elune's light", "quickness", "what are night elf racials", "nelf racials forever", "elunes light what does it do", "quickness racial nelf", "night elf racials changed", "does shadowmeld still exist nelf", "what racials does night elf have now whats elunes light", "nelf racails" }, a = "Night Elf: Elune's Light gives +10% crit for 15s. Quickness gives +1% dodge and a movement speed bonus that now stacks with other speed effects. Shadowmeld still works, and Wisp form is faster after death.", topic = "classes" }
add{ q = { "warrior changes forever", "what's new for warrior", "warrior forever abilities", "new warrior spells", "victory rush", "whats new for warrior in forever", "warrior changes", "what changed on warrior", "new warrior abilities forever", "does warrior get victory rush", "warrior forever differences from classic", "what did they change for warriors", "coming back from classic what did they change about warriors in forever", "warior changes forever" }, a = "Warrior changes: Rage from hits scales with weapon speed, and crits give 75% more rage. Tactical Mastery is baseline (keep 10 rage on stance swap). Victory Rush is new at 20 (usable 20s after a kill, heals 10% HP, 30s CD). Thunder Clap works in Defensive Stance. Battle Shout is raid-wide. Shield Wall, Retaliation and Recklessness no longer share a cooldown.", class = "WARRIOR", topic = "classes" }
add{ q = { "warrior rage normalized", "why is my rage low", "rage decay", "rage from crits", "why is my rage so low", "warrior not getting rage", "how does rage work now", "rage normalized weapon speed", "rage decay forever", "do crits give more rage", "my warrior has no rage help", "i barely get any rage on my warrior with this fast weapon is something wrong", "why is my rage so bad" }, a = "Rage from dealing damage now depends on weapon speed, not weapon damage, and crits give 75% more. Rage from damage taken ignores your armor, and absorbs don't reduce it. Rage decays out of combat, so plan on opening fights at 0 rage.", class = "WARRIOR", topic = "classes" }
add{ q = { "best warrior leveling spec", "warrior leveling build", "arms or fury leveling", "what spec should i level warrior", "warrior leveling spec forever", "arms or fury for leveling", "best spec to level a warrior", "warrior leveling talents", "is fury good for leveling", "im leveling a warrior which tree", "just rolled a warrior should i go arms or fury to level up faster", "best warior leveling spec" }, a = "Arms is the safe classic pick for leveling, with stable burst, Deflection and Anger Management. Fury hits hard but takes more damage and needs more downtime. Protection is surprisingly good at AoE-pulling packs. In Arms, max Two-Handed Weapon Specialization rather than Spearing Strike, and later choose Bloodthrill over Weaponmaster.", class = "WARRIOR", topic = "classes" }
add{ q = { "warrior defensive stance quest", "warrior level 10 quest", "bartleby", "path of defense", "skybreaker bulwark", "how do i get defensive stance", "warrior lvl 10 quest", "defensive stance quest location", "where is bartleby quest", "warrior def stance quest horde", "skyborne warrior defensive stance quest", "warrior 10 quest where do i go", "hit 10 on my warrior where do i go for the defensive stance quest", "defensive stance quset" }, a = "The level 10 Defensive Stance quest varies by race. Human/Dwarf/Gnome: Harry Burlguard (Stormwind), then Beat Bartleby and Bartleby's Mug. Night Elf: Elanaria in Darnassus, then Vorlus Vilehoof. Orc/Troll/Tauren: Veteran Uzzek, then Path of Defense. Undead: Speak with Dillinger (Tirisfal), then Ulag the Cleaver. Skyborne: The Skybreaker Bulwark on Zephras Isle.", class = "WARRIOR", topic = "classes" }
add{ q = { "berserker stance quest", "the affray", "warrior level 30 quest", "whirlwind axe quest", "how do i get berserker stance", "zerker stance quest", "warrior lvl 30 quest", "where is the affray", "berserker stance quest fray island", "warrior 30 quest steps", "the islander quest warrior", "just hit 30 on my warrior how do i get berserker stance", "berserker stanse quest" }, a = "At level 30, Berserker Stance comes from The Islander and then The Affray, an arena fight on Fray Island in The Barrens. The Whirlwind Weapon chain follows and turns in to Bath'rah the Windwatcher in Alterac Mountains. You choose the Whirlwind Axe, Sword or Warhammer, and must kill Cyclonian (level-40 elite) along the way.", class = "WARRIOR", topic = "classes" }
add{ q = { "warrior talents forever", "weaponmaster talent", "spearing strike", "bloodthrill", "warrior talent changes", "what does weaponmaster do", "spearing strike talent", "what is bloodthrill", "new warrior talents", "arms talents forever", "warrior new talent points", "what new talents did warriors get like weaponmaster and spearing strike", "warrior talants forever" }, a = "Arms: Weaponmaster replaces the old weapon specs (axes/polearms crit, maces/staves armor-pen, swords extra attacks). Spearing Strike is the 16-point gold (dismounts, double damage vs mounted, dragons and giants). Bloodthrill (2 pts) lets hits on Rend targets proc Overpower. Improved Slam stops Slam from resetting your swing.", class = "WARRIOR", topic = "classes" }
add{ q = { "fury warrior changes", "bloodthirst no heal", "reckless swings", "raging blows", "fury warrior changes forever", "does bloodthirst heal", "reckless swings talent", "raging blows fury", "whats new for fury", "fury talents forever", "playing fury is it true bloodthirst doesnt heal anymore whats changed", "furry warrior changes" }, a = "Fury: Bloodthirst no longer heals. It gives 10% move speed for 10s and now requires Death Wish. Raging Blows (16-pt) makes Whirlwind hit with both weapons. Flurry is 3 points (10/20/30%). Reckless Swings costs 25% base health and gives +5 rage on each of the next 4 swings. Improved Whirlwind lowers its CD by up to 2s.", class = "WARRIOR", topic = "classes" }
add{ q = { "prot warrior forever", "vanguard talent", "charge in defensive stance", "warrior tank threat", "prot warrior changes forever", "warrior tank forever", "can i charge in def stance", "vanguard talent warrior", "warrior tank threat forever", "how good is prot warrior", "defiance talent forever", "want to tank on my warrior what changed for prot in forever", "prot warior forever" }, a = "Prot: Defensive Stance threat is 80%, and Defiance gives 7/13/20% (needs a shield). Vanguard (16-pt) lets you Charge in Defensive Stance. Bastion boosts all damage while holding a shield. Master of Defense gives rage on dodge or parry. Improved Shield Wall greatly cuts its cooldown. Thunder Clap is usable in Defensive Stance.", class = "WARRIOR", topic = "classes" }
add{ q = { "warrior stat priority", "what stats warrior", "warrior gear stats leveling", "warrior stat prio", "what stats for warrior", "warrior stats leveling", "what should warrior gear for", "best stats warrior 60", "warrior str or agi", "what stats do i need on my warrior", "what stats should i be looking for on gear for my warrior while leveling", "warrior stat priorty" }, a = "For leveling: weapon DPS first (a slow 2H for Arms), then Strength/AP, then Stamina, Agility and Armor. At 60, hit and crit apply to all attacks, and Expertise replaces weapon skill. Guides haven't published a final 60 priority yet, but it's expected to look like Classic's: hit to cap, then Strength/crit.", class = "WARRIOR", topic = "classes" }
add{ q = { "best warrior race", "warrior race forever", "human or orc warrior", "best race for warrior", "what race warrior forever", "orc or human warrior", "best alliance warrior race", "best horde warrior race", "which race should i roll warrior", "about to make a warrior which race is the best pick in forever", "best warior race" }, a = "Alliance: Human (Ruthless crit) or Dwarf (Stoneform damage reduction, +1% hit). Night Elf and Gnome are fine, mostly for PvP. Horde: no clear winner. Orc has Blood Fury, Troll Berserking, Tauren War Stomp, and Undead Touch of the Grave. Guides rate Skyborne weak for Warriors.", class = "WARRIOR", topic = "classes" }
add{ q = { "warrior beginner mistakes", "warrior tips leveling", "why is warrior leveling hard", "warrior tips", "warrior leveling tips", "why is leveling warrior so hard", "warrior mistakes", "warrior tips for new players", "how to not die on warrior", "im bad at warrior tips", "my warrior keeps dying while leveling what mistakes am i making", "warior tips" }, a = "Common mistakes: wasting rage (Executing a mob at 60 HP), hoarding cooldowns instead of using them to pull more, letting Battle Shout lapse, and skipping food buffs. Warriors scale with gear, so upgrade your weapon often. Train a new weapon skill before you equip that weapon type.", class = "WARRIOR", topic = "classes" }
add{ q = { "mage changes forever", "what's new for mage", "frostfire bolt", "new mage spells", "whats new for mage in forever", "mage changes", "what changed on mage", "frostfire bolt level", "new mage abilities forever", "mage forever differences", "what did they change for mages", "back from classic what did forever change about mages", "mage chnages forever" }, a = "Mage changes: Comprehension is a new scroll-reading skill at level 6. Frostfire Bolt comes at 40 (3s cast, counts as both Fire and Frost, has a DoT and a slow). Ice Lance (Frost 11-pt), Arcane Blast (Arcane 11-pt) and Missile Barrage are new. Cold Snap's CD is now 10 min. Ignite and Winter's Chill are now personal to you.", class = "MAGE", topic = "classes" }
add{ q = { "mage comprehension", "comprehend scroll", "mage scrolls", "why did i turn into a sheep", "what is comprehension", "how does comprehend scroll work", "mage scroll skill", "i turned into a sheep reading a scroll", "mage scrolls forever", "how to level comprehension", "what do mage scrolls do", "i read a scroll on my mage and got turned into a sheep wtf is comprehension", "comprehention mage" }, a = "Comprehension is a Mage-only minor tradeskill. Comprehend Scroll is learned at level 6 and lets you decipher scrolls dropped by mobs. Scrolls include Frog Familiar, Scroll of Confuse Beast and weapon imbues like Lesser Flame and Imbue Spark. If you fail to read a scroll, you become a sheep, so raise your skill first. Study is learned through a quest, and Research was removed.", class = "MAGE", topic = "classes" }
add{ q = { "best mage leveling spec", "mage leveling build", "frost or fire leveling mage", "what spec should i level mage", "mage leveling spec forever", "frost or fire for leveling", "best spec to level mage", "mage leveling talents", "is fire good for leveling mage", "im leveling a mage which tree", "just started a mage should i level frost or fire in forever", "best mage leveing spec" }, a = "Frost is the standard leveling spec for its survivability and control, and Ice Lance on frozen targets kills fastest once you have gear. A common start is 7 points in Arcane for Missile Barrage, then Frost for Ice Lance, Fingers of Frost and Winter's Chill. Fire needs a lot of crit, and Arcane is better in dungeons.", class = "MAGE", topic = "classes" }
add{ q = { "ice lance", "ice lance cooldown", "shatter combo forever", "fingers of frost", "what does ice lance do", "ice lance cd", "ice lance level", "shatter forever", "fingers of frost talent", "how does ice lance work forever", "ice lance frozen damage", "how does ice lance work on frozen targets and whats the cooldown", "ice lanse" }, a = "Ice Lance (Frost 11-pt, around level 20) is instant and deals 300% damage to frozen targets. At launch it shares an 8s cooldown with Fire Blast. Fingers of Frost lets chill effects give charges that make targets count as frozen, so Ice Lance and Shatter hit hard without Frost Nova.", class = "MAGE", topic = "classes" }
add{ q = { "arcane blast", "arcane blast stacks", "missile barrage", "arcane mage forever", "what does arcane blast do", "arcane blast stacking", "missile barrage talent", "how does arcane blast work", "is arcane good forever", "thinking about arcane how does arcane blast stacking work in forever", "arcane blats stacks" }, a = "Arcane Blast (Arcane 11-pt) has a 2.5s cast. Each cast adds a stack (max 4, 18s) that buffs your spells and raises its own mana cost by 100% per stack. Missile Barrage procs make your next Arcane Missiles twice as fast and free, and Arcane Blast triggers it twice as often. Watch your mana.", class = "MAGE", topic = "classes" }
add{ q = { "fire mage forever", "heating up", "pyroblast fire mage", "incineration", "fire mage changes forever", "how does heating up work", "fire mage pyroblast", "incineration talent", "is fire good forever", "fire mage talents", "want to play fire mage what is heating up and how does pyro work now", "fire mage forver" }, a = "Fire: Heating Up means crits from Fireball, Frostfire Bolt, Fire Blast or Scorch each cut your next Pyroblast's cast by 25% (3 stacks). Incineration is now on row 1 (5 pts, +10% crit). Combustion lasts until 4 non-periodic crits. Fire needs high crit to shine.", class = "MAGE", topic = "classes" }
add{ q = { "mage class quests", "mage robe quest", "mage level 15 quest", "mage wand quest", "mage class quest", "mage robe quests", "mage lvl 15 quest", "mage wand quest where", "report to jennea", "report to anastasia", "what quests do mages get", "what class quests does mage get like the robe and wand quests", "mage class quets" }, a = "Mage robe chains are at levels 10, 15 and 26. Level 15 is Report to Jennea (Alliance) or Report to Anastasia (Horde), and ends in a Manaweave or Spellfire Robe. At level 30, Journey to the Marsh from a mage trainer leads to Tabetha west of Theramore. The reward is a choice of Nether Force, Ragefire or Icefury Wand.", class = "MAGE", topic = "classes" }
add{ q = { "mage stat priority", "what stats mage", "mage gear stats", "mage stat prio", "what stats for mage", "mage stats leveling", "what should mage gear for", "best stats mage 60", "frost mage stats", "what stats do i need on my mage", "what stats should i gear for on my mage while leveling and at 60", "mage stat priorty" }, a = "While leveling: Intellect/spell damage first, then Stamina/Spirit, then armor. Frost: spell damage > Int > MP5 > Stamina > Spirit. Arcane: Int > spell damage > Spirit > MP5, since it's mana-hungry. Mage Armor's Spirit regen was buffed, so it's good for longer fights.", class = "MAGE", topic = "classes" }
add{ q = { "best mage race", "mage race forever", "orc mage", "best race for mage", "what race mage forever", "is orc mage good", "best alliance mage race", "best horde mage race", "which race should i roll mage", "skyborne mage good?", "making a mage which race is best in forever alliance or horde", "best mage rase" }, a = "Alliance: High Order Skyborne is rated strongest (haste plus Read Ley Line regen), with Human and Gnome close behind. Horde: Orc (new for Mage) has the best burst from Blood Fury, Troll is close, and Undead is more RNG.", class = "MAGE", topic = "classes" }
add{ q = { "mage early wands weapons", "mage leveling items", "best mage gear leveling", "best mage leveling gear", "mage wand leveling", "mage weapons leveling", "what wand should mage use", "good items for mage leveling", "mage early gear", "what wands and staves should my mage pick up while leveling", "mage leveling iteams" }, a = "Useful leveling gear: crafted wands (Lesser, then Greater Magic Wand), Staff of Westfall, Emberstone Staff, Nightskulker Ring, Spidersilk Boots and Double-Stitched Woolen Shoulders. Lesser Wizard Oil and Elixir of Wisdom help too. The level 30 class wand quest is a nice mid-level upgrade.", class = "MAGE", topic = "classes" }
add{ q = { "mage beginner mistakes", "mage tips", "mage running out of mana", "mage leveling tips", "mage keeps going oom", "mage mistakes", "mage tips new players", "how to not die on mage", "im always out of mana on my mage", "i keep going oom on my mage and dying what am i doing wrong", "mage tipps" }, a = "Common mistakes: overcasting Arcane Blast or AoE until you have no mana left to escape, not conjuring water between pulls, sitting on Blink and Frost Nova, pulling aggro off the tank with AoE, and counting on procs (Fingers of Frost, Missile Barrage) without a backup plan.", class = "MAGE", topic = "classes" }
add{ q = { "hunter changes forever", "what's new hunter", "hunter forever abilities", "aimed shot baseline", "whats new for hunter in forever", "hunter changes", "what changed on hunter", "is aimed shot baseline now", "new hunter abilities forever", "hunter forever differences", "what did they change for hunters", "back from classic what did forever change about hunters", "huntar changes forever" }, a = "Hunter changes: Aimed Shot is baseline at 20 and shares a CD with Multi-Shot (Arcane Shot is separate). Traps work in combat on a shared 30s CD. Pets scale with your gear (10% of your AP, 100% of your crit) but can't get player buffs. Aspect of the Beast adds melee AP. Scorpid Sting now reduces hit by 2%.", class = "HUNTER", topic = "classes" }
add{ q = { "hunter pets forever", "pet family abilities", "what does each pet do", "fox pet", "what do pet families do", "pet family abilities forever", "what does each hunter pet do", "fox pet ability", "pet unique abilities", "which pet has what skill", "hunter pet families explained", "what unique abilities does each hunter pet family get in forever", "pet familys abilities" }, a = "Each pet family has a unique skill: Cat Prowl, Wolf Furious Howl (party AP), Boar Charge, Bear Swipe (3 targets), Gorilla Thunderstomp, Turtle Shell Shield, Wind Serpent Lightning Breath, Crocolisk Dismember (healing reduction), Bat Sonic Blast, Bird of Prey Mine! (disarm), Raptor Savage Rend, Spider Web, and Fox Trickster's Dance (new family). All families learn Bite or Claw, plus Dive or Dash.", class = "HUNTER", topic = "classes" }
add{ q = { "best hunter pet", "best pet for leveling", "best raid pet hunter", "cat or boar", "best pet hunter", "what pet should i get", "best pet for raids", "cat or boar leveling", "best hunter pet forever", "best pet for dungeons", "which pet for leveling", "just hit 10 on my hunter whats the best pet to tame for leveling and raids", "best huntr pet" }, a = "Leveling: Cat for damage, or Boar for durability and Charge. Raids and dungeons: Cat for damage, or Wolf for Furious Howl's party AP if you have no Battle Shout. PvP: Broken Tooth (Badlands rare cat, about 7-8h respawn), Wind Serpent, or utility pets like Crocolisk, Bat and Bird of Prey.", class = "HUNTER", topic = "classes" }
add{ q = { "best hunter leveling spec", "hunter leveling build", "bm leveling", "what spec should i level hunter", "hunter leveling spec forever", "bm leveling hunter", "best spec to level hunter", "hunter leveling talents", "is mm good for leveling", "im leveling a hunter which tree", "new hunter what spec should i level with bm or mm", "best hunter leveing spec" }, a = "Beast Mastery is the smoothest leveler: your pet tanks while you shoot. Rush pet talents toward Bestial Wrath, and take Pathfinding and Efficiency, then spill into Marksmanship. Don't take Lone Wolf while leveling, because your pet is your tank.", class = "HUNTER", topic = "classes" }
add{ q = { "lone wolf", "hunter without pet", "marksmanship forever", "sniper shot", "what is lone wolf", "hunter no pet spec", "marksmanship changes forever", "sniper shot talent", "mm hunter forever", "can hunter play without pet", "can i play hunter without a pet out with lone wolf is it good", "lone wolfe" }, a = "Marksmanship: Lone Wolf (11-pt) gives +20% damage with no pet out. Trueshot Aura is the 21-pt gold. Sniper Shot (31-pt) is a 4s cast, 15s CD, 45-yard shot that hits harder than Aimed Shot and adds 10 yards to your next 3 shots. Careful Aim converts Intellect into AP. Guides favor MM for group content.", class = "HUNTER", topic = "classes" }
add{ q = { "summon hawk", "beast mastery forever", "focused fire", "what does summon hawk do", "beast mastery changes forever", "focused fire talent", "bm hunter forever", "bm talents forever", "summon hawk cd", "playing bm what does summon hawk do and how does focused fire work", "sumon hawk" }, a = "Beast Mastery: Summon Hawk (16-pt) deals instant damage and summons a Hawk for 18s, up to 2 at once. It shares a CD with Arcane Shot, and the Nov 10 hotfix raised Hawk damage by about 80%. Focused Fire boosts your and your pet's damage while the pet is out. Endurance Training now includes Thick Hide.", class = "HUNTER", topic = "classes" }
add{ q = { "survival hunter forever", "melee hunter", "strider kick", "lacerating strikes", "survival hunter changes", "can hunter melee", "melee hunter forever", "strider kick talent", "lacerating strikes talent", "survival hunter talents", "is survival actually a melee spec in forever what does strider kick do", "survival hunter forver" }, a = "Survival is a melee/trap hybrid. Strider Kick (21-pt) is an instant hit plus 30% speed for 3s. Lacerating Strikes (31-pt) makes Mongoose Bite apply a 21s bleed. Expose Prey procs Mongoose Bite on your Hunter's Mark target, and Counterattack is the 16-pt. Wyvern Sting was removed. Guides call it the hardest spec to play.", class = "HUNTER", topic = "classes" }
add{ q = { "hunter taming quest", "how to tame pet", "hunter level 10 quest", "taming the beast", "how do i get a pet hunter", "hunter lvl 10 quest", "hunter taming quest where", "taming the beast quest", "how to tame first pet", "hunter pet quest", "just hit 10 on my hunter how do i get the pet taming quest", "hunter taming quets" }, a = "At level 10, your class trainer gives a Taming Rod and Taming the Beast, and Training the Beast unlocks pet training. Starting zones: Teldrassil (Night Elf), Dun Morogh (Dwarf), Mulgore (Tauren), Durotar (Orc) and Zephras Isle (Skyborne).", class = "HUNTER", topic = "classes" }
add{ q = { "hunter stat priority", "hunter hit cap", "what stats hunter", "hunter stat prio", "what stats for hunter", "hunter hit cap 60", "hunter stats leveling", "what should hunter gear for", "how much hit hunter", "what stats do i need on my hunter", "what stats should i gear for on hunter and how much hit do i need", "hunter stat priorty" }, a = "Leveling BM: Agility > AP > crit > Intellect > Spirit > Stamina. At 60, the effective boss hit cap is 9% with 300 weapon skill, and 5 weapon skill is roughly 3% hit. 53 Agility = 1% crit, and 14 AP = 1 DPS. Your pet takes 100% of your crit and 10% of your AP.", class = "HUNTER", topic = "classes" }
add{ q = { "hunter early weapons", "best bow leveling", "hunter leveling gear", "best hunter bow leveling", "hunter weapons leveling", "best gun leveling hunter", "hunter early ranged weapon", "good items for hunter leveling", "hunter early gear", "what bows and guns should my hunter grab while leveling", "best bow leveing" }, a = "Early ranged upgrades: Barbaric Crossbow (Ragefire Chasm), Calibrated Blunderbuss (Alliance quest), Venomstrike (Wailing Caverns), and Naga Heartpiercer or Fallenroot Longbow (BFD). Crafted Dark Leather Boots and Stalker's Leather Belt are solid. Restock ammo at every vendor.", class = "HUNTER", topic = "classes" }
add{ q = { "best hunter race", "hunter race forever", "human hunter", "best race for hunter", "what race hunter forever", "is human hunter good", "best alliance hunter race", "best horde hunter race", "which race should i roll hunter", "making a hunter which race is best for pve or pvp in forever", "best huntr race" }, a = "Alliance: Night Elf or Human for PvE (crit racials), and Dwarf or Human for PvP. Horde: Orc is strong for both (Command boosts pet damage 5%), Troll's Berserking is good for any spec, and Tauren gets crit damage. Skyborne haste suits BM and MM.", class = "HUNTER", topic = "classes" }
add{ q = { "hunter beginner mistakes", "hunter tips", "hunter traps combat", "hunter leveling tips", "hunter mistakes", "can traps be used in combat", "hunter tips new players", "how to not die on hunter", "im new to hunter any tips", "new to hunter what mistakes should i avoid while leveling", "hunter tipps" }, a = "Common mistakes: running out of ammo or water, spending all your mana and having none left for Feign Death or CC, taking Lone Wolf while leveling, Scare Beast pulling extra packs, and getting dazed in Aspect of the Cheetah. Also remember you must stand still 0.5s before Auto Shot fires.", class = "HUNTER", topic = "classes" }
add{ q = { "rogue changes forever", "what's new rogue", "rogue forever abilities", "shank", "whats new for rogue in forever", "rogue changes", "what changed on rogue", "what is shank", "new rogue abilities forever", "rogue forever differences", "what did they change for rogues", "back from classic what did forever change about rogues", "rouge changes forever" }, a = "Rogue changes: poisons have more charges and stack with sharpening and weight stones. Sap no longer breaks Stealth. Expose Armor is about equal to 5 Sunders. Rogues can use one-handed axes. Shank is new at 24 (off-hand strike, 10s CD). Poised (18) makes your next Energy ability cost 10 less when you're out of combat at full Energy.", class = "ROGUE", topic = "classes" }
add{ q = { "mutilate forever", "assassination rogue", "venom rogue", "mutilate changes forever", "assassination rogue forever", "how does mutilate work", "venom rogue spec", "assassination talents forever", "is mutilate good", "how does mutilate work in forever and do i need two daggers", "mutalate forever" }, a = "Assassination: Mutilate (21-pt) costs 60 Energy, gives 2 combo points and needs daggers in both hands. It deals 90% weapon damage plus extra to poisoned targets. Venom (31-pt) is a finisher that adds 30% poison damage. Cold Blood moved to 16-pt, and Murder was removed. Poisons gained higher AP scaling at launch.", class = "ROGUE", topic = "classes" }
add{ q = { "combat rogue forever", "hack and slash", "flawless execution", "combat rogue changes forever", "what is hack and slash", "flawless execution talent", "combat talents forever", "combat rogue weapon spec", "is combat good forever", "playing combat rogue what does hack and slash do with weapons", "combat rouge forever" }, a = "Combat: Hack and Slash replaces the four weapon specs (axe extra attacks, mace armor-pen, sword and dagger bonuses), so you can swap weapon types freely. Flawless Execution (16-pt) cuts Eviscerate's cost by 15 Energy. Weapon Expertise reduces your target's dodge and parry. Dual Wield Specialization is now 2 points (25/50%).", class = "ROGUE", topic = "classes" }
add{ q = { "subtlety rogue forever", "death mark", "boot knife", "sub rogue", "sub rogue changes forever", "what is death mark", "boot knife talent", "subtlety talents forever", "how does death mark work", "is sub good forever", "thinking about sub rogue what is death mark and boot knife", "subtelty rogue forever" }, a = "Subtlety: Death Mark (1 point, 25 Energy, 10s CD) is a finisher that stores part of your damage and releases it after 6s, and bleeds store at double rate. Boot Knife lets Shank add 2 combo points. Premeditation moved to 16-pt. Dirty Deeds allows Garrote from the front. Thousand Cuts, Quietus and Cutthroat were cut before launch.", class = "ROGUE", topic = "classes" }
add{ q = { "best rogue leveling spec", "rogue leveling build", "combat rogue leveling", "what spec should i level rogue", "rogue leveling spec forever", "combat leveling rogue", "best spec to level rogue", "rogue leveling talents", "is assassination good for leveling", "im leveling a rogue which tree", "just rolled a rogue what spec should i level combat or assassination", "best rouge leveling spec" }, a = "Combat is the most survivable leveling spec, and Hack and Slash lets you use whatever weapon drops. Assassination is weak early but strong once you have Mutilate and Venom. Subtlety Ambush or bleed builds work if you like opening from stealth.", class = "ROGUE", topic = "classes" }
add{ q = { "rogue poison quest", "how to get poisons", "rogue level 20 quest", "klaven's tower", "how do i get poisons", "rogue lvl 20 quest", "poison quest rogue", "klavens tower quest", "rogue poison quest horde", "rogue poison quest alliance", "where do rogues learn poisons", "hit 20 on my rogue how do i get the poisons quest", "rouge poison quest" }, a = "Poisons come from a level 20 class quest. Alliance: Mathias and the Defias from Mathias Shaw in Stormwind, then Klaven's Tower in Westfall. Horde: The Shattered Salute from Shenthul in Orgrimmar, then Deep Cover, Mission: Possible But Not Probable, and Hinott's Assistance in Hillsbrad.", class = "ROGUE", topic = "classes" }
add{ q = { "rogue new quests", "ruby-adorned blade", "eye of bhossca", "ravenholdt quest forever", "new rogue quests forever", "ruby adorned blade quest", "eye of bhossca quest", "ravenholdt quests forever", "rogue spy quest chain", "syndicate sabotage quest", "what are the new rogue quests in forever like ravenholdt and ruby blade", "rouge new quests" }, a = "Rogues have new Forever quests. Syndicate Sabotage (24) is a Ravenholdt chain. A spy chain starts with mail from C and a dead drop in Pyrewood Village, Silverpine (47.1, 71.1). It sends you to the Scarlet Monastery stables and Library, and the reward is the Ruby-Adorned Blade (Rogue-only sword, 2.30 speed).", class = "ROGUE", topic = "classes" }
add{ q = { "rogue stat priority", "what stats rogue", "rogue gear", "rogue stat prio", "what stats for rogue", "rogue stats leveling", "what should rogue gear for", "best stats rogue 60", "rogue agi or crit", "what stats do i need on my rogue", "what stats should my rogue be looking for on gear", "rouge stat priority" }, a = "While leveling: Agility > AP > Strength > Stamina > Armor. Later, guides put crit first, then Agility and AP. Hit and Expertise matter because hit now also applies to poisons.", class = "ROGUE", topic = "classes" }
add{ q = { "rogue early weapons", "best rogue dagger leveling", "rogue leveling items", "best rogue weapons leveling", "rogue dagger leveling", "best weapon for rogue leveling", "good items for rogue leveling", "rogue early gear", "what daggers and swords should my rogue grab while leveling", "best rouge weapons leveling" }, a = "Strong leveling weapons: Cruel Barb and Buzz Saw (Deadmines), Thief's Blade, Shadowfang, Assassin's Blade and Torturing Poker. Tunic of Westfall, Nightskulker Ring and crafted Dark Leather Boots are good too. Use Thistle Tea for burst Energy.", class = "ROGUE", topic = "classes" }
add{ q = { "best rogue race", "rogue race forever", "skyborne rogue", "best race for rogue", "what race rogue forever", "is skyborne rogue good", "best alliance rogue race", "best horde rogue race", "which race should i roll rogue", "making a rogue which race is best for pve or pvp in forever", "best rouge race" }, a = "Alliance: Human (Ruthless crit, stun-break for PvP), Night Elf for short fights, or Gnome for PvP. Horde: Orc is the best overall (Blood Fury burst, stun resistance), with Troll a strong alternative. Undead is strong in PvP thanks to Will of the Forsaken.", class = "ROGUE", topic = "classes" }
add{ q = { "rogue beginner mistakes", "rogue tips leveling", "rogue mistakes to avoid", "rogue tips", "rogue leveling tips", "rogue mistakes", "rogue tips new players", "how to not die on rogue", "im new to rogue any tips", "what am i doing wrong on my rogue", "new to rogue what mistakes should i avoid while leveling", "rouge tips" }, a = "Common mistakes: stealthing up to every mob (it's slow), switching targets with unspent combo points, letting Slice and Dice drop, damaging a mob you've just Gouged or Blinded, and running without food. Stealth only for dangerous pulls.", class = "ROGUE", topic = "classes" }
add{ q = { "priest changes forever", "what's new priest", "fear ward all priests", "shadow word death", "whats new for priest in forever", "priest changes", "what changed on priest", "do all priests get fear ward", "shadow word death forever", "new priest abilities forever", "what did they change for priests", "back from classic what did forever change about priests", "preist changes forever" }, a = "Priest changes: Fear Ward and Devouring Plague go to all Priests at 20, Divine Spirit is baseline at 30, and Shadow Word: Death at 32. If the target survives SW:D, you take 30% of your max HP (nothing on a miss). Fade's threat drop is doubled, and several Priests' Renews can stack on one target.", class = "PRIEST", topic = "classes" }
add{ q = { "priest racial spells", "priest racial quests", "divine grace", "contingency plan", "dark sacrifice", "what are priest racial spells", "priest racials forever", "priest racial quest", "what is divine grace", "gnome priest contingency plan", "undead priest dark sacrifice", "which priest race gets what spell", "what racial spells does my priest get at 10 and 20 for each race", "preist racial spells" }, a = "Every Priest race gets two racial spells via quests at 10 and 20. Human: Divine Grace and Feedback. Dwarf: Desperate Prayer and Chastise. Night Elf: Starshards and Elune's Grace. Gnome: Confounding Flash and Contingency Plan. Troll: Hex of Weakness and Shadowguard. Undead: Touch of Weakness and Dark Sacrifice.", class = "PRIEST", topic = "classes" }
add{ q = { "penance", "discipline priest forever", "disc priest", "divine aegis", "disc priest changes forever", "what does penance do", "penance level", "divine aegis forever", "discipline talents forever", "is disc good forever", "want to play disc what does penance do and when do i get it", "disipline priest forever" }, a = "Discipline: Penance is the 21-pt gold, a 2s channel on a 12s CD that damages enemies or heals allies (around level 30). Soul Warding (16-pt) cuts PW:Shield's CD and cost. Divine Aegis turns crit heals into shields, and Holy Precision gives up to 18% Holy hit. Beta guides rated Disc the top healer at level 30.", class = "PRIEST", topic = "classes" }
add{ q = { "holy priest forever", "prayer of mending", "holy binding", "binding heal", "holy priest changes forever", "prayer of mending level", "is binding heal removed", "what is holy binding", "holy priest talents forever", "is holy priest good", "playing holy priest what changed with prayer of mending and binding heal", "holy preist forever" }, a = "Holy: Prayer of Mending is the 31-pt gold (10s CD, jumps up to 5 times). Binding Heal was removed at launch. Holy Binding replaces it: Flash Heal on someone else also heals you for 50%. Litany of Light refunds mana when you alternate heals. Lightwell and Improved Prayer of Healing are gone.", class = "PRIEST", topic = "classes" }
add{ q = { "shadow priest forever", "shadowform changes", "vampiric embrace", "devouring contagion", "shadow priest changes forever", "vampiric embrace forever", "devouring contagion talent", "spriest forever", "shadow priest talents forever", "what changed about shadowform and vampiric embrace for shadow priests", "shadow preist forever" }, a = "Shadow: Shadowform (40) halves Shadow spell costs and doubles their crit bonus, and you can cast all non-healing spells in it. Vampiric Embrace is the 16-pt with a 30s CD. Shadow Weaving only buffs you, not other Priests. Devouring Contagion makes Plague jump when the target dies. Shadow Focus now gives hit.", class = "PRIEST", topic = "classes" }
add{ q = { "best priest leveling spec", "priest leveling build", "shadow or disc leveling", "what spec should i level priest", "priest leveling spec forever", "shadow or disc for leveling", "best spec to level priest", "priest leveling talents", "is disc good for leveling", "im leveling a priest which tree", "just rolled a priest should i level shadow or disc", "best preist leveling spec" }, a = "Shadow is the DPS route, but it's slow until around level 28 and Shadowform at 40. Discipline is a wand-and-shield leveler with low downtime, and it gets Penance around 30. Leveling as pure Holy is not recommended because kills are slow. Dual spec at 40 lets you keep a heal spec for dungeons.", class = "PRIEST", topic = "classes" }
add{ q = { "priest stat priority", "what stats priest", "shadow priest stats", "priest stat prio", "what stats for priest", "healer priest stats", "spriest stat priority", "best stats priest 60", "priest hit cap shadow", "what stats do i need on my priest", "what stats should my priest gear for healing vs shadow", "preist stat priority" }, a = "Healer: Healing Power > Intellect > MP5 > Spirit > crit. Shadow: hit to cap first, then Shadow/spell power > crit > Int > Spirit. While leveling, Int and spell damage come first, then Stamina and Spirit.", class = "PRIEST", topic = "classes" }
add{ q = { "priest early wands", "best priest wand leveling", "priest leveling items", "priest wands", "what wand should priest use", "priest weapons leveling", "good items for priest leveling", "priest early gear", "what wands should my priest use while leveling", "best preist wand" }, a = "Wands: Lesser Magic Wand (5) and Greater Magic Wand (13) from Enchanting, Sizzle Stick (Wailing Caverns quest), Gravestone Scepter (BFD quest) and Wand of Eventide (27, BoE). Keep cooked food handy for the XP buff.", class = "PRIEST", topic = "classes" }
add{ q = { "best priest race", "priest race forever", "gnome priest", "best race for priest", "what race priest forever", "is gnome priest good", "best alliance priest race", "best horde priest race", "which race should i roll priest", "making a priest which race is best in forever", "best preist race" }, a = "Alliance: Night Elf (Starshards, Elune's Light) looks strongest, and Gnome (Eureka! boosts PW:Shield, Contingency Plan) is close. Human and Dwarf add crit or hit. Horde: Undead (Touch of the Grave) looks strongest. Troll is weaker now that haste matters less.", class = "PRIEST", topic = "classes" }
add{ q = { "priest beginner mistakes", "priest tips", "what am i doing wrong priest", "priest leveling tips", "priest mistakes", "priest tips new players", "how to not die on priest", "im new to priest any tips", "new to priest what mistakes should i avoid while leveling", "preist tips" }, a = "Common mistakes: letting Power Word: Fortitude drop, running out of mana without water or potions, Psychic Scream fearing mobs into extra packs, trying to level as Holy, and forgetting that a Shadow Word: Death that doesn't kill costs you 30% of your HP.", class = "PRIEST", topic = "classes" }
add{ q = { "warlock changes forever", "what's new warlock", "banes warlock", "bane of agony", "whats new for warlock in forever", "warlock changes", "what changed on warlock", "what are banes", "bane of agony forever", "new warlock abilities forever", "lock changes forever", "back from classic what did forever change about warlocks", "warlok changes forever" }, a = "Warlock changes: Curse of Agony and Doom are now Banes (one Bane per Warlock per target), so you can run a Bane and a utility Curse together. Curse of the Elements covers all magic schools, and Curse of Shadows is removed. Pets scale with your stats. DoTs can crit and update every tick, with no snapshotting. Firestone and Spellstone are stackable weapon imbues.", class = "WARLOCK", topic = "classes" }
add{ q = { "best warlock leveling spec", "warlock leveling talents", "affliction leveling order", "what spec should i level warlock", "warlock leveling spec forever", "affliction leveling talents", "best spec to level lock", "warlock talent order leveling", "lock leveling build", "im leveling a lock which tree", "just made a warlock what talents should i take to level affliction", "best warlok leveling spec" }, a = "Affliction is the recommended leveling spec. Order: 10-17 Improved Corruption 5/5, then Suppression 3/5. 18-24 Unholy Power 5/5 and Demonic Energies 2/2. 25-30 Improved Drains 3/3, Amplify Curse and Improved Bane of Agony 2/2. 31-40 finish Suppression, Pandemic 3/3, Improved Life Tap and Soul Siphon 3/3. Then Shadow Mastery 5/5 and Wrack at 47.", class = "WARLOCK", topic = "classes" }
add{ q = { "warlock pet quests", "voidwalker quest", "succubus quest", "incubus", "felhunter quest", "warlock demon quests", "how do i get voidwalker", "how do i get succubus", "how to get incubus", "how do i get felhunter", "lock pet quests", "warlock pet quest levels", "how do i get my voidwalker succubus and felhunter quests on my lock", "warlok pet quests" }, a = "Demon quests: Voidwalker at 10 (Gakin's Summons in Goldshire, Gan'rul's in Razor Hill, Halgar's in Brill, or The Slaughtered Lamb for Gnomes). Succubus at 20 (Devourer of Souls), or the new Incubus. Felhunter at 30 (Seeking Strahad). The Horde Succubus chain is 8 quests across the Barrens and Stonetalon.", class = "WARLOCK", topic = "classes" }
add{ q = { "warlock mount quest", "felsteed", "dreadsteed quest", "how do i get felsteed", "lock mount quest 40", "warlock epic mount", "where is felsteed quest", "hit 40 on my lock how do i get the felsteed mount", "warlok mount quest" }, a = "Summon Felsteed is a short level 40 quest ending at Strahad Farsan in The Barrens. The epic Dreadsteed (60) starts with Mor'zul Bloodbringer in Burning Steppes and ends in a 5-player ritual in Dire Maul West. Inferno comes from Niby the Almighty in Felwood, and Ritual of Doom from Daio the Decrepit in the Blasted Lands.", class = "WARLOCK", topic = "classes" }
add{ q = { "orb of soran'ruk", "warlock level 20 quest", "staff of soranruk", "orb of soranruk quest", "warlock lvl 20 quest", "how do i get staff of soranruk", "soranruk fragments where", "lock 20 quest barrens", "doan karhan quest", "hit 20 on my lock where do i get the orb of soranruk quest", "orb of soran ruk" }, a = "The Orb of Soran'ruk (20) is from Doan Karhan in The Barrens (49.3, 57.2). Collect 3 Soran'ruk Fragments from Twilight's Hammer mobs in Blackfathom Deeps and 1 Large Fragment from Shadowfang Darksouls in Shadowfang Keep. Choose the Orb (off-hand) or the Staff (2H, Fire and Shadow damage).", class = "WARLOCK", topic = "classes" }
add{ q = { "wrack", "affliction warlock forever", "wrack nerf", "soul siphon", "what is wrack", "wrack nerfed", "affliction changes forever", "soul siphon talent", "affliction talents forever", "is affliction good forever", "playing affliction what is wrack and did it get nerfed", "rack warlock" }, a = "Wrack is Affliction's 31-pt: a 6s channel that ticks Shadow damage every second. Since the Nov 10 hotfix, it does 30% less damage, but your Corruption, Siphon Life and Bane of Agony tick 100% faster while you channel. Soul Siphon adds 4/8/12% to Drain and Wrack per active DoT, up to 36%.", class = "WARLOCK", topic = "classes" }
add{ q = { "demonology warlock forever", "demonic brand", "demonic sacrifice 2 hours", "demonic pact", "demonology changes forever", "what is demonic brand", "demonic sacrifice lasts 2 hours?", "demonic pact talent", "demo lock forever", "demonology talents forever", "playing demo how does demonic sacrifice and pact work now", "demonolgy warlock forever" }, a = "Demonology: Demonic Sacrifice (11-pt) lasts 2 hours. Demonic Pact (31-pt) keeps that buff when you summon a different demon. Demonic Brand makes Searing Pain low-threat and turns your pet's next 2 attacks into Fire or Shadow damage. Decimation makes Soul Fire cheap and fast on targets below 35%. Beta guides named Demo the best Warlock dungeon spec.", class = "WARLOCK", topic = "classes" }
add{ q = { "destruction warlock forever", "incinerate warlock", "bane of havoc", "conflagrate", "destruction changes forever", "incinerate forever", "what is bane of havoc", "conflagrate forever", "destro lock forever", "destruction talents forever", "thinking about destro what changed with conflagrate and bane of havoc", "destro warlok forever" }, a = "Destruction: Conflagrate is now 16-pt, and Bane of Havoc (21-pt) copies 15% of your damage onto the cursed target. Incinerate (31-pt) has a 2.5s cast and +25% damage vs Immolated targets. Shadow and Flame gives 4-20% and can keep Immolate from being consumed. It's the strongest dungeon burst but has the weakest leveling sustain.", class = "WARLOCK", topic = "classes" }
add{ q = { "warlock stat priority", "what stats warlock", "lock stat prio", "best stats for warlock", "warlock stat prio", "what stats for warlock", "warlock stats leveling", "does spirit help life tap", "best stats warlock 60", "lock stats 60", "what stats do i need on my lock", "what stats should i gear for on my lock while leveling and at 60", "warlok stat priority" }, a = "Leveling: wand DPS > spell power/Int > Stamina/Spirit (Life Tap now scales with Spirit). At 60: Affliction is Shadow/spell power > crit > hit. Demonology is spell power > hit > crit. Destruction is Fire/spell power > crit > hit.", class = "WARLOCK", topic = "classes" }
add{ q = { "best warlock race", "warlock race forever", "troll warlock", "best race for warlock", "what race warlock forever", "is troll warlock good", "best alliance warlock race", "best horde warlock race", "which race should i roll lock", "making a warlock which race is best in forever", "best warlok race" }, a = "Guides say the five races are close. Human and Orc are strong in PvE and PvP, and Orc's Command adds 5% pet damage. Undead (Will of the Forsaken) is best for PvP. Troll is new to Warlock, and Berserking suits Demo and Destro. Gnome's Eureka! doesn't boost DoTs, so it's weaker for Affliction.", class = "WARLOCK", topic = "classes" }
add{ q = { "warlock beginner mistakes", "warlock tips", "pet health warlock", "warlock leveling tips", "warlock mistakes", "lock tips new players", "how to not die on warlock", "my pet keeps dying warlock", "im new to lock any tips", "new to warlock what mistakes should i avoid while leveling", "warlok tips" }, a = "Common mistakes: casting Searing Pain without Demonic Brand (heavy threat), putting Curse of Recklessness on a mob you plan to Fear, DoTing mobs that are about to die, wanding at full mana, and Drain Life at full HP. Pets were buffed about 15% on Nov 10 but still have less HP than in Classic.", class = "WARLOCK", topic = "classes" }
add{ q = { "paladin changes forever", "what's new paladin", "holy strike", "seal of fury", "whats new for paladin in forever", "paladin changes", "what changed on paladin", "what is holy strike", "what does seal of fury do", "new paladin abilities forever", "pally changes forever", "back from classic what did forever change about paladins", "paldin changes forever" }, a = "Paladin changes: Holy Strike is new at 6 (instant, 50% weapon damage as Holy). Seal of Fury comes at 10: bonus Holy damage per swing plus a small absorb, and its Judgement taunts. Consecration is baseline at 20, Lay on Hands has a 20-minute CD, Judgement no longer uses up your Seal, Blessings last 1 hour, and Kings is baseline.", class = "PALADIN", topic = "classes" }
add{ q = { "blessing of salvation forever", "salvation removed", "paladin salvation", "is blessing of salvation gone", "was salvation removed", "salv removed forever", "no salvation forever", "pally salvation", "where is blessing of salvation", "my guild wants salv where did blessing of salvation go", "blessing of salvaton" }, a = "Salvation, Mass Salvation, Revoke and Blessing of Light were removed before launch (Nov 2 notes). Ignore older guides that say Salvation became a non-Blessing buff. Righteous Fury is now trained at level 10.", class = "PALADIN", topic = "classes" }
add{ q = { "righteous fury level", "paladin tank threat", "prot paladin forever", "templars bulwark", "prot paladin changes forever", "pally tank forever", "righteous fury lvl", "paladin threat forever", "templars bulwark talent", "how good is prot pally", "prot pally talents", "want to tank on my pally what changed for prot in forever", "prot paldin forever" }, a = "Prot: Righteous Fury (level 10) gives +33% threat plus 90% more from Holy damage. Seal of Fury's Judgement is a 10-yard taunt. Templar's Bulwark (21-pt) is an 8s absorb shield equal to 100% of your max HP (5-min CD). Holy Shield now requires Bulwark. Shieldsworn cuts Holy Strike's CD by 4s, and Holy Strike then hits with your shield. Beta guides rated Prot Paladin the top tank.", class = "PALADIN", topic = "classes" }
add{ q = { "ret paladin forever", "unsealed wrath", "seal twisting forever", "retribution changes", "ret paladin changes forever", "what is unsealed wrath", "can you seal twist forever", "retribution talents forever", "ret pally forever", "is ret good forever", "playing ret what is unsealed wrath and can i still seal twist", "ret paldin forever" }, a = "Retribution's 31-pt is Unsealed Wrath. Your swings store your current Seal (up to 3 stacks for 15s), and when you swap Seals, each stack can proc the old one. That's Forever's seal twisting (Twist of Light was cut). Vengeance stacks to 5, Conviction gives 2/4/6% crit to everything, and Sacred Arbiter (16-pt) boosts Holy Strike.", class = "PALADIN", topic = "classes" }
add{ q = { "holy paladin forever", "holy shock cooldown", "oath of light", "infusion of light", "holy paladin changes forever", "holy shock cd", "what is oath of light", "infusion of light talent", "holy pally forever", "holy paladin talents forever", "playing holy pally whats the holy shock cooldown now and what is oath of light", "holy paldin forever" }, a = "Holy: Holy Shock is now the 21-pt gold with a 10s CD. Oath of Light boosts your heals on one sworn ally (5 min, no CD). Boundless Light raises Holy Shock crit on other targets. Infusion of Light makes Holy Shock or Flash of Light crits shorten your next Holy Light, and Reverence adds casting regen. Divine Favor is now 16-pt.", class = "PALADIN", topic = "classes" }
add{ q = { "best paladin leveling spec", "paladin leveling build", "ret leveling paladin", "what spec should i level paladin", "pally leveling spec", "ret leveling", "best spec to level paladin", "paladin leveling talents", "prot pally leveling", "im leveling a pally which tree", "just rolled a paladin what spec should i level ret or prot", "best paldin leveling spec" }, a = "Put early points into Retribution even if you plan to tank later. Mid-levels: Ret for mana-efficient chain killing, or Prot for avoidance and big Consecration pulls. Shockadin isn't recommended for leveling. Paladins are slow but very safe levelers. Use Judgement and Holy Strike rather than only auto-attacking.", class = "PALADIN", topic = "classes" }
add{ q = { "paladin class quests", "verigans fist", "redemption quest", "paladin level 20 weapon", "verigans fist quest", "how do i get redemption", "paladin lvl 20 weapon quest", "pally class quest", "tome of divinity quest", "what quests do paladins get", "what class quests does my paladin get like redemption and verigans fist", "paldin class quests" }, a = "Redemption at 12 is The Tome of Divinity (Alliance trainer) or A Lesson in Divinity (Undead, Danitha Morr at Bandarion Keep). The Alliance level 20 weapon is The Test of Righteousness from Jordan Stilwell in Ironforge, using materials from DM, SFK, Thelsamar and BFD. It rewards Verigan's Fist. The level 40 Warhorse quest is The Tome of Nobility from Duthorian Rall in Stormwind.", class = "PALADIN", topic = "classes" }
add{ q = { "undead paladin quests", "bandarion keep", "wolfsbane", "forsaken paladin weapon", "where is bandarion keep", "forsaken paladin trainer", "wolfsbane quest", "undead pally weapon quest", "horde paladin class quests", "just made an undead paladin where do i go for my class quests", "undead paldin quests" }, a = "Forsaken Paladins train and quest at Bandarion Keep in the Whispering Wood (western Tirisfal Glades). Their trainers are in Deathknell, Brill and Bandarion Keep. Their weapon chain starts around 18 (A Moon-Kissed Blade, then Old Fire-Eye south of the Sepulcher) and rewards Wolfsbane, a 2H sword with bonus damage vs wolves and worgen. They also have their own Warhorse and Forsaken Charger quests.", class = "PALADIN", topic = "classes" }
add{ q = { "paladin stat priority", "what stats paladin", "prot paladin spell power", "paladin stat prio", "what stats for paladin", "pally stats leveling", "does prot pally need spell power", "best stats paladin 60", "ret pally stats", "what stats do i need on my pally", "what stats should my pally gear for as ret or prot", "paldin stat priority" }, a = "Ret: Strength/AP > Stamina > spell power > Int. Prot scales with spell power: SP > Stamina > Int > Strength. Use fast weapons as Prot (more Seal of Fury hits) and slow 2H weapons as Ret (Holy Strike, Seal of Command). Champion of the Light turns Int into spell power for Ret.", class = "PALADIN", topic = "classes" }
add{ q = { "best paladin race", "paladin race forever", "human or dwarf paladin", "best race for paladin", "what race paladin forever", "human or dwarf pally", "best alliance pally race", "best horde paladin race", "which race should i roll pally", "making a paladin which race is best in forever", "best paldin race" }, a = "Alliance: Human is the usual recommendation for Ruthless crit. Dwarf is solid with +1% hit and Stoneform's damage reduction. Horde: Undead is the only Paladin race. Touch of the Grave helps tank threat, and Cannibalize restores mana.", class = "PALADIN", topic = "classes" }
add{ q = { "paladin beginner mistakes", "paladin tips", "paladin mana problems", "pally leveling tips", "paladin mistakes", "pally keeps going oom", "pally tips new players", "how to not die on paladin", "im new to pally any tips", "new to paladin what mistakes should i avoid while leveling", "paldin tips" }, a = "Common mistakes: only auto-attacking (use Judgement and Holy Strike), forgetting to keep a Blessing and Aura up, skipping food and water, and running out of mana on chain pulls. Bring mana potions. Use Divine Protection or Blessing of Protection before you start healing in a bad fight.", class = "PALADIN", topic = "classes" }
add{ q = { "druid changes forever", "what's new druid", "druid potions in form", "druid polearm", "whats new for druid in forever", "druid changes", "what changed on druid", "can druids use potions in form", "can druids use polearms", "new druid abilities forever", "what did they change for druids", "back from classic what did forever change about druids", "druid chnages forever" }, a = "Druid changes: most potions and consumables work in form without shifting out, including Rage potions and Thistle Tea. Weapon enchants and procs work in form. Druids can use polearms from 20. Nature's Grasp is baseline at 10, Revive (out-of-combat res) comes at 12, and Omen of Clarity is baseline at 20. Faerie Fire works in feral forms.", class = "DRUID", topic = "classes" }
add{ q = { "druid cat form quest", "how to get cat form", "druid level 20 quest", "great cat spirit", "how do i get cat form", "cat form quest", "druid lvl 20 quest", "the great cat spirit quest", "where is cat form quest", "druid cat form level", "just hit 20 on my druid how do i get cat form", "druid cat from quest" }, a = "Cat Form is now a level 20 quest (The Great Cat Spirit, from Darnassus or Thunder Bluff), where you collect three relics from a barrow of cat spirits. Bear Form is still Heeding the Call at 10. Aquatic Form at 16 runs through Moonglade and rewards the Idol of Shifting Tides. Skyborne Druids get The Great Ursera Spirit (bear) on Zephras Isle.", class = "DRUID", topic = "classes" }
add{ q = { "best druid leveling spec", "druid leveling build", "feral leveling", "what spec should i level druid", "druid leveling spec forever", "feral leveling druid", "best spec to level druid", "druid leveling talents", "is balance good for leveling", "im leveling a druid which tree", "just rolled a druid what spec should i level feral or balance", "best druid leveing spec" }, a = "Feral Cat is the recommended leveling spec. Prowl and Dash give mobility, and you have little mana downtime. Balance (multi-DoT or Eclipse) works but is slower. Leveling as Resto isn't recommended. The guide's Feral build skips Shredding Attacks.", class = "DRUID", topic = "classes" }
add{ q = { "feral druid forever", "shifting power", "powershifting forever", "primal bite", "feral druid changes forever", "what is shifting power", "can you powershift forever", "primal bite talent", "is tigers fury gone", "feral talents forever", "playing feral is powershifting still a thing and what is shifting power", "feral druid forver" }, a = "Tiger's Fury is gone, and powershifting is replaced by Shifting Power, a talent that instantly grants Energy for mana (reworked to row 7 at launch). Shred is now 200% weapon damage and is learned at 20. Claw is 140%, Ravage 435%, and Rip, Rake and Bite are about 25% stronger. Berserk was removed at launch. Feral Charge also works in Cat Form.", class = "DRUID", topic = "classes" }
add{ q = { "bear tank forever", "druid tank threat", "lacerate", "thick hide defense", "bear tank changes forever", "how good is bear tank", "lacerate forever", "bear threat forever", "druid tanking forever", "want to tank on my druid is bear threat good in forever", "bear tank forver" }, a = "Bear: Bear and Dire Bear threat is 115% at launch, up from 50% in beta. Lacerate is a Feral talent (stacking bleed, high threat). Thick Hide gives armor from Defense on gear, so Defense items now help bears. Growl uses the Taunt cooldown, and Frenzied Regeneration can heal 100% of max HP. Beta guides rated bear the third-best tank.", class = "DRUID", topic = "classes" }
add{ q = { "resto druid forever", "wild growth", "swiftmend forever", "bloom", "resto druid changes forever", "what does wild growth do", "bloom talent", "resto talents forever", "is resto druid good", "playing resto druid what does wild growth do and how does swiftmend work", "resto druid forver" }, a = "Resto: Wild Growth (31-pt) is a party-wide HoT with a 3s cast and a 6s CD, and Nature's Swiftness makes it instant. Swiftmend (16-pt) no longer consumes your HoT. Bloom heals for 100% of your Spirit when Rejuvenation or Regrowth expires. HoTs can crit. Revive gives you an out-of-combat res.", class = "DRUID", topic = "classes" }
add{ q = { "balance druid forever", "moonkin forever", "eclipse druid", "insect swarm", "balance druid changes forever", "moonkin changes forever", "how does eclipse work", "insect swarm forever", "boomkin forever", "balance talents forever", "playing moonkin how does eclipse work in forever", "balence druid forever" }, a = "Balance: Eclipse makes Wrath shorten your next Starfires' casts. Insect Swarm (16-pt) is a DoT that lowers enemy hit. In Moonkin Form you can cast all non-healing spells, and Omen procs twice as often. Wrath is much cheaper but weaker, and Starfire got +40% base damage. Hurricane has no cooldown. Beta guides rated Balance the weakest Druid DPS.", class = "DRUID", topic = "classes" }
add{ q = { "druid stat priority", "what stats druid feral", "feral stats", "bear stats", "druid stat prio", "what stats for druid", "feral druid stats", "bear tank stats", "best stats druid 60", "balance druid stats", "what stats do i need on my druid", "what stats should my druid gear for as feral or bear", "druid stat priorty" }, a = "Feral: Strength/Agility/AP > Stamina/Int/Spirit > Armor. Bears now also benefit from Defense through Thick Hide. Balance and Resto level with Int/spell damage (or healing), then Stamina/Spirit. Your form attack speed is fixed, but its DPS matches your equipped weapon, so weapon DPS matters.", class = "DRUID", topic = "classes" }
add{ q = { "druid early items", "wolfshead helm", "druid leveling gear", "best druid leveling gear", "how do i get wolfshead helm", "druid leveling items", "idol of shifting tides", "good items for druid leveling", "druid early gear", "what items should my druid get while leveling like wolfshead", "wolfshead helm how" }, a = "Key leveling items: the Idol of Shifting Tides (Aquatic Form quest, cheaper shapeshifts), Wolfshead Helm (Leatherworking), Manual Crowd Pummeler (Gnomeregan), and the Embrace of the Viper set from Wailing Caverns, which also turns your Cat Form into a serpent.", class = "DRUID", topic = "classes" }
add{ q = { "best druid race", "druid race forever", "skyborne druid", "best race for druid", "what race druid forever", "is skyborne druid good", "best alliance druid race", "best horde druid race", "which race should i roll druid", "making a druid which race is best in forever", "best druid rase" }, a = "Alliance: High Order Skyborne (Read Ley Line regen, haste) or Night Elf (Elune's Light crit, Quickness dodge for bears). Horde: Tauren (War Stomp now works in forms, +5% HP for bears) or Windshaper Skyborne (Skysight speed, haste). Racials like Shadowmeld and War Stomp now work while shapeshifted.", class = "DRUID", topic = "classes" }
add{ q = { "druid beginner mistakes", "druid tips", "druid mistakes to avoid", "druid leveling tips", "druid mistakes", "druid tips new players", "how to not die on druid", "im new to druid any tips", "new to druid what mistakes should i avoid while leveling", "druid tipps" }, a = "Common mistakes: letting Mark of the Wild and Thorns drop, hoarding Innervate and Barkskin (Barkskin now works in forms), and forgetting water. Many still shift out to use potions, but you no longer need to. Learn your form keybinds early, because the kit is big.", class = "DRUID", topic = "classes" }
add{ q = { "shaman changes forever", "what's new shaman", "totem changes", "call of the elements", "whats new for shaman in forever", "shaman changes", "what changed on shaman", "totem changes forever", "what is call of the elements", "new shaman abilities forever", "shammy changes forever", "back from classic what did forever change about shamans and totems", "shamen changes forever" }, a = "Shaman changes: totems have a 1.0s GCD, buff totems last 5 minutes, and a totem bar tracks them. Call of the Elements (20), Spirits (30) and Ancestors (40) drop four preset totems at once after a 3s cast. Totemic Recall refunds 25% mana, and Totemic Call moves totems (30s CD). Weapon imbues last 60 minutes and stack with oils and stones.", class = "SHAMAN", topic = "classes" }
add{ q = { "windfury totem forever", "totem twisting", "grace of air windfury", "raid wide totems", "windfury totem changes", "is windfury raid wide now", "can you totem twist forever", "grace of air and windfury", "windfury totem forever how it works", "do windfury and flametongue stack", "do i still need to totem twist windfury or is it raid wide now", "windfurry totem forever" }, a = "Windfury and Flametongue Totems are now raid-wide buffs, not weapon enchants. They can't overlap with each other, but Grace of Air stacks with either, so there's no twisting. Strength of Earth and Grace of Air are raid-wide too. Since the Nov 10 hotfix, your own weapon imbue and a weapon totem work together.", class = "SHAMAN", topic = "classes" }
add{ q = { "best shaman leveling spec", "shaman leveling build", "enhancement leveling", "what spec should i level shaman", "shaman leveling spec forever", "enh leveling", "best spec to level shaman", "shaman leveling talents", "is elemental good for leveling", "im leveling a shammy which tree", "just rolled a shaman what spec should i level enh or elemental", "best shamen leveling spec" }, a = "Enhancement is the cleanest leveling path, with strong melee, Windfury and Ghost Wolf. Elemental works but struggles with mana. Wait for dual spec at 40 if you want to heal. Improved Ghost Wolf makes Ghost Wolf instant and usable indoors.", class = "SHAMAN", topic = "classes" }
add{ q = { "shaman totem quests", "earth totem quest", "call of fire", "call of water", "call of air", "how do i get earth totem", "how do i get fire totem", "how do i get water totem", "how do i get air totem", "totem quest levels", "shammy totem quest", "where do i get my earth fire water and air totem quests on shaman", "shamen totem quests" }, a = "Totem quests: Earth around 4, Fire (Call of Fire) at 10, Water (Call of Water) at 20 and Air (Call of Air) at 30. Water and Air start in Orgrimmar, Thunder Bluff or Ironforge. Dwarves have 4 new questlines through Dun Morogh, Loch Modan, Wetlands and Westfall, and Skyborne get their first totems on Zephras Isle.", class = "SHAMAN", topic = "classes" }
add{ q = { "shaman weapon quest", "rage of the storm", "tempest's weapons", "lightning's grasp", "rage of the storm quest", "tempests weapons quest", "lightnings grasp", "shaman lvl 30 weapon quest", "bathrah quest shaman", "just got call of air how do i do the shaman weapon quest", "shamen weapon quest" }, a = "After Call of Air (30), The Tempest's Weapons turns in to Bath'rah the Windwatcher in Alterac Mountains. It sends you to Charlga Razorflank in RFK, Twisted Totems across several zones, and a Thousand Needles event. Choose Rage of the Storm (Enh 2H mace, +10% Stormstrike), Lightning's Grasp (Ele) or Tidebringer's Claw (Resto).", class = "SHAMAN", topic = "classes" }
add{ q = { "enhancement shaman forever", "stormstrike nerf", "maelstrom weapon", "enh shaman", "enhancement shaman changes forever", "was stormstrike nerfed", "maelstrom weapon forever", "enh talents forever", "enhance shaman forever", "is enhancement good forever", "playing enh did stormstrike get nerfed and what is maelstrom weapon", "enhancment shaman forever" }, a = "Enhancement after the Nov 10 hotfix: Stormstrike is 100% weapon damage on an 8s CD. Mental Dexterity converts 33/66/100% of Int into AP. Maelstrom Weapon procs 6-10 times a minute by rank, and each stack cuts Lightning Bolt's cast and cost by 20%. Rage of the Farseer (31-pt) is a 3-minute, +30% attack speed self-cooldown.", class = "SHAMAN", topic = "classes" }
add{ q = { "can shaman tank", "enhancement tank", "shaman tank forever", "can shamans tank", "shaman tanking", "enh tank forever", "can shaman tank dungeons", "is shaman tank viable", "shammy tank", "can i tank dungeons as enhancement shaman in forever", "can shamen tank" }, a = "Enhancement is listed as a possible tank. Spirit Weapons with Rockbiter Weapon raise threat, and Earth Shock adds more, so it works in low-level dungeons. Guides doubt that Anticipation and Toughness give enough survivability for endgame raid tanking.", class = "SHAMAN", topic = "classes" }
add{ q = { "elemental shaman forever", "lava burst removed", "lightning overload", "lightning mastery", "elemental shaman changes forever", "was lava burst removed", "lightning overload forever", "lightning mastery talent", "ele shaman forever", "elemental talents forever", "playing elemental was lava burst removed what replaced it", "elemental shamen forever" }, a = "Elemental: Lava Burst was removed at launch, and Call of Thunder (+5% crit to Lightning Bolt and Chain Lightning) replaced it. Lightning Overload has a 10/20/30% chance to cast a free half-damage copy. Lightning Mastery (renamed Elemental Mastery, 31-pt) cuts Lightning Bolt's cast by 0.5s on a 3-minute CD. Lightning Bolt's base damage was raised.", class = "SHAMAN", topic = "classes" }
add{ q = { "resto shaman forever", "riptide", "water shield", "mana tide", "resto shaman changes forever", "what does riptide do", "water shield forever", "mana tide forever", "resto talents shaman forever", "is resto shaman good", "playing resto shaman what does riptide do now", "resto shamen forever" }, a = "Resto: Riptide (31-pt) is now a HoT only, with no initial heal, a 12s CD and about 40% lower cost. It boosts Chain Heal on that target. Water Shield (11-pt) gives mana when you're hit or when any of your spells crits. Mana Tide is now 16-pt. Beta guides rated Resto Shaman an A-tier healer.", class = "SHAMAN", topic = "classes" }
add{ q = { "shaman stat priority", "what stats shaman", "enhancement stats", "shaman stat prio", "what stats for shaman", "enh shaman stats", "elemental shaman stats", "resto shaman stats", "best stats shaman 60", "what stats do i need on my shammy", "what stats should my shaman gear for as enh ele or resto", "shamen stat priority" }, a = "Provisional (beta) priorities. Elemental: hit > haste > spell pen > spell power > Int > crit. Enhancement: weapon damage > hit/Expertise > Int/Strength > spell power > crit > Agility, and Int matters because of Mental Dexterity. Resto: healing power > Int > haste > MP5 > Spirit.", class = "SHAMAN", topic = "classes" }
add{ q = { "best shaman race", "shaman race forever", "dwarf shaman", "best race for shaman", "what race shaman forever", "is dwarf shaman good", "best alliance shaman race", "best horde shaman race", "which race should i roll shammy", "making a shaman which race is best in forever", "best shamen race" }, a = "Alliance: Dwarf is the only Shaman race (+1% hit from Artisan's Precision). Horde: Windshaper Skyborne is likely strongest (permanent haste, Skysight speed). Troll's Berserking is good for every spec, and Orc is good for PvP and burst. Tauren offers Shamans little.", class = "SHAMAN", topic = "classes" }
add{ q = { "shaman beginner mistakes", "shaman tips", "shaman mistakes to avoid", "shaman leveling tips", "shaman mistakes", "shaman tips new players", "how to not die on shaman", "im new to shammy any tips", "new to shaman what mistakes should i avoid while leveling", "shamen tips" }, a = "Common mistakes: dropping totems that don't help the fight, trying to totem-twist (Forever removed the need), poor mana management, and using new weapon types before training the skill. Also forgetting reagents: Ankhs for Reincarnation, Shiny Fish Scales for Water Breathing, and Fish Oil for Water Walking.", class = "SHAMAN", topic = "classes" }
add{ q = { "best tank forever", "tank tier list", "which tank is best", "what is the best tank", "best tank class forever", "tank tierlist forever", "which class tanks best", "best class to tank dungeons", "prot pally or warrior tank", "strongest tank forever", "trying to pick a tank class for forever which one is strongest right now", "best tank forver" }, a = "Beta tier lists (level 30, Oct 19) ranked Protection Paladin as the top tank (Seal of Fury taunt, Templar's Bulwark), then Prot Warrior, then Bear Druid. Bear threat was later raised to 115% and Warrior Defensive Stance to 80%, so expect 60 rankings to shift.", topic = "classes" }
add{ q = { "best healer forever", "healer tier list", "which healer is best", "what is the best healer", "best healer class forever", "healer tierlist forever", "which class heals best", "best class to heal dungeons", "strongest healer forever", "disc or resto shaman healer", "want to heal in forever which healer class is the strongest", "best healler forever" }, a = "Beta tier lists (level 30) ranked Discipline Priest as the top healer (Penance, shields), then Restoration Shaman and Restoration Druid, with Holy Priest as runner-up. Riptide and Wild Growth were reworked at launch, so 60 rankings may change.", topic = "classes" }
add{ q = { "best dps forever", "dps tier list", "strongest class forever", "what is the best dps", "best dps class forever", "dps tierlist forever", "which class does most damage", "best class for damage", "strongest dps spec", "what class should i play for dps", "which class does the most damage in forever right now", "best dps forver" }, a = "Beta tier lists (level 30) put BM and MM Hunter at the top, then Enhancement Shaman, Arms/Fury Warrior, Assassination/Combat Rogue and Demo Warlock. Mages were rated B for dungeon damage, and Balance lowest. Enhancement and Affliction were nerfed on Nov 10, so check current lists.", topic = "classes" }
add{ q = { "what new zones are in forever", "new zones wow forever", "whats new in forever zones", "list of new areas", "what zones did they add in forever", "new zones?", "any new zones in wow forever or just old ones", "where are the new zones", "how many new zones are there", "wat are the new areas in forever", "forever new maps list", "i heard forever has new zones which ones" }, a = "Forever adds four new zones: Zephras Isle (Skyborne start, 1-12), Riverglades (35-45, southeast Eastern Kingdoms), Shen'dralas (about 40+, between Desolace and Mulgore), and Mount Hyjal (level 60, through Darkwhisper Gorge in Winterspring). Dalaran is also back as a working city in Alterac Mountains with its own dungeon. In total there are 1,000+ new quests across 1-60.", topic = "content" }
add{ q = { "is the level cap still 60", "does forever raise level cap", "max level forever", "is there level scaling", "max lvl in forever", "can you go past 60 in forever", "is it still 60 cap", "do zones scale to my level", "level cap?", "is there level scaling like retail or no", "whats the max level in wow forever" }, a = "Yes, the cap stays at 60 and there is no level scaling, so zones get trivial or deadly depending on your level, just like Vanilla. There are no flying mounts either.", topic = "content" }
add{ q = { "how many new quests in forever", "does forever have more quests than classic", "quest density forever", "how many quests did forever add", "are there more quests than vanilla", "do i still need to grind mobs in forever", "new quest count forever", "is there enough quests to level without grinding", "lots of new quests?", "do zones have more quests now" }, a = "Over 1,000 new quests were added across levels 1-60. Many old chains got follow-ups and zones have up to about a third more quests than Classic, so you rarely need to grind or travel far to find quests.", topic = "content" }
add{ q = { "forever leveling route", "what zone should i level in", "zones by level forever", "where to quest at each level", "leveling zones list", "where should i level", "what zone for my lvl", "best zones to level in forever", "im lvl 25 where do i go", "leveling zones by level", "what zone should i be in at 30", "wher do i quest next", "zone order 1-60 forever" }, a = "Rough minimum levels: 1 starting zones/Zephras Isle; 10 Westfall, Loch Modan, Darkshore, Barrens, Silverpine; 15 Redridge, Stonetalon; 18 Ashenvale; 20 Wetlands, Hillsbrad, Duskwood; 25 Thousand Needles; 30 Alterac, Arathi, Desolace, STV; 35 Badlands, Dustwallow, Feralas, Riverglades, Swamp of Sorrows; 40 Shen'dralas, Tanaris, Hinterlands; 43 Searing Gorge; 45 Azshara, Felwood, Blasted Lands; 48 Un'Goro; 50 Burning Steppes, WPL; 53 Winterspring, EPL; 55 Silithus, Deadwind; 60 Mount Hyjal.", topic = "content" }
add{ q = { "alliance leveling route forever", "best alliance zones 1-60", "alliance route forever", "alliance zones 1-60", "best leveling route for alliance", "ally leveling route", "im alliance where do i level", "what zones for ally to go through", "alliance zone order forever", "best route ally 1-60", "im alliance and want the fastest zone order from 1 to 60" }, a = "Alliance: home zone to 10, then Westfall/Loch Modan/Darkshore (10-20), Redridge and Wetlands/Duskwood (15-30), then Stranglethorn/Arathi/Desolace (30-35). From 35 the new Riverglades is right next to Redridge with an Alliance base at Farholde Keep. Then Shen'dralas/Tanaris/Hinterlands (40s), Un'Goro/Felwood/WPL (48-55), EPL/Winterspring (53-60). Do each zone's new dungeon when you hit its range.", topic = "content" }
add{ q = { "horde leveling route forever", "best horde zones 1-60", "horde route forever", "horde zones 1-60", "best leveling route for horde", "im horde where should i level", "horde zone order forever", "best route horde 1 to 60", "what zones do horde go through", "hordie leveling path", "im horde and want the fastest zone order from 1 to 60" }, a = "Horde: home zone to 10, Barrens/Silverpine (10-20), Stonetalon/Ashenvale/Hillsbrad (15-30), then Thousand Needles, Desolace, Arathi, STV (25-40). At 35 Riverglades has a Horde base at Rog'mar (reach it by boat from Steamwheedle Port in Tanaris), and at 40 Shen'dralas opens south of Desolace. Then Tanaris/Feralas/Hinterlands, Un'Goro/Felwood/Azshara, and Plaguelands/Winterspring to 60.", topic = "content" }
add{ q = { "riverglades or stranglethorn", "is riverglades better than stv", "stv alternative forever", "where to level 35-45", "stv or riverglades", "should i do riverglades instead of stv", "is stv still worth it", "riverglades vs stranglethorn which is better", "where to lvl 35-45", "im 36 stv or riverglades", "best zone 35 to 45", "skip stv for riverglades?", "im level 37 should i keep doing stv or go to riverglades" }, a = "Riverglades is the new 35-45 option and is built as an alternative to Stranglethorn: 150+ quests in one contested zone, with Krol'dok Stronghold (40-45) inside it. It fills the late-30s slowdown that Classic had, so use it either instead of or alongside STV/Desolace/Dustwallow.", topic = "content" }
add{ q = { "what level for hyjal", "when should i go to hyjal", "hyjal level range", "is hyjal for leveling", "when can i go to hyjal", "hyjal what level", "can i level in hyjal", "is hyjal a 60 zone", "what lvl do i need for hyjal", "im 55 can i go hyjal yet", "hyjal min level", "im 54 is it worth going to hyjal yet or wait till 60" }, a = "Mount Hyjal is a level 60 endgame zone, though some quests open in the mid-50s (the postal bag chain needs 56). Getting in requires the Winterspring potion quest at 55. Treat it as your last stop after Winterspring and the Plaguelands, not a 50s leveling zone.", topic = "content" }
add{ q = { "should i do dungeons while leveling forever", "is dungeon spam good xp forever", "dungeon xp vs questing", "should i dungeon spam or quest", "is dungeon spamming good xp", "dungeons or questing faster", "best way to level dungeons or quests", "is it worth running dungeons while leveling", "dungeon xp good in forever?", "should i run dungeons on the way to 60" }, a = "Quest through each zone and finish with that zone's dungeon. Dungeon quests pay far more XP than Classic (Deadmines quests total about 18,450 XP vs 8,300), but mob XP is lower. Kill XP got a 50% buff on Nov 8-9, so reruns are better now, yet pure dungeon leveling is still slower than questing.", topic = "content" }
add{ q = { "can i get boosted in dungeons forever", "why no xp in dungeon", "dungeon boost xp forever", "high level friend dungeon no xp", "can i get boosted", "dungeon boosts work in forever", "why am i getting no xp in dungeon", "my 60 friend boosted me and no xp", "no xp in dungeons bug", "do boosts still work", "why are dungeon mobs giving 0 xp" }, a = "No. Since the Nov 13 hotfix, a dungeon kill gives zero XP to the whole party if that mob is trivial (grey) to anyone in the group. Party XP is otherwise based on each player's own level, not the highest member's.", topic = "content" }
add{ q = { "all new dungeons and levels", "new dungeon level list forever", "which new dungeon at my level", "new dungeons list", "what level are the new dungeons", "what dungeon should i do at my level", "list of forever dungeons", "new 5 mans forever", "which new dungeon for level 20", "all new dungeon level ranges" }, a = "New 5-mans: Hall of Thanes 13-18 (under Ironforge), Ruins of Lordaeron 15-20 (above Undercity), Excavation Site: Wetlands 24-29, City of Dalaran 28-33 (Alterac), The Drowned City 35-40 (off STV), Krol'dok Stronghold 40-45 (Riverglades), Alcaz Prison 48-53 (Dustwallow), Blackmaw Hold 55-60 (Azshara), Shaper's Terrace 58-60 (Un'Goro).", topic = "content" }
add{ q = { "leveling with friends forever", "group leveling changes", "quest items shared party forever", "party questing forever", "leveling with a friend", "is duo questing good in forever", "do quest items share in party", "questing in a group forever", "do we both get quest drops", "party leveling changes forever", "is it faster to level with friends", "me and my buddy are leveling together do we both get quest drops" }, a = "Quest item drops aren't fully shared, but the system favours whoever has fewer items, so groups finish together. Many specific items (Riverglades quest drops, Deadwood Key, Drop of Stolen Life, etc.) were hotfixed to drop for all eligible party members. New boat routes also make it easy to start together in another race's zone.", topic = "content" }
add{ q = { "do quests give gold at 60", "quest gold forever", "xp to gold conversion", "do quests give gold at max level", "quest gold at 60", "do i get gold instead of xp at 60", "quests give money?", "do 60s get gold from quests", "xp to gold at level cap", "does turning in quests at 60 give gold" }, a = "Since the Nov 10 hotfix most quests of level 48 and above also reward gold directly, which helps make up for max-level quest income.", topic = "content" }
add{ q = { "what changed in starting zones", "starting zone changes forever", "new quests in elwynn", "new stuff in durotar", "starting zone changes", "whats new in starting zones", "new quests in starting area", "are starting zones different in forever", "what changed in elwynn forest", "durotar changes forever", "new stuff in starter zones", "i used to play classic what changed in the starting zones" }, a = "All original starting zones got new quest givers, extra quests, vendors, class and profession trainers, and new rewards and recipes. Profession trainers now sit in the starting zones so you can pick up professions right away, and each race gets a guaranteed 6-slot quest bag early.", topic = "content" }
add{ q = { "starter bag quest", "how to get a bag early forever", "6 slot bag quest", "free bag starting zone", "how do i get a bag early", "first bag quest", "6 slot bag starting zone", "starter bag?", "free bag quest for new characters", "where do i get a bag at level 5", "is there a bag quest in starting zone" }, a = "Every race has a 6-slot bag quest: Human 'Book Return' (Marshal Dughan, Elwynn), Dwarf/Gnome 'Grund And Gozwin' (Grund Drokda, Dun Morogh), Night Elf 'Soft Saber Pelts' (Aldia, Teldrassil), Skyborne 'The Problem With Prideclaws' (Indari Sunseam), Undead 'Sticks And Bones' (Deathguard Bartholomew), Orc/Troll 'Carry Your Weight' (Furl Scornbrow, Durotar), Tauren 'Grace Of An'she And Mu'sha' (Seer Graytongue).", topic = "content" }
add{ q = { "8 slot bag quest forever", "early bag quests 10-15", "bag from quest westfall", "parts and pieces bag", "8 slot bag quest", "early 8 slot bag", "bag quest westfall", "poor old blanchy bag", "where to get bags at 10-15", "early bag quests forever", "bag quest around level 12", "where can i get an 8 slot bag around level 10 to 15" }, a = "Good early bags: Poor Old Blanchy (Verna Furlbrow, Westfall, now 8 slots), the Buzzbox chain from Auberdine (8 slots), and the new Ratchet quest 'Parts and Pieces' from Wrenix the Wretched for both factions (8 slots, level 14). Deviate Hides in Wailing Caverns and Vyrin's Revenge in Loch Modan give 10-slot bags.", topic = "content" }
add{ q = { "can i start in another race's starting zone", "level in different starting zone", "which starting zone is best forever", "can i level in a different starting zone", "best starting zone forever", "can my human start in dun morogh", "do other race starting zones", "which starting zone should i do", "go to another races start area", "what starter zone is best" }, a = "Yes, any character can run to another starting zone of its faction and quest there from level 1; the trip usually takes 10-25 minutes. Don't take a non-Skyborne to Zephras Isle, since the route is full of hostile mobs. Undead Paladins should stay in Tirisfal (most Horde Paladin trainers and early class quests are there) and Dwarf Shamans should start in Dun Morogh.", topic = "content" }
add{ q = { "how to unlock camping", "camping quest", "the great outdoors quest", "where do i learn camping", "how do i get camping", "camping skill forever", "where to learn camping", "great outdoors quest where", "how to unlock campfire camping", "camping unlock quest", "who teaches camping", "im level 5 and someone said i can learn camping where do i go" }, a = "Around level 5, find the adventurer standing just outside your starting zone's main quest hub and do their quests, starting with 'The Great Outdoors'. That unlocks the campsite system.", topic = "content" }
add{ q = { "kyle's gone missing forever", "is kyle quest in forever", "kyle the frenzied quest", "kyle quest forever", "is kyles gone missing in", "kyle the frenzied quest mulgore", "can you do the kyle quest", "where is kyles gone missing", "kyle missing quest tribute", "does forever have the kyle quest from tbc" }, a = "Yes, Blizzard added 'Kyle's Gone Missing' from Burning Crusade back in as a tribute (it was originally a Make-A-Wish quest). Ahab Wheathoof in Bloodhoof Village, Mulgore, offers it from level 5.", topic = "content" }
add{ q = { "zalazane too hard", "zalazane level 10 durotar", "cant kill zalazane", "zalazane is too hard", "how to kill zalazane", "zalazane solo", "cant beat zalazane", "zalazane level", "zalazane keeps killing me", "durotar zalazane quest too hard", "zalazane keeps killing me at level 9 how do i beat him" }, a = "Zalazane in Durotar is level 10 while the trolls around him are about 8, so he's tough solo at 8-9. Group up for him or come back a level or two later.", topic = "content" }
add{ q = { "what is zephras isle", "skyborne starting zone", "zephras isle level", "where do skyborne start", "whats zephras isle", "where do skyborne characters start out", "zephras isle what lvl range", "the floating island starting zone what is it", "tell me about the skyborne starting zone", "i just rolled a skyborne where am i starting", "zephras isle info" }, a = "Zephras Isle is the Skyborne starting zone for levels 1-12, a floating island in Skywall (the air elemental plane). It's a neutral sanctuary. Skyborne start in Thendal Village, and the main town is Valanaar near the southern tip. Both factions quest there, phased apart.", topic = "content" }
add{ q = { "zephras isle quest order", "zephras isle walkthrough", "skyborne leveling route 1-12", "skyborne 1-12 guide", "how to level skyborne", "zephras walkthrough", "zephras quest route", "what order do i do zephras quests", "skyborne leveling guide 1 to 12", "just made a skyborne what order should i do the zephras quests in" }, a = "Order: Thendal Village (Ailee Farheart's 'Coming of Age', then Rorian the Dayseeker) -> south road to Shen'dar Village (camping tutorial, Constable Aonda, set your hearth with Coriella Calmbreeze) -> Falaath Village (undercover Al'Aketh story) -> Valanaar and Gustberry Lowlands -> Shadowgale Forest -> East Pylon Watchtower and the finale. Group up for the tight-packed Ursera bear cave.", topic = "content" }
add{ q = { "skyborne class trainer", "where to train skyborne", "thendal trainer only to 6", "skyborne trainer", "thendal trainer only goes to 6", "skyborne class trainer location", "where do skyborne train after 6", "cant train past 6 skyborne", "skyborne trainers zephras isle", "my skyborne trainer stopped teaching me at 6 where do i train now" }, a = "Thendal Village trainers only teach up to level 6. After that, train in Shen'dar Village, whose trainers teach every rank. Valanaar also has class and profession trainers, a bank and an auction house.", topic = "content" }
add{ q = { "windstones zephras", "what are windstones", "harvesting windstones profession voucher", "what do windstones do", "windstone potions zephras", "how do i use windstones", "are windstones only usable on zephras isle", "windstone harvesting voucher", "i keep picking up windstones what are they for", "windstones explained" }, a = "Windstones are gathered on Zephras Isle and work as health and mana potions, but only on the island. The quest 'Harvesting Windstones' also gives a voucher for Herbalism, Mining or Skinning.", topic = "content" }
add{ q = { "blessing of zephras", "tornado speed buff", "how to travel fast zephras isle", "tornado buff", "zephras speed buff", "how to move fast zephras isle", "tornadoes give speed?", "travel fast on zephras", "speed buff skyborne zone", "is there a way to move faster on zephras isle before i have a mount" }, a = "Run through the tornadoes on Zephras Isle to get Blessing of Zephras, +40% movement speed. It stays until you attack a hostile mob. You can also use Walk on Air from the hill near 46.5, 51.4 to glide across the river toward Shen'dar Village.", topic = "content" }
add{ q = { "musical gustjumper pet", "zephras secret pet", "frog pet sing", "how do i get the singing frog pet", "musical gustjumper how to get", "secret pet on zephras isle", "sing to frogs pet", "where are the frogs you /sing at", "heard theres a hidden pet on zephras isle if you sing to frogs", "gustjumper pet location" }, a = "Type /sing at the frogs near the Shriekling Den on Zephras Isle to get the Musical Gustjumper pet.", topic = "content" }
add{ q = { "a last request quest", "corpse quest shen'dar highlands", "shadowsong family signet", "a last request", "shen'dar highlands corpse quest", "shadowsong signet", "corpse quest skyborne", "last request quest where", "quest from dead body on road zephras", "shadowsong family signet quest", "found a dead body on the road in shen'dar highlands with a quest what is it" }, a = "'A Last Request' is a level 8 quest from a corpse on the road in the Shen'dar Highlands. Loot the Bloody Note, clear the Al'Aketh outside West Pylon Watchtower, take the feather and Shadowsong Family Signet from the ground floor, kill the named boss on top, then turn in at the main building in Shen'dar Village.", topic = "content" }
add{ q = { "zephras isle ending", "how to leave zephras isle", "skyborne final quest", "how do i finish zephras isle", "last quest on zephras isle", "rohash fight skyborne", "how do i get off zephras isle", "the end of the skyborne campaign", "im done with zephras isle quests how do i leave the island", "zephras isle final boss" }, a = "The campaign ends with a fight against Rohash, Lord of the East Wind, when Alliance and Horde reinforcements arrive. Turn in to your faction leader (Ayessa Dawnsinger for Windshapers, Elaadrin Evengale for High Order), talk to Talaanis Shadowsong, and your leader sends you to the Valanaar skydocks to leave the island.", topic = "content" }
add{ q = { "skyborne alliance to stormwind", "zephras to ironforge", "how to get to stormwind as skyborne", "skyborne to stormwind", "how do skyborne get to stormwind", "alliance skyborne leave zephras", "where does ally skyborne go", "skycutter to dalaran", "skyborne alliance get to sw", "im an alliance skyborne how do i get to stormwind from zephras isle" }, a = "Alliance: take the eastern/left skycutter at Valanaar's sky harbour (about 64.9, 80.9) to Dalaran in Alterac Mountains, then use the Stormwind portal in the Violet Citadel. You arrive in Stormwind's Mage Quarter; take the Deeprun Tram from the Dwarven District for Ironforge.", topic = "content" }
add{ q = { "skyborne horde to orgrimmar", "zephras to thunder bluff", "how to get to orgrimmar as skyborne", "skyborne to orgrimmar", "how do skyborne get to org", "horde skyborne leave zephras", "where does horde skyborne go", "skycutter to mulgore", "skyborne horde get to org", "im a horde skyborne how do i get to orgrimmar from zephras isle" }, a = "Horde: take the western/right skycutter at Valanaar (about 58.2, 79.5) to Skywatcher Plateau in northwestern Mulgore, walk into Thunder Bluff, ride the central lift and fly from Tal to Orgrimmar. Tip: Skyborne can glide off the ship near the dock and land straight in Thunder Bluff.", topic = "content" }
add{ q = { "can non skyborne go to zephras isle", "visit zephras isle other race", "zephras airship everyone", "can other races go to zephras isle", "can non skyborne visit zephras", "zephras airship for everyone", "can my orc go to zephras isle", "how to get to zephras as human", "visit skyborne island", "zephras isle access other races", "can my human or orc take the airship to visit zephras isle" }, a = "Yes. The airships from Dalaran (Alliance) and Skywatcher Plateau (Horde) can be used by everyone, with or without the Skyborne pack. Finishing the Skyborne campaign itself needs the Heroic Pack. Don't level a new non-Skyborne character there, because the way in is full of hostile mobs.", topic = "content" }
add{ q = { "skyborne mount", "galestrider where to buy", "skyborne riding trainer", "galestrider", "where to buy galestrider", "what mount do skyborne get", "galestrider vendor", "skyborne racial mount", "my skyborne just hit 40 where do i buy a galestrider" }, a = "Skyborne ride Galestriders, bought at Fairweather Stables on Zephras Isle (about 53.8, 81.3) from Genn Fairweather, who also trains riding. Other races can buy them at Exalted with the High Order or Windshapers, earned through Zephras quests or cloth turn-ins to Belanaa Windveil (Dalaran) or Oura Stormspinner (Mulgore).", topic = "content" }
add{ q = { "skyborne alliance in hillsbrad danger", "skyborne level 12 dalaran what next", "where does skyborne go after zephras", "skyborne after zephras", "where do skyborne go at 12", "alliance skyborne dalaran what now", "skyborne hillsbrad dangerous", "im skyborne 12 where to quest", "skyborne lands in dalaran what next", "after zephras isle where", "im an alliance skyborne just landed in dalaran at 12 where do i quest now" }, a = "Alliance Skyborne land in Dalaran at about level 12, in Alterac Mountains, which is far too high for you. Take the portal to Stormwind straight away and quest Westfall/Elwynn or go on to Darkshore. Walking routes between the Alliance starting zones and the Dalaran side pass through dangerous Hillsbrad mobs. Horde Skyborne land at Skywatcher Plateau in Mulgore and can go straight on to the Barrens.", topic = "content" }
add{ q = { "what is riverglades", "riverglades level", "where is riverglades", "riverglades zone", "whats riverglades", "riverglades what lvl is it", "is riverglades alliance or horde or contested", "wher is the riverglades zone on the map", "tell me about the new riverglades zone", "riverglades good for 38?", "new 35-45 zone in eastern kingdoms where" }, a = "Riverglades is a new contested zone for levels 35-45 on the southeast coast of the Eastern Kingdoms, east of Redridge, Badlands and Burning Steppes and north of Swamp of Sorrows. It has 150+ quests and the Krol'dok Stronghold dungeon (40-45).", topic = "content" }
add{ q = { "how to get to riverglades alliance", "riverglades from redridge", "farholde keep how to get", "ally how do i get to riverglades", "how to get to riverglades from lakeshire", "path to farholde keep", "im alliance and cant find the way into riverglades", "riverglades entrance alliance side", "redridge to riverglades road", "where do alliance enter riverglades" }, a = "From Lakeshire, follow the road north to the signpost near the Burning Steppes gate and take the right-hand path into the Bristle Hills, then follow the road south to Farholde Keep, the Alliance base. Grab its flight path from Gretchen Mayberry.", topic = "content" }
add{ q = { "how to get to riverglades horde", "riverglades boat tanaris", "powderfuse port boat", "rog'mar how to get", "horde how do i get to riverglades", "riverglades boat from tanaris", "where is the boat to powderfuse", "steamwheedle port boat riverglades", "im horde how do i reach rog'mar", "horde entrance riverglades", "how do hordies get over to riverglades", "im horde how do i take the boat from tanaris to riverglades" }, a = "Horde: go to Gadgetzan, head east to Steamwheedle Port on the Tanaris coast and take the boat to Powderfuse Port, the neutral goblin town in Riverglades. Then follow the road to Rog'mar, the Horde base, and get its flight path. You can also walk in from Badlands or Swamp of Sorrows.", topic = "content" }
add{ q = { "riverglades hubs", "riverglades quest hubs", "riverglades towns", "bolder'ok", "where are the quest hubs in riverglades", "riverglades flight paths and towns", "what towns are in riverglades", "riverglades main hub alliance horde", "where do i pick up quests in riverglades", "bolderok where", "riverglades hub list" }, a = "Alliance: Farholde Keep (south, led by Knight Commander Demar Brant). Horde: Rog'mar (centre, on the main river) and Bolder'ok, an ogre town that broke from the Twilight's Hammer and joined the Horde. Neutral: Powderfuse Port (east coast, goblin). Hostile: Twilight's Hammer at Sunnyglade and Twilight's Shroud.", topic = "content" }
add{ q = { "powderfuse port", "riverglades goblin town", "powderfuse innkeeper", "where is powderfuse port", "whats in powderfuse port", "riverglades neutral town", "powderfuse inn", "is there a goblin town in riverglades", "powderfuse port innkeeper name", "where do i set hearth in riverglades neutral" }, a = "Powderfuse Port is the neutral Steamwheedle goblin town on the Riverglades east coast. Innkeeper Zizplink runs the inn, Melbin Powderfuse is the goblin engineer who runs the town, and Jazzle Cheapshot has an arena that isn't open yet. Boats go to Steamwheedle Port in Tanaris.", topic = "content" }
add{ q = { "riverglades story", "riverglades lore", "who lives in riverglades", "whats the story in riverglades", "who are the brotherhood of the horse", "what is going on in riverglades storyline", "who lives in the riverglades", "riverglades backstory", "why are humans fighting in riverglades", "what is the story of the riverglades and who are the people there" }, a = "Human survivors of the First and Second Wars (the Brotherhood of the Horse) are still fighting for their land. The Twilight's Hammer holds ruined Sunnyglade, and the old Horde army that besieged Farholde retreated to Krol'dok Stronghold. Expect ogres, gnolls, murlocs and Twilight cultists.", topic = "content" }
add{ q = { "bloodmaster's ring", "jezap jinglesprocket", "riverglades ring quest", "how do i get bloodmasters ring", "how does the jezap quest chain work", "wheres jezap jinglesprocket", "what ring does riverglades give", "who gives the bloodmaster ring quest", "where do i start the bloodmaster's ring quests in riverglades", "jezap ring quest" }, a = "Jezap Jinglesprocket in Riverglades gives the quests that reward the Bloodmaster's Ring. They were fixed in the Nov 9 and Nov 13 hotfixes, so they should work now.", topic = "content" }
add{ q = { "riverglades twilight enforcer hard", "twilight forgemaster mark of flames", "riverglades too hard", "twilight enforcer one shots me", "riverglades mobs hit way too hard", "were riverglades mobs nerfed", "twilight enforcer smash too strong", "riverglades too hard solo", "why is riverglades so hard", "the twilight enforcers in riverglades keep one shotting me is that a bug" }, a = "Several Riverglades mobs hit far too hard at launch. On Nov 11 Twilight Enforcer's Smash and Executioner Morg's damage were lowered, and Twilight Forgemaster's Mark of Flames now adds 50 damage instead of 1,000.", topic = "content" }
add{ q = { "poison tips glade vipers", "gaseous gold amount", "riverglades woodpiles", "not enough glade vipers poison tips", "poison tips quest vipers", "gaseous gold drop amount", "riverglades woodpiles quest", "cant find glade vipers", "riverglades quest bugs fixed", "poison tips taking forever", "poison tips quest in riverglades has hardly any glade vipers what do i do" }, a = "Known Riverglades quest fixes: many more Glade Vipers were added for 'Poison Tips', 'Gaseous Gold' now shows the right required amount, and woodpiles can only be looted while you're on their quest.", topic = "content" }
add{ q = { "krol'dok stronghold where", "kroldok entrance", "riverglades dungeon", "wheres krol'dok stronghold", "how do i get into kroldok", "kroldok location", "ogre dungeon riverglades where", "krol dok stronghold door", "i followed the ogre trail but cant find the krol'dok entrance", "krol'dok what level" }, a = "Krol'dok Stronghold is a level 40-45 ogre 5-man in the Riverglades. Follow the trail of ogre outrunners to the fortress. The ogres there have been kidnapping travellers and raiding settlements.", topic = "content" }
add{ q = { "what is shen'dralas", "shendralas level", "where is shen'dralas", "shen dralas zone", "whats shen'dralas", "shendralas what level", "wher is shen'dralas", "shen dralas zone info", "new kalimdor zone between desolace and mulgore", "tell me about shendralas", "shen'dralas good for 42?", "is shen'dralas a good zone to level in at 40" }, a = "Shen'dralas is a new contested zone in central Kalimdor, southeast of Desolace and between Feralas and Mulgore (roughly where Lake Dumont is in retail). It's aimed at about level 40+. The story covers the Shen'dralar Highborne of Eldre'Thalas/Dire Maul and the Magram, Gelkis and Kolkar centaur.", topic = "content" }
add{ q = { "how to get to shen'dralas", "shendralas entrance", "valley of bones", "how do i get to shen'dralas", "shendralas entrance where", "valley of bones desolace", "path into shen dralas", "shen'dralas from desolace", "where do you walk into shendralas", "how to reach shen'dralas", "how do i walk into shen'dralas from desolace through the valley of bones" }, a = "Walk in from southern Desolace through the Valley of Bones. Following the Desolace centaur questlines south leads you there. No boat or special transport goes there.", topic = "content" }
add{ q = { "shen'dralas hubs", "shendralas quest givers", "shendralas areas", "shen'dralas quest hubs", "where do i get quests in shendralas", "shendralas towns", "shen dralas areas list", "who gives quests in shen'dralas", "magram front outcast hideaway", "shendralas hub names", "where are the quest hubs once i get into shen'dralas" }, a = "Known areas include Magram Front, Outcast Hideaway, Bristleback Retreat, Evenshade Overlook and the Valley of Bones. There's no separate Alliance or Horde base, and the factions involved are the Shen'dralar, Magram clan and Bristleback quilboar. Expect level 43ish mobs such as Magram Marauders.", topic = "content" }
add{ q = { "cant mount in shen'dralas", "shendralas mount bug", "why cant i mount shendralas", "why cant i mount in shen'dralas", "shen dralas mount bug", "mount not working shendralas", "is the shendralas mount bug fixed", "stuck on foot in shen'dralas", "shendralas no mounting", "every time i try to mount in shen'dralas it says i cant is that a bug" }, a = "A bug stopped players from mounting in Shen'dralas's named areas. It was fixed in the Nov 11 hotfix.", topic = "content" }
add{ q = { "how to get to hyjal", "mount hyjal entrance", "darkwhisper gorge demons", "hyjal access", "how do i get to hyjal", "hyjal entrance", "wher is the way into hyjal", "mount hyjal access winterspring", "im 55 how do i get into hyjal", "hyjal how to get there" }, a = "Go through Darkwhisper Gorge in southern Winterspring. Elite demons guard it, so at 55 first do 'Shroud of the Winter Wilds' from Evie Whirlbrew in Everlook (60.8, 37.8). It gives a Potion of Winterspring Shrouding that lets you stealth past them. Then grab both Hyjal flight paths so you never have to walk the gorge again.", topic = "content" }
add{ q = { "hyjal flight path", "hyjal flight masters", "tainted foothills flight", "summit of eternity flight", "hyjal fp", "where are the flight masters in hyjal", "tainted foothills flight master", "summit of eternity fp", "is there a flight path in hyjal", "hyjal flights", "where do i pick up the flight paths once im in mount hyjal" }, a = "Hyjal has two flight masters: Bluebell in the Tainted Foothills (55.0, 82.8) and Fayran Elthas at the Summit of Eternity (68.6, 44.0). Tainted Foothills links to Everlook, so after unlocking it you can fly in from Winterspring.", topic = "content" }
add{ q = { "hyjal hub", "summit of eternity", "hyjal main town", "hyjal vendors", "hyjal main hub", "summit of eternity where", "whats at summit of eternity", "hyjal vendors where", "main town in hyjal", "hyjal repair vendor", "where do i hearth in hyjal", "where is the main town in hyjal with vendors and a repair guy" }, a = "Summit of Eternity near Nordrassil is Hyjal's main hub, with vendors, profession and supply NPCs, and the Hyjal Summit raid nearby. Tainted Foothills is the lower travel hub. Zone areas include Shrine of Aviana, Elderwild, Dae'gun, Mourning's Rest, Felblood Scar, Malorne's Retreat and Cradle of Tranquility.", topic = "content" }
add{ q = { "hyjal 18 slot bag", "hyjal postal satchel", "free bag quest hyjal", "hyjal postal clasp", "run speed trinket", "hyjal free 18 slot bag", "hyjal postal satchel quest", "18 slot bag quest hyjal", "hyjal postal clasp trinket", "sebelia quest", "mending communications quest", "hyjal run speed trinket", "how do i get the free 18 slot bag from the postal quest in hyjal" }, a = "Talk to Sebelia at Summit of Eternity (70.8, 51.4) at level 56+. 'Mending Communications' sends mail to Innkeeper Vizzie in Everlook, 'Unfrozen Deliveries' has you take 4 Missing Mail from Ice Thistle Yetis southeast of Everlook, and 'Top of the Post' takes you back to Sebelia. Rewards: Hyjal Postal Satchel (18-slot bag) and Hyjal Postal Clasp (trinket, +5% run/swim speed).", topic = "content" }
add{ q = { "hyjal reputations", "guardians of hyjal rep", "barkskin burrow", "hyjal factions", "what reps are there in hyjal", "what factions are in mount hyjal", "how do i get guardians of hyjal rep", "how do i get barkskin burrow rep", "hyjal reputation rewards", "what reputations should i grind in hyjal at 60", "hyjal faction list" }, a = "Hyjal has the Guardians of Hyjal (patterns from Aisarra Nightmeadow at Summit of Eternity; Revered gives the Rousing Seed Pod, raising your Artisan's Tier equip limit to two) and the Barkskin Burrow furbolgs, who trust you only after you fight the Deadwood. Full reward lists aren't confirmed yet.", topic = "content" }
add{ q = { "feathers in flight hyjal owl nests", "cant loot owl nest hyjal", "owl nest not lootable feathers in flight", "feathers in flight", "hyjal owl nest not lootable", "feathers in flight bug", "owl nests wont loot", "feathers in flight quest broken", "why cant i loot owl nests", "i cant loot the owl nests for feathers in flight is it bugged" }, a = "For 'Feathers in Flight', the Hyjal Owl Nests couldn't be looted below level 60 at launch. The Nov 9 hotfix fixed this, so any level can now loot them.", topic = "content" }
add{ q = { "hyjal raids", "where is hyjal summit raid", "barrow deeps entrance", "when do raids open", "hyjal raids when", "when do raids open in forever", "raid release date forever", "hyjal summit entrance", "barrow deeps where", "when do the hyjal raids open and where are the entrances" }, a = "Both Hyjal raids open on Dec 9, 2026, along with Onyxia's Lair. Hyjal Summit (20-player) is at the top of the mountain near Nordrassil. Barrow Deeps (10-player) is inside Mount Hyjal, with entrances linked through Hyjal, Winterspring and Blackmaw Hold.", topic = "content" }
add{ q = { "where is dalaran forever", "is dalaran in forever", "dalaran location", "how to get to dalaran", "where is dalaran", "how do i get to dalaran", "dalaran in alterac?", "wher is dalaran city", "dalaran on the map", "how do i get to dalaran in alterac mountains from southshore" }, a = "Dalaran is back as a working city where the crater used to be, in Alterac Mountains northwest of Hillsbrad. Alliance can walk in from Southshore, use the portal in Stormwind's Mage Sanctum, or take the skyship from Zephras Isle. It has a flight master, trainers, a stable master, a barber and battlemasters.", topic = "content" }
add{ q = { "can horde enter dalaran", "horde dalaran guards", "dalaran horde access", "can horde go into dalaran", "is dalaran alliance only", "horde dalaran guards attack", "dalaran horde", "why do dalaran guards attack me horde", "can my undead enter dalaran", "im horde and the dalaran guards keep attacking me can i go in" }, a = "Not the city itself. Dalaran is effectively Alliance-only, and Horde players get attacked by guards and teleported out. Horde can still run the City of Dalaran dungeon through the sewer entrance after the Tarren Mill attunement chain.", topic = "content" }
add{ q = { "dalaran trainers", "dalaran profession trainers", "dalaran mage trainer", "trainers in dalaran", "dalaran mage trainer where", "what class trainers in dalaran", "where is the druid trainer in dalaran", "dalaran trainer list", "where are the class and profession trainers in dalaran" }, a = "Dalaran trainers: Mage Jessa Weaver (17.7, 69.7), Druid Alfina Nightgaze (by the skyship landing), First Aid Angelique Butler, Enchanting Vanessa Sellers, Cooking Katherine Lee, Herbalism Edward Egan, Blacksmithing at 19.6, 63.3, Tailoring Charles Worth, Alchemy Linzy Blackbolt. Stable master Talia Softglen is at the Magic Menagerie.", topic = "content" }
add{ q = { "dalaran sewer key horde", "city of dalaran attunement horde", "key to the city", "prison break in", "key to the city horde", "prison break in quest", "horde dalaran dungeon attunement", "how do horde get into city of dalaran dungeon", "dalaran attunment horde", "magus wordeen voidglare" }, a = "Horde, level 30: Magus Wordeen Voidglare in Tarren Mill (61.5, 20.9) gives 'Prison Break In' (4 Bloodstone pieces from Lordamere Internment Camp) and 'Key to the City' (Grimy Key from Warden Belamoore's house). Then do 'Dalaran Patrols' (6 Summoners, 8 Elemental Slaves) and 'Blood in the Streets', which ends at Archmage Modera's image by the sewer (68.5, 45.1). That gives the Dalaran Sewer Key, and one key per group is enough.", topic = "content" }
add{ q = { "dalaran dungeon alliance quests", "an alarming request", "city of dalaran alliance start", "city of dalaran alliance quests", "alliance dalaran dungeon start", "emissary jaques southshore", "how do ally start dalaran dungeon", "dalaran dungeon alliance attunement", "where does the alliance dalaran chain start", "im alliance how do i start the quests for the city of dalaran dungeon" }, a = "Alliance: get 'An Alarming Request' from Emissary Jaques in Southshore (48.3, 60.1). It opens 'Starving Arcane' and 'Heart of Disruption' from Archmage Modera's image at the sewer (68.5, 45.1). Also take 'Power Overwhelming' from High Sorcerer Andromath in Stormwind's Mage Quarter and 'A Green Sample' from Shylamiir in Stormwind Park. Turn in the Arcane Mote to Archmage Celindra in the Violet Citadel.", topic = "content" }
add{ q = { "new boats forever", "new travel routes forever", "stormwind harbor boat", "forever transport changes", "any new boats or zeppelins in forever", "what travel routes did forever add", "is there a boat in stormwind harbor now", "new transport options", "did they change boats in forever", "how has travel changed from classic", "new boat routes list" }, a = "New routes: a Stormwind Harbor boat to Auberdine, Southshore added to the Auberdine-Menethil boat loop, Zephras Isle skyships to Dalaran (Alliance) and Skywatcher Plateau (Horde), a Dalaran-to-Stormwind portal, and a neutral boat from Steamwheedle Port (Tanaris) to Powderfuse Port (Riverglades). The old boats, zeppelins and tram are all still there.", topic = "content" }
add{ q = { "night elf to stormwind", "skip wetlands run", "darnassus to stormwind boat", "auberdine to stormwind", "how do night elves get to stormwind", "nelf to sw without wetlands", "do i still have to run through wetlands as a night elf", "boat from darnassus to stormwind?", "auberdine to stormwind boat", "fastest way from teldrassil to stormwind", "im a nelf how do i get to stormwind to train" }, a = "Night elves don't have to do the Wetlands death run any more. Take the Rut'theran boat to Auberdine, then the new boat from Auberdine straight to Stormwind Harbor, and Humans can go the other way to Darkshore. There's also a one-way loop: Auberdine to Menethil to Southshore and back to Auberdine.", topic = "content" }
add{ q = { "southshore boat", "boat from southshore", "menethil to southshore", "is there a boat to southshore", "southshore boat route", "how do i get from menethil to southshore", "where does the southshore boat go", "boat from southshore to auberdine", "southshore dock which boats", "can i take a boat to hillsbrad" }, a = "Southshore now has a boat stop on a one-way loop: Auberdine to Menethil to Southshore and back to Auberdine. It's handy for Hillsbrad and Alterac questing and for the Dalaran dungeon.", topic = "content" }
add{ q = { "riding level forever", "when can i get a mount", "mount cost forever", "apprentice riding cost", "what level do you get a mount", "how much does riding cost", "when can i ride", "mount at 40 or 30 in forever", "how much gold for apprentice riding", "how much g for my first mount", "im 39 how much gold do i need for mount" }, a = "Apprentice Riding is at level 40 for 100g from your race's riding instructor, and it includes your first basic mount (+60% speed). Extra colours cost 20g. Journeyman (epic) riding is level 60 for 1,000g, and epic mounts are 200g each. Being Honored with your home faction cuts riding and mount prices by 10%.", topic = "content" }
add{ q = { "camp taurajo flight thunder bluff", "horde flight path changes", "taurajo flight stuck", "camp taurajo to thunder bluff flight bugged", "flight path clipping taurajo", "did they fix the taurajo flight", "horde flight path changes forever", "taurajo fp broken", "my flight from taurajo gets stuck", "my flight from camp taurajo to thunder bluff keeps getting stuck" }, a = "The Camp Taurajo to Thunder Bluff flight used to clip through objects, which the Nov 9 hotfix fixed. Horde Skyborne can use Thunder Bluff's flight master (Tal) to reach Orgrimmar for 50 copper.", topic = "content" }
add{ q = { "azeroth commerce authority", "aca location", "where is aca redridge", "waylaid crate turn in alliance", "where is the aca", "aca camp location", "where do alliance turn in waylaid crates", "azeroth commerce authority where", "aca redridge three corners", "ally waylaid crate turn in spot", "where is azeroth commerce authority camp", "im alliance where do i take my waylaid crates to turn in" }, a = "The Azeroth Commerce Authority (Alliance) camp is at Three Corners in Redridge (about 9.7, 71.8). Turn Waylaid Crates in to Marcy Baker, buy rep rewards from Tamelyn Aldridge and mounts from Huey Sunnydale, and each profession has its own recipe vendor there.", topic = "content" }
add{ q = { "durotar supply and logistics", "dsl location", "waylaid crate turn in horde", "dsl barrens", "where is dsl", "dsl camp location", "where do horde turn in waylaid crates", "durotar supply and logistics where", "dsl near crossroads", "horde waylaid crate turn in spot", "where is durotar supply and logistics camp", "im horde where do i take my waylaid crates to turn in" }, a = "Durotar Supply and Logistics (Horde) is just west of the Crossroads in the Barrens (about 49.4, 28.9). Turn in Waylaid Crates to Dokimi, buy rep rewards from Gishah and mounts from Okamache, and each profession has its own recipe vendor there.", topic = "content" }
add{ q = { "waylaid crates how", "merchant's favor how to get", "craftsman's writ", "pack kodo mount", "how do waylaid crates work", "what do i put in a waylaid crate", "how to get merchants favor", "whats a craftsmans writ", "how do i get the pack kodo", "are waylaid crates worth doing", "waylaid crate rewards" }, a = "Waylaid Crates drop in the world (or buy them on the AH). Fill one with any single item from its list and turn it in for rep and Merchant's Favor, and the first turn-in gives a Shipping Label quest worth 50 Favor. Craftsman's Writs drop from mobs and start timed delivery quests. Top rewards: Reins of the Pack Kodo (Exalted, 6,000 Favor) and profession recipes costing 30-240 Favor.", topic = "content" }
add{ q = { "pix xizzix", "weekly quest booty bay", "undermine satchel", "tarnished undermine reals", "who is pix xizzix", "booty bay weekly quest", "in demand weekly quest", "what are tarnished undermine reals for", "how to get undermine satchel", "pix weekly dungeon quest where", "is there a weekly in booty bay", "what is the weekly quest from pix xizzix in booty bay and what does it give" }, a = "Pix Xizzix in Booty Bay (about 28.4, 75.8) gives a level 60 weekly 'In Demand' dungeon quest (Ancient Elven Curiosities, Blackrock Legal Records, Plague Records or Titan Relics) that rewards an Undermine Satchel. She also trades gear, reagents and recipes for Tarnished Undermine Reals, which drop from level 55+ dungeon bosses. Her weeklies clear at weekly reset.", topic = "content" }
add{ q = { "library books", "garion wendell", "owen thadd", "book turn in rewards", "where to turn in books", "where do i turn in books", "library books forever", "garion wendell where", "owen thadd book turn in", "what do the books give", "found a book where do i turn it in", "book collecting rewards" }, a = "Books are scattered around the world (inside buildings, caves and dungeons). Alliance turns them in to Garion Wendell in Stormwind's Mage Tower (49.0, 86.3) and Horde to Owen Thadd in Undercity's Magic Quarter (74.0, 32.5). Each book gives XP and silver. At 10 books you pick a neck, at 20 (level 20) a ring, and at 25 (level 30) Truthseeker's Bow, Crest of Elucidation or Researcher's Night Light. Deleted books can't be looted again.", topic = "content" }
add{ q = { "might of stormwind", "warchief's blessing forever", "rend buff forever", "world buff rend alliance", "rend buff alliance", "can alliance get the rend buff", "might of stormwind buff", "warchiefs blessing in forever", "where do ally turn in rends head", "rend head turn in stormwind", "does rend buff work for both factions", "can alliance get the rend world buff now and where do i turn in the head" }, a = "Rend's head now buffs both factions. Alliance turn it in to Master Mathias Shaw in Stormwind for Might of Stormwind, and Horde to Thrall for Warchief's Blessing. The buff gives +300 health, +15% haste and 10 mp5 for 1 hour and lasts through death. It only reaches players in Stormwind/Goldshire/Lakeshire/Sentinel Hill or Orgrimmar/Crossroads/Razor Hill, and it doesn't work in raids.", topic = "content" }
add{ q = { "do world buffs work in raids forever", "chronoboon forever", "world buffs dungeon", "do world buffs work in raids", "are world buffs removed in dungeons", "chronoboon in forever", "do i lose world buffs entering raid", "world buffs in raids forever", "is there chronoboon", "do world buffs matter in forever", "do world buffs stay on when i zone into a raid in forever" }, a = "No. World buffs are removed when you enter dungeons and raids in Forever, so they only help in the open world. The Chronoboon Displacer can only be used in the open world.", topic = "content" }
add{ q = { "cozy sleeping bag", "how to get sleeping bag forever", "sleeping bag quest start", "and that note you found", "how do i get the cozy sleeping bag", "where does the sleeping bag quest start", "nailed plank westfall", "and that note you found quest", "sleeping bag quest horde", "cozy sleepin bag how to get" }, a = "From level 14, Alliance click the Nailed Plank in Westfall (37, 50) and Horde click the Burned-Out Remains in the south Barrens (46, 74). That starts a no-combat scavenger hunt: the other one of those two spots, then Stonetalon near Sun Rock Retreat, the Carved Figurine at Stonewrought Dam in Loch Modan (49, 12), and the Messenger Bag on top of Thoradin's Wall in Hillsbrad. You get the Cozy Sleeping Bag plus Student Fodder and a 12-slot Old Toolbox/Lunchbox.", topic = "content" }
add{ q = { "what does cozy sleeping bag do", "sleeping bag xp buff", "is sleeping bag worth it", "what does the sleeping bag do", "is the cozy sleeping bag worth getting", "sleeping bag rested xp", "does sleeping bag give rested anywhere", "sleeping bag xp bonus", "whats the point of the sleeping bag", "can i log out on sleeping bag for rested" }, a = "Lying on it counts as a rested area, even while logged out, so you earn rested XP anywhere. It also gives up to 3 Well-Rested stacks of +1% kill XP each, and they last through death.", topic = "content" }
add{ q = { "night watchman's torch", "duskwood torch", "night watch guard corpse", "how to get the duskwood torch", "dead night watch guard duskwood", "night watchman torch quest", "where is the night watch guard corpse", "duskwood torch only at night?", "how do i start the night watchman torch quest" }, a = "In Duskwood after 20:00 game time, find the dead Night Watch Guard (yellow ! over the body). Check Raven Hill (18.1, 55.2) first, then the south and west of the zone. Use /target Night Watch Guard. The torch makes light for 5 minutes and goes out in combat, water or cities. If you delete it, you can get another.", topic = "content" }
add{ q = { "satchel of potions", "changing tastes quest", "lost in the thicket things", "heartwoven", "satchel of potions quest", "how do i get satchel of potions", "changing tastes quest borstan", "lost in the thicket quest", "potion bag quest", "where does changing tastes start", "heartwoven quest", "how do i get the satchel of potions bag as horde or alliance" }, a = "Horde: 'Changing Tastes' from Borstan, the Orgrimmar cooking trainer. Alliance: 'Lost In The Thicket Things' from Caitlin Grassman in Wetlands, then 'Heartwoven' from Ardin Grassman inside Excavation Site: Wetlands, then back to Caitlin. The trinket has a 10-minute cooldown and randomly gives a healing, mana or swiftness potion effect, or burns you for 216.", topic = "content" }
add{ q = { "malignant root ring", "nightveiled rotheap", "rethiel the greenwarden", "wetlands rare ring", "where is nightveiled rotheap", "wetlands rare elite ring", "rethiel the greenwarden quest", "how to get malignant root", "rotheap spawn location", "wetlands swamp elite ring drop", "where does nightveiled rotheap patrol in the wetlands for the ring" }, a = "Kill Nightveiled Rotheap, a level 31-32 elite that patrols the Wetlands swamp waters toward the dam. It drops Rotheap Innards for every group member. Pick 'I found something' at Rethiel the Greenwarden (56.4, 40.5) to trade them for Malignant Root, a ring with stamina, spell power and attack power and no level requirement. Alliance only, since Rethiel is hostile to Horde.", topic = "content" }
add{ q = { "scarlet banner", "scarlet monastery echoes", "library statues order", "how to get the scarlet banner", "scarlet monastery echoes locations", "sm library statues order", "where are the scarlet echoes", "scarlet banner quest", "echoes quest order", "what order do i click the statues in sm library" }, a = "Collect 4 Echoes: Arathi (62.2, 54.0, Go'shek Farm), Theramore (63.5, 42.4, Dustwallow graveyard), Swamp (16.8, 53.6, Splinterspear Junction) and one in SM Graveyard. In SM Library use them on the statues in this order: Warrior gets Swamp, Mage gets Arathi, Paladin gets Theramore, Priest gets Graveyard. The banner is a cosmetic camp decoration. A wrong order means resetting the instance.", topic = "content" }
add{ q = { "barrens rare set", "blessing of kalimdor set", "humar takk set", "signet of the zhevra", "which rares drop the barrens set", "humar takk set pieces", "barrens rares drop blues", "where do i get blessing of kalimdor set", "signet of zhevra drop", "which rares in the barrens drop the blessing of kalimdor set pieces", "barrens set bonus" }, a = "Forever rares can drop set pieces. In the Barrens, Humar the Pridelord, Takk the Leaper and Swiftmane drop the Blessing of Kalimdor set (level 20): Mark of the Pack Leader (neck), Raptor Hide Cloak and Signet of the Zhevra (ring). 2 pieces give +5% movement speed in the Barrens and Stonetalon.", topic = "content" }
add{ q = { "do rares drop better loot forever", "rare mobs worth killing", "rare set items", "do rares drop good loot in forever", "are rares worth killing", "rare mobs drop set items?", "should i hunt rares", "rare loot better in forever", "rares drop blues now", "worth camping rares while leveling", "is it worth hunting rares while leveling in forever for the loot" }, a = "Yes, some open-world rares now drop blue set items, like the Barrens set that gives bonus run speed, so they're worth killing while you level. Several rare respawn timers were also tuned after launch, such as Ferocitas in Teldrassil and Ivar the Foul in Silverpine.", topic = "content" }
add{ q = { "darkmoon faire forever", "when is darkmoon faire", "darkmoon faire location", "when does the darkmoon faire come", "dmf this month where", "wher is dmf right now", "is darkmoon faire in elwynn or mulgore", "what week is darkmoon faire", "dmf schedule forever", "when does dmf open and close", "when and where is the darkmoon faire this month" }, a = "The Faire starts setting up on the first Friday of each month, opens the following Monday and runs a week. It alternates between Elwynn Forest and Mulgore, and your in-game calendar shows which. Its staff are neutral, so both factions can go.", topic = "content" }
add{ q = { "darkmoon storage box", "14 slot bag darkmoon", "darkmoon tickets fastest", "how do i get the dmf 14 slot bag", "darkmoon storage box how many tickets", "fastest way to farm darkmoon tickets", "best dmf ticket turnins", "im trying to get the darkmoon bag whats quickest", "dmf bag cost", "quick darkmoon tickets" }, a = "Gelvas Grimegate sells the 14-slot Darkmoon Storage Box for 50 tickets. Fast route: the intro quest gives 5 tickets, and six turn-ins of Green Iron Bracers to Kerri Hicks give 48 more.", topic = "content" }
add{ q = { "fishing extravaganza forever", "stranglethorn fishing tournament", "when is fishing contest", "when is the stv fishing contest", "fishing tournament what time", "booty bay fishing extravaganza", "what fishing lvl do i need for the tourney", "is the fishing contest every sunday", "stranglethorn fishing contest rewards", "how does the fishing extravaganza work" }, a = "Every Sunday at 2 pm server time in Booty Bay. You need 150+ fishing. The first players to hand 40 Speckled Tastyfish to Riggle Bassbait win, up to 250 per week, so it's no longer one winner per realm. Winners get the Master Angler title, an Arcanite Fishing Pole and a coin to spend on prizes. Jang and Fishbot 5000 trade leftover fish for smaller rewards.", topic = "content" }
add{ q = { "darkspear islands battleground location", "new battleground forever", "darkspear islands level", "where is the darkspear islands bg", "whats the new battleground", "darkspear islands what level", "how do i queue for darkspear islands", "new bg in forever?", "is darkspear islands 15v15", "battle for the darkspear islands info", "where is the new darkspear islands battleground and what level do i need" }, a = "Battle for the Darkspear Islands is a new 15v15 battleground off the coast of Dustwallow Marsh for levels 30-60. Darkspear Raiders fight the Theramore Expeditionary Force over four capture points and a central flag, and the first team to 2,000 points wins.", topic = "content" }
add{ q = { "vorsha the lasher bug", "sleeper has awakened kerlonian horn", "darkshore escort fix", "vorsha the lasher hitting the whole zone", "kerlonian horn not working", "the sleeper has awakened bugged", "did they fix darkshore escorts", "vorsha escort broken", "darkshore escort quest fix", "kerlonian keeps falling asleep quest", "is the vorsha the lasher escort in darkshore fixed now" }, a = "Darkshore fixes from Nov 6: 'Vorsha the Lasher' no longer hits everyone in the zone, and in 'The Sleeper Has Awakened' you now start with the Horn of Awakening for Kerlonian Evershade.", topic = "content" }
add{ q = { "worgen in the woods not enough mobs", "duskwood nightbane spawns", "worgen in the woods hard to find mobs", "cant find nightbane for worgen in the woods", "duskwood nightbane spawns too low", "did they add more nightbane", "worgen in the woods quest takes forever", "nightbane vile fang spawns", "duskwood worgen quest mobs contested" }, a = "On Nov 10 Duskwood got more Nightbane Vile Fangs and Tainted Ones for 'Worgen in the Woods', so the quest should be quicker to finish now.", topic = "content" }
add{ q = { "mulgore too many quillboar", "starting area respawn too fast", "dun morogh troggs respawn", "quillboar respawn way too fast mulgore", "dun morogh troggs keep respawning", "starting zone respawn rate", "mobs respawning on top of me starting area", "did they slow respawns in starter zones", "venture co respawn mulgore", "respawns too fast new character" }, a = "Spawn rates were turned down in a few starting areas: Mulgore's quilboar and Venture Co. (Nov 13) and the Grol'bolar Quarry troggs in Dun Morogh (Nov 6). STV tigers, panthers and raptors, on the other hand, spawn more often now.", topic = "content" }
add{ q = { "zones too crowded forever", "layer population forever", "too many players questing", "zone way too crowded", "too many people in starting zone", "layer pop caps forever", "can they add more layers its packed", "zones overcrowded at launch", "how many players per layer", "did blizzard lower zone population", "the zone is so crowded i cant tag anything did they fix layers" }, a = "On Nov 9 Blizzard lowered player population caps in crowded zones, with a bigger cut on the PvP ruleset, so mobs should be less contested.", topic = "content" }
add{ q = { "unending torment quest ruins of lordaeron", "the baron abominable head", "abominable head quest level", "unending torment quest", "what do i do with the abominable head", "the baron drops abominable head", "what level is unending torment", "abominable head ruins of lordaeron quest", "baron head quest horde", "abominible head quest" }, a = "The Abominable Head from The Baron in Ruins of Lordaeron starts 'Unending Torment' for Horde at level 15 (it was 16 before the Nov 6 hotfix).", topic = "content" }
add{ q = { "shatterspear trolls xp", "shatterspear no xp", "should i kill shatterspear trolls", "do shatterspear trolls give xp", "should i grind shatterspear trolls", "shatterspear no xp anymore", "why am i getting 0 xp from shatterspear", "shatterspear farm nerfed", "is shatterspear still good xp", "killing shatterspear trolls worth it" }, a = "Since Nov 10, Shatterspear Trolls give no XP when you kill them, so don't farm them for leveling.", topic = "content" }
add{ q = { "skywatcher plateau", "where do horde skyborne arrive", "skywatcher plateau mulgore", "where is skywatcher plateau", "where do horde skyborne land", "skywatcher plateau in mulgore", "whats at skywatcher plateau", "horde skyborne arrive where", "skywatcher plateau near thunder bluff", "skyborne horde landing point", "where do horde skyborne land when they leave zephras isle" }, a = "Skywatcher Plateau is a new landing point in northwestern Mulgore, just outside Thunder Bluff, where the Horde skyship from Zephras Isle docks. Oura Stormspinner there takes cloth for Windshaper reputation.", topic = "content" }
add{ q = { "farholde keep npcs", "farholde flight master", "farholde keep vendors", "whats at farholde keep", "farholde keep flight master name", "farholde keep vendors and inn", "does farholde have a repair guy", "farholde keep npcs list", "where is the flight path at farholde", "farholde innkeeper", "what npcs are at farholde keep like flight master and innkeeper" }, a = "Farholde Keep (Alliance, southern Riverglades) has flight master Gretchen Mayberry, an inn, food vendors Penny Pinderton and Cassandra Wheeler, and stable master Wheatley. Knight Commander Demar Brant leads it, and other NPCs include Foreman Bertrand Ironbrow and Interrogator Ravenwing.", topic = "content" }
add{ q = { "innkeeper dungeon info", "ask innkeeper about dungeons", "which dungeon should i do innkeeper", "can the innkeeper tell me which dungeon", "innkeeper dungeon suggestions", "how do i know what dungeon to run", "ask innkeeper what dungeon", "tell me about the dungeons innkeeper option", "what dungeon for my lvl innkeeper", "innkeepers recommend dungeons?" }, a = "Innkeepers have a dialogue option, 'Tell me about the dungeons I can explore', that suggests dungeons for your level. Its answers were improved in the Nov 10 hotfix.", topic = "content" }
add{ q = { "what's coming next forever", "forever roadmap", "next content patch forever", "spring 2027 forever", "whats coming next in forever", "when is the next content patch", "what comes after the dec raids", "is hardcore coming to forever", "forever future plans", "whats planned for spring 2027", "whats coming next for forever after the december raids" }, a = "Dec 9, 2026 brings the Barrow Deeps, Hyjal Summit and Onyxia raids. Hardcore comes in winter 2026/27. Spring 2027 adds two raids, two dungeons, new quests and a new playable area, plus a legendary questline. Summer 2027 adds a revamped classic raid, another new raid, more world content and two more dungeons.", topic = "content" }
add{ q = { "when do raids open", "raid release date forever", "when does ony open", "raid unlock date", "when is phase 1 raids", "raids open when", "when do the raids come out in forever", "is ony open yet or still locked", "what day do the launch raids unlock", "my guild wants to plan around raid release what date is it", "raid realese date?", "how long until we can raid barrow deeps and hyjal" }, a = "All three launch raids unlock on December 9, 2026, for level 60 characters: The Barrow Deeps (10-player), Hyjal Summit (20-player) and Onyxia's Lair (40-player). Game launch was November 4, so there is roughly a five-week leveling window before raids.", topic = "dungeons" }
add{ q = { "what raids are in forever", "list of raids", "which raids at launch", "raids in wow forever", "what raids can i do", "raids at launch?", "which raids can i do when i hit 60", "forever raid list", "are there new raids or just old classic ones", "how many raids are out at launch in forever", "just dinged 60 what raids are there to do", "what raid tier is first" }, a = "At launch: The Barrow Deeps (10 players, 8 bosses, Mount Hyjal), Hyjal Summit (20 players, 13 bosses, top of Mount Hyjal) and Onyxia's Lair (40 players, 1 boss, Dustwallow Marsh). Molten Core, Blackwing Lair, ZG, AQ and Naxx are not launch raids.", topic = "dungeons" }
add{ q = { "raid lockout", "when do raids reset", "raid reset weekly", "ony lockout", "is ony 5 day reset", "raid reset day", "how often do raids reset in forever", "is onyxia a 5 day lockout or weekly", "weekly lockout barrow deeps", "can i run hyjal summit more than once a week", "do all the raids reset on the same day", "lockout timer ony" }, a = "Blizzard says all three launch raids (Barrow Deeps, Hyjal Summit, Onyxia's Lair) are planned to reset weekly. That includes Onyxia, which reset every 5 days in Classic. Blizzard has not published finer lockout rules yet (e.g. whether you can run more than one group a week).", topic = "dungeons" }
add{ q = { "raid roadmap", "next raids forever", "spring 2027 raids", "future raids", "what raid comes next", "next raid forever?", "what raids are coming after the launch ones", "forever raid roadmap", "what raid is in spring 2027", "whats the plan for future raids in forever", "when is the next raid tier coming out", "upcoming raids" }, a = "Roadmap: Spring 2027 brings two new raids (one 10-player, one 20-player), two new dungeons, a new zone and the first legendary questline. Summer 2027 adds one new raid, a revamp of one Classic raid (not yet named) and two more dungeons. Every tier is planned to have a 10 and a 20-player raid.", topic = "dungeons" }
add{ q = { "is molten core in forever", "when is mc coming", "molten core release", "mc forever", "bwl naxx forever", "mc in forever?", "is molten core coming to forever", "will there be bwl or naxx", "when do we get molten core", "can i do mc in forever or is it removed", "are the old classic 40 man raids coming back", "mc release date forever" }, a = "Molten Core is not a launch raid, and Blizzard has not dated MC, BWL, ZG, AQ or Naxxramas. Their instances exist in the beta client data, and the quest Attunement to the Core is in the Blackrock Depths data. Summer 2027 includes one revamped Classic raid, still unnamed.", topic = "dungeons" }
add{ q = { "will there be 40 man raids", "raid sizes forever", "why is hyjal 20 man", "10 man raids", "are raids 40 player", "any 40 mans?", "are there 40 man raids in forever", "why is hyjal summit only 20 people", "do we need 40 players for anything", "raid sizes in forever 10 20 or 40", "my guild only has 25 people can we raid", "are all raids 10 man now" }, a = "Forever is built around 10 and 20-player raids. Lead designer Tim Jones said every tier will have one 10-player and one 20-player raid. Onyxia's Lair (40) is the exception, and big 40-player Classic raids will not return in large numbers.", topic = "dungeons" }
add{ q = { "scarlet enclave raid", "nightmare grove raid", "new raids in data", "storm cliffs raid", "crystal vale raid", "future raids datamined", "is the scarlet enclave coming to forever", "what raids are in the game files", "crystal vale raid when", "heard about a nightmare grove raid is that real", "datamined raid names forever", "unreleased raids list" }, a = "The Scarlet Enclave (from Season of Discovery) is a confirmed future Forever raid with no date. The beta client also lists Nightmare Grove, Storm Cliffs, The Crystal Vale and The Tainted Scar as raids, plus Classic raids, but none of these have dates or details yet.", topic = "dungeons" }
add{ q = { "what is barrow deeps", "barrow deeps raid", "bd raid info", "barrow deeps 10 man", "barrow deeps bosses", "barrow deeps info", "whats the barrow deeps", "how many bosses in barrow deeps", "tell me about the 10 man raid barrow deeps", "barrow deeps boss list", "is barrow deeps a 10 player raid", "bd raid bosses" }, a = "The Barrow Deeps is a new 10-player, level 60 raid with 8 bosses: Deepscar Matriarch, Khalith the Dreadspinner, Amethrax, Ravus and Darlissa, Elder Tangleclaw, Well of Sorrow, Del'lynar Songwood and Sonya Darkhallow (final boss). It is the old prison that held Illidan for 10,000 years. No attunement.", topic = "dungeons" }
add{ q = { "where is barrow deeps entrance", "how do i get to barrow deeps", "barrow deeps location", "bd entrance", "barrow deeps where", "wher is the barrow deeps entrance", "how many entrances does barrow deeps have", "barrow deeps entrance location hyjal", "where do we zone into the barrow deeps raid", "barrow deeps raid portal where", "is there more than one way into the barrow deeps" }, a = "Barrow Deeps has three entrances: from Mount Hyjal (about 70, 62), from Winterspring, and from inside the Blackmaw Hold dungeon in Azshara. Each entrance opens into a different section of the prison, but every section can be reached from any entrance.", topic = "dungeons" }
add{ q = { "how hard is barrow deeps", "can a pug clear barrow deeps", "barrow deeps difficulty", "is bd like ubrs or kara", "is bd hard", "can pugs do barrow deeps", "how hard is the barrow deeps raid", "is barrow deeps like karazhan", "is barrow deeps pug friendly or do i need a guild", "barrow deeps harder than ubrs?", "bd difficulty for a pug group" }, a = "Developers compare Barrow Deeps to Karazhan rather than to UBRS, i.e. a real raid, not a dungeon with more people. They expect pickup groups to clear it after a few weeks. Teased fights include a damage buff that costs you something and a pair of spiders (likely Ravus and Darlissa).", topic = "dungeons" }
add{ q = { "brooch of the wardens", "vord'anaar prison", "barrow deeps secret area", "what does brooch of the wardens do", "brooch of wardens", "how do i get the brooch of the wardens", "what is vordanaar prison", "barrow deeps hidden area how to open", "is there a secret boss in barrow deeps", "brooch of the wardens what is it for", "vord anaar prison how" }, a = "The Brooch of the Wardens opens the Vord'anaar Prison inside The Barrow Deeps. Developers hinted at extra steps for the full raid experience, and this optional prison section appears to be one. How to get the brooch has not been published yet.", topic = "dungeons" }
add{ q = { "what is hyjal summit", "hyjal raid forever", "hyjal 20 man bosses", "hyjal summit bosses list", "hs raid", "hyjal summit info", "whats hyjal summit", "how many bosses in hyjal summit", "hyjal summit boss list please", "tell me about the 20 man hyjal raid", "what bosses are in the hyjal summit raid", "hyjal raid bosses and info" }, a = "Hyjal Summit is a new 20-player, level 60 raid with 13 bosses: Bandalar, Time-Lost Battalion, Old Gloomlurker, Kathris the Haunted, Elder Minderel, Council of Thorns, The Wild King, Ancient of Decay, Sylvestris Dusksong, Gharalis the Abyssal, Anara Chillwind, Tracker Stillwind and Nythus the Dreambound. No attunement.", topic = "dungeons" }
add{ q = { "where is hyjal summit entrance", "how to get to hyjal summit raid", "hyjal raid portal", "hyjal summit location", "hyjal summit where", "how do i get to the hyjal summit raid", "hyjal raid entrance", "wher is hyjal summit portal", "where do we zone in for hyjal summit near nordrassil", "hs entrance", "hyjal summit entrance location" }, a = "Hyjal Summit is at the peak of Mount Hyjal next to the World Tree Nordrassil. Game files put the portal at about 85, 33 on the Summit of Eternity, with the Summit of Eternity flight path at about 68.6, 44.1.", topic = "dungeons" }
add{ q = { "hyjal summit layout", "hyjal raid paths", "hyjal summit wings", "is hyjal linear", "hyjal raid order", "is hyjal summit linear", "hyjal summit boss order", "what order do we do hyjal bosses", "does hyjal summit split into wings", "hyjal raid layout", "can we pick which path in hyjal summit", "hs wings" }, a = "Hyjal Summit opens with a fight against an ancient guardian, then splits into three routes across the mountain through ruins above and below ground. All three paths must be cleared before the final encounters. It is set after Archimonde's death, so neither Archimonde nor Rage Winterchill is in it.", topic = "dungeons" }
add{ q = { "hyjal summit final boss", "last boss of hyjal", "who is the end boss of hyjal", "nythus or wild king", "hyjal last boss", "who is the final boss of hyjal summit", "hyjal end boss", "is nythus the last boss of hyjal", "whats the final boss in hs", "nythus or wild king last", "hyjal summit end boss name" }, a = "Sources disagree. The Legacy challenge list ends with Nythus the Dreambound and the wiki lists Nythus as end boss; other guides guess The Wild King, who draws on Nordrassil's power until it overwhelms him. Treat the kill order as unconfirmed until the raid opens December 9.", topic = "dungeons" }
add{ q = { "tier 1 forever", "where does tier drop", "tier set forever raids", "which raid drops tier", "t1 set", "which raid drops tier 1", "where do i get my t1 pieces", "does tier drop in all three raids", "tier set split between raids?", "do i need ony for tier", "where does each tier piece drop", "farming my tier set which raid do i run" }, a = "Forever's first tier set is split across all three launch raids, so each of Barrow Deeps, Hyjal Summit and Onyxia's Lair holds part of every class set. Each set has 6 pieces (head, shoulders, chest, hands, legs, feet); legs, hands, shoulders and feet can also be crafted.", topic = "dungeons" }
add{ q = { "tier set names forever", "warrior tier set name", "what is my class tier", "tier set list by class", "whats my class tier set called", "warrior t1 name forever", "tier set names by class", "what is the druid tier set", "lock tier set name", "pally tier set name forever", "list all the season 1 tier sets for every class" }, a = "Season 1 set names: Druid Grovekeeper (Eclipse/Ferocity/Rage/Raiment), Hunter Wildstalker Armor, Mage Manaflare Regalia, Paladin Justice (Armor/Battleplate/Battlegear), Priest Vestments/Raiments of Conviction, Rogue Grimstitch Armor, Shaman The Spiritcaller (Storm/Rage/base), Warlock Demonheart Raiment, Warrior Battlegear/Battleplate of Glory.", topic = "dungeons" }
add{ q = { "tier set bonuses", "what do tier bonuses do", "2 piece bonus", "5 piece bonus forever", "what do the tier set bonuses do", "whats the 2 piece bonus", "5pc bonus forever", "are tier bonuses worth it", "how do set bonuses work on forever tier", "tier 2pc 4pc 5pc", "is the tier bonus good for my spec or should i mix" }, a = "All Forever sets follow one pattern: 2 pieces give a role stat (hit for casters, haste for melee and hunters, spirit for healers, defense for tanks), 3 pieces improve a utility or defensive spell, 4 pieces add damage vs a creature type (or healing for healers), and 5 pieces upgrade the spec's key ability. Values may still change.", topic = "dungeons" }
add{ q = { "crafted tier", "how to craft tier", "malleable essence of nature", "tier recipes vendor", "aisarra nightmeadow", "how do i craft tier pieces", "can you craft tier in forever", "where do i get tier recipes", "malleable essence of nature where", "who sells crafted tier patterns", "aisarra nightmeadow recipes", "which tier slots are craftable and what do i need" }, a = "Legs, hands, shoulders and feet are craftable (ilvl 61, BoE, 2 copies per craft) by 300 Tailoring, Leatherworking or Blacksmithing plus a camp station. Recipes come from Aisarra Nightmeadow in Mount Hyjal and cost Malleable Essence of Nature (legs 8, others 6), which you get by disenchanting Hyjal Summit and Barrow Deeps loot.", topic = "dungeons" }
add{ q = { "can i wear more than one crafted tier", "artisan tier limit", "rousing seed pod", "only one tier piece equip", "can i wear 2 crafted tier pieces", "it only lets me equip one artisan item why", "what is rousing seed pod", "how do i equip more crafted tier", "artisan tier unique equipped?", "rousing seed pod how to get", "crafted tier limit" }, a = "By default you can equip only one Artisan's (crafted) tier item. A Rousing Seed Pod raises the limit to two; Rhylin Stonethorn in Mount Hyjal sells it for 10 gold at level 60 with Revered reputation with the Guardians of Hyjal. Leg recipes need Friendly with Guardians of Hyjal and a quest.", topic = "dungeons" }
add{ q = { "raid loot forever", "why cant i see raid item stats", "rare drops raid", "boss loot table forever", "why cant i see raid loot stats", "what does barrow deeps drop", "raid loot tables forever", "raid items show no stats", "where can i see what drops in the new raids", "is there a loot list for hyjal summit", "hidden raid loot" }, a = "Loot tables for the new raids are not public: raid items only reveal their stats once looted. Developers say each boss has a few rare drops that are far better than its normal loot, so expect a jackpot item rather than a fixed BiS list early on.", topic = "dungeons" }
add{ q = { "forever legendary", "taldramir", "whispering wood", "legendary staff forever", "how to get legendary", "is there a legendary in forever", "how do i get taldramir", "taldramir the whispering wood", "forever legendary staff questline", "legendary in the hyjal raid", "who can use taldramir", "how do i start the legendary staff in forever" }, a = "Taldramir, the Whispering Wood is Forever's first legendary: a bind-on-pickup two-handed staff revealed November 4. Its legendary questline is slated for spring 2027; Blizzard has not published its class, stats or steps. Game data ties one step to the Sylvestris Dusksong fight in Hyjal Summit.", topic = "dungeons" }
add{ q = { "guardians of hyjal rep", "hyjal reputation", "why farm guardians of hyjal", "hyjal rep rewards", "why should i farm guardians of hyjal", "do i need guardians of hyjal rep for tier", "what does guardians of hyjal rep unlock", "is hyjal rep worth grinding", "guardians rep for crafting tier", "how much hyjal rep do i need", "guardians of hyjal rep rewards" }, a = "Guardians of Hyjal reputation gates the crafted tier: Friendly plus a quest unlocks the legs recipe, higher standing unlocks hands, shoulders and feet, and Revered lets you buy the Rousing Seed Pod (wear 2 crafted tier pieces). Start it before raids open.", topic = "dungeons" }
add{ q = { "onyxia's lair forever", "ony raid info", "is onyxia in forever", "where is onyxia's lair", "is ony in forever", "wheres onyxias lair", "ony raid info forever", "is ony still 40 man in forever", "where is the onyxia raid in dustwallow", "can we do ony at launch or is it later", "is onyxia the only old raid at launch" }, a = "Onyxia's Lair is the only Classic raid at launch: 40 players, level 60, one boss, opens December 9. The entrance is in southern Dustwallow Marsh (about 52, 76); nearest flight points are Brackenwall Village (Horde) and Theramore Isle (Alliance). Every raider needs the Drakefire Amulet in their bags.", topic = "dungeons" }
add{ q = { "ony attune", "onyxia attunement", "drakefire amulet", "how to get drakefire amulet", "do i need to equip ony amulet", "how do i attune for ony", "do i need the drakefire amulet", "where do i get drakefire amulet", "do i have to equip drakefire amulet to zone in", "onyxia attunment", "is ony attune the same as in classic", "is there a key to get into onyxias lair" }, a = "Onyxia attunement is unchanged from Classic. You need the Drakefire Amulet in your inventory (bags, not bank; it doesn't need to be equipped). It is per character, not account-wide, at launch. Both faction chains end by killing General Drakkisath in UBRS for the Blood of the Black Dragon Champion. The amulet requires level 50.", topic = "dungeons" }
add{ q = { "alliance ony attune", "ony attune alliance steps", "dragonkin menace", "windsor quest chain", "great masquerade", "alliance ony attune steps", "how do ally attune ony", "dragonkin menace start", "marshal windsor chain", "great masquerade quest", "alliance onyxia attunement guide", "im alliance where do i start ony attunement" }, a = "Alliance (16 quests): start with Dragonkin Menace from Helendis Riverhorn in Burning Steppes (from level 48), do The True Masters chain, find Marshal Windsor in Blackrock Depths and break him out, run The Great Masquerade in Stormwind, follow The Dragon's Eye, then kill Drakkisath in UBRS. Haleh in Winterspring gives the amulet.", topic = "dungeons" }
add{ q = { "horde ony attune", "ony attune horde steps", "blood and thunder goretooth", "emberstrife quest", "test of skulls", "horde ony attune steps", "how do horde attune ony", "warlord goretooth quest", "emberstrife test of skulls", "blood and thunder quest horde", "horde onyxia attunement guide", "im horde where do i start ony attunement" }, a = "Horde (15 quests, level 55): start with Warlord Goretooth in Kargath, Badlands, clear LBRS, report to Eitrigg and Thrall, take Warchief Rend Blackhand's head in Blackrock Spire, then Rexxar in Desolace, Myranda the Hag in WPL, Emberstrife in Dustwallow's Wyrmbog and the four Test of Skulls quests (Scryer, Somnus, Chronalis, Axtroz). Finish with Drakkisath's blood in UBRS and return to Rexxar.", topic = "dungeons" }
add{ q = { "chipped drakefire amulet", "ony attune shortcut", "skip ony attunement", "is ony attunement account wide", "can i skip ony attunement", "is ony attune account wide", "do alts need ony attune", "ony attune shortcut forever", "no shortcut for drakefire?", "do i have to redo ony attune on my alt", "can i buy the chipped amulet to skip it" }, a = "There is no shortcut: the Chipped Drakefire Amulet sold in other Classic versions is not in Forever, and the attunement is per character (not account-wide) at launch. Every alt must do the full chain.", topic = "dungeons" }
add{ q = { "onyxia mechanics", "how to kill onyxia", "ony phases", "onyxia deep breath", "ony strat", "how do you kill onyxia", "onyxia phases explained", "what is deep breath ony", "how to not wipe on ony phase 2", "whelps ony phase 2", "ony fight tactics", "we keep wiping on ony what are the mechanics" }, a = "Classic baseline: P1 (100-65%) tank her with her back to the entrance, avoid the tail and front breath, don't touch eggs. P2 (65-40%) she flies; dodge Fireballs and Deep Breath across the middle, kill whelps from the side caves. P3 (40%) she lands and uses Bellowing Roar fear and floor eruptions; use Fear Ward/Tremor Totem. Forever tuning is unconfirmed.", src = "classic", topic = "dungeons" }
add{ q = { "ony fire resist", "do i need fire resist for ony", "fire resistance onyxia", "ony prep", "how much fire res for onyxia", "ony fr gear", "what to prepare for ony", "is fire resistance needed for onyxia in forever", "ony prep consumables", "fire resist tank ony", "do i need fr for ony" }, a = "Blizzard tells raiders to build fire resistance before Onyxia, since her attacks are fire-heavy and the fight shifts positioning. Tanks benefit most. No exact resistance target has been published for Forever.", topic = "dungeons" }
add{ q = { "onyxia loot forever", "does ony drop t2 helm", "head of onyxia", "ony loot changes", "what does ony drop", "does onyxia drop the t2 helm in forever", "head of onyxia quest still there", "onyxia loot table forever", "is ony loot the same as classic or changed", "whats ony drop now", "ony loot" }, a = "Blizzard says Onyxia's loot will change considerably from Classic, but no table is published. Beta data still contains Head of Onyxia (quest item) and Mature Black Dragon Sinew. In Classic she dropped T2 helms, Deathbringer, Vis'kag and Shard of the Scale; don't assume those are unchanged.", topic = "dungeons" }
add{ q = { "ubrs key", "seal of ascension", "how to get into ubrs", "ubrs attune", "how do i get to ubrs", "how do i get into ubrs", "seal of ascension how to get", "ubrs attunment", "do i need a key for ubrs", "does only one person need the ubrs key", "how to get to ubrs", "ubrs key quest" }, a = "UBRS needs one Seal of Ascension holder in the group (confirmed per the Nov 16 update). Loot the Unadorned Seal of Ascension from LBRS trash and take it to Vaelan; collect gemstones from Highlord Omokk (Spirestone), War Master Voone (Smolderthorn) and Overlord Wyrmthalak (Bloodaxe); then forge it at Emberstrife in Dustwallow's Wyrmbog.", topic = "dungeons" }
add{ q = { "ubrs group size", "is ubrs 10 man", "ubrs raid size", "how many players ubrs", "how many people for ubrs", "can i do ubrs with 5", "is lbrs 5 man and ubrs 10 man", "ubrs raid size forever", "ubrs player cap", "can we bring a full raid to ubrs or is it capped at 10", "how big is a ubrs group" }, a = "Upper Blackrock Spire is a 10-player wing; Lower Blackrock Spire is a 5-player dungeon. Both share one portal on the east side of Blackrock Mountain. Fastest route: climb the big chain, follow the wall to gnome Bodley's balcony and drop down in front of the portal.", topic = "dungeons" }
add{ q = { "ubrs bosses", "lbrs bosses", "blackrock spire boss list", "drakkisath", "rend fight", "lbrs boss list", "who are the bosses in blackrock spire", "rend fight in ubrs", "lbrs boss order", "what bosses are in lbrs and ubrs", "running lbrs for the first time which bosses are in there", "blackrock spire bosses list" }, a = "LBRS: Omokk, Vosh'gajin, Voone, Mother Smolderweb, Urok Doomhowl, Quartermaster Zigris, Halycon, Gizrul, Overlord Wyrmthalak. UBRS: Pyroguard Emberseer, Solakar Flamewreath, Goraluk Anvilcrack, Warchief Rend Blackhand, The Beast, General Drakkisath. Forever guides use Classic data; the instance wasn't in beta.", src = "classic", topic = "dungeons" }
add{ q = { "drakkisath strat", "how to kill drakkisath", "ubrs last boss wipe", "drakkisath guards", "we keep wiping on drakkisath", "how do you handle drakkisath guards", "general drakkisath tactics", "ubrs last boss strat", "who tanks drakk guards", "drakkisath kill order and how to split the guards", "how do you do drakkisath" }, a = "Classic baseline: General Drakkisath has two Chromatic Elite Guards; tank the guards away from him or kill them first, keep everyone out of his frontal cleave and drop threat on Conflagration (it disorients the target). Drakkisath drops the Onyxia attunement blood item.", src = "classic", topic = "dungeons" }
add{ q = { "brd key", "shadowforge key", "how to get shadowforge key", "dark iron legacy", "prison cell key", "dark iron legacy quest", "prison cell key brd", "do i need a key for brd", "how do i open the doors in brd", "shadowforge key quest", "do i need to attune for blackrock depths or can i just go in", "how do i get shadowforge key" }, a = "Blackrock Depths needs no attunement. The Shadowforge Key (opens the Shadowforge doors and skips the lower area) comes from Dark Iron Legacy, startable at 48, which sends you to Franclorn Forgewright's spirit. The Prison Cell Key drops from High Interrogator Gerstahn about half the time.", topic = "dungeons" }
add{ q = { "thaurissan doors stuck", "brd throne room wont open", "emperor door bug", "heart of the mountain", "thaurissan door stuck", "emperor door bugged after wipe", "cant get back into the emperor room", "brd doors stayed closed after we wiped", "did they fix the thaurissan doors", "we wiped on emperor and now the throne room door is locked", "emperor doors wont open" }, a = "Hotfixed Nov 9-10: the throne room doors now reopen after a wipe on Emperor Thaurissan, and Heart of the Mountain can be looted more than once in Blackrock Depths.", topic = "dungeons" }
add{ q = { "molten core attunement", "mc attune", "lothos riftwaker", "core fragment", "mc attunement quest where", "how do i attune to mc", "mc attune quest", "where do i get a core fragment", "do i need to attune for molten core", "how do you get attuned to molten core in classic", "mc attunment" }, a = "Classic baseline: talk to Lothos Riftwaker atop Blackrock Mountain, loot a Core Fragment near the Molten Core portal inside Blackrock Depths, and you can then teleport in. Forever's data contains the quest Attunement to the Core, but MC itself is not released.", src = "classic", topic = "dungeons" }
add{ q = { "bwl attunement", "blackhand's command", "bwl attune", "how to attune to blackwing lair", "how do i attune to bwl", "bwl attune quest", "blackwing lair attunement", "where does blackhands command drop", "do i need a key for bwl", "how do you get attuned for blackwing lair classic style", "bwl attunment" }, a = "Classic baseline: loot Blackhand's Command from a Scarshield Quartermaster in LBRS, then touch the orb behind General Drakkisath's room in UBRS. Blackwing Lair is not released or dated in Forever.", src = "classic", topic = "dungeons" }
add{ q = { "naxx attunement", "naxx attune", "naxxramas forever", "how to get into naxx", "argent dawn rep for naxx", "is naxx in forever", "what are the naxx requirements", "naxxramas attunement", "how do you get into naxx", "do i need argent dawn rep to enter naxxramas", "naxx attunment" }, a = "Classic baseline: Naxxramas needed Argent Dawn reputation (Honored and above lowers the cost) plus materials turned in at Light's Hope Chapel. Naxxramas is not announced for Forever, so no Forever attunement exists yet.", src = "classic", topic = "dungeons" }
add{ q = { "scholo key", "skeleton key scholomance", "how do i get into scholomance", "key to scholomance quest", "skeleton key scholo", "how do you get in scholomance", "scholomance key quest", "how do i open scholo", "scholo attunement", "how do i get the skeleton key for scholomance", "scholo door locked how to open" }, a = "Scholomance's front gate needs the Skeleton Key from the Key to Scholomance chain (Alliance at Chillwind Camp, Horde at The Bulwark); the final quest requires level 55. Rogues with high Lockpicking or an engineer's Powerful Seaforium Charge can also open the gate. The Viewing Room Key from Rattlegore opens the deeper rooms.", topic = "dungeons" }
add{ q = { "dire maul key", "crescent key", "how to open dm west", "dm north key", "pusillin", "crescent key where", "pusillin chase in dire maul", "how do i open dire maul west", "dm west key", "where do i get the crescent key", "how do i get the crescent key for dire maul north and west", "dm doors locked need key" }, a = "Dire Maul West and North need the Crescent Key, which drops from Pusillin in Dire Maul East (you chase him through the wing). Once someone opens the doors, the torch just inside lets others through. DM East needs no key.", topic = "dungeons" }
add{ q = { "strat key", "key to the city", "how to get into undead strat", "service gate key", "dead side strat", "key to the city strat", "undead strat key", "how to get into dead side strat", "strat dead side entrance", "eastwall gate key", "how do i get the key to the city for stratholme service gate", "strat key quest" }, a = "The Stratholme service (Eastwall) gate to the undead side needs the Key to the City, which drops from Magistrate Barthilas. The two wings are connected, so you can also reach the undead side from the Living side.", topic = "dungeons" }
add{ q = { "gnomer back door", "workshop key", "scarlet key", "how to open sm armory", "sm cathedral key", "how do i get scarlet key", "gnomeregan workshop key", "sm armory key", "gnomer back door key", "scarlet monastery key", "how do i open the armory and cathedral doors in sm", "gnomer workshop key where" }, a = "Workshop Key (Gnomeregan back door) drops from Electrocutioner 6000. The Scarlet Key opens SM Armory and Cathedral; loot it from Doan's Strongbox at the end of the Library (one per player), or have a rogue pick the doors.", topic = "dungeons" }
add{ q = { "zf mallet", "gahz'rilla summon", "mallet of zul'farrak", "how to summon gahzrilla", "sacred mallet zf", "zf mallet quest", "how do i summon gahzrilla", "where do i get the zul farrak mallet", "gahzrilla gong mallet", "how do we get the mallet to summon gahz'rilla in zul'farrak", "where to use zf mallet" }, a = "Gahz'rilla in Zul'Farrak needs the Mallet of Zul'Farrak: get the Sacred Mallet from Qiaga the Keeper at the Altar of Zul in the Hinterlands, use it on the altar atop Jintha'Alor, then strike the gong in ZF.", topic = "dungeons" }
add{ q = { "maraudon scepter", "scepter of celebras", "earth song falls portal", "mara shortcut", "how to get scepter of celebras", "mara portal scepter", "celebras scepter quest", "maraudon scepter quest chain", "earth song falls shortcut", "how do i get the scepter that opens the portal in maraudon", "mara scepter where" }, a = "The Scepter of Celebras opens the portal straight to Earth Song Falls in Maraudon. Get it from the Legends of Maraudon and The Scepter of Celebras quests after freeing Celebras the Redeemed.", topic = "dungeons" }
add{ q = { "keyring forever", "are keys account wide", "do alts need keys", "attunements account wide", "is there a keyring", "keyring in forever", "keys per character or account", "are keys shared on alts", "do keys carry over to my alts", "do i have to farm all the dungeon keys again on every alt", "are attunements per character" }, a = "The keyring returns but is much lighter than Classic. Keys are per character (bind on pickup), but one key holder opens the door for the whole group, so alts can tag along. Onyxia attunement is per character. Barrow Deeps and Hyjal Summit have no attunement.", topic = "dungeons" }
add{ q = { "krol'dok key", "azsharan key", "krol'dok compound key", "what does azsharan key open", "new dungeon keys forever", "kroldok ogre key", "krol'dok keys", "azsharan key what is it for", "what new keys are in forever", "found an azsharan key what does it open", "kroldok compound key where" }, a = "Forever adds new keys: Krol'dok Compound Key and Krol'dok Ogre Key (Krol'dok Stronghold, Riverglades) and the Azsharan Key. Their tooltips don't say what they open, and no guide has confirmed it yet.", topic = "dungeons" }
add{ q = { "new dungeons forever", "list of new dungeons", "which dungeons are new", "9 new dungeons", "new dungeons?", "what dungeons did forever add", "list all the new 5 mans", "how many new dungeons are in forever", "which dungeons are new and which are classic", "new forever dungeons and levels", "all the new instances" }, a = "Forever adds nine dungeons: Hall of Thanes (13-18), Ruins of Lordaeron (15-20), Excavation Site: Wetlands (24-29), City of Dalaran (28-33), The Drowned City (35-40), Krol'dok Stronghold (40-45), Alcaz Prison (48-53), Blackmaw Hold (55-60) and Shaper's Terrace (58-60). Blizzard lists them all as 5-player.", topic = "dungeons" }
add{ q = { "dungeon list by level", "what dungeon should i run at 30", "dungeons by level forever", "which dungeon for my level", "what dungeon at my level", "im level 30 what dungeon should i run", "dungeon level ranges", "dungeons by lvl", "what instance for lvl 40", "what dungeons can i do at 25 in forever", "dungeon brackets list" }, a = "Rough brackets: RFC/Hall of Thanes 13-18, Ruins of Lordaeron 15-22, WC 15-24, Deadmines 17-26, SFK 20-30, BFD/Stockade 24-32, Excavation Site 26-33, City of Dalaran 28-35, RFK/Gnomer 29-38, SM 30-46, Drowned City 35-42, RFD 37-46, Krol'dok 40-47, Uldaman 41-51, ZF 44-54, Mara 46-55, Alcaz 48-55, ST 50-60, BRD 52-60, then the 55-60 endgame.", topic = "dungeons" }
add{ q = { "endgame dungeons forever", "60 dungeons list", "max level dungeons", "what dungeons at 60", "level 60 dungeons", "max lvl dungeons forever", "endgame 5 mans", "just hit 60 what dungeons should i run for gear", "55-60 dungeon list", "which dungeons are endgame" }, a = "Level 55-60 dungeons: LBRS, Blackmaw Hold (new), Dire Maul East/West/North, Shaper's Terrace (new, 58-60), Stratholme Live and Undead, Scholomance, and UBRS (10-player). BRD (52-60) and Sunken Temple (50-60) also cover late levels.", topic = "dungeons" }
add{ q = { "is dungeon xp good", "dungeon leveling forever", "should i spam dungeons", "dungeon xp nerf", "dungeon mob xp", "should i spam dungeons for xp", "did they nerf dungeon xp", "dungeon mobs give less xp?", "is it faster to level in dungeons or questing in forever", "dungeon xp worth it", "how much xp do dungeon mobs give now" }, a = "Dungeon mob XP is heavily reduced versus Classic (even after the Nov 9 hotfix added +50%, mobs give roughly 45% of Classic XP). Most XP comes from one-time dungeon quests, which pay well, so run each dungeon once with all quests and then go back to questing. Blizzard says spam-leveling in dungeons will not be optimal.", topic = "dungeons" }
add{ q = { "no xp in dungeon", "why am i getting no xp", "high level in group no xp", "boosting xp forever", "no xp in dungeon why", "my high level friend is in group and i get 0 xp", "boosting gives no xp", "dungeon no xp bug", "why does the whole group get no xp when a 60 is with us", "0 xp dungeon mobs" }, a = "If any party member is far above the mobs' level, nobody in the group gets XP from those kills. That kills old-style boosting runs; keep groups close in level.", topic = "dungeons" }
add{ q = { "dungeon finder forever", "lfg tool", "does lfg teleport", "meeting stone summon", "how to find dungeon group", "is there a dungeon finder", "lfg tool forever", "does group finder teleport you", "how do i find a dungeon group", "do meeting stones summon", "is there lfg in forever or do i have to walk", "group finder how it works" }, a = "The Group Finder is a listing board only: you post or browse, then whisper and invite. It doesn't auto-match or teleport you. Meeting Stones can't summon; the only summon is a Warlock's Ritual of Summoning with two helpers. There are no heroic or mythic difficulties.", topic = "dungeons" }
add{ q = { "instance reset limit", "how many dungeons per hour", "instance cap", "how to reset dungeon", "how do i reset a dungeon", "instance limit forever", "hit the instance cap what now", "how many times can i reset an instance in an hour", "reset dungeon how", "got the too many instances message", "whats the dungeon reset limit per hour" }, a = "You can reset dungeons up to 5 times per hour. Everyone must leave, then the leader resets instances from the character/party frame.", topic = "dungeons" }
add{ q = { "dungeon group size", "can i do dungeons with 10", "how many players in a dungeon", "party quests in raid group", "can i bring 10 people to a dungeon", "can i do dungeon quests in a raid group", "dungeons 5 man only?", "can we run a dungeon with a raid group to make it easier", "max party size dungeon", "dungeon max players forever", "can a 10 man group do party quests in a dungeon" }, a = "Blizzard lists the new dungeons as 5-player, and party quests can't be completed in a raid group, so quest runs need a normal 5-man. Upper Blackrock Spire is the 10-player exception.", topic = "dungeons" }
add{ q = { "dungeon loot changes forever", "is dungeon loot the same as classic", "new itemization dungeons", "dungeon transmog", "is dungeon loot the same", "dungeon loot changes", "did they change dungeon gear", "new dungeon itemization", "dungeon loot forever vs classic", "are classic dungeon drops still the same items", "dungeon gear reworked?" }, a = "Most Classic dungeons got reworked loot with new stats, some with effects that favor a class, spec, biome or enemy type. Items unlock their appearance for every eligible looter automatically. Dungeons also drop Tarnished Undermine Real, a currency for extra rewards, and first clears count toward Legacy Spelunker challenges.", topic = "dungeons" }
add{ q = { "spelunker", "legacy points dungeons", "master spelunker", "dungeon achievements legacy", "spelunker achievement", "how do i get spelunker", "do i get legacy points for clearing every dungeon", "spelunker legacy", "what is the spelunker thing", "spelunker progress how to track", "do i get anything for clearing all dungeons once" }, a = "Clearing each dungeon once earns Legacy System points through the Spelunker challenges; Master Spelunker covers 17 dungeons and wings. It's a good reason to clear every dungeon at least once.", topic = "dungeons" }
add{ q = { "crates in dungeons", "craftsman's writ drop dungeon", "waylaid crate dungeon", "do crates drop in dungeons", "craftsmans writ dungeon drop", "can i get waylaid crates from dungeons", "do dungeon bosses drop crates", "craftsman writ from dungeon mobs", "crates in instances", "i got a waylaid crate from a dungeon boss is that normal" }, a = "As of the Nov 9 hotfix, Waylaid Crates and Craftsman's Writs can drop inside dungeons too.", topic = "dungeons" }
add{ q = { "hall of thanes", "hot dungeon", "where is hall of thanes", "hall of thanes entrance", "ironforge dungeon", "hall of thanes where", "hot dungeon entrance", "hall of thanes level", "how do i get into hall of thanes under ironforge", "alliance ragefire equivalent", "where is the dungeon under ironforge", "hot location" }, a = "Hall of Thanes (13-20) is the Alliance counterpart to Ragefire Chasm, under Ironforge. From the Great Forge, go into King Magni's hall at the High Seat and take the cobwebbed passage on the left (about 43.5, 52.0) down to the entrance. Horde can enter, but it's deep in enemy territory and has few Horde quests.", topic = "dungeons" }
add{ q = { "hall of thanes bosses", "hall of thanes quests", "magmatus", "durgen dirgehammer", "faldrim anvilmar", "hall of thanes boss tips", "how do you beat magmatus", "what quests should i grab before hall of thanes", "hot bosses strat", "faldrim anvilmar curse dispel", "durgen dirgehammer fight", "were going into hall of thanes what do the bosses do" }, a = "Bosses: Faldrim Anvilmar (dispel his attack/cast slow curse), Magmatus (kill the Dark Iron Summoner first, ranged stay back from fire pulses), Plunder (knockback, tank against a wall), Durgen Dirgehammer (AoE fear, kill his two golems; Tremor Totem helps). Quests: Important Heirlooms, The Restless Dead, Old Ironforge Incursion, An Ancient Grudge, The Treaty of Understanding.", topic = "dungeons" }
add{ q = { "ruins of lordaeron", "rol dungeon", "where is ruins of lordaeron", "undercity dungeon", "rol entrance", "rol location", "how do i get into ruins of lordaeron", "dungeon above undercity", "ruins of lordaeron level", "where is the new tirisfal dungeon above the undercity", "rol entrance where" }, a = "Ruins of Lordaeron (15-22) is above the Undercity in Tirisfal Glades: outside the front gate, look left before the keep and go up the stairs (about 72.4, 11.6). Mainly Horde with 6 quests from Undercity, Tirisfal and Silverpine; Alliance can enter and get 4 quests inside, starting with Captain Truman by the entrance.", topic = "dungeons" }
add{ q = { "ruins of lordaeron bosses", "rol boss tips", "the baron rol", "rath'mael", "viktor the vile", "rol bosses", "ruins of lordaeron boss tips", "how to beat the baron in rol", "rathmael fight", "viktor the vile strat", "witherfang broodlings", "were doing ruins of lordaeron what do the bosses do" }, a = "Bosses: Witherfang (spider, kill Broodlings), The Baron (knockout stun on tank, back to wall), Viktor the Vile (5 add waves, start at the chimney/fireplace with full mana), The Abandoned (3 waves, interrupt Drain Life), Bjork (anti-magic shield, use physical), Rath'mael (final, interrupt Flamestrike). Cleanse Ghoul Plague immediately.", topic = "dungeons" }
add{ q = { "excavation site wetlands", "esw dungeon", "wetlands dungeon", "excavation site entrance", "where is the excavation site", "esw location", "how do i get into the wetlands dungeon", "excavation site what level", "is there a dungeon in the wetlands now", "the new dungeon above whelgars excavation where is the door", "excavation site wetlands lvl range" }, a = "Excavation Site: Wetlands (26-33) sits above Whelgar's Excavation; the entrance is at 48.1, 56.5 with the meeting stone near 53.9, 65.4. Bosses: Saltspine (crocolisk), Shadetooth (raptor, AoE fear, enrages), optional Highland Horror (Alliance quest), and the Relic Guardian, woken via the Archival Panel. Cure diseases.", topic = "dungeons" }
add{ q = { "city of dalaran dungeon", "cod dungeon", "dalaran sewer key", "how to get into dalaran", "dalaran attunement", "how do i get into city of dalaran", "dalaran dungeon key", "cod attunement", "city of dalaran dungeon locked", "do i need a key for the dalaran dungeon", "only one person needs the dalaran sewer key?", "city of dalaran attunment" }, a = "City of Dalaran (28-35) is the only dungeon locked outright. One group member needs the Dalaran Sewer Key from Heart of Disruption (Image of Archmage Modera). Alliance starts with An Alarming Request from Emissary Jacques in Southshore; Horde starts with Magus Wordeen Voidglare in Tarren Mill. Entrance is via the sewers (about 69.3, 45.6 in Silverpine).", topic = "dungeons" }
add{ q = { "city of dalaran bosses", "dalaran dungeon tips", "shade of the archmage", "lyn the ignored", "tome of dalaran", "city of dalaran boss tips", "cod bosses", "shade of the archmage fight", "tome of dalaran quest", "mana devourer healing check", "what do the bosses in city of dalaran do" }, a = "Bosses: Atrexis the Grave Knight, Mana Devourer (healing check), Arcane Anomaly (stay close to dodge its rotating beam), Fel Ancient, Arcanic Enigma (kill Mana Phantoms first), Unstable Sentry (melee move out of Malfunction), Shade of the Archmage (final; dodge Bounding Mana, break Mass Polymorph). Secret boss Lyn the Ignored needs the Tome of Dalaran from the end of SFK.", topic = "dungeons" }
add{ q = { "drowned city", "dc dungeon", "where is the drowned city", "drowned city entrance", "stv underwater dungeon", "wher is drowned city", "how do i get to the drowned city", "drowned city level range", "dungeon off the stv coast", "sunken troll city dungeon stranglethorn", "how do you get into the underwater dungeon in stranglethorn", "drowned city location" }, a = "The Drowned City (35-42) is a sunken troll city off the Stranglethorn coast west of Grom'gol. The entrance is underwater at about 21.4, 27.9: swim past the Vile Reef to Sunken Hollow and look for the cave with a big tablet. Bring water breathing for the Primeval Elemental area.", topic = "dungeons" }
add{ q = { "drowned city bosses", "deathless marrow", "min'loth", "captain dreadrise", "drowned city tips", "drowned city boss tips", "how to beat zul'alai", "var'taka priestess kill order", "drowned city strat", "dc bosses what do they do", "were wiping in the drowned city what are the boss mechanics", "deathless marrow quest drowned city" }, a = "Bosses: Zul'Alai (burn at 30% Undying Oath), Var'Taka (kill priestess adds, Harpoon pulls), Captain Dreadrise (break the Embrine bubble), Deathless Marrow (each add killed gives +20% damage to it; nerfed 25% health Nov 9), Primeval Elemental (kill Undying Offerings to spawn), Min'loth (becomes a serpent at 0%: poison volley and fear).", topic = "dungeons" }
add{ q = { "krol'dok stronghold", "kds dungeon", "riverglades dungeon", "krol'dok entrance", "where is krol'dok", "wheres kroldok", "kroldok location", "how do i get into krol'dok stronghold", "krol dok what level", "ogre dungeon riverglades where", "cant find the entrance to krol'dok stronghold in riverglades", "kroldok door" }, a = "Krol'Dok Stronghold (40-47) is an ogre and Twilight's Hammer fortress in the Riverglades, on a hill over Sunnyglade. The entrance is a cave west of the big gates at 37.5, 37.5. Bosses: Slavecrusher Grox, Twilight Commander Zarmok, War Handler Ashka, Nar'gurk, Bossman Toof (add endurance fight at the bridges), Overlord Mugg (spread out, he leaps).", topic = "dungeons" }
add{ q = { "krol'dok quests", "eye of mugg", "tome of twilight quest", "krol'dok moulding", "kroldok quest list", "what quests for krol'dok", "token of vengeance quest", "eye of mugg kroldok", "where do i get krol'dok quests horde", "which quests should i grab before running krol'dok stronghold", "krol dok quests alliance" }, a = "Horde: A Token of Vengeance (Da'grosh, Riverglades), Eye of Mugg and Tome of Twilight (Rom'gar). Alliance: Eye of Mugg and Tome of Twilight (Farholde Keep), Twilight Mementos (Sergeant Riftan), Vengeance of the Highborne (Ranath Nightstride, Dalaran). Both: Krol'dok Moulding from Tunk the Blacksmith inside.", topic = "dungeons" }
add{ q = { "alcaz prison", "alcaz island dungeon", "where is alcaz prison", "dustwallow dungeon", "varian prison", "where exactly is alcaz prison", "alcaz prison entrance", "how do i get over to alcaz island", "alcaz prison what level", "dustwallow prison dungeon", "how do you get to the prison dungeon on alcaz island off dustwallow", "alcaz location" }, a = "Alcaz Island Prison (48-55) is on Alcaz Island off Dustwallow Marsh; the portal is in the basement of the big building around 75, 15 (take the left hill path from the dock). It holds Defias and naga, and King Varian Wrynn is imprisoned there. Prereqs: Our Man in Theramore (Mathias Shaw, Alliance) or The Missing Kor'kron (Eitrigg, Horde).", topic = "dungeons" }
add{ q = { "alcaz bosses", "zarla ober", "blazeroar", "alcaz prison tips", "overseer wrex", "alcaz prison boss tips", "how to beat tidemistress ca'zass", "alcaz prison strat", "what do alcaz bosses do", "zarla ober fight", "were running alcaz prison what do i need to know about the bosses", "blazeroar mechanics" }, a = "Bosses: Tidemistress Ca'zass (interrupt Frostbolt Volley/Polymorph, kill enchantresses), Overseer Wrex (drops the keyring for the right side), Katerina the Cleaner (kill the priests first), Zarla Ober (fire mage who becomes Blazeroar at low health; turn the breath away, fear), and The Questioner behind a locked door for Mason Connery's quest.", topic = "dungeons" }
add{ q = { "blackmaw hold", "bmh dungeon", "where is blackmaw hold", "azshara dungeon", "furbolg dungeon", "wheres blackmaw hold", "blackmaw hold location", "how do i get into blackmaw hold", "blackmaw hold what level", "new furbolg dungeon azshara where", "how do i find the blackmaw hold entrance in northern azshara", "bmh entrance" }, a = "Blackmaw Hold (55-60) is a huge furbolg city in northern Azshara, bigger than BRD. The tunnel starts at 38.7, 33.4 in Azshara and the portal is deep inside (66.6, 84.4 on the Winterspring map). Bosses: Withermaw, Bonesnout the Unbroken, Impaan the Imprisoner, Unbound Spirit, Elder Shaman Bloodmane, Blackmaw Behemoth and Clawbert, Varrox Bleakhoof. It also connects to The Barrow Deeps.", topic = "dungeons" }
add{ q = { "blackmaw hold quests", "blackmaw pouches", "feeding time quest", "wilted lashling pet", "blackmaw hold quest list", "what quests for blackmaw hold", "where do i get bmh quests", "how do i get the wilted lashling", "blackmaw pouch what is it", "which quests should i pick up in azshara before blackmaw hold", "feeding time blackmaw" }, a = "Seven quests per faction, mostly from Azshara (Ekkal, Gatekeeper Rageroar, Ogtink) plus Blackmaw Magic and Get to the Roots of It from capital or Dalaran NPCs. Blackmaw Pouches becomes a repeatable rep farm after the first turn-in; Feeding Time inside is repeatable for herbs and a chance at the Wilted Lashling pet.", topic = "dungeons" }
add{ q = { "shaper's terrace", "terrace dungeon", "ungoro dungeon", "where is shaper's terrace", "power crystals dungeon", "wheres shapers terrace", "shapers terrace location", "how do i get into shapers terrace", "shapers terrace what level", "un goro titan dungeon where", "where is the entrance to the new dungeon in un'goro crater", "terrace entrance" }, a = "Shaper's Terrace (58-60) is a titan site in Un'Goro on the hill over Marshal's Refuge (48.1, 6.1). Bring 15 each of Red, Blue, Green and Yellow Power Crystals: each Archival Panel summons a boss (Cinder, Snowtalon, Vitrix, Bolt), and activating all four calls the final boss Nanaya. Mounts work inside; falling off near the lake kicks you out.", topic = "dungeons" }
add{ q = { "shaper's terrace bosses", "vitrix", "nanaya", "titanosaur", "terrace tips", "shapers terrace boss tips", "how to beat nanaya", "shapers terrace strat", "titanosaur fears tremor totem", "snowtalon fight", "were wiping in shapers terrace what are the boss mechanics", "vitrix strat" }, a = "Key fights: Titanosaur fears (Tremor Totem), Snowtalon (pull out of the cave, Frost Nova/Cone of Cold), Tor'Rel and Izha'Rel (kill fire raptor Tor'Rel first), Vitrix (can one-shot fresh groups, skippable), Venomridge (party poison, Poison Cleansing Totem), Bolt (Chain Lightning, spread), Nanaya (final, easy). Vitrix, Snowtalon and Cinder now drop loot (Nov 9 hotfix).", topic = "dungeons" }
add{ q = { "deadmines changes forever", "is deadmines harder", "vc changes", "deadmines forever", "did deadmines change", "is vc harder in forever", "deadmines bosses hit harder now", "whats different in deadmines", "did they make deadmines harder in forever compared to classic", "deadmines changes from classic layout and bosses", "vc harder?" }, a = "Deadmines keeps its layout and boss order, but bosses hit much harder (Rhahk'Zor's slam about 330 vs about 75 in Classic). Nearly all loot has new stats, five bosses got new items, the Defias Leather set was rebuilt, and the Staff of Westfall gained healing and spell damage. Best at 18-21; Alliance-only quests.", topic = "dungeons" }
add{ q = { "deadmines quests", "vc quests forever", "alba fairmoon", "destruction in deadmines", "what quests for deadmines", "vc quest list", "deadmines quest xp", "where do i get deadmines quests", "alliance deadmines quest givers", "which deadmines quests should i pick up before i go in", "deadmines quests forever" }, a = "Six Alliance quests (about 19,000 XP total): The Defias Brotherhood (Gryan Stoutmantle), Red Silk Bandanas (Scout Riell), Destruction in Deadmines (new Alba Fairmoon chain from level 9), Underground Assault (Shoni), Oh Brother... and Collecting Memories (Wilder Thistlenettle, Stormwind). VanCleef's Unsent Letter starts the Stockade chain.", topic = "dungeons" }
add{ q = { "horde gnomeregan", "can horde do gnomer", "gear wars quest", "gnomer horde quests", "gnomer for horde", "horde gnomeregan quests", "how do horde get to gnomeregan", "gear wars quest start", "is there a reason for horde to run gnomer now", "im horde can i do gnomeregan quests in forever", "horde gnomer quest chain" }, a = "Yes. In Forever, Horde reach Gnomeregan via a questline starting with Gear Wars. Alliance Gnomeregan quests are among the richest XP in any dungeon (about 54,000 XP total).", topic = "dungeons" }
add{ q = { "best dungeon quest xp", "which dungeons have the most quest xp", "dungeon quests worth it", "dungeon quest xp", "do dungeon quests give good xp", "what dungeons give the most quest xp", "are dungeon quests worth doing", "should i grab all the dungeon quests before going in", "dungeon quests give double xp?", "highest xp dungeon quests" }, a = "Dungeon quests below 40 pay roughly double Classic XP (bonus later halved in beta), and from 40 on most pay Classic amounts. Big ones: Gnomeregan Alliance about 54,000 XP, City of Dalaran about 37,600 (both factions), Ruins of Lordaeron Horde about 29,800. RFC and SFK have no Alliance quests; Deadmines and Stockade have none for Horde.", topic = "dungeons" }
add{ q = { "dire maul tribute", "dm tribute run", "how to do tribute run", "dm north buffs", "dm tribute", "how to do a tribute run", "dire maul tribute run", "tribute run guide", "how do you get the tribute chest in dire maul north", "gordok tribute" }, a = "Classic baseline: in Dire Maul North, kill King Gordok without killing guards Mol'dar, Fengus, Slip'kik or Captain Kromcrush (use the Gordok Inner Door key, sneak past, or trick them). Cho'Rush becomes king and you get a tribute chest plus world buffs from Mol'dar, Fengus and Slip'kik. Forever guides have not confirmed changes.", src = "classic", topic = "dungeons" }
add{ q = { "scholomance bosses", "scholo strat", "gandling", "how to summon kirtonos", "scholo wipe", "how do we clear scholo", "scholomance boss tips", "kirtonos summon how", "darkmaster gandling strat", "what order are the scholo bosses", "we keep wiping in scholomance what are the boss mechanics", "scholo bosses list" }, a = "Classic baseline: Kirtonos is summoned with Blood of Innocents, Rattlegore drops the Viewing Room Key, then kill the six room bosses so Darkmaster Gandling spawns; he teleports players into side rooms full of adds. Alexei Barov (Unholy Aura, decurse Veil of Shadow) and Krastinov (enrages at 50%) are the usual wipes. Not tested in Forever beta.", src = "classic", topic = "dungeons" }
add{ q = { "stratholme", "strat live vs dead", "strat bosses", "baron rivendare", "where is stratholme entrance", "strat live or undead side", "stratholme bosses", "which side of strat should we do", "stratholme entrance where", "strat main gate or service gate", "whats the difference between live and dead side stratholme", "stratholme info" }, a = "Stratholme (58-60) is in northwest Eastern Plaguelands: the main gate leads to Living (Scarlet side, ends at Balnazzar), the Eastwall service gate leads to Undead (ends at Baron Rivendare, needs Key to the City). The wings connect. Forever guides use Classic data; no mounts inside since the Nov 9 hotfix.", src = "classic", topic = "dungeons" }
add{ q = { "baron run", "45 minute baron", "deathcharger's reins forever", "baron mount", "can i still get the baron mount", "where do i farm deathchargers reins", "timed baron run", "does baron still drop the mount", "is the 45 min baron run in forever", "can i still get deathchargers reins from baron rivendare in forever", "baron run reward" }, a = "Classic baseline: Baron Rivendare dropped Deathcharger's Reins (very rare mount), and a 45-minute Baron run rewarded a quest item. Neither is confirmed for Forever yet.", src = "classic", topic = "dungeons" }
add{ q = { "tier 0 forever", "dungeon set 1", "is there t0 in forever", "valor set forever", "is there tier 0", "dungeon set 1 forever", "t0 bonuses", "valor set bonus", "t0 in forever?", "is dungeon set 1 in forever and what are the set bonuses", "tier 0 where to get" }, a = "Dungeon Set 1 (Tier 0) exists in Forever's item data with new bonuses. Example, Battlegear of Valor: 2 pieces +8 all resistances, 3 pieces +15 Strength, 5 pieces a melee proc that heals and gives rage, 6 pieces health regen. Drop locations aren't documented for Forever yet; in Classic they came from Strat, Scholo, LBRS/UBRS and BRD.", topic = "dungeons" }
add{ q = { "tier 0.5", "dungeon set 2 forever", "t0.5 quest", "is t0.5 in forever", "kormok summon", "is there tier 0.5 in forever", "dungeon set 2", "how do i do the t0.5 upgrade quest", "can i upgrade tier 0", "kormok summon scholo", "can i upgrade tier 0 to tier 0.5 in forever like classic", "dungeon set 2 quest" }, a = "No Forever source has confirmed the Dungeon Set 2 (Tier 0.5) upgrade questline yet. In Classic it ran through summoned bosses like Kormok (Scholomance), Lord Valthalak (UBRS), Mor Grayhoof (LBRS), Isalien (DM East) and Jarien and Sothos (Strat). Those summon spots are still listed in Forever guides, which use Classic data.", src = "classic", topic = "dungeons" }
add{ q = { "pre raid bis", "how to gear for raids forever", "pre-raid gear", "bis before raid", "what dungeons for gear at 60", "how do i gear up at 60", "pre bis forever", "best gear before raiding", "pre raid gear list", "what should i farm before raids", "just hit 60 how do i gear up for raids in forever", "are classic bis lists accurate for forever" }, a = "Forever reworked itemization, so Classic BiS lists are unreliable. Unified hit and crit (melee, ranged and spell share them), Expertise replaces weapon skill, and healing gear carries spell power. Farm UBRS, Strat, Scholo, Dire Maul, Blackmaw Hold and Shaper's Terrace, and check in-game tooltips. No final launch BiS is confirmed.", topic = "dungeons" }
add{ q = { "warrior pre raid bis", "fury warrior bis forever", "arms warrior pre raid", "warrior dps gear 60", "fury warrior bis", "arms warrior bis forever", "warrior gear 60", "warrior pre bis list", "what gear should my warrior farm before raids", "warrior bis forever" }, a = "Beta sim list for Arms: Lionheart Helm (BS), Devilsaur Gauntlets, Titanic Leggings (BS), Hand of Justice (BRD Emperor), Blade of Hanna (Strat), Lightforge Bracers (Scholo Alexei), Beads of Ogre Might (DM), Don Julio's Band (Stormpike Exalted), PvP Highlander's plate. New STV vendor items like Adaptive Combat Assistant also show up. Provisional.", class = "WARRIOR", topic = "dungeons" }
add{ q = { "rogue pre raid bis", "rogue bis forever", "rogue gear 60", "best rogue pre raid items", "rogue bis list", "what should my rogue wear before raid", "rogue pre bis forever", "rogue raid prep gear", "best rogue gear 60", "what gear should my rogue farm before raids in forever", "rogue pre raid list" }, a = "Beta sim list for Rogue: Devilsaur Gauntlets and Leggings, Dawn Armor (LW), Cape of the Black Baron (Strat), Felstriker (Rend, UBRS), Heartseeker (BS), Mark of Fordring (In Dreams), Royal Seal of Eldre'Thalas (DM), Satyr's Bow (DM East) plus the new Assassin's Waistguard and Adaptive Combat Assistant from an STV vendor. Provisional.", class = "ROGUE", topic = "dungeons" }
add{ q = { "hunter pre raid bis", "hunter bis forever", "hunter gear 60", "eaglehorn bow", "hunter bis list", "what should my hunter wear before raid", "hunter pre bis forever", "best hunter bow pre raid", "best hunter gear 60", "what gear should my hunter farm before raids in forever", "hunter pre raid list" }, a = "Beta sim list for Hunter: Black Dragonscale Helm and Dawn Armor (LW), Cape of the Black Baron (Strat), Marksman's Girdle (Urok, LBRS), Eaglehorn Long Bow (Gizrul, LBRS), Blackhand's Breadth (UBRS quest), Mark of Fordring, Legionite Glaive (BS), Frozen Heart of the Mountain (Enchanting). Provisional.", class = "HUNTER", topic = "dungeons" }
add{ q = { "mage pre raid bis", "caster pre raid bis", "warlock pre raid bis", "spellweaver's turban", "caster gear 60", "mage bis list", "caster bis forever", "lock pre bis", "what should my mage wear before raid", "best caster gear 60", "what gear should my mage or warlock farm before raids in forever", "caster pre raid list" }, a = "Beta sim list for casters: Spellweaver's Turban, Draconic Infused Emblem and Tome of the Lost (all Drakkisath, UBRS), Skyshroud Leggings (Omokk), Nacreous Shell Necklace (Strat), Robe of the Archmage/Void and Belt of the Archmage (Tailoring), Sageblade (BS), Dryad's Wrist Bindings (Silverwing Exalted), plus Arcanoweave Cloak from an STV vendor. Provisional.", topic = "dungeons" }
add{ q = { "healer pre raid bis", "resto shaman bis forever", "resto druid pre raid", "healing gear 60", "healer bis list", "what should my healer wear before raid", "healer pre bis forever", "priest healer pre raid", "best healing gear 60", "what gear should my resto druid farm before raids in forever", "healer pre raid list" }, a = "Beta sim list for resto Druid/Shaman: Living Crown and Ironfeather Leggings (LW), Hide of the Wild (LW cloak), Mooncloth Shoulders, Swarmtender's Footpads, Charstone Dirk (Maraudon), Orb of the Darkmoon, Dryad's Wrist Bindings, plus new STV vendor items Serenity Field (trinket) and Blessed Band of Light. Holy priests want Truefaith Vestments (Tailoring). Provisional.", topic = "dungeons" }
add{ q = { "tank pre raid bis", "prot warrior pre raid", "draconian deflector", "tank gear for ony", "tank bis list", "what should my tank wear before raid", "tank pre bis forever", "prot warrior gear before ony", "best tank gear 60", "what gear should my prot warrior farm before raids in forever", "tank pre raid list" }, a = "No confirmed Forever tank BiS yet. Classic staples like the Draconian Deflector (Drakkisath, UBRS) and Lionheart Helm are in the data, but stats may have changed; check tooltips since Expertise and unified hit replaced weapon skill. Fire resistance gear matters for Onyxia.", class = "WARRIOR", topic = "dungeons" }
add{ q = { "how many bosses in raids", "boss count raids forever", "how long is hyjal raid", "bosses per raid", "how many bosses in hyjal summit and barrow deeps", "raid boss count", "how long does a hyjal summit clear take", "how many bosses does each forever raid have", "boss numbers raids", "how many bosses total in launch raids" }, a = "Boss counts: Hyjal Summit 13, The Barrow Deeps 8, Onyxia's Lair 1. Counts come from the Legacy raid challenges.", topic = "dungeons" }
add{ q = { "can horde and alliance raid together", "cross faction raid forever", "raid with other faction", "cross faction raids", "can i raid with my alliance friend as horde", "mixed faction raids", "can horde join alliance raids in forever", "cross faction raiding", "is there any way to raid with the other faction", "raid with ally as horde" }, a = "No. Both new raids are open only to players on the same ruleset and faction, so no cross-faction groups.", topic = "dungeons" }
add{ q = { "raid week plan", "how to run 10 and 20 man", "raid schedule guild forever", "split raids", "how should my guild split raids", "guild raid plan forever", "raid schedule tips", "how do we run both 10 and 20 man each week", "raid week schedule", "best way to organize a week of raids with a 10 and a 20 man", "raid planning forever" }, a = "With a 10 and a 20 opening together, common guild plans are one Hyjal night plus two Barrow Deeps groups, or one Hyjal night with the strongest ten doing Barrow Deeps. That's guild advice, not a Blizzard rule; lockout sharing between the two raids is not yet published.", topic = "dungeons" }
add{ q = { "rend gauntlet", "how to do rend", "ubrs rend event", "rend waves", "rend event", "how does the rend event work", "how do we beat the rend waves", "rend event strat", "rend blackhand fight ubrs", "how do we beat the rend waves in ubrs without wiping", "rend waves tips" }, a = "Classic baseline: talking to Nefarius starts Rend's event in UBRS: waves of Blackhand Dragon Handlers, Chromatic Whelps and Chromatic Dragonspawn, then Gyth (frost/fire/poison breath) with Rend riding. Pull back toward the entrance and clear each wave fast. Horde need Rend's head for the Onyxia chain.", src = "classic", topic = "dungeons" }
add{ q = { "the beast ubrs", "how to kill the beast", "beast fear ubrs", "how to beat the beast", "the beast fight", "how do we stop getting feared on the beast", "tactics for the beast in ubrs", "beast fear ward", "how do you tank the beast in upper blackrock spire", "beast ubrs tips" }, a = "Classic baseline: The Beast in UBRS uses Fireball, Fire Blast, Terrifying Roar (fear) and Knock Away. Fight it in the open, pre-place Fear Ward/Tremor Totem, keep casters out of range of the roar and interrupt where possible. Clear the Blackhand Elites nearby first.", src = "classic", topic = "dungeons" }
add{ q = { "emperor thaurissan", "brd final boss", "moira bronzebeard", "dont kill moira", "thaurissan fight", "how do we kill emperor", "brd last boss strat", "should we kill moira", "emperor and moira", "how do we kill emperor without moira healing him the whole time", "emperor strat brd" }, a = "Classic baseline: Emperor Dagran Thaurissan fights with Princess Moira, who heals him. CC or kill her to finish fast, but keep her alive if you're on the Alliance quest The Princess Saved?. Thaurissan drops Hand of Justice, a key pre-raid melee trinket.", src = "classic", topic = "dungeons" }
add{ q = { "profession changes forever", "what changed with professions", "are professions different in forever", "forever profession overview", "prof changes forever", "how are professions different from classic", "professions overview", "what's new with professions in wow forever", "proffesion changes", "are profs reworked in forever", "how many profs and whats the cap in forever", "quick rundown of professions forever", "what changed with professions in forever" }, a = "You get 2 primary professions plus all 3 secondaries (Cooking, First Aid, Fishing); cap is still 300. Big changes: 600+ new recipes, camping objects for every profession, a Professions window on K with search, filters and recipe tracking, a reagent bag slot, specializations, and Merchant's Favor recipe vendors. Healing potions moved from Alchemy to First Aid. There is no Jewelcrafting.", topic = "economy" }
add{ q = { "profession skill tiers", "when can i train journeyman", "expert level requirement", "artisan requirements", "profession level requirements", "profession rank requirements", "what level for journeyman", "what level do i need for expert profession", "artisan level requirement", "when can i train artisan", "prof lvl reqs", "what skill and level do i need to train the next rank", "journeyman expert artisan levels", "what level do i need to train journeyman" }, a = "Apprentice: gathering from level 1, crafting and secondaries from level 5, cap 75. Journeyman: level 10 and skill 50, cap 150. Expert: level 20 and skill 125, cap 225. Artisan: level 35 and skill 200, cap 300. Artisan for most crafting professions comes from one special trainer, and Cooking, Fishing and First Aid need a book or quest for Expert and Artisan.", topic = "economy" }
add{ q = { "how to open professions window", "profession hotkey", "where is my tradeskill window", "how do i track a recipe", "professions window", "how do i open professions", "where is my profession window", "tradeskill window forever", "how to track a recipe", "profession keybind", "cant find my crafting window", "what key opens professions in forever", "how do i open my professions window" }, a = "Professions now have their own window. Open it from the micro menu or press K. You can search and filter recipes, track a recipe in the objectives tracker, and link a whole profession in chat. Skill-up colours: orange always gives a point, yellow usually does, green rarely does, grey never does.", topic = "economy" }
add{ q = { "how to unlearn profession", "drop a profession", "change profession forever", "unlearn tradeskill", "unlearn profession", "how do i drop my profession", "how to change professions", "how to unlearn a tradeskill", "remove profession forever", "want to swap herbalism for mining how", "how do i get rid of a profession", "unlearn prof", "how do i unlearn a profession in forever" }, a = "In the Professions window (K), click the red X next to the profession's skill bar and type the confirmation text. Relearning starts you from skill 1 and you lose found or bought recipes. Secondary professions (Cooking, First Aid, Fishing) can't be unlearned.", topic = "economy" }
add{ q = { "starter gathering quest", "mining for dummies", "free profession points starting zone", "wild harvest quest", "wild harvest", "starting zone profession quest", "free profession skill quest", "gathering quest starting zone", "free skill points profession", "is there a quest for free mining points", "starter zone herbalism quest", "is there a free mining quest in the starting zone" }, a = "Each starting zone offers a quest for one gathering profession, worth 2 free skill points: Mining for Dummies (Mining), Pelt Collecting for Beginners (Skinning) or Wild Harvest (Herbalism). Junior trainers in starter areas, such as Kelsey Fargo in Northshire, teach Mining, and level-1 Poor Copper Veins exist there.", topic = "economy" }
add{ q = { "reagent bag forever", "reagent bag slot", "linen reagent bag", "best early bag", "reagent bag", "reagent bag slot forever", "best starter bag", "what goes in the reagent slot", "how big are reagent bags", "early bags forever", "where do i get a reagent bag", "what is the reagent bag slot in forever" }, a = "Forever has a dedicated reagent bag slot on top of your 5 normal bags. 4-slot gathering reagent bags exist from the start; Tailors craft a 6-slot Linen Reagent Bag and a Woolen Reagent Bag. The Red Linen Bag is 8 slots in Forever (6 in Classic). Zephras Isle trade supply vendors sell apprentice tradeskill bags.", topic = "economy" }
add{ q = { "tailoring bag sizes", "red mageweave bag slots", "how big is green woolen bag", "bag changes hotfix", "tailoring bags", "bag sizes forever", "red mageweave bag size", "green woolen bag size", "bag hotfix", "how many slots is mageweave bag", "tailoring bag changes", "bag sizes changed nov 11", "how many slots is a red mageweave bag now" }, a = "The Nov 11 hotfix changed bolt costs for several Tailoring bags. Current sizes: Green and Red Woolen Bag 10 slots, Green Silk Pack 12, Black Silk Pack 12, Red Mageweave Bag 14. Red Linen Bag is 8 slots in Forever. Bags are a steady seller for Tailors.", topic = "economy" }
add{ q = { "racial profession bonus", "gnome engineering racial", "tauren cultivation", "does tauren need herbalism", "gnome engineering", "racial profs forever", "do tauren get herbalism bonus", "racial bonuses for professions", "gnome engi racial changed", "tauren herb racial", "what racial profession bonuses are there in forever" }, a = "Gnome Engineering Specialization lowers the chance your gadgets backfire instead of giving bonus skill. Tauren Cultivation duplicates a herb node so you pick it twice; the copy can be picked without Herbalism, but you need Herbalism for the original (doubling your yield).", topic = "economy" }
add{ q = { "profession titles", "how to get alchemist title", "profession certification", "crafting title", "profession title", "alchemist title", "certification", "how to get profession title", "title for 300 profession", "profession certification cost", "how do i get the alchemist title", "how do i get a profession title in forever" }, a = "Buy a Profession Certification for 1,000 Merchant's Favor from your trading company (Azeroth Commerce Authority or Durotar Supply and Logistics). It needs 300 skill, no reputation, and gives the title (Alchemist, Blacksmith, Enchanter, Engineer, Leatherworker, Tailor) to all your characters at 300 in that profession.", topic = "economy" }
add{ q = { "legacy profession talents", "working overtime", "dedicated study", "best legacy talents for professions", "bountiful harvest", "best legacy talents professions", "legacy talents for gathering", "what legacy talents should i get for profs", "legacy prof tree", "what legacy talents are best for professions", "is working overtime worth it for profs", "legacy points into professions tree what do i take" }, a = "Professions Legacy tree: Working Overtime (+4% skill-up chance per rank, 5 ranks), Bountiful Harvest (+20% Scarce mats per rank, 5), Luremaster (25% extra fish with a lure per rank, 2), Performance Bonus (5% chance per rank to double Merchant's Favor from crates, 3), Bartering (-5% vendor prices per rank, 2), Master Chef (10% extra food per rank, 5), Dedicated Study (+1 to your lowest profession daily; once all are 300, 2-4 Elemental Essences).", topic = "economy" }
add{ q = { "legacy points from professions", "how to earn legacy points crafting", "legacy point 150 skill", "do professions give legacy points", "legacy points crafting", "legacy point 150", "how to earn legacy points from profs", "do i get legacy points for leveling professions", "legacy points tradeskills", "profession legacy reward" }, a = "Each crafting profession (Alchemy, Blacksmithing, Enchanting, Engineering, Leatherworking, Tailoring) gives 1 account-wide Legacy Point at 150, 225 and 300 skill. Your first point usually comes from level 25 or 150 in a crafting profession.", topic = "economy" }
add{ q = { "camping professions", "what does each profession camp item do", "camp buffs list", "campfire profession objects", "camp items", "camp buffs", "profession camp items", "what does each camp object do", "campfire objects", "what camp item does my profession make", "camping buffs" }, a = "Every profession has a camp item placed near a Campfire: First Aid Kit (Stamina), Fish Bowl (stats like Kings), Mana Well (mp5), Sharpening Wheel (Strength), Enchanted Lute (armor/stats like Mark of the Wild), Reagent Bot (vendor), Incense Candle (Intellect), Camp Tent (5% of a level rested XP), Camp Chair (2% crit), Faction Banner (Spirit). Camp buffs don't stack with the matching class buff.", topic = "economy" }
add{ q = { "how do campfires work", "basic campfire", "how many camp items", "campfire kit", "campfire", "how many camp items on a fire", "how to make a campfire", "campfire how many slots", "campfire basics", "how do campfires work in forever" }, a = "A Cook's Basic Campfire (Cooking 1, made with Flint and Tinder and Simple Wood) holds up to 3 camp features, one per nearby player; upgraded campfires hold 5 or 10. Sit or craft at the camp for 1 minute to get buffs. Camp features share a 1-hour cooldown. Profession camp items unlock at skill 20; ones needing 140+ drop in dungeons/raids. Journeyman Campfire Kit now needs Cooking 90.", topic = "economy" }
add{ q = { "camp item upgrades", "tier 3 camp objects", "master forge", "alchemy laboratory", "what are tier 2 camp items", "camp upgrades", "tier 3 camp", "tier 2 camp items", "how do i upgrade camp items", "camp object tiers", "what are the camp tiers", "how do i get tier 3 camp items" }, a = "Each profession has 3 camp tiers: Alchemy Mana Well/Fermenter/Alchemy Laboratory, Blacksmithing Sharpening Wheel/Anvil/Master Forge, Enchanting Lute/Arcane Salvager/Arcane Forge, Engineering Reagent Bot/Repair Bot/Anarchist's Workbench, Leatherworking Tent/Tanning Rack/Sewing Machine, Mining Lodestone/Rock Garden/Molten Foundry, Herbalism Candle/Greenhouse/Seed Hybridizer, Skinning Chair/Field Guide/Trapper's Workbench, Tailoring Banner/Spinning Wheel/Loom, Fishing Bowl/Rack/Hut. Higher tiers unlock recipes.", topic = "economy" }
add{ q = { "best profession combo", "what professions should i pick", "profession pairs", "best professions for gold", "best professions", "best prof combo", "what profs should i take", "best profession pairs", "what professions go together", "which profs make the most money", "good profession combinations", "what profession combo should i pick in forever" }, a = "Standard pairs: Herbalism + Alchemy (gold and self-sufficiency), Mining + Blacksmithing (plate/melee), Mining + Engineering (PvP and utility), Tailoring + Enchanting (casters), Skinning + Leatherworking (leather/mail users). Everyone should level Cooking, Fishing and First Aid since all three secondaries can be learned.", topic = "economy" }
add{ q = { "best professions for mage", "warlock professions", "caster professions forever", "priest professions", "mage professions", "caster professions", "best profs for mage", "what profs for my lock", "best professions for caster", "should my mage take tailoring", "what professions should my mage take" }, a = "Mage, Warlock and Shadow Priest: Tailoring + Enchanting. Tailoring covers most crafted pre-raid pieces (bind-on-pickup Robe of the Archmage / Robe of the Void; Netherpearl Cuffs for Shadow) and Enchanting adds the spell power necklace or Brilliant Wand. Holy Priests gain less from Tailoring (only Mooncloth gloves/boots). PvP Priests may prefer Tailoring + Engineering. Based on beta data.", topic = "economy" }
add{ q = { "best professions for hunter", "rogue professions forever", "hunter rogue profession pick", "hunter professions", "rogue professions", "best profs for hunter", "best profs for rogue", "what profs for my rogue", "hunter profession pick", "should my hunter take leatherworking", "rogue profs forever", "what professions should my hunter take" }, a = "Hunter and Rogue: Leatherworking + Blacksmithing. Tribal Leatherworking gives the Devilsaur Gauntlets and Leggings, and Blacksmithing gives bound weapons like the Legionite Glaive. Use the auction house for leather and bars. Based on beta BiS data; may change after raids.", topic = "economy" }
add{ q = { "warrior professions forever", "paladin professions", "best professions for tank", "plate professions", "warrior professions", "tank professions", "best profs for warrior", "best profs for pally", "plate profs", "what profs for my prot warrior", "should my pally take bs", "what professions should my warrior take" }, a = "Warriors and Paladins: Blacksmithing first. Arms/Fury/Ret pair it with Leatherworking; Protection tanks take Blacksmithing + Mining (the Sentinel's Gloves are bound). Blacksmiths also craft the Artisan's Tier set pieces at 300. Beta-based recommendation.", topic = "economy" }
add{ q = { "druid professions forever", "shaman professions", "resto shaman professions", "feral professions", "druid professions", "best profs for druid", "best profs for shaman", "resto shaman profs", "feral profs", "what profs for my druid", "balance druid professions", "what professions should my druid take" }, a = "Druid: Leatherworking + Tailoring for Balance and Resto (covers all crafted pieces); Feral can just do Skinning + Leatherworking. Shaman: Enhancement Leatherworking + Enchanting (Totem of Thunder relic), Elemental and Resto Leatherworking + Tailoring. Enchanters can now craft relics, idols and totems.", topic = "economy" }
add{ q = { "where is artisan alchemy trainer", "alchemy trainer 225", "artisan alchemy", "artisan alchemy trainer", "alchemy 225 trainer", "where to train artisan alchemy", "kylanna windwhisper", "who trains alchemy past 225", "artisan alchemy location", "wher is the artisan alchemy trainer", "alchemy trainer feralas" }, a = "Artisan Alchemy: Kylanna Windwhisper at Feathermoon Stronghold, Feralas (32.6, 43.7) for Alliance; Rogvar in Stonard, Swamp of Sorrows (48.3, 55.5) for Horde. Master Mycologist Shurome at the Emerald Sanctuary, Felwood (51.5, 81.9) is neutral. Expert: Ainethil in Darnassus or Doctor Herbert Halsey in Undercity.", topic = "economy" }
add{ q = { "artisan blacksmithing trainer", "where to train blacksmithing 225", "brikk keencraft", "expert blacksmith trainer", "artisan bs trainer", "bs 225 trainer", "where to train bs past 225", "brikk", "artisan blacksmith location", "who trains artisan blacksmithing", "wher is the artisan bs trainer", "blacksmith trainer booty bay", "wher is the artisan blacksmithing trainer" }, a = "Artisan Blacksmithing for both factions is Brikk Keencraft in Booty Bay, Stranglethorn Vale (29.0, 75.5). Expert (needs skill 125, level 20, 50 silver): Bengus Deepforge in Ironforge, Alard Schmied in Dalaran, or Saru Steelfury in Orgrimmar. Buy a Blacksmith Hammer before 75.", topic = "economy" }
add{ q = { "artisan enchanting trainer", "annora location", "where to learn artisan enchanting", "expert enchanting trainer", "artisan enchanting", "annora", "where is annora", "enchanting 225 trainer", "artisan enchanting location", "who trains artisan enchanting", "annora uldaman", "wher do i train enchanting past 225", "wher is the artisan enchanting trainer" }, a = "Artisan Enchanting is Annora inside Uldaman, south of the Temple Hall, for both factions (enter by the Badlands back door; /way #1418 65.3 42.6). Expert: Kitta Firewind (Elwynn), Vanessa Sellers (Dalaran) or Melanie Sable (Riverglades) for Alliance; Hgarth at Sun Rock Retreat, Stonetalon (49.2, 57.2) for Horde.", topic = "economy" }
add{ q = { "artisan engineering trainer", "engineering trainer gadgetzan", "where to learn engineering 225", "artisan engi trainer", "engineering 225 trainer", "buzzek", "gadgetzan engineering trainer", "who trains artisan engineering", "artisan engineering location", "wher is the artisan engineering trainer", "engineering trainer tanaris" }, a = "Artisan Engineering: Buzzek Bracketswing in Gadgetzan, Tanaris (52.2, 27.6), or Kaylaena Springwhisper in Mount Hyjal (60.2, 61.4); both serve either faction. Expert: Springspindle Fizzlegear in Ironforge or Roxxik in Orgrimmar.", topic = "economy" }
add{ q = { "artisan leatherworking trainer", "leatherworking trainer 225", "where to train leatherworking", "artisan lw trainer", "lw 225 trainer", "where to train lw past 225", "drakk stonehand", "artisan leatherworking location", "who trains artisan leatherworking", "wher is the artisan leatherworking trainer", "leatherworking trainer hinterlands" }, a = "Artisan Leatherworking: Drakk Stonehand at Aerie Peak, Hinterlands (13.4, 43.4) for Alliance; Hahrana Ironhide at Camp Mojache, Feralas (74.4, 43.1) for Horde. Expert: Telonis in Darnassus or Una in Thunder Bluff.", topic = "economy" }
add{ q = { "artisan tailoring trainer", "tailoring trainer 225", "where to learn artisan tailoring", "artisan tailoring", "tailoring 225 trainer", "timothy worthington", "where to train tailoring past 225", "artisan tailoring location", "who trains artisan tailoring", "wher is the artisan tailoring trainer", "tailoring trainer theramore" }, a = "Artisan Tailoring: Timothy Worthington on Theramore Isle, Dustwallow Marsh (66.2, 51.6) for Alliance; Daryl Stack in Tarren Mill, Hillsbrad (63.6, 20.8) for Horde. Expert: Georgio Bolero or Lawrence Schneider in Stormwind, Charles Worth in Dalaran, or Josef Gregorian in Undercity.", topic = "economy" }
add{ q = { "artisan mining trainer", "artisan herbalism trainer", "skinning trainer 225", "gathering trainers", "artisan mining", "artisan herbalism", "artisan skinning", "gathering trainer", "where to train mining 225", "where to train herbalism 225", "who trains artisan mining", "do gathering trainers teach all ranks", "wher is the artisan mining trainer" }, a = "Gathering trainers outside starter areas teach every rank, so any city/town trainer works. Examples: Mining - Brock Stoneseeker (Thelsamar) or Brek Stonehoof (Thunder Bluff); Herbalism - Cylania Rootstalker (Silverwind Refuge, Ashenvale) or Ruw (Camp Mojache); Skinning - Balthus Stoneflayer (Ironforge) or Dranh (Camp Taurajo). Train again at 75, 125 and 200.", topic = "economy" }
add{ q = { "first aid 1-300", "fastest first aid leveling", "bandage leveling guide", "first aid route", "first aid leveling", "level first aid", "first aid 1 300", "bandage leveling", "first aid guide", "fastest way to level first aid", "fa 1-300", "how do i level bandages", "how do i level first aid fast" }, a = "Linen Bandage to 40, Heavy Linen to 80, Wool to 115, Heavy Wool to 150, Silk to 180, Heavy Silk to 210, Mageweave to 240, Heavy Mageweave to 260, Runecloth to 290, Heavy Runecloth to 300. Rough cloth needs: 170 Linen, 150 Wool, 135 Silk, 110 Mageweave, 75 Runecloth. Expert book and Heavy Silk/Mageweave manuals come from Deneb Walker (Stromgarde, Arathi) or Balai Lok'Wein (Brackenwall, Dustwallow).", topic = "economy" }
add{ q = { "artisan first aid", "triage quest", "how to get first aid 300", "first aid 225", "triage", "first aid 300", "how to do triage", "first aid 225 quest", "first aid stuck at 225", "how to get artisan first aid", "triage quest location", "how do i do the triage quest for first aid" }, a = "Artisan First Aid is the Triage quest (level 35+): Doctor Gustaf VanHowzen on Theramore Isle (67.5, 48.8) for Alliance or Doctor Gregory Victor in Hammerfall, Arathi (73.5, 36.9) for Horde. Save 15 patients with Triage Bandages before 6 die; heal critical (red) patients first.", topic = "economy" }
add{ q = { "first aid healing potions", "who makes healing potions now", "can first aid make potions", "health potions forever", "first aid potions", "healing potions forever", "who makes healing potions", "can first aid make health potions", "health pots forever", "healing potions moved to first aid", "do alchemists make healing potions", "first aid healing pots", "who makes healing potions in forever" }, a = "In Forever, healing potions moved from Alchemy to First Aid, so anyone can make them; First Aid also makes debuff-removing items. Potions span Minor Healing (1-55) to Major Healing (275-300) using herbs, vials and spices. You can level First Aid with potions instead of bandages where cloth is pricier.", topic = "economy" }
add{ q = { "cooking 1-300", "fastest cooking leveling", "cooking route forever", "cooking leveling", "level cooking", "cooking 1 300", "cooking guide", "fastest way to level cooking", "cooking route", "how do i level cooking fast", "cooking 1-300 forever" }, a = "Route: Brilliant Smallfish 1-50, Longjaw Mud Snapper 50-100, Bristle Whisker Catfish 100-150, Curiously Tasty Omelet (Raptor Eggs) 150-175, Mithril Head Trout 175-225, Filet of Redgill 225-250 (Kelsey Yance, Booty Bay), Poached Sunscale Salmon 250-300 (Gikkix, Steamwheedle Port). Fishing feeds almost all of it.", topic = "economy" }
add{ q = { "expert cookbook", "artisan cooking quest", "clamlette surprise", "how to get cooking past 225", "artisan cooking", "cooking 225", "cooking stuck at 225", "how to get artisan cooking", "where to buy expert cookbook", "cooking past 225", "how do i get cooking past 225" }, a = "Expert Cookbook: Shandrina in Ashenvale (49.5, 67.0) for Alliance, Wulan in Desolace (26.1, 69.7) for Horde. Artisan: Clamlette Surprise from Dirge Quikcleave in Gadgetzan (52.6, 27.9), level 35; bring 12 Giant Eggs, 10 Zesty Clam Meat and 20 Alterac Swiss first. Cooking 101 follows the camping intro quest.", topic = "economy" }
add{ q = { "artisan fishing", "nat pagle quest", "expert fishing book", "fishing past 225", "nat pagle", "expert fishing", "fishing 225", "fishing stuck at 225", "how to get artisan fishing", "old man heming", "where to buy expert fishing book", "how do i get fishing past 225" }, a = "Expert fishing book: Old Man Heming in Booty Bay (27.5, 77.0). Artisan: Nat Pagle, Angler Extreme quest from Nat Pagle in Dustwallow Marsh (58.5, 59.8).", topic = "economy" }
add{ q = { "fishing changes forever", "fishing rack lures", "rare fish forever", "fish bowl buff", "fishing changes", "fishing forever", "rare fish", "fishing lures", "fish bowl", "bait and tackle", "new fish forever", "what changed with fishing", "what changed with fishing in forever" }, a = "Fishing gains new Uncommon and Rare fish, a Bait and Tackle crafting menu, a Chef's Knife for Unique Fish, and buff food that raises Fishing. Fish Bowl gives a Kings-like stat buff; Fishing Rack and Fishing Hut unlock with skill and give buffs for catching Uncommon and Rare fish. Luremaster in Legacy adds bonus catches.", topic = "economy" }
add{ q = { "mining leveling zones", "where to level mining", "mining 1-300", "thorium where", "mining leveling", "level mining", "mining 1 300", "mining zones", "where to mine", "where is thorium", "best zones for mining", "mining route", "wher should i level mining" }, a = "Copper in starter zones to 65, Tin/Bronze in Westfall, Silverpine, Barrens, Loch Modan to ~115, Iron/Silver/Gold in Arathi, Alterac, Stranglethorn, Thousand Needles to ~175, Mithril in Badlands, Searing Gorge, Feralas, Tanaris, Hinterlands to 230, Dark Iron in Searing Gorge/Burning Steppes 230-245, Small Thorium in Winterspring, Plaguelands, Un'Goro, Silithus 245-295, then Rich Thorium.", topic = "economy" }
add{ q = { "mining changes forever", "new ores forever", "azerothium bar", "dynamic node respawn", "mining changes", "mining forever", "new ores", "azerothium", "node respawn", "pyrite", "bauxite", "what changed with mining", "what changed with mining in forever" }, a = "Ore nodes respawn faster when more players are around. New/changed ores: Pyrite, Bauxite, Pitchblende; new bars: Azerothium Bar (smelt from 275) and Heavy Thorium Bar. Find Minerals can run alongside other tracking. Mining camp: Lodestone (attack power like Might), Rock Garden (spawns common ore), Molten Foundry (high-end smelting).", topic = "economy" }
add{ q = { "herbalism leveling zones", "where to level herbalism", "herb route 1-300", "herbalism leveling", "level herbalism", "herb 1 300", "herb zones", "where to herb", "best zones for herbalism", "herb route", "herbalism route forever", "wher should i level herbalism" }, a = "Starter zones to 70 (Peacebloom, Silverleaf, Earthroot); Barrens/Darkshore/Loch Modan/Silverpine; Wetlands, Hillsbrad, Stonetalon; Arathi and north Stranglethorn; Tanaris or Searing Gorge (Purple Lotus, Firebloom); Hinterlands (Sungrass, Golden Sansam); then Felwood and Un'Goro for Dreamfoil, Gromsblood, Plaguebloom, Icecap, Black Lotus.", topic = "economy" }
add{ q = { "herbalism changes forever", "scarce herbs", "frilled lichen", "herb seeds greenhouse", "herbalism changes", "herbalism forever", "rosecap", "stranglevine", "herb seeds", "what changed with herbalism", "what changed with herbalism in forever" }, a = "New Scarce bonus herbs (Frilled Lichen, Rosecap, Stranglevine) drop while picking normal herbs; new herbs include Marefoil, Demonsage and Death Lotus. Herb Seeds (Commonplace to Scarce) grow in the Herbalism camp greenhouse; the Seed Hybridizer upgrades seeds. Scarce herbs and Black Lotus keep their value far better than common herbs.", topic = "economy" }
add{ q = { "skinning leveling zones", "where to level skinning", "skinning 1-300", "skinning leveling", "level skinning", "skinning 1 300", "skinning zones", "where to skin", "best zones for skinning", "skinning route", "skinning route forever", "wher should i level skinning" }, a = "Starter zones to 75; Barrens, Silverpine, Loch Modan, Darkshore, Westfall, Redridge, Wetlands, Hillsbrad, Ashenvale, Duskwood to 150; Shimmering Flats, Arathi, Desolace, Stranglethorn, Riverglades, Dustwallow, Badlands to 205; Feralas, Tanaris, Hinterlands, Searing Gorge, Azshara to 260; Un'Goro, Blasted Lands, Felwood, Plaguelands, Winterspring, Silithus to 300.", topic = "economy" }
add{ q = { "skinning changes forever", "pristine leather", "fel leather", "skinning camp", "skinning changes", "skinning forever", "fel hide", "new skinning mats", "what changed with skinning", "what changed with skinning in forever" }, a = "New skinning materials include Fel Hide, Fel Leather and Pristine Scale/Leather/Hide (Scarce). Camp items: Camp Chair (2% crit), Field Guide (crit plus Track Beasts), Trapper's Workbench (crit plus a trap). Bountiful Harvest boosts Scarce yields. Skinning leather sells to vendors in stacks even when the AH is flooded.", topic = "economy" }
add{ q = { "alchemy changes forever", "new elixirs forever", "what does alchemy do now", "alchemy dyes", "alchemy changes", "alchemy forever", "new elixirs", "what does alchemy make now", "alchemy no healing potions", "alch changes", "what changed with alchemy", "what changed with alchemy in forever" }, a = "Alchemists no longer make healing potions (now First Aid) but craft dyes for pricier crafted gear. The Alchemy Laboratory camp item lets you make flasks anywhere, no Scholomance trip. New elixirs: Minor Arcane Elixir (low-level spell power), Elixir of the Grizzly (Strength/crit), Elixir of Cunning (Agi/Int, for MM hunters); Rage Potion works for Druids. Greater Firepower was renamed Elixir of Holy Power.", topic = "economy" }
add{ q = { "alchemy 1-300", "fastest alchemy leveling", "alchemy route forever", "alchemy leveling", "level alchemy", "alchemy 1 300", "alchemy guide", "fastest way to level alchemy", "alchemy route", "alch 1-300", "alchemy 1-300 forever", "how do i level alchemy fast" }, a = "Minor Force 1-12, Minor Defense to 55, Minor Mana Potion to 65, Minor Fortitude to 90, Elixir of Wisdom to 120, Lesser Mana Potion to 160, Mana Potion to 195, Elixir of Agility to 205, Greater Mana Potion to 240 (make a Philosopher's Stone at 225), Draught of Detect Undead to 260, Superior Mana Potion to 270, Major Discolored Healing Potion to 300 (trainer after a short quest: the Odd Child in Westfall or Apothecary Renferrel in Silverpine). About 650 herbs.", topic = "economy" }
add{ q = { "blacksmithing 1-300", "fastest blacksmithing leveling", "bs leveling route", "bs leveling", "level blacksmithing", "bs 1 300", "blacksmithing guide", "fastest way to level bs", "bs route", "bs 1-300", "blacksmithing 1-300 forever", "how do i level blacksmithing fast" }, a = "Sharpening/Grinding Stones to 75, Silver Rods and Runed Copper Belts to 95, Patterned Bronze Bracers/Bronze Shortswords to 140, Bronze Warhammer to 150, Green Iron Bracers to 175, Golden Scale Bracers to 195, Mithril Plate Pants to 210, Heavy Mithril Axe/Breastplate to 225, Heavy Mithril Boots to 240, then Imperial Plate Belt/Bracers/Boots/Leggings to 300 (Imperial Plate lowered to 240 in Forever). Needs ~1,900 Thorium Bars for 225-300.", topic = "economy" }
add{ q = { "blacksmithing changes forever", "new blacksmith plans", "anvil camp", "sharpening stones stack", "bs changes", "blacksmithing forever", "new bs plans", "what changed with blacksmithing", "new blacksmithing recipes", "bs changes forever", "what changed with blacksmithing in forever" }, a = "Hundreds of new plans come from Merchant's Favor vendors and dungeon/raid drops, and old recipes were buffed for early levels. Sharpening Stones and Weightstones now stack with poisons and Windfury. A portable Anvil (later Master Forge) lets you craft anywhere. Coarse Grinding Stone gives skill-ups to 90 after a hotfix.", topic = "economy" }
add{ q = { "blacksmith specialization", "armorsmith or weaponsmith", "how to become weaponsmith", "bs spec", "armorsmith", "weaponsmith", "armorsmith vs weaponsmith", "how to become armorsmith", "which bs spec", "bs specialization forever", "weaponsmith quest", "should i be an armorsmith or weaponsmith" }, a = "At Blacksmithing 200 and level 40 you can pick Armorsmithing or Weaponsmithing; Weaponsmiths can further go Axe, Sword or Hammer. It's optional and can wait. The specialization also gates which Artisan's Tier plans (gloves, shoulders, boots) you can buy.", topic = "economy" }
add{ q = { "artisan's tier", "crafted tier set", "master forge blueprint", "how to craft tier set pieces", "artisans tier", "crafted tier", "tier set crafting", "master forge", "how to make tier", "crafted tier set forever", "artisan's tier set", "blacksmith tier set", "how do i craft artisan's tier pieces" }, a = "Blacksmiths at 300 make Artisan's Tier class set pieces (ilvl 61, BoE) for shoulders, gloves, legs and boots. You need a Master Forge camp object (Blueprint drops from dungeon bosses) and Malleable Essence of Nature, from disenchanting Hyjal Summit or Barrow Deeps loot. Plans are sold by Aisarra Nightmeadow in Mount Hyjal and need Guardians of Hyjal rep.", topic = "economy" }
add{ q = { "artisan tier limit", "can i wear more than one crafted tier", "rousing seed pod", "unique equipped artisan's tier", "artisan tier unique", "artisans tier limit", "unique equipped tier", "only one crafted tier", "can i wear two crafted tier pieces", "artisan tier unique equipped", "crafted tier limit", "can i wear more than one artisan's tier piece" }, a = "Crafted tier pieces are Unique-Equipped: Artisan's Tier (1), so only one at a time. The Rousing Seed Pod (10g, level 60, Revered with Guardians of Hyjal, from Rhylin Stonethorn in Mount Hyjal) raises the limit to two. Crafted and raid pieces count toward the same set bonus.", topic = "economy" }
add{ q = { "enchanting 1-300", "fastest enchanting leveling", "enchanting route forever", "enchanting leveling", "level enchanting", "enchanting 1 300", "enchanting guide", "fastest way to level enchanting", "enchanting route", "ench 1-300", "enchanting 1-300 forever", "how do i level enchanting fast" }, a = "Runed Copper Rod, then Bracer Inferior Stamina to 20, Chest Inferior Stamina to 75, Bracer Minor Stamina to 104, Runed Silver Rod, Shield Minor Stamina to 130, Bracer Lesser Stamina to 155, Runed Golden Rod, Boots Lesser Agility to 180, Bracer Strength to 200, Runed Truesilver Rod, Cloak Greater Defense to 225, Gloves Agility to 250, Lesser Mana Oil to 270, Shield Greater Stamina to 300 (~210 Dream Dust).", topic = "economy" }
add{ q = { "enchanting changes forever", "new enchants forever", "necklace enchants", "enchanting wands relics", "enchanting changes", "enchanting forever", "new enchants", "enchanting wands", "relics enchanting", "what changed with enchanting", "ench changes forever", "what changed with enchanting in forever" }, a = "New weapon enchants (Revelation, Recovery, Insight) and necklace enchants (Strength, Spell Power, Healing Power, Agility, Deflection). Novice's Practice Wand is craftable at skill 1 and wands gain spell power. Enchanters can craft staves, relics, idols and totems via Merchant's Favor recipes. Some enchants were renamed (Minor Health is now Inferior Stamina). Lesser Spirit boots/bracers now give Spirit.", topic = "economy" }
add{ q = { "arcane salvager", "enchanting camp items", "enchanted lute", "disenchant bonus", "enchanting camp", "enchanting camp item", "what does the arcane salvager do", "enchanted lute buff", "enchanting camp buff", "what does the enchanting camp item do" }, a = "Enchanting camp: Enchanted Lute (Mark of the Wild-style armor/stats/resists), upgraded by the Arcane Salvager and Arcane Forge. The Arcane Salvager gives a disenchanting bonus, now works for lower-level enchanters, and needs a Runed Golden Rod (was Truesilver). The rare Enchantress's Spire staff (Strashaz Enchantress, Alcaz Prison) cuts Disenchant cast time by 25%.", topic = "economy" }
add{ q = { "engineering 1-300", "fastest engineering leveling", "engineering route", "engineering leveling", "level engineering", "engineering 1 300", "engineering guide", "fastest way to level engineering", "engi route", "engi 1-300", "engineering 1-300 forever", "how do i level engineering fast" }, a = "Rough Blasting Powder to 30, Copper Bolts to 50, Arclight Spanner, Rough Copper Bomb to 75, Coarse Blasting Powder to 90, Coarse Dynamite to 100, Silver Contact, Bronze Tube to 125, Standard Scope to 135, Whirring Bronze Gizmo to 150, Bronze Framework, Explosive Sheep to 175, Solid Blasting Powder to 195, Mithril Tube, Unstable Trigger to 215, Mithril Casing to 238, Hi-Explosive Bomb to 250, Dense Blasting Powder, Thorium Widget to 285, Thorium Tube to 300. ~165 Thorium Bars.", topic = "economy" }
add{ q = { "engineering changes forever", "saf t dynamite", "satchel of copper bombs", "clanking cord", "engineering changes", "engineering forever", "saf-t dynamite", "satchel of bombs", "what changed with engineering", "new engineering items", "engi changes forever", "what changed with engineering in forever" }, a = "New: Saf T explosives (Saf T Dynamite, Saf T Copper Bomb) that non-Engineers can use, a thrown-slot Satchel of Copper Bombs needing no ammo, and the Clanking Cord belt for every armor type. Engineering camp: Reagent Bot (vendor), Repair Bot, Anarchist's Workbench; none give stat buffs. Iron Grenade vendor price was cut to 1s 25c.", topic = "economy" }
add{ q = { "goblin or gnomish", "engineering specialization forever", "how to become goblin engineer", "goblin or gnomish engineering", "gnomish or goblin", "engi spec", "engineering spec", "how to become gnomish engineer", "which engineering spec", "goblin vs gnomish forever", "engineering specialization quest", "should i go goblin or gnomish engineering" }, a = "At Engineering 200 pick Goblin or Gnomish and finish its quest chain. Goblin: explosives like The Big One and the Dimensional Ripper - Everlook. Gnomish: Mind Control Cap, Ultrasafe Transporter: Gadgetzan, World Enlarger. Switching means unlearning Engineering and releveling from 1, losing learned recipes.", topic = "economy" }
add{ q = { "leatherworking 1-300", "fastest leatherworking leveling", "lw leveling route", "lw leveling", "level leatherworking", "lw 1 300", "leatherworking guide", "fastest way to level lw", "lw route", "lw 1-300", "leatherworking 1-300 forever", "how do i level leatherworking fast" }, a = "Light Leather to 30, Light Armor Kit to 45, Cured Light Hide, Embossed Gloves to 85, Fine Leather Belt to 100, Dark Leather Pants to 115, Dark Leather Belt/Cured Heavy Hide to 145, Toughened Gloves to 155, Barbaric Shoulders and Gem-studded Belt to 190, Guardian Gloves to 200, Thick Armor Kit to 210, Nightscape Pants to 240, Wicked Leather Gauntlets to 270, Heavy Scorpid Helm to 300. ~1,900 leather total.", topic = "economy" }
add{ q = { "leatherworking specialization forever", "tribal dragonscale elemental", "which leatherworking spec", "lw spec", "leatherworking spec", "tribal", "dragonscale", "elemental leatherworking", "which lw spec", "lw specialization", "best leatherworking spec", "which leatherworking spec should i pick" }, a = "Choose at 225. Tribal: Wolfshead Helm, Devilsaur, Warbear, Chimeric, Ironfeather, Hide of the Wild (physical/druid). Dragonscale: Green (healer), Blue (caster) and Black (physical) Dragonscale sets. Elemental: Living (healer), Volcanic, Stormshroud, Molten Helm/Belt. Resistance stats were removed, so each spec's sets target roles. Hunters and Rogues want Tribal for Devilsaur.", topic = "economy" }
add{ q = { "leatherworking changes forever", "deeprock salt", "salt shaker", "tanning rack", "lw changes", "leatherworking forever", "what changed with leatherworking", "new lw patterns", "lw changes forever", "what changed with leatherworking in forever" }, a = "Hundreds of new patterns, new Forceful (physical) and Mystic (caster) Rugged Armor Kits. Camp: Camp Tent, Tanning Rack and Sewing Machine each give 5% of a level rested XP; Rack and Machine unlock recipes. Tanning Rack now needs skill 125 (was 140). Salt Shaker turns Deeprock Salt into Refined Deeprock Salt every 3 days, needed for Cured Rugged Hide.", topic = "economy" }
add{ q = { "tailoring 1-300", "fastest tailoring leveling", "tailoring route forever", "tailoring leveling", "level tailoring", "tailoring 1 300", "tailoring guide", "fastest way to level tailoring", "tailoring route", "tailor 1-300", "tailoring 1-300 forever", "how do i level tailoring fast" }, a = "Linen Bolts to 43, Linen Belt to 70, Reinforced Linen Cape to 75, Woolen Cape to 100, Silk Bolts to 110, Double-stitched Woolen Shoulders to 125, Azure Silk Hood, Lesser Wizard's Robe to 139, Mageweave bolts, Earthen Vest to 160, Robe of Power to 170, Black Mageweave Vest to 180, Orange Mageweave Shirt to 190, Black Mageweave Gloves to 205, Runecloth Belt to 234, Runecloth Cloak/Boots/Cuffs to 280, Wisdom of the Timbermaw to 285, Venomspew set to 300.", topic = "economy" }
add{ q = { "tailoring changes forever", "new tailoring patterns", "shadow circlet", "tailoring camp", "tailoring changes", "tailoring forever", "new tailoring", "what changed with tailoring", "new tailoring recipes", "spell school gear tailoring", "what changed with tailoring in forever" }, a = "New spell school gear (Shadow, Frost, Holy, Healing, Arcane, Fire Circlet/Gloves/Sash/Boots) comes from Merchant's Favor vendors; Filigreed Shadow Gown and Leggings drop in low dungeons. Several old patterns gained spell power. Tailoring camp: Faction Banner (Spirit like Divine Spirit), Spinning Wheel and Loom, which also unlock recipes.", topic = "economy" }
add{ q = { "kirin tor recipes", "azure skyforged", "azure profession patterns", "archmage alvareaux", "azure patterns", "alvareaux", "kirin tor vendor", "dalaran recipes", "azure profession recipes", "wher do i buy kirin tor recipes" }, a = "Archmage Alvareaux (Silver Enclave, upstairs, Dalaran in Alterac Mountains, Alliance) sells 8 Azure recipes at Kirin Tor Friendly for 10g each, all skill 175 and level-30 armor: Blacksmithing Azure Skyforged Helm/Pauldrons, Leatherworking Azure Gustwoven and Windraveled pieces, Tailoring Azure Stormsewn Cowl/Epaulets.", topic = "economy" }
add{ q = { "merchant's favor", "what is merchant's favor", "how to get merchants favor", "waylaid crate", "merchants favor", "merchant favor", "favor currency", "what is merchants favor", "how to get favor", "waylaid crates", "how do i earn merchants favor", "favor how", "how do i get merchants favor in forever" }, a = "Merchant's Favor is a currency from Waylaid Crates. Crates drop in the world and dungeons or can be bought on the AH. Fill a crate with one bundle from its list, it becomes a bound Sealed crate, and hand it in for Favor and rep. Apprentice crates pay 5 (Textiles/Ore/Herbs/Curiosities) or 10 (Fabrics/Ingots/Parts); Journeyman 10/20; Expert 15/30. Your first turn-in gives a Shipping Label quest: 50 Favor and 2,000 rep.", topic = "economy" }
add{ q = { "azeroth commerce authority location", "durotar supply and logistics location", "where to turn in waylaid crates", "marcy baker", "dokimi", "commerce authority location", "durotar supply location", "where to turn in crates", "where is azeroth commerce authority", "where is durotar supply and logistics", "waylaid crate turn in", "wher do i turn in waylaid crates" }, a = "Alliance: Azeroth Commerce Authority at Three Corners, Redridge Mountains; hand crates to Marcy Baker. Horde: Durotar Supply and Logistics outside the west gate of the Crossroads, The Barrens; hand crates to Dokimi. Each camp has recipe vendors for every crafting profession plus Cooking, a mount vendor and a rep rewards vendor.", topic = "economy" }
add{ q = { "craftsman's writ", "how do writs work", "writ reputation", "trading company reputation fast", "craftsmans writ", "writs", "writ rep", "trading company rep", "how to get trading company rep fast", "craftsman writ", "what are craftsman writs", "how do craftsman's writs work" }, a = "Craftsman's Writs drop from mobs (and now in dungeons) or come from the AH. Opening one gives a profession delivery quest (seen with a 9-hour timer). Journeyman/Expert/Artisan writs give 75/125/200 rep and no Favor; each specific writ can be done once a day. At Friendly the Uncertified Scribe sells Forged Delivery Receipts (15 Favor, turns a cheap empty crate into 50 rep); at Honored, Forger's Quill rerolls a writ.", topic = "economy" }
add{ q = { "merchant's favor rewards", "what to buy with merchant's favor", "pack kodo", "trading company mount", "favor rewards", "what to buy with favor", "merchants favor mount", "packmule", "what can i buy with merchants favor", "favor rewards list", "what should i buy with merchants favor" }, a = "Reins of the Pack Kodo: 6,000 Favor at Exalted (Huey Sunnydale / Okamache). Packmule Treat pet: 1,500 at Revered. Advertising License Application toy: 1,200 at Honored. Tabard: 200 at Exalted. Profession Certification title: 1,000 at skill 300. Recipes cost 30-45 with no rep, 60-180 at Friendly, 90-360 at Honored.", topic = "economy" }
add{ q = { "merchant's favor recipes", "trading company recipe vendor", "enchant necklace recipe where", "gnomish poultryizer", "favor recipes", "favor recipe vendor", "trading company recipes", "enchant necklace recipe", "poultryizer", "merchants favor recipe vendors", "where to buy favor recipes", "favor profession recipes", "wher do i buy merchants favor recipes" }, a = "Every crafting profession has a Favor recipe vendor (Alliance at Three Corners: Nina Surefire Alchemy, Stondry Darkhammer BS, Alynsia Enchanting, Fritz Fizzle Engineering, Daniel Stitchsong LW, Mivin Shadowweave Tailoring, Kalsey Sanden Cooking; Horde near Crossroads: Apothecary Durelle, Gor'mak, Beneris, Fizzlefuse, Pawani, Jim'bek, Aza'bek). Examples: Enchant Necklace formulas 120 at Friendly, Gnomish Poultryizer 360 at Honored, Blacksmithing armor sets 30-90.", topic = "economy" }
add{ q = { "wow token forever", "can i buy gold forever", "is there a token in forever", "character boost forever", "wow token", "buy gold", "is there a wow token", "character boost", "can i buy a boost", "is there a cash shop in forever", "token forever", "paid boost forever", "can i buy gold or a boost in forever" }, a = "No. Forever has no WoW Token and no paid character boosts, and Blizzard says there are no plans to add them. All gold comes from playing, so AH prices are purely player supply and demand.", topic = "economy" }
add{ q = { "gdkp forever", "are gdkp allowed", "gold raids forever", "gdkp", "gdkp allowed", "gold raids", "gdkp banned", "are gdkp raids allowed", "gdkp forever rules", "can i run gdkp", "gold dkp forever", "are gdkp raids allowed in forever" }, a = "No. Blizzard does not allow GDKP raids in Forever, citing real-money trading, gold laundering, and the pressure it puts on newer players. Use normal loot systems.", topic = "economy" }
add{ q = { "economy hold", "temporary economy hold", "cant use auction house or mail", "account restricted trade", "cant use ah", "cant mail", "account restricted", "why cant i use the auction house", "economy hold forever", "trade restricted account", "why do i have an economy hold on my account" }, a = "Accounts suspected of buying or selling gold for real money can get a Temporary Economy Hold, which blocks trade, mail, guild bank and Auction House while Blizzard investigates. It lifts automatically if it was a false positive and leaves no strike; confirmed RMT gets account action.", topic = "economy" }
add{ q = { "is auction house shared", "auction house rulesets", "cross faction auction house", "realmless auction house", "shared ah", "auction house shared", "cross faction ah", "realmless ah", "is the ah shared between servers", "is ah cross faction", "how does ah work forever", "is the auction house shared in forever" }, a = "Forever is realmless: you pick a ruleset (Normal, PvP or RP), and trading and grouping are limited to your faction and ruleset. Each ruleset has its own economy and auction house. Blizzard would only link AHs if a ruleset became non-viable. Changing ruleset needs a new character.", topic = "economy" }
add{ q = { "auction house deposit forever", "ah deposit change", "1 copper deposit", "why are ah deposits cheaper", "ah deposit", "auction house deposit", "cheap ah deposit", "ah deposit changed", "why are ah deposits so low", "ah posting cost", "auction deposit forever", "why are ah deposits only 1 copper" }, a = "The Nov 10 hotfix cut the minimum AH posting deposit from 1 silver to 1 copper. Blizzard pulled the AH changes on Nov 12 and said they would return after the Nov 17 maintenance, so check in game. Most quests level 48+ now also reward gold.", topic = "economy" }
add{ q = { "mail delay forever", "why does mail take an hour", "mail between alts slow", "mail delay", "mail slow", "mail takes an hour", "why is mail slow", "mail to alts", "mail between characters", "how long does mail take", "why does my mail take an hour" }, a = "Mail between different players is meant to take 60 minutes in Forever; a bug that sometimes delivered it in about 2 minutes was fixed on Nov 10. Plan AH and alt logistics around the hour delay.", topic = "economy" }
add{ q = { "mount cost forever", "how much gold for mount", "epic mount gold", "riding cost level 40", "mount cost", "how much is mount", "epic mount cost", "riding cost", "level 40 mount cost", "how much gold for epic mount", "mount gold forever", "riding training cost", "how much gold do i need for my mount" }, a = "Apprentice Riding at 40: 100g training plus a 20g mount (60%). Journeyman Riding at 60: 1,000g plus a 200g mount (100%). Honored with your home faction gives 10% off both. Paladins and Warlocks get class mounts by quest. Racial vendor mounts are bind-on-pickup.", topic = "economy" }
add{ q = { "how to make gold while leveling", "leveling gold tips", "gold while questing forever", "gold while leveling", "make gold leveling", "leveling gold", "gold questing", "how to make money while leveling", "best way to make gold leveling", "gold tips leveling", "money while leveling forever", "how do i make gold while leveling" }, a = "Take two gathering professions (Skinning plus Herbalism or Mining) and sell mats; skinning leather vendors well even when the AH is flooded. Vendor every grey, keep BoE blues/epics unequipped to sell, cook buff food for the AH, and fill Waylaid Crates. Level 48+ quests now give gold too. Save 100g for level 40 riding.", topic = "economy" }
add{ q = { "gold farming max level", "best gold farm 60", "how to make gold at 60", "gold making endgame", "gold farm 60", "best gold farm", "make gold at 60", "endgame gold", "gold farming", "how to make money at 60", "best gold farm forever", "gold making 60", "what is the best gold farm at 60" }, a = "At 60, Herbalism/Mining for rare mats (Black Lotus, Thorium, Scarce herbs like Frilled Lichen) plus selling consumables: flasks and elixirs (Alchemy), enchants, sharpening stones/weightstones, and Saf T explosives for non-Engineers. Classic farms still work: Jadefire satyrs in Felwood (Felcloth), Badlands earth elementals, Scarlets at Tyr's Hand for Runecloth. Epic mount is 1,200g total.", topic = "economy" }
add{ q = { "what sells on ah forever", "best items to sell forever", "what crafted items sell", "profession that makes most gold", "what sells on ah", "best items to sell", "most profitable profession", "ah sellers", "what sells best", "best things to sell on ah forever", "profession makes most gold", "what sells best on the ah in forever" }, a = "Steady sellers: consumables (potions, elixirs, flasks, food), bags, enchants, sharpening and weight stones, BoE crafted gear, rare herbs and Thorium. Scarce gathering mats and Black Lotus hold value; common herbs drop in price fast. Blizzard cut vendor payouts for some crafted BoP armor, so don't level crafting by vendoring.", topic = "economy" }
add{ q = { "save gold legacy talents", "bartering legacy", "frequent flier", "reagent economy talent", "save gold legacy", "bartering", "reagent economy", "legacy talents save gold", "cheaper vendor prices legacy", "what legacy talents save money", "bartering legacy talent", "what legacy talents save gold" }, a = "Legacy perks that save gold: Bartering (-5% vendor prices per rank, 2 ranks), Frequent Flier (50% off flight paths, 20% faster flights), Reagent Economy (class spells need no vendor reagents), and Performance Bonus (chance to double Merchant's Favor).", topic = "economy" }
add{ q = { "reputation amounts", "how much rep to exalted", "rep needed per level", "rep amounts", "how much rep", "rep to exalted", "rep needed", "how much rep for honored", "how much rep for revered", "rep per level", "rep thresholds", "how much rep do i need for exalted" }, a = "Neutral to Friendly 3,000, Friendly to Honored 6,000, Honored to Revered 12,000, Revered to Exalted 21,000; 42,000 total, half of it in the final bar. The Diplomat Legacy talent adds +2% rep per rank (up to +10%).", topic = "economy" }
add{ q = { "new reputations forever", "forever factions list", "what new factions are there", "new reputations", "forever factions", "new factions", "new rep forever", "what reps are new", "new factions list", "forever reputations list", "new reps", "what new factions are in forever" }, a = "New factions include Guardians of Hyjal, Barkskin Burrow and Cenarion Scouts (Mount Hyjal); Windshapers and High Order (Skyborne, Zephras Isle); Nightclaw Druids (Shadowgale Forest); Kirin Tor (Dalaran, Alliance); Darkspear Raiders and Theramore Expeditionary Force (Darkspear Islands PvP); Bolder'ok Clan, Brotherhood of the Horse and Powderfuse (Riverglades); The Watchers; Earthen Ring (Horde); plus the Azeroth Commerce Authority / Durotar Supply and Logistics trading companies.", topic = "economy" }
add{ q = { "kirin tor reputation forever", "how to get kirin tor rep", "kirin tor horde", "kirin tor", "kirin tor rep", "how to get kirin tor", "kirin tor reputation", "can horde get kirin tor", "kirin tor quests", "kirin tor forever", "how do i get kirin tor rep" }, a = "Kirin Tor is Alliance-only (Horde start Hated). Rep comes from quests: The Magical City of Dalaran, Exploring the Alliance, Heart of Disruption, Starving Arcane, Past Due (Scarlet Monastery) give 100 each. High Order Skyborne start at Friendly. Rewards: Azure crafting recipes at Friendly; tabard (25g) at Exalted. Repeatable farm not yet confirmed.", topic = "economy" }
add{ q = { "nightclaw druids rep", "more al'aketh ears", "shadowgale forest reputation", "shadowgale squirrel", "nightclaw druids", "nightclaw rep", "al'aketh ears", "shadowgale rep", "nightclaw druids reputation", "how to get nightclaw rep", "more alaketh ears", "how do i get nightclaw druids rep" }, a = "Nightclaw Druids (Shadowgale Forest, Zephras Isle): finish the story chain, then repeat More Al'Aketh Ears (rep value disputed: 200 per five ears in beta vs 1,000 in data). Friendly and Honored unlock recipes and patterns, Revered the Shadowgale Squirrel pet, Exalted the Nightclaw Mantle.", topic = "economy" }
add{ q = { "darkspear raiders rep", "theramore expeditionary force rep", "darkspear islands reputation rewards", "marks of honor turn in", "darkspear raiders", "theramore expeditionary force", "darkspear rep", "marks of honor", "darkspear islands rep", "darkspear raiders rewards", "how to get darkspear raiders rep", "theramore expeditionary rep", "how do i get darkspear raiders rep" }, a = "Earned by playing Darkspear Islands and turning in Marks of Honor quests (3 Marks per win, 1 per loss in beta). Quartermasters: Creeg Bothunk at Merchant Coast north of Ratchet (Horde) and Bryanna Embreeze at Northwatch Hold (Alliance). Friendly: trinkets; Honored: cloaks, rings, necklaces; Revered: weapons, off-hands; Exalted: armor, a tabard questline and a Legacy Point.", topic = "economy" }
add{ q = { "trading company reputation", "azeroth commerce authority rep", "durotar supply rep how", "trading company rep", "commerce authority rep", "durotar supply rep", "how to raise trading company rep", "azeroth commerce authority reputation", "durotar supply and logistics rep", "trading company rep fast", "commerce authority rep how", "how do i raise trading company rep" }, a = "Raise it with Waylaid Crates (Favor plus rep), Craftsman's Writs (75/125/200 rep each, once per writ per day) and the one-time Shipping Label quest (2,000 rep). After Friendly, buy Forged Delivery Receipts from the Uncertified Scribe to turn cheap empty crates into 50 rep each. Higher rep unlocks more recipes, the pet, toy, tabard and Pack Kodo.", topic = "economy" }
add{ q = { "argent dawn rep forever", "how to farm argent dawn", "scourgestones", "argent dawn commission", "argent dawn", "argent dawn rep", "farm argent dawn", "ad commission", "how to get argent dawn rep", "how do i farm argent dawn rep" }, a = "Classic method: wear the Argent Dawn Commission so Plaguelands undead drop Scourgestones and turn them in to Duke Nicholas Zverenhoff at Light's Hope Chapel (25 rep per Valor Token). Open-world undead stop at Honored; Scholomance and Stratholme trash to Revered, bosses to Exalted. Scholomance is the fastest. Forever itemization of rewards may differ.", src = "classic", topic = "economy" }
add{ q = { "argent dawn rewards", "argent dawn quartermaster", "mantle of the dawn", "what does argent dawn sell", "ad quartermaster", "argent dawn vendor", "what does ad sell", "argent dawn items", "miranda breechlock", "argent dawn honored rewards", "what does the argent dawn quartermaster sell" }, a = "Classic baseline: Miranda Breechlock at Light's Hope sells Honored items (Argent Boots, Dawn Treaders, Transmute Air to Fire, mana regen bracer enchant), Revered shoulder enchants (Frost/Shadow/Arcane/Nature/Flame Mantle of the Dawn) and the healing bracer formula, and Chromatic Mantle of the Dawn at Exalted. Not yet verified for Forever.", src = "classic", topic = "economy" }
add{ q = { "timbermaw rep", "how to farm timbermaw", "deadwood furbolgs", "timbermaw feathers", "timbermaw", "farm timbermaw", "how to get timbermaw rep", "timbermaw rep forever", "winterfall furbolgs", "how do i farm timbermaw rep" }, a = "Kill Deadwood furbolgs in Felwood (Deadwood, Felpaw villages) or Winterfall furbolgs in Winterspring; regular mobs stop at Revered, named bosses don't. Turn in Deadwood Headdress Feathers to Grazle or Nafien and Winterfall Spirit Beads to Salfa, 55 rep each. Classic route; the faction and vendor Meilosh are in Forever (his Wisdom of the Timbermaw pattern is used in Forever tailoring guides).", src = "classic", topic = "economy" }
add{ q = { "timbermaw rewards", "meilosh recipes", "defender of the timbermaw", "mantle of the timbermaw", "meilosh", "timbermaw vendor", "what does meilosh sell", "timbermaw recipes", "timbermaw items", "what can i buy from timbermaw at honored", "timbermaw quartermaster recipes" }, a = "Meilosh in Timbermaw Hold sells: Friendly - Transmute Earth to Water, Enchant 2H Agility, Warbear patterns; Honored - Heavy Timbermaw Belt, Might/Wisdom of the Timbermaw, Enchant Weapon Agility; Revered - Timbermaw Brawlers, Heavy Timbermaw Boots, Mantle of the Timbermaw. Exalted: Defender of the Timbermaw trinket quest. Classic baseline, not fully verified in Forever.", src = "classic", topic = "economy" }
add{ q = { "cenarion circle rep forever", "how to get cenarion circle rep", "silithus rep", "cenarion circle", "cenarion circle rep", "cc rep", "how to get cenarion circle", "cenarion circle reputation", "cenarion circle forever", "silithus reputation", "how do i get cenarion circle rep" }, a = "Classic method: Silithus quests, killing Twilight cultists, turning in Encrypted Twilight Texts and summoning Abyssal elementals at the wind stones. The faction is still in Forever; Forever quest changes aren't documented. Note it's separate from the new Cenarion Scouts.", src = "classic", topic = "economy" }
add{ q = { "thorium brotherhood rep", "lokhtos darkbargainer", "thorium brotherhood forever", "thorium brotherhood", "tb rep", "lokhtos", "thorium brotherhood reputation", "how to get thorium brotherhood rep", "thorium brotherhood rep forever", "lokhtos brd", "farm thorium brotherhood", "how do i get thorium brotherhood rep" }, a = "Classic method: turn in Dark Iron Ore, Incendosaur Scales, Fiery and Lava Cores, Core Leather and Blood of the Mountain; rewards are Blacksmithing, Leatherworking and Tailoring fire recipes from Lokhtos Darkbargainer in BRD. Molten Core isn't a confirmed Forever raid, so the higher-tier turn-ins and recipes may not be available yet.", src = "classic", topic = "economy" }
add{ q = { "hydraxian waterlords forever", "aqual quintessence", "molten core in forever", "hydraxian waterlords", "molten core forever", "is mc in forever", "hydraxian rep", "waterlords rep", "is molten core in forever", "hydraxian waterlords rep forever" }, a = "Hydraxian Waterlords rep comes from Molten Core, which is not among Forever's launch raids (Barrow Deeps, Hyjal Summit, Onyxia's Lair on Dec 9). MC is in the client files but unconfirmed, so Aqual Quintessence and douse runs aren't relevant yet.", src = "classic", topic = "economy" }
add{ q = { "zandalar rep forever", "zul'gurub forever", "zg enchants forever", "zandalar rep", "zg forever", "zul gurub forever", "zg enchants", "is zg in forever", "zandalar tribe forever", "zul'gurub enchants", "zandalar reputation", "is zul'gurub in forever" }, a = "Zandalar Tribe rep comes from Zul'Gurub, which isn't a confirmed Forever raid. Launch raids are Barrow Deeps (10), Hyjal Summit (20) and Onyxia's Lair (40); more raids arrive spring and summer 2027. Don't count on Zandalar enchants or idols yet.", src = "classic", topic = "economy" }
add{ q = { "capital city rep", "exalted with another race", "how to ride other race mount", "stormwind rep", "city rep", "other race mount", "orgrimmar rep", "how to ride other race mounts", "capital rep forever", "how do i get exalted with another city" }, a = "Capital city reps (Stormwind, Ironforge, Darnassus, Gnomeregan, Orgrimmar, Thunder Bluff, Darkspear, Undercity) rise through quests in their regions. You need Exalted with another race to learn its riding and buy its mounts. Honored with your home faction gives 10% off riding training and mounts.", topic = "economy" }
add{ q = { "centaur rep desolace", "gelkis or magram", "desolace centaur forever", "centaur rep", "gelkis", "magram", "desolace centaur", "which centaur faction", "centaur reputation", "desolace centaur rep", "should i pick gelkis or magram" }, a = "Desolace Gelkis and Magram centaur quests and rewards are expanded in Forever. Choosing one clan's allegiance quests lowers the other. Specific new rewards aren't documented yet.", src = "classic", topic = "economy" }
add{ q = { "how does pvp work forever", "pvp ranks forever", "honor vs rank points", "rank 14 forever", "how does pvp work", "pvp ranks", "rank 14", "pvp ranking forever", "how do pvp ranks work", "pvp system forever", "rank points", "how does pvp ranking work in forever" }, a = "Two tracks: Honor (currency) from kills, battlegrounds and PvP quests, and Rank Points from battlegrounds and PvP quests, which move you up ranks 1-14 toward High Warlord / Grand Marshal. Rank gain has a weekly cap (number not published). Holiday-week battlegrounds give bonus Honor and Rank Points. Ranks reset each season, so it's not the old Classic standing grind.", topic = "economy" }
add{ q = { "pvp rank rewards", "what do pvp ranks unlock", "rank 11 mount", "pvp trinket rank", "what do pvp ranks give", "pvp trinket", "pvp rank unlocks", "rank rewards list", "what do i get at each rank", "pvp mount rank", "what do i get from pvp ranks" }, a = "Rank 1 tabard, 2 PvP trinket, 3 cloaks, 4 necklace, 5 combat potions, 6 tabard, 7 battle standard, 8 epic bracer/belt tokens, 9 epic boots token, 10 epic gloves token, 11 mounts, 12 epic legs/shoulders tokens, 13 epic chest/helm tokens, 14 epic weapons.", topic = "economy" }
add{ q = { "pvp gear forever", "emboldened seal", "how to get epic pvp gear", "blue pvp set", "pvp gear", "epic pvp gear", "how to get pvp gear", "how to upgrade pvp gear", "pvp set forever", "how do i get epic pvp gear in forever" }, a = "Honor buys a blue PvP set. To upgrade a piece to epic, you need that blue piece plus an Emboldened Seal, and seals have rank requirements. Some specs got new sets, e.g. Shaman now have healer, melee and caster sets.", topic = "economy" }
add{ q = { "pvp seasons forever", "field of honor journey", "pvp weekly tasks", "pvp legacy points", "pvp seasons", "field of honor", "pvp weekly", "pvp season forever", "pvp journey", "how do pvp seasons work in forever" }, a = "PvP is seasonal. Each season has a Field of Honor journey of weekly tasks that grant Honor and Rank Points; completing weeks 4, 7 and 10 each gives a Legacy Point. PvP ranks 3, 7, 10, 13 and 14 and Exalted with battleground factions also give Legacy Points. For Great Honor in Legacy adds +2% Honor per rank.", topic = "economy" }
add{ q = { "check pvp rank", "where to see rank points", "pvp tab", "see rank points", "where is my pvp rank", "how to check honor", "pvp tab character pane", "how do i see my rank", "rank points where", "how do i check my pvp rank" }, a = "Open the Character pane (C) and pick the Player vs. Player tab on the right. It shows your rank, current Rank Points and the rewards you can buy at your rank.", topic = "economy" }
add{ q = { "pvp vendor missing", "where are pvp vendors", "cant find honor vendor", "pvp vendors", "honor vendor", "cant find pvp vendor", "honor vendor location", "pvp vendor bug", "pvp vendors missing forever", "wher are the pvp vendors" }, a = "At launch Blizzard listed PvP vendors as unavailable (known issue added Nov 5, still open Nov 9, no fix date), so checking other cities won't help. Keep earning Honor; it will be spendable once vendors are fixed.", topic = "economy" }
add{ q = { "darkspear islands", "new battleground forever", "darkspear islands how to play", "15v15 bg", "dsi", "new bg", "darkspear islands bg", "15v15", "how to play darkspear islands", "darkspear islands battleground", "what is darkspear islands" }, a = "Darkspear Islands is a 15v15 battleground off Dustwallow Marsh for levels 30-60. Hold four capture points (Abandoned Tower, Shipwreck Cove, Ruins, Camp) to earn points; a flag in the middle can be carried to any base you hold for bonus points. First to 2,000 wins. Water is lethal, so fight over bridges. Queue at battlemasters in capitals or the Barrens, or the portals at Merchant Coast / Northwatch.", topic = "economy" }
add{ q = { "darkspear islands tips", "how to win darkspear islands", "dsi strategy", "dsi tips", "how to win dsi", "darkspear islands strategy", "dsi strat", "darkspear islands guide", "how do i win darkspear islands", "dsi strategy forever" }, a = "Leave about two defenders per base; a single stealther can flip an empty one. Bring ranged or CC to take Abandoned Tower, which is easy to hold from the top. Knockbacks near edges can drown enemies. When ahead, kite attackers away while your bases tick. Carry the flag to your safest base; captures are worth more the more bases you hold.", topic = "economy" }
add{ q = { "battlegrounds forever", "which bgs are in forever", "is alterac valley in forever", "warsong gulch forever", "bgs forever", "battlegrounds", "which bgs", "av forever", "wsg forever", "ab forever", "is av in forever", "what battlegrounds are in forever" }, a = "Launch battlegrounds: Warsong Gulch, Arathi Basin, Alterac Valley and the new Darkspear Islands. Honor rates were rebalanced so AV isn't the only efficient choice. Battleground queues mix players across rulesets. No arenas or rated BGs have been announced.", topic = "economy" }
add{ q = { "world pvp forever", "pvp server vs normal", "faction lock pvp ruleset", "can i play both factions", "world pvp", "pvp ruleset", "pvp vs normal", "faction lock", "both factions", "can i play horde and alliance", "pvp server forever", "pvp realm forever", "can i play both factions on pvp ruleset" }, a = "PvP ruleset: open-world PvP is always on and an account can only have one faction there; a PvP guild's faction is permanent. Normal ruleset: PvP is opt-in (flag yourself) and both factions are allowed. On PvP rulesets, enemies can find and attack your camp.", topic = "economy" }
add{ q = { "darkspear marks pvp gear cost", "rank 14 weapon cost", "honor costs", "pvp gear cost", "darkspear marks", "rank 14 weapon", "how much honor for gear", "darkspear marks cost", "pvp item prices", "rank 14 weapon cost forever", "how much do pvp items cost" }, a = "Beta prices: rare PvP boots and the Premier Master Sergeant's Insignia cost 10 Darkspear Marks plus 5,000 Honor; Rank 14 one-handers, bows and guns 10 Marks plus 8,000 Honor; R14 shields/off-hands 10 Marks plus 7,000 Honor. An October build raised most Honor costs about 50%, so live prices are likely higher.", src = "classic", topic = "economy" }
add{ q = { "plainsrunning battleground", "tauren racial bg nerf", "plainsrunning stack flag", "plainsrunning", "tauren racial bg", "plainsrunning nerf", "plainsrunning stack", "tauren bg nerf", "plainsrunning flag", "tauren racial nerf", "plainsrunning forever", "what happened to tauren plainsrunning" }, a = "Tauren Plainsrunning can no longer stack, and stacks are removed when you pick up a battleground flag (Nov 5 hotfix). A stacking exploit during battleground preparation was also fixed.", topic = "economy" }
add{ q = { "why does my pet keep running away", "pet ran away", "my pet left me", "why did my hunter pet leave", "pet abandoned me", "pet keeps running off", "my cat ran away wtf", "pet disappeared after it got unhappy", "how do i stop my pet from running away", "pet is unhappy will it leave", "does my pet leave if i dont feed it", "pet ran away forever", "lost my pet it just ran off", "why do hunter pets run away" }, a = "A pet only leaves if it stays unhappy long enough to drop to the lowest Loyalty. Keep it fed and fighting with you and that won't happen. Forever guides haven't confirmed the Classic run-away rule, and in beta happiness only dropped when the pet died. If your pet seems gone, it's usually one of these: it's dismissed (use Call Pet), it's dead (use Revive Pet), or it's in the stable (visit a Stable Master). Feed it out of combat and mouse over the happiness icon to see which foods it accepts.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "where did my pet go", "my pet is gone", "call pet not working", "pet vanished", "cant find my pet", "pet disappeared after flight path", "pet missing after dying", "how do i get my pet back", "call pet says no pet", "my pet isnt showing up", "pet gone after dungeon", "pet not there when i log in", "i was flying and now my wolf is gone how do i get him back", "wher is my pet" }, a = "Check these in order:\n1. Press Call Pet. A pet dismissed by a flight, mount or loading screen comes straight back.\n2. If Call Pet says the pet is dead, cast Revive Pet out of combat.\n3. If it says you have no pet, it's in the stable. Swap it out at any friendly Stable Master.\n4. While a dead pet sits in your stable, you can't tame a new one until you revive it.", class = "HUNTER", topic = "gaps" }
add{ q = { "how do i keep my pet happy", "pet happiness low", "pet unhappy what do i do", "how to make pet happy", "pet face is red", "pet happiness icon red", "pet is content not happy", "does happiness matter", "pet doing less damage unhappy", "how often feed pet", "pet mood", "happy pet damage bonus", "my pet is always yellow how do i make him green happy", "pet hapiness" }, a = "Feed your pet out of combat with food from its diet (mouse over the happiness icon to see what it eats). Happy (green) gives 125% damage, Content (yellow) 100% and Unhappy (red) only 75%. Happiness falls slowly over time, drops by 50 when you Dismiss Pet and drops a lot when the pet dies. You can't feed in combat, so top it up before each pull. Feed Pet comes from the last quest in the level 10 taming chain.", class = "HUNTER", topic = "gaps" }
add{ q = { "pet wont eat", "my pet wont eat the food", "feed pet not working", "pet refuses food", "why cant i feed my pet", "feed pet says pet doesnt like that", "feed pet greyed out", "pet wont eat this food", "food too low level for pet", "cant feed pet in combat", "i try to feed my cat bread and it says it doesnt like it", "pet wont eat my food help" }, a = "Usual reasons Feed Pet fails:\n1. Wrong diet. Mouse over the happiness icon to see which food types it accepts.\n2. The food is far below the pet's level, so the pet won't eat it or gets little from it. Buy food closer to its level.\n3. You're in combat. Wait until you're out.\n4. The pet is dead. Revive Pet first.\n5. You don't have Feed Pet yet. It comes from the final level 10 taming quest.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "what food does a cat eat", "what does my cat eat", "cat pet food", "cat diet", "what do cats eat wow", "what to feed my cat", "lion pet food", "tiger pet what food", "feed cat hunter", "cat eat meat or fish", "what does a panther eat", "nightsaber pet food", "what do i feed my kitty its hungry", "wat does cat eat" }, a = "Cats (lions, tigers, panthers, sabers) eat Meat and Fish. Raw or cooked meat from butchers and food vendors works, and so does fish you catch. Keep a stack of food close to your pet's level.", class = "HUNTER", topic = "gaps" }
add{ q = { "what does a turtle eat", "turtle pet food", "crab pet food", "what does crab eat", "tallstrider food", "what does tallstrider eat", "turtle diet", "crab diet", "what to feed tallstrider", "strider pet food" }, a = "Turtle and Crab eat Bread, Fish, Fruit and Fungus. Tallstrider eats Bread, Cheese, Fruit and Fungus. None of these three eat meat, so carry bread or fruit from a vendor, or raw fish.", class = "HUNTER", topic = "gaps" }
add{ q = { "what does wind serpent eat", "wind serpent food", "what does carrion bird eat", "vulture pet food", "crocolisk food", "what does croc eat", "owl pet food", "bird of prey food", "what does my owl eat", "fox pet food", "what does a fox eat", "serpent diet" }, a = "Wind Serpent eats Bread, Cheese and Fish. Carrion Bird, Crocolisk and Bird of Prey (the old Owl family) eat Fish and Meat. Fox eats Fruit and Meat.", class = "HUNTER", topic = "gaps" }
add{ q = { "all pet diets", "pet food list", "hunter pet diet chart", "what every pet eats", "pet family food list", "list of pet foods", "which pet eats what", "diet for every pet family", "pet diet table forever", "pet food guide", "i want a list of what every hunter pet eats", "pet foood list" }, a = "Pet diets in Forever:\nMeat only: Wolf, Raptor, Spider, Scorpid, Hyena, Core Hound.\nMeat + Fish: Cat, Carrion Bird, Crocolisk, Bird of Prey.\nFruit + Meat: Fox.\nEverything: Bear, Boar.\nFruit + Fungus: Bat.\nBread, Fruit, Fungus: Gorilla.\nBread, Fish, Fruit, Fungus: Turtle, Crab.\nBread, Cheese, Fruit, Fungus: Tallstrider.\nBread, Cheese, Fish: Wind Serpent.", class = "HUNTER", topic = "gaps" }
add{ q = { "where to buy pet food", "where do i get pet food", "pet food vendor", "where to buy meat for pet", "hunter food vendor", "cheap pet food", "where buy fish for pet", "best way to get pet food", "pet food while leveling", "buy food for my cat" }, a = "Innkeepers and food vendors in every town sell bread, and city butchers sell meat. Fruit and mushroom vendors are found in the capitals (Darnassus and Thunder Bluff have fruit, the Undercity has mushrooms). The cheapest source is free: the meat you loot from beasts and the fish you catch. A Bear or Boar eats anything, so it's the easiest to feed.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "how do i get my class mount", "class mount", "free class mount", "do i get a free mount", "which classes get a free mount", "class mount warlock paladin", "free mount at 40", "class specific mount", "what classes have class mounts", "does my class get a mount", "which classes dont have to buy a mount", "class mount quest", "im level 40 do i get a free mount for my class or do i have to buy one", "clas mount" }, a = "Only Paladins and Warlocks get free class mounts at 40. Paladins do a class quest (Alliance: The Tome of Nobility) and Warlocks do Summon Felsteed from Strahad Farsan in Ratchet. Both get a free epic version at 60 through a long questline. Every other class buys Apprentice Riding at 40 for 100g from their race's riding trainer, and that includes a first mount. Druids, Shamans and Hunters also have speed forms: Travel Form, Ghost Wolf and Aspect of the Cheetah.", topic = "gaps" }
add{ q = { "how do i get my warlock mount", "warlock mount", "felsteed quest", "how to get felsteed", "warlock free mount 40", "where is strahad farsan", "warlock level 40 mount", "lock mount quest", "summon felsteed", "do warlocks need to buy riding", "warlock mount where", "felsteed not working no riding skill", "just hit 40 on my lock where do i get the felsteed", "warlok mount" }, a = "At 40, your warlock trainer gives the Summon Felsteed quest. It's short and free, and it ends with Strahad Farsan in Ratchet (The Barrens). It teaches Summon Felsteed (+60% speed). At launch a bug left out Apprentice Riding, but it was fixed Nov 9; if you finished the quest before that, summon the Felsteed once to receive it. The epic Dreadsteed at 60 starts with Mor'zul Bloodbringer in Burning Steppes.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i get my paladin mount", "paladin mount", "paladin free mount", "tome of nobility", "pally mount quest", "paladin level 40 horse", "summon warhorse quest", "where do i get paladin mount", "undead paladin mount", "horde paladin mount quest", "paladin mount stormwind", "pally horse", "just hit 40 on my pally where is the free horse quest", "paldin mount quest" }, a = "Alliance paladins get Summon Warhorse at 40 from The Tome of Nobility. Pick it up from Duthorian Rall in the Cathedral of Light in Stormwind, or follow the breadcrumb from the Mystic Ward in Ironforge. It's a one-step quest with no fee. Undead (Forsaken) paladins have their own Warhorse quest through Bandarion Keep. The epic Charger at 60 comes from a long, costly chain that starts with Lord Grayson Shadowbreaker in Stormwind.", class = "PALADIN", topic = "gaps" }
add{ q = { "do druids get a mount", "druid travel form", "shaman ghost wolf", "hunter cheetah", "do shamans get a free mount", "do druids need to buy a mount", "when do druids get travel form", "when do shamans get ghost wolf", "druid mount", "shaman mount", "speed forms classes", "what level ghost wolf" }, a = "Druids, Shamans and Hunters have no class mount, but they have run-speed abilities: Shaman Ghost Wolf at 20, Druid Travel Form at 30 (from the trainer) and Hunter Aspect of the Cheetah (you're dazed when hit). You still need to buy Apprentice Riding at 40 for a real mount.", src = "classic", topic = "gaps" }
add{ q = { "when can i use plate", "when do warriors get plate", "when can paladins wear plate", "plate at what level", "how do i learn plate", "plate armor level 40", "can i wear plate now", "cant wear plate", "learn plate armor", "pally plate when", "warrior plate trainer", "why cant i equip plate", "im a warrior level 38 when can i finally wear plate", "when can i wear plait" }, a = "Warriors and Paladins learn Plate at level 40 from their class trainer. It isn't automatic, so you need to visit the trainer when you hit 40. Until then both wear mail, which they can use from level 1. No other class can ever wear plate.", topic = "gaps" }
add{ q = { "when can i use mail", "when can hunters wear mail", "when can shamans wear mail", "mail armor level 40", "how do i learn mail", "shaman mail when", "hunter mail at 40", "cant equip mail hunter", "learn mail armor", "when do shamans switch to mail", "my shaman is 40 why cant i wear this mail chest", "when can i ware mail" }, a = "Hunters and Shamans learn Mail at level 40 from their class trainer. Before 40 they wear leather (and cloth). Remember to train it at 40, because it isn't automatic. Warriors and Paladins can wear mail from level 1.", topic = "gaps" }
add{ q = { "when do i get new armor types", "armor types by class", "what armor can i wear", "armor proficiency by level", "what armor does my class use", "cloth leather mail plate classes", "which classes wear leather", "can mage wear leather", "what armor should i wear", "armor class chart", "do i get better armor at 40", "armor type upgrade level" }, a = "Armor by class: Mage, Priest, Warlock wear cloth. Druid and Rogue wear leather. Hunter and Shaman wear leather, then mail at 40. Warrior and Paladin wear mail, then plate at 40. The 40 upgrades must be trained at your class trainer. You can wear lighter armor, but you lose armor and usually get stats your class can't use.", topic = "gaps" }
add{ q = { "why cant i equip this", "cant equip item", "item is red cant wear", "why is the item red in my bag", "you cant equip that", "cant use this weapon", "red text on item", "why wont this equip", "item wont go on", "cant put on this armor", "why cant i wear this helmet", "why cant i use this staff", "i got this sword from a quest and it wont let me equip it why", "why cant i equip it its red" }, a = "Red text on the tooltip tells you why. Common reasons:\n1. Level too low. Check 'Requires Level X'.\n2. Wrong armor type. Plate and mail need training at 40 (Warrior/Paladin plate, Hunter/Shaman mail).\n3. Weapon skill not learned. Buy it from a weapon master, around 10s.\n4. Your class can't ever use that weapon or armor type.\n5. Profession or reputation requirement.\n6. It's a shield or off-hand and you hold a two-hander.\n7. The item is broken (red durability). It still equips but gives no stats until repaired.", topic = "gaps" }
add{ q = { "why is my weapon skill so low", "weapon skill low", "weapon skill 1", "new weapon missing a lot", "how to level weapon skill", "raise weapon skill fast", "weapon skill not going up", "my sword skill is low", "how do i increase weapon skill", "why do i keep missing with my new axe", "weapon skill cap", "max weapon skill", "just learned axes and i miss everything is that normal", "weapon skil low" }, a = "A newly learned weapon type starts at skill 1, so you miss and glance a lot. Skill rises when you hit things with that weapon, up to 5 x your level (300 at 60). To raise it fast:\n1. Fight mobs a few levels below you. They die slowly enough to give many skill-ups and are safe.\n2. Auto-attack more and use fewer finishing spells.\n3. Switch back to your main weapon for hard pulls.\nIn Forever each missing point costs about 0.04% hit and crit, and +weapon skill gear was cut hard, so just keep it maxed.", topic = "gaps" }
add{ q = { "should i use a shield as paladin", "paladin shield or 2h", "ret pally shield", "should pally use two hander", "paladin 2h or 1h and shield", "holy paladin shield", "prot pally shield", "paladin leveling weapon type", "do ret paladins use shields", "pally sword and board or 2h", "should i use a shield", "shield or two hand pally", "im leveling ret should i use a 2 hander or a sword and board", "pally sheild or 2h" }, a = "It depends on spec. Retribution should use a slow two-hander: Holy Strike and Seal of Command scale with slow weapon speed, and that's the normal leveling setup. Protection uses a shield with a fast one-hander, because more swings means more Seal of Fury hits and threat. Holy uses a one-hander with a shield or a caster off-hand. Shield-and-1H is safer but slower if you're leveling as Ret.", class = "PALADIN", topic = "gaps" }
add{ q = { "which classes can use shields", "can shaman use shield", "can i use a shield", "who can wear shields", "can druid use shield", "can rogue use shield", "shield classes", "can hunter use a shield", "shield proficiency", "can priest use shield" }, a = "Only Warriors, Paladins and Shamans can use shields. Warriors and Paladins use them for tanking (and Paladins for healing). Shamans use them for healing, Elemental and leveling. Other classes can hold a caster off-hand (Mage, Priest, Warlock, Druid) or dual wield (Rogue, Warrior, Hunter, Shaman with the talent).", src = "classic", topic = "gaps" }
add{ q = { "what does stamina do", "stamina", "what is stamina for", "stamina health", "how much health per stamina", "is stamina good", "stamina vs other stats", "why do tanks want stamina", "does stamina increase hp", "stam", "what does stam give", "stamina wow forever", "is stamina worth it or should i get more strength on my warrior", "what does stamna do" }, a = "Stamina raises your maximum health, at the same amount per point at every level (in Classic it was 10 health per point). Everyone needs some, tanks stack it, and PvP players value it highly. It doesn't add damage or regen. Warlocks also turn health into mana with Life Tap, so Stamina works as extra mana for them.", src = "classic", topic = "gaps" }
add{ q = { "what does strength do", "strength", "what is strength for", "strength attack power", "does strength help hunters", "is strength good for rogue", "str", "what classes need strength", "strength vs agility", "strength block", "what does str give", "does strength do anything for my rogue", "what does strenght do" }, a = "Strength raises melee attack power, which means more melee damage. It's the main stat for Warriors, Paladins and melee (Enhancement) Shamans, and for Druids in Bear and Cat Form. In Classic, Strength also added block value to shields. Rogues and Hunters get much more out of Agility.", src = "classic", topic = "gaps" }
add{ q = { "what does agility do", "agility", "what is agility for", "agi", "agility crit", "agility for hunters", "is agility good for warriors", "agility armor dodge", "what classes need agility", "agility vs attack power", "i am a hunter is agility my main stat", "what does agilty do" }, a = "Agility gives crit chance, dodge and some armor. For Rogues, Hunters and Cat/Bear Druids it also adds attack power (ranged attack power for Hunters), so it's their main stat. Warriors and Paladins get crit and dodge from it but less damage than from Strength. In Forever, crit is one shared stat for melee, ranged and spells.", src = "classic", topic = "gaps" }
add{ q = { "what does intellect do", "intellect", "what is intellect for", "int", "does intellect give mana", "int spell crit", "is intellect good for paladin", "what classes need intellect", "intellect vs spirit", "int for hunters", "does my paladin need intellect or nah", "what does intelect do" }, a = "Intellect raises your maximum mana and adds spell crit chance. Every mana user wants it: Mage, Priest, Warlock, Druid, Shaman, Paladin and Hunter. In Forever some talents convert Intellect into attack power or spell power, such as the Paladin's Champion of the Light and the Hunter's Careful Aim. Warriors and Rogues get nothing useful from it.", topic = "gaps" }
add{ q = { "what does spirit do", "spirit", "what is spirit for", "spirit regen", "is spirit good", "spirit mana regen", "should i get spirit", "spirit vs intellect", "spirit for warriors", "spirit health regen", "spi", "why does gear have spirit", "my mage has lots of spirit gear is that good", "what does sprit do" }, a = "Spirit regenerates mana (and health) while you're not casting. After you cast a mana spell, Spirit regen pauses for 5 seconds (the five-second rule). It's great for casters who drink between pulls and for healers with talents that keep part of it while casting (Meditation, Arcane Meditation, Reflection, Mindfulness, Bestial Discipline at 50%, Reverence at 30%). Warriors and Rogues only get slow health regen from it.", topic = "gaps" }
add{ q = { "what is spell power", "spell power", "spell damage", "what does spell power do", "sp stat", "healing power", "bonus healing", "spell power vs intellect", "does healing count as spell damage", "spell power coefficient", "plus damage gear", "what is sp", "whats spell power and do i want it on my priest", "spellpower" }, a = "Spell power adds a fixed share of its value to each spell you cast, called the spell's coefficient, so long casts benefit more than instant ones. In Forever, one third of your bonus healing also counts as spell damage, and caster weapons now carry spell damage and healing, so casters get leveling weapon upgrades like melee classes do. Some talents turn Intellect into spell power.", topic = "gaps" }
add{ q = { "what is attack power", "attack power", "ap stat", "what does ap do", "attack power dps", "how much ap per strength", "ranged attack power", "ap vs crit", "does ap help hunter pets" }, a = "Attack power adds to your weapon damage and to abilities that scale with it (Blizzard names Rend and Swipe as examples). It comes from Strength (melee) and Agility (Rogues, Hunters, Cat Druids). Hunter pets in Forever get 10% of your attack power.", topic = "gaps" }
add{ q = { "what is haste", "haste stat", "does haste matter forever", "what does haste do", "haste cap", "haste for casters", "does haste lower gcd", "haste good or bad", "is haste worth it on gear", "how much haste do i need", "haste rating forever" }, a = "Haste speeds up melee swings, ranged attacks and spell casts. Skyborne get a small permanent haste racial, and Troll Berserking gives a big temporary burst. Blizzard hasn't said whether haste shortens the global cooldown.", topic = "gaps" }
add{ q = { "what stats do i need", "what stats should i look for", "which stats are good for my class", "stats for each class", "what stat do i want", "main stat for my class", "stat guide", "what gear stats should i get", "whats my main stat" }, a = "Quick rule by class:\nWarrior: Strength, Stamina, then crit and hit.\nRogue: Agility, then Strength, hit and crit.\nHunter: Agility, Intellect, Stamina.\nMage and Warlock: Intellect, spell power, Stamina, Spirit for leveling.\nPriest, Druid and Shaman healers: Intellect, spell power or healing, Spirit or mp5.\nRet Paladin: Strength, Stamina, spell power.\nProt Paladin: spell power, Stamina.\nEnhancement Shaman: Strength, Agility.\nFor exact priorities, ask about your class's stat priority.", src = "classic", topic = "gaps" }
add{ q = { "what is a soul shard", "soul shard", "soul shards", "what are soul shards for", "what do soul shards do", "how do soul shards work", "shards warlock", "what uses soul shards", "do i need soul shards", "how many soul shards", "lock shards", "soul shard bag", "im a new warlock what do these soul shards do", "soul shrads" }, a = "A Soul Shard is the Warlock's main reagent. You get one by killing an XP-giving enemy while channeling Drain Soul, and in Forever each tick also has a growing chance to give a shard. Shards are used to summon the Voidwalker, Succubus/Incubus and Felhunter (the Imp is free), and for Healthstones, Soulstones, Soul Fire, Shadowburn (refunded if the target dies) and Ritual of Summoning. Keep 2-3 spares, and put a Soul Shard bag in your reagent slot.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i summon my voidwalker", "summon voidwalker", "how to get voidwalker", "voidwalker not in spellbook", "voidwalker quest", "where do i get voidwalker", "void walker", "how to get vw", "summon void", "how to summon voidy", "voidwalker level 10", "cant summon voidwalker", "i got my voidwalker quest done but i cant summon him", "summon voidwalkr" }, a = "The Voidwalker is a level 10 class quest. Humans do Gakin's Summons (Goldshire), Gnomes and Dwarves do The Slaughtered Lamb (Ironforge), Orcs do Gan'rul's Summons (Razor Hill), Undead do Halgar's Summons (Brill), and Trolls do Tainted Tablet. Once you've learned it, cast Summon Voidwalker from your spellbook (P) out of combat. It costs 1 Soul Shard, so get one with Drain Soul first. If you can't summon it, you probably have no shard.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i summon my imp", "summon imp", "where is my imp", "imp spell", "how to get imp", "warlock imp", "imp level 1", "imp gone" }, a = "Summon Imp is your first demon. You start with it or get it from the starting-zone warlock quest at level 1-2. It costs no Soul Shard, so you can resummon it any time out of combat from your spellbook (P). The Imp is ranged and gives the party Blood Pact (Stamina). It falls behind the Voidwalker after level 10, but it's still handy in groups.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i summon succubus", "succubus quest", "how to get succubus", "incubus quest", "how to get incubus", "sayaad", "warlock level 20 pet", "succy", "succubus or incubus", "summon succubus" }, a = "At 20 your warlock trainer starts the Succubus or Incubus (Sayaad) quest. Succubus: Devourer of Souls, from Stormwind, Orgrimmar or the Undercity. Incubus: What Is Love? (Stormwind), Love Hurts (Orgrimmar) or Hearts of the Lovers (the Undercity). Both reward a Small Soul Pouch. They're your highest-damage demon, and Seduce locks down a humanoid. Summoning one costs 1 Soul Shard.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i summon felhunter", "felhunter quest", "how to get felhunter", "seeking strahad", "warlock level 30 pet", "felhunter where", "dog pet warlock", "summon felhunter" }, a = "The Felhunter is a level 30 class quest, Seeking Strahad, from your warlock trainer. It ends with Strahad Farsan in Ratchet (The Barrens) and rewards Summon Felhunter and a Box of Souls. The Felhunter has Spell Lock (interrupt) and Devour Magic (dispel), which makes it the PvP pick. Summoning it costs 1 Soul Shard.", class = "WARLOCK", topic = "gaps" }
add{ q = { "how do i get infernal", "inferno warlock", "summon infernal", "doomguard", "ritual of doom", "how to get doomguard", "warlock level 50 demon", "infernal stone", "warlock 60 demon", "inferno quest" }, a = "Inferno (50) and Ritual of Doom/Doomguard (60) are short-lived summons that cost reagents, and you don't need them for leveling. Inferno comes from Niby the Almighty in Felwood and Ritual of Doom from Daio the Decrepit in the Blasted Lands. In Classic they used an Infernal Stone and a Demonic Figurine. The Legacy talent Reagent Economy removes vendor reagent costs.", class = "WARLOCK", src = "classic", topic = "gaps" }
add{ q = { "where is broken tooth", "broken tooth location", "broken tooth spawn", "how to tame broken tooth", "broken tooth coords", "badlands rare cat", "1.0 speed cat", "where does broken tooth spawn", "broken tooth respawn timer", "fastest attack speed pet", "broken tooth forever", "bt pet hunter", "im a 37 hunter where do i find broken tooth in badlands", "where is brokentooth" }, a = "Broken Tooth is a level 37 rare cat in the Badlands with a 1.0 attack speed, the fastest tameable pet, and it keeps that in Forever. It has three spawn points: Angor Fortress (44.5, 36.5), the north hills south of Uldaman (53, 13) and the east clearing by a big rock (61.5, 30.5). Camp on the rocks at 50, 24 and use Eagle Eye to check all three. Classic respawn was about 6-8 hours, and Forever's isn't timed yet. You must be 37+. Trap it, then Tame Beast, and feed it right after.", class = "HUNTER", topic = "gaps" }
add{ q = { "where is humar", "humar the pridelord", "humar location", "barrens rare lion", "black lion pet barrens", "humar tame", "humar level", "where does humar spawn" }, a = "Humar the Pridelord is a level 23 rare elite cat (a black lion) that roams The Barrens. Hunters tame him for his look; he's no stronger than any other cat, since cat damage is normalized in PvE. You need to be level 23 or higher.", class = "HUNTER", topic = "gaps" }
add{ q = { "where is echeyakee", "echeyakee", "echeyakee tame", "white lion barrens", "horn of echeyakee", "how to tame echeyakee", "echeyakee quest", "how do i get echeyakee pet", "white lion pet horde", "echeyakee lair barrens", "echeyakee horn where" }, a = "Echeyakee is a white lion summoned through the Horde quest Echeyakee in The Barrens. Use the Horn of Echeyakee at its lair northeast of the Crossroads, and when it appears, tame it instead of killing it. You need the quest to make it spawn.", class = "HUNTER", topic = "gaps" }
add{ q = { "where is ghostfang", "ghostfang", "ghostfang location", "dun morogh rare cat", "white blue cat pet", "ghostfang tame", "ghostfang coords", "unique cat dun morogh" }, a = "Ghostfang is a new level 10 rare cat in eastern Dun Morogh, in the hills between Ironforge and the road to Loch Modan. It has a white coat with a blue-violet back, a look no other cat has. Spawn points: 74.5, 63.2; 79.5, 43.0; 80.8, 46.3; 81.7, 55.5. Respawn is about 30 minutes (beta reports). It has a normal 2.0 attack speed. Any hunter level 10+ of either faction can tame it. Don't confuse it with the Ghostfang Alpha wolves in Hyjal.", class = "HUNTER", topic = "gaps" }
add{ q = { "where is the rake", "the rake mulgore", "the rake pet", "mulgore rare cat", "rake tame", "fast cat low level", "the rake attack speed", "rake mulgore location", "best cat for tauren hunter", "where does the rake spawn", "1.2 speed cat where" }, a = "The Rake is a rare cat in Mulgore that hunters can tame from level 10. It has a fast 1.2 attack speed, which guides rate above Ghostfang for speed. It's a popular early pet for Tauren and any hunter who makes the trip.", class = "HUNTER", topic = "gaps" }
add{ q = { "coldrasp", "where is coldrasp", "spirit wolf pet tirisfal", "tirisfal rare wolf", "mystmane", "where is mystmane", "zephras isle rare pet", "new rare pets forever", "rare pets forever list", "best rare pets" }, a = "Rare tames worth knowing in Forever: Ghostfang (10, unique cat, east Dun Morogh), The Rake (Mulgore, 1.2 speed cat), Coldrasp (a spirit wolf in Tirisfal Glades, 1.5 speed), Mystmane (on Zephras Isle), Humar (23, The Barrens), Echeyakee (a Barrens quest summon) and Broken Tooth (37, Badlands, 1.0 speed). Exact spawn spots for Coldrasp and Mystmane aren't published in guides yet.", class = "HUNTER", topic = "gaps" }
add{ q = { "lupos", "where is lupos", "duskwood shadow wolf", "lupos tame", "shadow damage wolf pet", "lupos location", "lupos duskwood", "lupos shadow bite", "is lupos in forever", "lupos still good" }, a = "In Classic, Lupos is a rare level 23 wolf that roams eastern Duskwood. His bite deals Shadow damage, which goes through armor. Forever guides haven't confirmed whether his damage type is unchanged.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "is there arena in forever", "arena", "arenas forever", "does forever have arena", "2v2", "3v3 arena", "rated pvp forever", "rated battlegrounds", "arena season", "will there be arenas", "can i do arena", "where is arena", "do they have arenas in wow forever or only battlegrounds", "is ther arena" }, a = "No. Forever has no arenas or rated battlegrounds. PvP runs on battlegrounds (Warsong Gulch, Arathi Basin, Alterac Valley and the new Darkspear Islands), world PvP and duels. It does borrow arena-style PvP seasons: each season has a track of weekly tasks that give Honor, Rank Points and up to 3 Legacy Points.", topic = "gaps" }
add{ q = { "how do i get honor", "how to get honor", "honor farm", "fastest honor", "where to get honor", "how to earn honor forever", "honor points", "what gives honor", "best bg for honor", "honor per hour", "how do i get pvp currency", "how to farm honor", "i want honor for pvp gear whats the fastest way", "how to get honnor" }, a = "Honor comes from killing enemy players, finishing battlegrounds and doing PvP quests, plus each season's weekly tasks. Battleground honor was rebalanced, so Warsong Gulch, Arathi Basin and Darkspear Islands are worth about as much as Alterac Valley. The holiday-week battleground gives bonus Honor and Rank Points. Honor buys a blue PvP set, and the epic set needs the matching blue piece plus an Emboldened Seal from your rank.", topic = "gaps" }
add{ q = { "how do pvp ranks work", "pvp rank", "rank points", "how to rank up pvp", "high warlord forever", "grand marshal forever", "rank 14 forever", "pvp rank rewards", "weekly rank cap" }, a = "Rank Points come from battlegrounds and PvP quests and move you up ranks 1-14, toward High Warlord (Horde) or Grand Marshal (Alliance). There's a weekly cap, so it isn't the old full-time grind. Rewards by rank: 2 PvP trinket, 3 cloaks, 4 necklace, 8-10 and 12-13 epic armor tokens, 11 mounts, 14 epic weapons. Check your progress with C, then the PvP tab.", topic = "gaps" }
add{ q = { "how do i turn on pvp", "turn off pvp", "pvp flag", "how to unflag pvp", "/pvp", "how do i stop being flagged", "why am i pvp flagged", "how to turn pvp off", "flagged for pvp how long" }, a = "On Normal and RP rulesets, type /pvp (or right-click your portrait) to flag yourself. The flag drops about 5 minutes after you turn it off and stop fighting. Attacking a flagged player, healing one or entering enemy towns flags you too. On PvP rulesets you're flagged nearly everywhere outside sanctuaries and your own faction's areas.", topic = "gaps" }
add{ q = { "how do i duel", "duel someone", "how to duel a player", "can i duel in forever", "duel command", "where can i duel", "/duel", "duel my friend", "challenge someone to a duel", "how to start a duel", "why cant i duel here", "duel in city" }, a = "Right-click the player's portrait and choose Duel, or target them and type /duel. A flag drops between you, and the duel ends when one of you hits 1 health or leaves the area. You can't duel in capital cities. Blizzard also floated a dedicated Mak'gora space for duels to the death on the coming Hardcore ruleset.", src = "classic", topic = "gaps" }
add{ q = { "what race should i pick", "best race", "which race should i play", "what race is best", "best race forever", "what race for me", "race choice", "does race matter", "best racials", "should i pick race for looks or racials", "race tier list", "im new what race", "im new and dont know what race to make", "wat race should i pick" }, a = "Racials help, but pick what you'll enjoy playing for 100+ hours. Quick guide:\n- Orc and Troll: best raw damage (Blood Fury, Berserking).\n- Tauren: tanks and herbalists.\n- Undead: PvP (Will of the Forsaken).\n- Human: crit (Ruthless) and good PvP.\n- Dwarf: +1% hit (Artisan's Precision), Stoneform.\n- Gnome: Eureka!, great for healers and Engineering.\n- Night Elf: Elune's Light crit and Shadowmeld.\n- Skyborne: haste and speed, good for casters (needs the Heroic Pack).\nAsk 'best race for <class>' for a specific pick.", topic = "gaps" }
add{ q = { "what race should i pick for warrior", "best warrior race", "warrior race", "best race for warrior forever", "what race warrior alliance", "horde warrior race", "best race tank warrior", "orc or tauren warrior" }, a = "Alliance: Human (Ruthless crit) or Dwarf (+1% hit, Stoneform damage reduction). Night Elf and Gnome are fine, mostly for PvP. Horde: no clear winner. Orc has Blood Fury, Troll has Berserking, Tauren has War Stomp and +5% health for tanking, and Undead has Touch of the Grave and Will of the Forsaken. Guides rate Skyborne weak for Warriors.", class = "WARRIOR", topic = "gaps" }
add{ q = { "what race should i pick for mage", "best mage race", "mage race", "best race for mage forever", "gnome or human mage", "orc mage good", "skyborne mage", "mage race forever", "which race mage horde", "im making a mage what race", "undead mage or troll" }, a = "Alliance: High Order Skyborne is rated strongest (haste plus Read Ley Line regen), with Human and Gnome close behind. Horde: Orc, new to Mage in Forever, has the best burst from Blood Fury. Troll is close behind, and Undead is more random.", class = "MAGE", topic = "gaps" }
add{ q = { "what race should i pick for hunter", "best hunter race", "hunter race", "best race for hunter forever", "night elf or human hunter", "orc hunter", "tauren hunter good", "hunter race forever", "dwarf hunter", "human hunter good", "which race hunter pvp" }, a = "Alliance: Night Elf or Human for PvE (crit racials), and Dwarf or Human for PvP. Human Hunter is a new combo in Forever. Horde: Orc is strong in both (Command adds 5% pet damage), and Troll's Berserking suits any spec. Skyborne haste suits BM and MM.", class = "HUNTER", topic = "gaps" }
add{ q = { "what race should i pick for rogue", "best rogue race", "rogue race", "best race for rogue forever", "orc or undead rogue", "human rogue", "rogue race forever", "undead rogue pvp", "night elf rogue", "gnome rogue", "which race rogue pve" }, a = "Alliance: Human (Ruthless crit plus a stun break for PvP), Night Elf for short fights, or Gnome for PvP. Horde: Orc is the best overall (Blood Fury burst, shorter stuns), with Troll a strong alternative and Undead great in PvP thanks to Will of the Forsaken.", class = "ROGUE", topic = "gaps" }
add{ q = { "what race should i pick for priest", "best priest race", "priest race", "best race for priest forever", "gnome priest", "undead priest", "dwarf priest", "priest race forever", "night elf priest", "human priest", "which race healer priest" }, a = "Alliance: Night Elf (Starshards, Elune's Light) looks strongest, with Gnome close behind. Gnome Priest is new in Forever, and Eureka! boosts Power Word: Shield. Human and Dwarf add crit or hit. Horde: Undead (Touch of the Grave) looks strongest, and Troll is weaker now.", class = "PRIEST", topic = "gaps" }
add{ q = { "what race should i pick for warlock", "best warlock race", "warlock race", "best race for warlock forever", "orc or undead warlock", "troll warlock", "gnome warlock", "warlock race forever", "human warlock", "undead lock", "which race lock pvp" }, a = "Guides say the warlock races are close. Human and Orc are strong in PvE and PvP, and Orc's Command adds 5% pet damage. Undead (Will of the Forsaken) is best for PvP. Troll is new to Warlock, and Berserking suits Demonology and Destruction. Gnome's Eureka! doesn't boost DoTs, so it's weaker for Affliction.", class = "WARLOCK", topic = "gaps" }
add{ q = { "what race should i pick for paladin", "best paladin race", "paladin race", "best race for paladin forever", "human or dwarf paladin", "can horde be paladin", "undead paladin race", "paladin race forever", "pally race", "dwarf paladin", "best race ret pally" }, a = "Alliance: Human is the usual pick for Ruthless crit, and Dwarf is solid with +1% hit and Stoneform. Horde: Undead is the only Paladin race (new in Forever). Touch of the Grave helps tank threat, and Cannibalize restores mana.", class = "PALADIN", topic = "gaps" }
add{ q = { "what race should i pick for druid", "best druid race", "druid race", "best race for druid forever", "night elf or skyborne druid", "tauren druid", "druid race forever", "night elf druid", "windshaper druid", "which race bear druid", "tauren or skyborne druid" }, a = "Alliance: High Order Skyborne (Read Ley Line regen, haste) or Night Elf (Elune's Light crit, Quickness dodge for bears). Horde: Tauren (War Stomp now works in forms, +5% health for bears) or Windshaper Skyborne (Skysight speed, haste). Racials like Shadowmeld and War Stomp now work while shapeshifted.", class = "DRUID", topic = "gaps" }
add{ q = { "what race should i pick for shaman", "best shaman race", "shaman race", "best race for shaman forever", "can alliance be shaman", "dwarf shaman", "troll or orc shaman", "shaman race forever", "orc shaman", "troll shaman", "skyborne shaman", "which race resto shaman" }, a = "Alliance: Dwarf is the only Shaman race, new in Forever (+1% hit from Artisan's Precision). Horde: Windshaper Skyborne is likely strongest (permanent haste, Skysight speed). Troll's Berserking is good for every spec, Orc is good for PvP and burst, and Tauren offers Shamans little.", class = "SHAMAN", topic = "gaps" }
add{ q = { "whats the difference between forever and classic era", "forever vs classic era", "forever vs classic", "is forever just classic", "what changed from classic", "how is forever different", "classic era or forever", "forever vs vanilla", "is forever classic plus", "should i play forever or era", "differences forever classic", "is this the same as classic wow", "i played classic era is forever any different or the same thing", "forever vs clasic" }, a = "Classic Era is the original 2004-06 game left unchanged. Forever is a separate Classic+ game on the same old world with: 1,000+ new quests, new zones (Zephras Isle, Riverglades, Shen'dralas, Mount Hyjal, Dalaran), 9 new dungeons, new raids (Barrow Deeps, Hyjal Summit), the Skyborne race and new race/class combos, reworked talents, the account-wide Legacy system, Camping, transmog and a modern UI (damage meter, Edit Mode). Combat is slower, hit and crit are each one stat, the cap stays 60 forever and there are no expansions. Characters don't transfer between them.", topic = "gaps" }
add{ q = { "can i play classic era characters in forever", "does my classic char carry over", "transfer era to forever", "do i keep my classic characters", "will my sod character move to forever", "can i bring my classic character", "transfer from classic era", "move my era char to forever", "do i have to start over in forever", "is my hardcore char in forever" }, a = "No. Forever is its own game, and you start fresh. Classic Era, Season of Discovery and Hardcore characters stay where they are and can't be moved to Forever. Forever's own progress, including Legacy, is shared across your Forever characters.", src = "classic", topic = "gaps" }
add{ q = { "when does onyxia reset", "ony reset", "onyxia lockout", "is onyxia 5 day reset", "onyxia weekly", "how often can i kill onyxia", "ony reset day", "onyxia lockout forever", "when can i do ony again", "does ony reset every 5 days", "we killed ony on thursday when can we do her again", "when does ony reset forever" }, a = "In Forever, Onyxia's Lair is planned to reset weekly with the other launch raids. It's no longer the Classic 5-day timer. It opens December 9. Blizzard hasn't published the exact reset hour, so check Raid Info for your lockout timer once you've saved to it.", topic = "gaps" }
add{ q = { "raid reset days", "when do raids reset", "raid reset time", "weekly reset time", "what day is reset", "what time is weekly reset", "reset tuesday", "eu reset day", "na reset time", "raid lockout reset", "when is reset forever", "lockout timer", "what day do raids reset in forever", "when is weekly reset in na" }, a = "Blizzard says all of Forever's launch raids (Barrow Deeps, Hyjal Summit, Onyxia's Lair) reset weekly, but hasn't published the exact hour. WoW's normal weekly reset is Tuesday morning in the Americas (about 15:00 UTC) and Wednesday morning in Europe, so expect that. To see your exact timer, open the Social/Raid panel (O), go to the Raid tab and click Raid Info. Whether you can run more than one group a week isn't confirmed.", src = "classic", topic = "gaps" }
add{ q = { "how do i see my raid lockout", "raid info", "where is raid info", "check lockout", "am i saved", "how to see saved instances", "raid id", "am i locked to ony" }, a = "Press O to open Social, go to the Raid tab and click Raid Info. It lists every raid and dungeon you're saved to and how long until each lockout ends. You can also type /raidinfo. Note that 5-man dungeons have no lockout in Forever; you can reset them up to 5 times an hour.", src = "classic", topic = "gaps" }
add{ q = { "how do i reset a dungeon", "reset instance", "dungeon reset", "reset dungeon limit", "too many instances", "5 instances per hour", "how to reset deadmines", "instance reset forever" }, a = "Everyone must leave the dungeon. Then the party leader right-clicks their own portrait and picks Reset all instances. You can enter at most 5 instances per hour, and the next one opens once the oldest of them is an hour old. Forever keeps this limit.", topic = "gaps" }
add{ q = { "what does the d key do", "d key", "what does a and d do", "a and d turn instead of strafe", "how to strafe", "q and e keys", "change turn to strafe", "wasd strafe", "my character turns instead of strafing", "movement keys", "strafe keys", "how to make a d strafe", "my d key turns my character instead of strafing how do i fix it", "d key turns me" }, a = "It depends on the preset you picked at first login. With Classic, A and D turn your character and Q and E strafe. With Enhanced, A and D strafe. To change it, go to Esc > Options > Keybindings > Movement and bind Strafe Left/Right to A and D (or set them back to Turn). Holding right mouse button while pressing A/D also strafes.", topic = "gaps" }
add{ q = { "default keybinds", "keybinds list", "what are the default keys", "hotkeys", "keyboard shortcuts", "what key opens talents", "what key opens spellbook", "what key for map", "key for professions", "key for legacy", "what key opens bags", "list of hotkeys", "what are all the default hotkeys in forever", "defualt keybinds" }, a = "Forever defaults: C character, B backpack (Shift+B all bags), P spellbook, N talents, Y Legacy talents, K professions, L quest log, M map, U reputation, O friends/raid, J guild and communities, I Looking For Group, H honor/PvP, Shift+P collections, V / Shift+V enemy/friendly nameplates, Esc menu. Movement and combat use the usual WoW keys: W/S move, Space jump, Tab target nearest enemy, Num Lock autorun, Enter chat, R reply to a whisper.", topic = "gaps" }
add{ q = { "how do i make my ui bigger", "ui scale", "make ui bigger", "ui too small", "how to change ui size", "make everything bigger", "scale ui", "ui too big", "interface size", "increase ui size", "make the hud bigger", "text too small", "everything is tiny on my 4k monitor how do i make the ui bigger", "ui scale wont go bigger" }, a = "1. Press Esc > Options and type 'UI Scale' in the search box at the top right.\n2. Move the slider until it fits. Larger values make everything bigger.\n3. To resize single frames (action bars, unit frames, raid frames), press Esc > Edit Mode, click the frame and change its size.\nFor chat text, right-click the chat tab and pick Font Size.", src = "classic", topic = "gaps" }
add{ q = { "how do i make chat bigger", "chat font size", "chat text too small", "bigger chat", "resize chat window", "make chat box bigger", "chat font too small", "increase chat text size", "chat window too small", "how to change chat size", "make chat text larger" }, a = "Right-click the chat tab (General) and choose Font Size to change text size. Drag the chat window's corner to resize it, or move it in Edit Mode (Esc > Edit Mode). To add a tab, right-click a tab and choose Create New Window.", src = "classic", topic = "gaps" }
add{ q = { "how do i turn on rxp", "rxp guides", "restedxp forever", "how to install rested xp", "restedxp not working", "rxp addon", "rested xp addon forever", "how to use restedxp", "rxp guide setup", "how to get rxp guides", "rxp free", "rested xp guide forever", "i installed restedxp but it doesnt show up in game", "how to turn on rested xp guide" }, a = "1. On CurseForge, open RestedXP Guide > Files and download the latest Forever build (or the RXPGuides zip from GitHub). Delete any old copy first.\n2. Unzip and copy the whole RXPGuides folder into _forever_/Interface/AddOns. RXPGuides.toc must sit directly inside it.\n3. Fully restart the game, then tick RestedXP Guides in the AddOns list at character select.\n4. Type /rxp in game.\nLevels 1-20 are free. Paid guides need your Battle.net ID on restedxp.com, then right-click the addon > Import guide and paste the string.", topic = "gaps" }
add{ q = { "how do i turn on questie", "questie setup", "how to install questie", "questie not showing", "questie forever", "questie settings", "questie not working", "how to use questie", "questie icons on map", "questie low level quests", "turn off questie", "questie options", "questie isnt showing quests on my map how do i turn it on", "questy not working" }, a = "1. Download the Forever version of Questie (CurseForge Files tab, or Wago). The Classic Era file won't load.\n2. Copy the Questie folder into _forever_/Interface/AddOns and fully restart the game.\n3. Tick Questie in the AddOns list at character select.\n4. Click the Questie minimap icon, or type /questie, to open its options. There you can toggle map icons, show low-level quests and change the tracker.\nForever's own map already shows quest areas if you use the Enhanced preset. Questie's database may miss some new Forever quests.", topic = "gaps" }
add{ q = { "common addon setup", "what addons should i get", "best addons", "starter addons", "must have addons forever", "addons for new players", "what addons do people use", "addon pack forever", "recommended addons", "addons list" }, a = "Popular working Forever addons: Questie (quest helper), RestedXP (leveling guide), Baganator/Bagnon/BetterBags (bags), Bartender4 (bars), Leatrix Plus (comfort tweaks), Deadly Boss Mods, Auctionator, VuhDo or Grid2 (raid frames) and BugSack (errors). Forever already has a damage meter, swing timer, cooldown manager, Edit Mode and an equipment manager, so you need fewer addons. Always download the Forever build.", topic = "gaps" }
add{ q = { "how do i install addons", "how to install addons forever", "where do addons go", "addon folder forever", "curseforge forever", "how to get addons", "install addon mac", "wago forever", "addons not loading", "how to add addons", "i downloaded an addon but it doesnt show in game where do i put it", "how to instal addons" }, a = "1. Find your folder: World of Warcraft\\_forever_\\Interface\\AddOns (in Battle.net, pick Forever, click the gear by Play > Show in Explorer). Make Interface and AddOns if they're missing.\n2. Download the addon's Forever version and unzip it.\n3. Copy the addon folder (not the zip) in, so the .toc file sits directly inside it.\n4. Fully restart the game and tick it in the AddOns list.\nOr use the CurseForge or Wago app with Forever selected as the game.", topic = "gaps" }
add{ q = { "should i do sm or rfk at 32", "sm or rfk", "rfk or sm", "level 32 dungeon", "what dungeon at 32", "dungeon for level 30", "what dungeon should i do at 30", "sm graveyard or rfk", "is rfk worth it", "what dungeon at 33", "im 32 what dungeon", "best dungeon around 30", "im 32 should i run scarlet monastery or razorfen kraul", "sm or rfk lvl 32" }, a = "At 32 either works. SM Graveyard is the quicker run (about 30-38), and SM Library opens up around 33. Razorfen Kraul (29-38) is better if you have its Barrens quests in your log, and Horde get more of them. Other choices at this level: Gnomeregan (29-38, big Alliance quest XP), City of Dalaran (28-35) and Excavation Site: Wetlands (26-33). Always bring the dungeon's quests, because in Forever quest XP is where most dungeon XP comes from.", topic = "gaps" }
add{ q = { "what dungeon should i do", "dungeon by level", "what dungeon for my level", "which dungeon at my level", "dungeon level ranges", "what dungeons can i do", "dungeon levels list", "which dungeon next", "dungeon levels forever", "im lvl what dungeon", "im lvl 27 what dungeon should i run", "what dungon for my level" }, a = "Rough brackets: RFC/Hall of Thanes 13-18, Ruins of Lordaeron 15-22, Wailing Caverns 15-24, Deadmines 17-26, SFK 20-30, BFD/Stockade 24-32, Excavation Site 26-33, City of Dalaran 28-35, RFK/Gnomeregan 29-38, SM 30-46, Drowned City 35-42, RFD 37-46, Krol'dok 40-47, Uldaman 41-51, ZF 44-54, Maraudon 46-55, Alcaz Prison 48-55, Sunken Temple 50-60, BRD 52-60, then the 55-60 endgame (Blackmaw Hold, Shaper's Terrace, Strat, Scholo, DM, LBRS/UBRS).", topic = "gaps" }
add{ q = { "what dungeon at 15", "first dungeon", "level 15 dungeon", "dungeon at 16", "best dungeon at 18", "rfc or wc", "what dungeon alliance 15", "hall of thanes or deadmines" }, a = "Your first dungeons: Ragefire Chasm (Horde, Orgrimmar) or Hall of Thanes (Alliance, under Ironforge) at 13-18, Ruins of Lordaeron (Horde, above the Undercity) at 15-22, Wailing Caverns (Barrens) at 15-24, and Deadmines (Westfall) at 17-26. Grab every quest for the dungeon first.", topic = "gaps" }
add{ q = { "what dungeon at 20", "level 20 dungeon", "dungeon at 22", "sfk or deadmines", "dungeon for 24", "what dungeon at 25", "bfd or stockade", "im 20 what dungeon" }, a = "Around 20-25: Deadmines (17-26) and Shadowfang Keep (20-30) are the big ones, then Blackfathom Deeps and the Stockade (24-32). From the mid-20s there's also Excavation Site: Wetlands (26-33). Horde usually pick SFK, and Alliance usually Deadmines then Stockade.", topic = "gaps" }
add{ q = { "what dungeon at 40", "level 40 dungeon", "dungeon at 38", "dungeon at 42", "rfd or sm cath", "uldaman or zf", "what dungeon at 45", "drowned city or krol'dok", "im 40 what dungeon" }, a = "Around 35-45: SM Armory and Cathedral (up to 46), The Drowned City (35-42, off STV), Razorfen Downs (37-46), Krol'dok Stronghold (40-47, Riverglades) and Uldaman (41-51). At 44+, Zul'Farrak opens up.", topic = "gaps" }
add{ q = { "what dungeon at 50", "level 50 dungeon", "dungeon at 48", "mara or zf", "sunken temple level", "dungeon at 52", "what dungeon at 55", "im 50 what dungeon" }, a = "Around 45-55: Zul'Farrak (44-54), Maraudon (46-55), Alcaz Prison (48-55, Dustwallow), Sunken Temple (50-60, with the level 50 class quests) and Blackrock Depths (52-60). BRD is huge, so run it in wings with your quests.", topic = "gaps" }
add{ q = { "what dungeon at 58", "level 60 dungeons", "endgame dungeons", "dungeons at 60", "best dungeons for gear at 60", "what to run at 60", "pre bis dungeons", "dungeon at 60", "best dungeons at 59", "im 58 what dungeon", "where to farm gear at 60" }, a = "At 55-60: Blackmaw Hold (55-60, Azshara), Shaper's Terrace (58-60, Un'Goro), Stratholme, Scholomance, Dire Maul (East, West, North), and Lower and Upper Blackrock Spire. These drop the pre-raid gear, Tier 0 and dungeon set pieces, and recipes.", topic = "gaps" }
add{ q = { "where is deadmines", "deadmines entrance", "how to get to deadmines", "deadmines location", "vc dungeon where", "dm westfall where", "where is the deadmines entrance", "moonbrook dungeon", "where is the deadmines in westfall i cant find it", "where is deadmine" }, a = "The Deadmines is in Moonbrook, southern Westfall. Enter the mine building in Moonbrook, follow the long tunnel down and the portal is at the end. Nearest flight point is Sentinel Hill. Horde have a long trip, usually through Duskwood or Stranglethorn.", src = "classic", topic = "gaps" }
add{ q = { "where is wailing caverns", "wc entrance", "how to get to wailing caverns", "wailing caverns location", "wc barrens where", "where is wc", "wc location barrens", "how do i find wc", "wailing caverns cave entrance", "where is the wc portal" }, a = "Wailing Caverns is in The Barrens, west of the Crossroads (around 46, 36). The cave mouth is in a rock face shaped like a skull, above the Lushwater Oasis. Inside, follow the tunnel down past the Druids of the Fang to the portal.", src = "classic", topic = "gaps" }
add{ q = { "where is shadowfang keep", "sfk entrance", "how to get to sfk", "sfk location", "where is sfk", "shadowfang keep where", "sfk silverpine where", "how to find shadowfang", "shadowfang keep location alliance", "sfk castle where" }, a = "Shadowfang Keep is the castle in southern Silverpine Forest (around 45, 68), on the hill above Pyrewood Village. Horde fly to The Sepulcher and ride south. Alliance reach it through Hillsbrad or the Alterac roads.", src = "classic", topic = "gaps" }
add{ q = { "where is bfd", "blackfathom deeps entrance", "how to get to bfd", "bfd location", "blackfathom where", "where is blackfathom deeps", "bfd ashenvale where", "blackfathom deeps location", "how to find bfd", "bfd entrance under water" }, a = "Blackfathom Deeps is on the Zoram Strand coast in northwest Ashenvale (around 14, 14). Swim and walk through the sunken temple ruins. The portal is inside the main temple, part way down. Alliance fly to Astranaar, and Horde to Zoram'gar Outpost.", src = "classic", topic = "gaps" }
add{ q = { "where is the stockade", "stockades entrance", "how to get to stocks", "stockade location", "where is stocks", "prison stormwind dungeon", "stockade stormwind where", "where is stockades entrance", "stocks entrance sw", "how to find the stockade" }, a = "The Stockade is inside Stormwind City, by the canals near the Mage Quarter. Look for the guarded prison gate. It's Alliance-only in practice.", src = "classic", topic = "gaps" }
add{ q = { "where is gnomeregan", "gnomer entrance", "how to get to gnomer", "gnomeregan location", "where is gnomer", "gnomer dun morogh", "gnomer front door", "where is gnomer entrance", "how to find gnomeregan" }, a = "Gnomeregan is in western Dun Morogh (around 24, 40), west of Kharanos. Follow the road to the big gnomish entrance and take the lift down. The back door (Workshop Key) is off Ironforge's Tinker Town. In Forever, Horde reach it through the Gear Wars questline.", src = "classic", topic = "gaps" }
add{ q = { "where is rfc", "ragefire chasm entrance", "how to get to rfc", "rfc location", "ragefire where", "where is ragefire", "rfc orgrimmar where", "ragefire chasm location", "how to find rfc", "rfc in cleft of shadow" }, a = "Ragefire Chasm is inside Orgrimmar, in the Cleft of Shadow. Walk down to the lava cave near the warlock and rogue trainers, and the portal is inside. It's Horde-only. The Alliance version is Hall of Thanes under Ironforge.", src = "classic", topic = "gaps" }
add{ q = { "where is rfk", "razorfen kraul entrance", "how to get to rfk", "rfk location", "where is razorfen kraul", "razorfen kraul where", "how to find rfk", "rfk barrens where", "rfk south barrens" }, a = "Razorfen Kraul is at the far south of The Barrens (around 42, 90), on the border with Thousand Needles, inside a huge thorny bramble hill. Horde fly to Camp Taurajo and ride south. Alliance usually fly to Thalanaar or Theramore and ride over.", src = "classic", topic = "gaps" }
add{ q = { "where is rfd", "razorfen downs entrance", "how to get to rfd", "rfd location", "where is razorfen downs", "razorfen downs where", "how to find rfd", "rfd barrens", "rfd thousand needles" }, a = "Razorfen Downs is a short ride east of Razorfen Kraul, on The Barrens/Thousand Needles border at the very south of The Barrens. Look for the bramble mound covered in tusks.", src = "classic", topic = "gaps" }
add{ q = { "where is sm", "scarlet monastery entrance", "how to get to sm", "sm location", "where is scarlet monastery", "sm wings", "sm graveyard entrance", "sm tirisfal where", "how to find sm", "scarlet monastery location", "where is sm cath", "where is scarlet monastary", "im in tirisfal where is sm" }, a = "Scarlet Monastery is in northeast Tirisfal Glades (around 84, 30), past the Scarlet camps. The courtyard has four doors: Graveyard (30-38), Library (33-41), Armory (36-44) and Cathedral (38-46). Armory and Cathedral need the Scarlet Key from the Library. Horde fly to the Undercity, and Alliance usually travel through Southshore and the Hillsbrad/Silverpine roads.", src = "classic", topic = "gaps" }
add{ q = { "where is uldaman", "uldaman entrance", "how to get to uldaman", "uldaman location", "uldaman back door", "where is ulda", "uldaman badlands where", "ulda location", "how to find uldaman", "uldaman front entrance" }, a = "Uldaman is in the northern Badlands. The front entrance is near the Hammertoe digsite on the north side, and the back entrance is on the east side of the zone (around 65, 43). Fly to Thelsamar (Alliance) or Kargath (Horde).", src = "classic", topic = "gaps" }
add{ q = { "where is zf", "zul'farrak entrance", "how to get to zf", "zf location", "where is zul farrak", "zulfarrak where", "zf tanaris where", "how to find zf", "zul farrak entrance" }, a = "Zul'Farrak is in northwest Tanaris (around 39, 20), a big troll city in the desert. Fly to Gadgetzan and ride northwest.", src = "classic", topic = "gaps" }
add{ q = { "where is maraudon", "mara entrance", "how to get to maraudon", "maraudon location", "where is mara", "mara location", "maraudon desolace where", "how to find mara", "mara purple entrance", "mara orange entrance" }, a = "Maraudon is in southwest Desolace, in the Valley of Spears (around 29, 62). Enter the big cave and choose the Purple or Orange side. The Scepter of Celebras opens a shortcut to Earth Song Falls. Fly to Nijel's Point (Alliance) or Shadowprey Village (Horde).", src = "classic", topic = "gaps" }
add{ q = { "where is sunken temple", "st entrance", "how to get to sunken temple", "temple of atal'hakkar", "where is st dungeon", "sunken temple location", "sunken temple swamp of sorrows", "how to find sunken temple", "st location", "atal'hakkar entrance" }, a = "The Sunken Temple is in the Pool of Tears in Swamp of Sorrows (around 69, 53). Swim to the sunken temple ruins and go down the spiral stairs to the portal. Fly to Stonard (Horde) or Nethergarde Keep in the Blasted Lands (Alliance).", src = "classic", topic = "gaps" }
add{ q = { "where is brd", "blackrock depths entrance", "how to get to brd", "where is blackrock mountain", "lbrs entrance", "ubrs entrance", "brd location", "where is mc entrance", "how do i get into blackrock mountain", "where is blackrock depths entrance" }, a = "All Blackrock instances are inside Blackrock Mountain, between Searing Gorge and Burning Steppes. Enter the mountain, cross the chains over the lava, and you'll find Blackrock Depths at the bottom and Blackrock Spire (Lower and Upper) at the top. Fly to Thorium Point (Searing Gorge) or Flame Crest/Morgan's Vigil (Burning Steppes).", src = "classic", topic = "gaps" }
add{ q = { "where is dire maul", "dm entrance", "how to get to dire maul", "dire maul location", "where is dm feralas", "dm feralas where", "how to find dire maul", "dm east entrance", "dire maul north entrance" }, a = "Dire Maul is in central Feralas (around 59, 44), a huge ruined elven city. The courtyard has entrances to East, West and North. West and North need the Crescent Key from DM East. Fly to Feathermoon (Alliance) or Camp Mojache (Horde).", src = "classic", topic = "gaps" }
add{ q = { "where is stratholme", "strat entrance", "how to get to strat", "stratholme location", "where is strath", "strat entrance epl", "how to find strat", "strat service entrance", "strat ud side entrance" }, a = "Stratholme is in the far north of Eastern Plaguelands. The main gate leads to the Living (Scarlet) side, and the Eastwall service gate to the Undead side. Fly to Light's Hope Chapel and ride north-west.", src = "classic", topic = "gaps" }
add{ q = { "where is scholomance", "scholo entrance", "how to get to scholo", "scholomance location", "where is caer darrow", "scholo location", "scholomance wpl where", "how to find scholo", "scholo entrance island", "caer darrow where" }, a = "Scholomance is on Caer Darrow island in the lake of southern Western Plaguelands (around 69, 73). Swim or walk across to the castle. The front gate needs the Skeleton Key. Alliance stage at Chillwind Camp and Horde at The Bulwark.", src = "classic", topic = "gaps" }
add{ q = { "how do i get to kalimdor", "get to kalimdor", "eastern kingdoms to kalimdor", "how to get to darkshore from stormwind", "boat to kalimdor", "alliance to kalimdor", "horde to kalimdor", "how to get to orgrimmar from undercity", "how do i get to the barrens from stormwind", "cross the ocean", "how to get to other continent", "how to go to kalimdor alliance", "im in stormwind how do i get to kalimdor", "how to get to kalimdoor" }, a = "Alliance: take the new boat from Stormwind Harbor to Auberdine (Darkshore), or the Menethil Harbor (Wetlands) boat to Theramore (Dustwallow Marsh). Horde: take the zeppelin from the tower north of the Undercity, or from Grom'gol in Stranglethorn, to Orgrimmar. Neutral: the Booty Bay to Ratchet goblin boat, or the new Powderfuse Port (Riverglades) to Steamwheedle Port (Tanaris) ferry.", topic = "gaps" }
add{ q = { "how do i get to eastern kingdoms", "get to eastern kingdoms", "kalimdor to eastern kingdoms", "how to get to stormwind from darnassus", "horde to undercity", "zeppelin to undercity", "boat to stormwind", "how to get to stranglethorn from orgrimmar", "darnassus to stormwind", "night elf how to get to stormwind", "how to go to ek", "orgrimmar to grom'gol", "im in orgrimmar how do i get to the eastern kingdoms", "how to get to eastern kingdom" }, a = "Alliance: from Darnassus take the pink portal to Rut'theran, then the boat to Auberdine, then the Stormwind Harbor boat. Or go Theramore to Menethil and run or fly to Ironforge. Horde: zeppelin towers outside Orgrimmar's front gate go to the Undercity and to Grom'gol (Stranglethorn). Neutral: Ratchet to Booty Bay, or Steamwheedle Port (Tanaris) to Powderfuse Port (Riverglades).", topic = "gaps" }
add{ q = { "where is the zeppelin", "zeppelin tower orgrimmar", "where do zeppelins leave", "zeppelin location", "zep to undercity where", "undercity zeppelin", "zeppelin to thunder bluff", "grom'gol zeppelin", "how do i take the zeppelin", "zep tower" }, a = "Orgrimmar's zeppelin towers are just outside the main gate in Durotar: one goes to the Undercity (it lands at the tower north of the Undercity in Tirisfal) and one to Grom'gol in Stranglethorn. The Undercity tower also has a zeppelin to Grom'gol. There's no zeppelin to Thunder Bluff, so fly from Orgrimmar or ride through the Barrens. Ask the zeppelin master on the platform which side goes where.", topic = "gaps" }
add{ q = { "how do i get to thunder bluff", "get to thunder bluff from orgrimmar", "orgrimmar to thunder bluff", "how to get to mulgore", "tauren city how to get there", "walk to thunder bluff", "tb from org", "how to get to tb", "thunder bluff flight path", "how do i reach thunder bluff", "no zeppelin to thunder bluff", "im in orgrimmar how do i get to thunder bluff", "how to get to thunder bluf" }, a = "There's no zeppelin to Thunder Bluff. From Orgrimmar, fly from the flight master on the tower (once you've learned the Thunder Bluff flight path), or ride from the Crossroads through southern Barrens and west into Mulgore. Horde Skyborne can also take the skyboat to Skywatcher Plateau in Mulgore.", topic = "gaps" }
add{ q = { "how do i get to darnassus", "get to darnassus", "darnassus from stormwind", "how to get to teldrassil", "rut'theran portal", "boat to darnassus", "how to get to darn", "stormwind to darnassus", "darnassus boat", "how do i get to rutheran", "portal to darnassus", "im in stormwind how do i get to darnassus", "how to get to darnasus" }, a = "Take the Stormwind Harbor boat to Auberdine (Darkshore), then the Auberdine boat to Rut'theran Village. In Rut'theran, walk into the pink portal in the big tree to arrive in Darnassus. Hearthing to Auberdine puts you one boat from Stormwind, Darnassus, Menethil and Southshore.", topic = "gaps" }
add{ q = { "how do i get to booty bay", "get to booty bay", "booty bay from ratchet", "how to get to stranglethorn", "alliance to stranglethorn", "horde to stranglethorn", "how to get to stv", "bb how to get there", "booty bay boat", "how to get to bb from org", "booty bay flight path", "ratchet to booty bay" }, a = "Alliance: run south from Duskwood through Stranglethorn to Booty Bay at the southern tip, and pick up the Rebel Camp and Booty Bay flight points on the way. Horde: take the zeppelin to Grom'gol in north STV and ride south. Both: the goblin boat from Ratchet (The Barrens) docks at Booty Bay.", topic = "gaps" }
add{ q = { "how do i get to tanaris", "get to gadgetzan", "how to get to gadgetzan", "alliance to tanaris", "horde to tanaris", "tanaris from thousand needles", "how to get to tanaris alliance", "gadgetzan flight", "tanaris location", "how do i reach gadgetzan", "horde how to get to tanaris" }, a = "Ride south from Thousand Needles through the Shimmering Flats and into Tanaris. Gadgetzan's flight point serves both factions. The new Steamwheedle Port ferry in Tanaris runs to Powderfuse Port in the Riverglades, a fast link to Eastern Kingdoms.", topic = "gaps" }
add{ q = { "where can i buy arrows", "where to buy arrows", "where to buy bullets", "ammo vendor", "arrow vendor", "bullet vendor", "where do i get ammo", "out of arrows", "buy ammo", "where to get bullets for gun", "hunter ammo where", "who sells arrows", "im out of arrows where can i buy more", "wher to buy arrows" }, a = "General Goods and Trade Supplies vendors in most towns sell basic arrows and bullets, and bow, gun and weapon vendors in bigger towns carry better ones. Buy a big stack, then drag it to your ammo slot or quiver. Vendor arrows by level: Rough 1, Sharp 10, Razor 25, Jagged 40. Engineers can craft bullets. Restock in every town, because running dry in a dungeon kills your damage.", topic = "gaps" }
add{ q = { "do i need a quiver", "quiver or ammo pouch", "what is a quiver", "ammo bag", "where do i get a quiver", "quiver speed bonus", "ammo pouch for guns", "quiver", "where to buy quiver", "ammo pouch", "best quiver", "does a quiver help" }, a = "Bows and crossbows use arrows and a Quiver, and guns use bullets and an Ammo Pouch. Both bags hold only their ammo type and add ranged attack speed. Buy them from bow, gun or general vendors in towns, or from the AH. Leatherworkers make better ones later.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "how do i follow a quest chain", "quest chain next step", "what is the next quest", "where is the next part of the quest", "how to find next quest in chain", "quest chain help", "i finished the quest whats next", "how do i continue the quest line", "next step quest", "lost the quest chain", "how do i know where to go next quest", "finished quest no follow up", "i finished part one and dont know where part two is", "quest chian next step" }, a = "1. When you turn a quest in, the NPC often offers the follow-up right away. Look for a new ! on them, or in the window after you take the reward.\n2. Read the completion text. It names the next NPC and place ('speak to X in Y').\n3. Check your quest log (L) and map (M) for the new marker. Questie also shows follow-up givers.\n4. If nothing appears, the next part may need a higher level, a reputation, or a quest you skipped earlier. Come back after leveling, or finish the earlier step.", topic = "gaps" }
add{ q = { "what is a breadcrumb quest", "breadcrumb quest", "what does breadcrumb mean", "do i need to do breadcrumb quests", "can i skip breadcrumb", "breadcrumb disappeared", "breadcrumb quest gone", "what are breadcrumbs wow", "skipped the breadcrumb", "breadcrumb quest worth it", "what is breadcrumb quest do i need it", "breadcrum quest" }, a = "A breadcrumb quest is a short 'go talk to this person' quest that sends you to a new hub, zone or quest chain. It's optional: you can walk to the destination NPC and start the chain without it. Once you start the main chain, the breadcrumb often disappears from quest givers. It's still worth taking when you see it, because it gives free XP and points you to where you should go next.", src = "classic", topic = "gaps" }
add{ q = { "why isnt the quest showing up", "quest not showing", "quest giver has no exclamation mark", "cant find quest", "no ! above npc", "quest not available", "npc wont give me the quest", "why cant i get this quest", "quest missing", "where is the quest", "quest not appearing", "guide says take quest but its not there", "the guide says to pick up a quest but the npc doesnt have it", "quest not showin up" }, a = "Common reasons:\n1. Level too low. Many quests appear a few levels before their level.\n2. You skipped a prerequisite or breadcrumb earlier in the chain.\n3. Wrong race, class or faction, or not enough reputation (some need Neutral or better).\n4. You already did it. Most quests can be done only once.\n5. It's low level and hidden. Turn on showing low-level quests (Esc > Options, search 'quest', or the map's filter).\n6. Your quest log is full.\n7. The NPC is dead, despawned or busy with an escort. Wait for the respawn or change layer by grouping with someone.", topic = "gaps" }
add{ q = { "how do i see low level quests", "show low level quests", "trivial quests", "show grey quests", "where are low level quests", "turn on low level quest tracking", "show trivial quests forever", "grey quests not on map", "low level ! not showing", "i want to see the grey quests on my map how", "show low lvl quests" }, a = "Forever hides quests far below your level by default. Turn them back on with Esc > Options: type 'quest' in the search box and enable the option that shows lower-level quests. Or use the filter on the world map or minimap tracking. Questie also has a 'show low level quests' toggle. They give much less XP, but they can still be worth doing for gear, gold or a chain's next step.", topic = "gaps" }
add{ q = { "what do quest colors mean", "quest colors", "grey quest", "green quest", "red quest", "orange quest", "yellow quest", "quest difficulty colors", "is red quest too hard", "what does grey quest mean", "quest level color", "why is my quest red", "what does grey quest mean is it worth" }, a = "Quest colors compare the quest's level to yours. Red is 5+ above (very hard). Orange is 3-4 above (hard). Yellow is within 2 (normal). Green is 3-4 below (easy, slightly less XP). Grey is 5+ below (trivial, much less XP, often hidden). Mobs use the same colors, and a skull means 10+ levels above you.", topic = "gaps" }
add{ q = { "what does the exclamation mark mean", "yellow exclamation", "question mark above npc", "grey question mark", "blue exclamation mark", "what does ? mean", "quest markers meaning", "silver exclamation", "quest icons", "what does yellow ? mean", "what do the yellow ! mean over npcs", "what does the blue ! mean" }, a = "A yellow ! means a quest is available. A yellow ? means a quest is ready to turn in. A grey or silver ? means you have that quest but haven't finished it. A blue ! or ? usually marks a repeatable quest. If an NPC shows nothing, there's no quest for you right now (see why a quest isn't showing).", src = "classic", topic = "gaps" }
add{ q = { "how do i abandon a quest", "abandon quest", "delete quest", "remove quest from log", "how to drop a quest", "get rid of a quest", "cancel quest", "abandon quest restart", "how do i get rid of this quest i dont want", "abandon quest how" }, a = "Open the quest log (L), select the quest and click Abandon (or right-click it in the tracker). To redo it, go back to the original quest giver and take it again. Quest items from it are usually removed. Abandoning is also how you fix a quest whose item you deleted.", topic = "gaps" }
add{ q = { "how do i share a quest", "share quest", "share quest with party", "how to give quest to friend", "quest share not working", "friend cant get my quest", "push quest to group", "cant share quest", "share quest button", "how do i give my friend the quest", "why cant i share this quest", "quest sharing" }, a = "Open your quest log (L), select the quest and click Share, while your friend is in your party and nearby. It fails if they're too low level, already have it or did it, are missing a prerequisite, or have a full log. Some quests, like item-started ones and class quests, can't be shared.", src = "classic", topic = "gaps" }
add{ q = { "how do i track quests", "quest tracker", "track quest", "untrack quest", "quest objectives on screen", "quest tracker disappeared", "how to see quest objectives", "quest tracker too big", "hide quest tracker" }, a = "Tracked quests show their objectives on the right side of the screen, and the map (M) and minimap mark their areas when quest markers are on (Enhanced preset). In the quest log (L), tick or untick quests to track them, or shift-click one. Quest options are on the quest log itself. Untrack the quests you aren't doing so the tracker stays readable.", topic = "gaps" }
add{ q = { "quest item not dropping", "quest drop rate", "why wont the quest item drop", "mobs not dropping quest item", "bad drop rate quest", "quest item low drop", "i killed 50 mobs no drop", "quest loot not showing", "ive killed like 30 mobs and the item wont drop", "quest item not droping" }, a = "1. Make sure you have the quest. Many quest items drop only while it's in your log.\n2. Kill the right mob, since the item may drop only from one type or one area.\n3. If you're grouped, check whether your loot was taken by someone else; most quest items drop for each person who has the quest.\n4. You must have tagged the mob (hit it first, or your group did).\n5. Some drops are simply low. Kill nearby mobs of that type, and try another layer if it's crowded.", src = "classic", topic = "gaps" }
add{ q = { "mob is grey", "tapped mob", "someone else tagged my mob", "mob already tagged", "grey name mob no loot", "why no loot from mob", "no xp from kill", "who gets credit for kill", "mob tap", "stole my mob", "why did i get no loot the mob was grey", "someone tagged my mob" }, a = "A mob with a grey name or health bar is tagged by someone else, so you get no XP, loot or quest credit for killing it. The first player or group to damage a mob owns it. To share kills, group up: everyone in a party gets credit. In crowded zones, invite people who are killing the same quest mobs.", src = "classic", topic = "gaps" }
add{ q = { "what is an elite mob", "elite quest", "gold dragon mob", "elite mobs", "can i solo elite", "group quest", "what does elite mean", "rare elite", "silver dragon mob", "what is a rare mob", "rare spawn", "what does the gold dragon around the portrait mean", "what is elite" }, a = "A gold dragon border on a portrait means Elite: much more health and damage, meant for 2-5 players. Quests marked Elite or Group want a party. A silver dragon means a Rare spawn (sometimes rare elite). Rares respawn slowly and usually drop a guaranteed green or better. In Forever, rare elites drop leveling gear that can last 5-10 levels.", topic = "gaps" }
add{ q = { "escort quest failed", "how to restart escort quest", "escort npc died", "escort quest npc missing", "escort not starting", "escort quest someone else", "where is the escort npc", "escort failed", "escort npc dead", "redo escort quest", "escort quest wont start", "escort keeps failing" }, a = "If the escort NPC dies, the quest fails. Abandon it in the quest log (L) and take it again from the NPC once it respawns, which usually takes a few minutes. If another player is already escorting it, wait, or join their party to share the escort. Clear the route first and keep the NPC alive with heals or tanking.", src = "classic", topic = "gaps" }
add{ q = { "quest log full", "how many quests can i have", "max quests", "quest log limit", "cant accept quest log full", "too many quests", "quest log size", "my quest log is full", "full quest log", "cant take more quests", "quest log space", "remove quests to make room" }, a = "The quest log has a fixed number of slots. When it's full you can't accept new quests. Abandon grey, finished-elsewhere or low-value quests in the log (L) to make room. Turning in finished quests first is usually the quickest fix.", src = "classic", topic = "gaps" }
add{ q = { "which quest reward should i pick", "quest reward choice", "what reward to choose", "quest reward sell value", "best quest reward", "should i take the weapon or armor reward", "quest reward which one", "choose quest reward", "which reward is best", "what quest reward for my class", "pick reward or sell", "what reward do i take" }, a = "Pick an upgrade your class can use: right armor type, your main stats, and a weapon type you've trained. Compare it with your equipped item by hovering. If nothing helps, take the one with the highest vendor price (shown on the tooltip) or one that sells well on the AH. Some rewards are better for your second spec later.", src = "classic", topic = "gaps" }
add{ q = { "quest says go somewhere i cant find", "cant find quest location", "where is quest objective", "quest area not on map", "how to find quest npc", "quest target location", "how do i find where the quest is", "cant find the quest area", "where do i go for this quest", "quest location help", "im lost quest", "cant find quest target", "map doesnt show quest" }, a = "1. Open the map (M). With quest markers on (Enhanced preset, or the map filter) the objective area is shaded.\n2. Click the quest in the tracker to see it on the map.\n3. Read the quest text for directions: 'north of', 'in the cave', 'at the farm'.\n4. Ask a guard for NPCs and services in cities.\n5. Questie adds exact markers for most Classic quests, but some new Forever quests may be missing.", topic = "gaps" }
add{ q = { "what is a dungeon quest", "where do i get dungeon quests", "dungeon quests forever", "should i get quests before dungeon", "dungeon quest xp", "why do dungeon quests matter", "dungeon quest location", "how to get dungeon quests", "do dungeon quests give xp", "pick up dungeon quests where", "quests for deadmines where", "should i do dungeon quests" }, a = "Dungeon quests are picked up outside, in the dungeon's zone and nearby cities, then finished inside. In Forever they give much more XP than Classic (the Deadmines quests give about 19,000 XP in total), while mob kill XP is lower. Always grab them before you go in, and share the shareable ones with your group at the entrance.", topic = "gaps" }
add{ q = { "class quest not showing", "where is my class quest", "cant find class quest", "class trainer no quest", "class quest level", "how do i get class quests", "class quest missing", "no class quest at trainer", "when do i get class quests", "class quests list", "my trainer has no quest", "class quest level 10" }, a = "Class quests come from your class trainer at certain levels (often 10, 20, 30, 40 and 50), and from letters you get early on. If none shows: 1. Check your level. 2. You may need the trainer in your race's starting area or capital. 3. Turn on low-level quests if you've outleveled it. 4. Some are race-specific, e.g. Warrior Defensive Stance, Druid forms and Shaman totems.", src = "classic", topic = "gaps" }
add{ q = { "quest npc is dead", "quest giver dead", "quest npc missing", "where did the quest giver go", "npc not spawned", "quest npc gone", "quest giver is dead", "npc respawn time", "quest npc not there", "cant find npc he is gone", "npc dead how long respawn", "quest npc killed by someone" }, a = "Quest NPCs that are killed or run off for an event respawn after a few minutes. If they're still missing, change layer by grouping with someone in the zone, then leaving. Some NPCs patrol, so check along the road nearby. Also confirm the NPC is the right faction: hostile NPCs won't talk to you.", src = "classic", topic = "gaps" }
add{ q = { "timed quest failed", "quest failed timer", "how to redo failed quest", "quest says failed", "my quest failed", "quest failed", "failed quest how to restart", "quest failed what do i do", "red failed quest log", "redo failed quest" }, a = "Some quests have a timer or fail if an NPC dies. A failed quest stays red in your log. Abandon it (L > Abandon), then take it again from the quest giver.", src = "classic", topic = "gaps" }
add{ q = { "how do i move", "controls", "how to walk", "wasd", "how to jump", "how to autorun", "autorun key", "how do i run", "basic controls wow", "mouse controls", "how to turn camera", "how to move with mouse" }, a = "W and S move forward and back, Space jumps, and Num Lock (or both mouse buttons held) runs forward. Hold right mouse to steer and turn the camera, and left mouse to look around without turning. A/D turn or strafe depending on your preset (Q/E strafe in the Classic layout). Change any key in Esc > Options > Keybindings.", topic = "gaps" }
add{ q = { "how do i attack", "how to fight", "auto attack", "how to start attacking", "how do i hit a mob", "how to target enemy", "tab target", "how to select a mob", "right click to attack", "how to target nearest enemy" }, a = "Left-click a mob to target it, or press Tab to cycle through nearby enemies. Right-click it (or press an ability) to start auto-attacking. Then use your abilities from the action bar with 1-0 keys. Watch the mob's level color and pull one at a time while learning.", topic = "gaps" }
add{ q = { "how do i loot", "how to loot", "loot mobs", "where is my loot", "sparkly corpse", "cant loot", "loot all", "how to pick up items" }, a = "Right-click a sparkling corpse to open its loot, then click the items (or Shift-click for auto loot). Turn on Auto Loot in Options (search 'auto loot') so one click takes everything. If you can't loot, someone else tagged the mob, or your bags are full.", topic = "gaps" }
add{ q = { "how do i sell junk", "sell grey items", "how to sell items", "vendor trash", "what to do with grey items", "sell to vendor", "how do i sell stuff", "buyback", "sold wrong item" }, a = "Right-click any merchant to open their window, then right-click items in your bags to sell them. Grey items are vendor trash and have no other use. If you sell something by mistake, use the Buyback tab right away. You can't buy back items after you log out.", topic = "gaps" }
add{ q = { "how do i get more bags", "bags", "where to buy bags", "bigger bags", "bag slots", "cheap bags", "first bags", "8 slot bag", "where do i get bags early", "need more inventory space", "how to get bigger bags", "my bags are always full how do i get bigger ones", "where to get bags" }, a = "1. Do your race's 6-slot starter bag quest in the starting zone.\n2. Buy 6- or 8-slot bags from general goods/trade vendors, or cheap bags from the AH. Guides suggest filling all 4 slots by about level 10.\n3. Tailors craft Linen (6), Woolen (8), Silk (10), Mageweave (12) and Runecloth (14) bags.\n4. Quest rewards give bags too, such as the 12-slot Old Toolbox from the Cozy Sleeping Bag hunt and an 18-slot bag in Hyjal.", topic = "gaps" }
add{ q = { "what should i do at level 10", "level 10 what now", "i just hit 10", "level 10 checklist", "what unlocks at 10", "what to do after starting zone", "level 10 talents", "leaving starting zone", "just hit level 10 what should i do now", "lvl 10 what now" }, a = "At 10:\n1. Your first talent point unlocks. Open Talents (N).\n2. Visit your trainer for new spells and class quests: Warlock Voidwalker, Hunter taming, Druid Bear Form, Warrior Defensive Stance, Shaman fire totem.\n3. Warsong Gulch opens (10-19 bracket).\n4. Head to your faction's next zone: Westfall, Loch Modan, Darkshore, The Barrens or Silverpine.\n5. Set your hearthstone at your new hub and grab the flight points.", topic = "gaps" }
add{ q = { "what should i do at level 20", "level 20 what now", "i just hit 20", "level 20 checklist", "what unlocks at 20", "level 20 quests", "level 20 class quests", "i just hit 20 what now", "level 20 what to do", "20 checklist", "what to train at 20", "level 20 unlocks" }, a = "At 20: train new ranks, and grab the class quests: Warlock Succubus/Incubus, Druid Cat Form, Rogue poisons, Mage teleports (two capitals) and Shaman Ghost Wolf. Polearm skill opens. Good dungeons are Deadmines, Shadowfang Keep, then BFD/Stockade. The next zones are Wetlands, Hillsbrad, Duskwood, Redridge, Stonetalon and Ashenvale. Start saving for your 40 mount (100g).", src = "classic", topic = "gaps" }
add{ q = { "what should i do at level 30", "level 30 what now", "i just hit 30", "level 30 checklist", "what unlocks at 30", "level 30 quests", "30 checklist", "level 30 what to do", "what changes at 30", "what to train at 30", "berserker stance level 30" }, a = "At 30: Warriors do Berserker Stance on Fray Island (Barrens), Warlocks get the Felhunter (Seeking Strahad), Druids train Travel Form, Shamans get Reincarnation and Windfury, and Mages get their third capital teleport. Scarlet Monastery Graveyard and Razorfen Kraul suit this level. Zones: Alterac, Arathi, Desolace and Stranglethorn. Keep saving for 40.", src = "classic", topic = "gaps" }
add{ q = { "what should i do at level 40", "level 40 what now", "i just hit 40", "level 40 checklist", "what unlocks at 40", "level 40 mount and armor", "40 dual spec", "just hit 40", "40 checklist", "level 40 what to do", "what to buy at 40", "what to train at 40" }, a = "At 40:\n1. Buy Apprentice Riding (100g, includes a mount) from your race's riding trainer. Paladins and Warlocks get their free mount quest instead.\n2. Warriors and Paladins train Plate, and Hunters and Shamans train Mail.\n3. Dual Talent Specialization is available from your trainer for 50g.\n4. Mages get group portals.\n5. Zones: Tanaris, Hinterlands and Shen'dralas. Dungeons: SM Cathedral, Krol'dok, Uldaman.", topic = "gaps" }
add{ q = { "what to do at 60", "i just hit 60", "level 60 what now", "what do i do at max level", "endgame forever", "60 checklist", "max level what to do", "level 60 guide", "now im 60 what", "what is there to do at 60", "just dinged 60", "just dinged 60 on my mage whats next", "i hit 60 what do i do now" }, a = "Fresh 60 plan:\n1. Train your last ranks and set up your raid/dungeon talents.\n2. Gear up in 60 dungeons: Blackmaw Hold, Shaper's Terrace, Strat, Scholo, Dire Maul, BRD and LBRS/UBRS.\n3. Do Mount Hyjal (level 60 quests and reputations, the raid hub).\n4. Start the Onyxia attunement and prepare for Barrow Deeps (10) and Hyjal Summit (20) from Dec 9.\n5. Farm gold for Journeyman Riding (1,000g + 200g mount).\n6. Level professions to 300 for Legacy points, and run PvP if you like.", topic = "gaps" }
add{ q = { "how long does it take to level to 60", "how long to 60", "hours to 60", "how many hours to max level", "time to level 60 forever", "is leveling long", "how long to level", "leveling time forever", "how many days played to 60", "is 60 far", "average time to 60" }, a = "Expect 100+ hours played for a first 60. The XP curve is Classic's (about 4.08 million XP total), and combat is deliberately slow at roughly 10-15 seconds per normal mob. Experienced players with heavy dungeon groups did it much faster; the world-first party hit 60 a little over 3 days after launch.", topic = "gaps" }
add{ q = { "what zone should i go to", "where should i level", "next zone", "what zone for my level", "zone level ranges", "where do i go at 20", "zone after westfall", "what zone at 30", "zone levels list", "where to quest at my level", "im level 24 where should i go to quest", "what zone for lvl 30" }, a = "Recommended minimum levels: 1 starting zones/Zephras Isle; 10 Westfall, Loch Modan, Darkshore, Barrens, Silverpine; 15 Redridge, Stonetalon; 18 Ashenvale; 20 Wetlands, Hillsbrad, Duskwood; 25 Thousand Needles; 30 Alterac, Arathi, Desolace, STV; 35 Badlands, Dustwallow, Feralas, Riverglades, Swamp of Sorrows; 40 Shen'dralas, Tanaris, Hinterlands; 43 Searing Gorge; 45 Azshara, Felwood, Blasted Lands; 48 Un'Goro; 50 Burning Steppes, WPL; 53 Winterspring, EPL; 55 Silithus, Deadwind; 60 Mount Hyjal.", topic = "gaps" }
add{ q = { "what class should i play", "best class for beginners", "easiest class", "which class is best", "what class to pick", "best solo class", "best class forever", "im new what class", "easiest class to level", "which class is fun", "never played wow before what class should i pick", "wat class should i play" }, a = "For an easy first character, Hunter and Warlock are the most comfortable levelers thanks to their pets, and Hunter leveled fastest in beta. Mage is fast too and makes free food and water. Druids can do every role. Warriors and Priests level slowest solo, but they're always wanted in groups. Pick the role you want: tank (Warrior, Paladin, Druid), healer (Priest, Paladin, Druid, Shaman) or damage (everyone).", topic = "gaps" }
add{ q = { "how do i play with friends", "play with friends", "how to join my friend", "cant see my friend", "friend on different server", "how to group with friend", "why cant i invite my friend", "play with friend different faction", "my friend and i cant see each other how do we play together", "play with my freind" }, a = "You must be on the same region, ruleset (Normal, PvP, RP, RP-PvP) and faction. Forever has no realms, so add each other on Battle.net and invite with /invite Name. Joining a group also pulls you onto the same layer, so you can see each other. Alliance and Horde can't group.", topic = "gaps" }
add{ q = { "how do i whisper", "whisper someone", "how to send private message", "how to reply to whisper", "/w command", "private chat", "how to dm a player", "whisper", "how to message someone", "reply to whisper", "how to pm someone", "whisper not working", "/r reply" }, a = "Type /w Name message (or /whisper) and press Enter. Press R to reply to the last person who whispered you. In Forever, whispers open in a new chat tab by default; you can change that under Options > Social.", topic = "gaps" }
add{ q = { "how do i leave a group", "leave party", "how to leave group", "kick from group", "how to remove someone from party", "disband group", "how to make someone leader", "leave group", "/leave", "how do i quit the party", "how to kick someone", "promote to leader", "how to convert to raid", "leave party command" }, a = "Right-click your own portrait and choose Leave Group (or type /leave). The leader can right-click a member's portrait to Uninvite or Promote them to leader. To turn a party into a raid, right-click your portrait and choose Convert to Raid.", src = "classic", topic = "gaps" }
add{ q = { "how do i inspect someone", "inspect player", "see someone's gear", "check other players gear", "how to look at someones equipment", "inspect", "how to see what gear someone has", "inspect not working", "check gear of player", "look at someones gear", "how to inspect gear" }, a = "Right-click the player's portrait and choose Inspect, or target them and press the inspect key bound in Options. You need to be fairly close. Shift+right-clicking the portrait also offers it.", src = "classic", topic = "gaps" }
add{ q = { "how do i trade", "trade with player", "how to give item to friend", "trade window", "how to trade gold", "cant trade item", "trade", "/trade", "how to give gold", "trade not working", "how do i give my friend items", "cant trade soulbound" }, a = "Right-click the player's portrait and choose Trade (or type /trade), then drag items and gold into the window. Both players click Trade to finish. Soulbound (Bind on Pickup or equipped Bind on Equip) items can't be traded, except BoP loot within 2 hours to someone who was in the group when it dropped.", src = "classic", topic = "gaps" }
add{ q = { "how do i roll", "/roll", "how to roll dice", "roll command", "random roll", "roll", "roll dice", "/roll 100", "roll for loot", "how to roll a number", "random number" }, a = "Type /roll for a random number from 1 to 100, or /roll 1-1000 style ranges. Everyone nearby or in your group sees the result. Groups use it to settle loot without the Need/Greed window.", src = "classic", topic = "gaps" }
add{ q = { "how do i see my played time", "/played", "how long have i played", "time played", "playtime", "played time", "how many hours played", "/played command", "total played", "time played this level" }, a = "Type /played in chat to see your total time played on this character and time at your current level.", src = "classic", topic = "gaps" }
add{ q = { "how do i logout", "log out", "exit game", "camp logout", "logout timer", "how to quit", "why does logout take 20 seconds", "logout", "/logout", "/camp", "how to log off", "quit game", "logout in inn" }, a = "Press Esc and choose Log Out or Exit Game, or type /logout or /camp. Outside inns and cities there's a 20-second timer, and moving cancels it. Log out in an inn or capital so you build rested XP.", src = "classic", topic = "gaps" }
add{ q = { "how do i hide my helmet", "hide helm", "hide cloak", "show helm", "turn off helmet", "transmog hide helmet", "hide helmet", "hide my helm", "show cloak", "dont want to see my helmet", "how to hide cloak forever", "hide shoulders" }, a = "Guides haven't confirmed a Show Helm/Show Cloak checkbox for Forever. The usual way on this client is transmog: a Transmogrifier can set a slot to a hidden appearance. Transmogrifiers are in Stormwind's Mage District (Fyrenz Vishonar), Dalaran (Spellweaver Thaldris) and Orgrimmar's Cleft of Shadow (Mon'ye).", src = "classic", topic = "gaps" }
add{ q = { "why cant i mount here", "cant mount", "mount not working", "you cant mount here", "mount greyed out", "cant use mount indoors", "why cant i ride my mount", "cant mount in dungeon", "cant mount in shendralas", "mount not working in combat", "why cant i use my mount", "store mount wont work" }, a = "You can't mount indoors, in combat, while shapeshifted, swimming, in some dungeons (Stratholme mounting was disabled Nov 9) or in Shen'dralas. Your mount also needs Apprentice Riding. If you got a store or quest mount, train Riding at 40 first. Warlocks who finished the Felsteed quest before Nov 9 should summon it once to receive riding skill.", topic = "gaps" }
add{ q = { "why do mobs run away", "mob fleeing", "mob runs at low health", "humanoids flee", "mob ran and brought friends", "stop mob from fleeing", "fleeing mobs", "mob runs away", "mobs flee", "mob running for help", "stop mobs fleeing", "why do mobs run at low hp", "humanoid running away" }, a = "Many humanoid mobs flee at low health and can drag more mobs back. Finish them before they run: save an instant attack, stun or snare for the last 20% (Hamstring, Frost Nova, Concussive Shot, Seal of Justice's Judgement, Wing Clip). Fight away from other mobs so a runner can't pull friends.", src = "classic", topic = "gaps" }
add{ q = { "why am i dazed", "dazed", "what is dazed", "daze slow", "keep getting dazed", "dazed from behind", "what does dazed mean", "dazed when running", "how to avoid daze", "why am i so slow", "getting dazed by mobs", "dazed debuff" }, a = "Dazed slows your movement for a few seconds. Mobs can daze you when they hit you from behind, and Hunters are dazed when hit while Aspect of the Cheetah or the Pack is on. Face the mob and don't run through mob packs while unmounted.", src = "classic", topic = "gaps" }
add{ q = { "what does skull level mean", "skull icon mob", "?? level mob", "mob level skull", "mob shows skull", "skull mob", "?? mob", "mob with skull", "skull next to name", "what is ?? level", "red skull level" }, a = "A skull (??) in place of a mob's level means it's 10 or more levels above you, or a boss. You'll almost always miss and get crushed. Avoid it, or bring a much stronger group.", src = "classic", topic = "gaps" }
add{ q = { "how do i tank", "tank tips", "how to tank dungeons", "tanking basics", "first time tanking", "how to hold aggro", "tank guide forever", "tanking tips", "tank guide", "how to tank as warrior", "how to tank as pally", "how to tank as bear", "first dungeon as tank", "first time tanking a dungeon any tips" }, a = "1. Mark targets (skull first, X second) and pull to a spot where you can fight with your back near a wall.\n2. Open on the skull, then tab around hitting each mob so all of them stick to you.\n3. Face the mobs away from the group.\n4. Taunt anything that runs at a healer (Warrior Taunt, Paladin Judgement of Fury, Druid Growl).\n5. Watch the healer's mana, and wait for them to drink.\n6. Use cooldowns before you're low.", src = "classic", topic = "gaps" }
add{ q = { "how do i heal", "healing tips", "how to heal dungeons", "first time healing", "healer basics", "heal tips forever", "how to not go oom healing", "healing guide", "healer tips", "how to heal as priest", "how to heal dungeon", "going oom healing", "healing for beginners", "first time healing a dungeon tips" }, a = "1. Stand back where you can see the tank and everyone, but out of mob range.\n2. Use efficient heals early and save big heals for spikes. Don't overheal.\n3. Watch the five-second rule: stop casting between pulls so Spirit regen kicks in.\n4. Drink at 30-40% mana and say so, so the tank waits.\n5. Turn on raid-style party frames and Target of Target in Options.\n6. If you pull aggro, move toward the tank.", src = "classic", topic = "gaps" }
add{ q = { "how to do a dungeon first time", "dungeon tips", "dungeon etiquette", "first dungeon what to know", "how dungeons work", "dungeon beginner", "first dungeon tips", "how do dungeons work", "dungeon for beginners", "dungeon rules", "what to do in dungeon", "first time dungeon", "dungeon basics" }, a = "1. Pick up the dungeon's quests and share them.\n2. Travel to the entrance, since there's no teleport or summon stone. A Warlock can summon with two people present.\n3. Let the tank pull, and attack the marked skull first.\n4. Don't attack crowd-controlled (sheeped or sapped) mobs.\n5. Agree on loot (Need only for main-spec upgrades).\n6. Wait for the healer's mana.", topic = "gaps" }
add{ q = { "how do i mark targets", "raid markers", "skull marker", "target icons", "how to put skull on mob", "mark mob x", "raid target icons", "mark targets", "raid target icon", "put skull on target", "how to mark mobs", "target markers", "marker keybind" }, a = "Right-click the mob's portrait, choose Raid Target Icon and pick one (skull, X, moon, square and so on). Anyone in a party can mark by default. In raids, only leaders and assistants can. Bind keys for markers under Options > Keybindings for faster pulls. Usual meaning: skull is killed first, X second, moon is sheeped.", src = "classic", topic = "gaps" }
add{ q = { "how do i see threat", "threat meter", "aggro meter", "am i pulling aggro", "threat display", "how to check aggro forever", "threat", "see aggro", "who has aggro", "threat on nameplates", "threat warning", "pulling threat" }, a = "Forever's nameplates have built-in aggro coloring options (Options > Nameplates), and the target frame shows a threat indicator when a mob is close to switching to you. Turn on Target of Target so you can see who the mob is hitting. Damage dealers should hold back for a few seconds on each pull.", src = "classic", topic = "gaps" }
add{ q = { "what is cc", "crowd control", "what does cc mean", "sheep sap trap", "cc in dungeon", "who can cc", "cc", "crowd control explained", "sheep in dungeon", "what is cc in wow", "who should cc", "dont break cc" }, a = "CC (crowd control) disables a mob so the group fights fewer at once. Examples: Mage Polymorph (sheep), Rogue Sap, Hunter Freezing Trap, Warlock Banish (demons and elementals) and Seduce, Druid Hibernate (beasts and dragonkin) and Entangling Roots, Priest Shackle Undead and Mind Control, Paladin Turn Undead. Don't hit a CCed mob unless the plan says so.", src = "classic", topic = "gaps" }
add{ q = { "what does bop and boe mean", "soulbound", "bind on pickup", "bind on equip", "can i sell this item", "why cant i trade this", "boe item", "what is soulbound" }, a = "Bind on Pickup (BoP) items become yours when you loot them and can't be traded or sold on the AH. Bind on Equip (BoE) items can be traded or auctioned until someone equips them. Soulbound items can only be used, vendored or disenchanted.", src = "classic", topic = "gaps" }
add{ q = { "how to use the auction house", "how to sell on ah", "how to buy from ah", "auction house tutorial", "post item on ah", "ah deposit", "how does ah work forever", "auction house", "ah", "how to sell on auction house", "how to buy on auction house", "ah tutorial", "how does auction house work", "auction house deposit" }, a = "1. Find an auctioneer in a capital (or Booty Bay, Gadgetzan, Everlook).\n2. Browse: search a name or category, then click Buy.\n3. Sell: open the Sell tab, drag an item in, set the price and duration, and pay the deposit (refunded only if it sells).\n4. Gold and unsold items come by mail. In Forever the auction house is shared across your ruleset, so you can buy from level 1.", topic = "gaps" }
add{ q = { "how do i make money early", "gold while leveling", "how to get gold low level", "im broke", "how to make gold at level 20", "best early gold", "gold for mount", "make gold early", "money making low level", "early gold farm", "how to get rich leveling", "need gold for mount", "im poor what do i do", "im level 25 and broke how do i get gold for my mount" }, a = "1. Take two gathering professions (Herbalism and Mining, or Skinning) and sell the mats on the AH.\n2. Sell cloth, linen and wool stacks, which go fast.\n3. Vendor every grey item, and loot everything.\n4. Skip spell ranks you don't use.\n5. Do quests. Most give gold and items to sell.\nAim to have 100g saved by 40 for riding.", topic = "gaps" }
add{ q = { "what do i need to know returning player", "returning player forever", "coming back from classic", "whats new for returning players", "i played vanilla whats changed", "veteran tips forever", "returning player", "coming back to wow", "played classic before", "returning to wow forever", "im returning whats different", "what changed since classic" }, a = "Big changes from Classic:\n1. New spells aren't put on bars automatically. Drag them from P.\n2. Talents are reworked (27 specs, new 16-point gold talents).\n3. Hit and crit are each one stat.\n4. Mob kill XP in dungeons is lower, but dungeon quests pay big.\n5. Combat is slower.\n6. No world buffs inside instances.\n7. Professions have their own window (K), and there's Camping.\n8. The account-wide Legacy system (Y).\n9. Raids reset weekly, Onyxia included.", topic = "gaps" }
add{ q = { "why are my spell names different", "curse of agony renamed", "bane of agony", "spell renamed forever", "where did curse of agony go", "spell names changed", "curse of agony missing", "bane spells warlock", "renamed spells forever", "cant find my spell", "old spell name" }, a = "Forever renamed or reworked several spells. For example, the Warlock's Curse of Agony is now Bane of Agony, and Infernal is Inferno. If a guide uses the old name, look for the same icon in your spellbook (P), or search the spellbook by name.", class = "WARLOCK", src = "classic", topic = "gaps" }
add{ q = { "how do i get summoned", "warlock summon", "ritual of summoning", "how to get a summon to dungeon", "summon stone not working", "meeting stone forever", "summon to dungeon", "how to get a summon", "summoning stone", "meeting stone not working", "warlock summon how", "no summon stones" }, a = "Meeting stones don't summon in Forever. The only summon is a Warlock's Ritual of Summoning: the warlock plus two other party members at the spot click the portal, and it costs the warlock a Soul Shard. Everyone else has to travel to the entrance.", topic = "gaps" }
add{ q = { "how to change talents", "respec", "reset talents", "how do i respec", "talent reset cost", "change spec", "change talents", "respec talents", "talent reset", "how much is respec", "how to unlearn talents", "reset my talents" }, a = "Talk to your class trainer and choose the option to unlearn talents (Legacy talents can be reset there too). Fees climb with each reset (1g, 5g, 10g and so on) up to a 50g cap, then decay back toward 1g over time. Dual spec (50g at 40) lets you keep two builds and swap out of combat.", topic = "gaps" }
add{ q = { "where is my xp", "xp bar missing", "how much xp do i need", "how to see xp to next level", "rested xp bar", "xp bar", "exp bar", "where is my exp bar", "how much xp to level", "xp bar gone", "rested xp", "how to see exp" }, a = "The XP bar is along the bottom, above your action bars. Hover over it for exact numbers. The blue/purple shaded part is rested XP. If it's hidden, open Esc > Edit Mode and enable the status tracking bar.", src = "classic", topic = "gaps" }
add{ q = { "how do i get to undercity", "where is undercity entrance", "how to enter undercity", "undercity elevator", "ruins of lordaeron undercity", "undercity", "how to get to uc", "uc entrance", "where is undercity", "undercity from tirisfal", "how to get into undercity", "undercity elevators", "im at the zeppelin tower how do i get into undercity", "how to get to undercty" }, a = "The Undercity is under the Ruins of Lordaeron in southern Tirisfal Glades. Walk through the ruined city to the throne room, then take the green elevators down. The zeppelin tower is just north of the ruins. In Forever the Ruins of Lordaeron above also hold a new dungeon (15-20).", src = "classic", topic = "gaps" }
add{ q = { "how do i get to ironforge from stormwind", "deeprun tram", "tram location", "where is the tram", "stormwind ironforge tram", "stormwind to ironforge", "sw to if", "tram", "how to get to if", "deeprun tram where", "how to get to ironforge", "ironforge from sw" }, a = "Take the Deeprun Tram from Stormwind's Dwarven District. It drops you in Ironforge's Tinker Town in about a minute. Once you have both flight points, you can also fly.", topic = "gaps" }
add{ q = { "what is layering", "layers", "why do players disappear", "how to change layer", "layer hop", "phasing forever", "layering", "why cant i see my friend", "change layer", "how to layer hop", "what layer am i on", "layer" }, a = "Busy zones are split into copies called layers. Grouping with someone moves you to their layer, which is the usual way to switch if a zone is crowded or a quest mob is missing. Players and NPCs on other layers are invisible to you.", src = "classic", topic = "gaps" }
add{ q = { "is there cross faction", "can alliance and horde group", "play horde and alliance together", "cross faction forever", "can i talk to horde", "cross faction", "can horde and alliance play together", "cross faction grouping", "can i group with horde", "alliance and horde together", "talk to other faction", "can i play with my horde friend on alliance", "cross faction?" }, a = "No. Alliance and Horde can't share groups, guilds or raids, and they only meet as opponents in battlegrounds and world PvP. One exception for chat: Skyborne of both factions share a language, so they can talk to each other.", topic = "gaps" }
add{ q = { "how do i get a guild", "find a guild", "join guild", "guild recruitment", "how to find a guild forever", "guild", "how to join a guild", "looking for guild", "where to find guilds", "guild recruitment channel", "how to get invited to guild" }, a = "Ask in your capital's chat or the LookingForGroup channel, or check the official forums' guild recruitment sections. An officer then invites you. You can only join guilds on your own ruleset and faction. Press J for the Guild window once you're in. Guilds draw from the whole regional pool, since there are no realms.", topic = "gaps" }
add{ q = { "how do i find a group", "lfg", "looking for group", "group finder", "how to find dungeon group", "no group finder", "how to get a group", "find group", "group finder forever", "how to find group for dungeon", "lfg channel", "is there dungeon finder", "how to find people for dungeon" }, a = "Press I for the Looking For Group list: post your own listing or browse others after picking a playstyle (Learning, Relaxed, Competitive, Carry Offered). It doesn't auto-match or teleport you. You can also /join LookingForGroup and post there, or ask in zone chat.", topic = "gaps" }
add{ q = { "why isnt my kill counting for quest", "quest kills not counting", "quest not updating", "kill credit not working", "quest objective not counting", "in a raid group no quest credit", "why didnt i get credit", "quest progress not going up", "mobs not counting for quest", "killing the quest mobs but my quest isnt updating", "kills not counting quest" }, a = "Check:\n1. You or your party must have tagged the mob. A grey-tagged mob gives nothing.\n2. Raid groups don't get quest kill credit. Use a normal party of up to 5.\n3. You must be near the kill when it dies.\n4. It must be the exact mob named in the quest, since look-alikes often don't count.\n5. Some objectives need a quest item used on the mob first. Check the item in your bags or the tracker button.", topic = "gaps" }
add{ q = { "how do i use a quest item", "use quest item", "quest item button", "how to use item on mob", "quest says use the item", "right click quest item", "quest item use", "how to use the item for quest", "quest item not working", "use item on target", "quest item where to use" }, a = "Right-click the item in your bags, or click its button next to the quest in the tracker. Many quest items need a target (target the mob or object first) or a specific spot. Read the item tooltip, which says where or on what to use it.", src = "classic", topic = "gaps" }
add{ q = { "item starts a quest", "this item begins a quest", "how to start quest from item", "quest from drop", "what do i do with this quest item", "quest starting item", "how to start item quest", "item quest", "what do i do with item that starts quest" }, a = "Items whose tooltip says 'This Item Begins a Quest' start a quest when you right-click them in your bags. Accept it and it goes into your log like any other. If nothing happens, you may be too low level, already have it, or have already done it.", src = "classic", topic = "gaps" }
add{ q = { "cant turn in quest bags full", "quest reward bags full", "inventory full turn in", "cant complete quest no space", "bags full quest reward", "no room for quest reward", "inventory full cant turn in", "cant get quest reward", "quest wont complete bags full", "need bag space for quest" }, a = "You need a free bag slot for the reward, and sometimes one per item. Sell or destroy junk, then turn the quest in again. Your progress isn't lost.", src = "classic", topic = "gaps" }
add{ q = { "why cant i talk to npc", "npc wont talk to me", "npc is red", "npc attacking me", "cant interact with npc", "npc ignores me", "why is this npc hostile", "npc hostile", "cant talk to npc", "npc name red", "why wont npc talk", "npc wont open dialog", "unfriendly npc" }, a = "If the NPC's name is red, it's hostile to your faction or to you because of low reputation (Unfriendly or worse). Yellow is neutral and green is friendly. Raise rep with that faction first. Many factions, like Timbermaw and the Thorium Brotherhood, only talk to you at Neutral or better. Some NPCs are faction-only, for example Dalaran's NPCs are Alliance-only.", src = "classic", topic = "gaps" }
add{ q = { "are grey quests worth it", "should i do grey quests", "low level quests worth", "skip grey quests", "grey quest xp", "grey quests", "is it worth doing low level quests", "do grey quests give xp", "should i abandon grey quests", "grey quest worth doing" }, a = "Usually no for XP, since grey quests (5+ levels below you) lose 10-20% XP per extra level. Do them if they finish a chain, give a needed item or rep, or lead to an important follow-up. Otherwise abandon them to free your log.", topic = "gaps" }
add{ q = { "how to explore objective", "explore quest not completing", "discover location quest", "scout area quest not done", "explore objective", "explore quest", "scout quest not completing", "discover area not working", "explore not counting", "go to location quest not done" }, a = "Explore and scout objectives complete when you walk into the exact area, often the middle of a camp or a landmark. Check the map (M) for the shaded area and walk right through the middle. Discovering new subzones also gives small exploration XP.", src = "classic", topic = "gaps" }
add{ q = { "how do i stable my pet", "stable pet", "stable master", "where is stable master", "how to swap pets", "stable slots", "store my pet", "stable", "stable my pet", "stable master location", "swap pet", "buy stable slot", "i want to tame a new pet but keep my cat how", "how to stable pet" }, a = "Talk to any Stable Master (found by most innkeepers and in every city) and drag your pet into a stable slot. You can own 3 pets: one active and two stabled. Buy the extra slots from the Stable Master. Swap at any friendly one. Keep a slot free before you go out to tame.", class = "HUNTER", topic = "gaps" }
add{ q = { "how do i abandon my pet", "abandon pet", "get rid of pet", "release pet", "delete pet hunter", "abandon my pet", "how to release my pet", "get rid of my pet", "delete my pet", "how to abandon hunter pet" }, a = "Right-click your pet's portrait and choose Abandon (or use the pet frame menu). It's permanent, and the pet is gone. If you might want it later, stable it instead at a Stable Master.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "how do i rename my pet", "rename pet", "change pet name", "pet name", "name my pet", "pet rename", "can i rename pet", "how to change my pets name", "rename pet hunter", "change pet name twice" }, a = "Right-click your pet's portrait and choose Rename. Classic allows only one rename per pet, so pick carefully.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "turn off growl in dungeon", "pet growl dungeon", "pet taking aggro from tank", "disable growl", "pet stealing aggro", "how to stop pet taunting", "growl off", "autocast growl", "pet pulling aggro off tank", "turn off pet taunt", "growl in groups" }, a = "In groups with a real tank, right-click Growl on your pet bar to turn off autocast (the golden border disappears). Keep it on while soloing so the pet holds aggro. Also set the pet to Defensive or Passive in dungeons so it doesn't pull extra mobs.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "pet modes", "pet aggressive defensive passive", "how to stop pet attacking", "pet keeps pulling", "pet stance", "pet attack command", "how to make pet attack", "pet passive", "pet defensive", "pet aggressive", "pet keeps attacking", "pet attack button", "how to control pet" }, a = "Your pet bar has Aggressive (attacks anything nearby), Defensive (attacks what attacks you) and Passive (does nothing unless told). Use Defensive for normal play and Passive when you need it to stay out. Press the Attack button or a pet attack key to send it at your target, and Follow to call it back.", class = "HUNTER", src = "classic", topic = "gaps" }
add{ q = { "how to level a new pet", "new pet low level", "pet too low level", "level up pet fast", "pet xp", "pet behind my level", "level pet", "pet leveling", "pet xp share", "how does pet get xp", "does pet get quest xp", "new pet is low level", "my new pet is 10 levels lower than me how do i level it fast", "level pet fast" }, a = "Pets get 25% of the XP you earn from mobs green or higher, but no quest XP and no rested bonus. They stop gaining once they reach your level. To catch a pet up, grind mobs a few levels below you, and use it in dungeons. You can only tame beasts at your level or lower.", class = "HUNTER", topic = "gaps" }
add{ q = { "when do hunters get a pet", "hunter pet level", "how to get first pet", "hunter level 10 pet", "can i tame before 10", "hunter first pet", "when do i get pet", "what level hunter pet", "hunter pet at 10", "hunter tame level" }, a = "Hunters get Tame Beast at level 10 from the class trainer's taming quests: three practice tames with the Taming Rod, then Training the Beast, which unlocks Beast Training, Feed Pet and Revive Pet. Before 10 you fight alone with bow and melee.", class = "HUNTER", topic = "gaps" }
add{ q = { "how do i compare items", "compare gear", "is this an upgrade", "item comparison tooltip", "shift compare", "compare items", "item compare", "which item is better", "is this better", "compare tooltip" }, a = "Hover over an item and the tooltip shows your equipped item beside it, with green and red numbers for stat changes. Hold Shift if the comparison doesn't show. Check armor type, main stats and weapon skill, not just item color.", topic = "gaps" }
add{ q = { "how do i split a stack", "split stack", "unstack items", "take part of a stack", "shift click stack", "split", "split items", "how to split stacks", "divide stack", "split stack shift" }, a = "Shift-click a stack in your bags and type how many you want to split off, then place them in an empty slot.", src = "classic", topic = "gaps" }
add{ q = { "how do i delete a character", "delete character", "remove character", "how to delete alt", "delete char", "how to delete my character", "remove a character", "delete my alt", "can i restore deleted character", "delete character forever" }, a = "At character select, choose the character and click Delete Character. Type DELETE to confirm. The deletion is permanent unless Blizzard's restore service applies, so empty its bags and mail first.", src = "classic", topic = "gaps" }
add{ q = { "how to see coordinates", "coords on map", "map coordinates", "how to find coordinates", "/way command", "tomtom forever", "how do i use coords", "coordinates", "coords", "where are coords", "how to see coords forever", "coords addon", "waypoint" }, a = "Coordinates are X, Y on the zone map, from 0-100. If your map doesn't show them, add an addon that does (Leatrix Maps, TomTom or Questie). /way x y works only with TomTom (or an addon that supports it) installed, and it puts a waypoint arrow on screen.", src = "classic", topic = "gaps" }
add{ q = { "how to find a trainer", "where is my class trainer", "find trainer in city", "ask guard", "where is the mage trainer", "cant find trainer", "trainer", "find class trainer", "where are trainers", "guard directions", "how to find npc in city", "trainer location" }, a = "Ask any city guard: right-click them and choose the trainer or service, and you get a map flag. Starting areas have class and profession trainers near the first quest hub, and in Forever profession trainers sit in the starting zones too. Class trainers are usually grouped in a city district, such as Stormwind's Mage Quarter or Orgrimmar's Cleft of Shadow.", topic = "gaps" }
add{ q = { "what level can i learn professions", "when can i get professions", "profession level requirement", "learn profession at level 1", "where to learn professions starting zone", "when can i learn professions", "profession levels", "profession tiers", "journeyman level", "artisan level requirement", "expert level professions" }, a = "Gathering professions can be learned at level 1, and crafting and secondary professions at level 5. In Forever every starting zone has profession trainers. Tiers: Apprentice (cap 75), Journeyman (level 10, skill 50, cap 150), Expert (level 20, skill 125, cap 225), Artisan (level 35, skill 200, cap 300).", topic = "gaps" }
add{ q = { "what is fatigue", "fatigue bar", "swimming fatigue", "deep water fatigue", "dying in the ocean", "fatigue", "swim fatigue", "ocean fatigue", "why am i dying in water", "yellow bar swimming", "exhaustion bar" }, a = "The yellow Fatigue bar appears when you swim too far into open ocean. When it empties you start taking heavy damage and die quickly. Turn back toward land until it refills.", src = "classic", topic = "gaps" }
add{ q = { "fall damage", "how to avoid fall damage", "slow fall", "jumping off cliffs", "levitate", "falling damage", "fall damage forever", "how to not die from falling", "skyborne slow fall", "died from falling", "safe fall" }, a = "Long falls deal damage based on height and can kill you. Slow Fall (Mage), Levitate (Priest) and the Skyborne Walk on Air racial (steerable slow fall, 90s cooldown) prevent it. Landing in water also prevents it.", src = "classic", topic = "gaps" }
add{ q = { "durability", "what is durability", "gear breaking", "repair cost", "why is my repair bill high", "durability loss", "why is my gear yellow", "gear durability", "why is repair expensive", "death durability" }, a = "Gear loses durability when you die (and slowly in combat), and repairs cost more at higher levels. Yellow gear is low and red gear is broken and gives no stats. Repair at any vendor with an anvil icon. Spirit-healer resurrections cost extra durability, so run back to your corpse when you can.", topic = "gaps" }
add{ q = { "how to repair", "where to repair", "repair gear", "find a repair vendor", "repair all", "repair", "repair gear where", "repair vendor", "anvil vendor", "how do i repair my armor", "repair all button" }, a = "Talk to any vendor with an anvil icon (weapon, armor, blacksmith and many general vendors) and click Repair All in their window. Engineers can also place a Repair Bot at a camp from skill 140.", topic = "gaps" }
add{ q = { "what is a world buff", "world buffs forever", "do world buffs work in raids", "onyx head buff", "songflower", "rend buff forever", "world buff", "world buffs", "ony buff", "dragonslayer buff", "warchief's blessing forever", "wbuffs", "do world buffs work in raids forever", "world buff in dungeon" }, a = "World buffs (Onyxia's Rallying Cry, Warchief's Blessing, Songflower and so on) still exist, but Forever removes them when you enter a dungeon or raid. They only help in the open world.", topic = "gaps" }
add{ q = { "what is the level cap", "max level", "level cap forever", "will level cap go up", "is 60 max", "level cap", "max level forever", "is the cap 60", "will they raise level cap", "highest level", "level 70 forever" }, a = "60 is the cap, and Blizzard says it stays 60 permanently. Power grows through new gear, raids and Legacy instead of levels. There are no expansions in Forever.", topic = "gaps" }
add{ q = { "what professions should i take", "which profession first", "best profession for beginner", "profession choice", "best professions gold", "what profession to pick", "professions", "best profession", "best professions forever", "which professions to pick", "best profession combo", "profession for new player" }, a = "For a first character: Herbalism + Mining (or Skinning) make the most gold while leveling. Later, swap one for a crafting profession that suits your class (Engineering for PvP, Alchemy for raid consumables, Tailoring for cloth classes, Leatherworking for leather/mail, Blacksmithing for plate). Always take First Aid, Cooking and Fishing too.", topic = "gaps" }
add{ q = { "how do i set up action bars", "more action bars", "enable extra action bars", "action bar 2", "how to add bars", "where are my other bars", "action bars", "add action bars", "extra bars", "show more action bars", "right side action bars", "action bar settings" }, a = "Esc > Options > Action Bars: tick the extra bars to show them (bottom left/right and right-side bars). Then move or resize them in Edit Mode (Esc > Edit Mode). Bind keys with Quick Keybind mode in Options > Keybindings.", topic = "gaps" }
add{ q = { "what does well fed do", "well fed buff", "food buff xp", "eat food for xp", "cooking buff", "well fed", "food buff", "xp food", "buff food leveling", "does food give xp forever", "well fed xp bonus" }, a = "Crafted Cooking food gives Well Fed, which in Forever adds +5% kill XP for about 15 minutes along with its stats (lost on death). It stacks with camp buffs and the Cozy Sleeping Bag, so eat one whenever you level.", topic = "gaps" }
add{ q = { "how do i get legacy points", "legacy points how to get", "where do legacy points come from", "first legacy point", "how to earn legacy", "legacy challenges list", "how many legacy points", "legacy points", "how do i get my first legacy point", "legacy point how" }, a = "Legacy Points are account-wide and come from challenges: each class reaching 25, 45 and 60; crafting professions at 150, 225 and 300; PvP ranks and season tasks; dungeon 'Spelunker' clears; raid clears; and Explore Azeroth. Spend them per character in the Legacy window (Y). Your first point usually comes from level 25 or 150 in a crafting profession.", topic = "gaps" }
add{ q = { "where do i spend talent points", "how to use talent points", "talent window", "how to put points in talents", "talents not working", "talent points", "spend talents", "talents", "where are talents", "n key talents", "how do talents work" }, a = "Press N to open Talents, click a talent to put a point in, then confirm or apply. Points start at 10 (earlier with the Legacy Talented node). Each row needs 5 more points spent in that tree. Change them later at your class trainer.", src = "classic", topic = "gaps" }
add{ q = { "how do i get dual spec", "dual spec", "second spec", "when can i dual spec", "dual spec cost", "two specs", "dual specialization", "dual spec level", "switch spec", "how to swap spec", "dual spec trainer", "dual talent" }, a = "Dual Talent Specialization comes from your class trainer at level 40 for 50g. You can then swap between two talent builds out of combat (not in battlegrounds). Each spec has its own respec fee.", topic = "gaps" }
add{ q = { "how do i get to the next zone after starting zone alliance", "human after elwynn", "dwarf after dun morogh", "night elf after teldrassil", "where to go after northshire", "alliance where to go at 10", "gnome after dun morogh", "where to go after elwynn", "night elf where to level after 10", "after goldshire where" }, a = "Alliance next zones at about 10: Humans go to Westfall (west of Elwynn), Dwarves and Gnomes go to Loch Modan (east through the Dun Morogh tunnel), Night Elves go to Darkshore (boat from Rut'theran to Auberdine). Alliance Skyborne reach Dalaran at about 12; take the portal to Stormwind and quest in Westfall or Darkshore.", topic = "gaps" }
add{ q = { "how do i get to the next zone after starting zone horde", "orc after durotar", "undead after tirisfal", "tauren after mulgore", "troll after durotar", "where to go after valley of trials", "horde where to go at 10", "where to go after durotar", "undead where to level after 10", "after brill where", "tauren where to go at 10" }, a = "Horde next zones at about 10: Orcs and Trolls go to The Barrens (west of Durotar, Crossroads hub). Undead go to Silverpine Forest (south of Tirisfal) or take the zeppelin to the Barrens. Tauren go to The Barrens (northeast from Mulgore). Horde Skyborne land at Skywatcher Plateau in Mulgore and can head straight for the Barrens.", topic = "gaps" }
add{ q = { "how do i know what spells to train", "which spell ranks to buy", "skip spell ranks", "save gold on training", "do i need every rank", "which spells to train", "spell ranks worth it", "do i need to train every spell", "save money training", "skip ranks", "what to train" }, a = "Train your main damage, heal and utility spells every time, but skip ranks of spells you rarely use to save gold. Training everything from 1 to 60 costs about 206-207g for every class in Forever. Learned ranks replace the old rank on your bars automatically.", topic = "gaps" }
add{ q = { "what is the hit cap", "hit cap", "how much hit do i need", "hit cap pve", "spell hit cap", "melee hit cap forever", "hit cap raid", "hit cap boss", "spell hit cap forever", "hit needed", "how much hit for raids" }, a = "Forever hit caps with maxed weapon skill: specials and ranged 5% vs same level and 8% vs raid bosses; spells 4% vs same level and 17% vs raid bosses; dual-wield auto attacks need about 24% vs same level. Hit is one stat for melee, ranged and spells.", topic = "gaps" }
add{ q = { "do i need to eat and drink", "how to eat", "how to drink water", "regen health outside combat", "sit to regen", "eat and drink at same time", "eat", "drink", "how do i regen", "how to heal out of combat", "food and water", "eating" }, a = "Right-click food or drink in your bags (or put them on your bar) out of combat. You sit and regenerate over about 20-30 seconds, and moving cancels it. You can eat and drink at the same time. Buy the highest level food and water you can use from innkeepers or food vendors.", topic = "gaps" }
add{ q = { "how do i turn on quest markers", "quest markers on map", "quest objective areas on map", "map not showing quests", "turn on quest blobs", "quest poi", "enable quest markers forever", "no quest areas on map classic preset" }, a = "Quest markers and objective areas come with the Enhanced preset. If you picked Classic, turn them on with Esc > Options (search 'quest') and enable the quest marker and objective area options. The map (M) and minimap then shade where to go. Questie adds similar markers if you prefer an addon.", topic = "gaps" }
add{ q = { "can i change my preset", "switch classic to enhanced", "change experience preset", "picked wrong preset", "enhanced or classic preset", "reset preset", "change preset", "preset", "classic preset vs enhanced", "switch preset", "enhanced preset", "classic preset" }, a = "The preset screen appears only once, at first login, but every setting it changes can be switched later in Esc > Options: HD/SD models, quest markers and objective areas, one-bag mode, transmog, strafe or turn keys and UI layout. Blizzard suggests Enhanced if you're unsure.", topic = "gaps" }
add{ q = { "how do i find herbs on minimap", "track herbs", "find minerals", "minimap tracking", "track ore nodes", "how to see nodes on map", "find herbs not showing", "find herbs", "tracking", "herbs not on minimap", "ore not showing on minimap", "track herbs and ore" }, a = "After you learn Herbalism or Mining, click the tracking (magnifying glass) button on the minimap and pick Find Herbs or Find Minerals. Only one gathering track is active at a time. Nodes then show as yellow dots on the minimap. The same menu can track trainers, vendors and other services in towns.", src = "classic", topic = "gaps" }
add{ q = { "where do i turn in quest", "where to hand in quest", "quest complete where to go", "turn in location", "who do i turn this in to", "turn in quest", "hand in quest", "quest turn in", "where do i return the quest", "question mark npc", "quest done where to go" }, a = "A finished quest shows a yellow ? over the NPC who takes it; often it's the NPC who gave it, but not always. Open the quest log (L) and read the last line ('Return to X in Y'). With quest markers on, the map shows the turn-in spot.", topic = "gaps" }
add{ q = { "how do i find quests", "where are quests", "no quests left", "run out of quests", "where do i get quests", "out of quests what now", "find quests", "where are the quests", "no more quests", "quests near me", "cant find any quests", "where to find quests" }, a = "Look for yellow ! over NPCs in towns and camps, and check every new hub's inn and notice boards. If you've run out, move to the next zone for your level (ask 'what zone should I go to'), do dungeon quests, or turn on low-level quests in Options to find ones you skipped. Forever added over 1,000 quests, so most zones have new hubs.", topic = "gaps" }
add{ q = { "what is first aid", "how to learn first aid", "first aid trainer", "bandages", "how to make bandages", "should i get first aid", "first aid", "bandage", "how to make linen bandage", "where is first aid trainer", "first aid worth it", "learn first aid" }, a = "First Aid is a secondary profession, so it doesn't use a primary slot. Every class should take it, because bandages cut downtime without using mana. Learn it from a First Aid trainer in any city or starting area, then make Linen Bandages from Linen Cloth and work up through wool, silk, mageweave and runecloth.", topic = "gaps" }
add{ q = { "what happens at level 25", "level 25 legacy", "legacy unlock", "when does legacy unlock", "first legacy point at 25", "level 25", "25 legacy point", "what do i get at 25", "legacy at 25", "first legacy point level 25" }, a = "Around 25 most players earn their first Legacy Point, because reaching 25 on a class is a Legacy challenge (45 and 60 are too). Open Legacy with Y and spend the point in the Adventure, Professions or Resourcefulness tree. Points are account-wide.", topic = "gaps" }
add{ q = { "how do i get to dalaran", "where is dalaran", "dalaran forever", "can horde go to dalaran", "dalaran location", "dalaran", "get to dalaran", "dalaran alterac", "dalaran portal", "how to reach dalaran", "dalaran alliance only" }, a = "Forever's Dalaran is in the Alterac Mountains, and it's Alliance-only (Horde can't use its NPCs). Reach it from Southshore/Hillsbrad by road, fly to its flight master once discovered, or take the skyboat from Valanaar on Zephras Isle. Dalaran has a portal to Stormwind.", topic = "gaps" }
add{ q = { "when is wow forever set", "forever timeline", "is forever after frozen throne", "what year is forever lore", "is forever same timeline as retail", "when does forever take place", "forever lore timeline", "what year is wow forever set in", "is forever before or after the frozen throne", "is forever its own timeline separate from retail", "where does forever fit in warcraft lore", "forever set after wc3?" }, a = "Forever is set in year 25 ADP, the first year of the original WoW world. It picks up after the Warcraft III: Reforged campaign Forsaken Kingdom (the founding of the Undercity) and before Ragnaros wakes in Molten Core and before The Burning Crusade. It is its own branch: it starts like vanilla but some stories go differently and new ones are added. Outland is not planned.", topic = "lore_bosses" }
add{ q = { "what is forsaken kingdom", "forsaken kingdom story", "warcraft 3 forsaken kingdom wow forever", "how was undercity made", "forsaken kingdom?", "what is the forsaken kingdom story", "how did the undercity get made in forever", "is forever based on the forsaken kingdom from warcraft 3", "forsaken kingdom lore explained", "i heard forever uses the wc3 forsaken kingdom campaign whats that", "undercity origin forever" }, a = "Forsaken Kingdom is a 2026 Warcraft III: Reforged expansion that bridges WC3 and Forever. It covers the years after Arthas leaves Lordaeron: a Lordaeron guard lieutenant who becomes Forsaken helps found the Undercity, with new heroes Garek Bandarion and Dark Ranger Anya alongside Sylvanas, Varimathras, Putress, Whitemane and Renault Mograine. It also introduced the Forsaken Paladin hero.", topic = "lore_bosses" }
add{ q = { "does forever change lore", "is the story different in forever", "forever new story", "will vanilla stories play out the same in forever", "does forever change the lore", "is the story different from classic", "new story in forever?", "do the vanilla quest stories play out the same", "how much of the classic lore did forever change", "is forever just classic lore or a new story", "forever lore changes" }, a = "Forever keeps the established history (Arthas still culled Stratholme and became the Lich King) but does not follow vanilla beat for beat. Blizzard says some known vanilla stories won't happen the same way, and it adds new characters, zones, dungeons and storylines, often finishing threads vanilla left hanging (like Alcaz Island). The Skyborne have their own story rather than driving the world's.", topic = "lore_bosses" }
add{ q = { "who are the skyborne", "skyborne lore", "what are shen'dorei", "skyborne origin", "are skyborne high elves", "where do the skyborne come from", "what are the shendorei exactly", "are skyborne high elves or night elves", "tell me the lore behind the skyborne race", "i just made a skyborne what is their backstory", "skyborne race history" }, a = "The Skyborne (shen'dorei, the hidden people) are high elves descended from the people of Eldre'Thalas (today's Dire Maul). Fleeing Prince Tortheldrin's persecution, they made a pact with the wind spirits of Skywall, who lifted Zephras Isle into the Elemental Plane of Air. They lived there for millennia; now the wind spirits are gone, the islands drift apart and their pylons are failing. Forever-only lore.", topic = "lore_bosses" }
add{ q = { "windshapers vs high order", "which skyborne faction is horde", "skyborne factions", "who leads the high order", "who leads the windshapers", "high order or windshapers which is alliance", "why are some skyborne horde and some alliance", "who is the leader of the windshapers", "who is the leader of the high order", "my skyborne joined the horde which skyborne faction is that", "skyborne split explained" }, a = "Windshapers (Horde) are shaman-minded descendants of the ordinary kaldorei citizens, led by Ayessa Dawnsinger; they joined the Horde through the Earthen Ring. High Order (Alliance) are descendants of Highborne magisters chasing lost arcane knowledge, led by Elaadrin Evengale; they joined the Alliance through the Kirin Tor. Alliance Skyborne can be mages, Horde Skyborne shamans; both can be druid, hunter, rogue, warrior.", topic = "lore_bosses" }
add{ q = { "who is talaanis shadowsong", "talaanis", "high elder zephras isle", "whos talaanis", "talaanis shadowsong who is she", "who is the high elder on zephras isle", "talaanis shadowsong lore", "is talaanis related to maiev or jarod shadowsong", "tell me about talaanis shadowsong", "talaanis skyborne" }, a = "Talaanis Shadowsong is the High Elder of Zephras Isle, the senior Skyborne leader. At the end of the Zephras Isle campaign you speak with her after turning in to your faction leader, before leaving the island from the Valanaar skydocks.", topic = "lore_bosses" }
add{ q = { "who is rohash", "rohash lord of the east wind", "zephras isle final boss", "who is al'akir skyborne", "whos rohash", "rohash lore", "who is the zephras isle final boss", "rohash lord of the east wind who is he", "is rohash connected to al'akir", "tell me about rohash the wind lord", "rohash skyborne" }, a = "Rohash, Lord of the East Wind, is a member of Al'Akir's Conclave of Wind. He told the Skyborne that the Windlord's judgment was coming and is the final fight of the Zephras Isle campaign, when Alliance and Horde reinforcements arrive. Al'Akir is the elemental lord of air; a hostile Skyborne cult, the Al'Aketh (High Priestess Lorthuna, Skypriest Faladiel), worships him.", topic = "lore_bosses" }
add{ q = { "who is shal'nan", "skyborne first leader", "who is luminarian", "skyborne notable npcs", "whos shal'nan", "who was luminarian", "who was the first leader of the skyborne", "important skyborne npcs to know", "what happened to shal'nan", "tell me about the skyborne leaders shal'nan and luminarian", "skyborne big names" }, a = "Shal'nan was the first leader of the Skyborne, who led the rebellion that got them out of Eldre'Thalas; he is missing. Luminarian was a legendary Skyborne magesmith, now dead. Other names you'll meet: Valennia Stormfist (ex-captain of the Empyrean Blades), the Nightclaw Druids of Shadowgale Forest, and Ansirem Runeweaver and Muln Earthfury, who led the Kirin Tor and Earthen Ring help against the cult.", topic = "lore_bosses" }
add{ q = { "undead paladin lore", "how can forsaken be paladins", "forsaken paladin story", "unbowed story", "who is cormack", "undead paladins?", "how can undead use the light", "who is cormack in the forsaken paladin story", "what is the unbowed", "lore for forsaken paladins in forever", "how does a forsaken become a paladin in the forever story", "undead pally backstory" }, a = "Forever's short story Unbowed explains it: Cormack, a Scarlet crusader killed by his own comrade Arec Mistmantle, comes back as Forsaken. The Light burns him each time he uses it until he stops fighting it; then it heals him. Danitha, a Forsaken who also wields the Light, gives him back his father Gavinrad's hammer and recruits him. Blizzard hasn't said the burning has any gameplay effect.", class = "PALADIN", topic = "lore_bosses" }
add{ q = { "who are the tarnished", "tarnished paladins tirisfal", "rudolph gelhardt", "danitha morr", "bandarion keep quests", "tarnished paladins", "who is rudolph gelhardt", "who is danitha morr", "bandarion keep story", "tell me about the tarnished paladins in tirisfal", "tarnished lore" }, a = "The Tarnished are rogue Forsaken paladins in Tirisfal Glades who kept their living prejudices and attack other Forsaken. Leader Commander Rudolph Gelhardt is upstairs in the farmhouse at Shadowvale, southwest of the lake. The quests start with Danitha Morr at Bandarion Keep; you stop them to protect the new Forsaken paladin order.", class = "PALADIN", topic = "lore_bosses" }
add{ q = { "who is onyxia", "onyxia lore", "is lady prestor onyxia", "who is katrana prestor", "whos onyxia", "is lady katrana prestor actually onyxia", "onyxia backstory", "what is onyxia doing in stormwind", "tell me about onyxia the black dragon and her disguise", "why is onyxia pretending to be a noble in stormwind", "onyxia daughter of deathwing" }, a = "Onyxia is a black dragon, daughter of Deathwing. In Stormwind she poses as Lady Katrana Prestor, a noblewoman advising the regency while King Varian is missing, steering the kingdom toward ruin. The attunement questlines unmask her, and you kill her in Onyxia's Lair in Dustwallow Marsh's Wyrmbog (40-player in Forever, opens Dec 9, 2026). Her head turned in gives a world buff, but Forever removes world buffs inside instances.", topic = "lore_bosses" }
add{ q = { "who is varian wrynn", "where is king varian", "is varian in alcaz prison", "varian alcaz forever", "where is the king of stormwind", "where is varian", "what happened to king varian", "is varian locked up in alcaz prison", "varian wrynn lore", "who is varian wrynn and why is he missing", "where is the king of stormwind in forever and can i free him", "varian missing story" }, a = "Varian Wrynn is the missing King of Stormwind; he vanished on his way to a peace summit at Theramore, kidnapped through the Defias with Onyxia (Lady Prestor) behind it. In Forever, Alcaz Prison was rumored to hold him, but he is not actually in the dungeon: a note found after killing Zarla Ober/Blazeroar explains why he isn't there and raises new questions. Alliance start: Our Man in Theramore from Mathias Shaw in Stormwind.", topic = "lore_bosses" }
add{ q = { "who rules stormwind", "who is bolvar fordragon", "who is anduin", "boy king stormwind", "bolvar", "who is in charge of stormwind", "who is bolvar", "why is anduin a boy king", "who runs stormwind with varian gone", "bolvar fordragon lore", "who is actually running stormwind in forever while the king is missing", "stormwind regent" }, a = "With Varian missing, young Prince Anduin Wrynn is the nominal child king in Stormwind Keep. Highlord Bolvar Fordragon, a paladin and Varian's friend, runs the kingdom as regent, with Lady Katrana Prestor (secretly Onyxia) at his side. Both stand in the throne room of Stormwind Keep, and Bolvar plays a part in the Alliance Onyxia attunement. Classic baseline; Forever hasn't changed this setup as far as is known.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is arthas", "arthas lore", "is arthas in forever", "lich king forever", "where is arthas", "whos arthas", "where is arthas now", "is arthas the lich king in forever", "arthas menethil backstory", "tell me about arthas and what he did", "will we ever fight arthas in forever", "arthas story" }, a = "Arthas Menethil was the crown prince of Lordaeron. He purged Stratholme, took the cursed blade Frostmourne in Northrend, killed his father King Terenas and led the Scourge through Lordaeron, then merged with Ner'zhul to become the Lich King on the Frozen Throne in Icecrown. In Forever's year 25 ADP he rules from Northrend; Northrend is not in the game and Blizzard hasn't announced him as content.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is thrall", "thrall lore", "where is thrall", "warchief of the horde", "whos thrall", "who is the warchief of the horde", "thrall backstory", "where do i find thrall", "tell me about thrall and how he freed the orcs", "where can i find thrall in orgrimmar", "thrall story" }, a = "Thrall is Warchief of the Horde, son of Durotan of the Frostwolf clan. Raised as a slave and gladiator in Durnholde, he freed the interned orcs, led the Horde to Kalimdor and founded Orgrimmar in Durotar. He stands in Grommash Hold in Orgrimmar's Valley of Wisdom and gives quests such as part of the Horde Onyxia attunement and Hidden Enemies (Ragefire Chasm).", src = "classic", topic = "lore_bosses" }
add{ q = { "who is jaina", "jaina proudmoore", "where is jaina", "theramore leader", "whos jaina", "who leads theramore", "jaina proudmoore backstory", "where do i find jaina", "tell me about jaina proudmoore and theramore", "where can i find jaina in dustwallow marsh", "jaina story" }, a = "Jaina Proudmoore is a powerful archmage, once Arthas's companion, who led human refugees to Kalimdor and fought beside Thrall at Mount Hyjal. She rules Theramore Isle in Dustwallow Marsh from Foothold Citadel. Her father, Admiral Daelin Proudmoore, attacked the Horde and was killed by them, which strains her standing with some humans. Classic baseline; her role in Forever's new stories isn't confirmed.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is ragnaros", "ragnaros lore", "is molten core in forever", "when is ragnaros", "whos ragnaros", "where is ragnaros", "ragnaros backstory", "when can we fight rag", "tell me about ragnaros the firelord", "is ragnaros in forever or is molten core not out yet", "rag story" }, a = "Ragnaros the Firelord is the elemental lord of fire. Dark Iron sorcerer-thane Thaurissan summoned him about 300 years ago during the War of the Three Hammers, which created the Searing Gorge and Burning Steppes. He rules the Molten Core beneath Blackrock Mountain and is its final boss. In Forever the story sits before he stirs, and Molten Core exists in the data but has no release date.", topic = "lore_bosses" }
add{ q = { "who is nefarian", "victor nefarius", "nefarian lore", "blackwing lair forever", "whos nefarian", "is victor nefarius nefarian", "nefarian backstory", "where is nefarian", "tell me about nefarian and blackwing lair", "is victor nefarius the same guy as nefarian", "nef story" }, a = "Nefarian is Deathwing's son and Onyxia's brother. In human form he is Lord Victor Nefarius, master of Blackrock Spire, controlling the Dark Horde under Rend Blackhand and breeding chromatic dragons. He is at war with Ragnaros's Dark Irons below and is the final boss of Blackwing Lair. BWL has no Forever release date yet.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is illidan", "illidan lore", "illidan barrow deeps", "is illidan in forever", "whos illidan", "illidan backstory", "where is illidan", "does illidan show up in forever", "tell me about illidan stormrage", "is illidan connected to the barrow deeps raid somehow", "illidan story" }, a = "Illidan Stormrage, Malfurion's twin, made a second Well of Eternity on Mount Hyjal after the War of the Ancients and was locked in the barrow dens under Hyjal for 10,000 years, watched by Maiev Shadowsong's wardens. Tyrande freed him in Warcraft III. That prison is Forever's Barrow Deeps raid. Illidan himself is believed to be in Outland and isn't in Forever.", topic = "lore_bosses" }
add{ q = { "who is tyrande", "tyrande whisperwind", "night elf leader", "where is tyrande", "whos tyrande", "who leads the night elves", "tyrande backstory", "where do i find tyrande", "tell me about tyrande whisperwind", "where can i find tyrande in darnassus", "tyrande story", "i keep hearing about tyrande in darnassus who is she and what does she do" }, a = "Tyrande Whisperwind is High Priestess of Elune and leader of the night elves. She commands the Sentinels and is found in the Temple of the Moon in Darnassus on Teldrassil. She freed Illidan in Warcraft III and fought at the Battle of Mount Hyjal.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is malfurion", "malfurion stormrage", "where is malfurion", "archdruid malfurion", "whos malfurion", "malfurion backstory", "is malfurion stuck in the emerald dream", "tell me about malfurion stormrage", "is malfurion in forever or still asleep in the dream", "malfurion story" }, a = "Malfurion Stormrage is the first night elf druid, Tyrande's beloved and Illidan's twin. He helped defeat Archimonde at Hyjal and afterward sealed Hyjal and Nordrassil behind dense foliage so the World Tree could heal. In the vanilla era his spirit is in the Emerald Dream and he isn't a normal NPC; Keeper Remulos in Moonglade speaks for the druids.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is sylvanas", "sylvanas windrunner", "banshee queen", "where is sylvanas", "whos sylvanas", "who leads the forsaken", "sylvanas backstory", "where do i find sylvanas", "tell me about sylvanas windrunner", "where can i find sylvanas in the undercity", "sylvanas story" }, a = "Lady Sylvanas Windrunner, the Banshee Queen, was Ranger-General of Silvermoon until Arthas killed her and raised her as a banshee. She broke free, took Lordaeron's ruined capital and founded the Forsaken, shown in Warcraft III: Forsaken Kingdom. She rules from the Royal Quarter of the Undercity with dreadlord Varimathras beside her. Her revenge on Arthas is unfinished in Forever.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is cairne", "cairne bloodhoof", "tauren leader", "where is cairne", "whos cairne", "cairne lore", "who leads the tauren", "tell me about cairne bloodhoof", "where can i find cairne in thunder bluff", "tauren chieftain" }, a = "Cairne Bloodhoof is High Chieftain of the tauren and Thrall's closest ally. He united the tauren tribes, brought them into the Horde and built Thunder Bluff in Mulgore, where he sits on the top of the central rise. His son is Baine.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is magni", "magni bronzebeard", "king of ironforge", "where is magni", "whos magni", "who leads ironforge", "magni backstory", "where do i find magni", "tell me about magni bronzebeard", "where can i find magni in ironforge", "magni story", "who is the dwarf king in ironforge and what is his story" }, a = "Magni Bronzebeard is King of Ironforge, head of the Bronzebeard clan. Brothers: Muradin (lost in Northrend) and Brann (explorer). His daughter Moira married the Dark Iron emperor Dagran Thaurissan and is in Blackrock Depths. He sits at the High Seat in Ironforge; in Forever the Hall of Thanes dungeon entrance is reached from his hall.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is anduin", "anduin wrynn", "prince of stormwind", "whos anduin", "where is anduin", "anduin backstory", "is anduin the king", "tell me about anduin wrynn", "why is anduin on the throne of stormwind", "anduin story" }, a = "Anduin Wrynn is Varian's young son, crowned as child king while his father is missing. He's a boy and doesn't rule in practice; Highlord Bolvar runs the kingdom with Lady Prestor. You find him in Stormwind Keep's throne room. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is kel'thuzad", "kelthuzad", "kt lore", "naxxramas forever", "whos kel'thuzad", "kelthuzad backstory", "where is kelthuzad", "is kt in naxxramas", "tell me about kel'thuzad", "is kel'thuzad going to be in naxx in forever", "kt story" }, a = "Kel'Thuzad was a Dalaran archmage who turned to necromancy, founded the Cult of the Damned and spread the plague for the Lich King. Arthas killed him and later raised him as a lich at the Sunwell. He commands the Scourge from the floating necropolis Naxxramas over the Eastern Plaguelands and is its final boss. Naxx has no Forever date.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is hakkar", "hakkar the soulflayer", "blood god", "hakkar sunken temple", "whos hakkar", "hakkar backstory", "where is hakkar", "the blood god hakkar", "tell me about hakkar the soulflayer", "is hakkar in the sunken temple or zul'gurub", "hakkar story" }, a = "Hakkar the Soulflayer is the Gurubashi trolls' blood god. The Atal'ai priests tried to summon him, so the green dragons sank their temple: that's the Sunken Temple in Swamp of Sorrows, where you fight the Avatar of Hakkar. His full return happens in Zul'Gurub (Stranglethorn), which isn't a Forever launch raid.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is c'thun", "cthun", "old god ahn'qiraj", "what is c'thun", "whos c'thun", "cthun backstory", "where is cthun", "is cthun in forever", "tell me about cthun the old god", "will we fight cthun in ahn'qiraj in forever", "cthun story" }, a = "C'Thun is an Old God imprisoned beneath Ahn'Qiraj in Silithus, master of the insectoid Qiraji and their emperors Vek'lor and Vek'nilash. The Cenarion Circle and Brood of Nozdormu keep the Scarab Wall sealed. In Classic he's the final boss of the 40-player Temple of Ahn'Qiraj; AQ has no Forever date.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is tirion fordring", "tirion", "where is tirion", "in dreams quest", "whos tirion", "tirion backstory", "where do i find tirion", "why was tirion exiled", "tell me about tirion fordring", "where can i find tirion in the plaguelands", "tirion story" }, a = "Tirion Fordring was a Silver Hand paladin stripped of his title for defending the orc Eitrigg. He lives as a hermit in a hut by a pond in western Eastern Plaguelands. His son Taelan leads the Scarlet garrison at Hearthglen; the chain ends with In Dreams, which rewards Mark of Fordring. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is van cleef", "edwin vancleef", "defias leader", "vancleef lore", "who is vancleef", "whos vancleef", "why did vancleef start the defias", "vancleef backstory", "why is vancleef mad at stormwind", "tell me about edwin vancleef", "why did vancleef and the stonemasons turn on stormwind", "vancleef story" }, a = "Edwin VanCleef was master of the Stonemasons' Guild that rebuilt Stormwind after the Second War. The House of Nobles refused to pay, the masons rioted, and he fled to found the Defias Brotherhood, based in the Deadmines under Moonbrook in Westfall. He's the Deadmines' final boss aboard the juggernaut ship. Forever keeps the Deadmines layout and boss order, but bosses hit harder and loot changed.", topic = "lore_bosses" }
add{ q = { "who is hogger", "where is hogger", "wanted hogger", "hogger elwynn", "whos hogger", "where does hogger spawn", "hogger backstory", "how do i kill hogger", "tell me about hogger", "where does hogger spawn in elwynn forest", "hogger story", "who is hogger and why is there a wanted poster for him in goldshire" }, a = "Hogger is a giant gnoll elite of the Riverpaw pack in southwest Elwynn Forest, roaming around Forest's Edge near the Westfall border. The Wanted: Hogger poster in Goldshire sends you to kill him; turn in his claw to Marshal Dughan in Goldshire. At level 11 elite, bring a friend. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is rend blackhand", "warchief rend", "dark horde", "whos rend", "rend blackhand backstory", "what is the dark horde", "where is rend", "tell me about rend blackhand", "why does rend call himself warchief", "rend story", "who is rend blackhand and why is he in blackrock spire" }, a = "Rend Blackhand is the Dark Horde's warchief, son of Blackhand. He refused Thrall's leadership and serves Nefarian in Upper Blackrock Spire. You fight him in the Rend gauntlet event, riding Gyth after waves of adds. Felstriker is one of his notable drops.", topic = "lore_bosses" }
add{ q = { "who is drakkisath", "general drakkisath", "ubrs last boss", "whos drakkisath", "general drakkisath backstory", "where is drakkisath", "who does drakkisath serve", "tell me about general drakkisath", "is drakkisath the last boss of ubrs", "drakkisath story", "who is general drakkisath and why is he guarding the top of ubrs" }, a = "General Drakkisath is a black dragonspawn commanding Nefarian's forces in Upper Blackrock Spire and its final boss. Two Chromatic Elite Guards protect him. Killing him is part of the Onyxia attunement (Blood of the Black Dragon Champion) and a step toward Blackwing Lair.", topic = "lore_bosses" }
add{ q = { "who is thaurissan", "emperor thaurissan", "dagran thaurissan", "who is moira", "whos thaurissan", "thaurissan backstory", "why is moira with the dark irons", "where is thaurissan", "tell me about emperor dagran thaurissan", "why is princess moira married to the dark iron emperor", "moira story" }, a = "Emperor Dagran Thaurissan rules the Dark Iron dwarves from Shadowforge City in Blackrock Depths and serves Ragnaros. He married Magni's daughter Princess Moira Bronzebeard, who is at his side as an optional boss. He drops Hand of Justice and Ironfoe in Classic. Tank him away from the group; if you keep Moira alive, off-tank and interrupt her.", topic = "lore_bosses" }
add{ q = { "who is baron rivendare", "baron rivendare", "baron run", "whos baron rivendare", "baron rivendare backstory", "where is the baron", "is baron rivendare a death knight", "tell me about baron rivendare", "is baron rivendare the last boss of stratholme", "rivendare story" }, a = "Baron Rivendare is a death knight serving Kel'Thuzad who rules the undead side of Stratholme from his ziggurat at the end. Kill him to finish the Baron run (rewarding the Deathcharger mount in Classic at a small drop chance). He raises skeletons and casts Mortal Strike and Death Pact.", topic = "lore_bosses" }
add{ q = { "who is gandling", "darkmaster gandling", "scholomance last boss", "who is gandling exactly", "gandling backstory", "where is gandling", "who runs scholomance school", "tell me about darkmaster gandling", "is gandling the final boss of scholomance", "gandling story", "who is darkmaster gandling and what is he doing in scholomance" }, a = "Darkmaster Gandling heads the Scholomance, the Cult of the Damned's school of necromancy in Caer Darrow, Western Plaguelands. He's its final boss and teleports players into side rooms full of adds; get out by killing them or just waiting near the door. Tier 0.5 and the Skeleton Key run through Scholomance.", topic = "lore_bosses" }
add{ q = { "who is mathias shaw", "mathias shaw", "si:7 leader", "our man in theramore", "whos mathias shaw", "who leads si7", "mathias shaw lore", "where is mathias shaw", "tell me about mathias shaw", "where can i find mathias shaw in stormwind" }, a = "Mathias Shaw leads SI:7, Stormwind's spy agency. In Forever he gives Alliance players Our Man in Theramore, the start of the chain that leads to Alcaz Prison and the investigation into King Varian's whereabouts.", topic = "lore_bosses" }
add{ q = { "who is eitrigg", "eitrigg", "the missing kor'kron", "whos eitrigg", "eitrigg backstory", "where is eitrigg", "who is the missing korkron", "tell me about eitrigg", "where can i find eitrigg for the missing kor'kron quest", "eitrigg story" }, a = "Eitrigg is an old orc veteran and Thrall's advisor in Orgrimmar, the orc Tirion Fordring was exiled for defending. In Forever he gives Horde players The Missing Kor'kron, which leads to Alcaz Prison and Sergeant Ulka's quests on the island. He also features in the Horde Onyxia attunement.", topic = "lore_bosses" }
add{ q = { "who is mason connery", "man in the iron chains", "mason connery quest", "whos mason connery", "man in iron chains", "mason connery lore", "where is mason connery", "tell me about mason connery", "what is the man in the iron chains quest", "connery quest" }, a = "Mason Connery is a prisoner inside Alcaz Prison (a nod to Sean Connery's John Mason in The Rock). Talk to him before you kill The Questioner: he gives The Man in the Iron Chains and More Valuable Than Gold. Bring back the Ornate Shackle Key from The Questioner; the reward chain continues in Moonbrook.", topic = "lore_bosses" }
add{ q = { "who is zarla ober", "blazeroar", "alcaz final boss", "zarla's journal", "whos zarla ober", "zarla ober backstory", "who is blazeroar", "what is in zarlas journal", "tell me about zarla ober", "is zarla ober the last boss of alcaz prison", "zarla story" }, a = "Zarla Ober is a fire mage running Alcaz Prison who turns into the red dragon Blazeroar at low health. She's the dungeon's technical last boss. Face the breath away from the group and use Tremor Totem or fear immunity. Alliance loot Zarla's Journal for The Dragon's Journal (Archmage Lan'dalock, Dalaran; 300 Kirin Tor rep); Horde find a Perfumed Note for Bad News for Folkar. Loot drops since the Nov 9 hotfix.", topic = "lore_bosses" }
add{ q = { "who is sonya darkhallow", "barrow deeps final boss", "barrow deeps last boss", "whos sonya darkhallow", "sonya darkhallow lore", "who is the barrow deeps end boss", "tell me about sonya darkhallow", "is sonya darkhallow the last boss of barrow deeps", "barrow deeps boss lore" }, a = "Sonya Darkhallow is the final boss of the Barrow Deeps, Forever's 10-player raid in the old night elf prison beneath Hyjal. Blizzard hasn't published her lore or mechanics; the raid opens Dec 9, 2026. Other bosses: Deepscar Matriarch, Khalith the Dreadspinner, Amethrax, Ravus and Darlissa, Elder Tangleclaw, Well of Sorrow and Del'lynar Songwood.", topic = "lore_bosses" }
add{ q = { "who is the wild king", "nythus the dreambound", "hyjal summit lore", "who is behind hyjal summit", "whos the wild king", "who is nythus", "hyjal summit story", "who is the villain in hyjal summit", "tell me about the wild king", "who is behind the hyjal summit raid", "nythus the dreambound backstory", "who is the wild king and is nythus the dreambound the bad guy in hyjal" }, a = "Hyjal Summit is set after Archimonde's death, as Nordrassil's power is waning and players investigate who's behind it. The Wild King is described as drawing on the World Tree's power until it overwhelms him; whether he or Nythus the Dreambound is the last boss is unconfirmed. Teased fights include an undead crocolisk wild god fought as a possessed husk then a ghost. Raid opens Dec 9, 2026.", topic = "lore_bosses" }
add{ q = { "what is taldramir", "taldramir the whispering wood", "forever legendary staff", "first forever legendary", "whats taldramir", "taldramir backstory", "whispering wood staff lore", "where does taldramir come from", "tell me about taldramir", "what is the first legendary in forever", "taldramir story", "what is the story behind taldramir the whispering wood staff" }, a = "Taldramir, the Whispering Wood is Forever's first legendary: a bind-on-pickup wooden staff revealed Nov 4, 2026 (built with Weta Workshop as a real prop). Its questline is planned for spring 2027; game data links one step to the Sylvestris Dusksong fight in Hyjal Summit. Class, stats and exact steps are not public.", topic = "lore_bosses" }
add{ q = { "who is demar brant", "farholde keep leader", "brotherhood of the horse", "whos demar brant", "who runs farholde keep", "what is the brotherhood of the horse", "demar brant backstory", "tell me about knight commander demar brant", "who is in charge at farholde keep in riverglades", "brant story" }, a = "Knight Commander Demar Brant leads the Alliance at Farholde Keep in the Riverglades. The Brotherhood of the Horse, a knightly order sent to fight ogres and orcs after the Second War, still holds Farholde and Meadowsbrook and fights to win back the land the Old Horde took.", topic = "lore_bosses" }
add{ q = { "who is archmage modera", "modera dalaran", "image of archmage modera", "whos modera", "archmage modera backstory", "where is archmage modera", "is modera in dalaran", "tell me about archmage modera", "what is the image of archmage modera in southshore", "modera story" }, a = "Archmage Modera is a Kirin Tor archmage; in Forever her image stands by the Dalaran sewer entrance in Silverpine (about 68.5, 45.1). She hands out the final steps of the City of Dalaran attunement (Heart of Disruption for Alliance, Blood in the Streets for Horde), which give the Dalaran Sewer Key.", topic = "lore_bosses" }
add{ q = { "who is mankrik", "mankrik's wife", "lost in battle quest", "where is mankrik's wife", "whos mankrik", "mankrik backstory", "how do i find mankriks wife", "tell me about mankrik", "where do i find mankriks wife in the barrens", "mankrik story" }, a = "Mankrik is an orc in the Crossroads (The Barrens) whose wife Olgra was killed by quilboar. For Lost in Battle, find the Beaten Corpse south of the Crossroads at about 49, 50 in The Barrens. Classic baseline, location not reconfirmed for Forever.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is vol'jin", "vol'jin", "darkspear trolls leader", "whos voljin", "who leads the darkspear", "voljin backstory", "where is voljin", "tell me about voljin", "where can i find voljin in orgrimmar", "voljin story", "who is voljin and why are the darkspear trolls with the horde" }, a = "Vol'jin is chieftain of the Darkspear trolls, Thrall's allies since he rescued them from the sea witch. The Darkspears settled the Echo Isles and Sen'jin Village in Durotar. He's in the Valley of Spirits in Orgrimmar. Forever adds a Darkspear Islands battleground off Durotar.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is rexxar", "rexxar", "where is rexxar", "whos rexxar", "rexxar backstory", "where does rexxar patrol", "tell me about rexxar", "where does rexxar walk around in desolace", "rexxar story", "who is rexxar the guy walking around desolace with a bear" }, a = "Rexxar is a half-ogre beastmaster, champion of the Horde, who roams Desolace and Stonetalon with his bear Misha. He's a key figure in the Horde Onyxia attunement (Warlord's Command / Blood of the Black Dragon Champion chain). In Classic he patrols the road through Desolace.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is reginald windsor", "marshal windsor", "windsor escort", "whos windsor", "windsor backstory", "where is windsor", "what happened to windsor", "tell me about reginald windsor", "how do i do the windsor escort in brd", "windsor story" }, a = "Marshal Reginald Windsor is a Stormwind officer captured by the Dark Irons. In the Alliance Onyxia attunement you free him from Blackrock Depths' prison and escort him out, then later escort him through Stormwind to unmask Lady Prestor in The Great Masquerade. Blizzard says Forever's attunement is nearly the same as Classic.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is arugal", "archmage arugal", "shadowfang keep lore", "whos arugal", "arugal backstory", "where is arugal", "why did arugal make worgen", "tell me about archmage arugal", "why did arugal summon the worgen into shadowfang keep", "arugal story" }, a = "Archmage Arugal is a Dalaran mage who summoned worgen from another realm to fight the Scourge, lost control of them, went mad and took over Baron Silverlaine's Shadowfang Keep in Silverpine. He's its last boss: kill the three worgen first, keep aggro (Void Bolt can't be interrupted) and crowd-control anyone under Arugal's Curse rather than attacking them.", topic = "lore_bosses" }
add{ q = { "who is princess theradras", "zaetar", "maraudon lore", "whos theradras", "theradras backstory", "who is zaetar", "what is maraudon about", "tell me about princess theradras", "what is the story behind maraudon and theradras", "theradras story" }, a = "Princess Theradras is the earth elemental daughter of Therazane. With Zaetar, son of Cenarius, she fathered the centaur; the centaur's ancestors killed Zaetar, and his ghost (Zaetar's Spirit) lies at the bottom of Maraudon in Desolace. She's Maraudon's last boss: tank at the back of the platform and break Repulsive Gaze with Fear Ward or Tremor Totem.", topic = "lore_bosses" }
add{ q = { "who is leeroy jenkins", "leeroy jenkins", "leeroy ubrs", "leeroy?", "who is leeroy", "is leeroy in forever", "leeroy backstory", "tell me about leeroy jenkins", "is leeroy jenkins an npc in ubrs in forever", "leeroy story" }, a = "Leeroy Jenkins is a 2005 video meme: a paladin who charged into the Rookery whelp room in Upper Blackrock Spire while his guild planned, getting everyone killed. Blizzard later put an NPC nod to him in retail. No Forever-specific Leeroy content is known.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is the lich king", "lich king vs arthas", "ner'zhul", "nerzhul backstory", "is arthas the lich king", "tell me about the lich king", "is the lich king arthas or nerzhul in forever", "lich king story", "whats the difference between the lich king arthas and nerzhul", "is the lich king a person or a helmet" }, a = "The original Lich King was Ner'zhul, an orc shaman the demon Kil'jaeden trapped in a suit of ice armor in Northrend to lead the Scourge. Arthas took up the helm at the end of The Frozen Throne and merged with him. In vanilla-era lore the Lich King rules from Icecrown while Kel'Thuzad runs Naxxramas over the Plaguelands.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is deathwing", "deathwing lore", "is deathwing in forever", "whos deathwing", "deathwing backstory", "where is deathwing", "will deathwing show up", "tell me about deathwing", "will deathwing show up in forever", "deathwing story", "is deathwing going to be in forever or is he not around yet" }, a = "Deathwing (Neltharion) was the black Dragon Aspect, corrupted by the Old Gods, father of Onyxia and Nefarian. In vanilla he's in hiding after the Second War, and his children run his schemes in Stormwind and Blackrock. Blizzard hasn't announced Deathwing content for Forever; fans speculate the Alcaz Island and Onyxia threads may lead to a black dragonflight plot.", src = "classic", topic = "lore_bosses" }
add{ q = { "who is varimathras", "varimathras", "dreadlord undercity", "whos varimathras", "varimathras backstory", "where is varimathras", "why is there a dreadlord", "tell me about varimathras", "why is there a dreadlord in undercity", "varimathras story", "who is varimathras and why is a dreadlord serving sylvanas" }, a = "Varimathras is a nathrezim dreadlord who served Sylvanas after she freed herself; he's her lieutenant in the Undercity's Royal Quarter. He gives Horde quests such as Into the Scarlet Monastery and The Power to Destroy (Ragefire Chasm). Forsaken Kingdom shows him at the founding of the Undercity.", topic = "lore_bosses" }
add{ q = { "who is whitemane", "sally whitemane", "high inquisitor whitemane", "who is mograine sm", "whos whitemane", "whitemane backstory", "who is mograine", "what is the scarlet crusade", "tell me about high inquisitor whitemane", "who is mograine in scarlet monastery", "whitemane story", "who is whitemane and how is she connected to mograine in sm" }, a = "High Inquisitor Sally Whitemane and Scarlet Commander Renault Mograine lead the Scarlet Crusade from the Cathedral of Scarlet Monastery in Tirisfal. Renault betrayed his father Alexandros (the original Ashbringer wielder). In SM Cathedral you kill Mograine, then Whitemane arrives and raises him at half health; kill Whitemane while the tank holds Mograine. In Forever Whitemane's Chapeau was reworked into a healer item.", topic = "lore_bosses" }
add{ q = { "last boss of every dungeon", "final boss list dungeons", "who is the end boss of", "dungeon final bosses", "final bosses of all dungeons", "who is the last boss in each dungeon", "list every dungeon end boss", "dungeon last boss list", "end bosses for every instance", "can you tell me the final boss of each classic dungeon", "last boss per dungeon" }, a = "Last bosses: RFC Bazzalan; WC Mutanus; DM VanCleef; SFK Arugal; BFD Aku'mai; Stocks Bazil Thredd; Gnomer Thermaplugg; RFK Charlga Razorflank; SM Mograine/Whitemane (Cathedral); RFD Amnennar; Uldaman Archaedas; ZF Ukorz Sandscalp; Mara Theradras; ST Shade of Eranikus/Avatar of Hakkar; BRD Thaurissan; LBRS Wyrmthalak; UBRS Drakkisath; DM King Gordok/Tortheldrin/Alzzin; Scholo Gandling; Strat Baron Rivendare/Balnazzar. Forever new: see Hall of Thanes, Alcaz, etc.", src = "classic", topic = "lore_bosses" }
add{ q = { "rfc bosses", "ragefire chasm bosses", "ragefire chasm guide", "rfc last boss", "ragefire bosses", "who is the last boss of ragefire", "rfc boss list", "ragefire chasm boss order", "rfc tips", "first time doing ragefire chasm what bosses are there", "taragaman the hungerer" }, a = "Ragefire Chasm (13-18, inside Orgrimmar's Cleft of Shadow): Oggleflint (kill his 2 adds first), Taragaman the Hungerer (Uppercut knocks you toward the lava, keep your back away from it), Jergosh the Invoker (interrupt Immolate, kill adds) and Bazzalan, the last boss (hits hard, cleanse Deadly Poison, kill his adds first). All quests are Horde-only; Alliance's counterpart is Hall of Thanes.", topic = "lore_bosses" }
add{ q = { "wc bosses", "wailing caverns guide", "how to summon mutanus", "wailing caverns last boss", "naralex escort", "wailing caverns bosses", "who is the last boss in wc", "wc boss order", "how do i do the naralex escort", "mutanus summon how", "how do you get mutanus the devourer to spawn in wailing caverns", "wc boss list" }, a = "Wailing Caverns bosses: Lady Anacondra, Lord Cobrahn, Kresh, Lord Pythas, Skum, Lord Serpentis, Verdan the Everliving, then Mutanus the Devourer. To get Mutanus, kill the four Fang lords (Anacondra, Cobrahn, Pythas, Serpentis), talk to the Disciple of Naralex at the entrance and escort him to the ritual stone; kill 7 oozes and 3 snakes, then Mutanus spawns. Interrupt Naralex's Nightmare. Forever adds a druid set that gives serpent Cat Form.", topic = "lore_bosses" }
add{ q = { "deadmines bosses", "dm boss order", "deadmines guide", "how to kill vancleef", "deadmines boss list", "who is the last boss in deadmines", "what are the bosses in the deadmines in order", "how do you get through deadmines", "vc boss list", "how do we get to vancleef and what bosses are on the way", "deadmines tips for first run" }, a = "Deadmines (Westfall, entrance in Moonbrook): Rhahk'Zor, Miner Johnson (rare), Sneed's Shredder/Sneed, Gilnid, Mr. Smite, Captain Greenskin, Edwin VanCleef (final, on the ship), Cookie. Forever keeps the order but bosses hit much harder (Rhahk'Zor ~330 per slam), so go at 18-21. VanCleef calls 2 Defias adds at low health: CC or kill them. Quests are Alliance-only.", topic = "lore_bosses" }
add{ q = { "sfk bosses", "shadowfang keep guide", "sfk boss order", "shadowfang keep last boss", "shadowfang bosses", "sfk boss list", "who is the last boss in sfk", "shadowfang keep boss order", "sfk tips", "how do we get through shadowfang keep to arugal", "arugal fight" }, a = "Shadowfang Keep (Silverpine): Rethilgore, Razorclaw the Butcher, Baron Silverlaine (decurse Veil of Shadow), Commander Springvale (interrupt Holy Light after his bubble), Odo the Blindwatcher (kill bats, he gets stronger as he drops), Deathsworn Captain (rare), Fenrus, Wolf Master Nandos (wolves at 80%), then Archmage Arugal. Forever only changed loot. Quests are Horde-only, plus rogue, warlock and Alliance paladin class quests. Ending SFK also drops the Tome of Dalaran for the secret Dalaran boss.", topic = "lore_bosses" }
add{ q = { "bfd bosses", "blackfathom deeps guide", "aku'mai", "bfd last boss", "how to open aku'mai", "blackfathom bosses", "bfd boss list", "how do i open akumai", "who is the last boss in bfd", "bfd fires how to light", "how do we light the braziers to get to aku'mai in bfd", "akumai fight" }, a = "Blackfathom Deeps (Zoram Strand, Ashenvale): Ghamoo-ra, Lady Sarevess, Gelihast (click the stone behind him for Blessing of Blackfathom), Lorgus Jett and Baron Aquanis (Horde quests), Twilight Lord Kelris, Old Serra'kis, Aku'mai. To reach Aku'mai, light the 4 braziers in Kelris's room; each wave of adds must die first. Tank Aku'mai away from casters and step out of Poison Cloud. Forever only changed loot.", topic = "lore_bosses" }
add{ q = { "stockade bosses", "stocks guide", "the stockade bosses", "bazil thredd", "stocks boss list", "who is the last boss in stockade", "where is bazil thredd in the stockade", "what are the stockade bosses", "who is the last boss in the stormwind stockade prison", "how do we clear the stockades fast", "stockade tips" }, a = "The Stockade (Stormwind's Mage Quarter canal): Targorr the Dread, Kam Deepfury, Hamhock, Dextren Ward, Bazil Thredd and the rare Bruegal Ironknuckle. All are simple; pull carefully because prisoners link. Quests are Alliance-only (Crime and Punishment, The Fury Runs Deep, What Comes Around..., Quell the Uprising, The Color of Blood). Classic baseline; Forever confirms no Horde quests here.", src = "classic", topic = "lore_bosses" }
add{ q = { "gnomer bosses", "gnomeregan guide", "thermaplugg", "gnomeregan last boss", "gnomer boss list", "who is the last boss in gnomer", "what are the bosses in gnomeregan in order", "how do you get through gnomer", "how do we beat thermaplugg", "how do we beat mekgineer thermaplugg in gnomeregan", "gnomer tips" }, a = "Gnomeregan (Dun Morogh): Grubbis (kill Chomper first), Viscous Fallout (immune to frost), Electrocutioner 6000 (spread; drops the Workshop Key), Crowd Pummeler 9-60 (tank against a wall), rare Dark Iron Ambassador, then Mekgineer Thermaplugg. On Thermaplugg, tank in the middle, re-taunt after Knock Away, kill Walking Bombs and hit the pillar buttons to stop bomb spawns. Horde get in via the Chief Engineer Scooty goblin transponder from Booty Bay.", topic = "lore_bosses" }
add{ q = { "rfk bosses", "razorfen kraul guide", "charlga razorflank", "rfk last boss", "rfk boss list", "who is the last boss in rfk", "what are the bosses in razorfen kraul in order", "how do you get through rfk", "how do we beat charlga", "what bosses are in razorfen kraul and who is last", "rfk tips" }, a = "Razorfen Kraul (southern Barrens): Roogug, Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, Agathelos the Raging, Blind Hunter (rare), Earthcaller Halmgar (rare) and Charlga Razorflank, the last boss. Interrupt Charlga's heals and kill her adds. Quests include Willix the Importer escort and Mortality Wanes (Treshala's pendant). Classic baseline; Forever said to change mainly loot.", src = "classic", topic = "lore_bosses" }
add{ q = { "rfd bosses", "razorfen downs guide", "amnennar", "rfd last boss", "rfd gong event", "rfd boss list", "who is the last boss in rfd", "what are the bosses in razorfen downs in order", "how does the rfd gong work", "how do we beat amnennar", "how does the gong event work in razorfen downs", "rfd tips" }, a = "Razorfen Downs (southern Barrens border): Tuten'kash (rung by the gong: 3 waves, then him), Mordresh Fire Eye, Glutton, Ragglesnout (rare), Plaguemaw, then Amnennar the Coldbringer, a lich. On Amnennar, kill his Frozen Spectral adds when they spawn and interrupt Frostbolt. Quests: Bring the Light (Alliance, kill Amnennar), Bring the End (Horde, Andrew Brownell in Undercity) and the Belnistrasz escort. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "sm graveyard bosses", "sm library bosses", "sm armory", "herod", "scarlet monastery bosses", "sm bosses", "scarlet monastery boss list", "sm wings bosses", "who is in sm library", "herod fight", "what bosses are in each scarlet monastery wing", "sm graveyard boss" }, a = "Scarlet Monastery wings: Graveyard (30-38) Interrogator Vishas, Bloodmage Thalnos, rares Azshir and Ironspire; Library (33-41) Houndmaster Loksey and Arcanist Doan (Scarlet Key is in the chest behind him); Armory (36-44) Herod, who whirlwinds and enrages at low health, then spawns trainee adds when he dies; Cathedral (38-46) High Inquisitor Fairbanks (hidden), Mograine and Whitemane. Forever changed loot, not bosses.", topic = "lore_bosses" }
add{ q = { "mograine whitemane strat", "sm cath boss", "how to kill whitemane", "whitemane fight", "how do we kill mograine and whitemane", "what bosses are in sm cathedral", "how do you handle whitemane resurrecting mograine", "whitemane sleep and res", "how do we beat mograine and whitemane in the cathedral", "sm cath strat tips" }, a = "Pull Scarlet Commander Mograine (usually his room's guards run in too: AoE them). When he dies Whitemane comes in; at half health she puts the group to sleep and resurrects Mograine. Then kill Whitemane first while the tank holds Mograine, interrupting her heals; Mograine's Divine Shield makes him the slower kill. Classic baseline tactics.", src = "classic", topic = "lore_bosses" }
add{ q = { "uldaman bosses", "uldaman guide", "archaedas", "uldaman last boss", "how to start archaedas", "uldaman boss list", "who is the last boss in uldaman", "archaedas fight", "how do i start archaedas", "ulda boss order", "how do we start the archaedas fight at the end of uldaman", "uldaman tips" }, a = "Uldaman (Badlands): The Lost Dwarves (Horde-side), Revelosh, Ironaya (summoned with Gni'kiv Medallion + Shaft of Tsol), Obsidian Sentinel, Ancient Stone Keeper, Galgann Firehammer, Grimlok, then Archaedas. The Medallion and Shaft combine into the Staff of Prehistoria, used in the Map Room for Ironaya. Wake Archaedas by using the altar in his chamber; he wakes stone guardians as you fight, so kill adds, spread for Ground Tremor and kite him if needed. Forever keeps the layout; loot updated.", topic = "lore_bosses" }
add{ q = { "zf bosses", "zul'farrak guide", "zf stairs event", "gahz'rilla", "zf last boss", "zul'farrak bosses", "zf boss list", "zf stairs event how", "who is the last boss in zf", "zf boss order", "how do we survive the stairs event in zul'farrak", "zf tips" }, a = "Zul'Farrak (Tanaris): Antu'sul, Theka the Martyr, Witch Doctor Zum'rah, Hydromancer Velratha, the stairs event, then Chief Ukorz Sandscalp and Ruuzlu. For the stairs, free Sergeant Bly and friends from their cages; waves of trolls come down, ending with Shadowpriest Sezz'ziz and Nekrum. Kill Bly's crew after (Weegli blows the door). Gahz'rilla is optional: ring the gong with the Mallet of Zul'Farrak. Classic-based guide.", topic = "lore_bosses" }
add{ q = { "mara bosses", "maraudon guide", "theradras", "maraudon last boss", "mara purple orange", "maraudon bosses", "mara boss list", "who is the last boss in mara", "mara purple or orange side", "theradras fight", "which maraudon wing should we do purple orange or inner", "mara tips" }, a = "Maraudon (Desolace): Purple side Tinkerer Gizlock and Lord Vyletongue; Orange side Noxxion and Razorlash; Poison Falls Celebras the Cursed and rare Meshlok; Earth Song Falls Landslide, Rotgrip (bring water breathing) and Princess Theradras. Theradras: tank at the back, stay out of Dust Field, break Repulsive Gaze. The Scepter of Celebras quest gives a port to Earth Song Falls. Classic-based guide.", topic = "lore_bosses" }
add{ q = { "sunken temple bosses", "st guide", "atal'hakkar", "eranikus", "avatar of hakkar how to summon", "st bosses", "sunken temple boss list", "how do i summon avatar of hakkar", "who is the last boss in st", "eranikus fight", "how do we summon the avatar of hakkar in sunken temple", "st tips" }, a = "Sunken Temple (Swamp of Sorrows): Atal'alarion, Spawn of Hakkar, six troll minibosses on the balconies (kill them to open Jammal'an), Jammal'an and Ogom, dragons Weaver, Dreamscythe, Hazzas and Morphaz, then the Shade of Eranikus. Avatar of Hakkar needs the Ancient Egg chain from Tanaris: kill the Bloodkeepers, use their blood to put out the 4 braziers, then fight him. Classic-based guide.", topic = "lore_bosses" }
add{ q = { "brd bosses list", "blackrock depths bosses", "brd boss order", "brd boss list", "how many bosses in brd", "blackrock depths bosses list", "brd bosses", "what bosses are in blackrock depths and what order", "brd tips" }, a = "BRD main bosses: High Interrogator Gerstahn, Lord Roccor, Houndmaster Grebmar, Ring of Law (random), Pyromancer Loregrain, Warder Stilgiss/Verek, Fineous Darkvire, Lord Incendius, Bael'Gar, General Angerforge, Golem Lord Argelmach, Grim Guzzler (Hurley, Ribbly, Plugger, Phalanx), Ambassador Flamelash, The Seven, Magmus, Emperor Dagran Thaurissan with Princess Moira. Magmus's room needs the seven dwarves killed first. Classic-based guide.", topic = "lore_bosses" }
add{ q = { "the seven brd", "seven dwarves brd", "how to do the seven", "the seven?", "how do i do the seven in brd", "seven dwarves event", "brd seven event strat", "the seven dwarves brd", "how do we beat the seven dwarves in blackrock depths", "the seven tips" }, a = "In the Summoners' Tomb, talk to Lord Doom'rel to start the fight. The seven dwarf spirits then attack one at a time (Anger'rel, Seeth'rel, Dope'rel, Gloom'rel, Vile'rel, Hate'rel, Doom'rel). Pull them to the middle, interrupt, and watch Doom'rel's demon adds. Kill all seven to open the Chest of the Seven (Hammer of Grace) and the way on.", topic = "lore_bosses" }
add{ q = { "lbrs bosses", "lower blackrock spire guide", "lbrs last boss", "wyrmthalak", "lbrs boss list", "who is the last boss in lbrs", "lbrs boss order", "wyrmthalak fight", "lower blackrock spire bosses", "what bosses are in lower blackrock spire and who is last", "lbrs tips" }, a = "Lower Blackrock Spire (55-60): Highlord Omokk, Shadow Hunter Vosh'gajin, War Master Voone, Mother Smolderweb, Urok Doomhowl (summoned event), Quartermaster Zigris, Halycon and Gizrul the Slavener, Overlord Wyrmthalak (last boss), plus rares Bannok Grimaxe, Spirestone Butcher, Crystal Fang and Ghok Bashguud. The UBRS key (Seal of Ascension) quest runs here. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "dire maul east bosses", "dm east guide", "alzzin", "dire maul west bosses", "dire maul north bosses", "dire maul boss list", "who is the last boss in dm east", "what bosses are in dire maul east west and north", "how do you get through dm east", "how do we beat alzzin", "what bosses are in each wing of dire maul", "dire maul tips" }, a = "Dire Maul (Feralas). East: Pusillin (chase him for the Crescent Key), Zevrim Thornhoof, Hydrospawn, Lethtendris, Alzzin the Wildshaper (last). West: Tendris Warpwood, Illyanna Ravenoak, Magister Kalendris, Immol'thar (drop the 5 pylons first), Prince Tortheldrin (last). North: Guard Mol'dar, Stomper Kreeg, Guard Fengus, Guard Slip'kik, Captain Kromcrush, King Gordok. Tribute runs leave the guards alive. Classic baseline.", topic = "lore_bosses" }
add{ q = { "scholomance boss list", "scholo bosses guide", "how to kill rattlegore", "scholo boss list", "who is the last boss in scholo", "what are the bosses in scholomance in order", "how do you get through scholo", "how do we beat rattlegore", "what bosses are in scholomance and in what order", "scholo tips" }, a = "Scholomance: Kirtonos the Herald (summoned with Blood of Innocents at the balcony brazier), Jandice Barov (find the real one among images), Rattlegore (drops the Viewing Room Key), Ras Frostwhisper, Instructor Malicia, Doctor Theolen Krastinov, Lorekeeper Polkelt, The Ravenian, Lord Alexei Barov, Lady Illucia Barov, Darkmaster Gandling. Kill the six side-room bosses to make Gandling appear. Skeleton Key needed to enter.", topic = "lore_bosses" }
add{ q = { "strat bosses", "stratholme live side", "stratholme dead side", "balnazzar", "strat boss list", "stratholme bosses", "strat live side bosses", "strat dead side bosses", "balnazzar fight", "what bosses are on each side of stratholme", "strat tips" }, a = "Stratholme Live (main gate): Timmy the Cruel, Malor the Zealous, Cannon Master Willey, Archivist Galford, Grand Crusader Dathrohan, who becomes the dreadlord Balnazzar (last boss). Undead (service gate): Magistrate Barthilas, Nerub'enkan, Baroness Anastari, Maleki the Pallid, Ramstein the Gorger, then Baron Rivendare. On the undead side, kill the three ziggurat bosses (Anastari, Nerub'enkan, Maleki) to open the slaughterhouse, then Ramstein, then the Baron. Classic baseline.", topic = "lore_bosses" }
add{ q = { "can i get thunderfury in forever", "thunderfury forever", "is thunderfury in the game", "bindings of the windseeker forever", "thunderfury?", "is thunderfury in forever", "can you get thunderfury", "do bindings drop in forever", "thunderfury available?", "can i actually get thunderfury in forever or is mc not out", "tf in forever" }, a = "Not yet. Thunderfury needs Molten Core and Blackwing Lair drops, and neither raid has a Forever release date (launch raids are Barrow Deeps, Hyjal Summit and Onyxia). Molten Core is in the game data with the Bindings of the Windseeker on Garr and Baron Geddon and the Thunderaan quest from Highlord Demitrian in Silithus, but you can't do it now.", topic = "lore_bosses" }
add{ q = { "how to get thunderfury", "thunderfury steps", "thunderfury quest", "blessed blade of the windseeker how", "thunderfury how?", "how do i get thunderfury", "thunderfury quest steps", "how to make thunderfury", "thunderfury mats", "what are all the steps to get thunderfury blessed blade", "tf quest" }, a = "Classic steps (not available in Forever yet):\n1. Loot the Left Binding (Garr) and Right Binding (Baron Geddon) of the Windseeker in Molten Core.\n2. Take a binding to Highlord Demitrian in northern Silithus to start the chain.\n3. Get the Essence of the Firelord from Ragnaros while on the quest.\n4. Gather Elementium Bars (Elementium Ore from Blackwing Lair, smelted via the Thorium Brotherhood).\n5. Hand everything to Demitrian; the ritual summons Prince Thunderaan, a 40-player fight. Win and you get Thunderfury.", src = "classic", topic = "lore_bosses" }
add{ q = { "how to get sulfuras", "sulfuras hand of ragnaros", "eye of sulfuras", "sulfuron hammer", "sulfuras?", "how do i get sulfuras", "sulfuras quest steps", "how to make sulfuras", "eye of sulfuras drop", "what are all the steps to make sulfuras hand of ragnaros", "sulfuras hammer" }, a = "Classic: combine the Eye of Sulfuras (rare drop from Ragnaros in Molten Core) with a Sulfuron Hammer. The hammer is a Blacksmithing item: Plans: Sulfuron Hammer come from Lokhtos Darkbargainer (Thorium Brotherhood) in BRD's Grim Guzzler, and it needs Sulfuron Ingots plus a big pile of other mats. It's BoE, so you can buy one. In Forever Molten Core isn't released, so Sulfuras can't be made yet.", src = "classic", topic = "lore_bosses" }
add{ q = { "how to get atiesh", "atiesh greatstaff", "splinters of atiesh", "atiesh forever", "atiesh?", "how do i get atiesh", "atiesh quest steps", "is atiesh in forever", "splinters of atiesh drop", "what are all the steps to get atiesh greatstaff of the guardian", "atiesh staff" }, a = "Classic (mage, priest, warlock, druid):\n1. Collect 40 Splinters of Atiesh from Naxxramas to make the Frame of Atiesh.\n2. Talk to Anachronos at the Caverns of Time in Tanaris.\n3. Get the remaining staff parts from Kel'Thuzad and C'Thun.\n4. Go to Stratholme and defeat Atiesh, the demon, to cleanse the staff.\n5. Return to Anachronos for the staff. Naxx and AQ have no Forever date, so Atiesh isn't obtainable yet.", src = "classic", topic = "lore_bosses" }
add{ q = { "whirlwind axe stats forever", "which whirlwind weapon", "whirlwind sword or axe", "whirlwind warhammer", "whirlwind axe sword or hammer", "whirlwind weapon stats", "best whirlwind weapon", "whirlwind sword vs axe", "which whirlwind weapon should i pick in forever", "whirlwind warhammer stats" }, a = "In Forever all three are item level 40 with +16 Strength and +15 Stamina (Classic was +15/+14). Axe 102-154 at 3.60 speed, Sword 82-124 at 2.90, Warhammer 97-146 at 3.40. With Weaponmaster 5/5 the axe gives +5% crit, the sword a 5% extra-attack chance, the hammer ignores 15% armor. Most guides pick the Axe. Finishing the quest unlocks all three appearances.", class = "WARRIOR", topic = "lore_bosses" }
add{ q = { "nature protection potion cyclonian", "how to kill cyclonian", "cyclonian solo", "cyclonian?", "nature protection potion", "cyclonian strat", "can i solo cyclonian with a nature protection potion", "cyclonian tips", "what potion do i need to kill cyclonian", "is cyclonian hard to kill" }, a = "Cyclonian is a level 40 elite with about 4,600 health that hits with nature damage and knocks you around. Bring a Nature Protection Potion (Forever shortened it to 2 minutes, so drink it right before the pull), healing potions, and ideally a friend or two. Many warriors do it around 35-40 with help.", class = "WARRIOR", topic = "lore_bosses" }
add{ q = { "are classic bis items the same in forever", "hand of edward the odd forever", "world epics forever", "boe epics forever", "classic bis same?", "are classic bis items the same", "hand of edward the odd", "are classic world epics and bis items the same in forever", "classic items changed?", "did forever change the old classic world drop epics", "is hand of edward still good" }, a = "Don't assume Classic stats. Forever reworked itemization across the board (unified hit/crit, Expertise instead of weapon skill, spell power on healing gear) and gave many old dungeon items new stats or effects; Blizzard also hid over 12,500 items from dataminers. Classic world-drop epics like Hand of Edward the Odd may exist, but check the tooltip in game before buying on the AH.", src = "classic", topic = "lore_bosses" }
add{ q = { "hand of justice", "ironfoe", "where does hand of justice drop", "hoj?", "hand of justice drop", "ironfoe drop", "hoj brd", "where do i farm hand of justice and ironfoe in brd", "hoj farm" }, a = "In Classic, Hand of Justice (melee trinket with an extra-attack proc) and Ironfoe (one-hand mace with extra attacks) both drop from Emperor Dagran Thaurissan in BRD. Hand of Justice shows on Forever beta BiS sims for warriors, but stats can differ, so read the tooltip.", src = "classic", topic = "lore_bosses" }
add{ q = { "quel'serrar", "foror's compendium", "ony tank sword quest", "how to get quel serrar", "how do i get quel'serrar", "quel serrar quest", "forors compendium drop", "ony tank sword", "how do i get the quel'serrar tank sword from onyxia", "quel serrar steps" }, a = "Classic: Foror's Compendium of Dragon Slaying drops in Dire Maul North (often from the Tribute chest or King Gordok's area). Turn it in to Lorekeeper Lydros in the Dire Maul West library to start the chain. You heat the blade in Onyxia's breath by dropping it in front of her during the fight and pick it up before it cools. Warrior/paladin only. Not confirmed in Forever.", src = "classic", topic = "lore_bosses" }
add{ q = { "benediction anathema", "priest staff quest", "rhok'delar", "hunter bow quest", "class epic quests", "benediction quest", "rhokdelar quest", "what are the class epic quests like benediction and rhokdelar", "class epics forever", "which classes get an epic quest at 60", "how do i get benediction", "is rhok'delar in forever" }, a = "Classic class epics need raid drops: Benediction/Anathema (priest; Eye of Divinity from Majordomo Executus in MC), Rhok'delar (hunter; Ancient Petrified Leaf from Majordomo's cache in MC, then four solo demon fights), Warlock Dreadsteed and Paladin Charger mount quests (Scholo/DM) and others. MC/BWL aren't in Forever yet, so the raid-based ones are unavailable; mount quests aren't confirmed.", src = "classic", topic = "lore_bosses" }
add{ q = { "ashbringer", "is ashbringer in the game", "corrupted ashbringer", "is ashbringer in forever", "can you get ashbringer in forever", "where does corrupted ashbringer drop", "ashbringer lore", "is ashbringer obtainable in forever or just a rumor", "ashbringer how" }, a = "Ashbringer is the holy sword of Alexandros Mograine, corrupted after his son Renault betrayed him. In Classic you only get the Corrupted Ashbringer, from the Four Horsemen in Naxxramas; it's the reason Whitemane and Mograine react to it in Scarlet Monastery. Naxx has no Forever date.", src = "classic", topic = "lore_bosses" }
add{ q = { "mark of fordring", "in dreams quest reward", "taelan fordring", "in dreams reward", "mark of fordring quest", "is mark of fordring worth it from the in dreams quest", "taelan fordring quest", "what does the in dreams quest give", "should i pick mark of fordring", "who is taelan fordring" }, a = "Mark of Fordring is the neck reward from In Dreams, the end of Tirion Fordring's Plaguelands chain: kill Grand Inquisitor Isillien at Hearthglen while escorting Taelan Fordring, who dies, then report to Tirion. It shows on Forever beta BiS lists for rogues and hunters, but check its new stats.", topic = "lore_bosses" }
add{ q = { "felstriker", "where does felstriker drop", "felstriker rend", "felstriker drop", "rend dagger", "where do i farm felstriker from rend in ubrs", "felstriker farm", "does rend drop felstriker", "is felstriker still good in forever", "felstriker drop rate" }, a = "Felstriker, a dagger with a chance to make your hits all crit for a short time, drops from Warchief Rend Blackhand in UBRS in Classic. It appears in Forever beta rogue sims, so it's still in the game, but the stats may have changed.", class = "ROGUE", topic = "lore_bosses" }
add{ q = { "onyxia hide backpack", "head of onyxia", "rallying cry of the dragonslayer forever", "ony bag?", "head of onyxia turn in", "rallying cry of the dragonslayer", "ony head buff", "how do i get the onyxia hide backpack from the head quest", "ony buff forever" }, a = "Onyxia drops her head; turning it in to Bolvar (Alliance) or Thrall (Horde) gives Rallying Cry of the Dragonslayer to nearby players. Forever removes world buffs when you enter dungeons and raids, so it only helps in the open world. The Onyxia Hide Backpack (18 slots) and loot tables in Forever are expected to change and aren't confirmed.", src = "classic", topic = "lore_bosses" }
add{ q = { "deathcharger's reins", "baron mount", "rivendare mount forever", "rivendare mount", "baron mount drop", "is baron mount in forever", "can i still get deathchargers reins from baron rivendare", "baron mount drop rate", "how rare is the baron mount", "deathcharger drop chance" }, a = "Classic: Baron Rivendare in Stratholme has a small chance to drop Deathcharger's Reins, an epic undead horse. Whether Forever kept the mount on his loot table isn't confirmed.", src = "classic", topic = "lore_bosses" }
add{ q = { "alcaz willcrusher", "alcaz prison loot", "best loot alcaz", "alcaz operative insignia", "alcaz loot?", "best loot in alcaz", "what is the best loot to farm from alcaz prison", "alcaz drops", "what does alcaz prison drop", "is alcaz willcrusher good", "alcaz insignia what for" }, a = "Alcaz Prison standouts: Alcaz Willcrusher (2H mace, Overseer Wrex), Katerina's Shanker (dagger) and Cutthroat Chestguard (Katerina), Tidesong Wand (Ca'zass), Defias Enforcer's Shoulderpads (The Questioner). The Alcaz Operative Insignia is a secret toy that makes you look like a Defias Operative for 10 minutes on a 30-minute cooldown.", topic = "lore_bosses" }
add{ q = { "molten core bosses", "mc boss list", "mc bosses order", "mc bosses?", "mc boss order", "how many bosses in molten core", "what bosses are in molten core and what order", "mc bosses forever", "what bosses are in mc", "how many bosses does molten core have" }, a = "Molten Core (Classic, not released in Forever): Lucifron, Magmadar, Gehennas, Garr, Shazzrah, Baron Geddon, Golemagg, Sulfuron Harbinger, Majordomo Executus, Ragnaros. You must douse the runes near bosses with Aqual Quintessence (Hydraxian Waterlords) to summon Majordomo; after him, talk to Majordomo to summon Ragnaros. Entry is via the Core Fragment attunement in BRD.", topic = "lore_bosses" }
add{ q = { "bwl bosses", "blackwing lair boss list", "when is bwl", "bwl boss list", "blackwing lair bosses", "bwl boss order", "what bosses are in blackwing lair and when is it out", "bwl forever", "what bosses are in bwl", "how many bosses in blackwing lair" }, a = "Blackwing Lair (Classic, no Forever date): Razorgore the Untamed, Vaelastrasz the Corrupt, Broodlord Lashlayer, Firemaw, Ebonroc, Flamegor, Chromaggus, Nefarian. Classic attunement was touching the orb behind Drakkisath in UBRS (Blackhand's Command).", src = "classic", topic = "lore_bosses" }
add{ q = { "onyxia lore why kill onyxia", "why does onyxia matter", "why are we killing onyxia", "why kill onyxia", "onyxia story why", "onyxia lore why", "why do we have to kill onyxia in the story", "onyxia plot", "what did onyxia do that we need to kill her", "why is onyxia a threat to stormwind" }, a = "Onyxia is the hidden power behind Stormwind's court as Lady Katrana Prestor and the reason both factions' heroes go after the black dragonflight. Killing her ends her manipulation of the regency, which ties into the mystery of the missing King Varian that Forever expands through Alcaz Island.", topic = "lore_bosses" }
add{ q = { "who are the defias", "defias brotherhood", "what is the defias", "defias?", "defias brotherhood lore", "why are the defias in westfall", "who are the defias brotherhood and what do they want", "defias story", "why are the defias attacking westfall" }, a = "The Defias Brotherhood are Stormwind's unpaid stonemasons turned outlaws under Edwin VanCleef. They terrorize Westfall from Moonbrook and the Deadmines, and secretly take money from Lady Prestor (Onyxia). In Forever they also run Alcaz Prison off Dustwallow Marsh alongside Strashaz naga.", topic = "lore_bosses" }
add{ q = { "who are the scarlet crusade", "scarlet crusade", "scarlets", "who are the scarlets", "scarlet crusade lore", "why are scarlets hostile", "scarlet crusade story", "who are the scarlet crusade and why do they attack everyone", "scarlets lore" }, a = "The Scarlet Crusade are zealous human survivors of Lordaeron who hunt the undead and anyone they think is tainted, Forsaken and outsiders included. Their strongholds are Scarlet Monastery and the Scarlet Bastion/Tyr's Hand area, Hearthglen in the Plaguelands, and Stratholme's living side. Their secret leader is the dreadlord Balnazzar posing as Grand Crusader Dathrohan.", src = "classic", topic = "lore_bosses" }
add{ q = { "who are the argent dawn", "argent dawn", "argent dawn rep", "argent dawn lore", "argent dawn story", "who are the argent dawn and why should i get their rep", "ad rep", "what are the argent dawn about", "why do argent dawn fight the scourge" }, a = "The Argent Dawn is a neutral order of fighters, priests and scholars defending against the Scourge without the Scarlets' fanaticism. Their base is Light's Hope Chapel in Eastern Plaguelands, with a camp at Chillwind Camp in Western Plaguelands. Rep comes from Scourgestones, Plaguelands quests and Scholo/Strat. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "who are the scourge", "scourge lore", "cult of the damned", "scourge?", "scourge story", "who are the scourge and the cult of the damned", "undead scourge", "what are the scourge", "who leads the scourge", "is the cult of the damned part of the scourge" }, a = "The Scourge is the Lich King's undead army that destroyed Lordaeron. The Cult of the Damned, founded by Kel'Thuzad, spreads its plague and runs places like Scholomance in Caer Darrow. In the vanilla era the Scourge holds most of the Plaguelands, with Naxxramas floating over the east.", src = "classic", topic = "lore_bosses" }
add{ q = { "who are the forsaken", "forsaken lore", "what are forsaken", "forsaken?", "what are the forsaken", "forsaken story", "who are the forsaken and how are they different from the scourge", "forsaken race lore", "why are the forsaken in the horde", "forsaken backstory" }, a = "The Forsaken are undead who broke free of the Lich King's control under Sylvanas Windrunner and made the ruins of Lordaeron their home, building the Undercity beneath the old capital (shown in Forsaken Kingdom). They joined the Horde out of necessity. In Forever some Forsaken can even be paladins.", topic = "lore_bosses" }
add{ q = { "who are the dark iron dwarves", "dark iron", "dark iron lore", "dark irons?", "dark iron dwarves story", "why are dark irons evil", "who are the dark iron dwarves and why do they serve ragnaros", "dark iron history", "what are dark iron dwarves", "dark iron dwarves backstory" }, a = "The Dark Iron clan lost the War of the Three Hammers to the Bronzebeards and Wildhammers. Their sorcerer-thane Thaurissan summoned Ragnaros in revenge, scorching the land into Searing Gorge and Burning Steppes and enslaving the clan to the Firelord. They rule Shadowforge City in Blackrock Depths under Emperor Dagran Thaurissan.", src = "classic", topic = "lore_bosses" }
add{ q = { "thorium brotherhood", "who are the thorium brotherhood", "lokhtos", "what is the thorium brotherhood", "who is lokhtos darkbargainer", "how do i get thorium brotherhood rep", "thorium brotherhood vendor location", "who are the thorium brotherhood and how do i get their rep", "thorium brotherhood lore" }, a = "The Thorium Brotherhood are Dark Iron smiths who broke from Ragnaros. Their camp Thorium Point is in Searing Gorge, and quartermaster Lokhtos Darkbargainer sits in the Grim Guzzler in BRD. Rep comes from Dark Iron Ore, Fiery Cores and Lava Cores and unlocks fire-resist and Sulfuron Hammer plans. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "timbermaw hold", "who are timbermaw", "timbermaw furbolgs", "timbermaw?", "who are the timbermaw", "timbermaw lore", "timbermaw furbolgs story", "why are timbermaw different", "who are the timbermaw furbolgs and why are they not corrupted", "timbermaw hold lore" }, a = "The Timbermaw are the only furbolg tribe that resisted demonic corruption. They guard the tunnels linking Felwood, Moonglade and Winterspring. Kill Deadwood (Felwood) or Winterfall (Winterspring) furbolgs to raise rep; at unfriendly or worse their tunnel guards attack you. Classic baseline; Forever's Blackmaw Hold and Hyjal's Barkskin furbolgs are new.", src = "classic", topic = "lore_bosses" }
add{ q = { "cenarion circle", "who are the cenarion circle", "cenarion circle rep", "what are the cenarion circle", "cenarion circle backstory", "cenarion circle druids lore", "what do the cenarion circle do", "who are the cenarion circle and what do they do in silithus", "cc lore" }, a = "The Cenarion Circle is the druid order of night elves and tauren, based in Moonglade under Keeper Remulos, with an outpost at Cenarion Hold in Silithus watching Ahn'Qiraj. Rep comes from Silithus quests and AQ20. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "who are the kirin tor", "kirin tor forever", "kirin tor rep", "kirin tor?", "kirin tor lore", "kirin tor story", "who are the kirin tor and why are they in dalaran in forever", "what are the kirin tor", "kirin tor backstory", "kirin tor mages dalaran" }, a = "The Kirin Tor are the ruling mages of Dalaran. In Forever Dalaran is back as a working Alliance city in the Alterac Mountains, and the Kirin Tor appear as a reputation (for example 300 rep from The Dragon's Journal in Alcaz). They also brought the Alliance Skyborne (High Order) into the Alliance.", topic = "lore_bosses" }
add{ q = { "hydraxian waterlords", "aqual quintessence", "who is duke hydraxis", "hydraxian rep", "waterlords lore", "who are the hydraxian waterlords and why do i need aqual quintessence", "hydraxis", "what are the hydraxian waterlords", "hydraxian waterlords rep", "who are the water elementals in azshara" }, a = "The Hydraxian Waterlords are water elementals led by Duke Hydraxis on an island off eastern Azshara, enemies of Ragnaros. In Classic their rep gives Aqual Quintessence to douse Molten Core's runes. With MC not released in Forever, the rep has little use yet.", src = "classic", topic = "lore_bosses" }
add{ q = { "zandalar tribe", "who are the zandalar", "zandalar rep", "zandalar?", "what are the zandalar", "zandalar trolls backstory", "how do i get zandalar rep", "zandalar tribe story", "who are the zandalar trolls and what do they want", "zandalar forever" }, a = "The Zandalari are the ancestral troll tribe whose priests run the Yojamba Isle camp off Stranglethorn to stop Hakkar in Zul'Gurub. Their rep gave enchants and ZG set pieces in Classic. Zul'Gurub isn't a Forever launch raid.", src = "classic", topic = "lore_bosses" }
add{ q = { "who are the twilight's hammer", "twilight's hammer", "twilight cult", "what is the twilight's hammer", "twilight cult lore", "who leads the twilights hammer", "why are twilight cultists everywhere", "who are the twilights hammer and why are they in silithus and riverglades", "twilight hammer backstory" }, a = "The Twilight's Hammer is a doomsday cult serving the Old Gods, led by Cho'gall. In Classic you meet them in BFD, Silithus and the Searing Gorge area. In Forever they hold ruined Sunnyglade in the Riverglades and fight alongside the ogres of Krol'dok Stronghold.", topic = "lore_bosses" }
add{ q = { "shen'dralar", "who are the shen'dralar", "highborne dire maul", "what are the shen'dralar", "highborne in dire maul", "shendralar lore", "shen'dralar rep", "who are the shen'dralar highborne living in dire maul", "shendralar backstory" }, a = "The Shen'dralar are Highborne elves who stayed in Eldre'Thalas (Dire Maul) under Prince Tortheldrin, draining a demon (Immol'thar) to keep their power. Classic gives you their rep in DM West. In Forever they are central to Shen'dralas zone, and the Skyborne descend from people who fled Tortheldrin.", topic = "lore_bosses" }
add{ q = { "guardians of hyjal", "barkskin burrow", "deadwood hyjal", "what are the guardians of hyjal", "barkskin burrow lore", "deadwood furbolgs in hyjal", "guardians of hyjal backstory", "who are the guardians of hyjal and what are they fighting", "hyjal factions lore" }, a = "Guardians of Hyjal are the night elf and druid defenders of Forever's Mount Hyjal; their rep unlocks crafted tier recipes and, at Revered, the Rousing Seed Pod. Barkskin Burrow are Hyjal furbolgs who trust you only after you fight the Deadwood furbolgs there.", topic = "lore_bosses" }
add{ q = { "steamwheedle cartel", "goblin factions", "booty bay rep", "steamwheedle?", "what is the steamwheedle cartel", "goblin faction lore", "booty bay rep how", "steamwheedle backstory", "who are the steamwheedle goblins and why are they neutral", "goblin cartels" }, a = "The Steamwheedle Cartel is the neutral goblin trading company running Booty Bay, Gadgetzan, Everlook and Ratchet. Their guards protect both factions. Killing Bloodsail pirates lowers Booty Bay rep. In Forever they also run Powderfuse Port in the Riverglades, with boats to Steamwheedle Port in Tanaris.", topic = "lore_bosses" }
add{ q = { "syndicate", "who are the syndicate", "ravenholdt", "what is the syndicate", "who leads the syndicate", "ravenholdt lore", "syndicate backstory", "who are the syndicate in alterac and hillsbrad", "syndicate vs ravenholdt" }, a = "The Syndicate is a criminal gang formed from the disgraced nobility of Alterac and their followers (the Perenolde line). They operate in Alterac Mountains and Arathi Highlands, holding places like Strahnbrad and Durnholde Keep. Ravenholdt Manor, the rogue guild hidden in the Alterac foothills, opposes them; killing Syndicate raises Ravenholdt rep. Classic baseline.", src = "classic", topic = "lore_bosses" }
add{ q = { "elwynn forest lore", "what happened in elwynn", "goldshire story", "elwynn story?", "elwynn forest backstory", "what is going on in elwynn", "goldshire lore", "northshire lore", "what is the story of elwynn forest and goldshire", "why is goldshire such a big deal in elwynn" }, a = "Elwynn Forest is Stormwind's farmland and the human starting zone, centered on Northshire Abbey and Goldshire. With the army stretched thin, Defias thieves, Riverpaw gnolls (Hogger) and kobolds in the mines plague the farms, and the Stormwind guard can barely keep up.", src = "classic", topic = "lore_bosses" }
add{ q = { "westfall lore", "what happened in westfall", "why is westfall abandoned", "westfall story?", "westfall backstory", "why are the farms abandoned in westfall", "what happened to westfall", "who are the people's militia", "why is westfall so poor and full of defias", "westfall history" }, a = "Westfall was Stormwind's breadbasket until the kingdom stopped protecting it. Farmers fled, the Defias Brotherhood took over Moonbrook and the Deadmines, and the volunteer People's Militia at Sentinel Hill under Gryan Stoutmantle is all that holds the line. The Missing Diplomat chain hints at the king's kidnapping.", src = "classic", topic = "lore_bosses" }
add{ q = { "redridge lore", "what happened in redridge", "lakeshire story", "redridge story?", "redridge backstory", "what is going on in redridge", "lakeshire lore", "why are orcs in redridge", "what is the story of redridge and the blackrock orcs", "redridge history" }, a = "Redridge Mountains hold Lakeshire, a town besieged by Blackrock orcs from Stonewatch Keep and the Redridge gnolls, while the Stormwind army ignores it. Magistrate Solomon begs Stormwind for help that never comes.", src = "classic", topic = "lore_bosses" }
add{ q = { "duskwood lore", "what happened in duskwood", "darkshire story", "stalvan", "duskwood story?", "duskwood backstory", "who is stalvan mistmantle", "why is duskwood so creepy", "darkshire lore", "what is the story of duskwood and the stalvan quest chain", "duskwood history" }, a = "Duskwood fell into darkness after the Second War; its forest is haunted by worgen, undead from Raven Hill Cemetery and the ghost of Stalvan Mistmantle. The Night Watch in Darkshire defends the town. The necromancer Morbent Fel and the worgen are key threats.", src = "classic", topic = "lore_bosses" }
add{ q = { "stranglethorn lore", "stv story", "what happened in stranglethorn", "stranglethorn backstory", "what is going on in stv", "booty bay lore", "zul'gurub stv lore", "what is the story of stranglethorn vale and the trolls", "stv history" }, a = "Stranglethorn Vale is a jungle once ruled by the Gurubashi troll empire, whose capital Zul'Gurub is now home to Hakkar's priests. Trolls, Bloodsail pirates, Venture Co. miners, hunters of Nesingwary's camp and the goblin port of Booty Bay all share it. Forever adds the Drowned City dungeon off its west coast.", topic = "lore_bosses" }
add{ q = { "dun morogh lore", "ironforge story", "what happened in dun morogh", "dun morogh story?", "dun morogh backstory", "ironforge lore", "what is going on in dun morogh", "why is gnomeregan lost", "what is the story of dun morogh and ironforge", "dun morogh history" }, a = "Dun Morogh is the snowy dwarf and gnome homeland around Ironforge. The gnomes lost Gnomeregan when Mekgineer Thermaplugg betrayed them and they irradiated their own city to stop the troggs. Frostmane trolls and Dark Iron agents add trouble.", src = "classic", topic = "lore_bosses" }
add{ q = { "loch modan lore", "what happened in loch modan", "stonewrought dam", "loch modan story?", "loch modan backstory", "stonewrought dam lore", "thelsamar lore", "what is going on in loch modan", "what is the story of the stonewrought dam in loch modan", "im questing in loch modan whats the story there" }, a = "Loch Modan is dwarven land east of Dun Morogh around the Stonewrought Dam and the town of Thelsamar. Troggs and Dark Iron saboteurs threaten the dam, and the Mo'grosh ogres hold the east. Explorers' League dig sites point toward Uldaman's titan secrets.", src = "classic", topic = "lore_bosses" }
add{ q = { "wetlands lore", "what happened in the wetlands", "grim batol", "wetlands story?", "wetlands backstory", "grim batol lore", "what is going on in the wetlands", "menethil harbor lore", "what is the story of grim batol and the dragonmaw in the wetlands", "im questing in the wetlands whats the story there" }, a = "The Wetlands are marshes between Khaz Modan and Arathi. Menethil Harbor is the Alliance's port, Dragonmaw orcs still hold Grim Batol's approaches, and dwarves dig at Whelgar's Excavation. Forever adds the Excavation Site: Wetlands dungeon above that dig.", topic = "lore_bosses" }
add{ q = { "arathi highlands lore", "what happened in arathi", "stromgarde", "arathi story?", "arathi highlands backstory", "stromgarde lore", "what is going on in arathi", "why is stromgarde in ruins", "what is the story of stromgarde and the arathi highlands", "arathi history" }, a = "Arathi Highlands was the heart of Stromgarde and the ancient Arathor empire. The kingdom is broken: ogres, the Syndicate and Stromgarde's last defenders fight over the keep's ruins, Refuge Pointe holds out for the Alliance and Hammerfall for the Horde. Arathi Basin is fought over here.", src = "classic", topic = "lore_bosses" }
add{ q = { "hillsbrad lore", "southshore vs tarren mill", "what happened in hillsbrad", "hillsbrad story?", "hillsbrad backstory", "southshore lore", "tarren mill lore", "why do southshore and tarren mill fight", "what is the story of the southshore vs tarren mill rivalry", "im questing in hillsbrad whats the story there" }, a = "Hillsbrad Foothills hold Alliance Southshore and Forsaken Tarren Mill, staring at each other across the hills. Durnholde Keep, where Thrall was raised as a slave, is held by the Syndicate. Forever sends Alliance from Southshore and Horde from Tarren Mill toward the new Dalaran.", topic = "lore_bosses" }
add{ q = { "alterac mountains lore", "what happened in alterac", "dalaran forever lore", "alterac story?", "alterac mountains backstory", "dalaran lore forever", "what is going on in alterac", "what happened to dalaran", "what is the story of dalaran in alterac in forever", "alterac history" }, a = "Alterac was a human kingdom destroyed after Lord Perenolde betrayed the Alliance to the Horde; ogres and the Syndicate now hold its ruins. In Forever, Dalaran stands again where vanilla had a crater, as an Alliance-only Kirin Tor city with the City of Dalaran dungeon beneath it in its sewers.", topic = "lore_bosses" }
add{ q = { "tirisfal glades lore", "what happened in tirisfal", "brill story", "tirisfal story?", "tirisfal backstory", "brill lore", "what is going on in tirisfal", "deathknell lore", "what is the story of tirisfal glades and the forsaken", "im questing in tirisfal whats the story there" }, a = "Tirisfal Glades is the Forsaken starting zone above the ruins of Lordaeron's capital. The Forsaken guard Brill and the Undercity while the Scarlet Crusade pushes from its Monastery in the north. Forever adds the Ruins of Lordaeron dungeon above the Undercity and the Tarnished paladins questline at Shadowvale.", topic = "lore_bosses" }
add{ q = { "silverpine lore", "what happened in silverpine", "pyrewood", "silverpine story?", "silverpine backstory", "pyrewood village lore", "what is going on in silverpine", "why are there worgen in silverpine", "what is the story of pyrewood and the worgen in silverpine", "silverpine history" }, a = "Silverpine Forest lies between Tirisfal and Gilneas's Greymane Wall. The Forsaken at the Sepulcher face worgen, gnolls and Arugal's Shadowfang Keep. Pyrewood Village turns into worgen at night. In Forever the sewer entrance to the City of Dalaran dungeon is here.", topic = "lore_bosses" }
add{ q = { "western plaguelands lore", "what happened in wpl", "caer darrow andorhal", "wpl story?", "western plaguelands backstory", "andorhal lore", "caer darrow lore", "what is going on in western plaguelands", "what is the story of andorhal and caer darrow", "im questing in western plaguelands whats the story there" }, a = "Western Plaguelands is the Scourge-ravaged heart of old Lordaeron. Andorhal is a ruined city, Caer Darrow holds the Scholomance, the Scarlets fortify Hearthglen, and the Argent Dawn and Alliance hold Chillwind Camp with Horde at the Bulwark.", src = "classic", topic = "lore_bosses" }
add{ q = { "eastern plaguelands lore", "what happened in epl", "stratholme lore", "epl story?", "eastern plaguelands backstory", "stratholme history", "what is going on in eastern plaguelands", "what happened at stratholme", "what is the story of stratholme and the culling", "epl history" }, a = "Eastern Plaguelands is the plague's ground zero. Stratholme, culled by Arthas, is split between the Scarlets and Baron Rivendare's undead. Light's Hope Chapel is the Argent Dawn base, Tyr's Hand is a Scarlet bastion, and Naxxramas hovers in the east. Tirion Fordring lives in exile in a hut here.", src = "classic", topic = "lore_bosses" }
add{ q = { "searing gorge lore", "what happened in searing gorge", "thorium point story", "searing gorge story?", "searing gorge backstory", "thorium point lore", "what is going on in searing gorge", "dark iron searing gorge", "what is the story of thorium point in searing gorge", "searing gorge history" }, a = "Searing Gorge is the scorched land around Blackrock Mountain's north side, burned when Thaurissan summoned Ragnaros. Dark Iron dwarves mine it with slaves; the Thorium Brotherhood holds Thorium Point.", src = "classic", topic = "lore_bosses" }
add{ q = { "burning steppes lore", "what happened in burning steppes", "why is burning steppes on fire", "burning steppes story?", "burning steppes backstory", "why is burning steppes burning", "what is going on in burning steppes", "morgan's vigil lore", "what is the story of the burning steppes and why is it on fire", "burning steppes history" }, a = "Burning Steppes, south of Blackrock Mountain, was the green land of Redridge's north until Ragnaros's summoning set it ablaze. The Blackrock orcs of the Dark Horde and Nefarian's dragonkin rule it; Morgan's Vigil (Alliance) and Flame Crest (Horde) watch them.", src = "classic", topic = "lore_bosses" }
add{ q = { "blackrock mountain lore", "blackrock mountain what is it", "brd vs brs whats the difference", "blackrock mountain?", "blackrock mountain backstory", "brd vs brs difference", "what is inside blackrock mountain", "whats the difference between brd lbrs ubrs and mc", "blackrock mountain history" }, a = "Blackrock Mountain is a volcano split in two: Ragnaros and the Dark Iron dwarves rule the depths (Blackrock Depths, Molten Core), while Nefarian and the Dark Horde hold the spire above (Blackrock Spire, Blackwing Lair). Their war is the backdrop for BRD, LBRS and UBRS.", src = "classic", topic = "lore_bosses" }
add{ q = { "badlands lore", "what happened in the badlands", "uldaman lore", "badlands story?", "badlands backstory", "uldaman history", "what is going on in the badlands", "kargath lore", "what is the story of uldaman and the badlands", "im questing in the badlands whats the story there" }, a = "The Badlands are a dusty waste east of Loch Modan holding Uldaman, a titan vault where the Explorers' League and Dark Irons dig for secrets of the dwarves' stone-born origins. Black dragons roam the Lethlor Ravine. In Forever the new Riverglades zone sits just to the east.", topic = "lore_bosses" }
add{ q = { "swamp of sorrows lore", "what happened in swamp of sorrows", "stonard story", "swamp of sorrows story?", "swamp of sorrows backstory", "stonard lore", "what is going on in swamp of sorrows", "sunken temple swamp lore", "what is the story of stonard and the swamp of sorrows", "swamp of sorrows history" }, a = "Swamp of Sorrows is a gloomy marsh holding the Sunken Temple of Atal'Hakkar, sunk by green dragons to stop Hakkar's summoning. Horde hold Stonard; black and green dragonkin and the Atal'ai trolls lurk in the temple.", src = "classic", topic = "lore_bosses" }
add{ q = { "blasted lands lore", "dark portal lore", "what happened in blasted lands", "blasted lands story?", "blasted lands backstory", "dark portal history", "what is going on in blasted lands", "nethergarde keep lore", "what is the story of the dark portal and the blasted lands", "im questing in the blasted lands whats the story there" }, a = "The Blasted Lands are the demon-scarred wasteland around the Dark Portal, where the orcs first came to Azeroth. Nethergarde Keep guards it. In Forever the Portal stays dormant: Outland isn't in the game.", src = "classic", topic = "lore_bosses" }
add{ q = { "hinterlands lore", "what happened in the hinterlands", "jintha'alor", "hinterlands story?", "hinterlands backstory", "jintha alor lore", "what is going on in the hinterlands", "aerie peak lore", "what is the story of the hinterlands and the wildhammer", "im questing in the hinterlands whats the story there" }, a = "The Hinterlands are home to the Wildhammer dwarves at Aerie Peak and the Revantusk trolls (Horde). The Vilebranch trolls hold Jintha'Alor, where you make the Mallet of Zul'Farrak, and Emerald Dream corruption shows at the Seradane portal.", src = "classic", topic = "lore_bosses" }
add{ q = { "deadwind pass lore", "karazhan lore", "medivh", "deadwind pass story?", "karazhan backstory", "who is medivh", "what is going on in deadwind pass", "karazhan history", "what is the story of medivh and karazhan", "why is karazhan haunted and empty" }, a = "Deadwind Pass holds Karazhan, the tower of Medivh, the last Guardian of Tirisfal, who was possessed by Sargeras and opened the Dark Portal. In Classic you can't enter the tower. Forever's devs compare Barrow Deeps to a Karazhan-style raid, but Karazhan itself isn't announced.", src = "classic", topic = "lore_bosses" }
add{ q = { "durotar lore", "what happened in durotar", "orgrimmar history", "durotar story?", "durotar backstory", "orgrimmar lore", "what is going on in durotar", "why did orcs settle in durotar", "what is the story of durotar and how orgrimmar was founded", "durotar history" }, a = "Durotar is the dry orc homeland named after Thrall's father Durotan. Thrall built Orgrimmar here after landing in Kalimdor; the Darkspear trolls live at Sen'jin Village and the Echo Isles. Burning Blade cultists and Kul Tiras marines at Tiragarde Keep are local threats.", src = "classic", topic = "lore_bosses" }
add{ q = { "barrens lore", "what happened in the barrens", "crossroads story", "barrens story?", "barrens backstory", "crossroads lore", "what is going on in the barrens", "barrens history", "what is the story of the crossroads in the barrens", "im questing in the barrens whats the story there" }, a = "The Barrens is a huge savanna between Durotar and Mulgore, held by the Horde at the Crossroads and Camp Taurajo. Centaur, quilboar of Razorfen Kraul and Downs, Venture Co. and the druids of the Fang (Wailing Caverns) fight over it, and goblin Ratchet is the port.", src = "classic", topic = "lore_bosses" }
add{ q = { "mulgore lore", "thunder bluff history", "tauren homeland", "mulgore story?", "mulgore backstory", "thunder bluff lore", "what is going on in mulgore", "tauren history", "what is the story of mulgore and the tauren", "im questing in mulgore whats the story there" }, a = "Mulgore is the grassland home of the tauren, led by Cairne Bloodhoof from Thunder Bluff's mesas. Centaur and the Venture Co. threaten it, along with Palemane gnolls and quilboar.", src = "classic", topic = "lore_bosses" }
add{ q = { "teldrassil lore", "darnassus history", "why did night elves plant teldrassil", "teldrassil story?", "teldrassil backstory", "darnassus lore", "why did the night elves plant a new world tree", "what is going on in teldrassil", "what is the story of teldrassil and darnassus", "teldrassil history" }, a = "Teldrassil is the new World Tree the night elves planted off Darkshore after Nordrassil was damaged in the Battle of Mount Hyjal and they lost their immortality. It was planted without nature's blessing and is already showing signs of corruption. Darnassus sits in its branches.", src = "classic", topic = "lore_bosses" }
add{ q = { "darkshore lore", "what happened in darkshore", "auberdine", "darkshore story?", "darkshore backstory", "auberdine lore", "what is going on in darkshore", "darkshore history", "what is the story of darkshore and auberdine" }, a = "Darkshore is the night elf coast below Teldrassil, with Auberdine as its port. Corrupted wildlife, Blackwood furbolgs and naga point to deeper trouble.", src = "classic", topic = "lore_bosses" }
add{ q = { "ashenvale lore", "warsong lumber", "what happened in ashenvale", "ashenvale story?", "ashenvale backstory", "warsong lumber camp lore", "what is going on in ashenvale", "why do orcs and night elves fight in ashenvale", "what is the story of ashenvale and the warsong clan", "ashenvale history" }, a = "Ashenvale is the ancient night elf forest where the Warsong orcs logging it sparked war; Grom Hellscream killed the demigod Cenarius here. Night elves hold Astranaar, the Horde Splintertree Post, and Blackfathom Deeps lies on the coast.", src = "classic", topic = "lore_bosses" }
add{ q = { "stonetalon lore", "what happened in stonetalon", "venture co stonetalon", "stonetalon story?", "stonetalon backstory", "venture co stonetalon lore", "what is going on in stonetalon", "why is venture co cutting down stonetalon", "what is the story of stonetalon mountains and the venture company", "stonetalon history" }, a = "Stonetalon Mountains are being stripped by the Venture Co. goblins, while the Horde hold Sun Rock Retreat and the night elves Stonetalon Peak.", src = "classic", topic = "lore_bosses" }
add{ q = { "desolace lore", "what happened in desolace", "centaur war", "desolace story?", "desolace backstory", "centaur war lore", "what is going on in desolace", "magram vs gelkis", "what is the story of the centaur war in desolace", "im questing in desolace whats the story there" }, a = "Desolace is a barren land where the centaur tribes (Gelkis, Magram, Kolkar) war with each other. Maraudon, where Zaetar is buried, is here. In Forever the centaur story continues south through the Valley of Bones into Shen'dralas.", topic = "lore_bosses" }
add{ q = { "feralas lore", "what happened in feralas", "eldre'thalas lore", "feralas story?", "feralas backstory", "what is going on in feralas", "dire maul history", "what is the story of feralas and eldre'thalas", "feralas history" }, a = "Feralas is a rainforest holding Dire Maul, the ruins of the Highborne city Eldre'Thalas, now home to the Shen'dralar, ogres of the Gordok and satyrs. Feathermoon Stronghold (Alliance) and Camp Mojache (Horde) are the bases. In Forever it's also the homeland the Skyborne fled.", topic = "lore_bosses" }
add{ q = { "thousand needles lore", "what happened in thousand needles", "shimmering flats story", "thousand needles story?", "thousand needles backstory", "shimmering flats lore", "what is going on in thousand needles", "mirage raceway lore", "what is the story of thousand needles and the shimmering flats", "im questing in thousand needles whats the story there" }, a = "Thousand Needles is a canyon of stone spires south of the Barrens, with the tauren of Freewind Post and the goblin speed track of the Shimmering Flats.", src = "classic", topic = "lore_bosses" }
add{ q = { "tanaris lore", "what happened in tanaris", "caverns of time", "tanaris story?", "tanaris backstory", "caverns of time lore", "what is going on in tanaris", "gadgetzan lore", "what is the story of tanaris and the caverns of time", "tanaris history" }, a = "Tanaris is a desert ruled from goblin Gadgetzan, holding Zul'Farrak's sandfury trolls and the Caverns of Time, home of the bronze dragonflight (Anachronos stands outside). Forever's Riverglades boats land at Steamwheedle Port here.", topic = "lore_bosses" }
add{ q = { "ungoro lore", "un'goro crater lore", "what happened in ungoro", "ungoro story?", "un'goro backstory", "un goro crater history", "what is going on in ungoro", "why are there dinosaurs in un'goro", "what is the story of un'goro crater and the titans", "ungoro history" }, a = "Un'Goro Crater is a primeval jungle titan experiment full of dinosaurs, elementals from the Fire Plume Ridge and the Pylons that pulse with power crystals. Marshal's Refuge is the neutral camp. Forever adds Shaper's Terrace, a titan site above the Refuge reached with power crystals.", topic = "lore_bosses" }
add{ q = { "silithus lore", "what happened in silithus", "ahn'qiraj lore", "silithus story?", "silithus backstory", "ahn qiraj history", "what is going on in silithus", "cenarion hold lore", "what is the story of silithus and ahn'qiraj", "im questing in silithus whats the story there" }, a = "Silithus is a desert scarred by the Qiraji, insects serving C'Thun beneath Ahn'Qiraj. The Cenarion Circle watches from Cenarion Hold, the Twilight's Hammer gathers at its camps, and wind elementals hint at Prince Thunderaan.", src = "classic", topic = "lore_bosses" }
add{ q = { "dustwallow marsh lore", "what happened in dustwallow", "theramore lore", "alcaz island lore", "dustwallow story?", "dustwallow marsh backstory", "theramore history", "alcaz island backstory", "what is going on in dustwallow", "what is the story of theramore and alcaz island", "im questing in dustwallow whats the story there" }, a = "Dustwallow Marsh holds Jaina's Theramore Isle, Onyxia's Lair in the Wyrmbog, Horde Brackenwall Village and the black dragonflight's agents. In Forever, Alcaz Island off its northeast coast becomes Alcaz Prison, tied to the mystery of King Varian's disappearance.", topic = "lore_bosses" }
add{ q = { "felwood lore", "what happened in felwood", "why is felwood corrupted", "felwood story?", "felwood backstory", "what is going on in felwood", "jaedenar lore", "what is the story of felwood and how it got corrupted", "felwood history" }, a = "Felwood was northern Ashenvale until Archimonde's demons corrupted it with the Skull of Gul'dan's power. The Deadwood furbolgs are tainted, satyrs and demons remain, and the Emerald Circle and Cenarion Circle try to cleanse it. Timbermaw tunnels lead north.", src = "classic", topic = "lore_bosses" }
add{ q = { "winterspring lore", "what happened in winterspring", "everlook", "winterspring story?", "winterspring backstory", "everlook lore", "what is going on in winterspring", "winterfall furbolgs lore", "what is the story of winterspring and everlook", "im questing in winterspring whats the story there" }, a = "Winterspring is a frozen valley north of Felwood, home to goblin Everlook, frostsabers, chimaeras and the Winterfall furbolgs. Darkwhisper Gorge in the south is full of demons; in Forever it is the way into Mount Hyjal (Evie Whirlbrew's Potion of Winterspring Shrouding lets you sneak past).", topic = "lore_bosses" }
add{ q = { "azshara lore", "what happened in azshara", "blackmaw hold lore", "azshara story?", "azshara backstory", "blackmaw hold history", "what is going on in azshara", "queen azshara lore", "what is the story of azshara and blackmaw hold", "im questing in azshara whats the story there" }, a = "Azshara is the ruined coast of the night elf empire, haunted by naga, satyrs and blue dragons drawn to old Highborne ruins. In Forever it hosts Blackmaw Hold, a huge furbolg city in the north that connects into the Barrow Deeps raid.", topic = "lore_bosses" }
add{ q = { "moonglade lore", "nighthaven", "what is moonglade", "moonglade story?", "moonglade backstory", "nighthaven lore", "what is going on in moonglade", "moonglade druids", "what is the story of moonglade and why druids go there", "why do druids all go to moonglade" }, a = "Moonglade is a sacred druid valley under Keeper Remulos, with Nighthaven its town. It's neutral, druids can teleport there, and Timbermaw tunnels connect it to Felwood and Winterspring.", src = "classic", topic = "lore_bosses" }
add{ q = { "what happened at mount hyjal", "hyjal history", "battle of mount hyjal", "hyjal story?", "hyjal backstory", "battle of mount hyjal lore", "what happened at hyjal", "archimonde hyjal", "what is the story of the battle of mount hyjal against archimonde", "mount hyjal history" }, a = "In Warcraft III Archimonde marched up Hyjal to drain the Well of Eternity under Nordrassil. Orcs, humans and night elves held the line until the wisps destroyed him, but the blast hurt Nordrassil and cost the night elves their immortality. Malfurion then sealed the mountain. In Forever, Hyjal opens as a level 60 zone where Nordrassil's power is waning.", topic = "lore_bosses" }
add{ q = { "riverglades history", "what happened in riverglades", "sunnyglade", "siege of farholde", "riverglades backstory", "siege of farholde lore", "sunnyglade lore", "what is going on in riverglades", "what is the story of sunnyglade and the siege of farholde", "riverglades lore" }, a = "The Old Horde raided Sunnyglade in the First War; survivors founded Windstead, and knights founded Meadowsbrook and Farholde Keep. After the Second War, Twilight's Hammer ogres and Stormreaver orcs moved in. The Horde later besieged Farholde, the Brotherhood of the Horse killed their leaders, and the rest retreated to Krol'dok Stronghold. Now the Bolder'ok ogres side with the Horde.", topic = "lore_bosses" }
add{ q = { "shen'dralas story", "what is shen'dralas about", "shendralas lore", "shen'dralas backstory", "shen'dralas history", "what is going on in shen'dralas", "what is the shendralas storyline", "what is the story of the new shen'dralas zone", "shen dralas lore" }, a = "Shen'dralas, between Desolace, Feralas and Mulgore, is a contested 40ish zone about the Shen'dralar Highborne of Dire Maul and the Magram, Gelkis and Kolkar centaur, with the Bristleback quilboar too. Its areas include Magram Front, Outcast Hideaway, Evenshade Overlook and the Valley of Bones. The wiki has little story detail yet.", topic = "lore_bosses" }
add{ q = { "zephras isle story", "skyborne starting zone story", "zephras isle lore", "zephras story?", "zephras isle backstory", "zephras isle history", "what is going on on zephras isle", "skyborne zone story", "what is the story of zephras isle and the skyborne", "just started on zephras isle what is going on here" }, a = "Zephras Isle is the Skyborne's floating home in Skywall, lifted by wind spirits long ago. With the spirits gone, the isle's pylons fail and the Al'Aketh cult courts Al'Akir. The campaign ends fighting Rohash, Lord of the East Wind, as Alliance and Horde arrive, and you leave from the Valanaar skydocks.", topic = "lore_bosses" }
add{ q = { "i want to turn in deadwood ritual totem", "where do i turn in deadwood ritual totem", "deadwood ritual totem kernda location", "who takes the deadwood totem", "DEADWOOD RITUAL TOTEM WHERE", "deadwood totem turn in", "who do i give the deadwood ritual totem to", "where is kernda", "got a deadwood ritual totem drop what do i do with it", "deadwood totem kernda timbermaw hold", "deadwod ritual totem who takes it", "i looted a deadwood ritual totem in felwood where does it go" }, a = "The totem goes to Kernda inside Timbermaw Hold, and you must be Neutral with Timbermaw first.\n1. Go to the Timbermaw tunnel at the far north of Felwood (around 64,10, where Nafien stands).\n2. Walk into the cave and follow it to the large central chamber.\n3. Kernda is in the middle of the hold, standing under the wooden bridge. Gorn One Eye and the quartermaster Meilosh are in the same cave.\n4. Right-click the totem in your bags if you haven't started the quest, then hand it in. Reward is potions, XP and Timbermaw rep.", src = "classic", topic = "practical" }
add{ q = { "im unfriendly it says it should work but i cant find kernda", "im unfriendly with timbermaw cant turn in totem", "why cant i talk to the furbolgs in timbermaw hold", "timbermaw npcs wont talk to me", "unfriendly timbermaw what can i do", "cant find kernda unfriendly", "timbermaw furbolgs wont talk to me", "why wont kernda talk to me", "im unfriendly can i turn in the totem yet", "need neutral for kernda?", "unfriendly with timbermaw and i cant hand anything in", "timbermaw npc wont show quest" }, a = "Unfriendly only stops the Timbermaw guards attacking you, so you can walk through the tunnel. Talking to Kernda and handing in either Ritual Totem needs Neutral. Kill Deadwood furbolgs in north Felwood (Felpaw Village, Deadwood Village) or Winterfall furbolgs in Winterspring until your Timbermaw bar reads Neutral, then go back to Kernda under the bridge in the middle of the cave. Keep the totem in your bags meanwhile; it doesn't expire.", src = "classic", topic = "practical" }
add{ q = { "timbermaw rep what does each level unlock", "timbermaw hostile unfriendly neutral", "when can i go through timbermaw tunnel", "timbermaw reputation requirements", "timbermaw rep guide", "timbermaw rep levels", "what does timbermaw unfriendly do", "when do timbermaw guards stop attacking", "what rep do i need for timbermaw tunnel", "timbermaw neutral what unlocks", "what does each timbermaw reputation level let me do", "timbermaw hostile to neutral" }, a = "Classic rules for Timbermaw Hold: you start Hostile, so the furbolgs in the tunnel attack you. Unfriendly lets you pass the tunnel and reach Salfa on the Winterspring side. Neutral lets you talk to everyone inside and unlocks the Deadwood and Winterfall Ritual Totem turn-ins with Kernda. Friendly opens Meilosh's recipes and the one-time 30 Runecloth turn-in. Exalted unlocks The Root of All Evil from Gorn One Eye for the Defender of the Timbermaw trinket.", src = "classic", topic = "practical" }
add{ q = { "fastest way to get timbermaw unfriendly", "how to farm timbermaw rep", "best place to grind timbermaw", "timbermaw rep farm spot", "deadwood furbolgs where", "timbermaw rep grind", "best place to farm timbermaw rep", "where do i kill furbolgs for timbermaw", "deadwood camps felwood", "winterfall furbolgs rep farm", "whats the fastest way to get timbermaw rep from hostile", "timbermaw rep farm" }, a = "Kill furbolgs from the two enemy tribes. In Felwood the Deadwood camps are Deadwood Village and Felpaw Village in the north, plus Jadefire Run area camps. In Winterspring the Winterfall camps are Timbermaw Post, Frostfire Hot Springs and Winterfall Village east of Everlook. Normal furbolgs give 5 rep each in Classic, the named chiefs (Overlord Ror, Chieftain Bloodmaw) give more. Save the Deadwood Headdress Feathers and Winterfall Spirit Beads they drop for turn-ins.", src = "classic", topic = "practical" }
add{ q = { "where is grazle", "grazle felwood location", "timbermaw ally quest", "feathers for grazle where", "grazle where?", "where do i find grazle in felwood", "how do i find the friendly furbolg grazle", "grazle is on the road at the south end of felwood right", "who is grazle and where does he stand", "im alliance looking for grazle to start timbermaw quests where is he", "cant find grazle anywhere" }, a = "Grazle is a friendly furbolg at the south end of Felwood, on the road by the Emerald Sanctuary (about 50,84). He gives Timbermaw Ally and takes Deadwood Headdress Feathers in stacks of 5 as a repeatable rep turn-in. Talking to him sends you north to Nafien.", src = "classic", topic = "practical" }
add{ q = { "where is nafien", "speak to nafien", "nafien felwood", "deadwood of the north quest", "nafien where?", "where do i find nafien in felwood", "is nafien outside timbermaw hold", "who gives deadwood of the north quest", "nafien timbermaw hold entrance felwood side", "im trying to start the timbermaw quests where is nafien standing", "cant find nafien" }, a = "Nafien waits just outside the Felwood entrance of Timbermaw Hold in the far north of Felwood (about 64,10), together with Ferli. He gives Deadwood of the North, takes 5-feather turn-ins, and then sends you through the tunnel to Salfa in Winterspring (Speak to Salfa). You must be at least Unfriendly to walk the tunnel safely.", src = "classic", topic = "practical" }
add{ q = { "where is salfa", "speak to salfa", "salfa winterspring", "beads for salfa", "winterfall activity quest", "salfa where?", "where do i find salfa in winterspring", "who takes the winterfall beads", "is salfa at the winterspring exit of the tunnel", "salfa winterfall activity quest giver", "i have winterfall spirit beads where is salfa to turn them in", "cant find salfa" }, a = "Salfa stands right outside the Winterspring exit of the Timbermaw tunnel. Take the tunnel from north Felwood and keep to the branch that heads east-southeast. Salfa gives Winterfall Activity (kill Winterfall furbolgs) and takes Winterfall Spirit Beads in stacks of 5 for repeatable rep.", src = "classic", topic = "practical" }
add{ q = { "winterfall ritual totem", "where does winterfall ritual totem drop", "high chief winterfall totem", "winterfall totem", "where does the winterfall ritual totem drop", "high chief winterfall location", "winterfall ritual totem quest", "who drops the winterfall ritual totem", "where do i kill high chief winterfall for the totem", "winterfall totem drop" }, a = "The Winterfall Ritual Totem is linked to High Chief Winterfall, who lives at the back of Winterfall Village east of Everlook in Winterspring. Like the Deadwood one, it is turned in to Kernda in the middle of Timbermaw Hold, and you need Neutral with Timbermaw to do it.", src = "classic", topic = "practical" }
add{ q = { "meilosh where", "timbermaw quartermaster", "timbermaw runecloth turn in", "timbermaw recipes vendor", "where is the timbermaw quartermaster", "who sells timbermaw recipes", "where do i turn in runecloth for timbermaw rep", "meilosh is inside timbermaw hold right", "im friendly with timbermaw now where do i buy the patterns", "timbermaw vendor location" }, a = "Meilosh, the Timbermaw quartermaster, is on the lower levels inside the Timbermaw Hold cave. At Friendly he sells recipes such as Transmute Earth to Water, Enchant 2H Weapon - Agility, Warbear Harness and Warbear Woolies. He also takes a one-time turn-in of 30 Runecloth (and 2 Mooncloth for tailors) for 100 rep each.", src = "classic", topic = "practical" }
add{ q = { "how to get from felwood to winterspring", "felwood to winterspring route", "how do i get to winterspring", "winterspring path", "felwood to winterspring", "winterspring route", "path from felwood to winterspring", "how do you get through to winterspring from felwood", "timbermaw tunnel to winterspring", "fastest way to winterspring" }, a = "On foot:\n1. Ride to the far north of Felwood, past Talonbranch Glade, to the Timbermaw Hold cave where Nafien stands.\n2. Make sure you're at least Unfriendly with Timbermaw, or use stealth or invisibility.\n3. Inside, cross the bridge and take the east-southeast tunnel. The north tunnel goes to Moonglade.\n4. You exit next to Salfa in Winterspring. Follow the road east to Everlook and grab the flight path.", src = "classic", topic = "practical" }
add{ q = { "how do i get to moonglade", "moonglade access", "moonglade from felwood", "how to reach nighthaven", "moonglade how", "how do i get to moonglade if im not a druid", "path to moonglade through timbermaw", "how to get to nighthaven", "moonglade walk in from felwood", "im a warrior how do i reach moonglade for a quest", "can anyone get to moonglade" }, a = "Druids can just cast Teleport: Moonglade. Everyone else walks in through Timbermaw Hold: enter from north Felwood, then take the north tunnel instead of the Winterspring one. It comes out in Moonglade near Nighthaven. You need at least Unfriendly with Timbermaw to get through safely. Once there, talk to the Nighthaven flight master so you can fly back next time.", src = "classic", topic = "practical" }
add{ q = { "felwood flight path", "where is felwood flight master", "bloodvenom post flight", "talonbranch glade fp", "felwood fp?", "where is the flight path in felwood", "talonbranch glade flight master", "bloodvenom post fp horde", "felwood flight points alliance and horde", "i just got to felwood where do i grab the flight path", "felwood flight master location" }, a = "Classic Felwood has two flight points. Alliance use Talonbranch Glade in the northeast near the Timbermaw tunnel. Horde use Bloodvenom Post in the middle-west of the zone. The Emerald Sanctuary in the south has no flight master. Both connect to Everlook in Winterspring once you have discovered it.", src = "classic", topic = "practical" }
add{ q = { "felwood corrupted plants how to cleanse", "cenarion plant salve", "songflower how to get", "whipper root windblossom felwood", "cleansing felwood quest", "cleansing felwood", "how to cleanse felwood plants", "how do i get songflower", "felwood corrupted plants", "whipper root and windblossom", "how do i use the corrupted plants in felwood for buffs" }, a = "Classic setup: do Cleansing Felwood (level 55). Alliance get it from Arathandris Silversky, Horde from their Felwood counterpart. You collect 15 Blood Amber from Warpwood elementals in the Irontree Caverns north of the quest hub. That unlocks the repeatable Salve via Gathering/Mining/Skinning/Hunting/Disenchanting turn-ins, each giving Cenarion Plant Salve. Use a salve on a corrupted plant (Whipper Root, Windblossom, Songflower, Night Dragon's Breath) to cleanse it, then loot the fruit or buff.", src = "classic", topic = "practical" }
add{ q = { "emphasis on sacrifice quest", "emphasis on sacrifice", "where is high priest rohan", "rohans exorcism censer", "where do i find high priest rohan", "how do i start emphasis on sacrifice", "first gold step of the charger quest", "what do i do with rohans exorcism censer", "im a 60 pally starting the charger chain where is high priest rohan", "rohan ironforge paladin" }, a = "Emphasis on Sacrifice is the first gold step of the Alliance paladin Charger chain.\n1. Get it from Lord Grayson Shadowbreaker in the western part of the Cathedral of Light in Stormwind.\n2. Take the Deeprun Tram to Ironforge and go to the Hall of Mysteries in the Mystic Ward.\n3. Pay High Priest Rohan 150g for Rohan's Exorcism Censer.\n4. Take To Show Due Judgment back to Lord Grayson, then start Exorcising Terrordale.", class = "PALADIN", src = "classic", topic = "practical" }
add{ q = { "paladin epic mount quest", "how to get charger", "summon charger quest chain", "pally 60 mount steps", "charger questline", "charger quest?", "how do i get my paladin epic mount", "pally charger questline steps", "how much gold does the charger quest cost", "paladin 60 mount quest guide", "just hit 60 on my pally how do i get the charger", "what are all the steps for summon charger" }, a = "Alliance Charger (Classic chain, about 350g in fees plus mats):\n1. Lord Grayson Shadowbreaker, Cathedral of Light, Stormwind starts it.\n2. Emphasis on Sacrifice: pay High Priest Rohan in Ironforge 150g for the censer.\n3. Exorcising Terrordale: kill 25 Terrordale Spirits in Eastern Plaguelands.\n4. The Work of Grimand Elmore: 150g, 6 Arcanite Bars, 10 Arthas' Tears, 40 Runecloth, 5 Stratholme Holy Water.\n5. Ancient Equine Spirit: 50g + 20 Enriched Manna Biscuits to Merideth Carlson in Southshore, then kill Tendris in DM West.\n6. Divination Scryer: Azerothian Diamond + Pristine Black Diamond.\n7. Judgment and Redemption: Scholomance waves and Death Knight Darkreaver.", class = "PALADIN", src = "classic", topic = "practical" }
add{ q = { "exorcising terrordale", "terrordale spirits where", "where do i use the censer", "terrordale paladin", "terrordale spirits", "where to use exorcism censer", "terrordale paladin quest", "where are the terrordale spirits", "how do i do the exorcising terrordale quest", "terrordale censer" }, a = "Buy 20 Enriched Manna Biscuits first from the Argent Dawn quartermaster at Light's Hope Chapel (you need Friendly). You'll need them for a later step. Then head to the northwest of Eastern Plaguelands, past the Stratholme entrance and west into Terrordale. Use Rohan's Exorcism Censer on the glowing green patches. Each use calls 1-3 Terrordale Spirits. Kill 25 and return to Lord Grayson in Stormwind.", class = "PALADIN", src = "classic", topic = "practical" }
add{ q = { "divination scryer scholomance", "judgment and redemption darkreaver", "darkreaver seals which seal", "charger scholomance event", "darkreaver how?", "how do i summon darkreaver in scholomance", "which seal do i use for darkreaver", "divination scryer scholo", "judgment and redemption quest steps", "were in scholo for my pally charger how do we start the darkreaver event", "darkreaver seal order" }, a = "In Scholomance, clear to Rattlegore, then open Lord Grayson's Satchel in the empty room for the Divination Scryer. Use it in the room's centre. Four waves come, each weak to one seal: Banal Spirits to Wisdom, Malicious to Justice, Corrupted to Righteousness, Shadowed to Light. Then Death Knight Darkreaver appears. Dispel his mind control fast. Loot Charger's Lost Soul, use it on his fallen charger, and hand the quest to the charger to learn Summon Charger.", class = "PALADIN", src = "classic", topic = "practical" }
add{ q = { "ancient equine spirit", "merideth carlson southshore", "manna enriched horse feed", "tendris warpwood horse spirit", "equine spirit quest", "where is merideth carlson", "how do i get the ancient equine spirit", "manna enriched horse feed where to use", "tendris warpwood horse spirit drop", "i killed tendris warpwood now what do i do with the horse spirit", "southshore horse lady charger" }, a = "Ancient Equine Spirit costs 50g plus 20 Enriched Manna Biscuits. Hand both to horse breeder Merideth Carlson in Southshore to get the Manna-Enriched Horse Feed. Then run Dire Maul West, kill Tendris Warpwood, and the Ancient Equine Spirit appears. Talk to it to finish the step, then take Blessed Arcanite Barding back to Stormwind.", class = "PALADIN", src = "classic", topic = "practical" }
add{ q = { "paladin level 40 mount quest", "tome of nobility", "free paladin mount", "summon warhorse quest", "pally mount 40", "free pally mount?", "how do paladins get the free mount at 40", "tome of nobility quest", "summon warhorse paladin", "where do i get the warhorse quest", "my pally just hit 40 do i have to buy a mount or is it free", "paladin warhorse" }, a = "Alliance paladins get a free 40 mount from The Tome of Nobility. Pick it up at the Cathedral of Light in Stormwind (Duthorian Rall), or follow the breadcrumb from the Mystic Ward in Ironforge. It's a one-step quest with no fee, and it teaches Summon Warhorse, so you skip the 100g race mount. Undead (Forsaken) paladins have their own Warhorse quest through Bandarion Keep.", class = "PALADIN", topic = "practical" }
add{ q = { "undead paladin where to start", "forsaken paladin class quests", "bandarion keep where", "whispering wood tirisfal", "undead pally?", "where do forsaken paladins train", "how do i start the forsaken paladin quests", "where is bandarion keep", "forsaken paladin hub whispering wood", "i rolled an undead paladin where do i go for class quests", "undead paladin trainer" }, a = "Forsaken paladins are new in Forever. Their hub is Bandarion Keep in Whispering Wood, a part of Tirisfal Glades that used to be closed off. Most of their class quests start there. A Second Home sends you to find the keep and report to Breton Samuels. Their level 40 Warhorse and level 60 Forsaken Charger come from their own chain, themed on Retribution rather than the Alliance Redemption path.", class = "PALADIN", topic = "practical" }
add{ q = { "paladin redemption quest", "tome of divinity", "a lesson in divinity", "pally level 12 quest", "how do i learn redemption", "paladin res spell quest", "tome of divinity where", "a lesson in divinity quest", "pally 12 class quest", "my paladin is 12 how do i get the resurrection spell", "redemption pally quest" }, a = "Redemption is learned at level 12 from a class quest. Humans and dwarves do The Tome of Divinity from their paladin trainer. Undead paladins do the new A Lesson in Divinity, which starts with Danitha Morr at Bandarion Keep in Whispering Wood (Tirisfal) and runs through Tanis Alderwood and Deathguard Billmuth.", class = "PALADIN", topic = "practical" }
add{ q = { "verigans fist quest", "paladin level 20 weapon quest", "wolfsbane undead paladin", "test of righteousness", "how do i get verigans fist", "is verigans fist worth it", "paladin 20 quest weapon", "test of righteousness quest steps", "verigans fist undead paladin wolfsbane", "my pally is 20 should i do the verigans fist quest", "verigans fist" }, a = "At level 20 Alliance paladins can build Verigan's Fist through The Test of Righteousness, which starts with Jordan Stilwell outside Ironforge. Undead paladins get a different Forever chain that has you hunt a worgen for Wolfsbane (Old Fire Eye). Sources disagree on whether it opens at 18 or 20.", class = "PALADIN", topic = "practical" }
add{ q = { "warlock epic mount quest", "dreadsteed quest chain", "how to get dreadsteed", "lock 60 mount steps", "dreadsteed?", "how do i get the dreadsteed", "warlock epic mount quest steps", "dreadsteed questline forever", "lock 60 mount how to start", "just hit 60 on my lock how do i start the dreadsteed", "how long does dreadsteed take" }, a = "Dreadsteed chain (Forever, level 60):\n1. Your demon trainer gives Mor'zul Bloodbringer. Find Mor'zul at the Altar of Storms, Burning Steppes (about 12.7,31.6). Gorzeeki Wildeyes stands next to him.\n2. Rage of Blood: 30 Raging Beast's Blood from Winterspring owlbeasts.\n3. Felwood branch: Lord Banehollow (Shadowy Potion to enter Shadow Hold), kill Ulathek, buy Xorothian Stardust from Ur'dan.\n4. Gorzeeki's three tools: 10 Elixir of Shadow Power; 6 Large Brilliant Shard + 25 Dark Iron Ore; 35 Black Dragonscale.\n5. Imp Delivery to the Scholomance alchemy lab, then 3 Arcanite Bars.\n6. Dreadsteed of Xoroth: summoning ritual in Dire Maul West with a group.", class = "WARLOCK", topic = "practical" }
add{ q = { "mor'zul bloodbringer where", "altar of storms warlock", "gorzeeki wildeyes location", "morzul where?", "where is mor'zul bloodbringer", "how do i get to the altar of storms", "where is gorzeeki wildeyes", "morzul bloodbringer dreadsteed start", "i got the dreadsteed quest from my trainer where is mor'zul", "gorzeeki location burning steppes" }, a = "Mor'zul Bloodbringer is at the Altar of Storms in the far northwest of Burning Steppes, around 12.7,31.6. Gorzeeki Wildeyes is right beside him at about 12.4,31.6. Take Mor'zul Bloodbringer from your warlock trainer first. The Orgrimmar and Ironforge trainers offer it.", class = "WARLOCK", topic = "practical" }
add{ q = { "lord banehollow shadow hold", "how to get into shadow hold felwood", "shadowy potion warlock", "ulathek the traitor", "banehollow where?", "how do i get to lord banehollow", "shadowy potion for shadow hold", "where is ulathek the traitor", "i need to talk to lord banehollow deep in jaedenar how do i get there", "banehollow location" }, a = "Lord Banehollow is deep inside Shadow Hold in Jaedenar, Felwood. Drink a Shadowy Potion before you go in so the demons and cultists don't attack you. Banehollow sends you to kill Ulathek the Traitor and bring back his heart. Then buy Xorothian Stardust from Ur'dan near Banehollow and take it to Gorzeeki in Burning Steppes.", class = "WARLOCK", topic = "practical" }
add{ q = { "dreadsteed arcanite how many", "dreadsteed mats list", "what do i need for dreadsteed", "dreadsteed mats?", "what mats do i need for dreadsteed", "how much arcanite for dreadsteed", "dreadsteed materials list forever", "dreadsteed shopping list", "what should i buy off the ah before starting dreadsteed", "dreadsteed items needed" }, a = "Shopping list for Dreadsteed in Forever: 30 Raging Beast's Blood (farm Winterspring owlbeasts), 10 Elixir of Shadow Power, 6 Large Brilliant Shard, 25 Dark Iron Ore, 35 Black Dragonscale, 3 Arcanite Bar (Forever needs 3, not 1), at least one Shadowy Potion, and the Xorothian Stardust. Old Classic guides put the Stardust at 150g. Bring Soul Shards too: the Black Lodestone uses them to restart failed ritual nodes.", class = "WARLOCK", topic = "practical" }
add{ q = { "warlock level 40 mount", "summon felsteed quest", "strahad farsan ratchet", "felsteed didnt give riding skill", "felsteed quest?", "how do warlocks get the free mount at 40", "summon felsteed where", "strahad farsan ratchet quest", "felsteed didnt give me riding", "my lock hit 40 do i get a free mount or do i buy one", "warlock felsteed 40" }, a = "Warlocks of both factions get a free level 40 Felsteed. Take Summon Felsteed from your class trainer and finish it with Strahad Farsan in Ratchet. In Forever, finishing it also gives Apprentice Riding, so you skip the 100g training. If you finished it before the Nov 9 hotfix and have no riding skill, summon the Felsteed once and the skill is granted.", class = "WARLOCK", topic = "practical" }
add{ q = { "infernal quest", "summon infernal niby", "doomguard quest", "ritual of doom quest", "inferno quest?", "how do i learn inferno", "how do i get doomguard", "what niby commands quest", "niby the almighty felwood", "how do warlocks get the infernal and the doomguard spells", "ritual of doom how" }, a = "Inferno: Niby the Almighty in central Felwood starts What Niby Commands. Collect Flawless Fel Essence from Azshara, Jaedenar and the Dark Portal area, then finish to the north. Ritual of Doom: Daio the Decrepit in the northwest Tainted Scar, Blasted Lands. Kill satyrs in DM East, kill Hederine demons in Darkwhisper Gorge (south Winterspring) for Tears of the Hederine, then bind a Doomguard Commander at the Glowing Crystal Prison.", class = "WARLOCK", src = "classic", topic = "practical" }
add{ q = { "shaman fire totem quest", "call of fire dwarf", "shaman level 10 quest", "fire totem quest alliance", "fire totem quest?", "how do i get my fire totem", "call of fire quest", "shaman lvl 10 quest", "dwarf shaman fire totem", "my shaman is 10 how do i get the fire totem", "where do shamans get fire totem" }, a = "Dwarf shaman Call of Fire (10):\n1. Get it from a shaman trainer, then find Bruegs Kindleborn in a cave on Dun Morogh's eastern edge (path near 86.7,47.0, behind a farm).\n2. Take the Torch of the Dormant Flame to Braldir Ashmantle in Loch Modan (32.0,66.3).\n3. Get Fire Tar from Tunnel Rat Geomancers in Silver Stream Mine and a Reagent Pouch from Stonesplinter Seers.\n4. Drink the Fire Sapta at the Fire Spirit Stone (31.9,64.5) and kill the Minor Manifestation of Fire.\n5. Return the Torch of Eternal Flame to Bruegs for your Fire Totem. In Forever the quest also gives the Totem of Charged Flames.", class = "SHAMAN", topic = "practical" }
add{ q = { "shaman earth totem quest dwarf", "call of earth teo hammerstorm", "dwarf shaman first totem", "earth totem quest?", "how do i get my earth totem", "call of earth quest", "where is teo hammerstorm", "dwarf shaman first totem quest", "my dwarf shaman is 4 how do i get the earth totem", "earth totem dwarf" }, a = "Dwarf Call of Earth (level 4): talk to Teo Hammerstorm in Anvilmar (28.8,66.2). Loot 2 Iceclaw Bear Pendants from Frostmane Troll Whelps around 27,79. Take the Earth Sapta up the rubble path (starts near 25.8,69.3) to the Earth Spirit Stone at 25.0,62.4. Drink it, talk to the Minor Manifestation of Earth and bring the Rough Quartz back to Teo for the Earth Totem and Stoneskin Totem.", class = "SHAMAN", topic = "practical" }
add{ q = { "shaman water totem quest dwarf", "call of water hervdana", "waterskin quest shaman alliance", "shaman level 20 quest alliance", "water totem quest?", "how do i get my water totem", "call of water quest", "where is hervdana", "dwarf shaman water totem", "my shaman is 20 how do i get the water totem", "shaman 20 quest alliance" }, a = "Dwarf Call of Water (20):\n1. Trainer quest to Norric Lochthane, Loch Modan (41.9,19.0).\n2. Hervdana Saegrund's cave behind a waterfall in the Wetlands (65.7,76.4): fill the brown waterskin at her waterfall.\n3. Fill the red one at Stonewatch Falls lake, Redridge (73.7,61.6).\n4. Fill the blue one at the lake near Astranaar, Ashenvale (37.0,51.6). Take the Menethil boat to Auberdine from the north pier and don't get off at Southshore.\n5. Drink the Water Sapta at the Forgotten Shrine by Stendel's Pond, Westfall (47.5,60.4). Kill the corrupt manifestation, turn in the bracers, then swim to the new manifestation.\n6. Bring the Shard of Water to Norric for the Water Totem.", class = "SHAMAN", topic = "practical" }
add{ q = { "shaman air totem quest", "call of air", "shaman level 30 quest", "veyric thundervein", "air totem quest?", "how do i get my air totem", "call of air quest", "where is veyric thundervein", "shaman lvl 30 quest", "my shaman is 30 how do i get the air totem", "air totem shaman" }, a = "Call of Air (30), dwarf version: get it from a shaman trainer and find Veyric Thundervein in Arathi Highlands (59.8,27.6). Start by the floating Shard of Myzrael and take the narrow path from about 60.5,35.2 up the rocks near 60.5,31.5. Talking to him finishes it and gives the Air Totem. In Forever, Call of Air also opens the shaman weapon quest Rage of the Storm. Orc, troll and tauren shamans still use the Classic totem chains.", class = "SHAMAN", topic = "practical" }
add{ q = { "skipped a totem quest totems greyed out", "why are my fire totems grey", "missing totem item shaman", "totems greyed out", "why are my totems grey", "missing totem item", "my fire totems are grayed out what do i do", "skipped a totem quest", "i cant cast my water totems because i skipped the quest", "totem spells unusable" }, a = "Each element's totem spells need that element's totem item in your bags. If you skipped Call of Earth, Fire, Water or Air, every totem of that element stays greyed out until you do the quest and get the item. Do the matching quest from any shaman trainer to fix it.", class = "SHAMAN", topic = "practical" }
add{ q = { "druid cure poison quest", "lessons anew", "power over poison", "druid level 14 quest", "cure poison druid", "how do i get cure poison", "lessons anew quest", "power over poison quest", "druid lvl 14 quest", "my druid is 14 how do i learn cure poison", "druid poison quest" }, a = "Cure Poison (14) is the Lessons Anew chain: Lessons Anew, then The Principal Source, then Gathering the Cure, then Power over Poison, which teaches the spell. Night elves start it in Darnassus, tauren in Thunder Bluff. Skyborne druids have been able to do it since the Nov 2 build.", class = "DRUID", topic = "practical" }
add{ q = { "druid aquatic form quest", "aquatic form forever", "druid level 16 quest", "idol of shifting tides", "aquatic form quest?", "how do i get aquatic form", "druid lvl 16 quest", "druid aquatic form forever", "my druid is 16 how do i get seal form", "aquatic form chain" }, a = "Aquatic Form at 16 is a short chain that starts with your druid trainer (A Lesson to Learn for Skyborne) and runs through Moonglade. In Forever the reward is a choice that includes the new Idol of Shifting Tides, which lowers shapeshift mana costs. Travel Form (30) and Dire Bear (40) are still trained, no quest.", class = "DRUID", topic = "practical" }
add{ q = { "skyborne druid bear form", "great ursera spirit", "strength and mercy quest", "urendra cave", "skyborne bear form?", "how do skyborne druids get bear form", "where is the great ursera spirit", "strength and mercy quest steps", "where is urendra cave on zephras", "my skyborne druid is 10 how do i get bear form", "skyborne druid lvl 10 quest" }, a = "Skyborne Bear Form (10) on Zephras Isle:\n1. The Great Ursera Spirit from Lotheluum Starbreeze in Valanaar (64.0,75.1).\n2. Go to Urs'endris on the small east-side island (69.8,61.7) and take Strength and Mercy.\n3. Kill the maddened Ur'endra in a hilltop cave in the Shen'dar Highlands, south-central Zephras (about 53.9,65.4).\n4. Return to Urs'endris for Bear Form, Growl and Maul.", class = "DRUID", topic = "practical" }
add{ q = { "rhokdelar quest", "hunter epic bow quest", "an introduction hunter 60", "rhokdelar?", "hunter epic bow", "how do i get rhokdelar", "an introduction hunter quest", "hunter 60 quest", "my hunter just hit 60 how do i start the epic bow quest", "do hunters have class quests" }, a = "Hunters have no class quests between 10 and 60. At 60, An Introduction starts the Rhok'delar, Longbow of the Ancient Keepers chain. Its key parts drop in Molten Core.", class = "HUNTER", topic = "practical" }
add{ q = { "rogue poisons quest alliance", "mathias and the defias", "klaven's tower", "how do rogues learn poisons", "rogue poisons ally?", "how do alliance rogues learn poisons", "mathias and the defias quest steps", "where is klavens tower", "rogue lvl 20 poison quest alliance", "my rogue is 20 how do i learn poisons as alliance", "poison quest ally rogue need lockpicking?" }, a = "Alliance poisons (20, needs 80 Lockpicking):\n1. Mathias and the Defias from Master Mathias Shaw, Old Town, Stormwind.\n2. Go to Klaven's Tower east of Sentinel Hill, Westfall, and take Klaven's Tower from Agent Kearnen.\n3. Pickpocket the Malformed Defias Drone for the tower key. Don't fight it.\n4. Climb the tower, sap Klaven Mortwake and pick the chest. It gives you Touch of Zanzil.\n5. Turn in at Stormwind for Poisons and Thistle Tea. Clear Zanzil with Anti-Venom, a druid or shaman, or Doc Mixilpixil's quest.", class = "ROGUE", topic = "practical" }
add{ q = { "rogue poisons quest horde", "mission possible but not probable", "the shattered salute", "taskmaster fizzule", "deep cover rogue", "rogue poisons horde?", "how do horde rogues learn poisons", "where is taskmaster fizzule", "shattered salute quest steps", "rogue lvl 20 poison quest horde", "my rogue is 20 how do i learn poisons as horde its so hard", "mission possible but not probable help" }, a = "Horde poisons (20, harder):\n1. The Shattered Salute from Shenthul, Cleft of Shadow, Orgrimmar. Use /salute.\n2. Deep Cover: go to the Sludge Fen, northeast Barrens. Fire the Flare Gun twice near Taskmaster Fizzule east of the Venture tower, then salute him.\n3. Mission: Possible But Not Probable: pickpocket Foreman Silixiz for the key, clear the tower, kill Grand Foreman Puzik Gallywix and pick his lockbox.\n4. Back to Shenthul, then Hinott's Assistance: zeppelin to Tirisfal and travel to Serge Hinott in Tarren Mill to learn Poisons.\nRestarting the mission was bugged until the Nov 9 hotfix.", class = "ROGUE", topic = "practical" }
add{ q = { "rogue new quests forever", "syndicate sabotage", "ruby adorned blade", "horn of xelthos", "new rogue quests?", "what new rogue quests are in forever", "how do i start syndicate sabotage", "how do i get the ruby adorned blade", "what is the horn of xelthos", "did forever add any new class quests for rogues at ravenholdt", "rogue quests forever list" }, a = "Forever adds rogue content. Syndicate Sabotage (24) is a Ravenholdt chain that pays gold and rep, not a spell. A level 23 spy chain starts with The Horn of Xelthos and ends with the Ruby-Adorned Blade from Scarlet Monastery.", class = "ROGUE", topic = "practical" }
add{ q = { "priest racial quest", "priest level 10 quest", "priest level 20 quest", "how to get desperate prayer", "how do i get desperate prayer", "priest lvl 10 quest", "priest 20 quest", "priest racial spells", "my priest is 10 how do i get my racial spell", "priest class quests" }, a = "Priest racial spells come from quests at 10 and 20, ending with a trainer in your capital. Human: Divine Grace (new) then Feedback. Dwarf: Desperate Prayer then Chastise. Gnome: Confounding Flash then Contingency Plan (both new). Night elf: Starshards then Elune's Grace. Troll: Hex of Weakness then Shadowguard. Undead: Touch of Weakness then Dark Sacrifice.", class = "PRIEST", topic = "practical" }
add{ q = { "marshal windsor quest", "where is marshal windsor", "onyxia attunement alliance", "ony attune alliance steps", "windsor where?", "where do i find marshal windsor", "how do alliance start ony attunement", "marshal windsor brd quest", "ony attune alliance first step", "im alliance where do i find marshal windsor for the onyxia chain", "alliance ony attune guide" }, a = "Alliance Onyxia attunement:\n1. Dragonkin Menace from Helendis Riverhorn in Burning Steppes, then The True Masters through Stormwind, ending at Marshal Maxwell at Morgan's Vigil.\n2. Marshal Windsor: find him in his cell in Blackrock Depths, then report back (Abandoned Hope).\n3. A Crumpled Up Note drops from BRD mobs. Bring it to Windsor.\n4. A Shred of Hope: get his notes from Golem Lord Argelmach and General Angerforge.\n5. Jail Break!: escort Windsor out of BRD.\n6. Stormwind Rendezvous: talk to Squire Rowe at the Stormwind gate.\n7. The Great Masquerade, then The Dragon's Eye and Drakefire Amulet: kill Drakkisath in UBRS for the Blood of the Black Dragon Champion.", topic = "practical" }
add{ q = { "onyxia attunement horde", "ony attune horde", "rexxar quest desolace", "emberstrife test of skulls", "horde ony attune?", "how do horde start ony attunement", "where is rexxar in desolace", "emberstrife test of skulls steps", "horde onyxia chain first step", "im horde where do i start the onyxia attunement chain", "horde ony attune guide" }, a = "Horde Onyxia attunement:\n1. Warlord Goretooth in Kargath, Badlands: Warlord's Command in LBRS.\n2. Report to Eitrigg and Thrall in Orgrimmar. For the Horde!: kill Rend Blackhand in UBRS.\n3. Find Rexxar, who wanders Desolace, and take his testament to Myranda the Hag in Western Plaguelands.\n4. Oculus Illusions: Black Dragonspawn Eyes for the Amulet of Draconic Subversion.\n5. Wear it to reach Emberstrife in Dustwallow Marsh and do The Test of Skulls (Scryer, Somnus, Chronalis, Axtroz).\n6. Ascension: take the Dull Drakefire Amulet to Rexxar, then kill Drakkisath in UBRS for the blood.", topic = "practical" }
add{ q = { "squire rowe windsor didnt show", "great masquerade not starting", "windsor stormwind event bugged", "windsor didnt spawn", "great masquerade wont start", "squire rowe isnt working", "windsor never showed up at stormwind gates", "stormwind rendezvous bugged", "i talked to squire rowe but windsor never came out what do i do", "windsor event stuck" }, a = "For Stormwind Rendezvous, talk to Squire Rowe just outside the Stormwind city gate and he calls Windsor in. If Windsor isn't there when you return for The Great Masquerade, speak to Rowe again to restart it. Also check the Drakefire Amulet is in your bags at the end. You need it in your inventory to enter Onyxia, not equipped, and each character needs their own.", topic = "practical" }
add{ q = { "tirion fordring quest chain", "where is tirion fordring", "in dreams quest", "of love and family painting", "tirion quest?", "how do i start the tirion fordring chain", "where do i find tirion in eastern plaguelands", "in dreams quest steps", "of love and family painting where", "where does the tirion fordring questline start in the plaguelands", "tirion chain rewards" }, a = "Tirion chain (Classic, faction-neutral):\n1. Find Tirion Fordring in his hut by the Thondoril River, west Eastern Plaguelands. Do Demon Dogs, Blood Tinged Skies and Carrion Grubbage.\n2. Redemption, then Of Forgotten Memories: fight at Tirion's grave in the Undercroft for Taelan's Hammer.\n3. Of Lost Honor: fish the Symbol of Lost Honor out of a pond in Northdale.\n4. Of Love and Family: Artist Renfray at Caer Darrow sends you for the Unfinished Painting in Stratholme's Scarlet Bastion.\n5. Find Myranda, Scarlet Subterfuge, then In Dreams with Taelan in Hearthglen.", src = "classic", topic = "practical" }
add{ q = { "shapers terrace how to unlock", "un'goro crystals what are they for forever", "power crystals forever", "shapers terrace final boss nanaya", "how do i unlock shapers terrace", "un'goro crystals forever", "power crystals what for", "shapers terrace nanaya", "un goro power crystals use", "what are the un'goro crystals used for in forever", "shapers terrace unlock" }, a = "Forever puts Un'Goro's power crystals to work in Shaper's Terrace (58-60). The entrance is on the hill above Marshal's Refuge at 48.1,6.1. To summon the last boss, Nanaya, light all four Archival Panels. Each needs 15 matching crystals in your bags (Red, Blue, Green, Yellow), which you get from the panel bosses: Cinder (red, west mountain), Snowtalon (blue, cave behind a waterfall), Vitrix (green, north cave), Bolt (yellow, south near Venomridge). Then use the Titan Panel on the Pillar of Assimilation.", topic = "practical" }
add{ q = { "shapers terrace quests", "where do i get shapers terrace quests", "curator thorius", "crystalline elements quest", "who gives shapers terrace quests", "where is curator thorius", "shapers terrace quest givers alliance horde", "which quests should i grab before running shapers terrace", "terrace dungeon quests", "where do i pick up quests for the terrace dungeon" }, a = "Pick up Shaper's Terrace quests before you go. Alliance: Curator Thorius in the Hall of Explorers, Ironforge (72.6,14.8), has Mapping the Way Forward and Panic at the Digsite. Horde: Mayena Earthseeker on Sunwatcher Plateau, Mulgore (34.8,22.1) has Crystalline Elements. Chemist Fuely (47.8,72.3) and Master Apothecary Faranell (48.4,68.0) in the Undercity Apothecarium have the rest. Inside, the Partially Digested Journal near the entrance starts Digestible Research.", topic = "practical" }
add{ q = { "un'goro pylons", "jd collie pylons", "northern eastern western pylon", "crystals of power quest", "making sense of it", "un goro pylons?", "how do i do the un'goro pylon quests", "where is jd collie", "where are the three pylons in ungoro", "crystals of power quest steps", "how do i activate the northern eastern and western pylons", "pylon quest chain" }, a = "Classic pylon chain: J.D. Collie at Marshal's Refuge gives Crystals of Power, then the Western, Northern and Eastern Pylon quests. Visit each crystal pylon: north around 56,12, east on the cliff near 77,49 by the graveyard, west around 23,59. Then Making Sense of It (53). Afterwards each pylon has repeatable crystal turn-ins for buff items: Crystal Force and Spire (east), Charge and Restore (north), Ward and Yield (west).", src = "classic", topic = "practical" }
add{ q = { "young diemetradons level 58", "ungoro dinos too high level", "diemetradon bug", "young diemetradons 58", "ungoro dinos too high", "why are the dinos level 58", "un goro mobs too high level", "the young diemetradons in un'goro are level 58 is that a bug", "diemetradon level" }, a = "That was a bug. Young Diemetradons in Un'Goro were spawning at level 58 instead of 51-52, and the Nov 9 hotfix fixed it. If you still see high-level ones, they spawned before the fix and will be replaced when they die.", topic = "practical" }
add{ q = { "cenarion hold where", "how do i get to silithus", "cenarion hold flight path", "silithus quest hub", "cenarion hold?", "where is cenarion hold", "how do i get to silithus from tanaris", "silithus flight path", "cenarion hold flight master", "how do i get to silithus and where is the main quest hub", "silithus hub" }, a = "Cenarion Hold is the Cenarion Circle hub in the middle of Silithus, just below Hive'Ashi. It has a flight point for both factions, repairs and vendors. On foot, Silithus is reached through the western exit of Un'Goro Crater. Grab the Marshal's Refuge flight point in north Un'Goro on the way.", src = "classic", topic = "practical" }
add{ q = { "cenarion circle rep farm", "encrypted twilight texts", "cenarion circle repeatables", "how to get cenarion circle rep", "cc rep?", "how do i get cenarion circle rep fast", "cenarion circle rep farm spot", "encrypted twilight texts turn in", "cc repeatable quests", "what is the fastest way to get cenarion circle rep in silithus", "cenarion circle grind" }, a = "Main Cenarion Circle repeatables in Classic: Encrypted Twilight Texts (100 rep), Mortal Champions (100), Abyssal Crests (50), Abyssal Signets (100), Field Duty (25), plus the three Battlegear quests. Kills: Twilight's Hammer cultists give 1 rep up to Honored, prophets and Twilight Lord Everun give 5 up to Revered. Summoned Templars give 5, Dukes 25, Abyssal Lords 50.", src = "classic", topic = "practical" }
add{ q = { "darkmoon faire where is it", "when is darkmoon faire", "dmf location forever", "darkmoon faire schedule", "dmf where?", "where is the darkmoon faire right now", "is dmf in elwynn or mulgore this month", "when does darkmoon faire open", "darkmoon faire dates", "where is the darkmoon faire this month and when does it open", "dmf schedule" }, a = "The Darkmoon Faire switches each month between Elwynn Forest, just outside Goldshire (about 42,69), and Mulgore, by the Thunder Bluff lift (about 37,38). It opens the Monday after the first Saturday of the month and runs to the following Sunday. Your in-game calendar shows the dates. On PvP realms you're flagged in the enemy faction's zone.", topic = "practical" }
add{ q = { "sayge buff", "dmf damage buff", "which sayge answer for damage", "darkmoon fortune buff", "sayge answers?", "what do i answer sayge for damage", "sayge damage buff answers", "how do i get the darkmoon fortune buff", "dmf buff which answer", "what are the sayge answers for the 10 percent damage buff", "sayge buff options" }, a = "Sayge, the gnoll fortune teller at the Faire, gives a 2-hour buff that you lose on death. It has a 4-hour cooldown and doesn't work in raids. Options are +10% damage, +25 all resistances, +10% armor, or +10% to one of Spirit, Intellect, Stamina, Strength or Agility. Some fortunes also start a quest for a Mysterious Lockbox.", topic = "practical" }
add{ q = { "darkmoon faire tickets", "what to turn in for dmf tickets", "darkmoon storage box", "dmf 14 slot bag", "dmf tickets?", "what can i turn in for darkmoon tickets", "how do i get the darkmoon storage box", "dmf ticket turn ins", "how many tickets for the 14 slot bag", "what can i turn in at the darkmoon faire for tickets", "darkmoon faire ticket items" }, a = "Turn crafted items or beast drops in for tickets. Blacksmiths go to Kerri Hicks, engineers to Rinling, leatherworkers to Chronos, and Yebb Neblegear takes drops. Good ones: 8 Dense Grinding Stone, 6 Thorium Widget, 8 Rugged Armor Kit or 10 Evil Bat Eye each pay 20 tickets (level 40+). Spend them at Gelvas Grimegate. The Darkmoon Storage Box, a unique 14-slot bag, costs 50 tickets.", topic = "practical" }
add{ q = { "darkmoon cards where do they drop", "darkmoon deck ace", "how to make darkmoon trinket", "darkmoon cards?", "where do darkmoon cards drop", "how do i make a darkmoon deck", "how do i get a darkmoon trinket", "darkmoon ace drop", "how do i get the darkmoon cards to build a trinket", "darkmoon card drops" }, a = "A deck is an Ace plus cards 2-8. Numbered cards drop from level 45-60 humanoids and undead. Aces: Beasts from The Beast in UBRS, Elementals from Avalanchion, Hydrospawn, Lord Incendius or The Windreaver, Portals from Darkmaster Gandling, Warlords from King Gordok. Trade the deck to Professor Thaddeus Paleo for the trinket (Blue Dragon, Maelstrom, Twisting Nether, Heroism). Cards and decks are BoE, trinkets BoP.", topic = "practical" }
add{ q = { "jubling pet", "spawn of jubjub", "dark iron ale mug dmf", "jubling", "dark iron ale mug", "how do i get jubling pet", "jubling pet dmf", "how do i get the jubling pet from the darkmoon faire", "jubjub pet" }, a = "Buy two Dark Iron Ale Mugs from Plugger Spazzring in the Grim Guzzler, Blackrock Depths. At the Faire, drop one near Morja to start Spawn of Jubjub, then hand in the second. The egg hatches into Jubling after 7 days. The pet is BoP but the ale isn't.", topic = "practical" }
add{ q = { "dalaran quests forever", "how to get kirin tor rep", "kirin tor reputation", "dalaran rep", "kirin tor rep?", "how do i grind kirin tor rep", "dalaran quests for rep", "kirin tor reputation farm", "best way to get kirin tor rep", "how do i grind kirin tor rep in dalaran as alliance", "kirin tor quests" }, a = "Kirin Tor is an Alliance faction in Forever, based in Dalaran in Alterac Mountains. Most races start Neutral, High Order Skyborne start Friendly. Known quests (about 520 rep total): An Alarming Request (Emissary Jacques, Southshore), Heart of Disruption, Friend of the Kirin Tor (Archmage Celindra, Violet Citadel), Starving Arcane (8 each of Seeking Remnants, Saturated Remnants, Mana Echoes), and Past Due (a book from Scarlet Monastery). No repeatable farm is confirmed yet.", topic = "practical" }
add{ q = { "kirin tor quartermaster", "archmage alvareaux where", "kirin tor rewards", "azure recipes", "kirin tor vendor?", "where is the kirin tor quartermaster", "what does archmage alvareaux sell", "kirin tor rep rewards list", "azure recipes where", "where is the kirin tor quartermaster and what does he sell", "dalaran rep vendor" }, a = "The Kirin Tor quartermaster is Archmage Alvareaux in Dalaran, Alterac Mountains, around 14.0,63.2, on an upper floor of a building hung with Kirin Tor banners. At Friendly he sells eight Azure recipes for 10g each (4 leatherworking, 2 tailoring, 2 blacksmithing) that make level 30 armor. At Exalted there's a 25g tabard.", topic = "practical" }
add{ q = { "can horde go to dalaran", "dalaran guards attacking me horde", "horde dalaran sewer key", "horde kirin tor rep", "horde dalaran?", "why are dalaran guards attacking me as horde", "can horde get kirin tor rep", "im horde can i go into dalaran or get kirin tor rep at all", "dalaran horde access", "dalaran horde can i enter" }, a = "No. Horde are attacked on sight in Dalaran in Forever, and the Horde Dalaran Sewer Key questline no longer opens the city in the open world. Horde also can't gain Kirin Tor rep. A beta bug that allowed it was fixed. The City of Dalaran dungeon still works for Horde. The Horde's equivalent rep track is the Earthen Ring.", topic = "practical" }
add{ q = { "an alarming request", "emissary jacques southshore", "image of archmage modera", "alarming request?", "where is emissary jacques", "how do i start an alarming request", "image of archmage modera quest", "alarming request southshore", "how do i start the an alarming request quest in southshore", "alarming request steps" }, a = "An Alarming Request is from Emissary Jacques in Southshore, Hillsbrad. It sends you to the Image of Archmage Modera near Dalaran, which leads into Heart of Disruption. Finish that and you get the Dalaran Sewer Key, then Friend of the Kirin Tor with Archmage Celindra in the Violet Citadel.", topic = "practical" }
add{ q = { "city of dalaran dungeon entrance", "reached dalaran but cant enter dungeon", "dalaran dungeon key", "cod entrance?", "where is the city of dalaran dungeon entrance", "im in dalaran but cant get into the dungeon", "how do i unlock the dalaran dungeon", "dalaran dungeon locked door", "i made it to dalaran city but the dungeon wont let me in why", "city of dalaran dungeon key" }, a = "Getting into outdoor Dalaran doesn't unlock the City of Dalaran 5-player dungeon. Getting there (or the Skyborne skycutter ride) and the dungeon's key are separate requirements. The dungeon is one of nine new Forever dungeons and works for both factions even though Horde are attacked in the open city.", topic = "practical" }
add{ q = { "how do i get to mount hyjal", "hyjal entrance forever", "darkwhisper gorge hyjal", "where is hyjal", "hyjal how?", "hyjal entrance where", "darkwhisper gorge how to get through", "where is mount hyjal on the map", "im 55 how do i get into mount hyjal from winterspring", "hyjal access" }, a = "Mount Hyjal is a level 60 zone in Forever (high 50s can quest there). Fly to Everlook in Winterspring, then go south to Darkwhisper Gorge, the entrance at the bottom of Winterspring (the old portal spot was about 50,83 on the Winterspring map). Follow the Hyjal quests through Tainted Foothills up to Summit of Eternity. Cataclysm portals and old wall-jump routes don't work. Flight points: Everlook to Tainted Foothills, and Tainted Foothills to Summit of Eternity. Both are neutral.", topic = "practical" }
add{ q = { "summit of eternity npcs", "hyjal hub vendors", "rhylin stonethorn", "aisarra nightmeadow", "hyjal quartermaster", "summit of eternity?", "who is at summit of eternity", "where is rhylin stonethorn", "where is aisarra nightmeadow", "what npcs are at summit of eternity in hyjal", "hyjal quartermaster where" }, a = "Summit of Eternity is Hyjal's main hub. Aisarra Nightmeadow sells high-level Guardians of Hyjal profession patterns. Rhylin Stonethorn is a former follower of the Wild King and the Guardians of Hyjal vendor. Marn Euhorn sells supplies and Toron Rockhoof is the smith. Exact coordinates aren't published yet. Look for them at the summit after taking the Tainted Foothills flight.", topic = "practical" }
add{ q = { "hyjal explore areas", "explore mount hyjal achievement", "hyjal subzones", "explore hyjal", "hyjal subzones list", "what areas do i need for explore hyjal", "hyjal exploration missing area", "which zones are left for the explore mount hyjal achievement", "hyjal areas" }, a = "Explore Mount Hyjal needs all 9 areas: Tainted Foothills, Summit of Eternity, Shrine of Aviana, Elderwild, Dae'gun, Mourning's Rest, Felblood Scar, Malorne's Retreat and Cradle of Tranquility. The list isn't a quest order.", topic = "practical" }
add{ q = { "feathers in flight cant loot owl nests", "hyjal owl nest wont loot", "feathers in flight bug", "owl nests wont loot", "feathers in flight not working", "cant loot owl nests in hyjal", "feathers in flight fixed?", "hyjal owl nest bug", "i cant loot the owl nests for feathers in flight what do i do", "owl nest bug" }, a = "Feathers in Flight had a bug where players under 60 couldn't loot the Hyjal Owl Nests. The Nov 9 hotfix fixed it, so try again. If a nest still won't open, check your quest log, since only players on the quest can loot it.", topic = "practical" }
add{ q = { "hyjal summit raid", "barrow deeps raid", "when do hyjal raids open", "hyjal attunement", "hyjal raids?", "hyjal summit raid info", "barrow deeps raid info", "do i need attunement for hyjal", "when do the hyjal summit and barrow deeps raids open", "hyjal raid attunement" }, a = "Hyjal Summit is a 20-player, 13-boss raid at the summit near Nordrassil. It's new content, not the Burning Crusade raid. Barrow Deeps is a 10-player level 60 raid whose entrances connect through Hyjal, Winterspring and Blackmaw Hold. Both open December 9, 2026. No attunement has been announced.", topic = "practical" }
add{ q = { "how do i get to riverglades", "riverglades entrance", "where is riverglades", "riverglades from redridge", "riverglades how?", "how do i get into riverglades", "wher is the riverglades zone", "riverglades entrance from lakeshire road", "what is the route into riverglades", "how do i get to the new riverglades zone as alliance or horde", "path to riverglades from redridge mountains" }, a = "Riverglades (35-45) is new land in southeastern Khaz Modan, between Redridge, Burning Steppes, Swamp of Sorrows and the Badlands. Walk in from Redridge or Burning Steppes through Blackrock Pass or Redridge Pass, from the Badlands north of Twilight's Shroud, or from Swamp of Sorrows via Redridge Pass. Horde can also take the neutral boat from Steamwheedle Port in Tanaris to Powderfuse Port.", topic = "practical" }
add{ q = { "riverglades flight path", "farholde keep", "rog'mar flight", "riverglades horde hub", "riverglades alliance hub", "riverglades fp?", "where are the riverglades flight paths", "where is farholde keep", "where is rog'mar in riverglades", "what is the alliance hub in riverglades", "where are the alliance and horde hubs in riverglades", "horde town riverglades flight master" }, a = "Alliance hub: Farholde Keep in southern Riverglades, led by Demar Brant. The gryphon master is Gretchen Mayberry, and there's an inn, a mailbox, stables and a forge, but no bank or AH. Beta data linked it to Lakeshire, Thelsamar and Morgan's Vigil. Horde hubs: Rog'mar (with flights, linked in beta to Stonard, Hammerfall, Kargath and Flame Crest) and Bolder'ok. The neutral goblin town is Powderfuse Port. Its flight point was hidden in late beta, so use the boat.", topic = "practical" }
add{ q = { "how do i get to shendralas", "shen'dralas entrance", "shendralas level", "where is shendralas", "shendralas how?", "where is shen'dralas on the map", "shendralas what level", "shen'dralas entrance from desolace", "how do i get to the new shen'dralas zone and what level is it", "shen dralas route" }, a = "Shen'dralas is a new contested zone between Mulgore and Desolace, tied to the Shen'dralar, Dire Maul and the Magram and Gelkis centaurs. You walk in from Desolace through the Valley of Bones. Guides put it at roughly 45-53. Subzones include Bristleback Retreat, Evenshade Overlook, Magram Front and Outcast Hideaway.", topic = "practical" }
add{ q = { "how do i leave zephras isle", "skyborne how to get to stormwind", "skyborne horde how to get to orgrimmar", "zephras boat", "leave zephras?", "how do skyborne leave zephras isle", "how do i get to stormwind as skyborne", "how do i get to orgrimmar as skyborne", "zephras isle ship", "im a skyborne how do i get off zephras isle to the main cities", "zephras skycutter" }, a = "Skyborne can leave Zephras Isle at any level. Follow the road to Valanaar at the south end of the island and take the marked dock. High Order (Alliance) ride a skycutter to Dalaran (The Magical City of Dalaran), then use the Skyborne-only portal to Stormwind. Windshaper (Horde) ride to Skywatcher Plateau on the Mulgore/Desolace border (The Earthen Ring). There's no portal to Orgrimmar, so walk or fly from Thunder Bluff.", topic = "practical" }
add{ q = { "boats and zeppelins forever", "all travel routes", "where does the boat go", "alliance boats list", "horde zeppelins list", "boats list?", "where do all the boats go in forever", "list of all boats and zeppelins", "what alliance boat routes are there", "where do horde zeppelins go", "can you list every boat and zeppelin route in forever", "which boats and zeps are new" }, a = "Alliance: Stormwind Harbor to Auberdine (new), the Deeprun Tram, the Auberdine to Menethil to Southshore loop, Menethil to Theramore, Rut'theran to Auberdine, Feathermoon to the Forgotten Coast. Horde: Orgrimmar to Undercity, Undercity to Grom'gol, Orgrimmar to Grom'gol zeppelins. There's no Orgrimmar to Thunder Bluff zeppelin. Neutral: Ratchet to Booty Bay, and the new Steamwheedle Port (Tanaris) to Powderfuse Port (Riverglades). The guard at each dock names the destination.", topic = "practical" }
add{ q = { "night elf how to get to stormwind", "darnassus to stormwind", "stormwind harbor boat", "how do i get to eastern kingdoms as nelf", "nelf to sw?", "how do night elves get to stormwind", "is there a boat from auberdine to stormwind", "darnassus to stormwind fastest", "stormwind harbor boat to darkshore", "im a night elf how do i get to the eastern kingdoms", "nelf to eastern kingdoms" }, a = "Forever adds a direct ship between Stormwind Harbor and Auberdine in Darkshore, so night elves no longer need the Menethil and Wetlands run. Take the portal in Darnassus to Rut'theran Village, the boat to Auberdine, then the Stormwind ship.", topic = "practical" }
add{ q = { "menethil southshore boat", "does the boat stop at southshore", "wetlands boat loop", "how to get to southshore by boat", "southshore boat?", "which boat goes to southshore", "can i take the boat from menethil to southshore", "is the southshore boat one way", "what stops does the wetlands boat make", "which boat goes from menethil to southshore in forever", "boat loop auberdine menethil southshore" }, a = "Forever links Menethil Harbor, Southshore and Auberdine by ship. Community maps show a one-way loop (Auberdine, Menethil, Southshore, back to Auberdine), but Blizzard hasn't confirmed the order. Read the dock guard's sign and stay on until your stop. Menethil's Theramore ship is a separate dock.", topic = "practical" }
add{ q = { "how do i get to tanaris riverglades boat", "steamwheedle port where", "powderfuse port boat", "riverglades boat?", "where is steamwheedle port", "boat from tanaris to riverglades", "how do i get the tanaris boat to riverglades", "where does the neutral ship to powderfuse port leave from", "tanaris boat" }, a = "The new neutral ship leaves from Steamwheedle Port on the Tanaris coast, east of Gadgetzan, and sails to Powderfuse Port, the goblin town in Riverglades. It's open to both factions and is the usual Horde way into Riverglades.", topic = "practical" }
add{ q = { "riding cost forever", "how much is mount at 40", "when can i get a mount", "epic mount cost forever", "riding training price", "riding cost?", "how much is the epic mount", "how much gold for riding at 40", "what does riding training cost", "how much is apprentice riding", "how much gold do i need for my first mount and the epic one", "mount prices forever" }, a = "Apprentice Riding is level 40 and costs 100g from your own race's riding trainer. The price includes your first mount (60% speed), and extra colours are 20g each. Journeyman Riding is level 60 and costs 1000g, with epic mounts at 200g (100% speed). Honored with your home city gives 10% off training and mounts, and the Bartering legacy perk gives up to 10% more off mounts only. Paladins and warlocks get their mounts from class quests.", topic = "practical" }
add{ q = { "where is riding trainer", "mount trainer location", "where to learn riding human", "horde riding trainer where", "riding trainer?", "where is the riding trainer", "where do humans learn riding", "horde riding trainer location", "mount trainer where", "where do i learn riding for my race", "riding trainer by race" }, a = "Riding trainers by race: Human, Randal Hunter at Eastvale Logging Camp, Elwynn (84.3,64.9). Dwarf, Ultham Ironhorn at Amberstill Ranch, Dun Morogh (63.7,50.1). Gnome, Binjy Featherwhistle at Steelgrill's Depot (49.2,48.1). Night elf, Jartsam in Darnassus (38.1,16.1). Orc, Kildar in Orgrimmar (69.4,13.1). Troll, Xar'Ti at Sen'jin (55.3,75.5). Tauren, Kar Stormsinger at Bloodhoof (46.8,61.9). Undead, Velma Warnam in Brill (60.2,52.4). Skyborne, Genn Fairweather at Fairweather Stables, Zephras (53.8,81.3).", topic = "practical" }
add{ q = { "can i buy another race mount", "other race mount rep", "tiger mount as human", "other race mount?", "can i ride another race's mount", "can my human get a tiger", "how much rep for other race mounts", "can my orc buy a raptor", "can my human buy a night elf tiger or a dwarf ram", "exalted for other race mounts" }, a = "To learn riding from or buy mounts from another race of your faction, you need Exalted with that race's city. Turn in Runecloth to that city's cloth quartermaster or quest in their zones to get there.", topic = "practical" }
add{ q = { "reputation levels explained", "how much rep for exalted", "rep tiers points", "what is neutral friendly honored", "rep levels?", "reputation tiers explained", "how many points from neutral to friendly", "what is honored revered exalted", "how much reputation do i need for each rep level", "rep points per tier" }, a = "Each tier needs: Neutral to Friendly 3,000, Friendly to Honored 6,000, Honored to Revered 12,000, Revered to Exalted 21,000. Below Neutral there are Unfriendly, Hostile and Hated. As a rule, Hostile and Hated factions attack you on sight. Unfriendly ones usually leave you alone but won't talk to you. Neutral lets you talk and take quests. Friendly is usually where vendor recipes start. The Diplomat legacy perk adds up to +10% rep (2% per rank).", topic = "practical" }
add{ q = { "darkspear raiders quartermaster", "theramore expeditionary force vendor", "darkspear islands rep vendor", "darkspear raiders?", "where is the darkspear raiders quartermaster", "where is the theramore expeditionary force vendor", "darkspear islands rep vendor location", "who sells the darkspear islands pvp rewards", "where are the darkspear islands battleground rep vendors", "creeg bothunk where" }, a = "The Darkspear Islands PvP rep vendors are Creeg Bothunk for the Darkspear Raiders, north of Ratchet (about 65.0,34.6), and Bryanna Embreeze for the Theramore Expeditionary Force at Northwatch Hold (about 63.4,58.6). Friendly sells trinkets, Honored cloaks, rings and necks, Revered weapons, and Exalted armor, a tabard and a Legacy Point.", topic = "practical" }
add{ q = { "why cant i turn in quest", "quest wont complete checklist", "cant hand in quest npc wont talk", "quest giver not showing", "cant turn in quest", "quest wont complete", "npc wont talk to me", "quest giver missing", "why cant i hand in my quest", "i have all the items but the quest npc wont take it", "quest turn in not working" }, a = "Things to check:\n1. Reputation: many factions only talk to you at Neutral or better (Timbermaw, Thorium Brotherhood and others).\n2. Faction: Horde can't use Kirin Tor or Dalaran NPCs, and some hubs are one faction only.\n3. Prerequisites: an earlier quest in the chain may be missing. Forever changed prerequisites and levels on several quests.\n4. Quest item: if you deleted it, abandon the quest and pick it up again (Forever fixed several of these links).\n5. Escort or event NPC respawning: wait a few minutes.\n6. Level: some starts moved (Ruins of Lordaeron quests are now level 15).", topic = "practical" }
add{ q = { "the great outdoors quest", "sit by campfire quest not completing", "boosted rest campfire quest", "camping quest bugged", "great outdoors bug", "campfire quest not completing", "camping quest broken", "boosted rest campfire", "sitting by campfire not working", "i sit at the campfire but the great outdoors quest wont complete", "the great outdoors quest help" }, a = "The Great Outdoors teaches you camping basics. Stand at a campfire and sit (default X). Then wait about 60 seconds while the Welcoming Campfire countdown runs in the top right, and the quest completes. If sitting doesn't register, sit by the fire and also type /sit in chat. If it still fails, come back later. The quest giver teaches Camping and leads into early crafting quests.", topic = "practical" }
add{ q = { "the sleeper has awakened", "kerlonian evershade keeps falling asleep", "horn of awakening missing", "kerlonian sleeping", "the sleeper has awakened help", "horn of awakening lost", "kerlonian keeps falling asleep", "kerlonian escort", "kerlonian evershade keeps falling asleep and i lost the horn", "sleeper has awakened quest" }, a = "For The Sleeper Has Awakened (Kerlonian Evershade escort, Darkshore), Forever hotfixes made him fall asleep less often and now give you the Horn of Awakening when you start. Blow the horn whenever he dozes off. If you took the quest before the fix and have no horn, abandon it and take it again.", topic = "practical" }
add{ q = { "unending torment level", "abominable head quest", "ruins of lordaeron quests level", "cant start ruins of lordaeron quest", "rol quests?", "what level is unending torment", "what level do rol quests start", "abominable head what level", "why cant i pick up the ruins of lordaeron quests", "what level do the ruins of lordaeron quests start at now", "rol quest min level" }, a = "All Ruins of Lordaeron dungeon quests start at level 15 now. Unending Torment comes from the Abominable Head, which The Baron drops, and you take it to Master Apothecary Faranell in Undercity. It used to need 16 for Horde and was lowered to 15 on Nov 6. If you're holding the head, check whether the quest offers now.", topic = "practical" }
add{ q = { "drowned city entrance", "where is drowned city", "blackmaw hold where", "drowned city portal not working", "drowned city?", "how do i get into the drowned city", "drowned city portal isnt working", "where is blackmaw hold", "drowned city entrance location", "the portal to the drowned city isnt working what do i do", "how to enter drowned city" }, a = "The Drowned City (naga and pirates) is off the Stranglethorn coast west of Grom'gol. Its portal wasn't teleporting people at launch and has been fixed. Blackmaw Hold is in Azshara. Both had mobs that disengaged by mistake, which is also fixed.", topic = "practical" }
add{ q = { "hall of thanes quest", "old ironforge incursion", "excavation site wetlands level", "new dungeons forever list", "new dungeon quests?", "where do i get hall of thanes quests", "old ironforge incursion quest", "what level is excavation site", "list of new forever dungeons and quests", "where do i get quests for all the new forever dungeons", "new dungeon quest givers" }, a = "Forever's nine new dungeons: Ruins of Lordaeron (quests from 15), Hall of Thanes under Ironforge (Alliance quest Old Ironforge Incursion: bring back Durgen Dirgehammer's head), Excavation Site above Whelgar's Excavation in the Wetlands (26-31), City of Dalaran, Blackmaw Hold (Azshara), the Drowned City (STV coast), Krol'dok Stronghold (Riverglades), Alcaz Prison, and Shaper's Terrace (Un'Goro, 58-60). Bonus dungeon quest XP pays only on your first clear, so grab every quest first.", topic = "practical" }
add{ q = { "counterattack event barrens", "rethgar deathgate", "the attack stormwind quest", "how to start the attack tyrion", "counterattack quest", "the attack stormwind", "how to start the attack", "counterattack barrens easier", "how do i start the counterattack event in the barrens", "the attack tyrion quest" }, a = "Forever made two event quests easier. In the Barrens, talk to Rethgar Deathgate to start Counterattack! if it isn't running. In Stormwind, The Attack! is no longer an escort and can be shared even mid-event. Talk to Tyrion to start the event if it isn't active.", topic = "practical" }
add{ q = { "darkshore quest fixes", "for love eternal turn in", "how big a threat furbolg camps", "holy diver xp", "darkshore changes?", "what changed in darkshore", "for love eternal where do i turn in", "do furbolg camps count for how big a threat", "holy diver xp change", "what changed in the darkshore quests in forever", "darkshore quest fixes list" }, a = "Darkshore changes in Forever: many furbolg camps now count for How Big a Threat?, you can hand For Love Eternal to Cerellian Whiteclaw any time, Holy Diver now gives XP, and Body and Heart's Cenarion Moondust isn't consumed, so you can re-summon Lunaclaw.", topic = "practical" }
add{ q = { "deleted quest item what do i do", "destroyed quest item cant abandon", "lost quest item", "deleted quest item", "destroyed quest item", "accidentally deleted my quest item", "how do i get a quest item back", "i deleted a quest item by accident can i get it again", "quest item gone" }, a = "Abandon the quest and pick it up again from the giver. Most quest items come back that way. Forever fixed many quests where destroying the item didn't abandon the quest, or the other way round. Some givers, like Teo Hammerstorm for the Earth Sapta, will hand you a replacement if you ask.", topic = "practical" }
add{ q = { "party member didnt get quest item", "quest drop not shared", "group quest loot only one person", "quest item not shared", "party member no quest drop", "quest loot only one person", "my friend didnt get the quest item", "group quest drops", "we are grouped but only i got the quest drop", "shared quest drops" }, a = "Forever now shares many quest drops with the party, and hotfixes added more. Examples are The Monster Surfaces, Croaky's Head, Elmpaw's Head and Riverglades party drops. Quest drops are also spread more evenly across group members. If one person still misses out, keep killing; some items still drop for each player separately.", topic = "practical" }
add{ q = { "lonebrows journal where", "henrig lonebrow journal", "a recipe for death berard journal", "fetch n fletch bug", "lonebrows journal?", "where is henrig lonebrows journal", "lonebrow journal respawn slow", "a recipe for death journal where", "fetch n fletch bugged", "henrig lonebrows journal respawn is so slow is that fixed", "berard journal where" }, a = "Nov 9 hotfixes: Henrig Lonebrow's Journal now respawns faster and has moved a little further down the road from its old spot. Berard's Journal for A Recipe for Death can be looted again from Berard's Bookshelf. Fetch 'n' Fletch can be completed. If any of these failed for you earlier, try again.", topic = "practical" }
add{ q = { "escorting erland", "deathstalker erland not there", "jom-jom escape stuck", "unwelcome guests terry longdrink", "erland escort?", "deathstalker erland isnt there", "escorting erland bugged", "jom-jom escape is stuck", "deathstalker erland isnt spawning for the escort quest", "silverpine escort fix" }, a = "Hotfix fixes: Deathstalker Erland (Escorting Erland, Silverpine) now respawns much faster. Jom-jom no longer stops partway through his escape. In Unwelcome Guests, Terry Longdrink no longer stays alive by mistake. If one of these is still stuck, abandon and retake the quest so the NPC resets.", topic = "practical" }
add{ q = { "darkwhisper gorge warlock", "hederine where", "tears of the hederine", "eye of shadow drop", "darkwhisper gorge?", "where is darkwhisper gorge", "where are the hederine", "how do i get tears of the hederine", "where does eye of shadow drop", "where do warlocks go in darkwhisper gorge for the dreadsteed", "hederine initiate location" }, a = "Darkwhisper Gorge is at the far south of Winterspring, past Frostwhisper Gorge, a maze of tunnels and chasms. In Classic it holds elite Hederine demons (about 5-man difficulty) and Vi'el, an imp selling Felcloth and Gromsblood. Hederine drop Tears of the Hederine for the warlock Doomguard quest. Slayers and Initiates have a 0.5% Eye of Shadow drop for the priest Benediction quest. In Forever the gorge is also the road into Mount Hyjal.", src = "classic", topic = "practical" }
add{ q = { "argent dawn friendly needed", "enriched manna biscuits where", "light's hope quartermaster", "manna biscuits?", "where do i buy enriched manna biscuits", "do i need argent dawn friendly", "where is the lights hope quartermaster", "argent dawn vendor location", "where do i buy enriched manna biscuits for the charger quest", "lights hope chapel vendor" }, a = "Light's Hope Chapel in Eastern Plaguelands has the Argent Dawn quartermaster, with a flight path for both factions. Enriched Manna Biscuits (needed for the paladin Charger) are sold there once you're Friendly with Argent Dawn. Argent Dawn is still a Classic-style rep in Forever and is still tied to Naxxramas progression.", src = "classic", topic = "practical" }
add{ q = { "kalimdor flight paths list", "where are the flight masters kalimdor", "horde flight paths kalimdor", "alliance flight paths kalimdor", "kalimdor fps?", "list of kalimdor flight paths", "where are the horde flight paths in kalimdor", "where are the alliance flight paths in kalimdor", "kalimdor flight points", "can you list all the flight paths in kalimdor for my faction", "kalimdor flight masters" }, a = "Classic Kalimdor flight points. Alliance: Rut'theran Village, Auberdine, Astranaar, Stonetalon Peak, Nijel's Point, Thalanaar, Feathermoon, Theramore, Talrendis Point, Talonbranch Glade. Horde: Orgrimmar, Crossroads, Camp Taurajo, Thunder Bluff, Sun Rock Retreat, Splintertree Post, Zoram'gar, Shadowprey Village, Camp Mojache, Freewind Post, Brackenwall, Valormok, Bloodvenom Post. Both factions: Ratchet, Gadgetzan, Marshal's Refuge, Cenarion Hold, Everlook, Moonglade.", src = "classic", topic = "practical" }
add{ q = { "eastern kingdoms flight paths", "where are flight masters eastern kingdoms", "alliance flight paths ek", "horde flight paths ek", "ek fps?", "list of eastern kingdoms flight paths", "where are the horde flight paths in ek", "where are the alliance flight paths in ek", "eastern kingdoms flight points", "can you list all the flight paths in the eastern kingdoms", "ek flight masters list" }, a = "Classic Eastern Kingdoms flight points. Alliance: Stormwind, Ironforge, Sentinel Hill, Lakeshire, Darkshire, Thelsamar, Menethil Harbor, Southshore, Refuge Pointe, Aerie Peak, Chillwind Camp, Morgan's Vigil, Nethergarde Keep, Rebel Camp. Horde: Undercity, The Sepulcher, Tarren Mill, Hammerfall, Revantusk Village, Kargath, Stonard, Grom'gol, Flame Crest. Both: Booty Bay, Thorium Point, Light's Hope Chapel. New in Forever: Farholde Keep (Alliance) and Rog'mar (Horde) in Riverglades.", src = "classic", topic = "practical" }
add{ q = { "frequent flier perk", "cheaper flights forever", "faster flight paths", "frequent flier?", "how do i get cheaper flights", "what is the frequent flier perk", "can flights be faster", "legacy perk for flying", "is there a legacy perk to make flight paths cheaper", "how to reduce flight cost" }, a = "The Frequent Flier legacy perk halves flight master fares and makes taxis 20% faster. It only affects flight master rides, not boats, zeppelins or riding. Gamepad players can also end a flight early with Back/Cancel and get off at the next flight point.", topic = "practical" }
add{ q = { "mage teleport dalaran", "teleport dalaran level", "portal to dalaran", "teleport dalaran?", "can mages teleport to dalaran", "what level is teleport dalaran", "portal dalaran mage", "which races get teleport dalaran", "what level can my mage learn teleport dalaran", "dalaran port spell" }, a = "Teleport: Dalaran is a level 50 spell for Human, Gnome and High Order Skyborne mages, and it moves only the caster. No group Portal: Dalaran appears in the spell list. Teleports use a Rune of Teleportation and group portals use a Rune of Portals.", class = "MAGE", topic = "practical" }
add{ q = { "how to get to ungoro crater", "how to get to un'goro", "un'goro entrance", "marshal's refuge flight path", "un'goro how?", "how do i get to un'goro", "marshal's refuge fp", "how to get to ungoro from tanaris", "how do i get down into un'goro crater from tanaris", "ungoro route" }, a = "Un'Goro Crater is entered from Tanaris: take the long ramp down from the northwest of Tanaris, west of Gadgetzan, into the crater. Ride north to Marshal's Refuge at the crater's north edge for the flight point (both factions) and the main quest givers. Silithus lies through the crater's western exit.", src = "classic", topic = "practical" }
add{ q = { "dmf ticket level requirements", "darkmoon low level turn ins", "small furry paw dmf", "low lvl dmf turnins", "dmf small furry paw", "darkmoon low level tickets", "dmf turn ins under 20", "darkmoon ticket level requirements", "what can i turn in at the darkmoon faire as a low level", "dmf low level" }, a = "Low-level Darkmoon turn-ins: 5 Small Furry Paw (1 ticket, any level), 5 Torn Bear Pelt (4 tickets, level 10), 5 Soft Bushy Tail (8, level 20), 5 Vibrant Plume (12, level 30), all to Yebb Neblegear. Crafters can hand Kerri Hicks 10 Coarse Weightstone, Rinling 3 Copper Modulator, or Chronos 3 Embossed Leather Boots, 1 ticket each. Each turn-in also gives 250 Darkmoon rep.", topic = "practical" }
add{ q = { "warlock level 20 25 quest list forever", "forever new class quests list", "what class quests are new in forever", "new class quests", "forever class quests list", "what class quests are new", "warlock 20 25 quests", "class quest changes forever", "what class quests changed or were added in forever", "new class quests list" }, a = "New or changed class quests in Forever: druid Cat Form is now a quest (Moonglade barrow); shamans get the Rage of the Storm weapon quest after Call of Air, a relic from Call of Fire, and Dwarf and Skyborne totem chains; Undead paladins get a whole Bandarion Keep chain with their own Warhorse and Forsaken Charger; Human and Gnome priests get new racial quests; troll warlocks start with Tainted Tablet; rogues get Syndicate Sabotage and a Ruby-Adorned Blade spy chain; the Staff of Soran'ruk is stronger.", topic = "practical" }
add{ q = { "paladin plate armor when", "paladin trainer weapons", "where to learn polearms paladin", "paladin plate?", "when can paladins wear plate", "what armor can paladins wear", "where do paladins learn polearms", "paladin weapon trainer", "when does my paladin get plate armor in forever", "pally armor levels" }, a = "Forever paladins wear cloth, leather and mail from level 1 and learn Plate at 40 from the class trainer. Polearms can be learned from 20. Alliance: Woo Ping in Stormwind teaches swords and polearms, Buliwyf Stonehand in Ironforge teaches axes and two-handed maces. Horde: Archibald in Undercity teaches swords and polearms, Hanashi and Sayoc in Orgrimmar teach axes, Ansekhwa in Thunder Bluff teaches two-handed maces.", class = "PALADIN", topic = "practical" }
add{ q = { "warrior brutal armor quest", "warrior level 20 quest", "yorus barleybrew", "brutal armor quest?", "warrior lvl 20 armor quest", "where is yorus barleybrew", "how do i get the brutal armor", "warrior 20 quest chain", "how do i do the warrior level 20 armor quest", "warrior 20 armor quest horde" }, a = "Classic level 20 warrior armor chains. Alliance start with Yorus Barleybrew in Lakeshire (a timed cave fight) and Duren Longbeard in Stormwind's Dwarven District. Horde start with Thun'grim Firegaze on the hill east of the northern Crossroads, a long chain through Razorfen Kraul plus Smoky Iron Ingots and Powdered Azurite. Other pieces come from trainers in each capital.", class = "WARRIOR", src = "classic", topic = "practical" }
add{ q = { "tanning rack skill requirement", "leatherworking tanning rack 140", "cant use tanning rack", "tanning rack?", "why cant i use the tanning rack", "what lw skill for tanning rack", "tanning rack needs 140", "tanning rack leatherworking", "why cant i use the tanning rack in forever", "tanning rack skill requirement changed" }, a = "Forever's Tanning Rack used to need 140 Leatherworking, which locked out the 125 patterns. A hotfix lowered it to 125 and dropped its skill-up thresholds by 15. Check whether you can use it now before grinding to 140.", topic = "practical" }
add{ q = { "vorsha the lasher", "ashenvale vorsha quest disabled", "vorsha quest not available", "vorsha ashenvale?", "why is vorsha disabled", "vorsha quest missing", "cant get vorsha the lasher quest", "vorsha the lasher ashenvale off", "why cant i get the vorsha the lasher quest in ashenvale", "vorsha back yet" }, a = "Vorsha the Lasher in Ashenvale was switched off at launch because it crashed the zone. The Nov 6 notes say it's fixed, but the Known Issues page still listed it as disabled at the time. If the quest giver won't offer it, it's still off. Skip it and come back later.", topic = "practical" }
add{ q = { "winterspring flight path", "everlook flight master", "how to get flight path winterspring", "everlook fp?", "where is the everlook flight master", "how do i get the winterspring flight path", "is there a flight path in winterspring", "everlook flight", "where is the flight master in everlook winterspring", "winterspring fp location" }, a = "Everlook in central Winterspring has a flight point for both factions. Alliance usually link it to Talonbranch Glade (Felwood) and Horde to Bloodvenom Post. The first trip is on foot through the Timbermaw tunnel from north Felwood, which needs Unfriendly with Timbermaw. In Forever, Everlook also links to Tainted Foothills in Mount Hyjal.", src = "classic", topic = "practical" }
add{ q = { "xp from dungeon quests only once", "second run no quest xp", "dungeon quest xp forever", "dungeon quest xp once", "dungeon quest xp", "repeat dungeon quest xp", "why did i get less xp from dungeon quest", "do dungeon quests give bonus xp only the first time", "dungeon quest bonus xp" }, a = "In Forever the extra quest XP for dungeon quests pays only on your first run of that dungeon, while kill XP pays every run. Pick up every quest for a dungeon before your first clear. Blizzard halved bonus dungeon quest XP in beta and raised dungeon kill XP afterwards.", topic = "practical" }
add{ q = { "silithus twilight cultist quests", "bor wildmane", "cenarion hold quartermaster rewards", "cenarion rewards?", "what does cenarion hold sell", "where is bor wildmane", "silithus cultist quests", "cenarion circle reward list", "what rewards does the cenarion hold quartermaster sell", "cc vendor items" }, a = "Classic Cenarion Circle rewards at Cenarion Hold. Friendly: patterns from Kania, Vargus, Mishta and Aendel Windspear (Sandstalker, Spitfire, Bramblewood). Honored: Windcaller Yessendra's class rings. Revered: Keyl Swiftclaw's class cloaks and Mishta's Satchel of Cenarius. Exalted: Warden Haro's class weapons. Encrypted Twilight Texts from Twilight's Hammer cultists are the main repeatable turn-in.", src = "classic", topic = "practical" }
add{ q = { "zephras anchors quest stuck", "halaans gift scry", "the anchors of zephras", "anchors of zephras?", "anchors of zephras is stuck", "how do i use halaans gift", "anchors quest bugged", "the anchors of zephras quest is stuck what do i do", "help with anchors of zephras" }, a = "For The Anchors of Zephras on Zephras Isle, use Halaan's Gift to scry each anchor. A beta bug stopped Halaan's Gift working and was fixed in the Oct 15 notes. If it still won't register, abandon the quest and retake it to get a fresh Halaan's Gift.", topic = "practical" }
add{ q = { "raene's cleansing bloodtooth guards", "twisted hatred lord melenas", "the cleft spiders teldrassil", "raenes cleansing?", "where are the bloodtooth guards", "the cleft spiders", "what changed in teldrassil quests", "what changed in raenes cleansing and twisted hatred in forever", "ashenvale quest changes" }, a = "Forever changes: Raene's Cleansing in Ashenvale spawns more Bloodtooth Guards. In Twisted Hatred on Teldrassil, The Cleft has fewer spiders and Lord Melenas no longer evades at low health.", topic = "practical" }
add{ q = { "respawn too slow quest mobs", "mobs not spawning quest", "zone too crowded cant finish quest", "slow respawns?", "quest mobs are not spawning", "respawn too slow", "zone too crowded to finish quest", "quest mobs not respawning", "the quest mobs are taking forever to respawn what can i do", "respawn rates forever" }, a = "Blizzard sped up respawns across many zones for launch, fastest in starting zones and slower as you level. On Nov 9 they also lowered player population caps in crowded zones, especially on PvP realms. If a named mob is camped, switch to another quest and come back. Many named spawns (Ivar the Foul, Ferocitas, Yarrog Baneshadow) also had respawn fixes.", topic = "practical" }
add{ q = { "wetlands new quests", "excavation site wetlands", "wetlands level forever", "carnage quest reset", "wetlands quests?", "new quests in the wetlands", "what level is the wetlands", "what new quests are in the wetlands in forever", "wetlands questing forever", "whats new to do in the wetlands" }, a = "The Wetlands (20-29) have over 25 new quests in Forever, plus the Excavation Site dungeon (26-31) above Whelgar's Excavation. Fixes: the Carnage boss no longer resets near the end, and Alba Fairmoon stays available to hand in Destruction in Deadmines. Get there by Menethil Harbor's boats or on foot from Loch Modan.", topic = "practical" }
add{ q = { "where is undead paladin trainer", "forsaken paladin a second home", "breton samuels", "undead pally trainer?", "where is the undead paladin trainer", "a second home quest", "where is breton samuels", "forsaken paladin trainer location", "im an undead paladin where do i go to train", "where do undead paladins train in forever" }, a = "Forsaken paladins get A Second Home, which sends them to Bandarion Keep in Whispering Wood, Tirisfal, to report to Breton Samuels. A Difficult Path also starts with a Consecrated Scroll that you take to Aramis Hammerhand in Deathknell. Most Undead paladin class quests are handed out at the keep.", class = "PALADIN", topic = "practical" }
add{ q = { "thendal grove where", "a student of nature", "a student of the arcane", "dorii brightwhisper", "thendal grove", "student of nature", "student of the arcane", "where is thendal grove", "where do i do a student of nature on zephras isle", "skyborne class quest" }, a = "A Student of Nature (read the Folded Parchment) and A Student of the Arcane (examine the Glowing Recall Crystal) are new Forever class starters. Both send you to Thendal Grove: Xyton Silverwind for nature and Dorii Brightwhisper for arcane.", topic = "practical" }
add{ q = { "guardians of hyjal recipes artisan tier", "malleable essence of nature", "artisan tier crafting", "hyjal recipes?", "where do i get artisan tier recipes", "malleable essence of nature where", "how does artisan tier crafting work", "guardians of hyjal patterns", "where do i get the artisan tier recipes from guardians of hyjal", "crafted tier recipes vendor" }, a = "Guardians of Hyjal patterns, sold by Aisarra Nightmeadow at Summit of Eternity from Friendly, craft Artisan's Tier pieces such as the Manaflare, Conviction, Demonheart and Grovekeeper sets. They need Malleable Essence of Nature, which comes from disenchanting qualifying Hyjal Summit and Barrow Deeps raid drops. You can normally wear only one Artisan piece; the Revered Rousing Seed Pod raises that to two.", topic = "practical" }
add{ q = { "wild king hyjal", "to have loved and lost hyjal", "hyjal storyline quests", "hyjal story?", "what is the wild king quest", "to have loved and lost quest", "hyjal quest chains list", "what are the main storyline quest chains in hyjal", "hyjal lore quests" }, a = "The main Hyjal storylines are the Darkwhisper Gorge journey, the Summit of Eternity hub, To Have Loved and Lost (rebuilding a druid camp), Guardians of Hyjal and Barkskin Burrow rep, and the fight against the Wild King, a druid who tried to use the Wild Gods' power to bring back night elf immortality. Rhylin Stonethorn left him and now helps the defenders. The exact breadcrumb order isn't published yet.", topic = "practical" }
add{ q = { "stratholme living quests", "the medallion of faith", "the archivist quest", "ezra grimm tobacco", "strat live quests?", "medallion of faith quest", "ezra grimm quest", "stratholme quest list", "what quests can i do in stratholme live side", "strat living side quests" }, a = "Stratholme Live quests: The Great Ezra Grimm (Smokey LaRue at Light's Hope, bring Grimm's Premium Tobacco). The Archivist and The Truth Comes Crashing Down (Duke Nicholas Zverenhoff, Light's Hope). Don't kill Balnazzar during The Archivist if you want to finish the chain in one run. The Medallion of Faith comes from Aurius in the chapel (Malor's Strongbox in the Bastion). The Restless Souls comes from Egan in Terrordale. These guides are based on Classic and weren't tested in the Forever beta.", src = "classic", topic = "practical" }
add{ q = { "what changed with alchemy in wow forever", "alchemy changes forever vs classic", "is alchemy different in forever", "forever alchemy whats new", "alchemy changes", "what's different about alchemy", "alchemy in forever vs vanilla", "did they change alchemy", "whats new with alch", "is alchemy still good in forever", "what did forever do to alchemy", "how is alchemy different in wow forever compared to classic", "just started alchemy whats different from classic" }, a = "Biggest Alchemy changes in Forever:\n1. Healing potions were moved out of Alchemy into First Aid, so anyone can make them.\n2. Alchemists now make dyes (Cerulean, Magenta, Viridian) used by other crafts.\n3. Lots of new elixirs/potions: Mender's, Spellblasting, Frenzy, Cleric's, Mageblood, Grizzly, Cunning, Owl, Sages and more.\n4. Four new zone flasks (Flask of Natural Accuracy/Aggression/Precision/Swiftness).\n5. Camp placeables: Mana Well, Fermenter, Alchemy Laboratory, so you no longer need Scholomance for flasks.\n6. New transmute: Legionite.\n7. Philosopher's Stone now learnable at 225.", topic = "prof_alch_ench" }
add{ q = { "how many alchemy recipes are in forever", "how many new alchemy recipes", "alchemy recipe count forever", "how many alch recipes", "number of alchemy recipes", "how many new potions in forever", "alchemy recipe total", "how many recipes did they add to alchemy", "alchemy new recipe count", "how many potions can alchemists make", "how many recipes does alchemy have in forever" }, a = "Kami-labs counts 178 Alchemy recipes in Forever: 71 brand new, 46 changed from Classic and 61 unchanged. That includes 9 flasks (5 Classic plus 4 new Natural flasks) and 13 transmutes.", topic = "prof_alch_ench" }
add{ q = { "can alchemists make healing potions in forever", "where did healing potions go", "why cant i learn major healing potion alchemy", "healing potion recipe forever", "who makes healing pots in forever", "where are healing potions", "can alchemy make heal pots", "healing pots first aid", "who makes healing potions now", "why cant i learn healing potion", "major healing potion recipe missing", "healing potions moved to first aid?", "im an alchemist why cant i make healing pots anymore", "where did healing pots go in forever" }, a = "In Forever, regular healing potions (Minor through Major Healing Potion) were moved from Alchemy to First Aid, so any First Aid user crafts them. Alchemists instead get the Discolored Healing Potion line (taught by Odd Child for Alliance or Apothecary Renferrel for Horde), which uses Murloc Eyes plus herbs.", topic = "prof_alch_ench" }
add{ q = { "is there alchemy specialization in forever", "transmute master forever", "elixir master potion master forever", "alchemy spec quest forever", "mixology forever", "alchemy spec", "transmute master", "potion master forever", "elixir master", "is there alchemy specialization", "alchemy specialization quest", "can i spec transmute in forever", "mixology", "can i become a transmute master in forever" }, a = "Classic-style Alchemy specializations (Transmute/Elixir/Potion Master) are not part of Forever; no Forever guide lists a specialization quest. A Mixology-style bonus (elixirs and flasks lasting twice as long and 25% stronger) was reported from a BlizzCon 2026 demo, but it is unconfirmed, so don't count on it.", src = "classic", topic = "prof_alch_ench" }
add{ q = { "what profession goes with alchemy", "alchemy and herbalism forever", "best pair for alchemy", "alchemy fishing forever", "what goes with alchemy", "alchemy herbalism", "best prof with alchemy", "alchemy and fishing", "what should i pair with alch", "alchemy second profession", "is herb alch still the best combo", "im leveling alch what should my second prof be" }, a = "Herbalism is the natural partner, since almost every recipe uses herbs and you'll save a lot of gold versus the AH. Fishing is a decent second option for Firefin Snapper (Fire Oil) and Stonescale Eel (Stonescale Oil), both used in the cheaper leveling routes and in flasks.", topic = "prof_alch_ench" }
add{ q = { "alchemy trainer stormwind", "where is alchemy trainer alliance", "alchemy trainer ironforge darnassus", "alliance alchemy trainers forever", "alchemy trainer sw", "alliance alchemy trainer", "alchemy trainer if", "alchemy trainer darnassus", "where to learn alchemy alliance", "where is alchemy trainer in stormwind", "alch trainer alliance location", "where do i learn alchemy in ironforge" }, a = "Alliance Apprentice Alchemy: Tel'Athir (Stormwind Mage Quarter 55.6, 85.6), Vosur Brakthel (Ironforge Tinker Town 67.0, 54.2), Milla Fairancora (Darnassus 55.8, 23.8), Alchemist Mallory (Goldshire 39.8, 48.6), Cyndra Kindwhisper (Dolanaar 57.6, 60.6), Ghak Healtouch (Thelsamar 37, 49.2). Journeyman: Lilyssia Nightbreeze (Stormwind 55.6, 85.8) or Tally Berryfizz (Ironforge 67.2, 54.2).", topic = "prof_alch_ench" }
add{ q = { "alchemy trainer orgrimmar", "horde alchemy trainer", "alchemy trainer undercity thunder bluff", "where do i learn alchemy horde", "alchemy trainer org", "alchemy trainer uc", "alchemy trainer tb", "where to learn alchemy horde", "where is the alchemy trainer in orgrimmar", "alch trainer horde", "where do i learn alchemy in undercity" }, a = "Horde Apprentice Alchemy: Whuut (Orgrimmar, The Drag 56.0, 33.8), Doctor Martin Felben (Undercity Apothecarium 46.6, 74.6), Kray (Thunder Bluff 47.0, 34.6), Miao'zan (Sen'jin Village 55.4, 74), Carolai Anise (Brill 59.4, 52.2). Journeyman: Yelmak (Orgrimmar 56.6, 33.2), Doctor Marsh (Undercity 51.6, 75.6), Bena Winterhoof (Thunder Bluff 47, 33) or Serge Hinott (Tarren Mill 61.6, 19.2).", topic = "prof_alch_ench" }
add{ q = { "expert alchemy trainer", "where to learn expert alchemy", "alchemy 150 trainer", "alchemy past 225 trainer", "artisan alchemy trainer location", "where to learn expert alch", "alchemy trainer 150", "artisan alchemy trainer", "alchemy past 225", "where do i train alchemy after 150", "stuck at 225 alchemy trainer", "where is the artisan alchemy trainer", "im 150 alchemy where do i learn expert" }, a = "Expert (150-225, needs skill 125, level 20, 50s): Ainethil in Darnassus (55, 24), Linzy Blackbolt in Dalaran, Alterac Mountains (18.6, 62.4) for Alliance; Doctor Herbert Halsey in the Undercity Apothecarium (48.2, 72.2) for Horde.\nArtisan (225-300, needs skill 200, level 35): Kylanna Windwhisper at Feathermoon Stronghold, Feralas (32.6, 43.8) for Alliance; Rogvar in Stonard, Swamp of Sorrows (48.4, 55.6) for Horde. Neutral Artisan: Master Mycologist Shurome at Emerald Sanctuary (51.4, 82.0).", topic = "prof_alch_ench" }
add{ q = { "alchemy trainer zephras isle", "skyborne alchemy trainer", "alchemy trainer valanaar", "neutral alchemy trainer booty bay", "valanaar alchemy", "neutral alchemy trainer", "booty bay alchemy trainer", "alchemy trainer on zephras", "where do skyborne learn alchemy", "where can skyborne learn alchemy on zephras isle", "zephras isle alchemy", "neutral alch trainer" }, a = "On Zephras Isle (Skyborne start): Iaadaria Bitterwind (66.2, 79.6) and Valiena Swiftgale (59.2, 76.2) in Valanaar, or Nyassa Swiftdraught in Shen'dar Village (43.6, 43.6) for Apprentice. Jaxin Chong in Booty Bay (28, 78) is a neutral Journeyman trainer.", topic = "prof_alch_ench" }
add{ q = { "alchemy rank requirements", "when can i learn journeyman alchemy", "level needed for artisan alchemy", "alchemy skill cap 75 150 225", "artisan alchemy level", "alchemy skill caps", "alchemy level requirements", "what level for expert alchemy", "alchemy 75 150 225 300 requirements", "what level do i need for artisan alchemy", "journeyman alchemy level", "what level expert alch" }, a = "Alchemy ranks: Apprentice (to 75) any level; Journeyman (to 150) needs skill 50 and level 10; Expert (to 225) needs skill 125, level 20 and 50 silver; Artisan (to 300) needs skill 200 and level 35. Each rank must be bought from the right-tier trainer.", topic = "prof_alch_ench" }
add{ q = { "no alchemy trainer in mulgore", "dwarf alchemy trainer dun morogh", "tauren alchemy trainer", "cant find alchemy trainer", "no alchemy trainer mulgore", "dwarf alchemy trainer", "dun morogh alchemy trainer", "gnome alchemy trainer", "where do tauren learn alchemy", "im a tauren and theres no alchemy trainer in mulgore where do i go", "no alch trainer in my starting zone", "where do dwarves learn alchemy" }, a = "Tauren and Dwarf/Gnome starting zones have no Alchemy trainer: Tauren use Kray in Thunder Bluff (47.0, 34.6), Dwarves/Gnomes use Vosur Brakthel in Ironforge's Tinker Town (67.0, 54.2). If lost, ask any city guard and the trainer gets marked on your map.", topic = "prof_alch_ench" }
add{ q = { "alchemy 1-300 guide", "fastest alchemy leveling forever", "how to level alchemy", "alchemy leveling guide wow forever", "ALCHEMY GUIDE STEP BY STEP", "alchemy 1-300", "alchemy leveling guide", "fastest alchemy leveling", "alchemy guide forever", "alch 1 300", "alchemy levling guide", "whats the fastest way to level alchemy to 300 in forever", "ALCHEMY GUIDE 1-300 FOREVER PLS" }, a = "Wowhead's default Forever route:\n1. 1-12 Elixir of Minor Force (Silverleaf)\n2. 12-55 Elixir of Minor Defense (Silverleaf+Peacebloom)\n3. 55-65 Minor Mana Potion\n4. 65-90 Elixir of Minor Fortitude (2 Earthroot+Peacebloom)\n5. 90-120 Elixir of Wisdom (Mageroyal+2 Briarthorn)\n6. 120-160 Lesser Mana Potion\n7. 160-195 Mana Potion (Stranglekelp+Kingsblood)\n8. 195-205 Elixir of Agility\n9. 205-225 Greater Mana Potion\n10. 225 Philosopher's Stone (1 point)\n11. 226-240 Greater Mana Potion\n12. 240-260 Draught of Detect Undead (Arthas' Tears)\n13. 260-270 Superior Mana Potion\n14. 270-300 Major Discolored Healing Potion. About 316 crafts total.", topic = "prof_alch_ench" }
add{ q = { "alchemy 1-75", "alchemy 1 to 75 forever", "what to make alchemy level 1", "alchemy apprentice leveling", "alchemy 1 75", "alchemy at skill 1", "what to make at alchemy 1", "alch 1-75", "elixir of minor force leveling", "first alchemy recipes to level", "just learned alchemy what do i make first" }, a = "1-75 Alchemy:\n1. 1-12: Elixir of Minor Force x11 (11 Silverleaf, 11 Empty Vial).\n2. 12-55: Elixir of Minor Defense x43 (43 Silverleaf, 43 Peacebloom, 43 Empty Vial).\n3. At 50 train Journeyman (level 10). 55-65: Minor Mana Potion x10 (10 Mageroyal, 10 Peacebloom).\n4. 65-90: Elixir of Minor Fortitude (2 Earthroot + 1 Peacebloom each).\nBuy Empty Vials from any Alchemy/Trade Supplies vendor near the trainer.", topic = "prof_alch_ench" }
add{ q = { "alchemy 75-150", "alchemy 90 to 150", "journeyman alchemy what to craft", "alchemy 120", "alchemy 75 150", "alchemy 90 150", "journeyman alchemy what to make", "alchemy 120 what to craft", "alch 75-150", "im 90 alchemy what do i craft", "im 75 alchemy what should i craft now" }, a = "75-150 Alchemy:\n1. Finish Elixir of Minor Fortitude to 90 (26 crafts total: 52 Earthroot, 26 Peacebloom).\n2. 90-120: Elixir of Wisdom x30 (30 Mageroyal, 60 Briarthorn, 30 Empty Vial). Keep them if you level Tailoring.\n3. 120-150+: Lesser Mana Potion (1 Mageroyal, 1 Stranglekelp, 1 Empty Vial each). Wowhead runs this to 160 (43 crafts).\nAlternative 130-150: Fire Oil x20 from 40 Firefin Snapper, keeping 30 Fire Oil for Elixir of Fire Power at 150-165.\nTrain Expert at 125+ (level 20).", topic = "prof_alch_ench" }
add{ q = { "alchemy 150-225", "alchemy 150 to 225 forever", "expert alchemy leveling", "alchemy 195", "alchemy 150 225", "alchemy 195 what to make", "alch 150-225", "im 160 alchemy what do i craft", "mana potion leveling alchemy", "im 150 alch what do i make to get to 225", "alch 150-225 guide", "expert alch leveling" }, a = "150-225 Alchemy:\n1. Lesser Mana Potion to 160.\n2. 160-195: Mana Potion x38 (38 Stranglekelp, 38 Kingsblood, 38 Leaded Vial).\n3. 195-205: Elixir of Agility x10 (10 Stranglekelp, 10 Goldthorn, 10 Leaded Vial).\n4. 205-225: Greater Mana Potion x20 (20 Khadgar's Whisker, 20 Goldthorn, 20 Leaded Vial).\nAlternative: Nature Protection Potion (Liferoot + Stranglekelp) from 195-235, but its recipe is bind-on-pickup from Bronk/Logannas (Feralas), Glyx Brewright (STV) or Pestlezugg (Tanaris).\nTrain Artisan at 200+ (level 35).", topic = "prof_alch_ench" }
add{ q = { "alchemy 225-300", "alchemy 225 to 300 forever", "artisan alchemy leveling", "alchemy 270-300", "how to get alchemy to 300", "alchemy 225 300", "alchemy 270 300", "alch 225-300", "im 250 alchemy what do i make", "alchemy last 50 points", "im 225 alchemy how do i get to 300", "alch 225-300 guide", "artisan alch leveling" }, a = "225-300 Alchemy:\n1. 225-226: Philosopher's Stone (4 Iron Bar, 1 Black Vitriol, 4 Purple Lotus, 4 Firebloom; recipe from Alchemist Pestlezugg, Tanaris).\n2. 226-240: Greater Mana Potion x20.\n3. 240-260: Draught of Detect Undead x23 (1 Arthas' Tears + 1 Crystal Vial each).\n4. 260-270: Superior Mana Potion x10 (2 Sungrass, 2 Blindweed each; recipe Ulthir in Darnassus or Algernon in Undercity).\n5. 270-300: Major Discolored Healing Potion x31 (Plaguebloom, Murloc Eye, Crystal Vial; from Odd Child/Apothecary Renferrel).", topic = "prof_alch_ench" }
add{ q = { "alchemy shopping list", "what do i buy on ah for alchemy", "alchemy 1-300 mats list", "how many herbs for alchemy 300", "alchemy materials total", "alchemy mats list", "what do i buy for alchemy", "alch mats 1-300", "what herbs do i need to level alchemy", "how many herbs do i need to buy to level alchemy to 300", "alch shopping list", "what mats do i need for alch", "how many herbs for alch" }, a = "Approximate mats for Wowhead's 1-300 route: Peacebloom 79, Silverleaf 54, Mageroyal 83, Earthroot 52, Briarthorn 60, Stranglekelp 91, Kingsblood 38, Goldthorn 50, Khadgar's Whisker 40, Arthas' Tears 23, Sungrass 20, Blindweed 20, Plaguebloom 31, Murloc Eye 31, Purple Lotus 4, Firebloom 4, Iron Bar 4, Black Vitriol 1. Vials: 163 Empty, 88 Leaded, 64 Crystal (vendor). Counts are averages; buy a few extra.", topic = "prof_alch_ench" }
add{ q = { "cheap alchemy route", "alchemy route without murloc eyes", "alternative alchemy 265-300", "alchemy stonescale oil leveling", "greater defense elixir leveling", "alchemy without murloc eyes", "alternative alchemy route", "alchemy 265 300 alternative", "stonescale oil leveling", "greater defense elixir alchemy leveling", "cheaper way to level alch", "is there a cheaper alchemy route without murloc eyes" }, a = "wow-professions' alternative 225-300:\n1. 225-235 Nature Protection Potion (Liferoot+Stranglekelp).\n2. 235-250 Elixir of Greater Intellect (Blindweed+Khadgar's Whisker+Crystal Vial).\n3. 250-260 Stonescale Oil x47 (1 Stonescale Eel, makes 2; keep all).\n4. 260-265 Greater Intellect.\n5. 265-300 Elixir of Greater Defense x47 (2 Stonescale Oil, 1 Sungrass, 1 Crystal Vial).\nIf eels are pricey, skip oil and do ~55 Superior Mana Potions from 265 instead (110 Sungrass, 110 Blindweed).", topic = "prof_alch_ench" }
add{ q = { "how much does alchemy cost to level", "alchemy vendor cost forever", "how much gold for alchemy 300", "alchemy cost to level", "how much gold for alchemy", "alchemy 1-300 cost", "alchemy vendor cost", "is alchemy expensive to level", "how much g to get alchemy to 300", "how much will it cost me to level alchemy" }, a = "Kami-labs puts the vendor-only cost of 1-300 Alchemy (vials plus purchasable recipes) at about 19g 53s, of which about 5g 54s is recipes. Herbs come on top of that unless you pick them yourself with Herbalism.", topic = "prof_alch_ench" }
add{ q = { "where to buy vials", "empty vial vendor", "crystal vial vendor", "imbued vial where", "leaded vial forever", "crystal vial", "imbued vial", "leaded vial", "vial vendor location", "who sells crystal vials", "where do i get vials for alchemy", "where can i buy imbued vials" }, a = "Empty, Leaded and Crystal Vials are sold by Alchemy Supplies, Herbalism Supplies and general Trade Supplies vendors, usually standing near the trainers, in stacks of 5. Imbued Vials (needed for the new Natural flasks and several new 275+ potions) are only sold by Alchemy/Herbalism suppliers. Algernon (Undercity) and Narret Shadowgrove (Dolanaar) are handy vial vendors.", topic = "prof_alch_ench" }
add{ q = { "odd child westfall", "where is odd child", "discolored healing potion trainer", "moonbrook barn alchemy", "odd child location", "odd child", "who teaches discolored healing potion alliance", "odd child location forever", "where do i find odd child in westfall", "odd child moonbrook", "where is the odd child npc", "who is odd child", "odd child westfall barn" }, a = "Odd Child is a Forever-only NPC in the barn at Moonbrook, Westfall (about 41.1, 79.1). She teaches Alliance alchemists the Discolored Healing Potion line: Minor (50), Lesser (85), standard (135), Greater (175), Superior (230) and Major (250). Her quests start at level 10. Horde alchemists use Apothecary Renferrel at the Sepulcher in Silverpine Forest instead.", topic = "prof_alch_ench" }
add{ q = { "my first alchemy set quest", "my first real potion", "odd child quest requirements", "what do i need for odd child quest", "my first alchemy set", "my first real potion quest", "odd child quest", "what do i need for odd child", "my first alchemy set quest level", "how to start odd child quest", "what do i need to do the my first alchemy set quest" }, a = "My First Alchemy Set (level 10, Alliance, needs Alchemy as a primary profession): bring Odd Child in the Moonbrook barn 5 Empty Vials, 5 Peacebloom and 5 Silverleaf. Reward choice is 5 Minor Healing Potions or a Scribbled I.O.U. It leads straight into My First Real Potion.", topic = "prof_alch_ench" }
add{ q = { "apothecary renferrel discolored", "horde discolored healing potion", "sepulcher alchemy trainer", "major discolored healing potion horde", "apothecary renferrel", "who teaches discolored healing potion horde", "where is renferrel", "discolored potion horde trainer", "where do horde learn discolored healing potions", "renferrel discolored healing", "where is apothecary renferrel", "horde discolored pot trainer" }, a = "Horde alchemists learn the Discolored Healing Potion recipes (Minor through Major) from Apothecary Renferrel at the Sepulcher in Silverpine Forest. The Major version (Plaguebloom, Murloc Eye, Crystal Vial) is Wowhead's pick for 270-300 and needs a short questline first.", topic = "prof_alch_ench" }
add{ q = { "discolored healing potion mats", "what does discolored healing potion need", "murloc eye alchemy", "discolored potion reagents", "discolored healing potion reagents", "what does discolored potion need", "discolored pot recipe mats", "how to make discolored healing potion", "what mats do discolored healing potions need", "discolored pot mats", "murloc eye potion", "what herbs for discolored healing potion" }, a = "Discolored Healing Potions all use a Murloc Eye plus one herb: Minor (Peacebloom, Empty Vial), Lesser (Briarthorn, Empty Vial), standard (Bruiseweed, Leaded Vial), Greater (Kingsblood, Leaded Vial), Superior (Sungrass, Crystal Vial), Major (Plaguebloom, Crystal Vial). Buy Murloc Eyes on the AH or farm murlocs.", topic = "prof_alch_ench" }
add{ q = { "philosophers stone forever", "how to get philosopher's stone", "philosopher stone recipe where", "pestlezugg tanaris", "do i need philosophers stone for transmute", "philosophers stone", "how to get philosophers stone", "philosophers stone recipe", "pestlezugg", "philo stone forever", "philosopher stone where", "where do i get a philosophers stone for transmutes" }, a = "Philosopher's Stone is required as a tool for every transmute. In Forever you can learn it at 225 (changed from Classic). Recipe: Alchemist Pestlezugg in Gadgetzan, Tanaris (about 80s). Mats: 4 Iron Bar, 1 Black Vitriol, 4 Purple Lotus, 4 Firebloom. It also gives a skill point at 225.", topic = "prof_alch_ench" }
add{ q = { "arcanite transmute cooldown", "how often can i transmute arcanite", "arcanite cd forever", "transmute cooldown forever", "arcanite cooldown", "transmute cooldown", "arcanite cd", "how often can i transmute", "arcanite transmute timer", "how long is the arcanite cd in forever", "transmute cd forever", "how long is the arcanite transmute cooldown" }, a = "Transmute: Arcanite (Thorium Bar + Arcane Crystal = Arcanite Bar, needs skill 275 and a Philosopher's Stone) has a 47-hour cooldown in Forever. The new Legionite transmute is also 47 hours, and the elemental essence transmutes are about 23 hours.", topic = "prof_alch_ench" }
add{ q = { "how much gold does arcanite make", "is arcanite transmute worth it", "arcanite profit forever", "transmute gold per week", "arcanite profit", "is arcanite worth it", "how much gold arcanite", "transmute gold", "arcanite transmute profit forever", "how much do i make from arcanite", "is transmuting worth it", "is arcanite transmute still worth doing in forever" }, a = "Timesaver's US Alliance prices on Nov 16 2026 put Arcanite at about +36g profit per transmute (~130g/week if cast every cooldown) and Legionite at about +31g (~111g/week). Several essence transmutes (e.g. Water to Undeath) currently lose money. Prices move, so check Arcane Crystal vs Arcanite Bar on your AH first; buy the crystal and sell the bar yourself.", topic = "prof_alch_ench" }
add{ q = { "transmute legionite", "where to get legionite recipe", "legionite bar", "felguard sentinel recipe", "legionite recipe", "where to get legionite transmute", "how to make legionite", "legionite transmute recipe drop", "where do i get the transmute legionite recipe", "legionite transmute", "how do i transmute legionite", "legionite bar recipe" }, a = "Transmute: Legionite is Forever-only: Heavy Thorium Bar + Fel Crystal = Legionite Bar, skill 275, Philosopher's Stone required, 25-second cast and 47-hour cooldown. The recipe drops from Felguard Sentinels in Mount Hyjal. Legionite is a crafting reagent (e.g. the Legionite Glaive blacksmith pattern).", topic = "prof_alch_ench" }
add{ q = { "where to get transmute arcanite recipe", "arcanite recipe source", "learn arcanite transmute", "arcanite recipe", "where to get arcanite transmute", "learn arcanite", "arcanite transmute recipe", "who teaches arcanite", "transmute arcanite where to learn", "where do i learn transmute arcanite" }, a = "Transmute: Arcanite needs Alchemy 275 and a Philosopher's Stone. No Forever guide confirms the recipe source yet; in Classic, Recipe: Transmute Arcanite was sold by Alchemist Pestlezugg in Gadgetzan, Tanaris, who also sells the Philosopher's Stone and Iron to Gold recipes in Forever, so check him first.", src = "classic", topic = "prof_alch_ench" }
add{ q = { "iron to gold transmute", "mithril to truesilver", "is iron to gold worth it", "gold bar transmute", "iron to gold", "iron to gold worth it", "transmute iron to gold", "truesilver transmute", "is mithril to truesilver profitable", "is iron to gold transmute worth it in forever", "iron 2 gold", "mithril into truesilver" }, a = "Transmute Iron to Gold and Mithril to Truesilver are learnable at 225 in Forever (recipe from Alchemist Pestlezugg, Tanaris, about 80s) and can be done roughly once an hour. Timesaver says Iron to Gold only beats selling the Iron Bar if Iron Bars cost about 6s or less; Mithril to Truesilver currently loses money.", topic = "prof_alch_ench" }
add{ q = { "essence transmutes", "transmute earth to water", "transmute air to fire", "which essence transmute needs rep", "earth to water", "air to fire", "essence transmute rep", "transmute essence", "which transmute needs reputation", "elemental essence transmute", "which essence transmutes need rep" }, a = "Elemental essence transmutes (Air to Fire, Fire to Earth, Earth to Water, Water to Air, Earth to Life, Life to Earth, Water to Undeath, Undeath to Water) all need skill 275 and have ~23h cooldowns. Air to Fire requires Honored with Argent Dawn and Earth to Water requires Friendly with Timbermaw Hold. Transmute Elemental Fire (Heart of Fire into 3 Elemental Fire) needs 300 and Friendly Thorium Brotherhood.", topic = "prof_alch_ench" }
add{ q = { "what flasks are in forever", "list of flasks forever", "forever flasks", "flask recipes forever", "flasks forever", "list of flasks", "what flasks are there", "flask recipes", "all flasks forever", "how many flasks in forever", "new flasks forever", "what flasks can i make in forever" }, a = "Forever has 9 flasks, all skill 300: the five Classic ones (Titans, Supreme Power, Distilled Wisdom, Chromatic Resistance, Petrification) and four new Natural flasks (Accuracy, Aggression, Precision, Swiftness). Classic flasks cost 30 of a main herb, 10 of a secondary, 1 Black Lotus and 1 Crystal Vial; Natural flasks use Death Lotus, Demonsage or Marefoil and an Imbued Vial.", topic = "prof_alch_ench" }
add{ q = { "flask of the titans recipe", "where does titans flask drop", "flask of titans forever", "drakkisath flask recipe", "flask of titans recipe", "titans recipe drop", "drakkisath flask", "flask of the titans", "titans flask forever", "where does flask of titans drop", "titans flask recipe ubrs", "where does the flask of the titans recipe drop" }, a = "Recipe: Flask of the Titans drops from General Drakkisath in Upper Blackrock Spire (~3%). Flask: +1200 max health, persists through death. Mats: 30 Gromsblood, 10 Stonescale Oil, 1 Black Lotus, 1 Crystal Vial; craft at an Alchemy Laboratory.", topic = "prof_alch_ench" }
add{ q = { "flask of supreme power recipe", "supreme power drop", "ras frostwhisper recipe", "caster flask forever", "supreme power recipe", "flask of supreme power", "caster flask", "where does supreme power drop", "sp flask recipe", "where do i get flask of supreme power recipe", "supreme power flask recipe", "where to get supreme power" }, a = "Recipe: Flask of Supreme Power drops from Ras Frostwhisper in Scholomance (~4%). Flask gives +150 spell damage. Mats: 30 Dreamfoil, 10 Mountain Silversage, 1 Black Lotus, 1 Crystal Vial.", topic = "prof_alch_ench" }
add{ q = { "distilled wisdom recipe", "flask of distilled wisdom where", "chromatic resistance recipe", "pix xizzix", "flask of distilled wisdom", "wisdom flask recipe", "where is pix xizzix", "where to buy distilled wisdom recipe", "where do i buy flask of distilled wisdom recipe", "distilled wisdom flask recipe", "where to get wisdom flask", "pix xizzix stv" }, a = "Pix Xizzix (Stranglethorn Vale) sells Recipe: Flask of Distilled Wisdom and Recipe: Flask of Chromatic Resistance for 4g each. Distilled Wisdom (+2000 max mana): 30 Dreamfoil, 10 Icecap, Black Lotus, Crystal Vial. Chromatic Resistance: 30 Icecap, 10 Mountain Silversage, Black Lotus, Crystal Vial. Distilled Wisdom also drops in Stratholme, Chromatic from Gyth in UBRS.", topic = "prof_alch_ench" }
add{ q = { "flask of petrification recipe", "petrification drop", "where to get petrification flask", "petrification recipe", "flask of petrification", "petrification flask", "where does petrification drop", "frostmaul giant recipe", "where does the petrification recipe drop", "petrification recipe drop", "petri flask recipe" }, a = "Recipe: Flask of Petrification drops very rarely from Frostmaul Giants in Winterspring (~0.1%) and Chieftain Bloodmaw in Felwood (~0.02%). Mats: 30 Stonescale Oil, 10 Mountain Silversage, 1 Black Lotus, 1 Crystal Vial.", topic = "prof_alch_ench" }
add{ q = { "flask of natural aggression", "natural flasks forever", "hyjal flask", "flask of natural swiftness", "flask of natural precision accuracy", "natural flasks", "flask of natural precision", "hyjal flasks", "what do natural flasks do", "natural flask stats", "what do the new natural flasks give", "natural flask", "nature flasks hyjal" }, a = "The new Natural flasks (level 55, 2 hours, persist through death) all give +60 Stamina everywhere, plus a bonus only in Mount Hyjal, Hyjal Summit and the Barrow Deeps:\n- Accuracy: +5% hit (1 Death Lotus, 12 Demonsage, 9 Golden Sansam)\n- Aggression: +4% crit (1 Death Lotus, 18 Demonsage, 6 Mountain Silversage)\n- Precision: -5% chance to be dodged/parried (1 Death Lotus, 12 Marefoil, 9 Dreamfoil)\n- Swiftness: +5% haste (1 Death Lotus, 18 Marefoil, 6 Icecap)\nEach also needs an Imbued Vial. Recipe sources are not documented yet.", topic = "prof_alch_ench" }
add{ q = { "where do i make flasks", "do i need scholomance for flasks", "alchemy lab forever", "alchemy laboratory placeable", "how to craft flask without scholo", "where to make flasks", "do i need scholo for flasks", "alchemy lab", "alchemy laboratory", "craft flasks without scholomance", "where do i craft flasks in forever", "alchemist lab placeable", "do i still need the scholomance lab to make flasks" }, a = "In Forever you don't need the Scholomance lab. At 300 Alchemy you get the Alchemy Laboratory camp object (made from 1 Lich's Index Finger, 1 Crystal Vial, 2 Dreamfoil) that you place at a Campfire; flasks are crafted next to it. It also includes the Mana Well and Fermenter effects. Its exact source is still listed as unknown on Wowhead.", topic = "prof_alch_ench" }
add{ q = { "do flasks stack with elixirs forever", "can i use flask and elixir", "flask elixir stacking forever", "flask and elixir stack", "do flasks stack with elixirs", "flask elixir stacking", "can i flask and use elixirs", "flask elixir stack forever", "can i run a flask and elixirs at the same time in forever", "flask + elixir", "do elixirs stack with flask" }, a = "According to Method's Forever beta consumables guide, flasks now stack with elixirs in Forever (they didn't stack this way in Classic). Flasks last through death; elixirs are lost on death. Only one flask can be active at a time.", topic = "prof_alch_ench" }
add{ q = { "death lotus where", "how to get death lotus", "lotus claw enchant", "demonsage marefoil", "death lotus", "lotus claw", "demonsage", "marefoil", "where to get death lotus", "herbs for natural flasks", "where do i get death lotus for natural flasks" }, a = "Death Lotus, Demonsage and Marefoil are the new herbs behind the Natural flasks, tied to Mount Hyjal. Enchanters can put Enchant Gloves - Lotus Claw on gloves, which gives a small chance to get Death Lotus when gathering herbs in Hyjal. Natural Power gloves also cost 4 Death Lotus.", topic = "prof_alch_ench" }
add{ q = { "mongoose recipe", "elixir of the mongoose where", "mongoose drop forever", "jadefire rogue", "elixir of the mongoose", "mongoose drop", "where does mongoose drop", "mongoose recipe felwood", "elixir of mongoose recipe forever", "where does the mongoose recipe drop", "mongoose elixir recipe", "mongoose recipe where" }, a = "Recipe: Elixir of the Mongoose (skill 280) drops from Jadefire Rogues in Felwood (~4%) and Legashi Rogues in Azshara (~3.6%). Each elixir: 2 Mountain Silversage, 2 Plaguebloom, 1 Crystal Vial.", topic = "prof_alch_ench" }
add{ q = { "greater fire protection potion recipe", "gfpp recipe", "firebrand recipe ubrs", "fire protection potion where", "greater fire protection potion", "firebrand recipe", "fire protection potion recipe", "where does gfpp drop", "gfpp drop ubrs", "fire resist potion recipe", "where does greater fire protection potion recipe drop" }, a = "Recipe: Greater Fire Protection Potion (skill 290) drops from Firebrand Invokers and Firebrand Pyromancers in Blackrock Spire (~4% each). Each potion: 1 Elemental Fire, 1 Dreamfoil, 1 Crystal Vial. The basic Fire Protection Potion recipe is sold by Nandar Branson in Hillsbrad (Alliance, limited stock).", topic = "prof_alch_ench" }
add{ q = { "greater arcane elixir recipe", "major mana potion recipe", "magnus frostwake recipe", "magnus frostwake", "where is magnus frostwake", "gae recipe", "major mana pot recipe where", "greater arcane recipe", "where do i get the major mana potion recipe", "major mana recipe", "gae recipe where" }, a = "Major Mana Potion (295) recipe: Magnus Frostwake in Western Plaguelands, about 3g; mats 3 Dreamfoil, 2 Icecap, Crystal Vial. Greater Arcane Elixir (285) is a very rare world drop (e.g. Angerclaw Grizzly, Blighted Horror ~0.02%); mats 3 Dreamfoil, 1 Mountain Silversage, Crystal Vial.", topic = "prof_alch_ench" }
add{ q = { "free action potion recipe", "fap recipe where", "ulthir recipe", "kor'geld recipe", "fap recipe", "ulthir", "korgeld", "where to buy fap recipe", "free action recipe vendor", "who sells free action potion recipe", "where can i buy the free action potion recipe" }, a = "Recipe: Free Action Potion is sold by Ulthir in Darnassus (Alliance) and Kor'geld in Orgrimmar (Horde) for about 18s, limited stock, so check back after it restocks.", topic = "prof_alch_ench" }
add{ q = { "greater stoneshield recipe", "limited invulnerability recipe", "lip recipe forever", "elixir of brute force", "greater stoneshield", "limited invulnerability potion", "lip recipe", "stoneshield recipe", "where does lip recipe drop", "brute force recipe", "where do i get the limited invulnerability potion recipe" }, a = "Greater Stoneshield Potion (280; 3 Stonescale Oil, 1 Thorium Ore, Crystal Vial) drops from Dessecus in Felwood or Shade of Ambermoon. Limited Invulnerability Potion (250; 2 Blindweed, 1 Ghost Mushroom, Crystal Vial) is a rare drop (Witherheart the Stalker, Ravasaur Matriarch). Elixir of Brute Force (275; 2 Gromsblood, 2 Plaguebloom) comes from a Small Brown-wrapped Package.", topic = "prof_alch_ench" }
add{ q = { "major rejuvenation potion", "gurubashi mojo madness", "refined scale of onyxia", "mojo madness recipe", "major rejuv pot", "are major rejuvs still in forever", "is major rejuvenation potion still in forever", "major rejuv recipe", "mojo madness", "onyxia scale potion", "major rejuvenation recipe" }, a = "Still in Forever at 300: Major Rejuvenation Potion (4 Heart of the Wild, 4 Golden Sansam, 1 Dreamfoil, Imbued Vial), Gurubashi Mojo Madness (Blood of Heroes, 6 Massive Mojo, Powerful Mojo, Black Lotus) and Refined Scale of Onyxia (from a Scale of Onyxia).", topic = "prof_alch_ench" }
add{ q = { "new elixirs forever", "elixir of the grizzly", "elixir of cunning", "elixir of ferocity", "new alchemy recipes merchant's favor", "new elixirs", "merchants favor alchemy", "what new elixirs are in forever", "best new elixirs forever", "what are the best new elixirs in forever", "grizzly elixir", "ferocity elixir", "cunning elixir" }, a = "Top new Forever elixirs (all from Merchant's Favor vendors at Honored):\n- Elixir of the Grizzly (300): Strength + crit; 3 Gromsblood, Blindweed, Crystal Vial; 240 MF.\n- Elixir of Cunning (275): Agility + Intellect (great for MM Hunters); 3 Dreamfoil, 2 Gromsblood.\n- Elixir of Ferocity (275): 3 Gromsblood, Ghost Mushroom.\n- Elixir of Sages (275), Owl (280): caster elixirs using Dreamfoil + Imbued Vial.\n- Elixir of the Whale (275), Nature Power (285), Wicked Regeneration (285), Phalanx (250, armor).\nMost cost 180 Merchant's Favor.", topic = "prof_alch_ench" }
add{ q = { "frenzy potion", "spellblasting potion", "mender's potion", "major frenzy potion what does it do", "menders potion", "major frenzy potion", "new combat potions", "what does frenzy potion do", "what is menders potion", "what do the new frenzy and spellblasting potions do", "frenzy pot", "spellblasting pot" }, a = "New Forever 30-second combat potions come in Minor to Major tiers: Frenzy (attack power; Major = +80 AP), Spellblasting (spell damage; Major = +47) and Mender's (healing; Major = +88). Major Frenzy (290) needs 3 Plaguebloom, 2 Blindweed, Imbued Vial (240 Merchant's Favor); Major Spellblasting (285) and Major Mender's (280) cost 180 MF.", topic = "prof_alch_ench" }
add{ q = { "cleric's elixir", "mageblood elixir forever", "greater cleric's elixir", "healer elixirs forever", "clerics elixir", "mageblood elixir", "greater clerics elixir", "healer elixirs", "healing elixir forever", "mana regen elixir forever", "what elixirs for healers", "what elixirs can i make for healers in forever" }, a = "Healer elixirs new in Forever: Cleric's line (healing) and Mageblood line (mana regen). Minor/Lesser versions are drops or 45 Merchant's Favor; Greater Cleric's Elixir (195; 3 Arthas' Tears, Purple Lotus, Crystal Vial) and Greater Mageblood (175) need Friendly with the commerce faction and 120 MF.", topic = "prof_alch_ench" }
add{ q = { "minor arcane elixir", "rage potion druid", "low level alchemy new recipes", "rage potion", "low level alchemy recipes", "new low level alchemy", "druid rage potion", "minor arcane elixir recipe", "new alchemy recipes at low skill", "what new low level alchemy recipes are there" }, a = "Minor Arcane Elixir is a new spell power elixir known from skill 1 (just Peacebloom + Empty Vial). Rage Potion can now be used by Druids as well as Warriors; its recipe is 1s from Xandar Goodbeard or the Defias Profiteer, and it's a good 71-100 leveling recipe.", topic = "prof_alch_ench" }
add{ q = { "greater spellblasting recipe", "a new need for shadow protection", "carved centaur totem", "gorhak molkar", "greater frenzy recipe", "how to get greater spellblasting", "where is gorhak molkar", "how do i get the greater spellblasting recipe", "spellblasting recipe quest", "centaur totem quest", "a new need for shadow protection quest", "greater frenzy potion recipe" }, a = "Greater Spellblasting and Greater Frenzy Potion recipes come from the quest A New Need for Shadow Protection, or from vendors Gorhak (15 Carved Centaur Totems) or Molkar (60 Carved Centaur Totems).", topic = "prof_alch_ench" }
add{ q = { "alchemy dyes", "cerulean dye", "magenta dye", "viridian dye", "sulfuric acid alchemy", "sulfuric acid", "can alchemists make dyes", "dye recipes alchemy", "can alchemists make dyes in forever", "dyes alchemy", "how to make dyes", "how do i make cerulean dye", "sulfuric acid recipe" }, a = "Forever lets alchemists make dyes and acids used by other professions (e.g. Enchanting necklace and staff recipes): Cerulean Dye and Sulfuric Acid at 40, Magenta Dye at 120, Viridian Dye at 220 (2 Stranglevine + Crystal Vial). All are trainer recipes.", topic = "prof_alch_ench" }
add{ q = { "dragonfire potion", "caustic smog", "potion of venomous blood", "elemental purging potion", "what does dragonfire potion do", "new 245 potions", "caustic smog recipe", "what does the dragonfire potion do", "dragonfire pot", "venomous blood potion", "purging potion", "caustic smog potion" }, a = "Other new 245-280 potions sold for Merchant's Favor: Dragonfire Potion (245; 2 Mountain Silversage, 2 Firebloom; Friendly, 120 MF), Caustic Smog Potion (265), Potion of Venomous Blood (275), Potion of Elemental Purging (280; 2 Firebloom, 2 Wintersbite), all Honored and 180 MF.", topic = "prof_alch_ench" }
add{ q = { "mana well alchemy", "what is the mana well", "alchemy camp objects", "fermenter where to get", "rath'mael fermenter", "mana well", "what is mana well", "alchemy camp", "fermenter", "rathmael fermenter", "alchemy camp buff", "where to get fermenter", "what alchemy camp items are there" }, a = "Alchemy camp objects (placed at a Campfire; sitting at them gives an MP5 buff that doesn't stack with Blessing of Wisdom):\n1. Mana Well, skill 20, from the trainer.\n2. Fermenter, skill 140 (Leaded Vial, Kingsblood, Swiftthistle); blueprint drops from Rath'mael in the Ruins of Lordaeron. Unlocks some recipes and includes the Mana Well.\n3. Alchemy Laboratory, skill 300; needed for flasks, includes both previous objects.", topic = "prof_alch_ench" }
add{ q = { "where is alchemy recipe vendor merchant's favor", "nina surefire", "apothecary durelle", "where do i buy new alchemy recipes", "alchemy recipe vendor", "where to buy new alchemy recipes", "merchants favor alchemy vendor", "where is nina surefire", "new alch recipes vendor", "where do i buy the new alchemy recipes", "alch recipes vendor", "merchant favor alchemy recipes" }, a = "New alchemy recipes are sold for Merchant's Favor by Nina Surefire at the Azeroth Commerce Authority camp (Three Corners, west edge of Redridge Mountains, Alliance) and Apothecary Durelle at Durotar Supply and Logistics (just outside the Crossroads west gate, Barrens, Horde). 28 recipes, 45-240 MF; a few need Friendly, most need Honored.", topic = "prof_alch_ench" }
add{ q = { "where is enchanting recipe vendor merchant's favor", "alynsia", "beneris", "necklace enchant recipe where", "enchanting recipe vendor", "necklace enchant recipe", "where to buy new enchanting formulas", "merchants favor enchanting vendor", "where is alynsia", "where do i buy the new enchanting recipes", "ench recipe vendor", "merchant favor enchanting formulas" }, a = "New enchanting formulas are sold for Merchant's Favor by Alynsia (Azeroth Commerce Authority, Three Corners, Redridge, Alliance) and Beneris (Durotar Supply and Logistics, outside the Crossroads west gate, Horde). 39 formulas: 140-skill weapon enchants 45 MF (no rep), necklaces and Chest Absorption 120 MF at Friendly, 2H and most bracer/cloak/glove/off-hand enchants 240 MF at Honored.", topic = "prof_alch_ench" }
add{ q = { "how to get merchant's favor", "merchant's favor farm", "waylaid crate", "how to get recipes from commerce authority", "merchants favor", "how to get merchants favor", "merchants favor farm", "commerce authority recipes", "fastest merchants favor", "what is merchants favor", "whats the fastest way to get merchants favor" }, a = "Merchant's Favor:\n1. Loot a Waylaid Crate, fill it with the listed bundle of mats so it becomes Sealed (binds to you).\n2. Turn it in at your camp (Marcy Baker at Three Corners for Alliance, Dokimi outside the Crossroads for Horde): roughly 5-30 Favor depending on tier.\n3. The first crate's Shipping Label starts a quest worth 2,000 rep and 50 Favor.\nDaily Craftsman's Writs give rep (75/125/200) but no Favor.", topic = "prof_alch_ench" }
add{ q = { "alchemy certification", "enchanting certification", "alchemist title forever", "how to get enchanter title", "alchemist title", "enchanter title", "how to get alchemist title", "profession title forever", "certification cost merchants favor", "how do i get the alchemist title in forever", "enchanter title how", "how do i become certified alchemist" }, a = "Alchemy Certification and Enchanting Certification each cost 1,000 Merchant's Favor from the profession's commerce-camp vendor and need 300 skill. They unlock the profession title (e.g. \"the Alchemist\") account-wide; a character needs 300 in that profession to show it.", topic = "prof_alch_ench" }
add{ q = { "working overtime talent", "dedicated study", "legacy profession talents", "how to level professions faster forever", "working overtime", "level professions faster", "best legacy talents for professions", "faster skill ups forever", "legacy professions tree", "how do i level my professions faster in forever", "legacy talents professions", "working overtime legacy talent" }, a = "Legacy Professions tree: Working Overtime (5 ranks, +4% each to skill-up chance in primary, secondary and class tradeskills) and Dedicated Study (raises your lowest primary or secondary tradeskill by 1; 25s cast, 23h cooldown; once everything is 300 it gives 2-4 random Elemental Essences instead). Each profession gives a Legacy point at 150, 225 and 300.", topic = "prof_alch_ench" }
add{ q = { "what changed with enchanting in forever", "enchanting changes forever", "is enchanting worth it forever", "forever enchanting whats new", "enchanting changes", "what changed with enchanting", "is enchanting worth it", "whats new with enchanting", "enchanting forever vs classic", "did they change enchanting", "is enchanting good in forever", "is enchanting worth leveling in forever" }, a = "Enchanting in Forever:\n1. About 40 new formulas: necklace enchants (new slot), off-hand Wisdom, Insight/Recovery/Revelation weapon procs, Mighty Healing/Spell Power and Spellblasting 2H, Superior Strength/Agility/Deflection etc.\n2. Enchanters craft wands, staves, off-hand orbs and class relics (idols, librams, totems).\n3. Many old enchants were buffed or made cheaper.\n4. Camp objects (Enchanted Lute, Arcane Salvager, Arcane Forge) give a Mark of the Wild-style buff.\n5. Artisan is taught only by Annora in Uldaman.", topic = "prof_alch_ench" }
add{ q = { "novice's practice wand", "can enchanters make wands", "enchanting wands forever", "best wand enchanting", "novices practice wand", "enchanters make wands", "enchanting wands", "best enchanting wand", "can enchanters craft wands", "practice wand", "enchanting wand recipes", "can enchanters make wands in forever" }, a = "Enchanters can craft a Novice's Practice Wand at skill 1, and wands now carry spell power from level 5. Crafted wands: Lesser Mystic (175), Twisted Nether (185, +6 SP), Dreambough (215, +7 SP), Lesser Eternal (245, +8 SP), Greater Eternal (275, +9 SP), Brilliant Wand (275, +7 Int +9 SP). All use Star Wood plus enchanting mats and come from the trainer.", topic = "prof_alch_ench" }
add{ q = { "enchanting staves", "glimmering staff", "dreamstaff radiant staff", "soulstaff", "dreamstaff", "radiant staff", "can enchanters make staffs", "enchanter staff recipes", "what staves can enchanters craft", "enchanter staffs", "enchanting staff recipes", "can enchanters craft a staff" }, a = "Enchanter-made staves: Glimmering Staff and Soulstaff at 140 (+11 Stamina, +11 Intellect; Glimmering Shards, 4 Star Wood, Greater Astral Essence plus dust), Dreamstaff and Radiant Staff at 220 (+19 Stamina, +19 Intellect; Radiant Shards, Star Wood, Greater Nether Essence, Dream Dust and dyes).", topic = "prof_alch_ench" }
add{ q = { "enchanting relics", "idol libram totem enchanting", "polished driftwood icon", "tenets of the silver hand", "mystic mushroom idol", "idol libram totem", "can enchanters make relics", "enchanter relic recipes", "can enchanters make idols librams and totems", "enchanter idols", "enchanter librams", "enchanter totems", "enchanting relic recipe" }, a = "Enchanters make class relics in Forever. Druid idols: Mystic Mushroom (+5% Spirit), Talons of Wrath, Idol of Swiftness, Ursine Twins, Idol of the Dream. Paladin librams: Tenets of the Silver Hand, Invocation, Steadfast, Infusion, Holy Alacrity. Shaman totems: Polished Driftwood Icon (8% regen while casting), Ancestral Protection, Urgency, Thunder. Higher ones (300) need dyes, Star Wood and Brilliant shards.", topic = "prof_alch_ench" }
add{ q = { "orb of mystic insight", "enchanting off hand", "twisting essence jar", "orb of souls", "enchanter offhand recipes", "can enchanters make offhands", "what off hands can enchanters make", "enchanting offhands", "enchanter off hand", "orb enchanting recipe", "can enchanters make an orb" }, a = "Enchanter-made off-hands: Orb of Mystic Insight (+6 Int, +7 spell power), Orb of Souls (+6 Spirit, small damage/healing), Twisting Essence Jar (+8 Stamina, +8 Spirit, +6 damage, +19 healing), and Truesilver Conduit. Off-hands can also take the new Enchant Off-Hand - Wisdom (+6 Int, +5 Spirit).", topic = "prof_alch_ench" }
add{ q = { "hearts of the mountain", "molten heart of the mountain", "frozen heart trinket", "enchanting trinkets", "heart of the mountain", "frozen heart", "enchanter trinket", "can enchanters make trinkets", "heart of the mountain trinket", "what trinkets can enchanters craft in forever", "enchanter trinkets", "heart of mountain" }, a = "Enchanters craft Heart of the Mountain trinkets: Molten (+55 AP for 15s, doubled in volcanic zones), Frozen (+29 Frost/Shadow damage, doubled in snowy zones), Dormant (+40 healing on some heals), all at 285; Smoking Heart of the Mountain at 265.", topic = "prof_alch_ench" }
add{ q = { "enchanting camp", "enchanted lute", "arcane salvager", "arcane forge", "mark of the wild camp buff", "enchanting camp objects", "enchanting camp buff", "mark of the wild camp", "what enchanting camp items are there", "enchanting camp items", "enchanted lute buff", "arcane forge camp", "what does the enchanted lute do" }, a = "Enchanting camp objects: Enchanted Lute (+28 armor buff that doesn't stack with Mark of the Wild), Arcane Salvager (skill 140) and Arcane Forge (skill 300), which upgrade that buff further. Arcane Salvager and Forge also act as enchanting workstations.", topic = "prof_alch_ench" }
add{ q = { "enchanting trainer stormwind", "alliance enchanting trainer", "enchanting trainer ironforge darnassus", "where to learn enchanting alliance", "enchanting trainer sw", "enchanting trainer if", "enchanting trainer darnassus", "where is enchanting trainer in stormwind", "ench trainer alliance", "where do i learn enchanting in stormwind", "ench trainer sw", "enchanting trainer ironforge" }, a = "Alliance Enchanting: Apprentice Betty Quin (Stormwind Mage Quarter 53.0, 73.7), Thonys Pillarstone (Ironforge 60.3, 45.4), Lalina Summermoon (Darnassus 58.9, 12.8), Alanna Raveneye (Teldrassil 36.7, 34.2). Journeyman (skill 50, level 10): Lucan Cordell (Stormwind 53.1, 74.3), Gimble Thistlefuzz (Ironforge 59.8, 45.5), Taladan (Darnassus 58.6, 13.2), Xylinnia Starshine (Feralas 31.5, 44.2). Vanessa Sellers in Dalaran (16.8, 62.2) trains up to Expert.", topic = "prof_alch_ench" }
add{ q = { "enchanting trainer orgrimmar", "horde enchanting trainer", "enchanting trainer undercity", "enchanting trainer thunder bluff", "enchanting trainer org", "enchanting trainer uc", "enchanting trainer tb", "where to learn enchanting horde", "where is enchanting trainer in orgrimmar", "ench trainer horde", "where do i learn enchanting as horde", "where do i learn enchanting in thunder bluff" }, a = "Horde Enchanting: Apprentice Jhag (Orgrimmar 53.5, 38.4), Malcomb Wynn (Undercity 62.4, 60.8), Mot Dawnstrider (Thunder Bluff 44.6, 38.5), Pa'zula (Sen'jin Village 56.5, 73.6), Vance Undergloom (upstairs in Brill inn, 61.8, 51.6). Journeyman (skill 50, level 10): Godan (Orgrimmar 53.8, 38.5), Lavinia Crowe (Undercity 62.4, 61.6), Teg Dawnstrider (Thunder Bluff 44.9, 37.7).", topic = "prof_alch_ench" }
add{ q = { "expert enchanting trainer", "where to learn expert enchanting", "hgarth", "kitta firewind", "enchanting 150 trainer", "enchanting trainer 150", "im 150 enchanting where do i train", "where is kitta firewind", "where is hgarth", "where do i learn expert enchanting as alliance", "expert ench trainer", "ench trainer 150", "where to train expert enchanting" }, a = "Expert Enchanting (to 225; needs skill 125, level 20, 50s): Alliance: Kitta Firewind at the top of the Tower of Azora, Elwynn Forest (64.9, 70.6), Vanessa Sellers in Dalaran (16.8, 62.2) or Melanie Sable in Riverglades (66.2, 83.2). Horde: Hgarth in Sun Rock Retreat, Stonetalon (49.2, 57.1); he's up on a cliff, take the path starting northeast of the biggest tent.", topic = "prof_alch_ench" }
add{ q = { "enchanting trainer zephras isle", "skyborne enchanting trainer", "eaysaa brightgust", "nasalanna windsinger", "where do skyborne learn enchanting", "zephras enchanting trainer", "where can skyborne learn enchanting on zephras isle", "zephras isle enchanting", "skyborne ench trainer", "enchanting trainer valanaar", "enchanting trainer shendar" }, a = "Zephras Isle Apprentice Enchanting trainers: Eaysaa Brightgust in Valanaar (59.2, 76.3) and Nasalanna Windsinger in Shen'dar Village (43.2, 43.2). Only the Zephras Isle and Brill trainers among starting zones sell Mote of Magic; others must shop in a capital.", topic = "prof_alch_ench" }
add{ q = { "enchanting 1-75", "enchanting 1 to 70", "what to enchant at level 1", "mote of magic", "enchanting 1 75", "enchanting 1 70", "what to enchant at 1", "ench 1-75", "just learned enchanting what do i make first", "first enchanting recipes", "just learned enchanting what should i make first" }, a = "1-75 Enchanting:\n1. Buy a Copper Rod and Motes of Magic from the Enchanting Supplies vendor next to the trainer.\n2. 1-2: Runed Copper Rod (Copper Rod + 1 Mote).\n3. 2-20: Enchant Bracer - Inferior Stamina x18 (18 Motes).\n4. 20-70: Enchant Chest - Inferior Stamina x50 (50 Strange Dust), or Bracer - Minor Deflect with Lesser Magic Essence instead.\nRight-click a Greater Magic Essence to split it into 3 Lesser. Train Journeyman at 50 (level 10).", topic = "prof_alch_ench" }
add{ q = { "enchanting 75-150", "enchanting 70 to 150", "journeyman enchanting leveling", "runed silver rod", "enchanting 75 150", "enchanting 70 150", "ench 75-150", "im 100 enchanting what do i make", "im 75 enchanting what should i make now", "ench 75-150 guide", "journeyman ench leveling", "enchanting 100 what to make" }, a = "70-150 Enchanting (Strange Dust path):\n1. 70-100: Bracer - Minor Stamina x30 (60 Strange Dust).\n2. 100-109: Cloak - Minor Protection x9.\n3. 109-110: Runed Silver Rod (Silver Rod from a Blacksmith/AH, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem).\n4. 110-130: Cloak - Minor Protection x32 (64 Strange Dust).\n5. 130-150: Boots - Minor Stamina x20 (80 Strange Dust), or Bracer - Lesser Stamina x20 with Soul Dust if cheaper.\nEssence path: Chest Minor Absorption to 109, then 2H Lesser Intellect (formula from Kithas, Nata Dawnstrider, Leo Sarn or Tilli Thistlefuzz).", topic = "prof_alch_ench" }
add{ q = { "enchanting 150-225", "enchanting 150 to 225", "expert enchanting leveling", "runed golden rod", "runed truesilver rod", "enchanting 150 225", "ench 150-225", "im 175 enchanting what do i make", "im 150 enchanting what do i make to 225", "ench 150-225 guide", "expert ench leveling", "enchanting 175", "what to enchant at 150" }, a = "150-225 Enchanting:\n1. 150: Runed Golden Rod (Golden Rod, Iridescent Pearl, Greater Astral Essence, Soul Dust).\n2. 151-165: Minor Mana Oil x16 (16 Soul Dust, 32 Maple Seed, 16 Leaded Vial).\n3. 165-200: Boots - Lesser Agility x47 (47 Soul Dust); or switch to Bracer - Strength with Vision Dust at 185 if cheaper.\n4. 200: Runed Truesilver Rod (Truesilver Rod, Black Pearl, Greater Mystic Essence, Vision Dust).\n5. 201-220: Lesser Wizard Oil x25 (25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial).\n6. 220-225: Cloak - Greater Defense x5.\nOil formulas: Kithas, Nata Dawnstrider, Thaddeus Webb, Vaean, Tilli Thistlefuzz or Jessara Cordell.", topic = "prof_alch_ench" }
add{ q = { "enchanting 225-300", "enchanting 250 to 300", "artisan enchanting leveling", "enchanting 265-300", "runed arcanite rod", "enchanting 225 300", "enchanting 265 300", "ench 225-300", "im 250 enchanting how do i get to 300", "enchanting last 50 points", "im 225 enchanting how do i get to 300", "ench 225-300 guide", "artisan ench leveling" }, a = "225-300 Enchanting:\n1. Learn Artisan + all recipes from Annora (Uldaman).\n2. 225-250: Gloves - Agility x37 (37 Vision Dust).\n3. 250-265: Lesser Mana Oil x20 (Dream Dust, Purple Lotus, Crystal Vial; formula from Kania upstairs in the Silithus inn). No lotus? Bracer - Greater Strength instead.\n4. 265-299: Shield - Greater Stamina x40 (6 Dream Dust each, 240 total); formula BoP from Daniel Bartlett (Undercity) or Mythrin'dir (Darnassus). Turns yellow at 285.\n5. 299-300: Runed Arcanite Rod (Arcanite Rod, Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small + 2 Large Brilliant Shards); formula from Lorelae Wintersong, Nighthaven, Moonglade.", topic = "prof_alch_ench" }
add{ q = { "enchanting shopping list", "what do i buy for enchanting", "how much dust for enchanting 300", "enchanting mats list", "what to buy for enchanting", "how much dust for enchanting", "ench mats 1-300", "how many strange dust to level enchanting", "what do i need from ah for enchanting", "how much dust do i need to level enchanting to 300", "ench shopping list", "how much dust for ench" }, a = "Rough enchanting mats (wow-professions): 1-150: 19 Mote of Magic, Copper Rod, ~275 Strange Dust, Silver Rod, Shadowgem, 4 Lesser Magic Essence. 150-225: 64 Soul Dust, ~31 Vision Dust, Golden Rod, Truesilver Rod, Iridescent and Black Pearl, Greater Astral and Greater Mystic Essence, 32 Maple Seed, 50 Stranglethorn Seed, 41 Leaded Vial. 225-300: 37 Vision Dust, 260 Dream Dust, 20 Purple Lotus, 20 Crystal Vial, Arcanite Rod, Golden Pearl, 10 Illusion Dust, 4 Greater Eternal, 4 Small + 2 Large Brilliant Shard.", topic = "prof_alch_ench" }
add{ q = { "enchanting rods", "where to get runed rods", "copper rod silver rod golden rod", "do enchanters need a rod", "runed rods", "copper rod", "silver rod", "golden rod", "where do i get runed rods", "which rod do i need for enchanting", "where do i get the runed rods for enchanting" }, a = "Enchanters need a Runed rod for most recipes. The base rods come from Blacksmiths (Copper Rod is also sold by Enchanting Supplies vendors); you then enchant them yourself: Runed Copper (1), Silver (~110), Golden (150), Truesilver (200), Arcanite (290-300). Buy Silver/Golden/Truesilver/Arcanite Rods on the AH or from a Blacksmith.", topic = "prof_alch_ench" }
add{ q = { "enchanting craft macro", "enchanting macro forever", "how to spam enchant vellum", "enchant replace prompt macro", "enchanting macro", "enchant craft macro", "enchant vellum macro", "enchant replace prompt", "how to skip enchant confirm", "macro to spam enchants", "enchanting replace popup macro", "is there a macro to skip the replace enchant popup" }, a = "Forever's retail-style UI asks to confirm replacing an enchant. Macro from wow-professions:\n/run ProfessionsFrame.CraftingPage.CreateButton:Click()\n/run StaticPopup1Button1:Click()\nOpen Enchanting, pick the enchant, put the target item in the slot, then spam the macro.", topic = "prof_alch_ench" }
add{ q = { "enchanting cost to level forever", "is leveling enchanting expensive", "enchanting 1-300 gold cost", "enchanting cost", "is enchanting expensive", "enchanting 1-300 cost", "how much gold for enchanting", "how much g to level enchanting", "enchanting total cost forever", "how much will it cost to level enchanting to 300" }, a = "Timesaver's Nov 16 2026 US Alliance prices put buying reagents for 1-300 Enchanting at about 90g, and a net loss of about 25g if you sell everything you make. Disenchanting your own leveling greens (or pairing with Tailoring) brings that down a lot.", topic = "prof_alch_ench" }
add{ q = { "where is disenchant", "how to disenchant forever", "cant find disenchant spell", "disenchant not in spellbook", "how to disenchant", "cant find disenchant", "disenchant missing", "how do i de in forever", "where did disenchant go", "i cant find disenchant in my spellbook where is it", "disenchant button", "disenchant where is it" }, a = "In Forever, Disenchant isn't in your spellbook. Open the Professions window, find the Enchanting box and drag the Disenchant button onto your action bar. You can disenchant any green or better item at Enchanting skill 1, regardless of item level.", topic = "prof_alch_ench" }
add{ q = { "disenchant table forever", "what do i get from disenchanting", "illusion dust from what level", "what level gear gives dream dust", "disenchant table", "illusion dust level", "dream dust level", "disenchant results by level", "what dust from what level gear", "de table forever", "what level gear do i disenchant for illusion dust" }, a = "Forever disenchant results go by the item's required level:\n1-10 Strange Dust/Lesser Magic; 11-20 Strange Dust, Greater Magic or Lesser Astral, Small Glimmering Shard; 21-25 Soul Dust, Greater Astral, Large Glimmering; 26-30 Soul Dust, Lesser Mystic, Small Glowing; 31-35 Vision Dust, Greater Mystic, Large Glowing; 36-40 Vision Dust, Lesser Nether, Small Radiant; 41-45 Dream Dust, Greater Nether, Large Radiant; 46-50 Dream Dust, Lesser Eternal, Small Brilliant; 51-60 Illusion Dust, Greater Eternal, Large Brilliant (Nexus Crystal rare).", topic = "prof_alch_ench" }
add{ q = { "armor or weapon to disenchant", "disenchant essence vs dust", "how to get more essences", "nexus crystal chance", "essence vs dust", "do weapons give more essence", "disenchant weapons or armor", "best way to get essences", "should i disenchant weapons or armor for essences", "dust or essence", "how to get more nexus crystals", "essence chance de" }, a = "Green armor gives dust about 75% of the time and essence ~20%; green weapons are the reverse (~75% essence). Greens give a shard only 3-5% of the time. Blues always give a shard (Nexus Crystal ~0.5%). Epics at level 50 and below give a shard; high-level epics always give a Nexus Crystal.", topic = "prof_alch_ench" }
add{ q = { "what should i disenchant", "best items to disenchant", "disenchant or vendor", "cheap greens to disenchant", "what to disenchant", "cheap greens to de", "should i disenchant or sell", "what greens should i buy to disenchant", "is it worth disenchanting greens", "should i disenchant greens or sell them to vendor", "what to de", "worth disenchanting" }, a = "Disenchant greens you looted or bought below the value of their mats; check AH prices of the resulting dust/essence first. Tailoring greens are the classic cheap DE source while leveling, and Fishing crates give extra gear to DE. Timesaver shows only small margins on crafted greens right now (e.g. Hillman's Shoulders ~+1s), so DE farming loot is better than crafting to DE.", topic = "prof_alch_ench" }
add{ q = { "enchantresses spire", "faster disenchant staff", "disenchant cast time reduction", "strashaz enchantress staff", "faster disenchant", "disenchant cast time", "strashaz enchantress", "enchantress staff", "how to disenchant faster", "staff that speeds disenchanting", "is there a staff that makes disenchanting faster" }, a = "The Enchantresses' Spire is a rare staff dropped by Strashaz Enchantress in Alcaz Prison; it cuts Disenchant's cast time by 25%, nice for bulk DE sessions.", topic = "prof_alch_ench" }
add{ q = { "bulk disenchant macro", "disenchant macro forever", "fast disenchant", "bulk disenchant", "disenchant macro", "de macro", "mass disenchant", "how to disenchant lots of items fast", "is there a macro to disenchant a lot of items fast", "de macro forever", "disenchant spam macro" }, a = "Bulk-DE macro:\n/cast Disenchant\n/use ItemName\nShift-click the item in your bags to insert its name, press once per item, and turn on Auto Loot to skip the loot window.", topic = "prof_alch_ench" }
add{ q = { "where to get black pearl", "enchanting pearls", "iridescent pearl golden pearl", "black pearl", "iridescent pearl", "golden pearl", "where to get pearls for rods", "where do i get black pearls", "pearls for runed rods", "where do i get black pearls for enchanting rods" }, a = "Pearls for the Runed rods come from clams (Black Pearl from clams via Fishing or mobs), so Fishing pairs well with Enchanting. Golden Pearl (Runed Arcanite Rod) comes from Big-mouth Clams in the 50s; buy on the AH otherwise.", src = "classic", topic = "prof_alch_ench" }
add{ q = { "crusader recipe", "where does crusader drop", "formula enchant weapon crusader", "scarlet spellbinder crusader", "crusader drop", "formula crusader", "scarlet spellbinder", "how to get crusader enchant", "crusader formula forever", "where does the crusader recipe drop in forever", "crusader formula", "crusader enchant recipe" }, a = "Formula: Enchant Weapon - Crusader drops from Scarlet Spellbinders in Western Plaguelands (~0.75%). Enchant: procs +100 Strength for 15s and a small heal. Mats per enchant: 4 Large Brilliant Shard, 2 Righteous Orb. Still the best 1H choice for melee and tanks in Forever.", topic = "prof_alch_ench" }
add{ q = { "lifestealing recipe", "where does lifestealing drop", "fiery weapon recipe", "fiery weapon forever", "lifestealing drop", "fiery weapon", "where does fiery weapon drop", "lifesteal enchant formula", "where does the lifestealing recipe drop", "lifesteal recipe", "fiery recipe", "fiery weapon formula" }, a = "Formula: Lifestealing drops in Scholomance (enchant: 6 Large Brilliant, 6 Essence of Undeath, 6 Living Essence). Formula: Fiery Weapon drops in Blackrock Depths; in Forever it's skill 265 and cheaper (2 Small Radiant Shard, 1 Essence of Fire) for a 40-fire-damage proc.", topic = "prof_alch_ench" }
add{ q = { "agility weapon enchant recipe", "15 agility enchant", "enchant weapon agility where", "meilosh recipe", "2h agility recipe", "agility weapon enchant", "where to get agility weapon enchant", "where is meilosh", "weapon agility formula", "where do i get the agility weapon enchant recipe", "agi weapon enchant", "meilosh timbermaw", "where to get 15 agi weapon" }, a = "Both Agility weapon formulas come from Meilosh, the Timbermaw Hold quartermaster in Felwood: Enchant Weapon - Agility (+15 Agi, 290) needs Honored; Enchant 2H Weapon - Agility (+25 Agi, 290) needs Friendly. 1H mats: 6 Large Brilliant, 6 Greater Eternal, 4 Illusion Dust, 2 Essence of Air. 2H mats: 10 Large Brilliant, 6 Greater Eternal, 14 Illusion Dust, 4 Essence of Air.", topic = "prof_alch_ench" }
add{ q = { "healing power weapon enchant", "spell power weapon enchant recipe", "molten core enchant recipes", "weapon healing forever", "spell power weapon enchant", "molten core enchants", "weapon healing", "where to get spell power weapon recipe", "mc enchant recipes", "healing weapon enchant forever", "where do i get the spell power weapon enchant recipe" }, a = "Enchant Weapon - Healing Power (now +55 healing, +19 spell damage) and Enchant Weapon - Spell Power (now +30 spell power) formulas drop in Molten Core. Both are the best 1H picks for healers and casters respectively.", topic = "prof_alch_ench" }
add{ q = { "mighty intellect recipe", "mighty spirit recipe", "lokhtos darkbargainer", "thorium brotherhood enchants", "lokhtos", "where is lokhtos", "lokhtos darkbargainer recipes", "thorium brotherhood enchanting", "what enchant recipes does lokhtos sell", "lokhtos recipes", "mighty spirit recipe where", "mighty int recipe" }, a = "Lokhtos Darkbargainer in Blackrock Depths (Thorium Brotherhood) sells: Mighty Spirit (+22 Spirit, Honored), Mighty Intellect (+22 Int, Revered) and 1H Strength (+15 Str, Friendly), plus Greater Fire Resistance cloak (Honored). Mighty Intellect mats: 15 Large Brilliant, 12 Greater Eternal, 20 Illusion Dust.", topic = "prof_alch_ench" }
add{ q = { "superior striking recipe", "icy chill recipe", "unholy weapon recipe", "where does superior striking drop", "where does icy chill drop", "unholy weapon formula", "where does superior striking recipe drop", "superior striking", "icy chill", "unholy weapon", "where to get superior striking" }, a = "Superior Striking (+5 weapon damage) drops in Blackrock Spire. Icy Chill drops from Anguished Highborne in Winterspring (~0.9%). Unholy Weapon (295) needs 4 Large Brilliant and 4 Essence of Undeath.", topic = "prof_alch_ench" }
add{ q = { "greater stats recipe", "enchant chest greater stats where", "chest stats enchant", "chest greater stats", "where does greater stats drop", "+4 stats chest", "enchant chest greater stats formula", "where does enchant chest greater stats drop", "greater stats chest", "chest +4 stats recipe", "where do i get greater stats" }, a = "Enchant Chest - Greater Stats (+4 all stats, skill 300) drops from Hive'Regal Hive Lord in Silithus (very rare, ~0.02%); mats 4 Large Brilliant, 15 Illusion Dust, 10 Greater Eternal Essence. Enchant Chest - Stats (+3) is a trainer recipe at 245 from Annora.", topic = "prof_alch_ench" }
add{ q = { "superior stamina bracer recipe", "superior strength bracer recipe", "healing bracer recipe", "bracer healing argent dawn", "superior stamina bracer", "superior strength bracer", "bracer healing", "where to get bracer healing", "superior strength bracer drop", "bracer recipes", "where do i get the bracer healing recipe" }, a = "Bracer formulas: Superior Stamina drops from Nathanos Blightcaller or Demetria in Eastern Plaguelands (~1%), mats 15 Illusion Dust. Superior Strength (+9) drops from Deadwind Warlocks in Blasted Lands (~0.9%). Healing Power (+24 healing) needs Revered with Argent Dawn.", topic = "prof_alch_ench" }
add{ q = { "greater agility gloves recipe", "greater agility boots recipe", "riding skill gloves recipe", "greater stamina boots recipe", "greater agility gloves", "greater agility boots", "riding skill gloves", "greater stamina boots", "where to get greater agility gloves recipe", "boots greater stamina drop", "glove and boot enchant recipes", "where do i get the greater agility gloves recipe" }, a = "Gloves Greater Agility (+10 in Forever): Legashi Rogues, Azshara. Boots Greater Agility (+7): Strashaz Hydras (Dustwallow) or Verdantine Boughguards (Hinterlands). Boots Greater Stamina (+7): Krellack (Silithus) or Stegodons (Un'Goro). Gloves Riding Skill: very rare from Blazing Elementals (Searing Gorge) or Bloodsail Swabbies (STV).", topic = "prof_alch_ench" }
add{ q = { "superior agility gloves", "fire power gloves recipe", "shadow power gloves", "frost power gloves recipe", "aq enchants", "fire power gloves", "frost power gloves", "where do aq glove enchants come from", "15 agi gloves enchant", "where do the superior agility glove enchants come from", "aq glove enchants", "superior agi gloves", "fire power glove enchant" }, a = "Superior Agility gloves (+15 Agi) and Fire, Frost, Shadow and Healing Power gloves drop in Ahn'Qiraj (Ruins and Temple). Arcane Power, Holy Power and Natural Power gloves are new and sold for 240 Merchant's Favor by Alynsia/Beneris at Honored.", topic = "prof_alch_ench" }
add{ q = { "greater resistance cloak recipe", "greater fire resistance cloak", "cloak resistance enchant where", "greater resistance cloak", "cloak resistance enchant", "where does greater resistance drop", "fire resist cloak enchant", "cloak resist recipe", "where does the greater resistance cloak recipe drop", "greater resist cloak", "cloak resistance recipe" }, a = "Cloak Greater Resistance (+5 all resist) drops in Sunken Temple. Greater Fire Resistance (+15) needs Cenarion Circle Friendly or Thorium Brotherhood Honored; Greater Nature Resistance needs Cenarion Circle or Thorium Brotherhood Honored.", topic = "prof_alch_ench" }
add{ q = { "minor speed boots", "speed enchant boots forever", "run speed enchant", "speed enchant boots", "boots minor speed", "where to learn minor speed", "is minor speed a trainer recipe now", "movement speed enchant", "how do i get minor speed boots enchant in forever", "boots speed enchant", "minor speed recipe" }, a = "Boots - Minor Speed is changed to a trainer recipe (yellow at 245) giving 4% run speed. Forever adds Boots - Speed (learn at 280) for 8% movement speed.", topic = "prof_alch_ench" }
add{ q = { "necklace enchants forever", "can you enchant necklace", "neck enchant", "enchant necklace strength agility spell power", "necklace enchants", "enchant necklace", "necklace enchant strength", "can i enchant my necklace", "necklace enchant list", "what neck enchants are there", "can you enchant necklaces in forever" }, a = "Necklaces can be enchanted in Forever (never possible in Classic). All five are skill 210, 120 Merchant's Favor at Friendly from Alynsia/Beneris: Strength (+5), Agility (+5), Spell Power (+6), Healing Power (+11 heal, +4 dmg), Deflection (+5 defense). Mats use Greater Nether Essence, Large Radiant Shards, Dream Dust plus a dye/acid.", topic = "prof_alch_ench" }
add{ q = { "insight enchant", "revelation enchant", "recovery enchant", "new weapon procs forever", "45 merchant's favor enchants", "new weapon procs", "45 merchants favor enchants", "what does insight do", "new low level weapon enchants", "what do the new insight and revelation weapon enchants do", "insight weapon enchant", "revelation weapon enchant", "recovery weapon enchant" }, a = "Three new skill-140 weapon enchants, 45 Merchant's Favor each from Alynsia/Beneris (no rep needed): Insight (proc +100% Spirit for 10s), Revelation (after a non-periodic spell fails to crit, next one gets +100% crit chance) and Recovery (heals 5% max HP when you dodge or parry, 10s cooldown). Cheap and great for leveling alts.", topic = "prof_alch_ench" }
add{ q = { "spellblasting enchant", "mighty spell power", "mighty healing power", "best 2h caster enchant", "staff enchant caster forever", "staff enchant caster", "2h spell power enchant", "best enchant for caster staff", "whats the best 2h enchant for a caster in forever", "spellblasting 2h", "mighty spellpower enchant", "caster 2h enchant", "best staff enchant" }, a = "New 2H caster enchants (skill 300, 240 Merchant's Favor at Honored): Spellblasting +65 spell power (best for casters), Mighty Spell Power +55, Mighty Healing Power +100 healing/+34 damage (best healer staff enchant). Mighty versions need Fel Crystals, Greater Eternal Essence, Nexus Crystals and Torbernite.", topic = "prof_alch_ench" }
add{ q = { "2h strength enchant", "enchant 2h weapon strength", "lesser strength 2h", "best 2h enchant warrior forever", "enchant 2h strength", "best 2h enchant warrior", "2h weapon strength enchant", "strength enchant for 2h", "whats the best 2h strength enchant in forever", "2h str enchant", "strength 2h enchant", "warrior 2h enchant" }, a = "New 2H Strength enchants: Strength +25 (290, 8 Large Brilliant, 10 Greater Eternal, 8 Illusion Dust, 4 Arcane Crystal) and Lesser Strength +15 (220). RankedBoost rates +25 Strength over Crusader on a 2H unless Crusader procs above ~1.15/min. Lesser Agility 2H (210) is also new.", topic = "prof_alch_ench" }
add{ q = { "greater spellpower bracer", "superior intellect bracer", "superior deflection", "superior agility bracer", "new bracer enchants", "best bracer enchant forever", "what are the new bracer enchants in forever", "bracer enchants forever", "spellpower bracer", "int bracer enchant", "deflection bracer" }, a = "New bracer enchants: Greater Spellpower (+16 SP, 300) and Superior Intellect (+9, 300) for 240 Merchant's Favor at Honored; Superior Deflection (+9 defense) for tanks; Superior Agility (+9 Agi, 295) for hunters/rogues; plus lower ones like Agility (+5), Greater Agility (+7) and Lesser Healing Power (+16 heal, Gorhak in Desolace).", topic = "prof_alch_ench" }
add{ q = { "cloak agility enchant", "enchant cloak agility forever", "cloak dodge enchant", "enchant cloak agility", "best cloak enchant", "cloak agi enchant", "agility cloak recipe", "whats the best cloak enchant in forever", "cloak agi", "agility cloak enchant", "best cloak enchant forever" }, a = "Enchant Cloak - Agility (+5 Agi, skill 300) is new in Forever and the best cloak for physical DPS; tanks use Cloak - Dodge (+1%), and Feral bears use Superior Defense (+70 armor). It's a Merchant's Favor formula.", topic = "prof_alch_ench" }
add{ q = { "absorption chest enchant", "enchant chest absorption", "what does absorption enchant do", "what does absorption do", "absorption enchant", "chest absorb enchant", "is absorption enchant good", "what does enchant chest absorption do", "absorption enchant chest", "absorb chest enchant", "chest absorption what does it do" }, a = "Enchant Chest - Absorption is a new Forever formula: 25% chance to absorb 50 damage per hit. 120 Merchant's Favor at Friendly from Alynsia/Beneris. Not a top pick for any role, more a leveling tank option.", topic = "prof_alch_ench" }
add{ q = { "superior strength gloves", "15 strength gloves enchant", "natural power gloves", "advanced skinning gloves", "15 strength gloves", "new glove enchants", "best glove enchant melee", "what are the new glove enchants in forever", "str gloves enchant", "superior str gloves", "glove enchants forever", "natural power glove enchant" }, a = "New glove enchants: Superior Strength (+15 Str, best for melee and tanks; 4 Nexus Crystal, 8 Greater Eternal, 4 Essence of Earth), Natural Power (+20 Nature damage; 4 Death Lotus), Arcane Power, Holy Power, Lotus Claw (chance for Death Lotus in Hyjal) and Advanced Skinning (+10 Skinning).", topic = "prof_alch_ench" }
add{ q = { "changed enchants forever", "buffed enchants forever", "major intellect chest change", "winter's might forever", "changed enchants", "buffed enchants", "major intellect chest", "winters might", "which enchants were changed", "what enchants got buffed in forever", "which classic enchants did forever change" }, a = "Some Classic enchants were changed: Chest Major Intellect is now +10 Int (was +100 mana), Major Stamina +10 Sta (was +100 HP); Weapon Healing Power +55 heal, Spell Power +30, Mighty Spirit +22, Winter's Might +15 frost; Minor/Lesser/regular Impact and Lesser Intellect/Spirit 2H all gained stats; many boots/bracer enchants got +1-2 stats or cheaper mats.", topic = "prof_alch_ench" }
add{ q = { "best enchants for warrior forever", "best enchants melee", "what enchants should i get as warrior", "fury warrior enchants forever", "best warrior enchants", "best melee enchants", "warrior enchants forever", "fury warrior enchants", "enchants for warrior", "what to enchant on my warrior", "melee enchant list", "what enchants should i get on my warrior in forever" }, a = "Melee (Warrior/Ret/Enh) best enchants per RankedBoost/Method: Weapon Crusader (1H) or +25 Strength (2H); Gloves Superior Strength +15; Bracer Superior Strength +9; Chest Greater Stats; Cloak Agility +5; Boots Greater Agility +7; Necklace Strength +5.", class = "WARRIOR", topic = "prof_alch_ench" }
