add{ q = { "best enchants rogue forever", "rogue enchants crusader or agility", "what enchants should my rogue get", "best rogue enchants", "rogue enchants forever", "crusader or agility rogue", "enchants for rogue", "what to enchant on my rogue", "rogue weapon enchant", "should my rogue use crusader or agility" }, a = "Rogue: Combat uses +15 Agility on weapons unless Crusader procs above ~1.07/min; Assassination/Subtlety use Superior Striking unless Crusader procs above ~1.2/min. Rest: Gloves Superior Agility, Bracer Superior Agility, Cloak Agility, Boots Greater Agility, Chest Greater Stats, Necklace Agility.", class = "ROGUE", topic = "prof_alch_ench" }
add{ q = { "best enchants caster forever", "mage enchants forever", "warlock enchants", "caster enchants list", "best caster enchants", "mage enchants", "caster enchant list", "enchants for mage", "what to enchant on my mage", "spell power enchants list", "what enchants should i get on my mage or lock" }, a = "Casters: Weapon Spell Power (+30) or 2H Spellblasting (+65); Bracer Greater Spellpower (+16); Gloves school power (Fire/Frost/Shadow/Arcane/Natural +20); Chest Major Intellect or Greater Stats; Necklace Spell Power (+6); Off-hand Wisdom; Boots Greater Stamina.", topic = "prof_alch_ench" }
