add{ q = { "best tank enchants forever", "prot warrior enchants", "tank enchants list", "bear enchants", "best tank enchants", "tank enchant list", "enchants for tank", "what to enchant on my tank", "defense enchants", "what enchants should i get as a tank", "tank weapon enchant", "warrior tank enchants" }, a = "Tanks: Weapon Crusader; Necklace Deflection (+5 defense); Bracer Superior Deflection (+9 defense) or Superior Stamina; Gloves Superior Strength; Chest Major Stamina or Greater Stats; Cloak Dodge (bears: Superior Defense); Boots Greater Stamina; Shield Excellent Stamina or Greater Stamina.", topic = "prof_alch_ench" }
add{ q = { "cheap enchants under 250", "best enchants low level", "budget enchants leveling forever", "cheap enchants", "budget enchants", "low level enchants", "enchants under 250", "leveling enchants", "cheap enchants for alts", "what are some cheap enchants for leveling" }, a = "Budget (skill 250 or less): Weapon Striking (+3 dmg) or Revelation/Insight for casters; 2H Lesser Strength (+15) or Impact (+6); Bracer Strength/Agility/Intellect (+5) or Lesser Healing Power; Gloves Strength or Agility (+7); Chest Lesser Stats or Superior Intellect/Stamina (+8); Boots Lesser Agility (+4) or Stamina (+5); Cloak Minor Agility or Greater Defense.", topic = "prof_alch_ench" }
add{ q = { "how do i get enchants from enchanter", "enchant through trade window", "how to apply enchant to someone", "how to get enchanted", "enchant through trade", "apply enchant to someone", "how to enchant someone elses gear", "trade window enchant", "how does enchanting someone work", "how do i get an enchanter to enchant my gear" }, a = "Enchants are applied by an Enchanter through the trade window: put your item in the 'will not be traded' slot, the enchanter casts the enchant on it, then you both accept. Bring the mats yourself to save money.", topic = "prof_alch_ench" }
add{ q = { "how much to tip enchanter", "enchant prices forever", "how much does crusader cost", "what do enchanters charge", "enchant prices", "crusader price", "enchant cost", "tip for enchants", "how much should i pay for crusader", "how much should i tip an enchanter", "enchanting prices", "crusader cost" }, a = "No reliable Forever-wide price list exists yet; prices depend on your server's AH. Normal practice (Classic baseline): bring the mats and tip for the formula, more for rare ones like Crusader, Agility or Healing Power. Early market snapshot (US Alliance, Nov 16 2026): Illusion Dust ~45s, Vision Dust ~10s, Soul Dust ~4s.", src = "classic", topic = "prof_alch_ench" }
add{ q = { "raid consumables forever", "what consumables for raid", "best pots for raid forever", "what do i need for mc", "raid consumables", "best pots for raid", "raid consumes forever", "consumes list for raid", "what to bring to raid", "what consumables do i need for raid in forever", "raid consumes", "consumes for mc", "what pots for raid" }, a = "Typical Forever raid kit:\n1. Flask: Titans (tank), Supreme Power (caster), Distilled Wisdom (healer); Natural flasks in Hyjal content.\n2. Elixirs: Mongoose/Grizzly/Ferocity (melee), Greater Arcane/Sages/Owl (caster), Greater Cleric's (healer), Greater Fortitude/Phalanx (tank). Method's beta guide says flasks now stack with elixirs.\n3. Potions: Major Frenzy (+80 AP), Major Spellblasting (+47 SP), Major Mender's (+88 heal), Major Mana, Greater Stoneshield, Greater Fire Protection for MC/BWL, Free Action.\n4. Oils/stones: Brilliant Wizard/Mana Oil, Elemental or Consecrated Sharpening Stone.\n5. Buff food.", topic = "prof_alch_ench" }
add{ q = { "warrior consumables forever", "melee raid consumables", "what elixir for warrior", "warrior consumables", "warrior consumes", "melee consumes list", "what pots for warrior", "what consumables should a warrior bring to raid", "what elixir for melee", "fury consumables" }, a = "Melee consumables: Flask of the Titans or a Natural flask in Hyjal, Elixir of the Mongoose (Agi+crit), Elixir of the Grizzly (new, Str+crit) or Ferocity, Major Frenzy Potion (+80 AP, 30s) on burst, Elemental Sharpening Stone (+2% crit), Mightfish Steak (+40 AP food).", class = "WARRIOR", topic = "prof_alch_ench" }
add{ q = { "caster consumables forever", "mage raid consumables", "warlock consumables", "caster consumables", "caster consumes", "mage consumes list", "what pots for mage", "what consumables should a caster bring to raid", "mage consumes", "lock consumes" }, a = "Casters: Flask of Supreme Power (+150 spell damage), Greater Arcane Elixir plus a school elixir (Shadow/Fire Power), Elixir of Sages or Owl (new), Major Spellblasting Potion (+47 SP for 30s), Brilliant Wizard Oil, Nightfin Soup or similar spell food.", topic = "prof_alch_ench" }
add{ q = { "healer consumables forever", "priest raid consumables", "healer flask", "healer consumables", "healer consumes", "priest consumes list", "what pots for healer", "what consumables should a healer bring to raid", "priest consumes", "healing consumables" }, a = "Healers: Flask of Distilled Wisdom (+2000 mana), Greater Cleric's Elixir (new, healing) and Mageblood/Greater Mageblood for regen, Major Mender's Potion (+88 healing, 30s), Major Mana Potion, Brilliant Mana Oil, Sage's Tea (+44 healing) food.", topic = "prof_alch_ench" }
add{ q = { "tank consumables forever", "tank flask forever", "what pots does a tank need", "tank consumables", "tank flask", "tank consumes", "tank consumes list", "warrior tank consumables", "what consumables should a tank bring to raid", "tank pots" }, a = "Tanks: Flask of the Titans (+1200 HP), Elixir of Greater Fortitude and the new Elixir of the Phalanx (armor), Greater Stoneshield Potion (+2000 armor, 2 min), Free Action Potion, Savory Turtle Stew (+20 Sta), plus Greater Fire Protection for fire bosses.", topic = "prof_alch_ench" }
add{ q = { "how to make gold with alchemy forever", "alchemy gold farm", "is alchemy good for gold", "alchemy money forever", "alchemy gold", "make gold with alchemy", "is alchemy good money", "alchemy money", "alch gold making forever", "best way to make gold with alch", "how do i make gold with alchemy in forever" }, a = "Alchemy gold in Forever:\n1. Cast Transmute: Arcanite every 47h (~+36g each at Nov 2026 prices) and Legionite (~+31g).\n2. Sell raid consumables: flasks, Mongoose, Greater Fire Protection, Major Mana and the new Major Frenzy/Spellblasting/Mender's potions; potions and flasks are used up, so demand repeats every raid night.\n3. Skip money-losing transmutes (several essence ones) and Mithril to Truesilver.\n4. Pair with Herbalism so your herbs are free.", topic = "prof_alch_ench" }
add{ q = { "how to make gold with enchanting forever", "enchanting gold", "is enchanting good money", "make gold with enchanting", "enchanting money", "ench gold making", "best way to make gold with enchanting", "how do i make gold with enchanting in forever", "ench gold", "enchanting money making", "enchanting gold making forever" }, a = "Enchanting gold: sell enchants for tips (bring in the rare formulas like Crusader, Agility, Spellblasting, necklaces), disenchant leveling greens and sell dust/essence/shards, and craft the new wands/staves/relics for levelers. Crafting cheap enchants purely to vendor currently loses money, so sell mats instead.", topic = "prof_alch_ench" }
add{ q = { "recipe is bop", "can i buy recipe on alt", "bind on pickup recipe enchanting alchemy", "bind on pickup recipe", "bop recipes", "can i trade recipes", "is this recipe bop", "this recipe is bind on pickup can i still get it for my alt", "bop recipe", "recipe bind on pickup", "can i send recipe to alt" }, a = "Watch out for bind-on-pickup recipes: Formula Enchant Shield - Greater Stamina (Daniel Bartlett/Mythrin'dir) and Recipe Nature Protection Potion are BoP, so buy them on the character with the profession, not an alt.", topic = "prof_alch_ench" }
add{ q = { "limited supply recipe", "free action recipe sold out", "recipe out of stock", "recipe vendor sold out", "when does recipe restock", "limited recipe restock time", "the recipe vendor is sold out when does it restock", "limited supply", "recipe restock", "vendor recipe sold out", "free action recipe restock" }, a = "Some vendor recipes are limited-supply and restock over time, e.g. Free Action Potion (Ulthir/Kor'geld) and Fire Protection Potion (Nandar Branson). If sold out, wait for the restock or buy the recipe from another player.", topic = "prof_alch_ench" }
add{ q = { "cant learn artisan enchanting", "annora not there", "annora missing uldaman", "annora missing", "where is annora uldaman not spawning", "annora wont show up", "cant find annora", "annora isnt in uldaman where is she", "annora wont spawn", "annora not spawning", "annora uldaman missing" }, a = "If Annora isn't showing in Uldaman, clear every mob in her area; she only appears afterward. You also need level 35 and Enchanting 200. She's the only Artisan Enchanting trainer, so learn every recipe while there.", topic = "prof_alch_ench" }
add{ q = { "cant learn journeyman", "why cant i train alchemy 75", "skill stuck at 75", "stuck at 150 enchanting", "cant train alchemy 75", "profession stuck at 225", "why is my skill not going up", "skill capped cant level", "my skill is stuck at 75 why cant i go higher", "stuck at 75 alchemy", "why cant i level past 150", "skill capped at 225" }, a = "Profession skill caps at 75/150/225 until you buy the next rank: Journeyman needs skill 50 and level 10, Expert needs skill 125 and level 20 (50s), Artisan needs skill 200 and level 35. If the trainer won't teach it, check your character level and current skill.", topic = "prof_alch_ench" }
add{ q = { "cant use flask natural", "natural flask not working", "flask bonus not showing", "natural flask outside hyjal", "why does my natural flask do nothing", "natural flask only in hyjal", "my natural flask isnt giving the bonus why", "natural flask doesnt work", "natural flask buff missing", "flask natural not working outside hyjal" }, a = "Natural flasks only give their bonus (hit/crit/haste/expertise-style) inside Mount Hyjal, Hyjal Summit and the Barrow Deeps; elsewhere you just get the +60 Stamina. They also need level 55.", topic = "prof_alch_ench" }
add{ q = { "cant buy alchemy recipe merchant favor", "recipe vendor greyed out", "need honored commerce authority", "cant buy alchemy recipe", "merchants favor recipe red", "cant buy merchants favor recipe", "commerce authority rep needed", "why cant i buy the merchants favor recipe its greyed out", "merchant favor recipe greyed out", "cant buy recipe rep", "alch recipe greyed out", "need honored for recipe" }, a = "Merchant's Favor recipes are rep-gated: some need Friendly and most of the good ones (Grizzly, Cunning, Owl, Major potions, 2H enchants, Greater Spellpower bracer) need Honored with Azeroth Commerce Authority (Alliance) or Durotar Supply and Logistics (Horde). Earn rep with daily Craftsman's Writs and crate turn-ins.", topic = "prof_alch_ench" }
add{ q = { "imbued vial new", "why do new potions need imbued vial", "where to buy imbued vial", "imbued vial", "why do potions need imbued vial", "imbued vial vendor", "how to get imbued vials", "new potions imbued vial", "why do the new potions need imbued vials", "imbued vials", "imbued vial where" }, a = "Many new 275+ Forever potions and the Natural flasks need Imbued Vials, which only Alchemy/Herbalism supply vendors sell (not general trade vendors). Stock up near a trainer before crafting.", topic = "prof_alch_ench" }
add{ q = { "elixir of giants recipe", "giants elixir where", "elixir of giants forever", "giants elixir", "elixir of giants", "where to get elixir of giants", "giants recipe forever", "+25 strength elixir", "where do i get the elixir of giants recipe", "giants elixir recipe", "elixir giants" }, a = "Elixir of Giants (+25 Strength) is still in Forever at skill 245 (Sungrass, Gromsblood, Crystal Vial). Its Forever recipe source isn't documented yet; in Classic it was a world drop.", src = "classic", topic = "prof_alch_ench" }
add{ q = { "superior mana potion recipe", "ulthir algernon recipe", "where to buy superior mana pot recipe", "ulthir recipe", "algernon recipe", "superior mana pot recipe", "where to buy superior mana potion", "superior mana recipe vendor", "where do i buy the superior mana potion recipe", "superior mana recipe", "sup mana pot recipe" }, a = "Recipe: Superior Mana Potion is sold by Ulthir in Darnassus (Alliance) and Algernon in Undercity (Horde). Each potion: 2 Sungrass, 2 Blindweed, Crystal Vial. It's used at 260-270 (or 265-300 in the no-eel route).", topic = "prof_alch_ench" }
add{ q = { "elixir of superior defense recipe", "kor'geld soolie berryfizz", "superior defense elixir where", "korgeld", "soolie berryfizz", "superior defense elixir", "where to buy superior defense recipe", "superior defense recipe vendor", "where do i buy the elixir of superior defense recipe", "superior defense recipe", "sup defense elixir recipe" }, a = "Recipe: Elixir of Superior Defense is sold by Kor'geld in Orgrimmar and Soolie Berryfizz in Ironforge.", topic = "prof_alch_ench" }
add{ q = { "blacksmithing changes in forever", "whats new with bs in wow forever", "is blacksmithing different in forever", "forever blacksmith changes vs classic", "bs worth it forever", "what did they change about blacksmithing in forever", "bs changes", "is bs reworked in forever", "how different is blacksmithing from vanilla", "are there new bs recipes in forever", "thinking about leveling bs on my warrior is it good in forever", "blacksmithing overhaul forever", "new blacksmith plans forever", "is blacksmithing actualy worth leveling in forever or is it the same as classic", "bs diffrent in forever?" }, a = "Big overhaul. Forever has about 431 plans: roughly 197 new, 183 changed and only 51 untouched from Classic. Leveling greens are buffed so crafted mail/plate is useful while leveling, many mail/plate pieces got proper hybrid stats, hundreds of new plans come from Merchant's Favor vendors and dungeon/raid drops, and Sharpening/Weightstones now stack with poisons and Windfury. Endgame mail like Invulnerable Mail and Storm Gauntlets moved to Leatherworking.", topic = "prof_bs_eng" }
add{ q = { "what is the max blacksmithing skill forever", "bs skill cap forever", "can blacksmithing go past 300", "blacksmithing ranks forever", "max bs skill", "how high does blacksmithing go", "whats the blacksmithing cap", "bs max lvl forever", "what level do i need for each bs rank", "can i get bs to 375 in forever or is it 300", "blacksmithing journeyman expert artisan requirements", "bs rank level requirements", "wats the max lvl for blacksmithing", "how far can bs go in forever is 300 max" }, a = "Cap is 300, in four ranks: Apprentice 1-75 (no level req), Journeyman 75-150 (skill 50, level 10), Expert 150-225 (skill 125, level 20), Artisan 225-300 (skill 200, level 35). Some datamined plans show 310-320 requirements but those are leftover Season of Discovery data, not reachable ranks.", topic = "prof_bs_eng" }
add{ q = { "is the 225 cap still a thing", "professions stuck at 225 beta", "why can't i go above 225 profession", "exploit 300 professions forever", "is profession cap 225 or 300", "why is my profession capped at 225", "was there a 225 cap in beta", "dedicated study exploit", "cant train past 225 bs", "people had 300 profs in beta how", "profession cap beta forever", "225 cap removed?", "my friend has 300 profs from beta how is that possible", "why cant i go past 225 in my proffesion" }, a = "During the beta the profession cap was 225. Some players abused the Legacy talent Dedicated Study (reset Legacy points to clear its 23-hour cooldown) to push past 225; the Forever Open organizers called anything above 225 an exploit. The full 300 cap with Artisan ranks is in the live game.", topic = "prof_bs_eng" }
add{ q = { "what do i need for blacksmithing", "bs tools", "do i need a blacksmith hammer", "where do i buy blacksmith hammer", "what tools blacksmithing forever", "where do i get a blacksmith hammer", "bs hammer vendor", "what do i need to start bs", "need hammer for blacksmithing?", "cant craft says requires blacksmith hammer", "blacksmithing tools needed", "just learned bs what tools do i buy", "who sells blacksmith hammer", "wher do i buy the hammer for bs", "trying to craft but it says i need a hammer" }, a = "You need a Blacksmith Hammer in your bags (sold by Trade/General Goods and Blacksmithing Supply vendors, e.g. Walter Mason in Deathknell or Abigail Shiel in Brill for Horde) and an Anvil for most items. Stones, weapon stones, most reagents and camp features can be made anywhere. Coal, Weak Flux and Strong Flux come from the Blacksmithing Supply vendor beside every capital trainer. Pair it with Mining - you'll burn 1000+ Thorium Bars.", topic = "prof_bs_eng" }
add{ q = { "best profession to pair with blacksmithing", "bs and mining", "blacksmithing second profession", "should i take mining with bs", "what should i pair with bs", "bs + mining good?", "best second prof for blacksmith", "bs mining or bs herb", "should i go mining or skinning with blacksmithing", "is mining required for blacksmithing", "making a warrior with bs what other profession", "bs and what", "im leveling bs what should my other prof be", "is it dumb to do bs without mining" }, a = "Mining. Blacksmithing to 300 eats roughly 1,000-1,900 Thorium Bars depending on route, plus hundreds of Mithril, Bronze and Iron Bars, so buying everything is very expensive. Mining also lets you smelt Steel (Mining 165) and the new Azerothium Bar.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing trainers forever", "where is the bs trainer", "journeyman blacksmith trainer location", "expert blacksmith trainer", "where do i learn blacksmithing", "where can i learn blacksmithing", "bs trainer location", "where is the blacksmith trainer in org", "where is the blacksmith trainer in stormwind", "who trains blacksmithing", "expert bs trainer where", "need to train journeyman bs where do i go", "bs trainer ironforge", "wher is the bs trainer", "just picked up blacksmithing who do i talk to to rank up" }, a = "Apprentice: every capital and starting town (Ug'thok Org, Basil Frye UC, Thrag Stonehoof TB, Dane Lindgren SW, Groum Stonebeard IF, Smith Argus Goldshire, Tognus Flintfire Kharanos, Dwukk Razor Hill, Delfrum Flintbeard Auberdine). Journeyman (skill 50, lvl 10): Snarl Org, James Van Brunt UC, Karn Stonehoof TB, Therum Deepforge SW, Rotgath Stonebeard IF. Expert (125, lvl 20, 50s): Saru Steelfury Org or Bengus Deepforge IF. Artisan (200, lvl 35): Brikk Keencraft in Booty Bay (both factions).", topic = "prof_bs_eng" }
add{ q = { "artisan blacksmith trainer", "where to train bs 225", "who teaches artisan blacksmithing", "brikk keencraft location", "where do i train artisan bs", "artisan bs trainer", "who trains bs past 225", "brikk booty bay", "wher is the artisan blacksmith", "need artisan blacksmithing trainer location", "hit 225 bs where do i train", "booty bay blacksmith trainer", "wheres the 225 bs trainer at", "i capped expert bs who trains me next" }, a = "Brikk Keencraft in Booty Bay, Stranglethorn Vale (about 29.0, 75.4) trains Artisan for both factions; you need skill 200 and level 35. Some guides also list Bengus Deepforge (Ironforge 51.4, 42.2) and Saru Steelfury (Orgrimmar 82.2, 23.0) for the higher ranks - if your capital trainer won't offer Artisan, go to Brikk.", topic = "prof_bs_eng" }
add{ q = { "blacksmith trainer zephras isle", "skyborne blacksmithing trainer", "valanaar blacksmith", "shen'dar village blacksmith", "bs trainer on zephras", "blacksmith trainer for skyborne", "where is the blacksmith on zephras isle", "daeann steelwind", "aedi thriceforged", "zephras isle bs trainer location", "im skyborne where do i learn blacksmithing", "shen'dar bs trainer", "skyborne bs trainer wher", "im on zephras and want to train blacksmithing who do i go to" }, a = "Zephras Isle has two: Daeann Steelwind (Valanaar, around 65.4, 80.2), who trains up to Journeyman, and Aedi Thriceforged (Shen'dar Village, around 44.8, 44.4) for Apprentice. Darnassus and Teldrassil have no Blacksmithing trainer - night elves train in Auberdine, Darkshore.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing camp features", "sharpening wheel forever", "anvil camp blueprint", "bs camping", "what camp stuff does bs get", "blacksmith camp", "bs camp buff", "sharpening wheel buff", "camp anvil blacksmith", "what can blacksmiths place at camp", "does bs give a camp buff in forever", "blacksmith camp blueprints", "what does the sharpening wheel do at camp", "can i put an anvil at my camp as bs" }, a = "Blacksmiths get three camp features: Sharpening Wheel (skill 20, gives Strength/Agility like Strength of Earth Totem to people at camp), Anvil (skill 140, acts as an anvil plus the Wheel buff) and Master Forge (skill 300, acts as a forge/anvil plus Wheel buff). They need a Campfire nearby and share a 1-hour cooldown with other camp features.", topic = "prof_bs_eng" }
add{ q = { "master forge forever", "how to get master forge", "blueprint master forge", "master forge materials", "how do i make a master forge", "master forge mats", "master forge blueprint where", "what does master forge do", "master forge bs 300", "golem heart master forge", "where do i get the master forge blueprint", "master forge requirements", "just hit 300 bs how do i get the master forge", "masterforge what do i need" }, a = "Master Forge is a new Forever blueprint at Blacksmithing 300. It costs 1 Golem Heart, 5 Thorium Bars and 2 Rugged Leather to place, must be next to a Campfire, works as a forge for recipes that need one and gives the Sharpening Wheel buff. Shares the 1-hour camp cooldown. The blueprint's drop source isn't documented yet.", topic = "prof_bs_eng" }
add{ q = { "legacy talents professions", "working overtime talent", "dedicated study legacy", "faster profession leveling forever", "legacy talents for professions", "working overtime", "dedicated study talent", "how to level professions faster", "legacy tree professions", "what does working overtime do", "best legacy talents for crafting", "dedicated study cooldown", "is there a talent to level profs faster", "worth putting legacy points into working overtime for profs" }, a = "The Legacy professions tree has two helpers: Working Overtime (about +10% chance for an extra skill point on qualifying crafts/gathers) and Dedicated Study (25-sec cast, once every ~23 hours, +1 point to your lowest profession, or 3 random Elemental Essences if all are maxed). Blacksmithing and Engineering both award Legacy points at 150, 225 and 300.", topic = "prof_bs_eng" }
add{ q = { "bs crafting ui", "create all button", "what do the arrows mean crafting forever", "orange yellow green recipe arrow", "crafting window forever", "what does create all do", "recipe colors meaning", "what do the skill up colors mean", "orange vs yellow recipe", "crafting arrows", "how does the crafting ui work in forever", "what do the arrows next to recipes mean", "what do the green yellow orange colors mean on recipes", "how does create all work in crafting window" }, a = "Forever's crafting window lists recipes on the left, materials on the right, with Create (pick an amount) and Create All. Skill-up arrows: orange = guaranteed point, yellow = good chance, green = low chance, no arrow = no point.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing certification title", "profession title forever", "engineering certification cost", "how do i get the profession title", "bs title", "how to get blacksmith title", "certification title", "what is profession certification", "blacksmithing certification cost", "how do i get a title for my profession", "profession certification forever", "can i get a title for 300 bs", "maxed bs how do i get a title", "is there a blacksmith title for hitting 300" }, a = "Each profession has a Certification item that unlocks a title once you're at 300 skill. The Engineering Certification costs 1000 Merchant's Favor from the Merchant's Favor vendor; Blacksmithing works the same way through its Merchant's Favor vendor.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing 1-75", "bs 1 75 forever", "apprentice blacksmithing guide", "what to make 1-75 bs", "bs 1-75", "blacksmithing 1 to 75", "what do i make first in blacksmithing", "starting blacksmithing guide", "just started bs what do i craft", "bs leveling 1-75", "rough sharpening stone leveling", "apprentice bs route", "new to bs what do i make 1 to 75", "bs 1-75 fastest way" }, a = "1-75 (Apprentice):\n1. 1-25: 30x Rough Sharpening Stone (30 Rough Stone).\n2. 25-50: 30x Rough Grinding Stone (60 Rough Stone). Keep 10.\n3. Train Journeyman at 50 (level 10).\n4. 50-75: 36x Coarse Grinding Stone (72 Coarse Stone); save extras for Patterned Bronze Bracers later.\nTotal: ~90 Rough Stone, 72 Coarse Stone. Buy a Blacksmith Hammer first.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing 75-150", "bs 75 150", "journeyman bs leveling forever", "what to craft 100 blacksmithing", "bs 75-150", "blacksmithing 75 to 150", "journeyman bs route", "what to make at 75 bs", "runed copper belt leveling", "im 100 bs what should i craft", "bs 100-150", "what do i craft after 75 blacksmithing", "im 75 bs now what", "what to craft from 75 to 150 blacksmithing" }, a = "75-150 (Journeyman):\n1. 75-80: 5x Silver Rod (Silver Bar + 2 Rough Grinding Stone), or 5 Runed Copper Belts.\n2. 80-95: 18x Runed Copper Belt (180 Copper Bar).\n3. 95-100: 5x Patterned Bronze Bracers (25 Bronze, 10 Coarse Grinding Stone).\n4. 100-112: 20x Heavy Grinding Stone (60 Heavy Stone).\n5. 112-125: 13x Patterned Bronze Bracers. Train Expert at 125 (lvl 20).\n6. 125-140: 24x Bronze Shortsword (120 Bronze, 96 Weak Flux, 48 Medium Leather).\n7. 140-150: 10x Bronze Warhammer (80 Bronze, 10 Strong Flux, 10 Medium Leather).", topic = "prof_bs_eng" }
add{ q = { "blacksmithing 150-225", "bs 150 225", "expert blacksmithing leveling", "bs 200 what to make", "bs 150-225", "blacksmithing 150 to 225", "expert bs route", "what to craft 150 bs", "green iron bracers leveling", "im at 175 bs what now", "bs leveling 150 225 forever", "what do i make at 200 blacksmithing", "im 150 bs whats next", "bs 150-225 cheapest route" }, a = "150-225 (Expert):\n1. 150-175: 30x Green Iron Bracers (180 Iron Bar, 30 Green Dye from a trade vendor).\n2. 175-180: 8x Solid Grinding Stone (32 Solid Stone).\n3. 180-195: 20x Golden Scale Bracers (100 Steel Bar, 40 Heavy Grinding Stone).\n4. 195-210: 17x Mithril Plate Pants (204 Mithril Bar) - renamed from Mithril Scale Pants.\n5. 210-215: 6x Heavy Mithril Axe (72 Mithril, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather).\n6. Train Artisan at 200+ (lvl 35) with Brikk in Booty Bay.\n7. 215-225: 10x Heavy Mithril Breastplate (160 Mithril).", topic = "prof_bs_eng" }
add{ q = { "blacksmithing 225-300", "bs 225 300", "artisan blacksmithing route", "how to get bs to 300 forever", "bs 225-300", "blacksmithing 225 to 300", "artisan bs leveling", "how to finish blacksmithing", "bs 250 what to make", "im 260 bs what do i craft", "blacksmithing 300 route forever", "fastest way to 300 bs", "just hit 225 bs whats the fastest route to 300", "artisan bs what do i make" }, a = "225-300 (Artisan):\n1. 225-230: 5x Dense Sharpening Stone (5 Dense Stone) - lowered from Classic.\n2. 230-240: 16x Heavy Mithril Boots (224 Mithril, 64 Thick Leather).\n3. Go to Gadgetzan with ~250 Thorium Bars and do Derotain Mudsipper's Imperial Plate quests for the plans.\n4. 240-245: 5x Imperial Plate Belt (110 Thorium, 30 Rugged Leather, 5 Aquamarine).\n5. 245-270: 27x Imperial Plate Bracers (540 Thorium, 27 Star Ruby).\n6. 270-290: 20x Imperial Plate Boots (680 Thorium, 20 Star Ruby, 20 Aquamarine).\n7. 290-300: 10x Imperial Plate Leggings (440 Thorium, 20 Star Ruby).\nRoughly 1,900 Thorium total on this path.", topic = "prof_bs_eng" }
add{ q = { "cheapest blacksmithing route forever", "alternative bs leveling kami", "bs leveling silver skeleton key", "mithril plate bracers leveling", "cheapest way to level bs", "cheap blacksmithing route", "other bs leveling route", "alternate blacksmithing guide", "bs leveling cheap forever", "is there a cheaper bs route than imperial plate", "silver skeleton key leveling", "budget blacksmithing leveling", "imperial plate is too expensive any other way to level bs", "cheapest bs lvling guide pls" }, a = "An alternative verified route (Nov 2026): Rough Sharpening Stone 1-35, Rough Grinding Stone 35-75, Silver Skeleton Key 75-90, Rough Bronze Leggings 90-125 (with Heavy Sharpening Stone 100-113), Iron Buckle/Golden Rod/Silvered Bronze Boots 125-140, Green Iron Bracers 140-175, Solid Sharpening Stone 175-184, Golden Scale Bracers 184-190, Mithril Plate Bracers 190-221 (plans from Harggan, Hinterlands, ~53s; 8 Mithril + 2 Citrine each), Heavy Mithril Breastplate 221-225, then Dense Weightstone, Ebon Shiv, Arcanite Skeleton Key and Imperial Plate pieces to 300.", topic = "prof_bs_eng" }
add{ q = { "blacksmithing shopping list", "what do i buy on ah for blacksmithing", "bs mats 1-300", "how many thorium bars for 300 blacksmithing", "bs materials list", "bs mats", "what mats do i need for blacksmithing", "how much does bs cost to level", "bs 1-300 mats list", "how many mithril bars for blacksmithing", "what to buy on ah to level bs", "total mats blacksmithing 300", "blacksmithing cost to max", "how much gold to get bs to 300", "how many thorium do i need for bs 300" }, a = "Rough 1-300 shopping list: Thorium Bar ~1,000-1,900 (biggest cost by far), Mithril Bar ~450-660, Bronze Bar ~170-290, Iron Bar ~180-230, Steel Bar ~30-100, Copper Bar ~180, Star Ruby ~55-67, Citrine ~12-64, Aquamarine ~20-25, Thick Leather ~30-64, Rugged Leather ~30, Rough/Coarse/Heavy/Solid/Dense Stone, Green Dye ~30 and Weak/Strong Flux from vendors. Exact numbers depend on route; buy 10% extra because yellow recipes miss.", topic = "prof_bs_eng" }
add{ q = { "imperial plate quests", "derotain mudsipper", "where do i get imperial plate plans", "imperial plate bracers plans forever", "imperial plate plans", "where do imperial plate recipes come from", "derotain gadgetzan", "imperial plate belt quest", "imperial plate leggings plans", "how do i get imperial plate boots plans", "imperial plate quest requirements", "imperial plate for leveling bs", "wher do i get the imperial plate recipes", "derotain mudsipper quests what do i turn in" }, a = "Derotain Mudsipper in Gadgetzan, Tanaris gives the Imperial Plate plan quests (need level 50): Belt (20 Thorium Bar), Bracers (20), Boots (40) and Leggings (60). Chest and Helm plans come the same way. Bring ~250 Thorium so you can turn them all in and start crafting. Forever lowered Imperial Plate Belt to skill 240 (was 265).", topic = "prof_bs_eng" }
add{ q = { "mithril spurs plans", "mithril spurs leveling", "is mithril spurs worth it forever", "are mithril spurs good for leveling", "mithril spurs recipe", "where do i get mithril spurs plans", "mithril spurs skill up", "should i buy mithril spurs plans", "mithril spurs 215", "spurs leveling bs", "mithril spurs worth buying", "found mithril spurs plans on ah worth buying for leveling", "are spurs cheaper than other bs skill ups" }, a = "Mithril Spurs is a world-drop plan (check the AH). If you have it, it's the cheapest 215-240 option: about 10 crafts at 215-225 (40 Mithril, 30 Solid Grinding Stone) and 16 at 230-240 (64 Mithril, 48 Solid Grinding Stone), replacing the Heavy Mithril Breastplate/Boots.", topic = "prof_bs_eng" }
add{ q = { "where to buy green dye", "green dye vendor", "coal flux vendor blacksmith", "green dye", "who sells green dye", "where to buy coal", "where to buy flux", "strong flux vendor", "weak flux where", "need green dye for green iron bracers", "coal vendor blacksmithing", "where can i buy green dye for green iron bracers", "who sells coal and flux" }, a = "Green Dye: Tamar in Orgrimmar or Bombus Finespindle in Ironforge (trade supplies vendors). Coal, Weak Flux and Strong Flux are sold by the Blacksmithing Supply vendor standing next to the trainer in each capital.", topic = "prof_bs_eng" }
add{ q = { "bronze warhammer skill up", "why is bronze grey bs", "bronze items stop giving skill", "bronze recipes grey", "bronze warhammer", "why are my bronze recipes grey already", "skill up colors changed forever", "bronze stopped giving points", "last bronze recipe for skill ups", "bs recipes go grey early", "bronze grey early forever", "why are bronze recipes already grey for me", "is bronze warhammer the last bronze skill up" }, a = "Forever changed 180+ recipe skill-up colors so many go grey earlier than in Classic. Bronze Warhammer is the last Bronze craft that still gives points (yellow until about 155), so don't overbuy Bronze past 150.", topic = "prof_bs_eng" }
add{ q = { "blight blacksmithing forever", "blight weapon recipe", "what blacksmith recipe sells well", "blight recipe", "blight 2h", "is blight good for leveling bs", "blight mats", "what bs items sell well", "where to get blight plans", "blight blacksmith forever", "best selling bs recipe", "is blight worth making to level", "what bs stuff can i sell on ah" }, a = "Blight (Artisan, ~250-275) is a desirable BoE two-hander some guides use to level: 28 Mithril, 10 Ichor of Undeath, 10 Truesilver, 6 Solid Grinding Stone, 6 Thick Leather each. It wasn't confirmed whether it needs Weaponsmith in Forever. Bronze Shortswords at 125-140 also sell for well over twice what Bronze Bracers do.", topic = "prof_bs_eng" }
add{ q = { "arcanite blacksmith hammer", "new blacksmith hammer forever", "bs thrown weapon hammer", "arcanite hammer recipe", "blacksmith hammer thrown weapon", "bs hammer thrown", "new hammer recipe bs 270", "arcanite hammer mats", "arcanite bs hammer stun", "what is the arcanite blacksmith hammer", "thrown weapon blacksmithing", "is the arcanite blacksmith hammer good", "bs 270 new hammer thrown weapon what is it" }, a = "New Forever craft at Blacksmithing 270 (level 49): Arcanite Blacksmith Hammer, a thrown weapon with Strength/Spirit and a small chance to stun for 1 sec. It counts as a Blacksmith Hammer, so it frees a bag slot. Recipe: 4 Dark Iron Bar, 1 Arcanite Bar, 1 Blue Sapphire; also good skill-ups around 270-280. Plan source isn't confirmed.", topic = "prof_bs_eng" }
add{ q = { "steel bars blacksmithing", "how to make steel bar", "smelt steel forever", "steel bar", "how do i make steel bars", "steel bar mining", "smelt steel", "where to get steel bars", "can blacksmiths make steel", "steel bar mining skill requirement", "steel bars for golden scale bracers", "i dont have mining how do i get steel bars", "how to smelt steel bars wat skill" }, a = "Steel Bar needs Mining 165 to smelt (1 Iron Bar + 1 Coal). Non-miners must buy them. Golden Scale Bracers (5 Steel + 2 Heavy Grinding Stone) is the main Steel sink while leveling around 160-195.", topic = "prof_bs_eng" }
add{ q = { "azerothium bar", "what is azerothium", "how to make azerothium bar", "pitchblende", "azerothium", "azerothium bar recipe", "what is pitchblende", "where do i get azerothium", "how to smelt azerothium", "azerothium mining skill", "pitchblende ore", "new metal forever azerothium", "wher do i find pitchblende", "what is azerothium used for" }, a = "Azerothium Bar is a new Forever metal: smelted from 2 Pitchblende + 1 Coal at about skill 275. It goes into new Blacksmithing items (Thorium Cestus, Thorium Greatmace, Thorium Poleaxe, Bold Dirk, Bagh Nakh, Enriched Thorium set, Legionite Glaive, Stormcarver) plus Engineering's Ultralight Goblin Glider and SAF-T Tube. Other new mats: Legionite Bar, Torbernite, Marefoil.", topic = "prof_bs_eng" }
add{ q = { "merchant's favor blacksmith recipes", "where to buy bs plans merchant's favor", "gor'mak", "stondry darkhammer", "bs favor vendor", "merchants favor bs plans", "where to buy bs recipes with favor", "gormak barrens", "stondry three corners", "blacksmithing favor recipes", "who sells bs plans for merchant's favor", "favor vendor blacksmith", "where do i spend merchants favor on bs plans", "which favor vendor sells blacksmith recipes" }, a = "Blacksmithing Merchant's Favor plans are sold by Gor'mak (Horde camp, The Barrens) and Stondry Darkhammer (Alliance camp, Three Corners, Redridge). Chain sets (Guard's, Veteran's, Acolyte's, Protector's, Crusader's) at skill 45-125 cost 30 Favor; plate gauntlets/pauldrons (Sentinel's, Officer's, Prefect's, Warder's, Justicar's) at 175-210 cost 60 at Friendly; wristguards/sabatons/waistguards at 225-250 cost 90 at Honored. Gear made from these is BoP.", topic = "prof_bs_eng" }
add{ q = { "thorium cestus", "thorium greatmace", "legionite glaive", "enriched thorium set", "best merchant favor bs recipe", "best favor recipe bs", "thorium cestus recipe", "thorium greatmace recipe", "legionite glaive recipe", "enriched thorium", "honored favor bs plans", "best bs plans to buy with favor", "what favor recipes should a blacksmith get", "whats the best thing to buy with merchants favor as bs", "is thorium cestus worth getting" }, a = "At Honored with Azeroth Commerce Authority / Durotar Supply and Logistics: Thorium Cestus (fist) and Thorium Greatmace (2H mace) at skill 250 for 90 Favor; Enriched Thorium Breastplate/Helm/Leggings (defense + spell power plate) and Legionite Glaive (2H polearm) at 300 for 120 Favor. All bind on pickup and several use Azerothium Bars.", topic = "prof_bs_eng" }
add{ q = { "how do i get merchant's favor", "waylaid crate", "merchants favor how to earn", "where to turn in sealed crate", "how to earn merchant's favor", "merchants favor", "sealed crate turn in", "where do i turn in waylaid crate", "how to get favor", "merchant favor farm", "what do i do with waylaid crate", "how do i get merchants favor fast", "found a waylaid crate what do i do with it" }, a = "1. Get a Waylaid Crate (drops in the world and dungeons, or buy one on the AH).\n2. Fill it with the requested material bundle to make a Sealed crate (level 10/20/35 by rank).\n3. Turn it in to Dokimi (Horde camp, The Barrens) or Marcy Baker (Alliance, Three Corners, Redridge).\nJourneyman crates give 10-20 Favor, Expert 15-30; your first crate also starts a quest worth 50. Daily Craftsman's Writs give rep (75/125/200) but no Favor. At Friendly you can buy a Forged Delivery Receipt (15 Favor) to turn an empty crate into 50 rep.", topic = "prof_bs_eng" }
add{ q = { "armorsmith or weaponsmith", "which bs spec should i pick", "blacksmithing specialization forever", "bs spec choice", "armorsmith vs weaponsmith", "which bs spec", "bs spec", "should i be armorsmith or weaponsmith", "blacksmithing specialization", "best bs spec for warrior", "armorsmith or weaponsmith forever", "which bs specialization is better", "should my warrior go armorsmith or weaponsmith", "armor or weapon smith which is better in forever" }, a = "At Blacksmithing 200 and level 40 you can choose Armorsmith or Weaponsmith (optional). Armorsmith unlocks the best crafted plate like Lionheart Helm; Weaponsmith then branches into Master Axesmith, Hammersmith or Swordsmith for the endgame weapon plans. Spec-locked plans are excluded from normal leveling routes, so you don't need a spec to hit 300.", topic = "prof_bs_eng" }
add{ q = { "how to become armorsmith", "armorsmith quest", "art of the armorsmith", "armorsmith forever steps", "how do i become armorsmith", "armorsmith quest chain", "the art of the armorsmith", "armorsmith steps", "how to get armorsmith specialization", "armorsmith requirements", "myolor sunderfury armorsmith", "how to get armorsmith spec", "im 200 bs how do i become an armorsmith" }, a = "1. Be BS 200+, level 40.\n2. Talk to Myolor Sunderfury (Ironforge) or Krathok Moltenfist (Orgrimmar), pick armorsmith.\n3. Get 'The Art of the Armorsmith' from Grumnus Steelshaper (IF) or Okothos Ironrager (Org).\n4. Turn in 4 Ornate Mithril Helm, 2 Ornate Mithril Boots and 1 Ornate Mithril Breastplate.\nThose plans come from the optional Mithril Order chain (steps in other entries), but you can buy the pieces from the AH or another smith instead - only quest 5283 is required.", topic = "prof_bs_eng" }
add{ q = { "mithril order quest chain", "galvan the ancient", "mcgavan booty bay", "ornate mithril plans quests", "mithril order", "galvan", "mcgavan", "ornate mithril plans", "galvan the ancient quests", "mithril order quest steps", "how to get ornate mithril plans", "bs 210 quest chain", "how do i do the galvan quests", "where do i get ornate mithril plans" }, a = "1. BS 210: Alliance - Hank the Hammer (SW), craft 6 Golden Scale Bracers; Horde - Aturk the Anvil (Org), craft 4 Steel Breastplate + 4 Steel Plate Helm.\n2. Booty Bay: McGavan up the cave exit trail behind the shops (28.8, 75.4) - get The Mithril Order.\n3. Galvan the Ancient in northern STV (50.6, 20.6): do all three - Smelt On, Smelt Off (40 Iron, 40 Mithril), The Art of the Imbue (40 Mithril, 4 Citrine), The Great Silver Deceiver (40 Mithril, 5 Truesilver). Rewards: Ornate Mithril Pants/Shoulders/Gloves plans.\n4. Finish all three before leaving, then take Galvan's Finest Pupil.", topic = "prof_bs_eng" }
add{ q = { "trenton lighthammer", "armorsmith gadgetzan quests", "ornate mithril helm plans", "the mithril kid", "ornate mithril helm", "armorsmith quests gadgetzan", "trenton gadgetzan quests", "where is trenton lighthammer", "armorsmith gadgetzan", "wher is trenton lighthammer", "armorsmith quest in gadgetzan how do i start it", "trenton lighthammer quest" }, a = "At BS 235, learn Mithril Coif, Heavy Mithril Boots and Heavy Mithril Breastplate from Brikk in Booty Bay, then find Trenton Lighthammer outside the Gadgetzan forge (51.4, 28.6). Quests: The World At Your Feet, A Good Head On Your Shoulders, The Mithril Kid - turn in 2 Mithril Coif, 2 Heavy Mithril Boots, 2 Heavy Mithril Breastplate plus one each of Ornate Mithril Shoulder, Pants and Gloves. Rewards: Ornate Mithril Boots, Helm and Breastplate plans.", topic = "prof_bs_eng" }
add{ q = { "armorsmith materials total", "how much mithril for armorsmith", "armorsmith mats list", "armorsmith mats", "armorsmith cost", "mats for armorsmith quests", "armorsmith total mats list", "what do i need for armorsmith", "armorsmith materials", "how expensive is armorsmith", "how much will armorsmith cost me", "how many mithril bars do i need for the armorsmith quests" }, a = "Full Armorsmith chain (both factions): ~342 Mithril Bar, 26 Truesilver, 40 Iron, 30 Steel, 36 Solid Stone, 36 Heavy Stone, 18 Mageweave, 22 Thick Leather, 4 Citrine, 3 Aquamarine, 4 Black Pearl, 1 Heart of Fire. Horde also need ~90 more Steel, 16 Solid Stone and 4 Citrine for Aturk's steel quest. The final turn-in alone: 4 Ornate Mithril Helm, 2 Boots, 1 Breastplate.", topic = "prof_bs_eng" }
add{ q = { "how to become weaponsmith", "weaponsmith quest", "way of the weaponsmith", "weaponsmith forever", "how do i become weaponsmith", "weaponsmith quest chain", "the way of the weaponsmith", "weaponsmith steps", "how to get weaponsmith", "weaponsmith requirements", "krathok moltenfist weaponsmith", "how to get weaponsmith spec", "im 200 bs how do i become a weaponsmith" }, a = "1. BS 200, level 40.\n2. Talk to Myolor Sunderfury (IF) or Krathok Moltenfist (Org) and choose 'I wish to become a weaponsmith' (quest won't show otherwise).\n3. Take 'The Way of the Weaponsmith' from Ironus Coldsteel (IF) or Borgosh Corebender (Org).\n4. Turn in 4 Moonsteel Broadsword, 4 Massive Iron Axe, 2 Heavy Mithril Axe, 2 Big Black Mace. AH-bought or friend-crafted ones are fine.", topic = "prof_bs_eng" }
add{ q = { "weaponsmith mats", "where to get moonsteel broadsword plans", "massive iron axe plans", "big black mace plans", "weaponsmith mats list", "moonsteel broadsword plans", "where to buy weaponsmith quest plans", "weaponsmith plans where", "what do i need for weaponsmith quest", "weaponsmith materials", "wher do i buy moonsteel broadsword plans", "what do i need to make for the weaponsmith quest" }, a = "Plans: Moonsteel Broadsword from Zarena Cromwind (Old Port Authority, Booty Bay); Massive Iron Axe from Jaquilina Dramet (Nesingwary's Camp, STV) or Vharr (Grom'gol, Horde); Big Black Mace (205) from Brikk Keencraft, Booty Bay; Heavy Mithril Axe (185) from Saru Steelfury, Alard Schmied or Brikk. Mats for all 12: 56 Mithril, 56 Iron, 32 Steel, 16 Gold, 16 Heavy + 4 Solid Grinding Stone, 12 Lesser Moonstone, 8 Shadowgem, 4 Citrine, 2 Black Pearl, 28 Heavy + 4 Thick Leather, 16 Strong Flux.", topic = "prof_bs_eng" }
add{ q = { "master axesmith", "master hammersmith", "master swordsmith", "how to become master axe smith", "weaponsmith sub spec", "weaponsmith specialization", "how to become hammersmith", "how to become swordsmith", "weaponsmith subspec", "everlook weaponsmith trainers", "how do i become a master swordsmith", "which weaponsmith subspec should i pick", "everlook weaponsmith quests" }, a = "After Weaponsmith, go to the house in Everlook, Winterspring where three trainers stand together and do one dungeon quest:\n- Axesmith: Kilram, 'Snakestone of the Shadow Huntress' - kill Shadow Hunter Vosh'gajin in Lower Blackrock Spire.\n- Hammersmith: Lilith the Lithe, 'Sweet Serenity' - kill the Crimson Hammersmith in live-side Stratholme.\n- Swordsmith: Seril Scourgebane, 'Corruption' - kill the Black Guard Swordsmith in undead-side Stratholme.\nYou can only be one.", topic = "prof_bs_eng" }
add{ q = { "lionheart helm", "lionheart helm forever", "best warrior helm forever", "is lionheart bis", "is lionheart helm worth it", "lionheart bis", "best helm for warrior", "lionheart helm good in forever", "best dps warrior helm forever", "lionheart vs stalwart helm", "is lionheart still bis", "should i make lionheart helm for my warrior", "is lionheart helm still the best warrior helm in forever" }, a = "Yes - RankedBoost's Forever tier list puts Lionheart Helm as S-tier, the best DPS warrior helm (Stalwart Helm, a new Forever blacksmith plan, is A-tier). Enchanted Thorium Helm is C-tier and Enriched Thorium Helm D-tier. Lionheart is a Blacksmithing 300 craft from a rare world-drop plan and binds on equip, so non-smiths can buy it on the AH.", class = "WARRIOR", topic = "prof_bs_eng" }
add{ q = { "lionheart helm mats classic", "does lionheart need armorsmith", "wicked claw lionheart", "lionheart helm mats", "lionheart helm recipe", "lionheart helm armorsmith", "how much does lionheart helm cost", "wicked claw", "lionheart helm requirements", "what do i need for lionheart helm", "lionheart helm plans", "how much do lionheart mats cost", "do i need armorsmith to make lionheart helm" }, a = "Classic 1.12 baseline: Lionheart Helm required Armorsmith and Blacksmithing 300, cost 80 Thorium Bar, 12 Arcanite Bar, 40 Wicked Claw, 10 Blue Sapphire, 4 Azerothian Diamond; it gave +18 Str, 2% crit and 2% hit (level 56). Later versions dropped the Wicked Claws. Forever's exact mats/spec rule isn't confirmed - check the plan tooltip.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "forever blacksmith bis items", "crafted bis warrior forever", "what blacksmith items are bis", "best crafted plate forever", "bis blacksmith items", "best crafted plate", "crafted bis warrior", "what bs items are bis", "best blacksmithing gear forever", "best crafted gear for warrior", "bis crafted plate forever", "what crafted plate is bis", "what crafted plate is bis for warriors in forever", "which blacksmith gear is bis" }, a = "Forever Arms warrior BiS lists include these crafted blacksmith items: Lionheart Helm (head), Obsidian Mail Tunic (chest), Titanic Leggings and the new Azerothium Legplates (legs), Nightfall and the new Forest Defender's Axe (weapons). Lionheart and Titanic Leggings are the big moneymakers to sell.", class = "WARRIOR", topic = "prof_bs_eng" }
add{ q = { "arcanite reaper", "arcanite reaper plans", "where do arcanite reaper plans drop", "arcanite reaper mats", "arcanite reaper recipe", "is arcanite reaper still in forever", "how to make arcanite reaper", "arcanite reaper forever", "how do i make arcanite reaper", "arcanite reaper recipe wher" }, a = "Arcanite Reaper is still in Forever as an old (unchanged) 300-skill drop plan. Classic baseline: plans drop from Bannok Grimaxe in Lower Blackrock Spire (rare), and it takes 20 Arcanite Bar, 6 Enchanted Leather and 2 Dense Grinding Stone. Makes a 2H axe with +62 AP and +13 Stam, level 58. Forever also lists Refined Arcanite Reaper and Arcanite Champion.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "arcanite champion", "arcanite champion mats", "righteous orb sword", "arcanite champion recipe", "righteous orb", "arcanite champion plans", "how to make arcanite champion", "arcanite champion forever", "arcanite champion sword", "how much does arcanite champion cost to make", "where do i get the righteous orb for arcanite champion" }, a = "Classic baseline: Arcanite Champion (2H sword, lvl 58, procs a self-heal and +120 Str for 30s) costs 15 Arcanite Bar, 8 Azerothian Diamond, 1 Righteous Orb, 4 Large Opal, 8 Enchanted Leather, 2 Dense Grinding Stone. The plan is still listed as a 300-skill drop in Forever.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "dark iron gear blacksmithing", "dark iron plans forever", "dark iron reaver", "dark iron helm plans", "dark iron plans", "dark iron gear", "dark iron helm", "dark iron bracers", "fiery chain girdle", "dark iron plate", "dark iron recipes forever", "how do i get dark iron plans", "where do i buy dark iron recipes" }, a = "Dark Iron plans are unchanged Thorium Brotherhood vendor plans in Forever (skill 295-300): Dark Iron Bracers (Friendly), Fiery Chain Girdle, Dark Iron Reaver, Dark Iron Destroyer, Dark Iron Helm (Honored), Dark Iron Gauntlets, Dark Iron Leggings, Fiery Chain Shoulders, Black Amnesty, Blackfury (Revered), Dark Iron Boots, Nightfall, Ebon Hand, Blackguard (Exalted). Buy them from Lokhtos Darkbargainer in BRD's Grim Guzzler.", topic = "prof_bs_eng" }
add{ q = { "sulfuron hammer", "how to get sulfuron hammer plans", "sulfuron ingot", "sulfuron hammer plans", "sulfuron hammer mats", "how to make sulfuron hammer", "sulfuron hammer quest", "where do i get sulfuron ingot", "sulfuron hammer forever", "how do i make sulfuron hammer", "where do i get a sulfuron ingot", "sulfuron hammer plans wher" }, a = "Sulfuron Hammer is still a 300 Blacksmithing quest plan in Forever. Classic baseline: get a Sulfuron Ingot (Molten Core) and a Thorium Brotherhood Contract from Lokhtos Darkbargainer (Grim Guzzler, BRD), then turn both in for the level 60 quest 'A Binding Contract' - rewards Plans: Sulfuron Hammer and 1000 Thorium Brotherhood rep. The hammer is part of the Sulfuras, Hand of Ragnaros chain.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "new endgame blacksmith items forever", "stalwart helm", "forest defender's axe", "azerothium legplates", "stormcarver", "new 300 bs plans", "forest defenders axe", "new forever endgame bs", "new blacksmithing recipes at 300", "what are the new bs plans", "whats new at 300 blacksmithing", "where do the new 300 bs plans come from", "where to get stalwart helm plans" }, a = "New 300-skill Forever plans with unconfirmed sources: Azerothium Legplates, Depleted Thorium Sabatons, Evergreen Shield, Forest Defender's Axe, Greenhammer, Heavy Thorium Gauntlets, Ironwood Blade, Bagh Nakh, Breastplate of Salvation, Champion's Legplates, Martyr's Legplates, Stalwart Helm and Stormcarver. Vendor-sold new sets include the Glory and Justice armor pieces.", topic = "prof_bs_eng" }
add{ q = { "blessed plate", "blessed plate bracers", "blessed plate belt leveling", "blessed plate belt", "blessed plate leveling", "blessed plate mats", "blessed plate set", "blessed plate recipe", "blessed plate forever", "what is blessed plate", "is blessed plate good for leveling bs" }, a = "Blessed Plate is a new Forever plate line at skill 240-280. Some routes use Blessed Plate Bracers (255-279, Thorium + Blue Sapphire) and Blessed Plate Belt (279-292, Thorium, Blue Sapphire, Rugged Leather, Iron Buckles), but plan sources weren't confirmed, so the Imperial Plate quest route is the safe path.", topic = "prof_bs_eng" }
add{ q = { "enchanted thorium helm", "enchanted thorium plans", "enchanted thorium forever", "enchanted thorium", "enchanted thorium breastplate", "enchanted thorium leggings", "enriched thorium", "enchanted vs enriched thorium", "where do i get enchanted thorium plans", "whats the difference between enchanted and enriched thorium", "enchanted thorium quest" }, a = "Enchanted Thorium Breastplate, Helm and Leggings are still quest-reward plans at 300 in Forever (old). The new Enriched Thorium Breastplate/Helm/Leggings (defense + spell power) are Merchant's Favor plans for 120 Favor at Honored. RankedBoost rates Enchanted Thorium Helm C-tier and Enriched D-tier for DPS warriors.", topic = "prof_bs_eng" }
add{ q = { "does blacksmith make mail forever", "mail moved to leatherworking", "where did invulnerable mail go", "can bs make mail", "invulnerable mail", "mail moved to lw", "where did mail go", "helm of the great chief", "can blacksmiths make mail armor", "mail crafting forever", "invulnerable mail forever", "can blacksmiths still make invulnerable mail", "why cant i find mail recipes in bs" }, a = "Endgame mail was moved to Leatherworking: Helm of the Great Chief, Invulnerable Mail, Heavy Timbermaw Boots/Belt, Wildthorn Mail and Storm Gauntlets. Blacksmithing keeps lots of new leveling mail (58 mostly-BoP pieces for levels 10-35) and plate for 40-58.", topic = "prof_bs_eng" }
add{ q = { "early blacksmith gear leveling", "copper boots forever", "strange copper boots", "skyforged armor", "early bs gear", "copper boots", "low level bs gear", "early blacksmith gear forever", "best early bs items", "blacksmith leveling gear", "what early bs gear is good for leveling", "what are skyforged armor plans" }, a = "Forever added useful early BoP blacksmith gear: Gemmed, Glowing and Strange Copper Boots (skill 35, trainer), the Skyforged chain set (50-60, mostly vendor), Silvered Chain and Sterling Silver pieces (80-125), Hard Gold pieces (145-175), plus trainer belts at 150 (Justicar's, Officer's, Prefect's, Sentinel's, Warder's). Hybrid classes get real stats on these.", topic = "prof_bs_eng" }
add{ q = { "sharpening stones stack windfury", "do weightstones stack with poison forever", "bs stones worth it rogue", "sharpening stone windfury", "weightstone windfury", "do stones stack with windfury", "sharpening stones stack with poisons", "are stones worth it", "do stones stack forever", "sharpening stone rogue", "weightstone poisons stack", "do sharpening stones stack with windfury in forever", "are weightstones worth it on my rogue" }, a = "Yes. In Forever, Sharpening Stones and Weightstones stack with rogue poisons, Windfury Weapon and Windfury Totem, so blacksmith stones are always worth using.", topic = "prof_bs_eng" }
add{ q = { "blacksmith profession bonus", "free repair blacksmith", "belt buckle bonus", "bs profession bonus", "free repair bs", "belt buckle bs", "blacksmith bonus", "blacksmithing perks forever", "what bonus does bs give", "bs repair cooldown", "belt buckles forever", "does blacksmithing give a bonus like free repairs", "bs profession perk" }, a = "BlizzCon 2026 showed a Blacksmithing profession bonus (stat belt buckles and a free 'Repair All' cooldown), but guides flag it as unconfirmed in the live game. Don't count on it until you see it in your spellbook.", topic = "prof_bs_eng" }
add{ q = { "lokhtos darkbargainer", "where is lokhtos", "grim guzzler vendor", "lokhtos", "grim guzzler", "thorium brotherhood vendor", "where is the thorium brotherhood vendor", "lokhtos location", "lokhtos brd", "wher is lokhtos", "where do i buy thorium brotherhood plans in brd" }, a = "Lokhtos Darkbargainer is in the Grim Guzzler tavern inside Blackrock Depths. He sells the Thorium Brotherhood plans (Dark Iron set, Fiery Chain, Nightfall etc.) and takes the Honored+ rep turn-ins. Reaching the bar needs a decent group. Classic baseline; Forever lists his Dark Iron plans as vendor plans.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "thorium brotherhood exalted mats", "how many dark iron ore for exalted", "fiery core turn in", "thorium brotherhood exalted", "lava core turn in", "how long thorium brotherhood exalted", "core leather", "blood of the mountain", "how many dark iron ore to get exalted thorium brotherhood", "how many fiery cores for exalted", "thorium brotherhood exalted fast" }, a = "Classic baseline: Honored to Exalted with only repeatables needs about 165 Lava Core, or 165 Fiery Core, or 165 Blood of the Mountain, or 440 Core Leather, or 6,600 Dark Iron Ore - mix and match. Molten Core drops make it far faster than ore.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "dark iron smelting", "how to smelt dark iron", "spectral chalice", "smelt dark iron", "dark iron smelting requirements", "gloom'rel", "where to smelt dark iron", "dark iron ore", "how do i learn to smelt dark iron", "where is the dark iron smelting quest", "dark iron smelting quest brd" }, a = "Classic baseline: with Mining 230, talk to Gloom'rel in Blackrock Depths and complete The Spectral Chalice to learn Smelt Dark Iron; Dark Iron Ore is then smelted at the Black Forge inside BRD. Dark Iron Bars feed the Thorium Brotherhood Dark Iron gear and Forever's new Arcanite Blacksmith Hammer (4 per craft).", src = "classic", topic = "prof_bs_eng" }
add{ q = { "engineering skill cap forever", "engineering ranks", "engineering trainer requirements", "engineering cap", "engi max skill", "engineering skill cap", "engineering ranks forever", "engineering trainer level requirements", "what level for expert engineering", "how high does engineering go in forever", "engi rank reqs", "whats the max engineering skill", "what lvl do i need for each engi rank" }, a = "Engineering caps at 300 with Apprentice (cap 75), Journeyman (skill 50, lvl 10, cap 150), Expert (skill 125, lvl 20, ~50s, cap 225) and Artisan (skill 200, lvl 35, cap 300).", topic = "prof_bs_eng" }
add{ q = { "what do i need for engineering", "engineering tools", "arclight spanner", "gyromatic micro adjustor", "do engineers need blacksmith hammer", "engineering tools needed", "what do engineers need", "blacksmith hammer for engineering", "where to buy arclight spanner", "what tools do i need for engi", "engi tools", "what tools do engineers need", "wher do i buy an arclight spanner" }, a = "Keep three tools in your bags: a Blacksmith Hammer (bought from trade vendors near most trainers - not available on Dun Morogh or Zephras Isle trainers' vendors), an Arclight Spanner (craft at 50, 6 Copper Bar) and a Gyromatic Micro-Adjustor (craft ~194, 4 Steel Bar). Many Forever recipes also need an Anvil.", topic = "prof_bs_eng" }
add{ q = { "best profession with engineering", "engineering and mining", "engineering alchemy forever", "engineering + mining", "best profession with engi", "engi and mining", "engineering and alchemy", "what to pair with engineering", "engi second prof", "is mining required for engineering", "engineering and herbalism", "what should i pair with engineering", "is engi + mining the best combo" }, a = "Mining is the standard pair - nearly everything uses stone and bars. Warcraft Tavern notes many Forever schematics also need Alchemy-made materials, so Alchemy is a reasonable second choice if you buy ore.", topic = "prof_bs_eng" }
add{ q = { "engineering trainers forever", "where is engineering trainer", "journeyman engineering trainer", "expert engineering trainer location", "engineering trainer location", "where is engi trainer", "engineering trainer", "expert engi trainer", "engineering trainer org", "where can i train engineering", "engineering trainer stormwind", "journeyman engi trainer", "wher is the engineering trainer", "who trains engineering in org" }, a = "Apprentice: Thund (Org), Graham Van Talen (UC), Mukdrak (Razor Hill), Twizwick (Mulgore), Tinkerwiz (Ratchet), Sprite Jumpsprocket (SW), Jemma Quikswitch (IF Tinker Town), Bronk Guzzlegear (Dun Morogh), Deek Fizzlebizz (Loch Modan), Jenna Lemkenilli (Auberdine), Strange Hermit (Shadowgale Forest, Zephras Isle). Journeyman (50, lvl 10): Nogg (Org), Franklin Lloyd (UC), Trixie Quikswitch (IF), Lilliam Sparkspindle (SW), Finbus Geargrind (Darkshire). Expert (125, lvl 20): Roxxik (Org) or Springspindle Fizzlegear (IF).", topic = "prof_bs_eng" }
add{ q = { "strange hermit engineering", "zephras isle engineering trainer", "skyborne engineering", "engineering trainer skyborne", "strange hermit", "engineering zephras", "zephras engineering", "where is engineering trainer on zephras", "strange hermit shadowgale", "skyborne engi trainer", "zephras isle engineering trainer location", "where is the engi trainer on zephras", "im skyborne where do i learn engineering" }, a = "On Zephras Isle the Engineering trainer is the Strange Hermit in Shadowgale Forest (~54.0, 39.0). He only opens the trainer window after a short chat every visit.", topic = "prof_bs_eng" }
add{ q = { "engineering camp features", "reagent bot", "repair bot camp", "anarchist's workbench", "engineering camp", "engineering camp blueprints", "anarchists workbench", "what camp stuff does engineering get", "engi camp items", "what does engineering add to camp", "what can engineers put at camp", "how do i get the repair bot for camp" }, a = "Engineering camp features (no buff, pure utility): Reagent Bot at skill 20 (buy/sell reagents), Repair Bot at 140 (repair gear; blueprint sold by Happy Camper in Dun Morogh per wow.gg, also listed as a drop) and Anarchist's Workbench at 300 (workstation some high-end recipes need). Camp items share a 1-hour cooldown.", topic = "prof_bs_eng" }
add{ q = { "gnome engineering racial forever", "gnome +15 engineering", "engineering specialization racial changed", "gnome racial engineering", "gnome engineering bonus", "gnome racial changed", "do gnomes still get +15 engineering", "engineering specialization gnome", "gnome engi racial", "do gnomes still get +15 engineering in forever", "whats the gnome engineering racial now" }, a = "Gnomes no longer get +15 Engineering. Their Engineering Specialization racial now cuts the chance engineering devices fail or backfire by 20%.", topic = "prof_bs_eng" }
add{ q = { "engineering certification", "engineer title forever", "how to get engineer title", "engineering title", "engineer title", "engineering certification cost", "how to get engineering certification", "engineering title forever", "engi cert", "engineering cert vendor", "how do i get the engineering title", "how much merchants favor for engi certification" }, a = "Engineering Certification is bought for 1000 Merchant's Favor from the Engineering Favor vendor (Fritz Fizzle, Alliance; Fizzlefuse, Horde) and unlocks a title at 300 skill.", topic = "prof_bs_eng" }
add{ q = { "engineering 1-75", "engi 1 75 forever", "apprentice engineering guide", "engi 1-75", "engineering 1 to 75", "starting engineering", "what do i make first engineering", "engineering leveling 1-75", "rough blasting powder", "engi beginner guide", "engineering 1-75 forever", "just started engineering what do i make", "engi 1-75 fastest" }, a = "1-75:\n1. 1-30: 60x Rough Blasting Powder (60 Rough Stone) - keep them.\n2. 30-50: 30x Handful of Copper Bolts (30 Copper Bar) - keep them.\n3. Train Journeyman at 50 (lvl 10).\n4. 50-51: 1x Arclight Spanner (6 Copper Bar) - keep forever.\n5. 51-75: 30x Rough Copper Bomb (30 Copper Bar, 30 Bolts, 60 Rough Powder, 30 Linen).\nAlt: Copper Tube 54-75 (2 Copper + 1 Weak Flux).", topic = "prof_bs_eng" }
add{ q = { "engineering 75-150", "engi 75 150", "journeyman engineering leveling", "engi 75-150", "engineering 75 to 150", "journeyman engi route", "what to make 75 engineering", "engineering 100", "coarse dynamite leveling", "engi leveling 75 150", "engineering 75-150 forever", "im 75 engineering what now", "engi 75-150 what to make" }, a = "75-150:\n1. 75-90: 60x Coarse Blasting Powder (60 Coarse Stone).\n2. 90-100: 20x Coarse Dynamite (60 Coarse Powder, 20 Linen).\n3. 100-105: 5x Silver Contact (5 Silver Bar) or Flying Tiger Goggles.\n4. 105-125: 25x Bronze Tube (50 Bronze, 25 Weak Flux); keep 10. Train Expert at 125.\n5. 125-135: 10x Standard Scope (Bronze Tube + Moss Agate).\n6. 135-150: 30x Heavy Blasting Powder (30 Heavy Stone), then 15x Whirring Bronze Gizmo (2 Bronze, 1 Wool each).", topic = "prof_bs_eng" }
add{ q = { "engineering 150-225", "engi 150 225", "expert engineering leveling", "engineering 200", "engi 150-225", "engineering 150 to 225", "what to make at 150 engineering", "explosive sheep leveling", "bronze framework leveling", "im 175 engi what do i craft", "expert engi route forever", "engineering 150-225 what do i make next", "just trained expert engi what do i make", "engineering 175-225" }, a = "150-225:\n1. 150-160: 15x Bronze Framework (2 Bronze, Medium Leather, Wool).\n2. 160-175: 15x Explosive Sheep - keep 5 for the Goblin quest.\n3. 175-194: 60x Solid Blasting Powder (120 Solid Stone).\n4. 194-195: Gyromatic Micro-Adjustor (4 Steel).\n5. 195-200: 6x Mithril Tube (18 Mithril) - keep for the Gnomish quest.\n6. Train Artisan at 200 with Buzzek in Gadgetzan.\n7. 200-215: 20x Unstable Trigger (Mithril, Mageweave, Solid Powder).\n8. 215-225: Mithril Casing (3 Mithril each).", topic = "prof_bs_eng" }
add{ q = { "engineering 225-300", "engi 225 300", "artisan engineering route", "how to get engineering to 300 forever", "engi 225-300", "engineering 225 to 300", "artisan engi leveling", "mithril casing leveling", "how do i finish engineering", "im 250 engineering what now", "engineering 250 what to craft", "just trained artisan engi whats the route to 300", "how to get engineering 225-300 cheap", "artisan engineering what to craft" }, a = "225-300:\n1. 215-238: 40x Mithril Casing (120 Mithril).\n2. 238-250: 20x Hi-Explosive Bomb (2 Casing, 1 Unstable Trigger, 2 Solid Powder each).\n3. 250-260: ~30x Dense Blasting Powder (60 Dense Stone).\n4. 260-285: 35x Thorium Widget (3 Thorium + 1 Runecloth). Plan from Sovik (Org) or Gearcutter Cogspinner (IF), ~1g26s.\n5. 285-300: 20x Thorium Tube (6 Thorium each). Plan from Xizzer Fizzbolt in Everlook - BoP in Forever, so buy it on the engineer. Alt: Delicate Arcanite Converter (Arcanite Bar + Ironweb Spider Silk), plan 2g from Xizzer.", topic = "prof_bs_eng" }
add{ q = { "engineering shopping list", "what do i buy for engineering", "engineering mats 1-300", "how much thorium for engineering", "engi mats", "engineering mats list", "what mats for engineering 1-300", "how much does engineering cost to level", "total mats engi 300", "what to buy on ah for engineering", "how many bars do i need for engineering", "engineering cost to max forever", "how much gold to level engineering to 300", "engi 1-300 shopping list" }, a = "Approx totals: 60 Rough Stone, 66 Copper Bar, 50 Linen, 60 Coarse Stone, 5 Silver Bar, 110 Bronze Bar, 25 Weak Flux (vendor), 10 Moss Agate, 30 Heavy Stone, 60 Wool, 15 Medium Leather, 4 Steel Bar, 120 Solid Stone, ~160 Mithril Bar, 20 Mageweave, 60 Dense Stone, ~225 Thorium Bar, 35 Runecloth. Much cheaper than Blacksmithing; buy ~10% extra.", topic = "prof_bs_eng" }
add{ q = { "alternative engineering route", "flash bomb leveling", "gold power core gyrochronatom leveling", "other engineering leveling route", "cheaper engi route", "gold power core leveling", "gyrochronatom leveling", "flash bomb skill up", "alternate engineering guide forever", "kami labs engineering route", "is there a cheaper way to level engi", "any cheaper way to level engineering than the usual guide", "engi alt route forever" }, a = "Kami-labs' verified route differs mid-game: Silver Contact 90-125, Heavy Blasting Powder 125-140, Whirring Bronze Gizmo 140-150, Gold Power Core 150-170, Gyrochronatom 170-186, Flash Bomb 186-210 (Blue Pearl, Heavy Powder, Silk), Hi-Impact Mithril Slugs 210-215, Mithril Casing 215-241, Rose Colored Goggles 241-245, Mithril Gyro-Shot 245-250, Dense Blasting Powder 250-258, Thorium Widget 260-285, Delicate Arcanite Converter 285-300.", topic = "prof_bs_eng" }
add{ q = { "gnomish or goblin engineering", "gnomish vs goblin forever", "which engineering spec", "goblin or gnome engi pvp", "gnomish vs goblin", "which engi spec", "gnome or goblin engineering", "best engineering spec pvp", "best engineering spec pve", "goblin or gnomish forever", "should i go gnomish or goblin on my rogue", "which engineering specialization is better", "goblin or gnomish for pvp in forever", "im 200 engi which spec should i pick" }, a = "Pick by the BoP toys you want. Gnomish: Gnomish Battle Chicken (raid melee buff), Death Ray, Mind Control Cap, Net-o-Matic, Rocket Boots, Shrink Ray, World Enlarger, Gadgetzan teleporter. Goblin: Bomb Dispenser, Dragon Gun, Construction Helmet, Rocket Helmet, Mortar, The Big One, Jumper Cables XL, Everlook teleporter. Classically, PvPers favored Goblin and melee raiders Gnomish for the chicken, and Gnomish engineers traditionally had to buy Sapper Charges (any engineer can use them).", topic = "prof_bs_eng" }
add{ q = { "how to become gnomish engineer", "gnome engineering quest", "tinkmaster overspark", "show your work gnomish", "gnomish engineering quest", "how do i become gnomish", "tinkmaster overspark quest", "gnomish show your work", "how to get gnomish engineering", "gnomish spec quest steps", "where do i start the gnomish engineering quest", "gnome engi spec how", "how do i do the gnomish engineering quest", "im horde how do i become gnomish engineer" }, a = "Engineering 200, level 30.\n1. Alliance: get 'Gnome Engineering' from Springspindle Fizzlegear (IF), turn in to Tinkmaster Overspark (Tinker Town). Horde: get it from Tinkerwiz in Ratchet, boat to Booty Bay, find Oglethorpe Obnoticus (above First Mate Crazz).\n2. Take The Pledge of Secrecy, right-click the Pledge in your bags.\n3. 'Show Your Work': turn in 6 Mithril Tube, 1 Accurate Scope, 2 Advanced Target Dummy. Accurate Scope plan is from Mazk Snipeshot, Booty Bay.", topic = "prof_bs_eng" }
add{ q = { "gnomish quest mats", "advanced target dummy mats", "accurate scope gnomish quest", "what do i need for gnomish show your work", "advanced target dummy", "accurate scope for gnomish quest", "mats for gnomish engineering", "gnomish spec materials list", "how many mithril bars for gnomish quest", "what to bring for gnomish quest", "what mats do i need to bring for gnomish quest", "gnomish show your work what to craft" }, a = "Gnomish 'Show Your Work' raw mats: 18 Mithril Bar (for 6 Mithril Tubes, if you didn't save them), 6 Bronze Bar, 6 Iron Bar, 1 Jade, 1 Citrine, 1 Gold Bar, 2 Medium Leather, 8 Heavy Leather, 2 Wool. Craft order: Bronze Tube, Accurate Scope, 2 Iron Strut, 2 Bronze Framework, Gold Power Core, 2 Gyrochronatom, 2 Advanced Target Dummy.", topic = "prof_bs_eng" }
add{ q = { "how to become goblin engineer", "goblin engineering quest", "nixx sprocketspring", "goblin show your work", "how do i become goblin engineer", "nixx sprocketspring quest", "how to get goblin engineering", "goblin spec quest steps", "where do i start goblin engineering", "goblin engi spec how", "how do i do the goblin engineering quest", "wher is nixx sprocketspring" }, a = "Engineering 200, level 30.\n1. Get 'Goblin Engineering' from an engineering trainer (Tinkerwiz in Ratchet works for both factions).\n2. Go to Nixx Sprocketspring in Gadgetzan, Tanaris, take The Pledge of Secrecy and right-click it.\n3. 'Show Your Work': turn in 20 Big Iron Bomb, 20 Solid Dynamite, 5 Explosive Sheep.\nRaw mats: 2 Silver Bar, 30 Iron Bar, 30 Heavy Stone, 20 Solid Stone, 10 Silk (+ 10 Wool, 5 Medium Leather, 20 Bronze, 10 Heavy Stone if you didn't keep 5 sheep).", topic = "prof_bs_eng" }
add{ q = { "melbin powderfuse", "goblin engineering trainer riverglades", "powderfuse port", "where is melbin powderfuse", "riverglades engineering trainer", "new goblin engineer trainer forever", "master goblin engineer riverglades", "powderfuse port goblin trainer", "wher is melbin powderfuse", "is there a goblin engineering trainer in riverglades" }, a = "Melbin Powderfuse is a new Forever Master Goblin Engineer in Powderfuse Port, Riverglades (77.6, 50.8), neutral to both factions, added in patch 1.60.1 (Nov 4 2026). Goblin specialization trainers are him, Nixx Sprocketspring (Gadgetzan) and Vazario Linkgrease (Ratchet); Gnomish ones are Tinkmaster Overspark (IF) and Oglethorpe Obnoticus (Booty Bay).", topic = "prof_bs_eng" }
add{ q = { "how to switch engineering spec", "change gnomish to goblin", "unlearn engineering specialization", "soothsaying for dummies", "switch engineering spec", "change goblin to gnomish", "unlearn gnomish", "how do i swap engi spec", "can i respec engineering", "how to drop goblin engineering", "can i switch from gnomish to goblin engineering", "how much does it cost to swap engi spec" }, a = "Switching is costly: you must unlearn Engineering (Skills tab), losing every recipe and point, re-level to 200, then read 'Soothsaying for Dummies' in the hut at Steamwheedle Port, Tanaris, which lets you take the other school without redoing the quest. Any bought/dropped schematics are lost.", topic = "prof_bs_eng" }
add{ q = { "gnomish then goblin trick", "craft gnomish items then switch", "keep battle chicken switch goblin", "gnomish then goblin", "go gnomish first then goblin", "keep gnomish items after switching", "do i keep battle chicken if i switch to goblin", "engineering spec switch trick", "craft gnomish stuff then swap", "can i use gnomish items as goblin", "best way to get both engi specs items", "if i go gnomish then switch to goblin do i keep the items", "can i get both gnomish and goblin stuff" }, a = "Common trick: go Gnomish first, craft the BoP Gnomish items you want (Battle Chicken, Death Ray, etc.), then unlearn, re-level to 200 and switch to Goblin via Soothsaying for Dummies. You keep crafted items; only spec-required ones like the Gadgetzan teleporter stop working. Costs a full re-level in time and gold.", topic = "prof_bs_eng" }
add{ q = { "gnomish exclusive items", "what does gnomish engineering give", "gnomish engineering items list", "what does gnomish get", "gnomish items", "gnomish only items", "gnomish engineering list", "gnomish engineering perks", "what can gnomish engineers make", "gnomish exclusive recipes", "whats good about gnomish engineering", "what are the gnomish engineering items", "is gnomish engineering worth it" }, a = "Gnomish-only: Ultrasafe Transporter - Gadgetzan, World Enlarger (shrink), Lil' Smoky pet, Gnomish Battle Chicken (1.5-min pet, 20-min CD, BoP), Gnomish Death Ray (4-sec cast, hits you and the target hard, 5-min CD, BoP), Gnomish Goggles, Rocket Boots, Shrink Ray, Alarm-O-Bot, Mind Control Cap, Net-o-Matic Projector, Harm Prevention Belt.", topic = "prof_bs_eng" }
add{ q = { "goblin exclusive items", "what does goblin engineering give", "goblin engineering items list", "what does goblin get", "goblin items", "goblin only items", "goblin engineering list", "goblin engineering perks", "what can goblin engineers make", "goblin exclusive recipes", "whats good about goblin engineering", "what are the goblin engineering items", "is goblin engineering worth it" }, a = "Goblin-only: Dimensional Ripper - Everlook, Pet Bombling, Goblin Bomb Dispenser (bomb charges nearest enemy for 315-385 fire, 30-min CD), Goblin Dragon Gun (fire cone, 5-min CD), Goblin Mining Helmet (+5 Mining), Goblin Construction Helmet (+15 Fire Resist, 300-500 fire absorb, 1-hr CD), Rocket Helmet, Mortar, The Big One, Jumper Cables XL.", topic = "prof_bs_eng" }
add{ q = { "goblin sapper charge", "sapper charge recipe", "where to learn sappers", "can gnomish make sappers", "sapper charge", "goblin sapper", "sappers", "sapper recipe", "where do i learn goblin sapper charge", "sapper charge mats", "can gnomish engineers make sappers", "sapper charge forever", "how do i make sapper charges", "can i make sappers as gnomish" }, a = "Goblin Sapper Charge: Engineering 205 trainer recipe (listed unchanged in Forever). Mats: 1 Mageweave Cloth, 3 Solid Blasting Powder, 1 Unstable Trigger. It blasts all nearby enemies with heavy fire damage and hurts you too; using it needs Engineering 205. In Classic only Goblin engineers could craft it, so Gnomish engineers bought them. Top AoE and PvP burst item.", topic = "prof_bs_eng" }
add{ q = { "goblin jumper cables", "where do jumper cables drop", "jumper cables schematic forever", "battle res engineer", "jumper cables", "jumper cables schematic", "engineer battle rez", "jumper cables gnomeregan", "jumper cables mats", "how do i get jumper cables", "wher do goblin jumper cables drop", "how do engineers battle rez" }, a = "Schematic: Goblin Jumper Cables (skill 165) drops from Mekgineer Thermaplugg in Gnomeregan (~2%). Mats: 6 Iron Bar, 2 Whirring Bronze Gizmo, 2 Flask of Oil, 2 Silk, 2 Shadowgem. It tries to revive a dead player (can fail); engineers only. Jumper Cables XL is the better Goblin-only version.", topic = "prof_bs_eng" }
add{ q = { "gnomish battle chicken", "battle chicken", "battle squawk", "is battle chicken worth it", "is battle chicken good", "battle chicken recipe", "battle chicken raid buff", "how do i make battle chicken", "battle chicken forever", "is the gnomish battle chicken worth it in raids", "how do i get battle chicken" }, a = "Gnomish Battle Chicken: trainer recipe at Engineering 230, Gnomish only, BoP. Summons a combat chicken for 1.5 min (20-min CD) that can proc Battle Squawk, a party-wide attack speed buff. Classic raiders stacked several Gnomish melee for multiple chickens since it only hits the party.", topic = "prof_bs_eng" }
add{ q = { "gnomish mind control cap", "mind control cap", "mc cap engineering", "mc cap", "mind control cap recipe", "is mind control cap good pvp", "mind control cap skill", "how do i get mind control cap", "mc cap forever", "how do i get the mind control cap", "is mc cap good in pvp" }, a = "Gnomish Mind Control Cap: Gnomish trainer recipe at Engineering 235. On use it tries to mind control a humanoid target for a short time, and it can fail or backfire. The Forever gnome racial lowers device backfire chance by 20%, which pairs nicely with it. Warcraft Tavern names it the signature Gnomish device.", topic = "prof_bs_eng" }
add{ q = { "mechanical squirrel", "mechanical squirrel schematic", "engineering pet squirrel", "mechanical squirrel box", "squirrel pet engineering", "where do i get mechanical squirrel schematic", "mechanical squirrel skill up", "engineering squirrel pet", "mechanical squirrel recipe", "squirrel box schematic", "wher do i get mechanical squirrel schematic", "how do i get the squirrel pet" }, a = "Mechanical Squirrel Box: old schematic at Engineering 75, from a drop (unchanged in Forever). Makes a non-combat pet; also a cheap skill-up around 75.", topic = "prof_bs_eng" }
add{ q = { "mechanical chicken", "how do i get mechanical chicken", "oox chicken pet", "mechanical chicken pet", "an oox of your own", "how to get mechanical chicken", "oox chicken", "is mechanical chicken engineering", "oox quest chain chicken", "where do i get the mechanical chicken pet", "how do i get the mechanical chicken pet", "is the mechanical chicken made by engineers" }, a = "The Mechanical Chicken isn't an engineering craft. Classic baseline: it's the reward for 'An OOX of Your Own', the last quest of Oglethorpe Obnoticus's homing robot chain (Booty Bay) - find and escort the OOX robots in Tanaris, Feralas and the Hinterlands, then return to Oglethorpe. Not confirmed for Forever.", src = "classic", topic = "prof_bs_eng" }
add{ q = { "field repair bot", "field repair bot 74a", "how to get repair bot engineering", "portable repair forever", "repair bot 74a", "portable repair bot", "how do i get field repair bot", "field repair bot schematic", "repair bot engineering", "can engineers repair anywhere", "field repair bot forever", "how do i get a repair bot as engineer", "can i repair in the field with engineering" }, a = "Two options: Field Repair Bot 74A is still a 300 Engineering schematic in Forever (source not listed yet). Easier: the new camp Repair Bot blueprint at skill 140 lets you place a repair bot at your campfire (shares the 1-hour camp cooldown); wow.gg lists it from Happy Camper in Dun Morogh.", topic = "prof_bs_eng" }
add{ q = { "engineering scopes", "sniper scope", "deadly scope", "biznicks accurascope", "best hunter scope", "best scope", "accurascope", "biznicks scope", "best scope for hunter forever", "where do i get sniper scope schematic", "whats the best scope for my hunter", "wher do i get sniper scope" }, a = "Scopes in Forever: Standard/Accurate early, Deadly Scope (Engineering 210, vendor), Sniper Scope (240, drop), Biznicks 247x128 Accurascope (300, drop - Classic: Molten Core, +3% ranged hit), and the new SAF-T Ultra Precision Scope (300). Hunters want Biznicks for raiding.", class = "HUNTER", topic = "prof_bs_eng" }
