add{ q = { "rough dynamite changed", "rough dynamite forever", "rough dynamite recipe", "rough dynamite", "rough dynamite mats", "rough dynamite blasting powder", "how many sticks rough dynamite", "rough dynamite 2 sticks", "what changed with rough dynamite", "how much blasting powder for rough dynamite" }, a = "Forever changed Rough Dynamite: it now needs only 1 Rough Blasting Powder (instead of 2) and makes 2 sticks.", topic = "prof_bs_eng" }
add{ q = { "engineering beta level 30", "what engineering items can i make at 30", "engineering spec level", "what level for gnomish", "what level for goblin", "engineering at level 30", "engineering spec requirements", "engi spec level", "can i spec engineering at 30", "engineering 200 level requirement", "what level do i need for gnomish engineering", "can i spec engineering at level 30" }, a = "You can pick Gnomish or Goblin at Engineering 200 and character level 30. Artisan training (to go past 225) needs level 35, Blacksmithing specs need level 40.", topic = "prof_bs_eng" }
add{ q = { "HOW DO I GET MY ENGINEERING TO 300 FAST", "fastest engineering leveling forever", "engineering quick guide", "fast engineering", "engineering fast", "fastest engi leveling", "engi quick guide", "how to level engineering fast", "engineering 1-300 fast", "engi speed leveling", "quickest engineering route", "how do i level engineering fast", "fastest way to get engineering to 300" }, a = "1. Mine or buy: ~60 Rough, 60 Coarse, 30 Heavy, 120 Solid, 60 Dense Stone; ~66 Copper, 110 Bronze, 160 Mithril, 225 Thorium Bars; cloth (Linen, Wool, Mageweave, Runecloth).\n2. Powders/bolts 1-50, Arclight Spanner, Copper Bombs to 75.\n3. Coarse Powder/Dynamite, Bronze Tubes, Heavy Powder, Gizmos to 150.\n4. Framework, Sheep, Solid Powder, Mithril Tubes to 200, train Artisan from Buzzek (Gadgetzan).\n5. Unstable Triggers, Mithril Casings, Hi-Explosive Bombs to 250.\n6. Dense Powder, Thorium Widgets (Sovik/Gearcutter), Thorium Tubes (Xizzer, Everlook) to 300.", topic = "prof_bs_eng" }
add{ q = { "what blacksmith plans do i need to buy", "which bs recipes arent from trainer", "bs recipes to buy list", "bs plans to buy", "what bs recipes do i buy", "bs plans list", "which bs plans arent from trainer", "bs recipes not from trainer", "bs plans needed for leveling", "what bs recipes do i need", "what plans do i need for blacksmithing", "what bs plans do i need to buy", "which blacksmithing recipes do i need for leveling" }, a = "For the standard route you only need: Imperial Plate Belt/Bracers/Boots/Leggings plans (quests from Derotain Mudsipper, Gadgetzan, ~140 Thorium in turn-ins). Optional upgrades: Mithril Plate Bracers (Harggan, Hinterlands), Ebon Shiv (Magnus Frostwake, WPL), Mithril Spurs (world drop/AH). Everything else is trainer-taught.", topic = "prof_bs_eng" }
add{ q = { "forever bs anvil needed", "where is an anvil", "craft anywhere blacksmith", "anvil", "anvil needed", "do i need an anvil", "craft anywhere bs", "camp anvil", "anvil location", "bs anvil", "do i need an anvil to craft", "wher is the nearest anvil" }, a = "Most armor and weapons need an Anvil (any town forge, or your own camp Anvil from skill 140 / Master Forge at 300). Sharpening stones, weightstones, grinding stones, most reagents and camp features can be crafted anywhere.", topic = "prof_bs_eng" }
add{ q = { "repair bot happy camper", "where buy repair bot blueprint", "camping vendor engineering", "repair bot blueprint", "happy camper", "where to buy repair bot", "camping vendor", "repair bot camp blueprint", "happy camper dun morogh", "repair bot vendor", "where is happy camper", "wher do i buy the repair bot blueprint", "who sells the repair bot camp blueprint" }, a = "The Repair Bot camp blueprint (Engineering 140) is listed as sold by Happy Camper in Dun Morogh; other lists show it as a drop. Place it at a campfire to repair gear in the field (1-hour shared camp cooldown).", topic = "prof_bs_eng" }
add{ q = { "what is camping in wow forever", "camping profession", "how does camping work", "what is camping", "is camping a profession", "camping forever", "what is the camp system", "how do camps work in forever", "whats this campfire thing everyone is doing", "camping explained", "do i need to learn camping", "new camping system wow forever", "is camping its own skill or part of professions", "how does camping work wat do i need", "camping system how" }, a = "Camping is a new Forever system, not a separate skill. Someone drops a campfire (made with Cooking), then each nearby player can place one camp object made with their own profession. Sit at the fire about a minute and everyone gets 'Camp Benefits' for 1 hour: the combined buffs of all objects placed (Stamina, Strength, crit, rested XP, etc.). Camp buffs are a bit weaker than class buffs and don't stack with them.", topic = "prof_crafting" }
add{ q = { "camping 101 fishing", "lee brown camping quest", "camping 101 fishing lee brown goldshire", "learn to craft a camping item fishing", "how do i do camping 101 fishing", "lee brown quest", "where is lee brown", "camping 101 fishing quest help", "how do i finish camping 101 fishing", "fishing camping quest goldshire", "cant find lee brown for the fishing camp quest", "camping 101 fishing elwynn", "crystal lake fishing trainer camping quest", "wher is lee brown for camping 101 fishing" }, a = "1. Lee Brown is the Fishing trainer on the pier at Crystal Lake, just east of Goldshire (Elwynn 47.5, 62.3).\n2. Train Fishing from him if you haven't, and buy a Fishing Pole (Tharynn Bouden in Goldshire sells poles and Shiny Baubles).\n3. Like the other Camping 101 quests, the goal is to reach skill 20 in the profession; fish in Crystal Lake until Fishing hits 20.\n4. Turn in to learn the Fish Bowl camp item: 1 Raw Brilliant Smallfish + 1 Empty Vial. Placed at a campfire it gives +8% all stats (a weaker Blessing of Kings).", topic = "prof_crafting" }
add{ q = { "camping 101 quest", "what are the camping 101 quests", "camping 101 first aid", "camping 101 tailoring", "camping 101 leatherworking", "camping 101", "camping 101 quests list", "which camping 101 quest should i do", "how many camping 101 quests are there", "camping 101 alchemy", "camping 101 mining", "do i have to do every camping 101 quest", "camping 101 lvl 6 quests", "what are all the camping 101 quests about" }, a = "Camping 101 is a set of level ~6 quests (one per profession) that follow The Great Outdoors. Each asks you to raise that profession to 20 and rewards its tier-1 camp object recipe plus 270 XP. Example: Camping 101: First Aid is turned in to Michelle Belle (Goldshire), Thamner Pol (Kharanos), Byancie (Dolanaar), Rawrk (Razor Hill), Nurse Neela (Brill) or Vira Younghoof (Bloodhoof). You can also just learn the tier-1 item from the trainer at 20.", topic = "prof_crafting" }
add{ q = { "how do i make a campfire", "basic campfire kit", "how to place a campfire", "make camp fire forever", "campfire kit how", "campfire", "how to build a campfire", "basic campfire", "where do i get basic campfire kit", "campfire recipe", "how do i put down a campfire", "how to make camp", "campfire kit recipe cooking", "how do i make a camp fire i have simple wood" }, a = "1. Learn Cooking from any Cooking trainer; the Basic Campfire Kit recipe comes with it at skill 1.\n2. Buy Simple Wood (about 38c, unlimited) from General Goods, Cooking Supply or Enchanting Supply vendors, and keep a Flint and Tinder in your bags (needed to craft).\n3. Open the Professions window (K) > Cooking and craft the kit from 1 Simple Wood.\n4. Use the kit from your bags outdoors and target the ground. You can't build in the middle of a settlement.\nTip: craft a stack ahead of time; kits can be traded to others.", topic = "prof_crafting" }
add{ q = { "simple wood where to buy", "where do i get simple wood", "simple wood vendor", "star wood where", "thick logs where", "simple wood", "who sells simple wood", "where to buy wood for campfire", "star wood", "thick logs", "wood vendor", "simple wood location", "where do i get logs for campfire", "wher do i buy simple wood" }, a = "Simple Wood: sold by General Goods, Cooking Supply and Enchanting Supply vendors in most towns, ~38 copper, unlimited, can't be gathered. Star Wood (for the Journeyman Campfire) is the old wand material sold by trade/enchanting supply vendors. Thick Logs (Expert Campfire) have no confirmed source in guides yet; check trade vendors and the AH.", topic = "prof_crafting" }
add{ q = { "campfire tiers", "journeyman campfire", "expert campfire", "how many items can a campfire hold", "upgrade campfire", "campfire upgrade", "better campfire", "journeyman vs expert campfire", "campfire sizes", "how many camp objects per fire", "campfire levels", "max items on a campfire", "how to get a bigger campfire", "how do i upgrade my campfire to journeyman" }, a = "Three campfire tiers, all from Cooking:\n- Basic: Cooking 1, 1 Simple Wood, holds 3 camp objects.\n- Journeyman: 1 Star Wood, holds 5. Blueprint drops from Lord Serpentis in Wailing Caverns; guides list the skill as 90 (some say 140).\n- Expert: 1 Thick Logs, holds 10. Blueprint drops from Slavecrusher Grox in Krol'dok Stronghold; needs Cooking 220 to use.\nA fire burns about 10 minutes and has a 5-minute placement cooldown.", topic = "prof_crafting" }
add{ q = { "how long do camp buffs last", "camp buff duration", "how do i get camp buffs", "camp buffs not working", "sit at campfire buff", "camp buff", "camp buffs", "camp benefits", "camp buff how long", "how long do i have to sit at campfire", "camp buffs not applying", "how to get the camp buff", "sit at campfire for buffs", "i sat at the fire but didnt get a buff why" }, a = "Sit (/sit) at the fire for about 1 minute; then you get Camp Benefits for 1 hour, combining every object's buff. A fire itself lasts ~10 minutes, but the buff keeps going after it burns out. Camp buffs don't stack with the matching class buff (e.g. First Aid Kit vs Power Word: Fortitude), so the stronger one wins. Higher-tier objects also carry the tier-1 buff of that profession.", topic = "prof_crafting" }
add{ q = { "camp object cooldown", "why cant i place my camp item", "camp item on cooldown", "how many camp items can i place", "one camp object per person", "camp item cooldown", "camp object limit", "cant place camp item", "camp item greyed out", "how many camp objects can i put", "why is my camp object on cooldown", "camp cooldown", "one camp item per player", "why cant i place another camp item it says on cooldown" }, a = "Each player can place only one camp object per fire, and placing one puts all your camp objects on a 1-hour cooldown. The fire's slot limit is 3/5/10 depending on tier, so you need several players with different professions to fill it. Upgrading to a higher tier of the same profession's object replaces the lower one without using another slot and ignores the cooldown.", topic = "prof_crafting" }
add{ q = { "list of camp buffs", "what buff does each profession give at camp", "camp buffs per profession", "camping buffs list", "best camp buffs", "camp buffs list", "all camp buffs", "what does each camp item do", "profession camp buffs", "camp buff by profession", "which profession gives best camp buff", "what camp buff does alchemy give", "camping buffs per prof", "what buffs can i get from camping" }, a = "Tier-1 camp buffs (skill 20): Alchemy Mana Well = mana regen; Blacksmithing Sharpening Wheel = Strength; Enchanting Enchanted Lute = stats + resistances; Engineering Reagent Bot = reagent vendor; First Aid Kit = Stamina; Fishing Fish Bowl = +8% stats; Herbalism Incense Candle = Intellect; Leatherworking Camp Tent = rested XP; Mining Lodestone = melee AP; Skinning Camp Chair = +2% crit; Tailoring Faction Banner = Spirit. Cooking makes the fire itself.", topic = "prof_crafting" }
add{ q = { "tailoring camp item", "faction banner", "spinning wheel", "loom tailoring camping", "tailor camp object", "tailoring camp", "tailor camp item", "faction banner camp", "spinning wheel camp", "loom camp", "what camp stuff do tailors get", "tailoring camping buff", "loom tailoring", "what camp items can tailors make" }, a = "Tailoring camp objects:\n- Faction Banner (skill 20): Spirit buff for your faction, like Divine Spirit. 1 Bolt of Linen Cloth + 1 Coarse Thread; trainer or Camping 101.\n- Spinning Wheel (140): workstation for some tailoring materials. 2 Simple Wood, 5 Bolt of Silk, 3 Fine Thread. Blueprint from the Unstable Sentinel in Dalaran.\n- Loom (300): needed for some high-end patterns. 1 Bottled Screams, 4 Bolt of Runecloth, 4 Simple Wood. Blueprint from Baroness Anastari, Stratholme.", topic = "prof_crafting" }
add{ q = { "leatherworking camp item", "camp tent", "tanning rack", "sewing machine", "lw camp object", "leatherworking camp", "lw camp item", "tanning rack camp", "sewing machine camp", "what camp stuff do leatherworkers get", "leatherworking camping buff", "lw camp tent", "what camp items can leatherworkers make" }, a = "Leatherworking camp objects:\n- Camp Tent (20): instantly grants rested XP up to 5% of a level, once per hour (Boosted Rest debuff). 5 Light Leather.\n- Tanning Rack (125-140): workstation for some LW recipes (e.g. Skulker's pieces). 5 Medium Leather, 3 Fine Thread, 2 Simple Wood. Blueprint from Razorclaw the Butcher, Shadowfang Keep.\n- Sewing Machine (300): needed for some top patterns like Blue Suede Hat. 1 Undeath Engine, 5 Rugged Leather, 1 Rune Thread. Blueprint from Vectus, Scholomance.", topic = "prof_crafting" }
add{ q = { "first aid camp item", "first aid kit camp", "toxin study", "plague doctor's laboratory", "first aid camping", "first aid camp", "first aid kit camp item", "plague doctors laboratory", "what camp stuff does first aid get", "first aid camping buff", "fa camp item", "first aid kit stamina buff", "what camp items can first aid make" }, a = "First Aid camp objects:\n- First Aid Kit (20): Stamina buff, like Power Word: Fortitude. 3 Linen Bandage + 1 Refreshing Spring Water.\n- Toxin Study (140): offers healing potions and anti-venom at camp. 1 Anti-Venom, 2 Mageweave Bandage, 2 Simple Wood. Blueprint from Commander Springvale, Shadowfang Keep.\n- Plague Doctor's Laboratory (300): healing potions and poultices. 2 Simple Wood, 2 Strong Anti-Venom, 5 Heavy Runecloth Bandage. Blueprint from Doctor Theolen Krastinov, Scholomance.", topic = "prof_crafting" }
add{ q = { "cooking camp items", "cookie's feast", "iron oven", "cooking camping", "cooking camp", "cookies feast", "what camp stuff does cooking get", "cooking camp objects", "cooking camping buff", "iron oven camp", "cookie's feast buff", "what camp items can cooking make" }, a = "Cooking makes the campfires (Basic/Journeyman/Expert) plus two objects:\n- Cookie's Feast (140): Stamina food for everyone at camp. 2 Mystery Meat, 1 Heavy Kodo Meat, 1 Soothing Spices. Blueprint from Cookie in The Deadmines.\n- Iron Oven (300): workstation for the top cooking recipes. 10 Simple Flour, 5 Refreshing Spring Water, 4 Soothing Spices. One guide lists it as a Quartermaster Zigris (LBRS) drop, another as a trainer recipe.", topic = "prof_crafting" }
add{ q = { "fishing camp items", "fish bowl", "fishing rack", "fishing hut", "fishing camping", "fishing camp", "what camp stuff does fishing get", "fishing camp objects", "fishing camping buff", "fish bowl buff", "what camp items can fishing make" }, a = "Fishing camp objects:\n- Fish Bowl (20): +8% all stats, like a weaker Blessing of Kings. 1 Raw Brilliant Smallfish + 1 Empty Vial.\n- Fishing Rack (140): lures plus uncommon fish nearby for 1 hour. 2 Simple Wood, 1 Crystal Vial, 2 Raw Mithril Head Trout. Blueprint from Gelihast, Blackfathom Deeps (also fished from pools).\n- Fishing Hut (300): lures plus rare fish for 1 hour. 5 Simple Wood, 2 Bolt of Runecloth, 1 Seasonal Fish Steaks. Blueprint from Jammal'an, Sunken Temple.", topic = "prof_crafting" }
add{ q = { "other professions camp items", "alchemy camp item", "blacksmith camp item", "engineering repair bot camp", "mining camp item rock garden", "herbalism greenhouse", "mining camp", "rock garden", "greenhouse", "alchemy camp", "engineering camp", "other profession camp items", "herbalism camp item", "tier 2 camp items", "what camp items do mining and herbalism get" }, a = "Tier-2/3 highlights from other professions: Engineering Repair Bot (140, Sneed in Deadmines) repairs everyone at camp; Mining Rock Garden (140, Relic Guardian at the Wetlands excavation) spawns an ore node; Herbalism Greenhouse (140, Shadetooth, Wetlands) grows herbs from seeds; Skinning Field Guide (140, Lady Anacondra, WC) teaches Track Beasts; Blacksmithing Anvil (140, Gilnid, Deadmines). Tier-3s (300) are mostly workstations for endgame recipes.", topic = "prof_crafting" }
add{ q = { "do camp buffs stack with food", "stack xp buffs camping", "sleeping bag stack with camp", "max xp buffs forever", "do camp buffs stack", "stack xp buffs", "camp and food stack", "sleeping bag stacks with camp", "max xp buff", "how to stack xp buffs forever", "do xp buffs stack forever", "best xp buff stack", "can i stack camp buff food buff and sleeping bag" }, a = "Yes. Camp buffs, the Cozy Sleeping Bag's Well-Rested (+1% XP per minute lying, max +3%) and cooked food's Well Fed XP bonus (+5% kill XP) all stack. Eat while lying on the bag next to a fire with a Camp Tent placed to get everything at once. The sleeping bag also counts as a rested area, and it vanishes if you move ~100 yards away.", topic = "prof_crafting" }
add{ q = { "legacy talents camping", "field guide talent", "permanence talent", "reagent economy talent", "camping legacy talents", "field guide", "permanence", "reagent economy", "legacy talents for camp", "field guide legacy talent", "what does permanence do", "best legacy talents for camping", "what legacy talents help with camping" }, a = "Account-wide Legacy talents that help camping: Field Guide (Adventure tree) cuts the camp object placement cooldown (about 8%); Permanence (Resourcefulness) makes camp rest benefits last 50% longer; Reagent Economy (Resourcefulness) lets you craft tier-1 camp objects without materials.", topic = "prof_crafting" }
add{ q = { "camp tent rested xp", "how much xp does camp tent give", "boosted rest debuff", "camp tent not giving rested", "camp tent xp", "camp tent rested", "boosted rest", "how much rested xp from tent", "camp tent not working", "camp tent debuff", "does camp tent give rested xp", "camp tent cooldown", "why isnt my camp tent giving rested xp" }, a = "The Leatherworking Camp Tent gives rested XP equal to up to 5% of a level, but only if you don't already have that much rested stored. It then applies Boosted Rest, which blocks another tent refill for 1 hour. Quest-giver campfires (The Great Outdoors NPCs) always give this tent effect.", topic = "prof_crafting" }
add{ q = { "scarlet banner camping", "cosmetic camp item", "scarlet banner how to get", "scarlet banner", "cosmetic camp", "how to get scarlet banner", "scarlet banner camp item", "where do i get scarlet banner", "cosmetic camp objects", "scarlet banner drop", "scarlet banner forever", "how do i get the scarlet banner camp item" }, a = "The Scarlet Banner is the only cosmetic camp object so far. It isn't tied to a profession: you visit several zones and finish a puzzle inside Scarlet Monastery to get it.", topic = "prof_crafting" }
add{ q = { "where can i build a camp", "cant place campfire", "campfire won't place", "can i camp in town", "where to build camp", "campfire cant place", "cant put campfire", "camp in town", "camp location rules", "where can i camp", "campfire wont place here", "can i make camp inside a town", "why wont my campfire place" }, a = "Camps must be outdoors and not in the middle of a settlement. If the kit won't place, step outside town. Each fire has a 5-minute placement cooldown, so you can't drop fires back to back.", topic = "prof_crafting" }
add{ q = { "eating at campfire well fed", "camp food buff", "does camping refresh food", "food at campfire", "well fed camp", "camp food", "eating at camp", "does eating at camp give buff", "food xp camp", "well fed forever", "camp food buff xp", "do i get well fed from eating at the campfire" }, a = "Eating while seated for 10 seconds gives Well Fed, and cooked food in Forever also adds +5% XP from kills. Guides note camping also refreshes food buffs, and the Cooking object Cookie's Feast (140) hands out Stamina food to everyone at camp.", topic = "prof_crafting" }
add{ q = { "profession skill cap forever", "max profession skill forever", "is the cap 300", "profession ranks levels", "when can i train journeyman", "profession cap", "max skill professions", "profession max level", "professions cap 300", "profession ranks", "when can i train expert", "what level do i need for artisan", "whats the max skill for professions in forever", "whats the max profession skill" }, a = "Cap is 300 in Forever, in four ranks: Apprentice (to 75, level 5 for crafting/secondaries), Journeyman (to 150, needs level 10 and skill 50), Expert (to 225, level 20 and skill 125), Artisan (to 300, level 35 and skill 200). Train the next rank before you hit the cap or your skill-ups stop at 75/150/225. Secondaries (Cooking, First Aid, Fishing) use special quests/books for upper ranks.", topic = "prof_crafting" }
add{ q = { "merchants favor tailoring recipes", "mivin shadowweave", "daniel stitchsong", "commerce authority leatherworking patterns", "favor recipes cost", "favor recipes", "merchants favor recipes", "mivin", "favor vendor tailoring", "favor patterns leatherworking", "what can i buy with merchants favor", "favor recipe prices", "what recipes can i buy with merchants favor" }, a = "Profession vendors at the Commerce Authority hubs sell Forever patterns for 30-360 Favor, many gated by Friendly/Honored rep and skill. Tailoring: Mivin Shadowweave (Three Corners), 67 patterns, about 3,120 Favor for all. Leatherworking: Daniel Stitchsong (Three Corners), 81 patterns, about 4,620 Favor. Horde equivalents are at the Barrens hub (Jim'bek for tailoring bags).", topic = "prof_crafting" }
add{ q = { "profession title", "the tailor title", "the leatherworker title", "profession certification", "how to get crafting title", "profession titles", "crafting title", "tailor title", "leatherworker title", "certification", "how to get profession title", "profession certification cost", "title for maxing profession", "how do i get a profession title" }, a = "Buy a Profession Certification for 1,000 Merchant's Favor from the Commerce Authority (Redridge) or Durotar Supply (Barrens). It's one-time use and grants '[Name] the Tailor/Leatherworker' (also Alchemist, Blacksmith, Enchanter, Engineer) to every character of yours with 300 in that profession. No Cooking or First Aid title.", topic = "prof_crafting" }
add{ q = { "working overtime legacy", "dedicated study", "profession legacy talents", "faster profession leveling", "working overtime", "legacy talents professions", "profession legacy", "faster professions", "level professions faster", "what does dedicated study do", "best legacy talents for profs", "which legacy talents make professions faster" }, a = "Legacy Professions tree: Working Overtime raises skill-up chance on any tradeskill; Dedicated Study gives a free daily skill point to your lowest tradeskill (or 3 Elemental Essence once all at 300); Master Chef gives a chance at extra cooked food; Gourmand lengthens food buffs; Field Medicine shortens Recently Bandaged in the open world.", topic = "prof_crafting" }
add{ q = { "tailoring trainers", "where do i learn tailoring", "tailoring trainer stormwind", "tailoring trainer orgrimmar", "journeyman tailoring trainer", "tailoring trainer", "where is tailoring trainer", "tailor trainer", "tailoring trainer sw", "tailoring trainer org", "who trains tailoring", "journeyman tailor trainer", "tailoring trainer ironforge", "wher is the tailoring trainer" }, a = "Apprentice/Journeyman: Eldrin (Eastvale Logging Camp, Elwynn), Uthrar Threx (Great Forge, IF), Trianna (Darnassus), Snang (The Drag, Org), Vhan (Thunder Bluff), Bowen Brisboise (Cold Hearth Manor, Tirisfal), Skyborne: Othesia Evengale or Taleen Shimmerthread (Zephras Isle). Higher Journeyman/Expert: Sellandus or Georgio Bolero (Stormwind), Jormund Stonebrow (IF), Me'lynn (Darn), Magar (Org), Tepa (TB), Josef Gregorian/Rhiannon Davis (UC). Expert costs 50s.", topic = "prof_crafting" }
add{ q = { "tailoring 1-75", "tailoring 1-75 guide", "level tailoring beginning", "how to start tailoring", "tailoring 1 75", "start tailoring", "tailoring beginner", "linen leveling", "tailoring 1-75 forever", "new to tailoring what to make", "bolt of linen cloth", "tailoring apprentice guide", "just started tailoring what do i make 1-75" }, a = "Tailoring 1-75:\n1. Learn Apprentice (no level needed) and buy Coarse Thread from the nearby Tailoring Supply vendor (Brill: Abigail Shiel).\n2. 1-30: Bolt of Linen Cloth x30 (60 Linen). Keep the bolts.\n3. 30-55: Linen Belt x28 (28 bolts + 28 Coarse Thread). Heavy Linen Gloves also work.\n4. At 50 (level 10) train Journeyman before 75.\n5. 55-75: start Bolt of Woolen Cloth.\nDon't forget the Faction Banner camp item at 20 and the Linen Reagent Bag at 5.", topic = "prof_crafting" }
add{ q = { "tailoring 75-150", "tailoring 75 to 150", "tailoring journeyman guide", "tailoring 100-150", "tailoring 75 150", "journeyman tailoring", "tailoring 100", "woolen cloth leveling", "tailoring 75-150 forever", "what to make at 75 tailoring", "bolt of woolen cloth", "tailoring 125", "im 75 tailoring what do i make now" }, a = "Tailoring 75-150 (Journeyman):\n1. 55-80: Bolt of Woolen Cloth (you need ~153 bolts / 459 Wool total by 140).\n2. 80-95: Woolen Cape x22 (bolt + Fine Thread).\n3. 95-100: Double-stitched Woolen Shoulders x5.\n4. 100-120: Bolt of Silk Cloth x54 (4 Silk each).\n5. 120-140: Gloves of Meditation x29 (4 woolen bolts, 3 Fine Thread, 1 Elixir of Wisdom each). Alt: Azure Silk Hood, Lesser Wizard's Robe.\n6. 140-150: Bolt of Mageweave x23 after training Expert at 125 (level 20, 50s).", topic = "prof_crafting" }
add{ q = { "tailoring 150-225", "tailoring 150 to 225", "tailoring expert guide", "crimson silk vest leveling", "tailoring 150 225", "expert tailoring", "tailoring 175", "silk leveling", "tailoring 150-225 forever", "what to make at 150 tailoring", "crimson silk vest", "tailoring 200", "im 150 tailoring what now" }, a = "Tailoring 150-225 (Expert):\n1. 150-170: Crimson Silk Vest x20 (4 Silk bolts, 2 Red Dye, 2 Fine Thread each).\n2. 170-190: Crimson Silk Pantaloons x26 (4 Silk bolts, 2 Red Dye, 2 Silken Thread).\n3. 190-200: Black Mageweave Leggings x19 (2 Mageweave bolts, 3 Silken Thread).\n4. Train Artisan at 200 (Theramore or Tarren Mill).\n5. 200-205: Black Mageweave Shoulders x5.\n6. 205-215: Bolt of Runecloth x23.\n7. 215-225: Mageweave Bag x26 (sellable), or Runecloth Belts.", topic = "prof_crafting" }
add{ q = { "tailoring 225-300", "tailoring 225 to 300", "tailoring artisan guide", "runecloth leveling tailoring", "tailoring 250-300", "tailoring 225 300", "artisan tailoring guide", "runecloth leveling", "tailoring 250", "tailoring 225-300 forever", "runecloth belt leveling", "what to make at 225 tailoring", "tailoring 275", "just hit 225 tailoring whats the route to 300" }, a = "Tailoring 225-300 (Artisan):\n1. 225-240: Runecloth Belt x24 (3 Runecloth bolts + Rune Thread).\n2. 240-250: Runecloth Gloves x11 (pattern from Qia, Everlook, Winterspring) or Runecloth Cloak/Boots (Darnall, Moonglade).\n3. 250-280: Runecloth Cuffs (pattern from Pexmit, Mount Hyjal; BoP, yellow at 265) or Runecloth Headband.\n4. 280-300: Runecloth Shoulders, or Wisdom of the Timbermaw (Meilosh), or the Cenarion Circle Venomspew/Swarmtender gloves-cord-footpads (Mishta, Silithus). Those last ones need a Loom placed at camp.", topic = "prof_crafting" }
add{ q = { "tailoring materials list", "how much cloth for tailoring 1-300", "what cloth do i need to buy tailoring", "tailoring shopping list", "tailoring mats", "tailoring cloth needed", "how much cloth for tailoring", "tailoring mats list", "tailoring 1-300 mats", "how much runecloth for tailoring", "tailoring cost to 300", "cloth list tailoring", "how much cloth do i need to get tailoring to 300" }, a = "Rough 1-300 cloth (Forever route): ~60-120 Linen, ~450 Wool, ~740 Silk, ~800 Mageweave, ~1,500-2,300 Runecloth. Extras: ~29 Elixir of Wisdom, ~40 Rugged Leather, ~40-180 Ironweb Spider Silk, ~90 Red Dye. Threads from supply vendors: ~30 Coarse, ~160 Fine, ~160 Silken, ~10 Heavy Silken, ~75+ Rune Thread. Buy extra 5-10%; yellow recipes don't always skill up.", topic = "prof_crafting" }
add{ q = { "tailoring loom recipes", "venomspew requires loom", "why cant i craft swarmtender", "tailoring needs loom", "loom recipes", "loom needed", "why cant i craft venomspew", "swarmtender", "tailoring loom", "requires loom", "where do i find a loom", "tailoring patterns need loom", "why does my tailoring recipe say requires loom" }, a = "In Forever some top tailoring patterns (e.g. the Cenarion Circle Swarmtender's/Venomspew Gloves, Cord, Footpads from Mishta in Silithus, which need Friendly/Honored) require a Loom at a camp. You can only make your own Loom at 300, so before that find another tailor's camp with a Loom placed. Some Mooncloth-tier patterns also need the Loom.", topic = "prof_crafting" }
add{ q = { "tailoring bags forever", "reagent bag tailoring", "linen reagent bag", "best bag to craft", "tailoring reagent bags sizes", "tailoring bags", "reagent bag", "best bag tailoring", "reagent bag sizes", "reagent bag slot", "bags forever", "what bags can tailors make", "what reagent bags can tailors make" }, a = "Forever adds Reagent Bags (go in the dedicated reagent bag slot, hold only crafting mats), all BoE and tailor-only:\n- Linen 6 slots (skill 5), Woolen 8 (70): patterns from Tailoring Supply vendors.\n- Silk 10 (125): Gelkis/Magram quartermaster, Desolace.\n- Mageweave 12 (190) and Runecloth 14 (215): 60 Merchant's Favor each, Friendly with Commerce Authority.\n- Mooncloth 18 (255): Dala Fairmaw, Mount Hyjal, for Deadwood Tribal Beads at Honored.\n- Bottomless 20 (300): source unknown.\nRed Linen Bag is now 8 slots.", topic = "prof_crafting" }
add{ q = { "mooncloth", "how to make mooncloth", "mooncloth cooldown", "mooncloth moonwell", "mooncloth forever", "make mooncloth", "mooncloth cd", "mooncloth pattern", "qia everlook", "mooncloth recipe", "how long is mooncloth cooldown", "mooncloth moonwell forever", "how do i make mooncloth in forever" }, a = "Mooncloth: Pattern from Qia in Everlook, Winterspring (~2g10s, Tailoring 230 in Forever). Take 2 Felcloth to a moonwell (Moonglade, Teldrassil/Darnassus, or Felwood's corrupted wells) and craft. Cooldown is about 4 days (3.96 days in Forever). It's one of the best tailoring gold makers, ~25g profit per craft in early AH data.", topic = "prof_crafting" }
add{ q = { "felcloth farm", "where to farm felcloth", "felcloth drop", "felcloth", "felcloth farm spot", "best felcloth farm", "where does felcloth drop", "jadefire satyrs felcloth", "felcloth drop rate", "felcloth farming", "felwood felcloth", "wher is the best place to farm felcloth" }, a = "Felcloth drops from demons at a low rate (~1 in 15-20): Jadefire satyrs in Felwood (Jadefire Run), Legashi satyrs in northern Azshara, Felguards in the Blasted Lands near the Dark Portal, and demons in Dire Maul. (Classic locations, not yet checked for Forever.)", src = "classic", topic = "prof_crafting" }
add{ q = { "where to farm runecloth", "runecloth farm", "best runecloth spot", "where to get runecloth", "runecloth", "runecloth farming", "runecloth spot", "best place to farm runecloth", "where does runecloth drop", "runecloth farm forever", "runecloth drop", "runecloth dungeons", "wher is the best place to farm runecloth" }, a = "Runecloth (Classic spots): any humanoid in BRD, LBRS/UBRS, Dire Maul, Scholomance, Stratholme, ZG; Eastern/Western Plaguelands Scourge; Twilight cultists in Silithus; Deadwood furbolgs in Felwood; Winterfall furbolgs in Winterspring; Blood Elves and Legashi in Azshara; Blackrock orcs in Burning Steppes.", src = "classic", topic = "prof_crafting" }
add{ q = { "where to farm mageweave", "mageweave farm", "where to farm silk", "silk cloth farm", "wool farm", "mageweave", "silk", "wool", "mageweave spot", "silk spot", "wool spot", "best place for mageweave", "cloth farming spots", "wher do i farm mageweave" }, a = "Classic cloth spots: Wool: Stockade, Deadmines, Hillsbrad Syndicate, Westfall Defias. Silk: Scarlet Monastery, Desolace centaurs, Arathi Boulderfist/Syndicate, STV trolls. Mageweave: Sunken Temple, Uldaman, Tanaris Wastewander/Dunemaul, Feralas Gordunni, Hinterlands Witherbark, Felwood Jaedenar. Linen: Deadmines, RFC, Westfall Defias, Durotar Burning Blade.", src = "classic", topic = "prof_crafting" }
add{ q = { "robe of the archmage", "how to make robe of the archmage", "robe of the archmage pattern", "archmage robe", "robe of archmage", "robe of the archmage recipe", "robe of the archmage mats", "where does robe of the archmage drop", "archmage robe pattern", "robe of the archmage forever", "how do i get robe of the archmage pattern", "how do i make robe of the archmage" }, a = "Robe of the Archmage (Tailoring 295-300) is still in Forever. In Classic the pattern drops from Firebrand Pyromancers in Lower Blackrock Spire. Materials: 12 Bolt of Runecloth, 10 each Essence of Fire/Air/Earth/Water, 2 Rune Thread. It's BoP. Drop source not yet confirmed for Forever.", topic = "prof_crafting" }
add{ q = { "truefaith vestments", "how to make truefaith", "truefaith pattern", "priest robe crafted", "truefaith", "truefaith robe", "truefaith vestments recipe", "truefaith vestments pattern", "where does truefaith drop", "truefaith mats", "truefaith vestments forever", "priest crafted robe", "how do i make truefaith vestments" }, a = "Truefaith Vestments (Tailoring 295) carries over to Forever. Classic pattern drops from Balnazzar in Stratholme. Materials: 12 Bolt of Runecloth, 10 Mooncloth, 4 Righteous Orb, 4 Golden Pearl, 10 Ghost Dye, 2 Rune Thread. The 10 Mooncloth (about 4-day cooldown each) is the bottleneck.", src = "classic", topic = "prof_crafting" }
add{ q = { "best tailoring crafts", "tailoring bis", "what to craft with tailoring at 60", "tailoring endgame gear", "tailoring endgame", "best tailoring items", "tailoring bis items", "tailoring crafts", "best tailoring recipes", "what to make at 300 tailoring", "tailoring 60 crafts", "best crafted cloth", "what are the best things to craft with tailoring at 60" }, a = "Classic-era tailoring highlights still listed in Forever: Robe of the Archmage, Truefaith Vestments, Mooncloth pieces and Incandescent Mooncloth gear, Felcloth bags (Felcloth Bag, Core Felcloth Bag), Bottomless Bag, Wisdom/Mantle of the Timbermaw, Satchel of Cenarius. New at 300: Conviction, Demonheart and Manaflare pieces, Felblood Soul Bag and the Bottomless Reagent Bag.", topic = "prof_crafting" }
add{ q = { "tailoring gold making", "make gold with tailoring", "what to sell tailoring", "tailoring profit forever", "tailoring gold", "money tailoring", "tailoring money", "tailoring profit", "what tailoring stuff sells", "is tailoring good for gold", "tailoring gold forever", "tailoring ah", "how do i make gold with tailoring" }, a = "Best early Forever tailoring money (Nov 11 AH data): Mooncloth (~25g profit per cooldown), Mageweave Reagent Bag (~1g+ each), Silk Reagent Bag (~70s). Leveling-set pieces are BoP and can't be sold, and Blizzard cut vendor prices on some BoP crafted armor on Nov 10. Pair with Enchanting to disenchant leftovers.", topic = "prof_crafting" }
add{ q = { "new tailoring recipes forever", "forever tailoring patterns", "stormsewn", "filigreed gown", "nightclaw druids tailoring", "new tailoring recipes", "forever tailoring", "nightclaw", "new tailoring patterns", "forever tailoring recipes", "tailoring new sets", "what new tailoring recipes are in forever" }, a = "Forever adds 160+ tailoring patterns. Examples: Stormsewn cords/cuffs/vests (skill 50-60, Friendly/Honored with the Nightclaw Druids), Filigreed Gowns (75, dungeon drops), coloured Boots (60), spell-power versions of Woolen Shoulders and Azure Silk Hood, Nether shoulders/cuffs (195-205), Novice Arcanist's/Ardent's Sash (50). Most use vanilla mats plus new dyes like Cerulean Dye.", topic = "prof_crafting" }
add{ q = { "skyborne tailoring trainer", "zephras isle tailoring", "tailoring trainer skyborne", "skyborne tailoring", "zephras tailoring", "othesia evengale", "taleen shimmer", "tailoring trainer zephras isle", "where to learn tailoring skyborne", "skyborne tailoring trainer location", "tailoring trainer valanaar", "wher do skyborne learn tailoring" }, a = "Skyborne on Zephras Isle learn Tailoring from Othesia Evengale (Valanaar) or Taleen Shimmerthread (Shen'dar Village). Later ranks use the normal faction trainers.", topic = "prof_crafting" }
add{ q = { "tailoring and enchanting", "best second profession with tailoring", "tailoring pair with", "tailoring enchanting", "tailoring pair", "tailoring second prof", "tailoring and what", "tailoring + enchanting", "best combo with tailoring", "tailoring with herbalism", "tailoring profession pairing", "what profession goes best with tailoring" }, a = "Tailoring needs no gathering (cloth drops from humanoids), so pair it with Enchanting to disenchant your crafted gear and leftovers, or with any money profession. Tailoring also makes your own reagent bags for free.", topic = "prof_crafting" }
add{ q = { "thread vendor", "where do i buy thread", "red dye vendor", "fine thread", "rune thread where", "thread", "buy thread", "red dye", "rune thread", "silken thread", "tailoring supplies vendor", "thread vendor location", "wher do i buy thread and dye" }, a = "Coarse, Fine, Silken, Heavy Silken and Rune Thread plus dyes are sold by the Tailoring Supply vendor beside most tailoring trainers. In Tirisfal buy from Abigail Shiel (Brill); in Elwynn try Tharynn Bouden (Goldshire). Rune Thread is sold by high-level trade vendors (e.g. Everlook).", topic = "prof_crafting" }
add{ q = { "leatherworking trainers", "where to learn leatherworking", "leatherworking trainer goldshire", "journeyman leatherworking trainer", "leatherworking trainer", "lw trainer", "where is leatherworking trainer", "where can i learn lw", "who trains leatherworking", "leatherworking trainer ironforge", "leatherworking trainer org", "journeyman lw trainer", "wher is the leatherworking trainer" }, a = "Apprentice: Adele Fielder (near Goldshire, Elwynn), Gretta Finespindle (IF), Nadyia Maneweaver (Teldrassil), Kamari (Org), Shelene Rhobart (SE of Brill), Chaw Stronghide (Bloodhoof), Skyborne: Emerii Tallgust or Indari Sunseam. Journeyman: Simon Tanner (SW), Fimble Finespindle (IF), Faldron (Darn), Karolek (Org), Arthur Moore (UC), Tarn (TB). Expert (past 130): Telonis (Darnassus) or Una (Thunder Bluff).", topic = "prof_crafting" }
add{ q = { "leatherworking 1-75", "leatherworking 1-75 guide", "how to start leatherworking", "lw 1-75", "leatherworking 1 75", "start leatherworking", "lw beginner", "lw 1-75 forever", "light leather leveling", "new to lw what to make", "leatherworking apprentice guide", "just started lw what do i make 1-75" }, a = "Leatherworking 1-75:\n1. Learn Apprentice. Buy Salt and Coarse Thread from the Leatherworking Supply vendor (Goldshire: Tharynn Bouden; Brill: Abigail Shiel).\n2. 1-30: Light Leather x35 (105 Ruined Leather Scraps).\n3. 30-55: Cured Light Hide x27 (Light Hide + Salt). Light Armor Kit also works.\n4. Train Journeyman at 50 (level 10).\n5. 55-75: Embossed Leather Gloves x21 (3 Light Leather, 2 Coarse Thread).\nMake the Camp Tent (5 Light Leather) at 20.", topic = "prof_crafting" }
add{ q = { "leatherworking 75-150", "leatherworking 75 to 150", "leatherworking journeyman guide", "lw 75-150", "leatherworking 75 150", "journeyman lw", "lw 100", "lw 75-150 forever", "medium leather leveling", "what to make at 75 leatherworking", "lw 125", "im 75 leatherworking what do i make now" }, a = "Leatherworking 75-150:\n1. 75-80: Medium Leather x8 (4 Light each).\n2. 80-90: Cured Medium Hide x10.\n3. 90-100: Fine Leather Belt x19 (keep 10).\n4. 100-115: Light Leather Pants x24 (10 Light Leather, Cured Light Hide, Fine Thread).\n5. 115-125: Dark Leather Belt x10 (Fine Leather Belt + Cured Medium Hide + Gray Dye).\n6. 125-130: Heavy Leather x7; train Expert (125, level 20, 50s).\n7. 130-143: Cured Heavy Hide x30 (keep 30).\n8. 143-155: Hillman's Leather Gloves x17.", topic = "prof_crafting" }
add{ q = { "leatherworking 150-225", "leatherworking 150 to 225", "leatherworking expert guide", "lw 150-225", "leatherworking 150 225", "expert lw", "lw 175", "lw 150-225 forever", "heavy leather leveling", "barbaric shoulders", "what to make at 150 lw", "im 150 leatherworking what now" }, a = "Leatherworking 150-225:\n1. 155-165: Barbaric Shoulders x10 (8 Heavy Leather + Cured Heavy Hide).\n2. 165-185: Guardian Gloves x20 (4 Heavy Leather, Cured Heavy Hide, Silken Thread).\n3. 185-195: Barbaric Harness x16 (14 Heavy Leather, 2 Fine Thread, Iron Buckle).\n4. 195-205: Nightscape Headband x12 (5 Thick Leather). Train Artisan at 200.\n5. 205-235: Nightscape Pants x36 (14 Thick Leather, 4 Silken Thread). Thick Armor Kits are a cheap alternative early on.", topic = "prof_crafting" }
add{ q = { "leatherworking 225-300", "leatherworking 225 to 300", "leatherworking artisan guide", "rugged leather leveling", "lw 225-300", "leatherworking 225 300", "artisan lw guide", "lw 250", "lw 225-300 forever", "nightscape pants leveling", "wicked leather gauntlets leveling", "what to make at 225 lw", "just hit 225 lw whats the route to 300" }, a = "Leatherworking 225-300:\n1. 205-235: Nightscape Pants.\n2. 235-265: Wicked Leather Gauntlets x36 (8 Rugged Leather, Black Dye, Rune Thread). Pattern: Werg Thickblade (Tirisfal) or Leonard Porter (Western Plaguelands). Blue Suede Shoes is an alternative.\n3. 265-300: Runic Leather Headband x53 (14 Rugged, 10 Runecloth, Rune Thread); pattern from Jase Farlane, Light's Hope Chapel. Heavy Scorpid Bracers/Helm (Zannok Hidepiercer, Silithus) also work. Blue Suede Hat at 280 needs a Sewing Machine at camp.", topic = "prof_crafting" }
add{ q = { "leatherworking materials list", "how much leather for leatherworking 1-300", "what leather do i need to buy", "leatherworking shopping list", "lw mats", "leatherworking mats", "how much leather for lw", "lw mats list", "lw 1-300 mats", "how much rugged leather for lw", "leatherworking cost to 300", "leather list lw", "how much leather do i need to get lw to 300" }, a = "Approx 1-300 (Forever route): 105 Ruined Leather Scraps, ~415 Light Leather, 27 Light Hide, ~265 Medium Leather, 10 Medium Hide, 30 Heavy Hide, ~380 Heavy Leather, ~560 Thick Leather, ~1,030 Rugged Leather, 530 Runecloth, 16 Iron Buckle. Vendor mats: ~127 Salt, ~80 Coarse, ~165 Fine, ~190 Silken, ~90 Rune Thread, 10 Gray Dye, 36 Black Dye. Skinning alongside saves a fortune.", topic = "prof_crafting" }
add{ q = { "leatherworking specialization", "which leatherworking spec", "dragonscale vs tribal vs elemental", "lw spec forever", "lw spec", "leatherworking spec", "dragonscale tribal elemental", "which lw spec", "best lw spec", "tribal vs dragonscale", "elemental leatherworking", "best leatherworking spec forever", "which leatherworking spec should i pick" }, a = "At Leatherworking 225 and level 40 you pick one specialization:\n- Tribal: leather agi/int gear, Devilsaur set, Wolfshead Helm, Hide of the Wild, Warbear/Ironfeather sets.\n- Dragonscale: mail gear in Green (healer), Blue (caster) and Black (physical) lines, e.g. Black Dragonscale pieces, Chromatic Gauntlets.\n- Elemental: Gauntlets of the Sea, Helm of Fire, Living set, Volcanic/Stormshroud, Shifting Cloak.\nForever removed many resistance stats from these sets in favour of role-based stats.", topic = "prof_crafting" }
add{ q = { "tribal leatherworking how", "how to become tribal", "tribal leatherworking quest", "wild leather quests", "tribal lw", "tribal spec", "tribal quest", "become tribal", "tribal leatherworking forever", "pratt mcgrubben", "jangdor swiftstrider", "wild leather", "how do i become a tribal leatherworker" }, a = "Tribal (LW 225, level 40):\n1. In Feralas talk to Pratt McGrubben (Alliance, Feathermoon) or Jangdor Swiftstrider (Horde, Camp Mojache). Do the Wild Leather chain: Armor, Vest, Shoulders, Leggings, Helmet, Boots, then Master of the Wild Leather.\n2. Buy Pattern: Turtle Scale Gloves from them.\n3. Finish Master of the Wild Leather with Telonis (Darnassus) or Una (Thunder Bluff).\n4. Craft a Wild Leather Vest and Helmet and hand them to the Tribal trainer: Caryssia Moonhunter (Feralas) or Se'Jib (Stranglethorn).\nMats: ~214 Thick Leather, 112 Turtle Scale, 11 Wildvine, 2 Cured Thick Hide.", topic = "prof_crafting" }
add{ q = { "dragonscale leatherworking how", "how to become dragonscale", "dragonscale quest", "dragonscale lw", "dragonscale spec", "become dragonscale", "dragonscale leatherworking quest", "dragonscale forever", "scorpid scale dragonscale quest", "how do i get dragonscale leatherworking", "dragonscale requirements", "how do i become a dragonscale leatherworker" }, a = "Dragonscale (LW 225, level 40):\n1. Get 36 Thick Leather, 40 Scorpid Scale, 12 Silken Thread, 10 Worn Dragonscale.\n2. Craft 2 Tough Scorpid Breastplate and 2 Tough Scorpid Gloves (patterns drop from Wastewander Bandits/Thieves in Tanaris, or AH).\n3. Alliance: Peter Galen, Ruins of Eldarath, Azshara (~37.6, 65.4). Horde: Thorkaf Dragoneye, Badlands (~62.6, 57.6). Turn in for the Dragonscale quest.", topic = "prof_crafting" }
add{ q = { "elemental leatherworking how", "how to become elemental leatherworker", "elemental lw quest", "elemental lw", "elemental spec", "become elemental", "elemental leatherworking quest", "elemental forever", "globe of water elemental lw", "how do i get elemental leatherworking", "elemental lw requirements", "how do i become an elemental leatherworker" }, a = "Elemental (LW 225, level 40): bring 2 Globe of Water, 2 Heart of Fire, 2 Core of Earth and 2 Breath of Wind to Sarah Tanner in Searing Gorge (~63.6, 75.8, Alliance) or Brumn Winterhoof in Arathi Highlands (~28.2, 45.0, Horde) and do the Elemental Leatherworking quest.", topic = "prof_crafting" }
add{ q = { "devilsaur set", "devilsaur gauntlets", "devilsaur leggings", "how to make devilsaur", "devilsaur pattern", "devilsaur", "devilsaur gloves", "devilsaur pants", "devilsaur set forever", "devilsaur recipe", "devilcore gauntlets", "devilsaur mats", "where to get devilsaur pattern", "how do i make devilsaur gauntlets in forever" }, a = "Devilsaur Gauntlets and Leggings are still in Forever (plus SoD-style Devilcore Gauntlets/Leggings as drops). Classic sources: Pattern: Devilsaur Gauntlets (290) sold by Nergal at Marshal's Stand, Un'Goro; Devilsaur Leggings (300) dropped by Un'Goro oozes. Mats: Gauntlets 8 Devilsaur Leather + 30 Rugged Leather + Rune Thread; Leggings 14 Devilsaur Leather + Cured Rugged Hide + Rune Thread. In Classic they needed Tribal; Forever lists them under Tribal.", src = "classic", topic = "prof_crafting" }
add{ q = { "onyxia scale cloak", "how to make onyxia scale cloak", "ony cloak nefarian", "onyxia cloak pattern", "ony cloak", "onyxia cloak", "onyxia scale cloak recipe", "ony scale cloak", "nef cloak", "onyxia scale cloak mats", "do i need ony cloak for bwl", "shadow flame cloak", "how do i make onyxia scale cloak for bwl" }, a = "Onyxia Scale Cloak protects from Nefarian's Shadow Flame in BWL. Classic: after killing Onyxia and turning in her head, a follow-up teaches the leatherworker the pattern. Mats include a Scale of Onyxia (skinned once per kill) and a Cindercloth Cloak from a tailor. It exists in Forever's pattern list but its Forever source isn't confirmed.", src = "classic", topic = "prof_crafting" }
add{ q = { "leatherworking bis crafts", "best leatherworking crafts", "lw endgame items", "best lw crafts", "lw bis", "leatherworking endgame", "best leatherworking items", "lw 300 crafts", "what to make at 300 lw", "hide of the wild", "wolfshead helm", "what are the best things to craft with lw" }, a = "Notable LW crafts in Forever: Devilsaur and Devilcore gear, Hide of the Wild, Wolfshead Helm, Black Dragonscale and Hardened Black Dragonscale pieces, Chromatic Gauntlets, Shifting Cloak, Core Armor Kit, Onyxia Scale Cloak, plus a new Black Dragonscale Helm. New Forever armor kits: Forceful (melee AP) and Mystic (spell power) Medium/Heavy/Thick kits.", topic = "prof_crafting" }
add{ q = { "new leatherworking patterns forever", "forever lw sets", "brawler's set", "mender's set", "skulker's set", "new lw patterns", "new leatherworking sets", "brawlers set", "menders set", "skulkers set", "lw leveling sets", "commerce authority lw sets", "what new leatherworking sets are in forever" }, a = "Forever adds 13 crafted leveling sets from the Commerce Authority leatherworking vendor in Redridge: Brawler's, Defender's, Mender's, Prowler's, Skirmisher's, Skulker's, Skycaller's, Stalker's, Stormrider's, Totemic, Trapper's, Warden's and Wisdom's (leather and mail, role-based stats, BoE). Also upgraded armor kits and new mats like Fel Hide and Pristine Leather.", topic = "prof_crafting" }
add{ q = { "salt shaker", "refined deeprock salt", "cured rugged hide", "how to make refined salt", "deeprock salt", "refined salt", "how to refine deeprock salt", "salt shaker recipe", "refined deeprock salt how", "where to get salt shaker", "how do i refine deeprock salt" }, a = "Cured Rugged Hide needs Refined Deeprock Salt. Use a Salt Shaker on Deeprock Salt to refine it; the Shaker has a 3-day cooldown. Deeprock Salt drops from mobs and is sold on the AH; the Shaker is an Engineering craft that anyone can use.", topic = "prof_crafting" }
add{ q = { "leatherworking quivers", "ammo pouch", "hunter quiver craft", "light leather quiver", "quiver", "lw quiver", "hunter quiver", "heavy quiver", "can leatherworkers make quivers", "best quiver to craft", "can leatherworkers make quivers for my hunter" }, a = "LW makes hunter bags: Light Leather Quiver and Small Leather Ammo Pouch (25), Heavy Quiver and Heavy Leather Ammo Pouch (125), Thick Leather Ammo Pouch and Quickdraw Quiver (200), Scarlet Quiver/Ammo Pouch (275). Forever adds a Light Leather Reagent Bag (30, quest).", topic = "prof_crafting" }
add{ q = { "blue suede hat sewing machine", "why cant i craft blue suede hat", "sewing machine needed", "blue suede hat", "sewing machine", "blue suede hat requires sewing machine", "sewing machine recipe", "how to craft blue suede hat", "sewing machine camp", "blue suede hat lw 280", "cant make blue suede hat", "why cant i craft the blue suede hat" }, a = "Blue Suede Hat (from 280) needs a Sewing Machine placed at a camp. You can only craft a Sewing Machine at LW 300 (blueprint from Vectus, Scholomance), so before that you must use another leatherworker's machine at their camp.", topic = "prof_crafting" }
add{ q = { "leatherworking gold making", "make money leatherworking", "what to sell leatherworking", "lw gold", "leatherworking gold", "lw money", "leatherworking profit", "what lw stuff sells", "is lw good for gold", "leatherworking gold forever", "lw ah", "how do i make gold with leatherworking" }, a = "Leatherworking crafts in Forever are mostly BoE (sets, armor kits, quivers), so they can be sold. Higher-value items are Devilsaur pieces, armor kits for leveling players and ammo pouches/quivers. Pair with Skinning to avoid buying leather.", topic = "prof_crafting" }
add{ q = { "where to farm rugged leather", "rugged leather farm", "devilsaur leather farm", "thick leather farm", "rugged leather", "rugged leather spot", "devilsaur leather", "thick leather", "best place for rugged leather", "leather farming spots", "where to farm devilsaur", "thick leather spot", "wher do i farm rugged leather" }, a = "Classic leather spots: Thick Leather from Feralas, Hinterlands and Tanaris beasts. Rugged Leather from Winterspring, Un'Goro, Felwood and Burning Steppes beasts. Devilsaur Leather from devilsaurs in Un'Goro Crater (watch for other skinners). Heavy Scorpid Scale from Silithus and Burning Steppes scorpids. Not yet confirmed for Forever.", src = "classic", topic = "prof_crafting" }
add{ q = { "first aid forever changes", "first aid healing potions", "can first aid make healing potions", "first aid new recipes", "first aid changes", "first aid forever", "first aid potions", "fa changes", "first aid new", "does first aid make potions", "first aid reworked", "what changed with first aid in forever" }, a = "Big Forever change: First Aid now makes healing potions (moved from Alchemy), along with bandages, poultices (cure disease), tourniquets (cure bleeds) and anti-venoms. Potions use an herb + spices + vial. Recipes are grouped as Bandages, Healing Potions and Curatives in the Professions window (K). Curatives can't be used in combat; potions can.", topic = "prof_crafting" }
add{ q = { "first aid healing potion recipes", "what herbs for first aid potions", "minor healing potion first aid", "major healing potion first aid", "first aid potions", "first aid potion recipes", "healing potion first aid", "minor healing potion", "major healing potion", "first aid herbs", "which herbs for first aid", "first aid potion mats", "what herbs do i need for first aid potions" }, a = "First Aid potions (skill per kami-labs): Minor (~55) Peacebloom + Mild Spices + Empty Vial; Lesser (~85) Briarthorn + 2 Mild Spices; Healing (~135) Bruiseweed + Hot Spices + Leaded Vial; Greater (155) with 3 Hot Spices; Superior (215) Sungrass + Soothing Spices; Major (275) Golden Sansam + 3 Soothing Spices. Spices from Cooking Supply vendors, vials from trade vendors.", topic = "prof_crafting" }
add{ q = { "poultice", "tourniquet", "cure disease first aid", "cure bleed first aid", "anti-venom forever", "cure disease", "cure bleed", "anti venom", "first aid cures", "first aid curatives", "first aid poison cure", "how do i cure diseases with first aid" }, a = "Forever First Aid curatives: Poultices cure diseases - Simple (90, up to level 25), Clever (140, 35), Superior (210, 45), Powerful (280, 65). Tourniquets cure bleeds - Woolen (120, 30), Leather (200, 45), Surgical (265, 65). Anti-venoms: Anti-Venom (80), Strong (130), new Potent (215), Powerful (300, changed). Not usable in combat.", topic = "prof_crafting" }
add{ q = { "first aid materials list", "what do i need for first aid 1-300", "first aid shopping list", "first aid mats", "fa mats", "first aid materials", "first aid mats list", "first aid shopping", "first aid cloth needed", "how much cloth for first aid", "first aid cost", "what do i need to buy to level first aid" }, a = "First Aid 1-300 shopping (approx): Linen 80-90, Wool ~100, Silk ~125-140, Mageweave ~90-105, Runecloth ~65-75, Peacebloom ~40, Bruiseweed ~20, plus vendor items ~40 Empty Vial, ~40 Mild Spices, ~20 Hot Spices, ~20 Leaded Vial. Vendor costs total only ~1.3g including recipes.", topic = "prof_crafting" }
add{ q = { "expert first aid", "under wraps book", "first aid 150", "where to buy expert first aid", "first aid stuck at 150", "under wraps", "first aid 150 cap", "first aid book", "first aid stuck 150", "where to buy under wraps", "expert first aid book location", "first aid capped at 150", "why is my first aid stuck at 150" }, a = "First Aid stops at 150 until you buy 'Expert First Aid - Under Wraps' (needs skill 125, no level req): Alliance from Deneb Walker in Stromgarde, Arathi Highlands (27.0, 58.8); Horde from Balai Lok'Wein in Brackenwall Village, Dustwallow Marsh. Buy the Heavy Silk Bandage and Mageweave Bandage manuals from the same vendor.", topic = "prof_crafting" }
add{ q = { "triage quest", "first aid 225", "artisan first aid", "how to do triage", "doctor gustaf vanhowzen", "doctor gregory victor", "triage", "first aid 225 quest", "artisan first aid quest", "gustaf vanhowzen", "gregory victor", "triage quest location", "first aid stuck at 225", "how do i do the triage quest" }, a = "Triage (First Aid 225, level 35) unlocks 300:\n1. Alliance: Doctor Gustaf VanHowzen, Theramore, Dustwallow Marsh (67.6, 48.8). Horde: Doctor Gregory Victor, Hammerfall, Arathi Highlands.\n2. He gives you Triage Bandages. Save 15 patients in the tent before too many die.\n3. Bandage Critically Injured first, then Badly Injured, then Injured (worst first).\n4. Turn in right when you hit 15; waiting can fail it.\nThe doctor then teaches Heavy Mageweave and Runecloth Bandages.", topic = "prof_crafting" }
add{ q = { "first aid trainers", "where to learn first aid", "first aid trainer goldshire", "first aid trainer orgrimmar", "first aid trainer", "fa trainer", "where is first aid trainer", "first aid trainer sw", "first aid trainer org", "who trains first aid", "first aid trainer ironforge", "first aid trainer location", "wher is the first aid trainer" }, a = "First Aid trainers: Michelle Belle (Goldshire 43.4, 65.6), Shaina Fuller (Stormwind 42.4, 26.8), Nissa Firestone (IF 54.8, 58.4), Thamner Pol (Kharanos), Byancie (Dolanaar), Dannelor (Darnassus), Fremal Doohickey (Wetlands), Arnok (Org 34.0, 84.4), Rawrk (Razor Hill), Nurse Neela (Brill), Mary Edras (UC), Pand Stonebinder (TB), Vira Younghoof (Bloodhoof), Melasa Fairmend / Naleeia Tattermend (Zephras Isle).", topic = "prof_crafting" }
add{ q = { "major healing potion manual", "pexmit first aid", "first aid 275", "where to get major healing potion recipe first aid", "major healing potion first aid", "pexmit", "first aid 275 recipe", "major healing potion recipe", "where to buy major healing potion recipe", "pexmit hyjal", "major healing potion manual first aid", "wher do i get the major healing potion recipe for first aid" }, a = "The Major Healing Potion recipe for First Aid (275) is sold by Pexmit in Mount Hyjal and also comes as a quest reward there. Mats: Golden Sansam, 3 Soothing Spices and a vial.", topic = "prof_crafting" }
add{ q = { "first aid herbalism", "best profession with first aid", "first aid pair herbalism", "first aid and herbalism", "first aid herb", "best prof with first aid", "first aid pair", "first aid herbalism combo", "first aid with herbalism", "first aid and alchemy", "what goes with first aid", "should i take herbalism with first aid" }, a = "Since First Aid makes healing potions in Forever, Herbalism pairs well with it (Peacebloom, Briarthorn, Bruiseweed, Sungrass, Golden Sansam). First Aid is a secondary profession, so it doesn't use a primary slot.", topic = "prof_crafting" }
add{ q = { "recently bandaged", "field medicine", "bandage cooldown", "bandage debuff", "recently bandaged debuff", "field medicine legacy", "how long is recently bandaged", "bandage cd", "why cant i bandage again right away" }, a = "Bandaging gives Recently Bandaged, which blocks another bandage for a short time. The Legacy talent Field Medicine shortens that debuff, but only in the open world. Bandages can be used on other players and pets.", topic = "prof_crafting" }
add{ q = { "cooking forever changes", "cooking xp buff", "does food give xp", "well fed xp forever", "cooking xp", "food xp", "well fed xp", "cooking forever", "cooking changes", "does food give xp in forever", "cooking xp buff forever", "does eating give more xp", "does food give bonus xp in forever" }, a = "In Forever, cooked food's Well Fed buff also gives +5% experience from kills (not quest XP). It stacks with camp buffs and the Cozy Sleeping Bag. Cooking also makes the campfires for Camping, and many old recipes were tweaked toward a single primary stat.", topic = "prof_crafting" }
add{ q = { "cooking meat route", "level cooking without fishing", "cooking with meat only", "cooking meat", "cooking no fishing", "meat only cooking", "cooking without fish", "cooking meat route forever", "level cooking with meat", "cooking meat leveling", "cooking without fishing route", "can i level cooking without fishing" }, a = "Meat-only route (kami-labs): 1-55 Brilliant Smallfish or starter meats, 55-90 Coyote Steak, 90-156 Dig Rat Stew (quest reward), 156-185 Lean Wolf Steak (pattern from Super-Seller 680, Desolace), 185-209 Plain Ol' Paletusk (new; 2 Chunk of Boar Meat + Mild Spices, from Martha Wellsworth, Riverglades), 209-225 Roast Raptor, then 225-250 Spotted Yellowtail and 250-300 Poached Sunscale Salmon (Gikkix, Tanaris).", topic = "prof_crafting" }
add{ q = { "artisan cooking", "clamlette surprise", "cooking 225", "dirge quikcleave", "cooking stuck at 225", "cooking stuck 225", "artisan cooking quest", "cooking artisan", "cooking 225 quest", "how do i get artisan cooking", "im 225 cooking how do i get artisan", "clamlette surprise quest dirge gadgetzan" }, a = "Artisan Cooking (Cooking 225, level 35):\n1. Pick up the Gadgetzan travel quest from Daryl Riknussun (Ironforge) or Zamja (Orgrimmar).\n2. Collect 12 Giant Egg, 10 Zesty Clam Meat and 20 Alterac Swiss (cheese from inn/food vendors).\n3. Turn in Clamlette Surprise to Dirge Quikcleave in Gadgetzan, Tanaris. He teaches Artisan.\n4. While there, buy Spotted Yellowtail / Poached Sunscale Salmon recipes from Gikkix in Steamwheedle Port.", topic = "prof_crafting" }
add{ q = { "cooking trainers", "where to learn cooking", "cooking trainer stormwind", "cooking trainer orgrimmar", "cooking trainer", "where is cooking trainer", "cooking trainer sw", "cooking trainer org", "who trains cooking", "cooking trainer ironforge", "cooking trainer location", "where do i learn cooking", "wher is the cooking trainer" }, a = "City Cooking trainers: Stephen Ryback (Stormwind), Daryl Riknussun (Ironforge), Alegorn (Darnassus), Zamja (Orgrimmar), Aska Mistrunner (Thunder Bluff), Eunice Burch (Undercity). Every starting zone also has one, often beside a campfire. Shen'dar Village's cook Zerril Softbreeze teaches Skyborne.", topic = "prof_crafting" }
add{ q = { "cooking recipe vendors", "gikkix", "kelsey yance", "where to buy cooking recipes 250", "cooking recipes vendor", "cooking recipes 250", "where to buy cooking recipes", "cooking vendor recipes", "gikkix tanaris", "kelsey yance stv", "wher do i buy cooking recipes for 250+" }, a = "Key cooking recipe vendors: Gikkix, Steamwheedle Port, Tanaris (Spotted Yellowtail, Poached Sunscale Salmon, Grilled Squid, Nightfin Soup); Kelsey Yance, Booty Bay (Filet of Redgill, Mithril Head Trout); Vivianna (Alliance) / Sheendra Tallgrass (Horde) in Feralas (Baked Salmon, Lobster Stew, Mightfish Steak); Kendor Kabonka (Stormwind) and Nerrist (Grom'gol) for Curiously Tasty Omelet.", topic = "prof_crafting" }
add{ q = { "new cooking recipes forever", "smoothie recipes", "forever cooking new foods", "teas cooking", "new cooking recipes", "smoothies", "teas", "forever cooking", "new foods forever", "forever new cooking", "cooking new recipes forever", "what new cooking recipes are in forever" }, a = "Forever adds ~44 cooking recipes: dishes like Skywall Souffle, Tasty Raptor Bites, Twice-Spiced Raptor Slice, Savory Whimsyfin Delight (turns you into a murloc/ogre), Plated Armorfish, Raging Raptor Ribs, and a block of 275-skill dishes from the trainer (Swiftstrike Steak, Clam Linguine, Bear Bruscitti, etc.); teas (Peace, Royal, Root, Sunny, Sage's, Triage); and six Spirit smoothies.", topic = "prof_crafting" }
add{ q = { "smoothies merchants favor", "kalsey sanden", "aza'bek", "venomous smoothie", "smoothies favor", "azabek", "smoothie vendor", "favor smoothies", "spirit smoothies", "smoothies merchants favor recipes", "wher do i buy smoothie recipes" }, a = "Six Spirit smoothies (Venomous, Slimy, Mrrggl Smrrthle, Calcified, Spicy, Wicked; skill 25-250) are sold for 30-90 Merchant's Favor by Kalsey Sanden (Alliance, Redridge) and Aza'bek (Horde, The Barrens).", topic = "prof_crafting" }
add{ q = { "best buff food 60", "raid food", "best food for raid", "smoked desert dumplings", "grilled squid", "nightfin soup", "best food", "buff food", "best buff food", "raid buff food forever", "what is the best raid food", "what food should i bring to raids in forever", "best stamina food 60" }, a = "Classic raid foods still in Forever's list: Smoked Desert Dumplings (300, trainer in Forever; +Strength), Grilled Squid (240, Gikkix; +Agility), Nightfin Soup (250, Gikkix; mana regen), Runn Tum Tuber Surprise (275, Pusillin in Dire Maul, 100%; +Int), Dirge's Kickin' Chimaerok Chops (300, quest; +Stamina). Stats may differ in Forever since many foods were rebalanced.", src = "classic", topic = "prof_crafting" }
add{ q = { "cookie's stirring rod", "cook faster", "cooking speed item", "stirring rod", "cooking speed", "cookie stirring rod", "cookies stirring rod deadmines", "faster cooking item", "stirring rod drop", "how do i cook faster" }, a = "Cookie's Stirring Rod drops from Cookie in The Deadmines and makes you cook 25% faster while equipped. Cookie also drops the Cookie's Feast camp blueprint.", topic = "prof_crafting" }
add{ q = { "where do i cook", "cooking fire location", "do i need a fire to cook", "cooking fire", "where to cook", "fire to cook", "need fire to cook", "where do i cook food", "cant cook no fire", "cooking requires fire", "wher can i cook" }, a = "Cook at any fire: inns, cooking trainers' fires, or your own Basic Campfire (Simple Wood + Flint and Tinder). Higher campfires add camp slots but cook the same. Some top recipes need the Iron Oven camp object.", topic = "prof_crafting" }
add{ q = { "savory whimsyfin delight", "murloc transform food", "ogre transform food", "murloc food", "ogre food", "transform food", "murloc transform", "whimsyfin delight", "food that turns you into murloc", "transform food forever", "what food turns me into a murloc" }, a = "Savory Whimsyfin Delight (Cooking ~85) is a new Forever food that turns you into a Murloc or an Ogre for fun.", topic = "prof_crafting" }
add{ q = { "journeyman campfire blueprint", "lord serpentis campfire", "how to get journeyman campfire", "journeyman campfire", "lord serpentis", "serpentis wc", "journeyman campfire drop", "journeyman campfire wailing caverns", "upgrade to journeyman campfire", "how do i get the journeyman campfire" }, a = "Blueprint: Journeyman Campfire drops from Lord Serpentis in Wailing Caverns (The Barrens). It uses 1 Star Wood per kit and holds 5 camp objects. Guides list the skill as Cooking 90 (some say 140).", topic = "prof_crafting" }
add{ q = { "expert campfire blueprint", "slavecrusher grox", "how to get expert campfire", "expert campfire", "grox kroldok", "expert campfire drop", "expert campfire location", "upgrade to expert campfire", "how do i get the expert campfire" }, a = "Blueprint: Expert Campfire drops from Slavecrusher Grox in Krol'dok Stronghold. The kit uses 1 Thick Logs, needs Cooking 220 to use, and holds 10 camp objects.", topic = "prof_crafting" }
add{ q = { "blueprint drops list", "camp blueprints dungeon", "which dungeon drops camp blueprints", "camp blueprints", "blueprint drops", "camp blueprint list", "dungeon camp blueprints", "which dungeons drop blueprints", "where do blueprints drop", "camp blueprints dungeons", "blueprints list forever", "which dungeons drop camp blueprints" }, a = "Tier-2 camp blueprints mostly drop in leveling dungeons: Deadmines (Gilnid Anvil, Sneed Repair Bot, Cookie's Feast), Wailing Caverns (Serpentis Journeyman Campfire, Anacondra Field Guide), Shadowfang Keep (Razorclaw Tanning Rack, Springvale Toxin Study), BFD (Gelihast Fishing Rack). Tier-3s come from 60 dungeons: Scholomance, Stratholme, BRD, LBRS, Sunken Temple.", topic = "prof_crafting" }
add{ q = { "engineering reagent bot", "buy reagents at camp", "repair at camp", "reagent bot", "buy reagents camp", "repair camp", "camp vendor", "reagent bot engineering", "can i buy reagents at camp" }, a = "Engineering's Reagent Bot (20) summons a vendor at camp selling class reagents and profession supplies and buys junk. The Repair Bot (140, Sneed in Deadmines) also repairs for everyone. Both are great to have in a group camp.", topic = "prof_crafting" }
add{ q = { "fishing in forever how", "fishing not in spellbook", "how to cast fishing forever", "lures forever", "fishing forever", "fishing spell", "how to fish", "cant find fishing", "fishing lures", "how do i fish in forever", "fishing button", "how do i fish in forever its not in my spellbook" }, a = "Fishing isn't in the spellbook in Forever: open the Professions window and drag Fishing to your bar. Lures: Shiny Bauble +25, Nightcrawlers +50 (skill 50), Bright Baubles +75 (skill 100), Aquadynamic Fish Attractor +100 (skill 100). Only use a lure when fish escape.", topic = "prof_crafting" }
add{ q = { "how to get fishing to 20 fast", "fishing 1-20 goldshire", "where to fish elwynn", "fishing 1 20", "fishing goldshire", "fishing elwynn", "fishing fast", "fishing 1-20", "where to fish elwynn forest", "fishing 20 quick", "fishing for camping 101", "wher should i fish to get to 20" }, a = "For Fishing 1-20 near Goldshire, fish Crystal Lake beside Lee Brown's pier (Elwynn 47.5, 62.3). Any water in a starting zone works. Each catch gives a skill-up early on, so 20 comes in a few minutes. Keep the Raw Brilliant Smallfish for Cooking and the Fish Bowl.", topic = "prof_crafting" }
add{ q = { "camping group size", "how many people in a camp", "camping with 10 players", "camp group size", "how many in a camp", "camping 10 players", "camp size", "max people at camp", "camping group", "how many people can use a camp", "camp player limit", "how many people can use one camp" }, a = "A full Expert campfire takes 10 camp objects, one per player, so up to 10 people with different professions can fill it. The buff covers everyone who sits at the camp, and each profession adds its own buff.", topic = "prof_crafting" }
add{ q = { "camp buffs vs class buffs", "does fortitude override first aid kit", "camp buff weaker", "fortitude first aid kit", "camp buff stack class buff", "do camp buffs stack with class buffs", "camp buff overridden", "fortitude camp buff", "camp buff class buff overlap", "do camp buffs stack with fortitude" }, a = "Each camp buff matches a class buff and doesn't stack with it: First Aid Kit vs Fortitude, Fish Bowl (8%) vs Kings (10%), Faction Banner vs Divine Spirit, Incense Candle vs Arcane Intellect, Lodestone vs Might, Mana Well vs Wisdom, Enchanted Lute vs Mark of the Wild, Sharpening Wheel vs Strength of Earth, Camp Chair vs Leader of the Pack / Moonkin Aura.", topic = "prof_crafting" }
add{ q = { "gloves of meditation", "elixir of wisdom tailoring", "tailoring 120-140", "elixir of wisdom", "tailoring 120", "tailoring 140", "gloves of meditation mats", "tailoring 120-140 forever", "gloves of meditation recipe", "elixir of wisdom tailoring forever", "what do i make for tailoring 120-140" }, a = "Gloves of Meditation (120-140): 4 Bolt of Woolen Cloth, 3 Fine Thread and 1 Elixir of Wisdom each; ~29 crafts. They turn yellow at 125, so plan a few extra. Buy Elixir of Wisdom on the AH or from an alchemist. Alternatives: Azure Silk Hood or Lesser Wizard's Robe.", topic = "prof_crafting" }
add{ q = { "runecloth cuffs pexmit", "mount hyjal tailoring vendor", "pexmit", "runecloth cuffs", "pexmit tailoring", "hyjal tailoring", "runecloth cuffs pattern", "pexmit hyjal", "mount hyjal vendor", "runecloth cuffs forever", "hyjal tailoring vendor", "wher do i buy runecloth cuffs pattern" }, a = "Pexmit in Mount Hyjal (a Forever zone) sells Pattern: Runecloth Cuffs (tailoring 250-280, BoP, yellow from 265) and the First Aid Major Healing Potion recipe.", topic = "prof_crafting" }
add{ q = { "tailoring 280-300 cheapest", "finish tailoring 300", "last tailoring points", "tailoring 280", "tailoring 280 300", "finish tailoring", "last points tailoring", "tailoring 290", "tailoring 280-300 forever", "cheapest tailoring 300", "tailoring last 20 points", "what is the cheapest way to finish tailoring 280-300" }, a = "Cheapest 280-300 options: Runecloth Shoulders (world drop/AH pattern), Wisdom of the Timbermaw (Meilosh, Felwood, Timbermaw rep), or the Cenarion Circle Venomspew/Swarmtender pieces from Mishta in Silithus (Friendly/Honored; needs a Loom at camp). Runecloth Headband/Cuffs stop giving points before 300.", topic = "prof_crafting" }
add{ q = { "nightscape pants", "leatherworking 205-235", "thick leather leveling", "lw 205", "lw 205-235", "thick leather lw", "nightscape pants recipe", "nightscape pants mats", "leatherworking 205", "nightscape pants forever", "how do i make nightscape pants" }, a = "Nightscape Pants (205-235): 14 Thick Leather + 4 Silken Thread each, ~36 crafts. Learn them from the Artisan trainer (Drakk Stonehand / Hahrana Ironhide), not the Expert trainers.", topic = "prof_crafting" }
add{ q = { "wicked leather gauntlets pattern", "werg thickblade", "leonard porter", "wicked leather gauntlets", "wicked leather gauntlets recipe", "werg tirisfal", "leonard porter wpl", "wicked leather gauntlets mats", "wicked leather gauntlets forever", "wher do i buy wicked leather gauntlets pattern" }, a = "Pattern: Wicked Leather Gauntlets: Horde from Werg Thickblade (Tirisfal Glades, near the Bulwark), Alliance from Leonard Porter (Chillwind Camp, Western Plaguelands). Each craft: 8 Rugged Leather, 1 Black Dye, 1 Rune Thread; good for 235-265.", topic = "prof_crafting" }
add{ q = { "runic leather headband", "jase farlane", "leatherworking 265-300", "lw 265", "lw 265-300", "runic leather headband recipe", "runic leather headband mats", "jase farlane location", "runic leather headband forever", "wher do i buy runic leather headband pattern" }, a = "Runic Leather Headband (265-300): 14 Rugged Leather, 10 Runecloth, 1 Rune Thread each, ~53 crafts. Pattern from Jase Farlane at Light's Hope Chapel, Eastern Plaguelands.", topic = "prof_crafting" }
add{ q = { "heavy scorpid helm", "zannok hidepiercer", "scorpid leveling leatherworking", "zannok", "heavy scorpid", "heavy scorpid bracers", "scorpid leveling", "zannok silithus", "heavy scorpid helm recipe", "wher do i buy heavy scorpid helm pattern" }, a = "Heavy Scorpid Bracers (255) and Helm (270-300) patterns come from Zannok Hidepiercer in Silithus (Cenarion Hold). They use Rugged Leather plus Heavy Scorpid Scale (Helm also needs Cured Rugged Hide). Good if you can farm scales.", topic = "prof_crafting" }
add{ q = { "minor healing potion leveling first aid 55", "first aid 55-80", "first aid potion leveling", "first aid 55", "first aid 55 80", "minor healing potion first aid", "first aid 55-80 forever", "first aid peacebloom", "fa 55-80", "minor healing potion leveling", "what do i make for first aid 55-80" }, a = "For First Aid 55-80 craft Minor Healing Potion: 1 Peacebloom, 1 Mild Spices (Cooking Supply vendor, ~10c), 1 Empty Vial (trade vendor, ~20c). About 38 crafts. Herbalists can farm Peacebloom in any starting zone.", topic = "prof_crafting" }
add{ q = { "do i need alchemy for healing potions forever", "alchemists make healing potions", "healing potion alchemy removed", "alchemy healing potions", "alchemy no healing potions", "healing potions alchemy", "healing potion alchemy forever", "can alchemy make healing potions", "who makes healing potions", "healing potion profession", "do alchemists still make healing potions", "can alchemists still make healing potions in forever" }, a = "In Forever healing potions moved to First Aid, so any character can make all six tiers (Minor to Major) without Alchemy. Alchemy keeps flasks, elixirs, mana potions and transmutes.", topic = "prof_crafting" }
add{ q = { "raptor eggs cooking", "curiously tasty omelet", "cooking 150-175", "raptor eggs", "cooking 150", "cooking 175", "raptor egg farm", "curiously tasty omelet recipe", "cooking 150-175 forever", "where to get raptor eggs", "wher do i get raptor eggs for omelets" }, a = "Curiously Tasty Omelet (150-175): 1 Raptor Egg + Hot Spices each, ~30 crafts. Raptor Eggs drop from raptors in Arathi Highlands, Wetlands and Stranglethorn. Recipe from Kendor Kabonka (Stormwind) or Nerrist (Grom'gol).", topic = "prof_crafting" }
add{ q = { "poached sunscale salmon", "cooking 250-300", "where to fish sunscale salmon", "sunscale salmon", "cooking 250", "cooking 300", "poached sunscale salmon recipe", "cooking 250-300 forever", "sunscale salmon location", "wher do i fish sunscale salmon" }, a = "Poached Sunscale Salmon (250-300): 1 Raw Sunscale Salmon each, ~60 crafts. Recipe from Gikkix, Steamwheedle Port, Tanaris (~2g). Salmon is fished in 40-60 zones (Classic: Feralas, Azshara, Hinterlands, Winterspring). AH is usually cheapest.", topic = "prof_crafting" }
add{ q = { "dig rat stew", "cooking 90-150 meat", "dig rat stew recipe where", "dig rat", "cooking 90", "cooking 90-150", "dig rat stew recipe", "where to get dig rats", "dig rat stew quest", "cooking meat 90-150", "wher do i get the dig rat stew recipe" }, a = "Dig Rat Stew (90-150ish): 1 Dig Rat each, a quest-reward recipe from The Barrens. Dig Rats drop from rats in the Barrens; about 80 needed in the kami-labs route.", topic = "prof_crafting" }
add{ q = { "flint and tinder", "where to buy flint and tinder", "flint and tinder vendor", "flint tinder", "do i need flint and tinder", "flint and tinder location", "flint and tinder for campfire", "flint tinder vendor", "wher do i buy flint and tinder" }, a = "Flint and Tinder is sold by Cooking trainers and most General Goods vendors. It's only needed in your bags to craft campfire kits, not to place them.", topic = "prof_crafting" }
add{ q = { "skyborne camping 101", "zephras isle camping quest", "raan wildwind", "skyborne camping", "zephras camping", "camping zephras isle", "skyborne great outdoors", "zephras camping 101", "where is raan wildwind", "camping quest zephras", "how do skyborne start camping" }, a = "On Zephras Isle, Raan Wildwind (41.7, 44.8) gives The Great Outdoors and the Camping 101 quests. Camping 101: First Aid is turned in to Naleeia Tattermend in Shen'dar Village; Camping 101: Cooking is done with Zerril Softbreeze in Shen'dar Village (train Cooking for 1s).", topic = "prof_crafting" }
add{ q = { "camping 101 cooking", "how to do camping 101 cooking", "camping 101 cooking quest", "camping cooking quest", "camping 101 cooking help", "how to finish camping 101 cooking", "camping 101 cook", "cooking camping quest", "camping 101 cooking trainer", "camping 101 cooking quest location", "how do i do the camping 101 cooking quest" }, a = "Camping 101: Cooking just needs you to train Apprentice Cooking from the cook it names (e.g. Zerril Softbreeze in Shen'dar Village, 1 silver), then turn in. You get XP and can now craft the Basic Campfire Kit (Cooking 1).", topic = "prof_crafting" }
add{ q = { "what is the max skill for gathering professions in forever", "is the profession cap still 300", "did forever raise herbalism mining cap", "max mining skill wow forever", "skill cap 300 or 375", "whats the max herbalism skill", "gathering cap forever", "can i go past 300 mining", "is 300 still max for herb", "did they raise prof cap in forever or is it still 300", "max skill professions", "how high can mining go", "is there a 375 cap like tbc", "wats the cap on profs in forever", "im at 300 mining can it go any higher in forever" }, a = "The gathering cap in Forever is still 300; it was not raised. Ranks are Apprentice (cap 75, from level 1), Journeyman (cap 150, char level 10), Expert (cap 225, level 20) and Artisan (cap 300, level 35). Gear and food bonuses can push effective skill past 300, which matters for a few mobs (e.g. Core Hounds) and for fishing in 425 zones.", topic = "prof_gathering" }
add{ q = { "how much does it cost to train herbalism mining skinning", "training cost gathering profession", "how much gold to train artisan mining", "how much gold to learn herbalism", "cost of mining training all ranks", "how much does skinning cost to train", "trainer fees for herb", "how much money do i need for artisan herbalism", "price to train gathering profs", "is training mining expensive", "how much g for journeyman expert artisan skinning", "how much money to train herb all the way to artisan", "how much do gathering trainers cost total" }, a = "Herbalism, Mining and Skinning each cost about 5g 55s in trainer fees for all four ranks: Apprentice 10c, Journeyman 5s, Expert 50s, Artisan 5g. Fishing costs about 1g 6s in total, most of it the ~1g Expert book; Artisan Fishing comes from Nat Pagle's quest.", topic = "prof_gathering" }
add{ q = { "junior herbalism trainer only teaches to 75", "why cant my trainer teach me journeyman", "starting zone trainer wont train me past 75", "junior mining trainer smelting", "my trainer wont teach me past 75", "junior trainer cant train journeyman", "why does the starting zone trainer stop at 75", "junior mining trainer doesnt teach smelting", "stuck at 75 starter trainer", "where do i go after junior herbalism trainer", "trainer in starting area only goes to 75 why", "junior trainer in my starting zone stops at 75 where do i go now", "why wont the junior trainer teach me more" }, a = "Forever puts a Junior trainer for each gathering skill in every starting area, but they only teach up to skill 75 and the Junior mining trainers don't teach Smelting. For Journeyman and higher, go to a full trainer in a town or city (e.g. Stormwind, Ironforge, Orgrimmar, Thunder Bluff, Undercity). Outside starting areas, gathering trainers teach every rank.", topic = "prof_gathering" }
add{ q = { "mining for dummies quest", "how to learn herbalism without trainer", "wild harvest pelt collecting for beginners", "starting zone quest teaches profession", "free gathering profession from quest", "quest that teaches mining", "free herbalism book quest", "starting zone profession book", "how do i get mining for dummies", "can i learn skinning from a quest", "wild harvest book", "learn a gathering prof without a trainer", "what quest gives pelt collecting for beginners", "is there a quest in the starting zone that gives a free proffesion", "pelt collecting for beginners where do i get it" }, a = "Each starting zone has a quest whose reward lets you pick one of three books: Mining for Dummies (teaches Mining), Pelt Collecting for Beginners (Skinning) or Wild Harvest (Herbalism). Each one teaches the profession with 2 skill points, so you can skip the trainer for your first gathering skill.", topic = "prof_gathering" }
add{ q = { "how do skill ups work gathering", "orange yellow green gray nodes", "why am i not getting skill points from herbs", "only first mine gives skill", "why am i not getting skill ups", "what do the node colors mean", "orange vs yellow vs green herbs", "gray node no skill", "no skillup from mining after first swing", "how does skilling up work for herbs and ore", "stopped getting points from herbs", "skill up chance gathering", "im mining but only the first swing gives a skill point is that normal", "why do my herbs stop giving skillups" }, a = "Node color shows your skill-up odds: orange always gives a point, yellow usually, green rarely, gray never. For mining, only the first successful swing on a vein can give a point, though you keep mining it until it's empty. In Forever, herbs stay yellow 15 points longer before turning green than in Classic, so low herbs give skill-ups longer.", topic = "prof_gathering" }
add{ q = { "are nodes respawning faster with more players", "dynamic spawn nodes forever", "why are there so many ore nodes when its crowded", "node spawn rate", "do nodes respawn faster when busy", "node respawn rate forever", "dynamic respawn herbs", "why so many herbs when the zone is crowded", "does more people mean more nodes", "ore spawn rate in forever", "crowded zone node spawns faster?", "are nodes respawning way faster cause theres so many ppl here", "do ore nodes spawn faster with more players around" }, a = "Yes. Forever uses dynamic node spawn rates: the more players nearby, the faster herb and ore nodes spawn. Busy zones are less of a dead end than in Classic, though Blizzard also capped player counts in congested zones in the Nov 9 hotfix.", topic = "prof_gathering" }
add{ q = { "what are scarce materials", "scarce materials gathering forever", "pyrite bauxite pitchblende stranglevine what are they", "how do i get scarce mats", "what are scarce mats", "what is pyrite", "scarce materials explained", "what is stranglevine for", "how do you get bauxite", "bonus mats from gathering", "where do scarce materials come from", "what are the new rare reagents from gathering", "got some weird pyrite thing from mining what is it", "scarce mats what are they and how do i farm them" }, a = "Scarce materials are new Forever reagents that drop as a bonus while gathering, not from their own nodes. Herbalism gives Frilled Lichen, Rosecap and Stranglevine; Mining gives Pyrite, Bauxite and Pitchblende; Skinning gives Pristine Leather, Pristine Hide and Pristine Scale. They feed new crafting recipes and hold value on the AH. The Bountiful Harvest legacy talent raises the chance.", topic = "prof_gathering" }
add{ q = { "bountiful harvest talent", "legacy talent for gathering", "best legacy talents for professions", "working overtime talent", "dedicated study", "bountiful harvest legacy", "best legacy talents for gathering", "what does working overtime do", "legacy tree professions", "dedicated study talent what does it do", "talent for more scarce mats", "legacy points for herb mining skinning", "which legacy talents should i get if i mostly gather", "is bountiful harvest worth it" }, a = "Profession Legacy talents: Bountiful Harvest raises Scarce material yield from Mining, Herbalism and Skinning by 20/40/60/80/100% (5 ranks). Working Overtime raises the chance of a skill-up on any tradeskill, best for the 270-300 grind. Dedicated Study gives free points to your lowest profession daily, or 3 random Elemental Essence once all five skills hit 300. Luremaster adds an extra fish chance when using a lure. Points can be reset for a fee.", topic = "prof_gathering" }
add{ q = { "what is camping", "how do campfires work forever", "camp benefits aura", "how to set up camp", "campfire slots", "how does camping work", "what is a campfire for", "how many camp items can a campfire hold", "camping system forever", "how do i set up a camp", "camp buff aura explained", "basic campfire vs expert campfire", "what is camping in wow forever", "how do i use campfires and camp items in forever", "camping explained pls" }, a = "Camping: a cook places a Campfire (Basic at Cooking 1 holds 3 camp items, Journeyman at Cooking 90 holds 5, Expert at Cooking 200 holds 10). Each player can add one profession camp item; anyone who sits or crafts at the camp for a minute gets the buffs. Camp buffs don't stack with the class buff they copy. All camp features share a 1-hour cooldown. You unlock it via the quest The Great Outdoors around level 5.", topic = "prof_gathering" }
add{ q = { "gathering profession camp items", "herbalism mining skinning fishing camp buffs", "what camp item does mining give", "what does the fish bowl do", "what camp item does herbalism give", "mining camp buff", "skinning camp item", "fishing camp buff what does it do", "fish bowl camp item", "gathering camp buffs list", "what buffs do gathering profs give at camp", "camp items for herb mining skinning fishing", "im a miner what camp item can i put down", "what do gathering profs give for camp buffs" }, a = "Gathering camp items (skill 20 / 140 / 300):\nHerbalism: Incense Candle / Greenhouse / Seed Hybridizer - Intellect buff (like Arcane Intellect).\nMining: Lodestone / Rock Garden / Molten Foundry - melee attack power (like Blessing of Might).\nSkinning: Camp Chair / Field Guide / Trapper's Workbench - +2% crit (like Moonkin Aura).\nFishing: Fish Bowl / Fishing Rack / Fishing Hut - 8% stats (like Blessing of Kings).\nHigher tiers replace the lower one in the same slot.", topic = "prof_gathering" }
add{ q = { "reagent bag slot gathering", "herb bag forever", "best herb bag", "where to buy herb pouch", "mining bag hold pick", "reagent bag slot", "where to buy herb bag", "best mining bag", "herb pouch vendor", "does forever have a reagent slot", "bag for herbs", "where do gathering mats go reagent bag", "biggest herb bag forever", "is there a herb bag in forever and where do i buy it", "wher to get a mining bag for my pick" }, a = "Forever adds a dedicated reagent bag slot, and gathering mats go there first. Herb bags: Apprentice's Herb Pouch (4 slots, 25c vendor), Herb Pouch (12 slots, 10s vendor), Cenarion Herb Bag (26, Tailoring 230), Satchel of Cenarius (32, Tailoring 255). Mining bags can also hold your Mining Pick. Ores now stack to 20 (was 10).", topic = "prof_gathering" }
add{ q = { "best gathering profession for gold forever", "which gathering prof makes most money", "herb or mining for gold", "should i take herbalism and mining", "best gathering prof for money", "which gathering makes most gold", "mining or herb for gold", "should i go herb mining", "best money gathering profession forever", "herb vs skin vs mining gold", "whats the best gold making gathering prof", "which prof makes most g", "just made a new char which gathering prof should i take for gold", "herb or mining which makes more g in forever" }, a = "There's no reliable Forever gold-per-hour ranking yet. At current AH medians, top single nodes are Black Lotus (~13g), Rich Thorium (~56s), Arthas' Tears (~79s), Plaguebloom (~77s); Small Thorium is ~31s. Herbalism + Mining on one character is the classic 'double gather' setup and covers both. Skinning is best for Leatherworkers or Devilsaur farming. Prices shift fast, so check your own AH.", topic = "prof_gathering" }
add{ q = { "gold per hour herbalism forever", "how much gold per hour farming herbs", "herbing gph", "gph mining thorium", "herb gold per hour", "how much g an hour herbing", "mining gph thorium", "gold per hour gathering forever", "is herbing good gph", "how much money per hour farming herbs at 60", "whats the gph on herbs", "how much gold per hour can i make herbing at 60", "is mining thorium good gold per hour" }, a = "No trustworthy Forever gold/hour figures are published; guides say to measure your own runs. A rough way: node value x nodes per hour. Example with current US medians, 50 Rich Thorium veins (~56s each) is ~28g of raw ore, and 60 Plaguebloom/Arthas' Tears (~77-79s) is ~46g, plus any Black Lotus (~13g each) and Scarce drops. Subtract AH cut and deposits.", topic = "prof_gathering" }
add{ q = { "herbalism leveling guide 1-300 forever", "how to level herbalism fast", "herb leveling route", "herbalism 1 300 step by step", "whats the fastest way to level herbalism", "herbalism leveling guide", "herb 1-300 guide", "fastest way to lvl herbalism", "herbalism 1 300 forever route", "how do i level herb fast", "herbalism guide step by step", "herb leveling route forever", "best route for levelling herbalism", "just started herbalism whats the fastest way to get it to 300", "herbalism levling guide forever" }, a = "Herbalism 1-300 (Forever routes):\n1. 1-75: Peacebloom, Silverleaf, Earthroot (15+). Teldrassil loop Dolanaar-Darnassus, or Mulgore loop around Thunder Bluff. Train Journeyman at 50+.\n2. 75-115: Mageroyal, Briarthorn, Stranglekelp (85). Loch Modan (A) / The Barrens (H).\n3. 115-170: Bruiseweed, Wild Steelbloom, Kingsblood (125), Liferoot (150). Wetlands from Menethil (A) / Hillsbrad via Tarren Mill (H). Train Expert at 125+.\n4. 170-205: Fadeleaf, Goldthorn, Khadgar's Whisker - Stranglethorn. Train Artisan at 200+ (char level 35).\n5. 205-230: Purple Lotus, Firebloom - Tanaris.\n6. 230-270: Sungrass, Ghost Mushroom, Golden Sansam - Hinterlands (Feralas if busy).\n7. 270-300: Dreamfoil, Silversage, Plaguebloom, Gromsblood - Felwood, then Un'Goro/Plaguelands.", topic = "prof_gathering" }
add{ q = { "herbalism 1-75", "where to level herbalism at the start", "herbalism starting route alliance", "herbalism starting route horde", "herb 1-75", "where to level herb at start", "herbalism 1 to 75 alliance", "herbalism 1 to 75 horde", "teldrassil herb route", "mulgore herb route", "where do i herb at skill 1", "starting herbalism where to go", "im skill 1 herb where should i go first", "where to pick herbs at the very start alliance" }, a = "Herbalism 1-75: pick Peacebloom and Silverleaf (skill 1) and Earthroot from 15 (on hills and ledges). Alliance: Teldrassil has dense herbs - loop from Dolanaar through Darnassus and back south; or Elwynn/Dun Morogh. Horde: Mulgore north of Bloodhoof, looping around Thunder Bluff; Durotar also works. Starting areas also have Wilted Peacebloom and Stunted Silverleaf. Train Journeyman before 75.", topic = "prof_gathering" }
add{ q = { "herbalism 75-150", "herbalism 75 to 115 where", "where to level herbalism after 75", "herbalism 115-170", "herb 75-150", "where to herb at 100", "herbalism 75 to 150 where", "where to go after 75 herbalism", "herbalism 115 to 170", "herb loch modan barrens", "where to level herbalism around 120", "im 75 herbalism where do i go next", "hit 100 herb where should i level now" }, a = "75-115: Mageroyal (50), Briarthorn (70), Stranglekelp (85, underwater). Alliance: Loch Modan big loop (no town on it, plan a mail stop). Horde: The Barrens, north first, south later.\n115-170: Bruiseweed (100), Wild Steelbloom (115, cliffs), Kingsblood (125), Liferoot (150, near water). Alliance: Wetlands loop from Menethil Harbor. Horde: Hillsbrad Foothills loop past Tarren Mill (mailbox). Arathi Highlands works for both. Train Expert (cap 225) at char level 20.", topic = "prof_gathering" }
add{ q = { "herbalism 150-225", "herbalism 170-205", "where to herb at 175", "herbalism stranglethorn route", "herb 150-225", "stv herb route", "herbalism 170 to 205", "where to level herbalism at 180", "khadgars whisker where to level", "im 170 herb is stv the best place", "where to herb at 180 as horde" }, a = "170-205: Stranglethorn Vale for both factions - Kingsblood, Liferoot, Fadeleaf (160), Goldthorn (170), Khadgar's Whisker (185). The loop passes Grom'gol and the northern Alliance camp for mailing. Arathi Highlands and Swamp of Sorrows are alternatives; Wintersbite (195) only grows in Alterac Mountains. Learn Artisan at 200+ (character level 35).", topic = "prof_gathering" }
add{ q = { "herbalism 225-300", "herbalism 230-270", "where to herb at 250", "herbalism 270-300 felwood", "herb 225-300", "herbalism 230 to 300", "herbalism 270 to 300 where", "hinterlands herbalism leveling", "felwood herb 270", "how do i finish herbalism to 300", "tanaris herbalism 205", "im 230 herbalism where do i go to finish", "how do i get herb from 250 to 300" }, a = "205-230: Tanaris - Firebloom (205) and Purple Lotus (210), low competition.\n230-270: The Hinterlands - most Sungrass (230), Purple Lotus, Ghost Mushroom (245, mostly in Hinterlands caves with 47+ oozes), Golden Sansam (260). Feralas if the Hinterlands is crowded.\n270-300: Felwood is the lowest-level zone with max herbs (Gromsblood, Dreamfoil 270, Plaguebloom 285). Also Un'Goro, Western/Eastern Plaguelands, and Winterspring for Icecap (290). Working Overtime talent helps here.", topic = "prof_gathering" }
add{ q = { "herb skill requirements list", "what skill do i need for dreamfoil", "herbalism skill needed for each herb", "what level herbalism for black lotus", "skill for icecap", "what skill for dreamfoil", "herbalism skill per herb", "what herb level for black lotus", "skill needed for icecap", "herb requirement list", "what herbalism do i need for sungrass", "list of herbs and skill levels", "what skill can i pick golden sansam", "what herbalism skill do i need to pick black lotus", "how much herb do i need for dreamfoil and plaguebloom" }, a = "Skill to pick (Forever): Peacebloom/Silverleaf 1, Earthroot 15, Mageroyal 50, Briarthorn 70, Stranglekelp 85, Bruiseweed 100, Wild Steelbloom 115, Grave Moss 120, Kingsblood 125, Liferoot 150, Fadeleaf 160, Goldthorn 170, Khadgar's Whisker 185, Wintersbite 195, Firebloom 205, Purple Lotus 210, Arthas' Tears 220, Sungrass 230, Blindweed 235, Ghost Mushroom 245, Gromsblood 250, Golden Sansam 260, Dreamfoil 270, Mountain Silversage 280, Plaguebloom 285, Icecap 290, Black Lotus 300.", topic = "prof_gathering" }
add{ q = { "im lvl 300 herb what do i buy on ah", "STEP BY STEP GUIDE TO FARM HERBS I AM 300 WHAT DO I BUY", "herb farming setup what to buy", "what do i need to farm herbs fast at 60", "best gear for herb farming", "im 300 herb what do i buy", "what do i need to farm herbs", "herb farming setup", "best gear for herbing", "just hit 300 herb what should i get from ah", "herb farming kit", "herbing prep what to buy", "just hit 60 on my druid with 300 herb what should i buy to farm faster" }, a = "Herb farming kit at 300:\n1. A mount (riding at 40, ~100g; swift at 60). Biggest speed gain by far.\n2. Swiftness Potions for long runs and escapes (Swiftthistle + Briarthorn; buy on AH or brew).\n3. A big herb bag in the reagent slot: Cenarion Herb Bag (26) or Satchel of Cenarius (32) from tailors.\n4. Keep Find Herbs on (re-cast after death).\n5. Bountiful Harvest legacy ranks for more Scarce herbs (Stranglevine).\n6. Lotus Claw glove enchant if farming Mount Hyjal for Death Lotus.\n+Herbalism gloves/enchants/Goldthorn Tea are only needed below 300.\n7. Route: Felwood/Plaguelands/Un'Goro; Winterspring and Burning Steppes for Black Lotus.", topic = "prof_gathering" }
add{ q = { "herbalism gloves", "+herbalism gear", "herbalism skill items", "goldthorn tea", "herbalist's gloves", "herbalism enchant gloves", "herbalism gloves enchant", "+herbalism items", "gear that boosts herbalism", "herbalist gloves where", "goldthorn tea herbalism", "herbalism skill bonus gear", "how to get +herbalism", "enchant gloves herbalism", "how do i get more herbalism skill from gear", "is there an enchant for herbalism gloves" }, a = "Herbalism skill boosters: Enchant Gloves - Herbalism +2 (Enchanting 145), Enchant Gloves - Advanced Herbalism +5 (Enchanting 225), Herbalist's Gloves +5 (Leatherworking 110, BoE, buy on AH), Bog Pickers +5 (drop from Mirelow, Wetlands), Apothecary Gloves +2 (Horde cooking quests), and new Goldthorn Tea +15 for 15 min (Cooking 215, recipe from Razorfen Downs). They let you pick herbs early while leveling; at 300 they add nothing for normal herbs.", topic = "prof_gathering" }
add{ q = { "black lotus where", "black lotus spawn locations forever", "where to farm black lotus", "black lotus farming", "how to find black lotus", "where is black lotus", "black lotus spawns", "where to farm lotus", "black lotus locations forever", "how do i find black lotus", "lotus farming", "where do black lotus spawn", "best zone for black lotus", "where can i find black lotus in forever im 300 herb", "best place to farm blacklotus" }, a = "Black Lotus needs 300 Herbalism and spawns in Burning Steppes, Eastern Plaguelands, Silithus and Winterspring. It's rare and contested; typical play is to loop known spawn points in one of those zones (Burning Steppes and Winterspring are the usual picks) while picking other herbs. It sells around 13g per pick on US AH right now. Black Lotus can't give Scarce herbs.", topic = "prof_gathering" }
add{ q = { "what are the new herbs in forever", "marefoil demonsage death lotus", "new forever herbs", "where is marefoil", "where to find demonsage", "new herbs forever", "what are the forever only herbs", "marefoil demonsage death lotus where", "new endgame herbs", "demonsage location", "what new herbs did forever add and where are they", "where do i pick marefoil" }, a = "Forever adds three endgame herbs: Marefoil (Alchemy Flask of Natural Precision/Swiftness, Engineering Stealthman 52), Demonsage (Flask of Natural Accuracy/Aggression) and Death Lotus. They were added in patch 1.60.1 (Nov 4, 2026). Exact node zones for Marefoil and Demonsage aren't documented yet; Death Lotus comes from herbs in Mount Hyjal with the Lotus Claw glove enchant.", topic = "prof_gathering" }
add{ q = { "death lotus", "how to get death lotus", "lotus claw enchant", "where does death lotus drop", "death lotus hyjal", "how do i get death lotus", "death lotus drop", "lotus claw glove enchant", "where to farm death lotus", "death lotus hyjal how", "death lotus not a node?", "how to get death lotus for natural flasks", "how do i get death lotus i cant find the node anywhere", "death lotus requires lotus claw?" }, a = "Death Lotus isn't a node you see. With Enchant Gloves - Lotus Claw on your gloves, picking any herb in Mount Hyjal (level 60 zone) gives a small chance at a Death Lotus. The enchant source and materials haven't been documented yet, so ask enchanters or check the Guardians of Hyjal vendors.", topic = "prof_gathering" }
add{ q = { "frilled lichen", "rosecap", "stranglevine", "scarce herbs where", "how to get stranglevine", "where to get frilled lichen", "rosecap where", "stranglevine farm", "scarce herbs location", "how do i get rosecap", "which herbs drop stranglevine", "scarce herb drops", "where does rosecap drop from", "what herbs do i need to pick to get frilled lichen" }, a = "Scarce herbs drop as bonus loot from regular herbs: Frilled Lichen from low herbs (Earthroot through Kingsblood), Rosecap from mid herbs (Liferoot through Purple Lotus), Stranglevine from high herbs (Sungrass through Icecap). Grave Moss, Arthas' Tears and Black Lotus give none. Used for Alchemy dyes and some Enchanting recipes. Bountiful Harvest boosts the drop rate.", topic = "prof_gathering" }
add{ q = { "herb seeds", "what do herb seeds do", "commonplace herb seeds", "how to grow herbs forever", "greenhouse herbs", "what are herb seeds for", "how do i grow herbs", "commonplace herb seeds what do", "greenhouse seeds", "herb seeds forever", "what do i do with herb seeds", "planting herbs forever", "i got commonplace herb seeds what are they for", "how do i plant seeds in forever" }, a = "Picking herbs can drop seeds in four tiers: Commonplace, Uncommon, Unusual and Scarce Herb Seeds. Plant them in a Greenhouse (Herbalism 140 camp item) to grow herbs over time, or use a Seed Hybridizer (Herbalism 300) to multiply seeds or combine them into a rarer tier. Both need a campfire and also give the Intellect camp buff.", topic = "prof_gathering" }
add{ q = { "greenhouse blueprint", "where do i get greenhouse", "shadetooth drop", "seed hybridizer blueprint", "how to unlock greenhouse", "greenhouse blueprint where", "how do i get the greenhouse", "where is shadetooth", "seed hybridizer how to get", "how to unlock greenhouse camp item", "greenhouse blueprint drop", "who drops greenhouse", "who drops the greenhouse blueprint for herb camp", "how do i unlock the seed hybridizer" }, a = "The Greenhouse (Herbalism 140) blueprint drops from Shadetooth in the Excavation Site in the Wetlands. The Seed Hybridizer (Herbalism 300) needs Blueprint: Seed Hybridizer; its drop source isn't documented yet. The Incense Candle (skill 20) comes from trainers or Camping 101: Herbalism.", topic = "prof_gathering" }
add{ q = { "swiftthistle", "where to get swiftthistle", "wildvine", "swiftness potion herbs", "swiftthistle where", "how to get swiftthistle", "where to get wildvine", "herbs for swiftness potion", "swiftthistle farm", "which herb gives swiftthistle", "wildvine drop", "where do i get swiftthistle for swiftness pots", "how do you get wildvine" }, a = "Swiftthistle isn't its own node: Mageroyal and Briarthorn have about a 20-40% chance to also give one. Wildvine comes from Purple Lotus (~10%). Swiftthistle + Briarthorn make Swiftness Potions, so herbalists in 10-25 zones farm their own speed pots.", topic = "prof_gathering" }
add{ q = { "ghost mushroom where", "where to farm ghost mushroom", "ghost mushroom cave", "where is ghost mushroom", "ghost mushroom farming", "ghost mushroom location", "ghost mushroom cave where", "where do ghost mushrooms grow", "hinterlands ghost mushroom", "best spot ghost mushroom", "where is the best spot to farm ghost mushrooms", "ghost mushrom location" }, a = "Ghost Mushroom (245 Herbalism) grows only in caves; the main source is the Hinterlands caves (with level 47+ oozes), with Desolace as a secondary zone. It sells around 52s per pick on US AH.", topic = "prof_gathering" }
add{ q = { "grave moss", "graverobber's shovel", "pick grave moss without herbalism", "where to get grave moss", "grave moss location", "graverobbers shovel where", "pick grave moss without herb", "grave moss farm", "how to use graverobbers shovel", "grave moss duskwood", "can i get grave moss without herbalism", "where does grave moss grow" }, a = "Grave Moss (120 Herbalism) grows near graves and crypts (Duskwood, Desolace, Wetlands). Non-herbalists can use the Graverobber's Shovel (drops from Dextren Ward in The Stockade, 10 uses) at Raven Hill Cemetery and the Scarlet Monastery graveyard, but it can wake a Disturbed Ghoul.", topic = "prof_gathering" }
add{ q = { "tauren cultivation", "tauren herbalism racial forever", "does tauren get double herbs", "tauren herbalism racial", "tauren cultivation forever", "does tauren double herbs", "what does cultivation do in forever", "tauren herb bonus", "is tauren good for herbing", "cultivation racial change", "im tauren does cultivation give me double herbs in forever", "tauren herb racial how does it work" }, a = "Tauren Cultivation in Forever duplicates a herb on the ground so you can pick it twice. The copy can be picked without Herbalism, but you need Herbalism to pick the original - effectively double herbs for a Tauren herbalist.", topic = "prof_gathering" }
add{ q = { "find herbs tracking", "how do i track herbs", "find herbs not showing", "how to track herbs", "find herbs ability", "find herbs not working", "herbs not showing on minimap", "how do i see herbs on map", "track herbs", "herb tracking", "herbs arent showing on my minimap how do i track them", "can i track herbs and treasure at same time" }, a = "Find Herbs marks herbs with gold minimap pins over a large radius. It works alongside Find Treasure and Hunter tracking but not alongside Find Minerals (one gathering track at a time), and you must re-cast it after you die.", topic = "prof_gathering" }
add{ q = { "incense candle", "herbalism camp buff", "does incense candle stack with arcane intellect", "what does incense candle do", "herb camp buff", "incense candle stack arcane int", "herbalism camp item 20", "incense candle buff", "does incense candle stack with ai", "does the incense candle stack with arcane intellect", "what buff does incense candle give" }, a = "Incense Candle (Herbalism 20, from trainers or Camping 101) gives nearby campers an Intellect buff of 2-25 depending on level. It does not stack with Arcane Intellect. Greenhouse and Seed Hybridizer give the same buff plus their own functions.", topic = "prof_gathering" }
add{ q = { "herbalism trainer stormwind", "herbalism trainer orgrimmar", "where is herbalism trainer", "herbalism trainer ironforge undercity thunder bluff darnassus", "herb trainer stormwind", "herb trainer org", "where is the herbalism trainer", "herbalism trainer if", "herbalism trainer uc", "herbalism trainer tb", "herbalism trainer darnassus", "herbalism trainer location", "where do i train herbalism in stormwind", "where is the herb trainer in org" }, a = "Herbalism trainers (all ranks): Stormwind - Tannysa, Mage Quarter (54.5, 83.9) or Shylamiir in The Park (31.4, 62.9); Ironforge - Reyna Stonebranch, Great Forge (55.6, 58.0); Darnassus - Firodren Mooncaller, Temple Gardens (47.9, 68.6). Orgrimmar - Jandi, The Drag (55.6, 40.0); Thunder Bluff - Komin Winterhoof, Middle Rise (49.7, 39.6); Undercity - Martha Alliestar, Apothecarium (54.8, 50.1).", topic = "prof_gathering" }
add{ q = { "herbalism trainer outside cities", "artisan herbalism trainer", "herbalism trainer booty bay", "neutral herbalism trainer", "artisan herb trainer", "neutral herb trainer", "herbalism trainer outside city", "where to learn artisan herbalism", "field herbalism trainer", "herb trainer not in city", "is there a herbalism trainer outside the capital cities", "where can i train artisan herbalism without going to a city" }, a = "Field Herbalism trainers that teach up to Artisan: Alliance - Herbalist Pomeroy (Elwynn, 39.9 48.3), Alma Jainrose (Lakeshire 16.8 46.8), Kali Healtouch (Thelsamar 36.6 48.4), Telurinon Moonshadow (Menethil 8.0 55.9), Brant Jasperbloom (Theramore 64.1 47.5), Malorne Bladeleaf (Dolanaar 57.7 60.6), Cylania Rootstalker (Ashenvale 50.6 67.0). Horde - Faruza (Brill 59.9 52.1), Mishiki (Sen'jin 55.4 75.1), Aranae Venomblood (Tarren Mill 61.8 19.7), Angrun (Grom'gol 32.2 27.6), Ruw (Camp Mojache 76.0 43.4). Both - Flora Silverwind (Booty Bay 27.6 77.8), Malvor (Nighthaven 45.6 46.8).", topic = "prof_gathering" }
add{ q = { "apprentice herbalism trainer starting zone", "herbalism trainer northshire", "herbalism trainer valley of trials", "herbalism trainer starting zone", "herb trainer northshire", "herb trainer valley of trials", "apprentice herb trainer", "starter zone herbalism trainer", "herbalism trainer coldridge valley", "where is junior herbalism trainer", "who trains herbalism in northshire", "starting zone herb trainer where is it" }, a = "Starting-zone (Junior, up to 75) Herbalism trainers: Nancy Songflower, Northshire (52.4, 43.8); Emrys Flintbeard, Coldridge Valley (28.8, 66.7); Eleyna Duskbreeze, Shadowglen (59.8, 41.3); Zor'la, Valley of Trials (42.7, 67.4); Garan Sunstrider, Red Cloud Mesa (44.2, 77.8); Florence Nightshade, Deathknell (32.4, 65.2); Halassa Fernbreeze, Shen'dar Village on Zephras Isle (43.1, 43.5).", topic = "prof_gathering" }
add{ q = { "best herb farming zone level 60", "where to farm herbs at 60", "best herbing zone forever", "un'goro or felwood for herbs", "best herb zone at 60", "where to farm herbs lvl 60", "best herbing zone", "ungoro or felwood herbs", "where should i herb at 60", "best place for herbs endgame", "60 herb farm zone forever", "just hit 60 where should i farm herbs", "best zone to herb at 60 in forever" }, a = "Level 60 herb zones: Un'Goro Crater (Golden Sansam, Dreamfoil, Mountain Silversage, Sungrass, Blindweed) is one of the best; Felwood (Plaguebloom, Gromsblood, Dreamfoil); Eastern/Western Plaguelands (Plaguebloom, Arthas' Tears, Dreamfoil, Black Lotus in EPL); Winterspring (Icecap, Black Lotus); Azshara (Purple Lotus, Golden Sansam, Silversage). Mount Hyjal adds Death Lotus chances with Lotus Claw. Pick the least crowded one on your layer.", topic = "prof_gathering" }
add{ q = { "most valuable herbs forever", "which herbs sell best", "what herbs to farm for gold", "herb prices ah", "best herbs to sell", "most valuable herbs", "which herbs sell for most", "herb prices", "what herbs make the most gold", "what herbs should i farm for money", "herb ah prices forever", "what herbs are worth the most on the ah right now", "which herbs should i farm for money" }, a = "Current US Alliance AH medians per pick: Black Lotus ~13g, Arthas' Tears ~79s, Plaguebloom ~77s, Ghost Mushroom ~52s, Icecap ~50s. Common low herbs drop in price fast; rare herbs (Black Lotus) and Scarce herbs (Frilled Lichen, Stranglevine) hold value. Raid flask and potion herbs sell best when raids open (Hyjal Summit opens Dec 9, 2026).", topic = "prof_gathering" }
add{ q = { "herbalism classic leveling route", "vanilla herbalism guide", "classic herb route same in forever", "is the classic herb route the same", "vanilla herbalism guide work in forever", "can i use classic herbalism guide", "herb nodes same as classic", "classic herb route forever", "are herb locations different in forever", "can i just follow a classic herbalism guide for forever", "are herb spawns the same as vanilla" }, a = "The node locations and skill requirements are the Classic ones with only small Forever tweaks (longer yellow window, Scarce drops, seeds). So Classic routes still work: Barrens/Silverpine/Darkshore 1-100, Hillsbrad/Wetlands/Arathi 100-170, STV/Swamp of Sorrows 170-205, Tanaris/Hinterlands/Feralas 205-270, Felwood/Un'Goro/Plaguelands 270-300.", topic = "prof_gathering" }
add{ q = { "mining leveling guide 1-300 forever", "how to level mining fast", "mining 1 300 step by step", "mining route forever", "fastest way to level mining", "mining leveling guide", "mining 1-300 guide", "fastest way to lvl mining", "mining 1 300 forever route", "how do i level mining fast", "mining guide step by step", "best route levelling mining", "just picked up mining whats the fastest way to 300", "mining levling guide forever" }, a = "Mining 1-300:\n1. 1-65: Copper (and Poor Copper Veins / Teldrassil Amber to 20). Elwynn/Westfall/Loch Modan (A), Durotar/Silverpine (H). Smelt Copper Bars for extra points. Train Journeyman at 50+.\n2. 65-125: Tin (65) and rare Silver (75) in Wetlands, Loch Modan, Silverpine, Barrens, Hillsbrad, Duskwood. Smelt Bronze (65-90). Train Expert at 125.\n3. 125-175: Iron (125) and Gold (155) in Arathi, Alterac Mtns, Stranglethorn, Thousand Needles. Smelt Iron/Steel/Gold.\n4. 175-245: Mithril (175) + Truesilver (230) in Badlands, Hinterlands, Searing Gorge, Tanaris, Feralas. Artisan at 200. Dark Iron at 230 in Searing Gorge/Burning Steppes.\n5. 245-300: Small Thorium (245), Rich Thorium (275) in Un'Goro, Winterspring, Silithus, Plaguelands, Burning Steppes. Smelt Azerothium Bars from 275 for points.", topic = "prof_gathering" }
add{ q = { "mining 1-75", "where to mine copper", "mining starting zone", "poor copper vein", "night elf mining teldrassil amber", "mining 1 to 75", "copper ore where", "mining at start", "teldrassil amber", "poor copper vein what is it", "night elf mining", "where to level mining at skill 1", "im 1 mining where do i find copper", "where do i mine at the very start" }, a = "Mining 1-75: mine Copper (skill 1, green around 50, gray at 100) in every starter zone, Westfall, Loch Modan, Durotar, Silverpine. Starter areas have Poor Copper Veins and Teldrassil has Chunks of Amber so Night Elves can mine at home, but those small nodes stop giving skill at 20. Smelt Copper Bars at a forge (good to ~47) for cheap extra points. The Junior trainer caps you at 75 and doesn't teach smelting.", topic = "prof_gathering" }
add{ q = { "mining 75-150", "where to mine tin", "mining 65-125", "where to find silver ore", "mining 75 to 150", "where is tin ore", "silver ore where", "mining 65 to 125", "silver vein location", "where do i level mining after copper", "im 65 mining where do i find tin", "where can i find silver veins" }, a = "Mining 65-125: Tin Veins from 65 (Wetlands, Loch Modan, Duskwood, Silverpine, Barrens, Westfall, Hillsbrad). Silver Veins (75) are rare spawns in the same and higher zones, mostly Arathi/Alterac/STV. Smelt Tin then Bronze Bars (Copper Bar + Tin Bar, orange at 65, gray at 115) to fill gaps. Train Expert at 125 (character level 20).", topic = "prof_gathering" }
add{ q = { "mining 125-175", "where to mine iron", "mining 150-225", "where is gold ore", "iron ore farming", "mining 125 to 175", "where to mine iron ore", "gold ore where", "iron deposit location", "mining 150 to 225", "iron farm", "where to level mining at 150", "best spot for iron", "im 125 mining where do i find iron", "where should i mine gold ore" }, a = "Mining 125-175: Iron Deposits (125) and Gold Veins (155) in Arathi Highlands, Alterac Mountains, Stranglethorn Vale and Thousand Needles (thinner in Duskwood, Ashenvale, Hillsbrad). Smelt Iron Bars (125-140) and Gold Bars (155); Steel Bars (Iron Bar + Coal, 165) also give points. At 175 move to Mithril.", topic = "prof_gathering" }
add{ q = { "mining 175-245", "where to mine mithril", "mithril farming spot", "truesilver where", "mining 175 to 245", "best mithril farm", "truesilver location", "mithril deposit where", "where to farm truesilver", "where to level mining around 200", "im 175 mining where to go for mithril", "where is truesilver usually" }, a = "Mining 175-245: Mithril Deposits (175) - most in Badlands, Searing Gorge, Hinterlands, Feralas, Tanaris; they often share spawns with Iron/Gold. Mithril stays useful until ~230 and gives points until ~270. Truesilver (230) shows up in the same zones and Alterac Mountains. Smelt Mithril (175) and Truesilver (230) Bars. Get Artisan at 200 (character level 35).", topic = "prof_gathering" }
add{ q = { "mining 245-300", "thorium leveling", "where to mine thorium", "mining 275-300", "rich thorium vein skill", "mining 245 to 300", "thorium level", "mining 275 to 300", "what skill rich thorium", "small thorium vein skill", "where do i finish mining to 300", "im 245 mining where do i find thorium", "how do i get mining from 275 to 300" }, a = "Mining 245-300: Small Thorium Veins from 245 (orange 245, gray 345) in Un'Goro, Winterspring, Silithus, Western/Eastern Plaguelands, Feralas, Blasted Lands, Swamp of Sorrows, plus Dire Maul East; rarer in Burning Steppes and Tanaris. Rich Thorium Veins need 275 (Winterspring, Azshara, Un'Goro). Smelt Thorium Bars (250) and the new Azerothium Bar (275) for extra points. Working Overtime helps the last stretch.", topic = "prof_gathering" }
add{ q = { "ore skill requirements list", "what skill do i need to mine thorium", "mining skill needed per ore", "what mining level for mithril", "what skill for thorium", "mining skill per ore", "ore skill list", "what mining for mithril", "what skill dark iron", "mining requirement each ore", "what skill do i need for truesilver", "what mining skill do i need for mithril", "how much mining for rich thorium" }, a = "Mining skill needed (Forever): Copper 1, Tin 65, Silver 75, Iron 125, Gold 155, Mithril 175, Truesilver 230, Dark Iron 230, Small Thorium 245, Rich Thorium 275, Heavy Thorium (new, Mount Hyjal) 300. +Mining gear lets you mine a node a little before your base skill reaches it.", topic = "prof_gathering" }
add{ q = { "smelting recipes skill", "smelting skill ups", "what smelts give mining points", "smelt bars for skill", "can smelting level mining", "which bars give mining skill", "smelt for skill", "level mining by smelting", "smelting recipes list", "smelting gray levels", "can i level mining just by smelting bars", "which smelting gives skill ups" }, a = "Smelting can raise Mining. Bars (orange skill): Copper 1 (gray 70), Tin 65 (gray 75), Bronze 65 (gray 115), Silver 75 (gray 125), Iron 125 (gray 140), Gold 155, Steel 165 (Iron Bar + Coal), Mithril 175, Truesilver 230, Dark Iron 230 (8 ore), Thorium 250, Azerothium 275 (2 Pitchblende + Coal, forge), Heavy Thorium 300 (Molten Foundry). Learn smelts from full Mining trainers, not Junior ones.", topic = "prof_gathering" }
add{ q = { "new ores forever", "pyrite bauxite pitchblende", "what is pitchblende", "where do i get pyrite", "where to farm bauxite", "where to get pyrite", "bauxite farm", "scarce ores", "how do i get pitchblende", "which veins drop bauxite", "got pitchblende from a vein what is it", "where do i farm pyrite" }, a = "Forever's Scarce ores drop as bonus loot from regular veins: Pyrite from low veins (Copper and Tin, plus Silver/Iron per sources), Bauxite from Iron and Mithril, Pitchblende from Thorium veins. Copper has about a 0.4% Pyrite chance. Bountiful Harvest raises these odds. Pitchblende is the key one: 2 Pitchblende + 1 Coal smelt an Azerothium Bar.", topic = "prof_gathering" }
add{ q = { "heavy thorium", "where is heavy thorium", "heavy thorium vein hyjal", "how to smelt heavy thorium", "legionite bar", "heavy thorium vein", "heavy thorium hyjal", "smelt heavy thorium", "how to make legionite bar", "heavy thorium ore where", "legionite", "where do i find heavy thorium veins", "how to make legionite bars" }, a = "Heavy Thorium Ore comes from Heavy Thorium Veins, a rare spawn in Mount Hyjal that needs 300 Mining; it looks like a Rich Thorium Vein with green fel smoke and can also give Torbernite and Fel Crystal gems. Smelt Heavy Thorium (Mining 300) needs a Molten Foundry camp item. The bars go mostly to Blacksmithing plus some Engineering; Alchemists can transmute them into Legionite Bars.", topic = "prof_gathering" }
add{ q = { "molten foundry", "rock garden", "lodestone mining camp", "mining camp items", "where to get rock garden blueprint", "what does lodestone do", "rock garden blueprint where", "molten foundry how to get", "mining camp buff", "rock garden camp", "where to get molten foundry", "what camp items does mining get", "where do i get the rock garden blueprint" }, a = "Mining camp items (place near a campfire): Lodestone (Mining 20, trainer) gives melee attack power like Blessing of Might. Rock Garden (Mining 140) spawns a common mining node over time; its blueprint drops from Relic Guardians at the Excavation Site in the Wetlands. Molten Foundry (Mining 300, Blueprint: Molten Foundry) is required for Smelt Heavy Thorium. All three give the Lodestone buff.", topic = "prof_gathering" }
add{ q = { "dark iron ore where", "dark iron farming", "how to mine dark iron", "dark iron deposit location", "where is dark iron", "dark iron ore farm", "dark iron deposit", "dark iron location", "where can i find dark iron ore", "searing gorge dark iron", "where can i mine dark iron ore", "best place to farm dark iron" }, a = "Dark Iron Deposits need 230 Mining and spawn in Searing Gorge and Burning Steppes (and inside Blackrock Depths and Molten Core in Classic). They give 230-245 skill-ups and sell around 13-14s per node. Searing Gorge is the easiest open-world spot.", topic = "prof_gathering" }
add{ q = { "how to smelt dark iron", "black forge", "smelt dark iron quest", "dark iron bar", "dark iron smelting quest", "black forge where", "spectral chalice", "smelt dark iron requirement", "how do i make dark iron bars", "how do i learn to smelt dark iron", "where is the black forge" }, a = "Classic baseline: Smelt Dark Iron needs 230 Mining and is taught by Gloom'rel in Blackrock Depths after the quest The Spectral Chalice; you smelt 8 Dark Iron Ore into 1 bar at the Black Forge in BRD. Forever's data still lists Dark Iron Bar at 230 from 8 ore, but whether the learning quest and forge changed isn't confirmed.", src = "classic", topic = "prof_gathering" }
add{ q = { "arcane crystal where", "how to get arcane crystal", "arcane crystal farming", "arcanite bar", "where to get arcane crystal", "arcane crystal farm", "arcane crystal drop", "how to make arcanite bar", "arcane crystals from thorium", "arcane crystal location", "how do i get arcane crystals for arcanite", "best place to farm arcane crystal" }, a = "Arcane Crystals are a rare extra drop from Small and Rich Thorium Veins (Un'Goro, Winterspring, Silithus, Plaguelands, Azshara). Alchemists transmute Thorium Bar + Arcane Crystal into an Arcanite Bar. In Forever, Arcanite matters even more: Elementium Bars need 10 Arcanite Bars each.", topic = "prof_gathering" }
add{ q = { "best thorium farming zone", "where to farm thorium fast", "thorium route forever", "un'goro thorium", "best thorium farm", "where to farm thorium", "thorium route", "ungoro thorium farm", "best zone for thorium", "winterspring thorium", "fastest thorium farm forever", "where should i farm thorium at 60", "whats the best thorium route in forever" }, a = "Best Thorium zones: Un'Goro Crater (lots of Rich and Small Thorium around the edges, plus Arcane Crystals) is the go-to; Winterspring (Rich Thorium, Arcane Crystals, watch for elites); Silithus (outer ridges and around hives, contested); Eastern/Western Plaguelands have mixed Mithril/Truesilver/Thorium. Rich Thorium is currently the most valuable ore node (~56s).", topic = "prof_gathering" }
add{ q = { "mining tools", "do i need a mining pick", "what do i need to mine", "rockslicer", "mine without mining pick", "mining pick where", "what is rockslicer", "can i mine without a pick", "mining tools forever", "where to buy mining pick", "do i need a mining pick or can i mine without one", "where do i buy a mining pick" }, a = "You need a Mining Pick in your bags to mine (sold by trade/mining supply vendors; a Mining bag can hold it). Forever adds the Rockslicer, which drops from Rhahk'Zor in The Deadmines: 30 uses, lets anyone mine Copper, Tin, Silver and Iron without the Mining profession.", topic = "prof_gathering" }
add{ q = { "mining skill gear", "+mining gear", "goblin mining helmet", "miner's cape", "mining enchant gloves", "mining skill items", "miners cape", "enchant gloves mining", "gear that boosts mining", "how to get +mining", "how do i get +mining gear", "is there a mining enchant for gloves" }, a = "Mining skill bonuses: Enchant Gloves - Mining +2, Enchant Gloves - Advanced Mining +5, Miner's Cape +2, Goblin Mining Helmet +5 (Engineering). They let you mine nodes a bit early while leveling; at 300 they don't add yield.", topic = "prof_gathering" }
add{ q = { "mining trainer stormwind", "mining trainer ironforge", "mining trainer orgrimmar", "where is mining trainer", "mining trainer undercity thunder bluff", "mining trainer sw", "mining trainer org", "mining trainer if", "mining trainer uc", "mining trainer tb", "mining trainer location", "where do i train mining in stormwind", "where is the mining trainer in org" }, a = "Mining trainers (all ranks): Stormwind - Gelman Stonehand, Dwarven District (59.1, 37.7); Ironforge - Geofram Bouldertoe, Great Forge (50.3, 28.0). Orgrimmar - Makaru, Valley of Honor (73.0, 27.0); Thunder Bluff - Brek Stonehoof, Middle Rise (34.5, 57.5); Undercity - Brom Killian, War Quarter (55.9, 36.0). Darnassus has none - use Kurdram Stonehammer in Auberdine (38.2, 41.0).", topic = "prof_gathering" }
add{ q = { "mining trainer outside city", "artisan mining trainer", "neutral mining trainer", "mining trainer gadgetzan", "where to learn artisan mining", "field mining trainer", "is there a mining trainer outside the capital", "where can i train artisan mining in the field", "wheres a mining trainer that isnt in a capital", "can i train mining in gadgetzan", "minning trainer near me outside town", "need artisan mining dont wanna go to ironforge" }, a = "Field Mining trainers (all ranks): Alliance - Brock Stoneseeker (Thelsamar 37.2, 46.9), Yarr Hammerstone (Kharanos 50.0, 50.4), Dank Drizzlecut (Gol'Bolar Quarry 69.1, 55.5), Kurdram Stonehammer (Auberdine), Matt Johnson (Darkshire 74.0, 49.6). Horde - Krunn (Razor Hill 51.8, 40.7), Johan Focht (The Sepulcher 43.3, 40.6). Neutral - Pikkle (Gadgetzan 51.0, 28.0), Grungle (Powderfuse Port, Riverglades 77.7, 51.9), Messana Crestwind and Halavuul Cragwind (Zephras Isle).", topic = "prof_gathering" }
add{ q = { "apprentice mining trainer", "mining trainer northshire", "mining trainer valley of trials", "kelsey fargo", "mining trainer starting zone", "starter zone mining trainer", "where is kelsey fargo", "junior mining trainer", "who trains mining in northshire", "starting zone mining trainer where is it", "first mining trainer for new chars", "lvl 5 where do i learn mining" }, a = "Starting-zone (Junior, to 75) Mining trainers: Kelsey Fargo, Northshire (47.1, 32.3); Sally Swiftwrench, Coldridge Valley (28.7, 67.8); Fanorran Stilloak, Shadowglen (58.2, 41.3); Norzsh, Valley of Trials (40.5, 68.0); Vartha Rockmane, Red Cloud Mesa (44.2, 78.2); Walter Mason, Deathknell (32.3, 65.7). They don't teach smelting.", topic = "prof_gathering" }
add{ q = { "most valuable ore forever", "what ore sells best", "mining gold making", "ore prices", "best ore to sell", "most valuable ore", "which ore sells best", "ore prices ah", "what ore makes most money", "what should i mine for gold", "what ore is worth the most on the ah", "which ore should i mine for money" }, a = "Current US Alliance AH value per node: Rich Thorium ~56s, Small Thorium ~31s, Dark Iron ~14s, Truesilver ~13s, Mithril ~12s, Gold ~10s, Silver ~6s, Iron ~6s, Tin ~2s, Copper ~1s. Compare raw ore vs smelted bars before posting, and sell Pitchblende/Arcane Crystals separately. Heavy Thorium will matter for Hyjal-era Blacksmithing.", topic = "prof_gathering" }
add{ q = { "what are mining gems forever", "torbernite fel crystal", "gems from ore", "gems from mining", "torbernite", "fel crystal from mining", "what gems drop from ore", "mining gems forever", "do veins drop gems", "new gems from mining forever", "what gems do i get from mining in forever", "do thorium veins drop gems" }, a = "Veins still drop gems as in Classic (e.g. Thorium veins give Star Ruby, Huge Emerald, Azerothian Diamond, Blue Sapphire, Large Opal - Classic baseline). New in Forever: Heavy Thorium Veins in Mount Hyjal can drop Torbernite and Fel Crystal.", topic = "prof_gathering" }
add{ q = { "skinning leveling guide 1-300 forever", "how to level skinning fast", "skinning 1 300 step by step", "skinning route", "where to level skinning", "skinning leveling guide", "skinning 1-300 guide", "fastest way to lvl skinning", "skinning 1 300 forever", "how do i level skinning fast", "skinning guide step by step", "just picked up skinning whats the fastest way to 300", "skinning levling guide forever" }, a = "Skinning 1-300 (skin what you kill; skill caps at mob level x5):\n1. 1-75: starter zones (Elwynn wolves/boars, Durotar boars/raptors). Train Journeyman before 75.\n2. 75-125: Loch Modan, Darkshore, Westfall (A); Northern Barrens, Silverpine (H). Train Expert at 125.\n3. 115-165: Wetlands crocs and raptors, Hillsbrad, Ashenvale.\n4. 150-235: Stranglethorn tigers, raptors and panthers; also Thousand Needles (Shimmering Flats), Arathi, Desolace, Dustwallow. Artisan at 200 (char level 35).\n5. 205-250: Feralas, Tanaris, Hinterlands.\n6. 235-275: Blasted Lands (basilisks, boars, hyenas).\n7. 250-300: Un'Goro (pterrordax, stegodons, Devilsaurs), Silithus scorpids, Winterspring frostsabers and chimaeras.", topic = "prof_gathering" }
add{ q = { "what level mob can i skin", "skinning skill formula", "why cant i skin this mob", "requires skinning 300", "skinning skill per mob level", "skinning formula", "cant skin this mob", "requires skinning 300 what level", "how much skinning to skin a lvl 50", "what skill to skin level 60 mobs", "why cant i skin this mob it says requires higher skinning", "what level mobs can i skin at 200 skinning" }, a = "Skill needed to skin a mob: levels 1-10 need 1; levels 11-20 need (level - 10) x 10; level 21+ need level x 5. So a level 40 mob needs 200, level 55 needs 275, level 60 needs 300, and level 62 needs 310 (more than the 300 cap, so you need +skill gear).", topic = "prof_gathering" }
add{ q = { "skinning 1-75", "skinning start", "where to skin at low level", "skinning 1 to 75", "skinning starter zone", "where to level skinning at start", "skinning at low level", "elwynn skinning", "durotar skinning", "where do i skin at skill 1", "im 1 skinning where do i start", "where do i skin at the start as horde" }, a = "Skinning 1-75: Elwynn Forest (Young Wolf, Timber Wolf, Stonetusk Boar, Prowler) or Dun Morogh/Teldrassil for Alliance; Durotar (Mottled Boar, Dire Mottled Boar, Bloodtalon Scythemaw) or Mulgore/Tirisfal for Horde. All skin from skill 1. You get Ruined Leather Scraps, Light Leather and Light Hide. Train Journeyman before 75.", topic = "prof_gathering" }
add{ q = { "skinning 75-150", "skinning barrens loch modan", "skinning 100-150 wetlands", "skinning 75 to 150", "barrens skinning", "loch modan skinning", "skinning 100 to 150", "where to skin at 100", "wetlands skinning", "skinning 30 to 130", "im 75 skinning where do i go next", "where to skin at 100 alliance" }, a = "Skinning 30-130: The Barrens (Greater Plainstrider from 10, Zhevra Runner from 30, Savannah Prowler from 40, Sunscale Scytheclaw from 60) or Loch Modan (Mountain Boar, Grizzled Black Bear 30, Loch Crocolisk 40, Elder Mountain Boar 60). Then 105-165 in the Wetlands: Young Wetlands Crocolisk (105), Mottled Raptor (110), Mottled Screecher (120), Giant Wetlands Crocolisk/Mottled Scytheclaw (125), Highland Razormaw (135). Hillsbrad and Ashenvale work too.", topic = "prof_gathering" }
add{ q = { "skinning 150-225", "skinning stranglethorn", "skinning 200-250", "skinning 150 to 225", "stv skinning", "skinning 200 to 250", "where to skin at 175", "stranglethorn tigers skinning", "im 150 skinning where do i go", "where should i level skinning around 200", "skining 150-235 route", "im 160 skinning should i go stv" }, a = "Skinning 150-235: Stranglethorn Vale - Young Stranglethorn Tiger (150), Stranglethorn Tiger (160), Lashtail Raptor (175), Jungle Stalker (200), Elder Shadowmaw Panther (210). Alternatives: Shimmering Flats in Thousand Needles, Arathi, Desolace, Dustwallow, Badlands. 205+: Feralas, Tanaris and the Hinterlands (level 40-50 beasts give Thick Leather).", topic = "prof_gathering" }
add{ q = { "skinning 225-300", "skinning 250-300", "where to finish skinning", "skinning un'goro", "skinning 225 to 300", "skinning 250 to 300 where", "ungoro skinning", "blasted lands skinning 235", "im 250 skinning where do i go to get 300", "how do i get skinning to 300", "im 235 skinning where should i go now" }, a = "Skinning 235-300: Blasted Lands - Redstone Basilisk (235), Ashmane Boar (240), Snickerfang Hyena and Scorpok Stinger (245); they also drop Blasted Lands quest items. 250+: Un'Goro - Pterrordax (250), Stomper (255), Stegodons and Frenzied Pterrordax (260), Devilsaur (270, elite). 270+: Silithus Stonelash scorpids (270-285) for Rugged Leather and Heavy Scorpid Scale. 275+: Winterspring Shardtooth Maulers, Chillwind Chimaera, Frostsabers (280-295).", topic = "prof_gathering" }
add{ q = { "leather tiers by level", "what leather drops at what level", "where to farm rugged leather", "thick leather where", "heavy leather farm", "what leather at what level", "thick leather farm", "heavy leather where", "leather by mob level", "which mobs drop thick leather", "where should i skin for heavy leather", "rugged leather best spot", "what level mobs drop thick leather" }, a = "Leather by mob level: 1-10 Light Leather/Ruined Scraps; 11-20 Light + Medium; 21-30 Medium + Heavy Leather/Heavy Hide; 31-40 Heavy + Thick Leather, Turtle Scale; 41-50 Thick + some Rugged; 51-60 Rugged Leather, Rugged Hide, Heavy Scorpid Scale. For Rugged Leather farm Winterspring, Azshara, Silithus scorpids or Un'Goro; for Thick, Feralas/Tanaris/Hinterlands.", topic = "prof_gathering" }
add{ q = { "devilsaur leather", "where to farm devilsaur", "devilsaur skinning skill", "devilsaur un'goro", "where to farm devilsaur leather", "devilsaur skinning", "devilsaur location", "how much skinning for devilsaur", "devilsaur farm ungoro", "where are the devilsaurs", "is devilsaur leather worth farming", "where do i farm devilsaur leather is it hard" }, a = "Devilsaur Leather comes only from Devilsaurs in Un'Goro Crater (elite, level 54-55, need ~270 Skinning). They roam the crater, hit hard and are heavily contested. Classic tactic: hunters and other kiters solo them; bring a skinner friend if you can't. Devilsaur Leather feeds the Devilsaur Leatherworking set, so value depends on demand.", topic = "prof_gathering" }
add{ q = { "core leather", "how to skin core hounds", "core leather skinning requirement", "skinning 310 how", "how to get core leather", "skin core hounds", "how do i get 310 skinning", "core hound skinning", "can i skin core hounds at 300", "core leather mc", "how do i skin core hounds if cap is 300" }, a = "Classic baseline: Core Leather comes from skinning Core Hounds in Molten Core, which needs 310 Skinning (they're level 62). With the 300 cap you need +10: in Forever, Enchant Gloves - Advanced Skinning (+10) alone does it; otherwise stack Enchant Gloves - Skinning (+5), Keen Skinning Knife (+3), Cartilage Shapers (+4) or Classic +10 items like Finkle's Skinner (The Beast, UBRS). Onyxia needs 315.", src = "classic", topic = "prof_gathering" }
add{ q = { "skinning knife", "do i need a skinning knife", "where to buy skinning knife", "keen skinning knife", "skinning knife vendor", "does skinning knife need to be equipped", "skinning without knife", "where do i get a better skinning knife", "do i need to equip my skinning knife or just have it in bags", "where can i buy a skinnin knife", "lost my skinning knife where do i get another", "skinning knife needed?" }, a = "You need a Skinning Knife in your bags (it doesn't have to be equipped); buy one from trade supplies or leatherworking vendors. The Keen Skinning Knife gives +3 Skinning and is a quest reward from Unwelcome Guests (level 18, The Barrens).", topic = "prof_gathering" }
add{ q = { "skinning gear", "+skinning gear", "skinning enchant", "advanced skinning enchant", "finkle's skinner zulian slicer", "skinning enchant gloves", "finkles skinner", "zulian slicer", "gear that boosts skinning", "how do i get more skinning skill from gear", "how to skin higher lvl mobs gear", "is there an enchant for skinning gloves" }, a = "Skinning bonuses: Enchant Gloves - Skinning +5 (Enchanting 200), new Enchant Gloves - Advanced Skinning +10 (Enchanting 250), Keen Skinning Knife +3, Cartilage Shapers +4. Classic +10 weapons Finkle's Skinner (The Beast, UBRS) and Zulian Slicer (Thekal, ZG) aren't confirmed for Forever. Bonuses matter only for mobs above level 60 (Core Hounds, Onyxia).", topic = "prof_gathering" }
add{ q = { "new skinning materials forever", "pristine leather", "pristine hide", "pristine scale", "fel leather fel hide forever", "pristine leather what is it", "fel leather forever", "new skinning mats", "what is fel hide", "scarce skinning materials", "got pristine leather what do i use it for", "what are the new skinning materials in forever" }, a = "New Forever skinning mats: Fel Leather and Fel Hide (normal skinned), plus Scarce Pristine Leather, Pristine Hide and Pristine Scale. Pristine Leather is used in many new Leatherworking, Blacksmithing and Tailoring recipes. Where Fel Hide drops isn't documented yet. Bountiful Harvest raises Scarce odds.", topic = "prof_gathering" }
add{ q = { "where to farm pristine leather", "pristine leather farm", "best place pristine leather", "best spot for pristine leather", "pristine leather drop location", "which mobs drop pristine leather", "how do i get pristine leather fast", "pristine leathr farm spot", "where is the best place to farm pristine leather in forever", "pristine leather spot", "farm pristine lether" }, a = "Reported Pristine Leather spots (no confirmed drop rates): Westfall Young Goretusks/Goretusks (level 12-15), The Barrens Fleeting Plainstriders, Sunscale Scytheclaws and Savannah Matriarchs, Silverpine Moonrage Gluttons near North Tide's Hollow; also reports from Darkshore, Loch Modan, Mulgore and Wailing Caverns. Beta testers suspect it's tied to low-level beasts, so a high character may not get it - unconfirmed.", topic = "prof_gathering" }
add{ q = { "skinning trainer stormwind", "skinning trainer orgrimmar", "where is skinning trainer", "skinning trainer ironforge darnassus undercity thunder bluff", "skinning trainer sw", "skinning trainer org", "skinning trainer if", "skinning trainer uc", "skinning trainer tb", "where do i train skinning in stormwind", "skinning trainer darnassus", "where is the skinning trainer in org" }, a = "Skinning trainers (all ranks): Stormwind - Maris Granger, Old Town (72.3, 62.3); Ironforge - Balthus Stoneflayer, Great Forge (39.6, 32.8); Darnassus - Eladriel, Craftsmen's Terrace (64.2, 21.7). Orgrimmar - Thuwd, The Drag (63.1, 45.3); Thunder Bluff - Mooranta, Middle Rise (44.7, 43.3); Undercity - Killian Hagey, Rogues' Quarter (71.0, 59.5).", topic = "prof_gathering" }
add{ q = { "skinning trainer outside cities", "artisan skinning trainer", "skinning trainer barrens", "skinning trainer goldshire", "skinning trainer outside city", "neutral skinning trainer", "where can i train skinning without going to a city", "field skinning trainer", "is there a skinning trainer outside the capital cities", "skinning trainer in the barrens where", "need artisan skinning without going to org", "wheres a skinning trainer out in the world" }, a = "Field Skinning trainers: Alliance - Helene Peltskinner (Goldshire 46.3, 62.2), Wilma Ranthal (Redridge, Shalewind Canyon 83.6, 71.1), Jayla (Ashenvale, Silverwind Refuge 50.1, 67.2), Radnaal Maneweaver (outside Darnassus 42.1, 50.0). Horde - Dranh (Camp Taurajo 45.1, 59.0), Yonn Deepcut (Bloodhoof 45.0, 61.4), Rand Rhobart (camp near Undercity 65.6, 60.1), Malux (Shadowprey 23.2, 69.8), Kulleg Stonehorn (Camp Mojache 74.4, 43.0). Zephras Isle (both): Ishlee Breezewhisper, Mendalass Tattermend.", topic = "prof_gathering" }
add{ q = { "apprentice skinning trainer", "skinning trainer northshire", "skinning trainer valley of trials", "skinning trainer starting zone", "starter skinning trainer", "who trains skinning in coldridge", "junior skinning trainer", "who trains skinning in northshire", "who teaches skinning in valley of trials", "lvl 5 where do i learn skinning", "first skinning trainer" }, a = "Starting-zone (to 75) Skinning trainers: Riley Peltskinner, Northshire (47.0, 39.8); Brighid Stormflayer, Coldridge Valley (29.2, 67.7); Terunne Bearshaper, Shadowglen (59.4, 38.7); Kagil, Valley of Trials (40.8, 68.0); Nawka Wildsong, Red Cloud Mesa (44.8, 76.8); Margaret Weaver, Deathknell (32.6, 65.7).", topic = "prof_gathering" }
add{ q = { "skinning camp items", "camp chair", "field guide skinning", "trapper's workbench", "track beasts camp", "camp chair what does it do", "skinning field guide camp", "trappers workbench", "skinning camp buff", "what camp items does skinning get", "track beasts camp item", "how do i get the camp chair for skinning" }, a = "Skinning camp items: Camp Chair (Skinning 20; 3 Light Leather + 2 Simple Wood; from trainer or Camping 101: Skinning) gives +2% crit like Moonkin Aura. Field Guide (Skinning 140; Medium Leather, Slimy Murloc Scale, Fine Thread) adds Track Beasts; its blueprint is tied to Lady Anacondra in Wailing Caverns. Trapper's Workbench (Skinning 300; Simple Wood, Heavy Leather, Iron Bar) holds one trap. All give the crit buff.", topic = "prof_gathering" }
add{ q = { "frostsaber leather", "chimera leather", "winterspring skinning", "special leathers", "where to get frostsaber leather", "where to farm chimera leather", "special leathers classic", "chimaera leather location", "where do i get frostsaber and chimera leather", "frostsaber leather where", "where do i skin chimeras", "winterspring leather farm" }, a = "Classic baseline: Winterspring Frostsabers give Frostsaber Leather and Chimaeras (Winterspring, Feralas) give Chimera Leather, both used in Leatherworking patterns. Winterspring's Frostsabers need 280-295 skill and Shardtooth Maulers/Chillwind Chimaera need 275.", src = "classic", topic = "prof_gathering" }
add{ q = { "shaper's terrace skinning", "dungeon skinning materials forever", "skinnable bosses forever", "shapers terrace skinning", "dungeon skinning forever", "can you skin bosses in shapers terrace", "vitrix skinning", "best dungeon for skinning", "skinning in new dungeon", "can you skin the bosses in the shapers terrace dungeon" }, a = "The new dungeon The Shaper's Terrace has skinnable bosses: since the Nov 9 hotfix, Vitrix, Snowtalon and Cinder correctly drop higher-level skinning materials, so bring a skinner.", topic = "prof_gathering" }
add{ q = { "best skinning farm level 60", "skinning gold farm", "where to skin for gold at 60", "best skinning farm 60", "where to skin for gold", "best place to skin at 60", "skinning gold forever", "just hit 60 where do i skin for money", "rugged leather farm 60", "whats the best place to skin for gold at 60" }, a = "Level 60 skinning farms: Silithus Stonelash scorpids (Rugged Leather + Heavy Scorpid Scale, from 270), Winterspring frostsabers/chimaeras/bears (Rugged Leather plus specialty leathers), Un'Goro Devilsaurs (Devilsaur Leather, elite and contested), Blasted Lands beasts (also drop quest items for Blasted Lands buff quests). Leatherworking's Tanning Rack (now Leatherworking 125) increased leather demand in Forever.", topic = "prof_gathering" }
add{ q = { "fishing leveling guide 1-300 forever", "how to level fishing fast", "fishing 1 300 step by step", "fishing route", "where to level fishing", "fishing leveling guide", "fishing 1-300 guide", "fastest way to lvl fishing", "fishing 1 300 forever", "how do i level fishing fast", "just started fishing how do i get to 300", "fishin guide step by step", "fishing levling guide forever" }, a = "Fishing 1-300:\n1. Train Apprentice and Journeyman at any Fishing trainer; buy a Fishing Pole and Shiny Baubles (+25).\n2. 1-75: starter zone lakes and capital cities.\n3. 75-150: Westfall, Loch Modan, Darkshore, Barrens, Silverpine (Oily Blackmouth). Go Expert near 150: buy 'Expert Fishing - The Bass and You' (about 1g) from Old Man Heming, Booty Bay docks (27.5, 77.0).\n4. 150-225: Wetlands, Hillsbrad, Ashenvale, Redridge, Duskwood (Firefin Snapper), then Stranglethorn coasts.\n5. 225: do Nat Pagle's quest in Dustwallow Marsh (58.5, 59.8) for Artisan.\n6. 225-300: Feralas, Tanaris, Hinterlands, Azshara, Un'Goro, Felwood (Nightfin/Sunscale, Stonescale Eel). Use Nightcrawlers/Bright Baubles so fewer fish get away.", topic = "prof_gathering" }
add{ q = { "fishing zone skill requirements", "why do fish get away", "fish got away", "what skill to fish in tanaris", "fishing skill needed per zone", "fishing skill per zone", "what fishing for tanaris", "fish keep escaping", "what skill to fish in stv", "fishing zone requirements", "my fish keep getting away what skill do i need", "what fishing skill do i need so fish stop getting away" }, a = "Fish escape when your effective skill (skill + pole + lure + gear) is below the zone's threshold. No get-aways at: 25 starter zones; 75 cities, Westfall, Loch Modan, Darkshore, Barrens, Silverpine; 150 Ashenvale, Duskwood, Hillsbrad, Redridge, Stonetalon, Wetlands; 225 Alterac, Arathi, Desolace, Dustwallow, STV, Swamp of Sorrows, Thousand Needles; 300 Azshara, Felwood, Feralas, Hinterlands, Tanaris, Un'Goro, WPL, Moonglade; 425 EPL, Silithus, Winterspring, Burning Steppes, Deadwind, Bay of Storms.", topic = "prof_gathering" }
add{ q = { "fishing trainer stormwind", "fishing trainer orgrimmar", "where is fishing trainer", "fishing trainer ironforge undercity thunder bluff darnassus", "fishing trainer sw", "fishing trainer org", "fishing trainer if", "fishing trainer uc", "fishing trainer tb", "where do i learn fishing", "fishing trainer darnassus", "where do i train fishing in stormwind" }, a = "Fishing trainers (Apprentice/Journeyman): Stormwind - Arnold Leland, Trade District (55.1, 69.6); Ironforge - Grimnur Stonebrand, Forlorn Cavern (48.5, 6.2); Darnassus - Astaia, Temple Gardens (47.5, 56.5); Goldshire - Lee Brown (47.6, 62.3). Orgrimmar - Lumak, Valley of Honor (69.7, 29.3); Thunder Bluff - Kah Mistrunner (56.4, 47.6); Undercity - Armand Cromwell, Magic Quarter (81.0, 29.5); Sen'jin - Lau'Tiki (53.2, 81.5). Booty Bay - Myizz Luckycatch (27.5, 77.2).", topic = "prof_gathering" }
add{ q = { "expert fishing", "how to get expert fishing", "the bass and you", "old man heming", "fishing stuck at 150", "the bass and you book", "where is old man heming", "expert fishing book", "how do i get fishing past 150", "cant train fishing past 150", "im 150 fishing how do i get expert", "expert fishing book where", "where to buy the bass and you" }, a = "Fishing trainers only teach up to Journeyman (150). For Expert (225), buy the book 'Expert Fishing - The Bass and You' from Old Man Heming on the lower docks of Booty Bay, Stranglethorn Vale (27.5, 77.0) - about 1g - and read it. Both factions use the same NPC.", topic = "prof_gathering" }
add{ q = { "stranglethorn fishing extravaganza", "stv fishing tournament forever", "fishing tournament when", "how does fishing derby work", "fishing contest sunday", "stv fishing tournament", "fishing extravaganza", "when is fishing tournament", "fishing derby forever", "sunday fishing contest", "how does the fishing tournament work", "stranglethorn fishing contest time", "what time is fishing extravaganza", "when is the stv fishing tournament in forever" }, a = "Stranglethorn Fishing Extravaganza (Forever): every Sunday 2-4 PM server time. Fish the STV coast for Speckled Tastyfish pools and turn 40 Speckled Tastyfish in to Riggle Bassbait in Booty Bay. Unlike Classic, many players win: the first 50 got rewards at launch, and the Nov 13 hotfix greatly raised the number of winners per ruleset. Winners get the Arcanite Fishing Pole (+35) and an Extravagant Extravaganza Coin.", topic = "prof_gathering" }
add{ q = { "extravagant extravaganza coin", "what can i buy with extravaganza coin", "jang booty bay", "hook of the master angler", "surfer shoes", "extravaganza coin", "what to buy with extravaganza coins", "where is jang", "fishing tournament rewards", "what do i spend extravaganza coin on", "what can i buy with the coin from the fishing tournament", "what does jang sell", "fishing tournament coin rewards list" }, a = "Spend Extravagant Extravaganza Coins at Jang in Booty Bay; each item costs 1 coin: Hook of the Master Angler (swim speed trinket), Surfer Shoes (water walking), Master Angler's Fishing Hat (cosmetic), Empty Fish Bucket (cosmetic off-hand), Bitter Baitling (pet). The coin is soulbound.", topic = "prof_gathering" }
add{ q = { "fishing tournament tips", "how to win fishing extravaganza", "best spot speckled tastyfish", "extra tastyfish", "how to win fishing tournament", "best spot for tastyfish", "speckled tastyfish where", "how do i win the stv fishing contest", "tastyfish pools", "fishing extravaganza strategy", "any tips to win the stv fishing extravaganza" }, a = "Tournament tips:\n1. Set your hearth to Booty Bay and arrive before 2 PM.\n2. Fish only Tastyfish pools on the STV coast (none inland or off the islands).\n3. Max your effective skill (best pole, lure, hat, boots) so fewer fish escape.\n4. Use mount/speed items between pools; a friend can clear mobs and scout.\nExtra Tastyfish can be traded for gold, and in Forever beta also for Messages in a Bottle (random recipes). Winning gives the Master Angler title for a week.", topic = "prof_gathering" }
add{ q = { "fishing poles best", "best fishing pole forever", "arcanite fishing pole", "nat pagle's extreme angler", "big iron fishing pole", "best fishing pole", "nat pagles pole", "fishing pole forever", "which fishing pole should i get", "strong fishing pole where", "whats the best fishing pole in forever", "what pole should i fish with", "best rod for fishing" }, a = "Fishing poles: Fishing Pole +0 (vendor), Blump Family Fishing Pole +3 (Alliance quest), Strong Fishing Pole +5 (vendor), Big Iron Fishing Pole +20, Nat Pagle's Extreme Angler FC-5000 +25 (Horde), Arcanite Fishing Pole +35 (Extravaganza winner reward).", topic = "prof_gathering" }
add{ q = { "fishing lures", "best fishing lure", "nightcrawlers", "aquadynamic fish attractor", "bright baubles shiny bauble", "secret bait", "bright baubles", "shiny bauble", "what lure should i use", "what fishing lure gives the most skill", "best bait for fishing", "what lures can i buy", "lure that gives +75", "which lure is best for fishing skill" }, a = "Lures (only one active at a time): Shiny Bauble +25, new 'Secret' Bait +25, Nightcrawlers +50, Aquadynamic Fish Lens +50, Bright Baubles +75 (Engineering), Flesh Eating Worm +75, Aquadynamic Fish Attractor +100 (Engineering). Lures raise effective skill, which stops fish escaping in high zones and is how you reach 425-skill zones.", topic = "prof_gathering" }
add{ q = { "fishing gear", "+fishing gear", "nat pagle boots", "lucky fishing hat", "fishing enchant", "fishing hat forever", "fishing hat", "wide brimmed fishing hat", "gear that boosts fishing", "best fishing gear forever", "what gear gives +fishing in forever", "fishing hat where", "what fishing gear should i get", "how do i boost my fishing skill with gear" }, a = "Fishing skill gear: Lucky Fishing Hat +5, Worn Fishing Hat +5, new Wide-Brimmed Fishing Hat +25, Nat Pagle's Extreme Anglin' Boots +5, High Test Eternium Fishing Line +5, Enchant Gloves - Fishing +2. Walk on water with Surfer Shoes (tournament) or a Draught of Waterwalking.", topic = "prof_gathering" }
add{ q = { "fishing buff food", "food that increases fishing", "loch frenzy delight", "fillet of frenzy", "food that gives fishing", "fishing skill food forever", "is there food that boosts fishing", "rockscale cod fishing buff", "is there any food that gives fishing skill", "fish food that gives fishing skill", "cooked food for +fishing", "frenzy fillet fishing buff" }, a = "Forever adds cooked food that raises Fishing skill: Loch Frenzy Delight +3, Fillet of Frenzy +5, Bristle Whisker Catfish +8, Rockscale Cod +12, Filet of Redgill +18, Spinefin Halibut +18.", topic = "prof_gathering" }
add{ q = { "chef's knife", "unique fish forever", "what is the chefs knife for", "chefs knife", "unique fish", "what is the chefs knife", "chefs knife what fishing skill", "how to prepare unique fish", "where do i get the chefs knife", "chef knife forever", "what is the chefs knife used for in forever" }, a = "Forever adds a Chef's Knife used to prepare Unique Fish, the new rarer catches. Beta reports put its requirement at 275 Fishing. Fishing crafts live in the new Bait and Tackle menu in the Professions window.", topic = "prof_gathering" }
add{ q = { "new fish forever", "savory whimsy fish delight", "alliance deviate fish", "uncommon rare fish forever", "rare fish forever", "uncommon fish", "what new fish are there", "forever new fish list", "what new fish did forever add", "what rare fish are in forever", "are there new fish to catch", "new rare fishes forever" }, a = "Forever adds Uncommon and Rare fish (best caught with the Fishing Rack/Hut camp buffs). Beta reports mention a Savory Whimsy Fish Delight as the Alliance counterpart to Savory Deviate Delight, caught in the small rivers of Redridge Mountains (not the main lake), with a one-hour transform when eaten. Treat that detail as beta-sourced.", topic = "prof_gathering" }
add{ q = { "fishing pools", "what are fish schools", "floating wreckage", "fishing wreckage loot", "oil spill pool", "fish schools", "what are fishing pools", "wreckage loot", "oil spill fishing", "how do fish schools work", "should i fish pools", "should i fish in pools or open water" }, a = "Pools (schools) along coasts, lakes and rivers give several catches of one fish type - e.g. Oily Blackmouth School, Firefin Snapper School, Stonescale Eel Swarm, Oil Spill. Cast right into the pool. Floating Wreckage gives locked trunks with cloth bolts, leather, metal and green gear; in Forever, wreckages are a source of Cloth Bolts and many leathers for Tailors and Leatherworkers.", topic = "prof_gathering" }
add{ q = { "key fish for alchemy", "stonescale eel", "oily blackmouth", "firefin snapper", "fish for free action potion", "where to fish stonescale eel", "fish for alchemy", "stonescale eel where", "oily blackmouth where", "firefin snapper where", "where to fish stonescale eels", "which fish do alchemists need", "where do i fish stonescale eel for alchemy" }, a = "Alchemy fish (Classic baseline): Oily Blackmouth -> Blackmouth Oil (Free Action, Swim Speed, Water Breathing); fish it in Darkshore, Westfall, Loch Modan, Silverpine, Barrens. Firefin Snapper -> Fire Oil (Fire Protection, fire elixirs); best in Wetlands and Hillsbrad coasts. Stonescale Eel -> Stonescale Oil (defense elixirs, Flask of Petrification); pools in Azshara's Bay of Storms, Tanaris, Feralas, Hinterlands coasts.", src = "classic", topic = "prof_gathering" }
add{ q = { "key fish for cooking", "nightfin snapper", "sunscale salmon", "sagefish", "mightfish", "best fish for buff food", "fish for cooking", "where to fish nightfin snapper", "which fish for raid food", "which fish do i need for raid buff food", "where to fish sunscale salmon", "best fish for cooking buffs", "mightfish where", "which fish should i catch for cooking" }, a = "Cooking fish (Classic baseline): Nightfin Snapper (night only) -> Nightfin Soup (mana regen); Sunscale Salmon (day only) -> Poached Sunscale Salmon (health regen) - both in Azshara, Felwood, Plaguelands, Hinterlands, Un'Goro, Winterspring. Sagefish/Greater Sagefish -> mp5 food (Loch Modan, Hillsbrad, Lordamere Lake, Lake Nazferiti). Glossy Mightfish (205) -> +Stamina food (Azshara, Feralas, Tanaris). Winter Squid -> Agility food; Summer Bass -> Spirit food.", src = "classic", topic = "prof_gathering" }
add{ q = { "deviate fish", "savory deviate delight", "where to fish deviate fish", "deviate fish location", "barrens deviate fish", "how to get deviate fish", "deviate delight recipe fish", "where do i catch deviate fish", "deviate fish where", "how to catch deviate fish barrens", "where to fish for deviate delight" }, a = "Classic baseline: Deviate Fish are caught in the Barrens oasis pools (Lushwater, Stagnant, Forgotten Pools, etc.) and cooked into Savory Deviate Delight (transform food). Forever's beta added an Alliance-side equivalent in Redridge.", src = "classic", topic = "prof_gathering" }
add{ q = { "fishing gold making", "how to make gold fishing forever", "fish that sell well", "fishing gold", "how to make gold fishing", "fishing for money", "best fish to sell", "is fishing good gold forever", "what fish should i farm for gold", "how do i make gold with fishing in forever" }, a = "Fishing gold: sell Stonescale Eels, Oily Blackmouth and Firefin Snapper to alchemists, Nightfin/Sunscale and Mightfish to raiders' cooks, open Floating Wreckage for cloth bolts and leather, and win the Sunday Extravaganza for the Arcanite pole and coins. No reliable Forever gold-per-hour figures exist yet; prices peak when new raids open.", topic = "prof_gathering" }
add{ q = { "fishing legacy talent", "luremaster", "extra fish lure talent", "luremaster talent", "extra fish talent", "what does luremaster do", "legacy talent for fishing", "is luremaster worth it", "is luremaster legacy talent worth it for fishing", "luremaster rank 1", "legacy fishing talent what does it do" }, a = "Luremaster (Professions Legacy tree) gives a chance to catch an extra fish while a lure is active; beta reports put rank 1 at 25%. Working Overtime also speeds up Fishing skill-ups.", topic = "prof_gathering" }
add{ q = { "fishing trainer outside cities", "fishing trainer hinterlands", "fishing trainer feralas", "fishing trainer booty bay", "fishing trainer outside city", "neutral fishing trainer", "fishing trainer menethil", "where else can i train fishing", "is there a fishing trainer outside the capital cities", "fishing trainer menethil harbor", "fishing trainer in booty bay", "wheres a fishing trainer outside town" }, a = "Other Fishing trainers: Alliance - Harold Riggs (Menethil 8.2, 58.3), Matthew Hooper (Lakeshire 21.5, 51.0), Warg Deepwater (Loch Modan 40.5, 39.4), Paxton Ganter (Dun Morogh 35.6, 40.4), Donald Rabonne (Southshore 50.3, 64.3), Brannock (Feathermoon 32.2, 41.4), Androl Oakhand (Rut'theran 55.8, 93.5). Horde - Clyde Kellen (Brightwater Lake 67.1, 51.0), Uthan Stillwater (Bloodhoof 44.2, 63.9), Kil'Hiwana (Zoram Strand 10.7, 33.5), Lui'Mala (Shadowprey 22.7, 72.7), Katoom the Angler (Revantusk 80.5, 81.5). Neutral - Myizz Luckycatch (Booty Bay), Krix (Riverglades 79.3, 54.7).", topic = "prof_gathering" }
add{ q = { "fishing in hyjal", "fishing new zones forever", "where to fish at 300 forever", "fishing new zones", "where to fish at 300", "new fishing spots forever", "can you fish in hyjal", "riverglades fishing", "zephras isle fishing", "where do i fish at 300 in forever" }, a = "Forever's new zones mainly add fishing spots rather than new fish: Zephras Isle (starter fish), Riverglades (~level 40, Stranglethorn-like), and Mount Hyjal near the Summit of Eternity. For skill 260-300, Azshara, Winterspring, Un'Goro, Felwood and the Plaguelands remain the main spots for Stonescale Eel and Darkclaw Lobster.", topic = "prof_gathering" }
add{ q = { "how to get to mount hyjal", "mount hyjal access", "where is hyjal entrance", "hyjal level", "hyjal flight path", "how to get to hyjal", "hyjal entrance", "where is mount hyjal", "what level is hyjal", "how do i get into hyjal", "how do i get to mount hyjal from winterspring", "hyjal how to get there", "can i go to hyjal at 58" }, a = "Mount Hyjal is a level 60 zone (some content from the high 50s). Travel through Winterspring via Darkwhisper Gorge; flight paths connect Everlook to Tainted Foothills and on to the Summit of Eternity, the main hub with vendors and profession NPCs. Gathering there: Heavy Thorium Veins (Mining 300), Death Lotus chances with Lotus Claw gloves, fishing near the Summit.", topic = "prof_gathering" }
add{ q = { "guardians of hyjal profession recipes", "hyjal reputation professions", "rousing seed pod", "artisan's tier", "guardians of hyjal recipes", "hyjal rep professions", "artisans tier", "what does guardians of hyjal sell", "hyjal reputation profession rewards", "how to upgrade artisans tier", "what profession stuff does guardians of hyjal sell" }, a = "Guardians of Hyjal (Mount Hyjal reputation) sells high-level recipes; at Revered it unlocks the Rousing Seed Pod, which raises the Artisan's Tier equip limit to two. Malleable Essence of Nature from disenchanted raid items feeds Artisan's Tier crafting. The other Hyjal faction is Barkskin Burrow.", topic = "prof_gathering" }
add{ q = { "zephras isle professions", "skyborne starting zone trainers", "shen'dar village trainers", "valanaar trainers", "zephras isle trainers", "skyborne trainers", "shendar village trainers", "skyborne profession trainers", "where do skyborne learn herbalism", "zephras isle mining trainer", "what profession trainers are on zephras isle" }, a = "Zephras Isle (Skyborne starting zone) has gathering trainers usable by both factions: Herbalism - Halassa Fernbreeze (Shen'dar Village 43.1, 43.5) and Syriel Nightrain (Valanaar 57.9, 75.5); Mining - Messana Crestwind (Shen'dar 44.7, 44.5) and Halavuul Cragwind (Valanaar 65.4, 80.4); Skinning - Mendalass Tattermend (Shen'dar 43.2, 43.4) and Ishlee Breezewhisper (Valanaar 59.6, 75.9); Fishing - Fenn Fairweather (Shen'dar 45.0, 48.4) and Baelann Swiftcurrent (Valanaar 63.2, 75.7).", topic = "prof_gathering" }
add{ q = { "riverglades trainers", "powderfuse port", "riverglades mining trainer", "riverglades fishing trainer", "where is powderfuse port", "trainers in riverglades", "riverglades herbalism trainer", "what profession trainers are in riverglades", "riverglades profession trainers", "who trains mining in riverglades", "riverglades herb trainer", "where are the trainers in riverglades" }, a = "Riverglades (new level ~32-40 contested zone between Ashenvale, Arathi and Stranglethorn) has neutral trainers at Powderfuse Port: Grungle teaches Mining (77.7, 51.9) and Krix teaches Fishing (79.3, 54.7). The zone is also a 150+ skinning area per Forever skinning guides.", topic = "prof_gathering" }
add{ q = { "swiftness potion", "how to make swiftness potion", "speed potion for farming", "best potion for farming herbs", "speed pot for farming", "best potion for herbing", "swiftness potion recipe", "potion to go faster while farming", "what pots for farming herbs", "how do i make swiftness potions for farming", "swiftness pot recipe", "speed potion for herbing" }, a = "Swiftness Potion: alchemists make it from Swiftthistle + Briarthorn (Classic recipe, Alchemy 60); it gives a short burst of run speed. Herbalists get Swiftthistle free from Mageroyal and Briarthorn nodes. Use it between distant nodes, to beat others to a Black Lotus, or to escape.", src = "classic", topic = "prof_gathering" }
add{ q = { "free action potion", "free action for farming", "how to make free action potion", "fap for farming", "free action potion recipe", "fap mats", "where to get free action pots", "do i need free action for farming", "how do i make free action potions", "free action pot", "fap recipe mats" }, a = "Classic baseline: Free Action Potion (Alchemy) uses Blackmouth Oil (from Oily Blackmouth fish) plus Stranglekelp, and makes you immune to stuns and movement impairment for a short time - useful against roots, slows and world PvP while farming contested nodes.", src = "classic", topic = "prof_gathering" }
add{ q = { "arclight spanner", "do i need arclight spanner", "where to buy arclight spanner", "engineering tool", "arclight spanner vendor", "what is arclight spanner for", "engi tool where", "do i need an arclight spanner for engineering", "arclight spanner where to buy", "engineering spanner", "do engineers need a spanner", "what tool does engineering need" }, a = "Classic baseline: the Arclight Spanner is the tool Engineers need in their bags for many recipes; buy it from an engineering supply vendor or craft it early in Engineering. It's not needed for Mining itself, but Mining + Engineering is a common pair (Goblin Mining Helmet +5 Mining, Bright Baubles and Fish Attractors for fishing).", src = "classic", topic = "prof_gathering" }
add{ q = { "can i have three gathering professions", "herbalism and mining together", "double gathering", "best profession combo for gold", "can i have 3 gathering profs", "herb and mining together", "best prof combo for gold", "can i take herb mining and skinning", "how many professions can i have", "is double gathering good forever", "can i have herbalism mining and skinning all at once" }, a = "You get two primary professions; Fishing, Cooking and First Aid are secondary and don't use a slot. Herbalism + Mining (both node-based, tracked one at a time) is the classic gold setup; Skinning pairs well with either if you kill beasts. Gatherer + matching crafter (Herb/Alchemy, Mining/Blacksmithing or Engineering, Skinning/Leatherworking) is better if you want consumables or gear.", topic = "prof_gathering" }
add{ q = { "track herbs and minerals at same time", "switch tracking herbs ore", "find minerals and find herbs", "track herbs and ore at once", "switch tracking", "find minerals and herbs at same time", "can i track herbs and minerals together", "how to swap tracking fast", "tracking both herbs ore", "dual tracking forever", "can i track herbs and minerals at the same time" }, a = "You can only have one gathering track active. Find Herbs and Find Minerals don't work together, so herb+mining players toggle between them (Find Herbs does work alongside Hunter tracking and Find Treasure).", topic = "prof_gathering" }
add{ q = { "what pairs with herbalism", "what profession goes with mining", "what goes with skinning", "what goes with herbalism", "what goes with mining", "herbalism pair", "mining pair profession", "skinning pair profession", "best crafting prof for herbalism", "what crafting profession goes best with mining" }, a = "Pairings: Herbalism -> Alchemy (also some Enchanting/dye uses of Scarce herbs). Mining -> Blacksmithing or Engineering. Skinning -> Leatherworking (also some Tailoring, Engineering, Blacksmithing recipes). Fishing -> Cooking (wreckages also feed Tailoring and Leatherworking).", topic = "prof_gathering" }
add{ q = { "ah deposit forever", "auction house cost to post", "should i sell ore or bars", "ah deposit", "sell ore or bars", "how much to post on ah", "should i smelt before selling", "minimum ah deposit", "should i sell ore or bars on the ah in forever", "ah posting cost", "ore or bars which sells better" }, a = "Since the Nov 10 hotfix, the minimum AH deposit is 1 copper (was 1 silver), so posting cheap herbs and ore in small stacks costs almost nothing. Compare raw ore vs smelted bar prices before posting, and price against recent completed sales, not listings.", topic = "prof_gathering" }
add{ q = { "thorium farming route un'goro step by step", "un'goro mining route", "how to farm thorium un'goro", "ungoro thorium route", "ungoro mining route", "how to farm thorium ungoro", "un goro thorium path", "thorium route step by step", "best mining route ungoro", "ungoro mining loop", "whats the best route to farm thorium in ungoro" }, a = "Un'Goro Thorium route:\n1. Enter from Tanaris or Silithus (Marshal's Refuge has a flight path).\n2. Track Minerals and run the outer rim of the crater clockwise, hugging the cliff walls and slopes where Small and Rich Thorium Veins spawn.\n3. Swing through the inner caves/hills only if a node shows on the minimap.\n4. Pick herbs on the way if you're also an herbalist (Golden Sansam, Dreamfoil, Silversage).\n5. Avoid Devilsaurs' paths; vendor and mail at Marshal's Refuge.\nRich Thorium can also drop Arcane Crystals.", src = "classic", topic = "prof_gathering" }
add{ q = { "felwood herb route", "how to farm herbs in felwood", "plaguebloom farming", "farm herbs felwood", "plaguebloom farm", "felwood herbing", "where is plaguebloom", "felwood herb loop", "best route in felwood for herbs", "whats the best herb route in felwood" }, a = "Felwood herb farming: fly to Talonbranch Glade or Bloodvenom Post, track herbs and run the length of the zone north-south along the road and the satyr/furbolg camps, picking Plaguebloom, Gromsblood, Dreamfoil, Golden Sansam and Sungrass. Jadefire satyrs on the way drop Felcloth. Plaguebloom (285) sells around 77s per pick.", src = "classic", topic = "prof_gathering" }
add{ q = { "winterspring farming route", "icecap farming", "winterspring herbs and ore", "winterspring farm route", "icecap farm", "where to farm icecap", "winterspring farming", "icecap location", "winterspring mining and herb", "is winterspring good for farming herbs and ore" }, a = "Winterspring (level 55-60) is a strong double-gather zone: Icecap (290) and Black Lotus for herbalists, Rich and Small Thorium plus Arcane Crystals for miners, and frostsabers, chimaeras and bears (Rugged Leather) for skinners. Base at Everlook; some rich ore spots have elites. It's also the road into Mount Hyjal.", topic = "prof_gathering" }
add{ q = { "plaguelands herb route", "eastern plaguelands herbs", "where to get arthas tears", "epl herbs", "wpl herbs", "arthas tears farm", "plaguelands herbing", "where do i farm arthas tears in the plaguelands", "epl herb route", "plaguelands herb farming route" }, a = "Western and Eastern Plaguelands: Plaguebloom, Arthas' Tears (220, ~79s per pick), Dreamfoil, Sungrass, Golden Sansam (EPL), plus Black Lotus in EPL. Ore here is a Mithril/Truesilver/Thorium mix along the mountain edges, weaker for pure Thorium than Un'Goro or Winterspring.", topic = "prof_gathering" }
add{ q = { "is gathering bad in pvp server", "world pvp gathering tips", "getting ganked while farming", "gathering on pvp server", "world pvp gathering", "pvp server farming tips", "how to farm on pvp server", "keep getting ganked while herbing", "how do i avoid getting ganked while farming on pvp", "pvp server gathering", "how not to get ganked herbing" }, a = "On PvP rulesets, contested 50-60 zones (Silithus, Un'Goro, Winterspring, Felwood, EPL) see a lot of world PvP, and enemies can also find your campsite. Farm off-peak, carry Swiftness/Free Action potions, keep a mount, and consider a less popular zone. Blizzard capped zone populations further on PvP realms in the Nov 9 hotfix.", topic = "prof_gathering" }
add{ q = { "skinning trainer levels", "when do i train skinning", "what skill to train expert skinning", "journeyman expert artisan levels", "what skill expert skinning", "when should i train next rank", "skinning rank level requirements", "level needed for artisan skinning", "when should i train journeyman expert and artisan skinning", "what level to train artisan skinning", "skinning ranks when to train", "skinning stuck at 150" }, a = "Train the next rank before you hit the cap: Journeyman (cap 150) needs character level 10, Expert (cap 225) level 20, Artisan (cap 300) level 35. In practice visit the trainer around skill 50-75, 125-150 and 200-225. Junior starting-zone trainers stop at 75.", topic = "prof_gathering" }
add{ q = { "rockslicer and shovel", "gather without profession", "can i mine without mining", "rockslicer where", "mine without the profession", "graverobbers shovel and rockslicer", "borrowed gathering tools", "can i gather without having the profession in forever", "can i herb without herbalism", "mine ore without mining skill", "rock slicer" }, a = "Forever has two 'borrowed' gathering tools: the Rockslicer (Rhahk'Zor, The Deadmines; 30 uses) mines Copper, Tin, Silver and Iron without Mining, and the Graverobber's Shovel (Dextren Ward, The Stockade; 10 uses) gathers Grave Moss without Herbalism. Tauren can also pick a duplicated herb without Herbalism via Cultivation.", topic = "prof_gathering" }
add{ q = { "mining route alliance", "alliance mining leveling zones", "where should i mine as alliance", "alliance mining zones", "where to mine as alliance", "alliance mining leveling path", "mining guide alliance", "best zones to level mining alliance", "where should i level mining as alliance", "alliance mining route", "mining zones alliance side" }, a = "Alliance mining path: Elwynn/Dun Morogh copper -> Westfall and Loch Modan (Copper/Tin) -> Wetlands and Duskwood (Tin, Silver) -> Arathi Highlands and Stranglethorn (Iron, Gold, Silver) -> Badlands and Hinterlands (Mithril, Truesilver) -> Searing Gorge/Burning Steppes (Dark Iron) -> Un'Goro/Winterspring/Plaguelands (Thorium). Train at Brock Stoneseeker in Thelsamar or Geofram Bouldertoe in Ironforge.", topic = "prof_gathering" }
add{ q = { "mining route horde", "horde mining leveling zones", "where should i mine as horde", "horde mining zones", "where to mine as horde", "horde mining leveling path", "mining guide horde", "best zones to level mining horde", "where should i level mining as horde", "horde mining route", "mining zones horde side" }, a = "Horde mining path: Durotar/Tirisfal copper -> Silverpine and The Barrens (Copper/Tin) -> Hillsbrad, Wetlands, Duskwood (Tin, Silver) -> Arathi, Alterac, Stranglethorn, Thousand Needles (Iron, Gold) -> Badlands, Hinterlands, Tanaris, Feralas (Mithril, Truesilver) -> Searing Gorge (Dark Iron) -> Un'Goro/Winterspring/Silithus (Thorium). Train at Makaru in Orgrimmar, Krunn in Razor Hill, or Pikkle in Gadgetzan.", topic = "prof_gathering" }
add{ q = { "herbalism route alliance", "alliance herb leveling zones", "where to herb as alliance", "herb route alliance", "alliance herb zones", "alliance herbalism path", "herbalism guide alliance", "best zones to level herbalism alliance", "where should i level herbalism as alliance", "alliance herbalism route", "herb zones alliance side" }, a = "Alliance herb path: Teldrassil or Elwynn (1-75) -> Loch Modan or Darkshore (75-115) -> Wetlands from Menethil, Arathi (115-170) -> Stranglethorn (170-205) -> Tanaris (205-230) -> Hinterlands, Feralas if busy (230-270) -> Felwood, Un'Goro, Plaguelands (270-300). Trainers on the way: Kali Healtouch (Thelsamar), Telurinon Moonshadow (Menethil), Alma Jainrose (Lakeshire).", topic = "prof_gathering" }
add{ q = { "herbalism route horde", "horde herb leveling zones", "where to herb as horde", "herb route horde", "horde herb zones", "horde herbalism path", "herbalism guide horde", "best zones to level herbalism horde", "where should i level herbalism as horde", "horde herbalism route", "herb zones horde side" }, a = "Horde herb path: Mulgore or Durotar (1-75) -> The Barrens (75-115) -> Hillsbrad via Tarren Mill (115-170) -> Stranglethorn via Grom'gol (170-205) -> Tanaris (205-230) -> Hinterlands with Revantusk Village (230-270) -> Felwood, Un'Goro, Plaguelands (270-300). Trainers on the way: Mishiki (Sen'jin), Aranae Venomblood (Tarren Mill), Angrun (Grom'gol), Ruw (Camp Mojache).", topic = "prof_gathering" }
add{ q = { "blasted lands skinning", "skinning 235 where", "scorpok stinger snickerfang", "skinning 235", "scorpok stinger", "snickerfang hyena", "where to skin at 235", "redstone basilisk skinning", "blasted lands skinning route", "is blasted lands good for skinning" }, a = "Blasted Lands is the 235-275 skinning stop: Redstone Basilisk (from 235), Ashmane Boar (240), Snickerfang Hyena and Scorpok Stinger (245). The same beasts drop the lungs, gizzards, pincers, jowls and brains for the Blasted Lands buff-item quests, plus vendor loot.", topic = "prof_gathering" }
add{ q = { "silithus skinning", "stonelash scorpid", "heavy scorpid scale farm", "heavy scorpid scale", "where to farm scorpid scale", "silithus scorpids skinning", "where do i farm heavy scorpid scale in silithus", "stonelash scorpid skinning", "where do i skin scorpids", "silithus skinning farm", "heavy scorpid scale where" }, a = "Silithus Stonelash scorpids give Rugged Leather and Heavy Scorpid Scale: Stonelash Scorpid (from 270), Stonelash Pincer (280), Stonelash Flayer (285). Good level 60 skinning farm if the zone isn't crowded.", topic = "prof_gathering" }
add{ q = { "what is wow forever", "what is forever", "is forever classic+", "forever vs classic era", "how is forever different from classic", "what is world of warcraft forever", "is forever just classic", "whats different in forever", "forever vs vanilla", "is forever classic plus", "explain forever to me", "what even is wow forever is it like classic era", "forever classic+ or new game", "my buddy says forever is classic plus whats actually new" }, a = "Forever is Blizzard's Classic+ game: the Vanilla world rebooted right before Molten Core, with level 60 as the permanent cap. It adds over 1,000 new quests, new zones (Zephras Isle, Riverglades, Shen'dralas, Mount Hyjal, Dalaran in Alterac), 9 new dungeons, new raids, the Skyborne race, 6 new race/class combos, reworked talents (27 specs), transmog, the Legacy system, Camping, and modern UI like a built-in damage meter. There is no Outland, no flying and no expansions.", topic = "systems" }
add{ q = { "when did forever launch", "forever release date", "when did forever beta start", "forever launch time", "when did forever come out", "forever launch date", "forever beta date", "when was forever released", "what day did forever launch", "when did the forever beta open", "release date of wow forever", "what time did forever go live" }, a = "The beta opened September 17, 2026 (stress test Oct 21, name reservation Oct 27). Live launch was November 4, 2026 at 23:00 UTC (evening of Nov 4 in the Americas, Nov 5 in Europe). Blizzard called it WoW's biggest launch ever by peak concurrent players.", topic = "systems" }
add{ q = { "will forever get expansions", "will level cap go above 60", "will tbc come to forever", "is there outland in forever", "will there be expansions in forever", "will forever get tbc", "level cap above 60", "outland in forever", "will the dark portal open", "will forever ever go past 60", "is forever getting burning crusade", "any chance forever gets tbc or a higher level cap later" }, a = "No. Blizzard says the Dark Portal never reopens in Forever: no expansions, no Outland, and the level cap stays at 60 indefinitely. New content comes as raids, dungeons, zones and quests within Azeroth instead.", topic = "systems" }
add{ q = { "forever roadmap", "when do raids open", "forever content phases", "whats coming to forever", "forever phase 2", "what is coming next in forever", "when do raids come out", "forever phases", "next phase forever", "when is hardcore coming", "whats the content schedule for forever", "whats the roadmap for forever after launch", "when does phase 2 start in forever" }, a = "Roadmap: raids (Barrow Deeps, Hyjal Summit, Onyxia's Lair) unlock December 9, 2026. Hardcore arrives winter 2026/27. Spring 2027: 2 new raids, 2 new dungeons, new quests and area, a legendary questline, PvP season refresh. Summer 2027: a revamped iconic raid, another new raid, more world content, 2 more dungeons, PvP refresh, profession and Legacy updates.", topic = "systems" }
add{ q = { "forever raids list", "what raids are in forever", "barrow deeps raid size", "hyjal summit how many players", "is molten core in forever", "forever raid list", "barrow deeps size", "how many people hyjal summit", "is mc in forever", "onyxia forever", "is ony in forever", "what raids open on dec 9", "how many players is barrow deeps and hyjal", "is molten core and bwl in forever" }, a = "Raids unlocking Dec 9: Barrow Deeps (10-player, new, Mount Hyjal), Hyjal Summit (20-player, new, Mount Hyjal) and Onyxia's Lair (40-player, Dustwallow Marsh). Molten Core is not open at launch; the world starts just before it, and a revamped iconic raid is on the summer 2027 roadmap.", topic = "systems" }
add{ q = { "do i need to buy forever", "is forever free with sub", "forever price", "forever editions", "how much is skyborne pack", "is forever free with my sub", "do i have to buy forever", "how much is forever", "price of forever", "skyborne pack price", "forever editions price", "do i need to pay extra for forever", "do i need to buy forever separately or is it with game time" }, a = "Forever is included with a normal WoW subscription or Game Time. Optional packs: Skyborne Heroic Pack $29.99 (Skyborne race, Zephras Isle start, Cerulean Prideclaw mount, transmog, toy), Skyborne Epic Pack $59.99 (adds beta access, 30 days game time, Veteran Adventurer's Loyal Companion mount, pets, tabards), Warcraft Forever Collection $79.99 (adds WC3 Reforged; sold until Jan 11, 2027).", topic = "systems" }
add{ q = { "how do i unlock skyborne", "is skyborne free", "can i play skyborne without paying", "skyborne paywall", "how do i get skyborne", "skyborne locked", "do i have to pay for skyborne", "unlock skyborne race", "can i make skyborne without the pack", "why cant i select skyborne at character creation", "do i have to pay to play skyborne", "skyborne is greyed out how do i unlock it" }, a = "Skyborne requires the Skyborne Heroic Pack ($29.99) or a higher edition. Anyone can visit Zephras Isle, but the Skyborne race and its starting questline are locked behind the pack.", topic = "systems" }
add{ q = { "what realm should i pick", "forever servers", "are there realms in forever", "forever mega realm", "forever rulesets", "what server should i pick", "which realm", "forever realms", "is there servers in forever", "mega realm", "what ruleset do i pick", "forever realm list", "what realm should i make my char on in forever", "theres no server list in forever what do i pick" }, a = "Forever is realmless: one mega-realm per ruleset per region. You pick a ruleset instead of a server: Normal (PvE, PvP optional), PvP, RP, RP-PvP, and Hardcore (coming later). Rulesets stay separate, and you can only group with your own faction on the same ruleset.", topic = "systems" }
add{ q = { "how does layering work in forever", "why cant i see my friend", "friend invisible in group", "different layer party", "layering", "what is layering", "how does layering work", "cant see my friend", "friend invisible", "my friend is in my party but i cant see him", "why is my group member invisible", "my friend is in my group but invisible whats going on" }, a = "Each ruleset's world is split into copies called layers; players on different layers can't see each other. If a party member is invisible, you're on separate layers. You can't switch manually; you join your friend's layer by grouping with them.", topic = "systems" }
add{ q = { "how to change layer", "how do i switch layers", "layer hop forever", "refresh now layer", "world refresh in 30 minutes", "change layer", "switch layer", "layer hop", "how to layer hop", "refresh now", "how do i get on my friends layer", "how to join friends layer", "how do i get on the same layer as my friend", "how to switch layers in forever" }, a = "Join a party with someone on the target layer (same ruleset and faction). A notice appears at the lower left; get out of combat, stand somewhere safe and click it, then pick Refresh Now to reload onto the party's layer. If you ignore it, the world refreshes on its own after a 30-minute timer.", topic = "systems" }
add{ q = { "does language affect who i see", "forever language setting", "why are players speaking spanish", "change preferred language", "language setting", "why is everyone speaking spanish", "change language", "preferred language", "language layers", "does my language setting change who i play with", "why are people speaking portuguese", "why am i only seeing spanish speakers in my zone", "does the language setting affect which layer im on" }, a = "Yes. Forever groups you with players who share your preferred online language (in the US region, for example English, LatAm Spanish or Brazilian Portuguese). You can change it in settings, with about a one-day delay before it takes effect.", topic = "systems" }
add{ q = { "zones too crowded", "layer population reduced", "why is my zone empty", "forever zone population", "zone too crowded", "layer cap", "zone population", "layer population lowered", "starting zone too many players", "why is my zone dead now", "the starting zone is packed how many people per layer", "why does my zone feel empty after the patch" }, a = "On Nov 9-10 Blizzard lowered the player cap per layer in heavily congested zones, with a bigger cut on the PvP ruleset, and said it will keep adjusting. Some players felt zones became too quiet after this; Blizzard said it's monitoring.", topic = "systems" }
add{ q = { "faction balance forever pvp", "can't make horde character", "character creation locked faction", "forever faction imbalance", "faction balance", "cant make horde", "faction locked", "character creation locked", "faction imbalance", "why cant i create alliance", "faction lock pvp forever", "why does it say i cant create a horde character", "is faction creation locked to balance the pvp server" }, a = "Blizzard tightened character creation to push regions toward 50/50. The worst split was about 55/45. In the short term it's harder to create Horde on North American PvP and Alliance on EU RP-PvP. Blizzard found no evidence trial accounts skewed balance.", topic = "systems" }
add{ q = { "forever character names", "first and last name", "are names unique forever", "name format forever", "names forever", "unique names", "name format", "how do names work in forever", "do i need a last name", "are names per server", "do i need a first and last name in forever", "are character names unique per region" }, a = "Characters have a first and last name, and names are unique per region (not per server, since there are no servers). Early name reservation in October allowed up to three characters per account.", topic = "systems" }
add{ q = { "is there hardcore in forever", "when does hardcore come out forever", "forever hardcore release", "hardcore ruleset", "hardcore forever", "is hardcore out", "hardcore release date", "when is hardcore", "hardcore ruleset forever", "is there hc in forever", "when does hc come out", "when does hardcore come out in forever", "is there a hardcore ruleset at launch" }, a = "Hardcore wasn't in at launch. It's slated for winter 2026/27, after raids open; no exact date yet. It's a permanent-death ruleset, and Blizzard says much of Forever was designed with Hardcore in mind.", topic = "systems" }
add{ q = { "what happens when you die in hardcore forever", "hardcore death transfer", "can i revive hardcore character", "hardcore death", "die in hardcore", "revive hardcore character", "what happens if i die in hc", "can i keep playing after hardcore death", "dead hc character transfer", "what happens when my hardcore character dies in forever", "can i transfer my dead hc char to normal" }, a = "A dead Hardcore character can transfer to another ruleset (Normal, PvP or RP) and continue there. Blizzard also floated a dedicated space for Mak'gora duels to the death.", topic = "systems" }
add{ q = { "does legacy work on hardcore", "hardcore legacy points", "legacy hardcore separate", "legacy hardcore", "does legacy carry to hardcore", "legacy on hc", "does legacy work in hardcore", "hardcore legacy separate", "do my legacy points from normal work on hardcore" }, a = "Legacy is one-way for Hardcore: points and rewards earned on Hardcore carry to the other rulesets, but progress from other rulesets doesn't apply to Hardcore characters. Hardcore has its own Legacy challenges in place of the PvP ones.", topic = "systems" }
add{ q = { "is leveling faster in forever", "forever xp curve", "how much xp to 60", "is forever leveling slower than classic", "leveling speed forever", "xp curve", "is leveling slower", "is leveling faster than classic", "xp to level 60 forever", "how long to level in forever", "is forever leveling slower than classic era", "how much total xp to hit 60 in forever" }, a = "The 1-60 XP curve is the Classic one: about 4.08 million total XP (1.15M to reach 40). Combat is deliberately slow, roughly 10-15 seconds per normal mob solo, so most estimates put a first 60 at 100+ hours played. The world-first party of five hit 60 a bit over 3 days after launch using big AoE dungeon pulls.", topic = "systems" }
add{ q = { "best way to level forever", "should i quest or dungeon", "dungeon leveling forever", "is dungeon grinding good forever", "best way to level", "quest or dungeon", "dungeon leveling", "dungeon grind", "fastest way to level forever", "should i spam dungeons to level", "is dungeon spam good in forever", "should i quest or spam dungeons to level in forever", "whats the fastest way to level in forever" }, a = "Questing in the open world is the intended main path. Dungeon kill XP is far below Classic Era, while dungeon quests give big XP, so do each dungeon with its quests rather than spam it. Blizzard has raised dungeon kill XP twice since but says dungeons shouldn't beat questing.", topic = "systems" }
add{ q = { "dungeon xp changes", "dungeon xp nerf", "dungeon kill xp increased", "dungeon xp hotfix november 8", "dungeon xp", "dungeon xp hotfix", "dungeon xp changes forever", "dungeon kill xp", "did they nerf dungeon xp", "dungeon xp nov 8", "did blizzard nerf dungeon xp in forever", "what changed with dungeon xp in the hotfix" }, a = "Timeline: beta cut dungeon mob XP hard and boosted dungeon quest XP; Oct 1 halved the dungeon quest bonus; Oct 8 raised mob XP about 20%; Nov 8 (live) raised dungeon kill XP by 50%. Blizzard wants repeat runs to feel worthwhile without dungeons outpacing questing.", topic = "systems" }
add{ q = { "can i get boosted in dungeons", "does a high level kill xp", "dungeon carry xp forever", "boosting forever", "dungeon boost", "carry xp", "can i get boosted", "do boosts work in forever", "high level carry dungeon", "is boosting dead in forever", "can my 60 friend boost me through dungeons for xp", "is dungeon boosting worth it in forever" }, a = "High-level boosting gives little: any party member more than 12 levels above a dungeon mob zeroes that kill's XP for everyone. Quest credit is still possible. The LFG tool has a 'Carry Offered' playstyle tag, but kill-XP boosting was the target of these changes.", topic = "systems" }
add{ q = { "group xp penalty", "does grouping reduce xp", "party xp forever", "is it better to solo", "group xp", "party xp", "solo or group", "xp in a group", "party xp bonus", "does grouping lower my xp in forever", "should i level solo or with a group" }, a = "Kill XP is shared: in a 5-player party each kill's XP is split five ways then multiplied by 1.4, so a 100 XP mob gives 28 each. Quest turn-in XP isn't reduced by grouping. Since Oct 8, level-based kill XP adjustment is per player again, as in Classic Era. Raid groups don't get quest objective credit.", topic = "systems" }
add{ q = { "quest xp penalty low level", "gray quests xp", "when do quests lose xp", "gray quest xp", "low level quest xp", "quest xp penalty", "when do quests stop giving xp", "do gray quests give xp", "low quests xp", "do gray quests still give xp", "how much xp do low level quests give" }, a = "Quests 5+ levels below you are gray and lose 10-20% XP per extra level below. Green is 3-4 below, yellow within 2, orange 3-4 above, red 5+ above. Several quest XP values were retuned before launch.", topic = "systems" }
add{ q = { "xp to gold at 60", "do quests give gold at 60", "why do quests give less gold at 60", "quest gold forever", "quest gold at 60", "xp to gold", "quests give gold at 60", "saving quests for 60", "do quests give gold at max level", "less gold at 60", "should i save quests for 60 to get gold", "why do my quests give less gold at 60" }, a = "Forever removed the XP-to-gold conversion for quests turned in at 60, so saving quests for 60 doesn't pay off. To compensate, a Nov 10-11 hotfix made most quests level 48+ grant some gold, and that amount doesn't change at 60.", topic = "systems" }
add{ q = { "rested xp forever", "how does rested work", "rested xp cap", "how fast does rested build", "rested xp", "rested cap", "max rested xp", "rested rate", "how much rested xp can i build up", "how fast does rested xp build in an inn" }, a = "Rested builds at 5% of your level's XP bar per 8 hours in an inn or city, including offline, up to 150% of a level (30 bubbles), about 10 days to fill. It doubles mob kill XP until used up; quests and exploration aren't boosted. Legacy's Well Rested talent adds 4% accrual and cap per rank (5 ranks).", topic = "systems" }
add{ q = { "how to get rested xp outside inn", "camp tent rested", "cozy sleeping bag", "portable rested xp", "rested outside inn", "camp tent", "sleeping bag rested", "portable rested", "how to get rested in the wild", "camp tent rested xp", "how can i get rested xp without going to an inn", "how does the camp tent give rested" }, a = "Two portable options: the Leatherworking Camp Tent at a campfire gives a Rested buff for an hour (persists through death, has its own Boosted Rest cooldown). The Cozy Sleeping Bag, from a scavenger-hunt quest chain starting at level 14 in Westfall or the Barrens, counts as a rested area even logged out and gives up to 3 Well-Rested stacks (+1% XP each).", topic = "systems" }
add{ q = { "xp buff food", "well fed xp", "does food give xp forever", "xp boost consumables", "xp food", "does food give xp", "xp consumables", "xp buff", "xp boost food", "does well fed boost xp", "does well fed give bonus xp in forever", "any food that boosts xp" }, a = "Crafted Cooking food gives Well Fed, which in Forever adds +5% kill XP for about 15 minutes on top of stats (lost on death). It stacks with camp buffs and the Cozy Sleeping Bag.", topic = "systems" }
add{ q = { "fastest leveling class forever", "best class to level", "which class levels fastest", "fastest leveling class", "best leveling class", "quickest class to level", "easiest class to level", "best class for leveling forever", "which class levels fastest in forever", "whats the best class for leveling solo" }, a = "In beta, Hunter leveled fastest, with Warlock and Mage close behind; Warrior and Priest were slowest. The gap was described as a matter of days /played, not weeks.", topic = "systems" }
add{ q = { "where are world buffs", "warchiefs blessing razor hill", "might of stormwind goldshire", "rend buff locations forever", "world buffs", "warchiefs blessing", "might of stormwind", "rend buff", "where can i get rend buff", "world buff locations", "where can i get warchiefs blessing in forever", "where do i get rend buff as alliance" }, a = "Rend Blackhand world buffs (Warchief's Blessing for Horde, Might of Stormwind for Alliance) now also drop in Razor Hill (guard tower) and, via Stormwind Criers, in Goldshire, Lakeshire and Sentinel Hill, besides Orgrimmar, the Crossroads and Stormwind. World buffs don't work inside raids or dungeons in Forever.", topic = "systems" }
add{ q = { "do world buffs work in raids", "chronoboon forever", "world buffs removed raids", "world buffs in raids", "chronoboon", "world buffs removed", "are world buffs in dungeons", "do wbuffs carry into raids", "do world buffs carry into raids in forever", "is there a chronoboon in forever" }, a = "No. World buffs are removed when you enter dungeons and raids in Forever, so they only help in the open world. The Chronoboon Displacer exists but is only useful for open-world play.", topic = "systems" }
add{ q = { "when can i get a mount", "mount level forever", "how much is riding", "mount cost forever", "level 40 mount price", "mount level", "riding cost", "mount cost", "how much for first mount", "level 40 mount", "mount price", "what level can i get my first mount", "how much is riding at 40 in forever" }, a = "Apprentice Riding unlocks at level 40 for 100g at your race's riding trainer and includes your first mount (+60% speed). Extra colors cost 20g each. Journeyman Riding at 60 costs 1,000g, and epic mounts are 200g each (+100% speed).", topic = "systems" }
add{ q = { "epic mount cost", "how much for epic mount forever", "journeyman riding cost", "level 60 mount", "epic mount", "journeyman riding", "100% mount", "how much for epic mount", "fast mount cost", "how much gold do i need for epic mount at 60", "whats the cost of journeyman riding" }, a = "At 60, Journeyman Riding costs 1,000g plus 200g per swift mount, giving +100% speed. Honored with your home faction cuts 10% off training and mounts; the Legacy Bartering talent stacks for up to 20% off mounts (not training).", topic = "systems" }
add{ q = { "mount discount", "honored mount discount", "cheaper mount forever", "bartering legacy mount", "honored discount", "cheaper mount", "bartering legacy", "how to get mount cheaper", "honored mount", "reputation discount mount", "how do i get a discount on my mount", "does honored rep make riding cheaper" }, a = "Honored with your home race faction gives 10% off riding training and mounts. The Legacy Bartering talent (2 ranks, -5% vendor prices each) also discounts mounts; together up to 20% off mounts, but only Honored discounts training.", topic = "systems" }
add{ q = { "can i buy other race mounts", "cross race mount", "exalted mount other race", "nightsaber as human", "other race mount", "exalted mount", "nightsaber human", "can i buy a different race mount", "buy another races mount", "mount from other race", "can my human ride a nightsaber", "how do i buy another races mount" }, a = "To learn riding from or buy mounts at another race's vendor, you need Exalted with that race. Since the Nov 10 hotfix all racial vendor mounts are Bind on Pickup, so they can't be traded or sold.", topic = "systems" }
add{ q = { "where is the riding trainer", "horse trainer elwynn", "ram trainer dun morogh", "wolf mount orgrimmar", "raptor trainer", "kodo vendor", "riding trainer", "where is riding trainer", "horse trainer", "ram trainer", "wolf trainer", "kodo trainer", "where do i learn to ride", "where do i learn riding as an orc", "where is the ram trainer in dun morogh" }, a = "Riding trainers/vendors: Human - Randal Hunter & Katie Hunter, Elwynn Forest (84,65). Dwarf - Amberstill Ranch, Dun Morogh (63,50). Gnome - Steelgrill's Depot, Dun Morogh (49,48). Night Elf - Jartsam & Lelanai, Darnassus (38,16). Orc - Kildar & Ogunaro Wolfrunner, Orgrimmar (69,13). Troll - Sen'jin Village (55,75). Tauren - Bloodhoof Village, Mulgore (47,62). Undead - Brill (60,52).", topic = "systems" }
add{ q = { "warlock free mount", "felsteed quest", "warlock mount level 40", "felsteed no riding skill", "warlock mount", "felsteed", "free warlock mount", "lock mount quest", "summon felsteed quest", "warlock level 40 mount", "felsteed needs riding", "how do i get the free warlock mount", "does my lock need riding skill for felsteed" }, a = "Warlocks get a free Felsteed from Strahad Farsan in Ratchet at level 40 via the Summon Felsteed quest. A launch bug didn't grant riding skill; fixed Nov 9. If you finished it earlier, summon the Felsteed once to receive Apprentice Riding.", class = "WARLOCK", topic = "systems" }
add{ q = { "paladin free mount", "paladin charger quest", "tome of nobility", "undead paladin mount", "paladin mount", "pally mount", "charger quest", "free paladin mount", "paladin warhorse", "how do paladins get their free mount", "how does an undead paladin get a mount" }, a = "Paladins get their level 40 warhorse free through a class quest (Alliance: The Tome of Nobility). Forsaken Paladins have their own mount quests. Epic class mounts at 60 come from a long, costly questline.", class = "PALADIN", topic = "systems" }
add{ q = { "are there flying mounts", "can you fly in forever", "flying forever", "flying mounts", "can you fly", "flying in forever", "will there be flying", "is there flying", "no flying", "can you fly anywhere in forever", "are there flying mounts in forever" }, a = "No flying mounts, ever. Travel is by ground mount, flight path, boat, zeppelin, skyboat, mage portals or warlock summons. The Legacy talent Frequent Flier gives 50% off flight paths and 20% faster flights.", topic = "systems" }
add{ q = { "legacy mount", "spectral bear mount", "how to get spectral bear", "reins of the spectral bear", "spectral bear", "legacy reward mount", "legacy 55 point mount", "how many legacy points for the spectral bear", "how do i get the spectral bear mount", "what do i get from legacy points mount reward", "is there a mount from legacy" }, a = "Reins of the Spectral Bear (100% speed mount) is the 55-point Legacy reward. Earlier rewards: 15 points Ironforge Air Rifle replica toy, 25 Spectral Bear Cub pet, 40 Spectral Bear Tabard. Claim them from Innkeeper Wiley in Ratchet.", topic = "systems" }
add{ q = { "store mount riding", "do i need riding for prideclaw", "cerulean prideclaw level", "store mount", "prideclaw", "cerulean prideclaw", "do store mounts need riding", "store mount level", "do i need riding skill for the cerulean prideclaw", "can i use my store mount before 40" }, a = "Store mounts (Cerulean Prideclaw, Veteran Adventurer's Loyal Companion) still need you to buy Riding skill. The Prideclaw appeared as level 60 in datamines, so using it at 40 isn't confirmed.", topic = "systems" }
add{ q = { "how do i reset talents", "respec forever", "where to respec", "unlearn talents", "reset talents", "respec", "how to respec", "respec cost", "how do i reset my talents", "how do i respec my talents in forever", "how much does it cost to reset talents" }, a = "Talk to your class trainer and choose the option to unlearn class or Legacy talents. Fees climb with each reset (1g, 5g, 10g and so on) up to a 50g cap, then decay back down toward 1g over time (roughly weekly).", topic = "systems" }
add{ q = { "dual spec forever", "when do i get dual spec", "dual spec cost", "how to swap specs", "dual spec", "swap spec", "dual spec level", "how to dual spec", "can i get dual spec in forever", "how much is dual spec and what level" }, a = "Dual Talent Specialization is learned from your class trainer at level 40 for 50g. You can swap freely out of combat, but not in battlegrounds. Each spec has its own respec fee, which decays toward 1g over time.", topic = "systems" }
add{ q = { "when do i get talent points", "first talent point level", "talented legacy", "talent points", "first talent point", "when do talents start", "what level talents", "talent level 10", "when do i get my first talent", "what level do i get my first talent point", "how does the talented legacy work" }, a = "Talent points start at level 10 as in Classic (51 total by 60). The Legacy talent Talented moves your first point one level earlier per rank, down to level 5 at 5 ranks, still capped at 51.", topic = "systems" }
add{ q = { "are talents different in forever", "forever talent trees", "specs reworked", "talents forever", "talent trees forever", "are talents different", "new talents", "how many specs forever", "talent changes forever", "are the talent trees different in forever", "did forever change the class specs" }, a = "Yes. Every class has three reworked talent trees (27 specs total), still 7 rows deep, with new abilities. Many former buff-upgrade talents became baseline. Abilities must still be bought from class trainers and aren't added to your spellbook or action bars automatically.", topic = "systems" }
add{ q = { "do i have to train spells", "spells not on my bar", "new spell not on action bar", "class trainer cost to 60", "train spells", "do i need to train spells", "spells not on bar", "new spell not on bar", "trainer cost", "class trainer", "do i learn spells automatically", "do i need to visit the trainer for new spells", "why didnt my new spell show up on my bars" }, a = "Yes, visit your class trainer to learn ranks; nothing is learned automatically. Since the Nov 2 notes, newly learned spells aren't auto-placed on bars, so drag them from the spellbook (P). Training from 1 to 60 costs about 206-207g for every class (Warlocks a bit less, since pet grimoires are folded in).", topic = "systems" }
add{ q = { "weapon skills forever", "do i need to level weapon skill", "weapon proficiency forever", "weapon skills", "do i need weapon skill", "weapon proficiency", "weapon skill forever", "level weapon skill", "weapon skill still a thing", "do i still need to level weapon skill in forever", "does weapon skill still exist in forever" }, a = "Weapon skills still exist: learn a weapon type from a weapon master, then level it by using it so you hit reliably. Blizzard kept them but toned down the bonus from +weapon skill items.", topic = "systems" }
add{ q = { "new race class combos", "forever new combos", "can alliance be shaman", "undead paladin", "orc mage", "troll warlock", "new combos", "alliance shaman", "dwarf shaman", "human hunter", "what new race class combos are in forever", "can alliance play shaman in forever" }, a = "Six new combos: Dwarf Shaman, Gnome Priest, Human Hunter, Orc Mage, Troll Warlock and Undead Paladin. All other Classic combos remain; Night Elf and Tauren gained nothing new. There is no free class choice; it's still race-locked.", topic = "systems" }
add{ q = { "skyborne classes", "what classes can skyborne be", "skyborne alliance or horde", "skyborne mage", "skyborne shaman", "what classes skyborne", "skyborne faction", "skyborne alliance", "skyborne horde", "skyborne druid", "can skyborne be mage", "what classes can skyborne play", "can skyborne be horde" }, a = "Skyborne pick a faction at creation. High Order (Alliance): Druid, Hunter, Mage, Rogue, Warrior. Windshaper (Horde): Druid, Hunter, Rogue, Shaman, Warrior. Only Alliance Skyborne can be mages and only Horde Skyborne can be shamans. Both start on Zephras Isle.", topic = "systems" }
add{ q = { "are tbc races in forever", "can i play blood elf", "draenei forever", "goblin worgen forever", "tbc races", "blood elf", "draenei", "goblin", "worgen", "can i be a blood elf", "new races forever", "can i play a blood elf in forever", "are there draenei or goblins in forever" }, a = "No. Only the 8 original races plus Skyborne are playable. Blood Elves, Draenei and all later races are not.", topic = "systems" }
add{ q = { "racials changed forever", "new racial abilities", "every race four racials", "racials", "racial changes", "new racials", "four racials", "racial abilities forever", "human racial", "orc racial forever", "did racials change in forever", "what are the new racials for my race" }, a = "Every race now has four racials, many new: e.g. Human Ruthless (+2% crit), Orc Shatter Curse, Tauren Plainsrunning (+3% mounted speed, no longer stacks in BGs), Troll Rapid Regeneration, Undead Touch of the Grave, Gnome Eureka!, Night Elf Elune's Light, Dwarf Artisan's Precision. Some races also get race-specific priest spells.", topic = "systems" }
add{ q = { "are addons allowed forever", "addon restrictions forever", "why doesnt my addon work", "does weakauras work forever", "combat addons forever", "addons allowed", "addon restrictions", "weakauras", "combat addons", "are addons banned", "addon rules forever", "are addons allowed in forever", "why is my combat addon broken in forever" }, a = "Forever uses the same addon rules as retail Midnight. Addons can restyle what the game shows but can't read secret combat values or compute decisions in combat, so WeakAuras-style logic, rotation helpers and others' debuff tracking are gutted. UI frames, bags, maps, quest helpers and HandyNotes still work. Classic Era addons often need Forever-specific updates.", topic = "systems" }
add{ q = { "details addon forever", "does details work", "dps meter addon forever", "details", "details addon", "dps meter addon", "details meter forever", "third party dps meter", "skada forever", "does details work in forever", "can i use a dps meter addon in forever" }, a = "Third-party meters like Details can only re-skin Blizzard's own meter data, which is less detailed, so advanced breakdowns are gone. Use the built-in Damage Meter instead.", topic = "systems" }
add{ q = { "how to turn on damage meter", "built in dps meter", "damage meter forever", "how to see dps", "damage meter", "turn on damage meter", "dps meter", "where is damage meter", "enable damage meter", "how do i turn on the built in damage meter", "is there a dps meter in forever" }, a = "Enable it under Options > Advanced Options > Damage Meter. It appears at the top-left; click its corner icon to pick a view: Damage Done, DPS, Damage Taken, Avoidable Damage Taken, Healing Done, HPS, Interrupts, Dispels or Deaths. Use the gear icon > Reset Data to clear it.", topic = "systems" }
add{ q = { "cooldown manager forever", "how to track cooldowns", "weakauras replacement", "track procs forever", "cooldown manager", "track cooldowns", "track procs", "cooldown tracker", "how to track buffs", "built in cooldown tracker", "how do i track my cooldowns without weakauras", "what replaced weakauras in forever" }, a = "The built-in Cooldown Manager (Options > Advanced Options) shows your cooldowns, buffs and procs; tracking addons can only display what it exposes. Hotfixes since launch added Redoubt and Maelstrom Weapon and fixed Seals, Lacerate and crowd-control durations.", topic = "systems" }
add{ q = { "forever ui options", "edit mode forever", "mouseover casting forever", "swing timer built in", "ping system", "ui options", "edit mode", "mouseover casting", "swing timer", "forever ui", "modern ui forever", "what ui features does forever have", "does forever have edit mode and mouseover casting" }, a = "Forever ships modern UI: Edit Mode, Cooldown Manager, Damage Meter, Ping system, built-in Swing Timer, Equipment Manager, new nameplate options, and mouseover/self-cast keybinds in the Combat tab. Gamepad is supported. A Standard preset and toggles can give a more old-school look, and there's an SD/HD model toggle.", topic = "systems" }
add{ q = { "forever keybinds", "what key opens legacy", "professions window key", "legacy y key", "keybinds forever", "legacy key", "professions key", "y key", "k key", "hotkey for professions", "what key opens the legacy window", "what button opens professions in forever" }, a = "New default keys: Y opens Legacy talents, K opens Professions/Tradeskills (profession icons for bars live there now). Others are standard: C character, B bags, P spellbook, L quest log, M map, N talents, U reputation, Shift+P collections.", topic = "systems" }
add{ q = { "bags not equipping", "new bag didnt equip", "reagent bag slot", "bag wont equip", "reagent bag", "how do i equip a bag", "bags dont auto equip", "my new bag wont equip", "how do i equip a bag in forever" }, a = "Bags must be equipped manually since the Nov 2 notes. There's also a separate retail-style reagent bag slot by the micro menu (e.g. Linen 6, Runecloth 14, Mooncloth 18, Bottomless 20 slots), leaving four normal bag slots.", topic = "systems" }
add{ q = { "is there a dungeon finder", "lfg tool forever", "rdf in forever", "how do i find a group", "dungeon finder", "lfg tool", "rdf", "random dungeon finder", "find a group", "is there lfd in forever", "queue for dungeon", "is there a dungeon finder in forever", "how do i find a group for a dungeon" }, a = "No automatic dungeon finder. Forever has the Classic-style Looking For Group list: it lets you post or browse groups but doesn't match or teleport you. You must pick a playstyle first (Learning, Relaxed, Competitive or Carry Offered).", topic = "systems" }
add{ q = { "summoning stones forever", "meeting stone summon", "how to get summoned to dungeon", "summoning stone", "meeting stone", "summon to dungeon", "how to summon", "meeting stones work", "can i get summoned", "summon stones forever", "do meeting stones summon in forever", "how do i get summoned to the dungeon" }, a = "Meeting stones don't summon in Forever. The only summon is a Warlock's Ritual of Summoning, which needs two other party members present. Everyone else has to travel to the entrance.", topic = "systems" }
add{ q = { "transmog forever", "where is transmogrifier", "how to transmog", "transmog npc stormwind orgrimmar", "transmog", "transmogrifier", "transmog npc", "where is transmog", "transmog stormwind", "transmog orgrimmar", "where is the transmog npc in stormwind", "how do i transmog in forever" }, a = "Transmog is in. Alliance: Fyrenz Vishonar, Mage District, Stormwind (48,84), or Spellweaver Thaldris in Dalaran (18,61). Horde: Mon'ye, Cleft of Shadows, Orgrimmar (46,54). Transmog applies per slot, so it stays when you swap gear. Open Collections with Shift+P.", topic = "systems" }
add{ q = { "how to unlock appearances", "transmog collect boe", "appearance from roll", "account wide transmog", "unlock appearances", "transmog collection", "how to collect transmog", "boe appearance", "how do appearances unlock", "transmog unlock rules", "how do i unlock transmog appearances", "are transmog appearances account wide" }, a = "Appearances are account-wide. Quest gear unlocks every reward choice on completion. BoP, gray and white items collect automatically; BoE items need to be soulbound or vendored. Being in the group when dungeon gear is rolled unlocks it even if you lose; raid epics only unlock for whoever binds them. Mog is same armor type only, with restrictions lifted at 60.", topic = "systems" }
add{ q = { "disable transmog", "turn off transmog see real gear", "hide transmog", "turn off transmog", "see real gear", "transmog off", "show actual gear", "can i turn off other peoples transmog", "how do i turn off transmog so i see real gear", "can i disable transmog in forever" }, a = "Any faction Transmogrifier has a free dialogue option to disable transmog, so you see everyone's actual gear like Classic Era. Toggle back anytime.", topic = "systems" }
add{ q = { "transmog outfits", "outfit slots", "conditional outfits", "outfits", "how many outfits", "buy more outfits", "outfit swap", "how many transmog outfits can i have", "how do i get more outfit slots" }, a = "You get 2 free outfits and can buy more slots at the Transmogrifier. Outfits swap free out of combat and can auto-switch by situation: location, movement, spec, weather or time of day.", topic = "systems" }
add{ q = { "guard sends me to wrong transmog npc", "fyrenz stagazer", "where is fyrenz", "transmog npc name wrong", "fyrenz", "guard transmog wrong", "transmog npc wrong", "fyrenz stargazer", "fyrenz vishonar", "guard sends me wrong place", "stormwind guard sent me to the wrong transmog npc", "where is fyrenz the transmog guy" }, a = "Known issue: Stormwind guards point to 'Fyrenz Stagazer', but the actual transmog NPC is Fyrenz Vishonar in the Mage District (48,84).", topic = "systems" }
add{ q = { "what is legacy system", "legacy points", "how to earn legacy", "legacy talents", "legacy", "what is legacy", "legacy system forever", "how do i get legacy points", "what is the legacy system in forever", "how do i earn legacy points" }, a = "Legacy is an account-wide progression. You earn points from challenges (each class reaching 25/45/60, crafting professions at 150/225/300, PvP ranks, dungeon 'Spelunker' clears, raid clears, Explore Azeroth) and spend them per character in three trees: Professions, Adventure and Resourcefulness. 65 challenges exist, but only 16 points can be spent at launch. Open it with Y.", topic = "systems" }
add{ q = { "best legacy talents", "what to put legacy points in", "legacy build leveling", "legacy build", "what legacy talents", "legacy for leveling", "where to put legacy points", "legacy talent guide", "best legacy picks", "what are the best legacy talents for leveling", "where should i put my legacy points" }, a = "For leveling, Adventure has the big ones: Well Rested (+4% rested gain and cap per rank), Talented (earlier talent points), Thrill of Adventure (heal/mana on kills) and Frequent Flier (half-price, faster flights). Resourcefulness has Reagent Economy (no vendor reagents) and The Quick and the Dead (faster corpse runs). Respec Legacy at your class trainer.", topic = "systems" }
add{ q = { "legacy icon glowing", "clear legacy notification", "legacy button keeps glowing", "legacy point notification wont go away", "legacy glowing", "legacy notification", "legacy button glow", "how to clear legacy glow", "legacy icon stuck", "legacy blue glow", "my legacy icon keeps glowing how do i fix it", "how do i clear the legacy notification" }, a = "The Legacy icon glows blue when you earn a point; spending points won't clear it. Open the Legacy Challenges tab and click the challenge that awarded the point.", topic = "systems" }
add{ q = { "how does camping work", "campfire forever", "camp buffs", "how to make a camp", "camping", "campfire", "how to camp", "make a camp", "camp benefits", "how does camping work in forever", "how do i build a campfire" }, a = "Build a Basic Campfire (Cooking 1, Flint and Tinder + Simple Wood). It burns about 10 minutes (5-min cooldown) and grants rested status. Each player can add one profession object (1-hour cooldown) for a buff: e.g. Mining Lodestone (AP), Blacksmithing Sharpening Wheel (Str), Herbalism Incense Candle (Int), Skinning Camp Chair (crit), Leatherworking Camp Tent (rested XP). /sit at the camp for a minute to get buffs.", topic = "systems" }
add{ q = { "how many professions forever", "profession changes forever", "profession trainers starting zone", "professions forever", "profession changes", "how many professions", "new recipes", "profession trainers", "new professions", "did professions change in forever", "how many professions can i have in forever" }, a = "Same as Classic: two primary professions plus Cooking, First Aid and Fishing. Over 600 new recipes; first new items unlock at skill 20, and advanced recipes come from blueprints, some dropped by dungeon bosses. Profession trainers and nodes now exist in starting zones.", topic = "systems" }
add{ q = { "new reputation factions", "azeroth commerce authority", "durotar supply and logistics", "waylaid crates turn in", "new reputations", "durotar supply", "waylaid crates", "crafting rep", "crafting factions", "aca rep", "what are the new crafting rep factions", "where do i turn in waylaid crates" }, a = "Two mirrored crafting factions: Azeroth Commerce Authority (Alliance, Three Corners, Redridge, 10,73) and Durotar Supply and Logistics (Horde, west of the Crossroads, Barrens, 42,34). Turn in loot crates for rep and Merchant's Favor; they sell mid-level recipes. Waylaid Crates and Craftsman's Writs can drop in dungeons since Nov 9.", topic = "systems" }
add{ q = { "level 60 weekly", "undermine satchel", "pix xizzix weekly", "tarnished undermine reals", "60 weekly", "weekly quest", "pix xizzix", "weekly at 60", "booty bay weekly", "whats the weekly quest at 60", "where do i get the undermine satchel" }, a = "At 60, Pix Xizzix in Booty Bay gives a weekly dungeon quest for an Undermine Satchel (sellable items worth 10-100g plus high-end reagents). Level 55+ dungeon bosses drop Tarnished Undermine Reals, traded to Pix Xizzix in Stranglethorn (28.4, 75.8) for armor, reagents and recipes. Weekly quests clear on reset.", topic = "systems" }
add{ q = { "auction house deposit", "ah changes forever", "black market vendor", "ah deposit", "ah changes", "auction house changes", "black market", "ah deposit 1 copper", "auction house forever", "how much is the ah deposit in forever", "is there a black market vendor in forever" }, a = "The Auction House uses the modern retail interface; minimum deposit dropped to 1 copper on Nov 10. Black Market NPCs sell some materials at fixed prices. Several BoP crafted armor vendor prices were cut to stop vendor-flipping.", topic = "systems" }
add{ q = { "library books forever", "where to turn in library books", "library book rewards", "library books", "library book turn in", "library rewards", "where to turn in books", "book rewards", "where do i turn in library books", "what do library books give in forever" }, a = "All classes can collect library books (a Season of Discovery carryover). Turn-in milestones at 10, 20, 25 and 30 books unlock quests rewarding items like Scholarly Pendant and Philanthropist's Ring. Turn-in librarians in Undercity and Stormwind (Owen Thadd, Garion Wendell) were fixed on Nov 13.", topic = "systems" }
add{ q = { "boats not coming", "zeppelin broken forever", "lost in the maelstrom", "boat portal", "zeppelin broken", "boat broken", "zeppelin never comes", "boat bug", "the boat never showed up whats going on", "zeppelin isnt coming is it bugged" }, a = "At launch, boats and zeppelins often got 'lost in the maelstrom' and never arrived. Blizzard placed temporary portals near most docks and inside zeppelin towers. If a dock has no portal, that route is running normally, so wait for it.", topic = "systems" }
add{ q = { "new boat routes forever", "stormwind to darkshore boat", "how to get to riverglades", "skyboat zephras", "new boat routes", "riverglades", "skyboat", "new boats", "new travel routes", "is there a boat from stormwind to darkshore", "what new boat routes are in forever" }, a = "New routes: Stormwind Harbor to Auberdine; a Menethil-Southshore-Auberdine loop; Steamwheedle Port (Tanaris) to Powderfuse Port (Riverglades); skyboats from Valanaar (Zephras Isle) to Dalaran and to Skywatcher Plateau in Mulgore, every ~5 min, usable by both factions. No zeppelin to Thunder Bluff.", topic = "systems" }
add{ q = { "mage portals forever", "dalaran teleport", "mage teleport levels", "mage portals", "when do mages get portals", "mage teleport", "portal levels", "teleport dalaran", "when do mages get portals in forever", "what level do mages learn the dalaran teleport" }, a = "Mages learn city teleports at 20 (two capitals) and 30 (the third), group portals at 40 and 50, and a Dalaran teleport at 50.", class = "MAGE", topic = "systems" }
add{ q = { "can i mount in stratholme", "mount inside dungeon", "why cant i mount in strat", "mount in stratholme", "mount in dungeon", "strat mount", "mounting in dungeons", "can i mount in strat", "can i mount up inside stratholme" }, a = "No. Mounting inside Stratholme was a launch bug and was disabled on Nov 9.", topic = "systems" }
add{ q = { "known bugs forever", "forever known issues", "pvp vendor missing", "vorsha the lasher bugged", "known bugs", "known issues", "vorsha bugged", "forever bugs", "launch bugs", "bug list forever", "what are the known bugs in forever", "pvp vendor missing in stormwind" }, a = "Launch known issues: PvP vendors in Orgrimmar, Stormwind and Dalaran were unavailable; Vorsha the Lasher (Ashenvale) was disabled for a crash bug, later fixed; bank tabs render outside the frame; a cauldron near Roogug in Razorfen Kraul can trap you; gamepad can't bulk-delete rare/epic items.", topic = "systems" }
add{ q = { "stuck in cauldron rfk", "razorfen kraul stuck", "roogug cauldron bug", "rfk cauldron", "stuck in cauldron", "rfk stuck", "razorfen kraul bug", "roogug cauldron", "rfk bug", "fell into the cauldron in rfk and im stuck" }, a = "Known issue at launch: a cauldron near Roogug in Razorfen Kraul can trap players who fall in. Steer clear of it during that pull.", topic = "systems" }
add{ q = { "action bars resetting", "action bars reset on logout dual spec", "my bars reset every login", "keybinds lost after relog", "bars reset", "action bars reset logout", "keybinds reset", "bars reset dual spec", "action bar bug", "my action bars keep resetting every time i log in", "why do my bars reset after logout" }, a = "A bug reset action bar settings every logout for players with a second talent spec. Blizzard fixed it in the Nov 13 hotfixes; if it happens again, report it.", topic = "systems" }
add{ q = { "item restoration disabled", "cant restore item", "item restore forever", "item restoration", "item restore", "restore item", "cant restore deleted item", "item restoration down", "can i get my deleted item restored", "is item restoration still disabled" }, a = "Customer Support's Item Restoration service was disabled on Nov 11 while Blizzard investigated a critical bug.", topic = "systems" }
add{ q = { "release spirit bug bfd", "cant release in blackfathom", "bfd cant release spirit", "bfd release bug", "cant release spirit bfd", "blackfathom bug", "bfd bug", "stuck dead in bfd", "release spirit bug", "i cant release spirit in bfd what do i do" }, a = "A bug in Blackfathom Deeps that stopped you releasing spirit after death was fixed on Nov 9.", topic = "systems" }
add{ q = { "drowned city too hard", "drowned city damage bug", "deathless marrow nerf", "drowned city", "drowned city hard", "drowned city bug", "deathless marrow", "drowned city damage", "drowned city nerf", "why is drowned city so hard", "did they fix the drowned city damage bug" }, a = "The Drowned City had a bug making mobs deal about 30% extra damage, fixed Nov 9. Deathless Marrow also got 25% less creature health, weaker Fireball and Charge, and fewer Shield Slams. Since Nov 13, its trash respawns after 2 hours instead of 1.", topic = "systems" }
add{ q = { "mail takes an hour", "why is mail slow forever", "auction house mail sender", "mail slow", "mail delay", "why is mail slow", "ah mail", "mail 60 minutes", "mail taking long", "why does mail take an hour in forever", "my mail used to be fast now it takes 60 minutes" }, a = "Mail to other players takes the intended 60 minutes. Some mail was arriving in about 2 minutes due to a bug, fixed Nov 10, along with mail wrongly showing 'Stormwind Auction House' as the sender.", topic = "systems" }
add{ q = { "spawn rates forever", "mobs respawn fast starting zone", "not enough mobs quest", "spawn rates", "respawn rate", "mobs respawn fast", "not enough mobs", "respawn speed", "mob respawn starting zone", "mobs are respawning really fast in my starting zone", "not enough mobs for my quest" }, a = "Before launch Blizzard sped up respawns in many zones, most of all in starting zones, and said it may slow them again after the launch rush. Some starting areas (e.g. Mulgore quillboar and Venture Co.) were already dialed back on Nov 13.", topic = "systems" }
add{ q = { "mob health increased", "mobs harder forever", "nov 2 class buffs mob hp", "mob health", "mobs harder", "mobs have more hp", "class buffs", "nov 2 patch", "mob hp buff", "why are mobs tanky", "why do higher level mobs have more health now", "did mobs get buffed in forever" }, a = "The Nov 2 pre-launch notes buffed damage for many classes and raised health on higher-level creatures to match. Blizzard said no big tuning before raids open except bugs and outliers.", topic = "systems" }
add{ q = { "quitter debuff", "deserter battleground forever", "bg deserter how long", "marks of honor stack", "deserter", "bg deserter", "deserter debuff", "deserter time", "marks of honor", "deserter length", "how long is the bg deserter debuff", "do marks of honor stack in forever" }, a = "The battleground quitter debuff was shortened to 40 seconds in the Nov 2 pre-launch notes. Marks of Honor now stack to 30.", topic = "systems" }
add{ q = { "new battleground", "darkspear islands battleground", "forever pvp battlegrounds", "darkspear islands", "new bg", "battlegrounds forever", "pvp battlegrounds", "darkspear bg", "list of battlegrounds", "what battlegrounds are in forever", "is there a new bg in forever" }, a = "All original Vanilla battlegrounds return plus a new one, Darkspear Islands. The PvP ruleset uses Season of Discovery-style faction balance tools. Legacy points come from PvP ranks 3, 7, 10, 13 and 14.", topic = "systems" }
add{ q = { "shatterspear trolls no xp", "shatterspear xp farm", "why no xp from shatterspear", "darkshore trolls no xp", "shatterspear", "shatterspear trolls", "shatterspear xp", "no xp shatterspear", "darkshore trolls", "shatterspear farm", "why dont shatterspear trolls give xp anymore", "can i still farm xp on shatterspear trolls" }, a = "Since Nov 10, Shatterspear Trolls give no XP when killed, closing off an XP farm.", topic = "systems" }
add{ q = { "collections account wide", "are mounts account wide forever", "pets toys account wide", "account wide collections", "account wide mounts", "account wide pets", "toys account wide", "collections forever", "are pets account wide", "are mounts and pets account wide in forever", "do collections carry over between rulesets" }, a = "Yes. Collections (mounts, pets, toys, transmog appearances) are account-wide across Forever's rulesets. Hardcore is the exception: things earned there carry out, but nothing comes in.", topic = "systems" }
add{ q = { "pouch of violet dust", "extra camp benefits hour", "violet dust camp", "violet dust", "camp benefits", "extra camp hour", "violet dust bug", "what does pouch of violet dust do", "violet dust not working for camp" }, a = "Pouch of Violet Dust grants an extra hour of Camp Benefits. It didn't work at launch; fixed Nov 9.", topic = "systems" }
add{ q = { "voidwalker too weak", "warlock pet health buff forever", "warlock pets dying", "imp buff forever", "voidwalker weak", "warlock pets", "warlock pet buff", "imp buff", "warlock pet dying", "void too weak", "lock pet buff", "my voidwalker keeps dying is it too weak", "did warlock pets get buffed" }, a = "Warlock pets have been buffed: Voidwalker base health rose about 40 (Nov 6), then Imp, Voidwalker, Incubus and Succubus got about 15% more base health and stronger Imp Firebolt (Nov 10). Pet health now also scales with your Stamina.", class = "WARLOCK", topic = "systems" }
add{ q = { "tailoring bag recipe changed", "mageweave bag slots forever", "silk bag slots", "tailoring bags", "bag recipe changes", "mageweave bag", "silk bag", "tailoring bag slots", "bag slot changes", "red mageweave bag", "how many slots is a mageweave bag now", "did tailoring bag recipes change" }, a = "Nov 11: several Tailoring bags got more slots and cost one more bolt: Red Mageweave Bag 14 slots (5 bolts), Green and Black Silk Pack 12 slots, Green and Red Woolen Bag 10 slots.", topic = "systems" }
add{ q = { "does forever have wow token", "can i buy gold forever", "character boost forever", "wow token", "token forever", "buy gold", "character boost", "level boost", "is there a boost", "can i buy a token", "is there a wow token in forever", "can i buy a character boost in forever" }, a = "Blizzard said it had no plans for WoW Tokens in Forever, and there was no paid level boost at launch. The only head start sold in the packs is the Skyborne race with its Zephras Isle start.", topic = "systems" }
